/* ---------- רשת ביטחון גלובלית לשגיאות בלתי צפויות ----------
   בלי זה: אם שגיאה כלשהי (לא רק תקלת רשת שכבר מטופלת ב-initSupabase) קורית בעליית
   האפליקציה — למשל render() שנכשל על נתונים ישנים/פגומים ספציפיים למשתמש מסוים — המשתמש
   נשאר תקוע על מסך ישן/חלקי (כמו מסך "בודק הרשאת גישה...") בלי שום פידבק ובלי שום דרך
   להבין מה קרה, גם אם ה-timeout ברשת עצמה כבר תוקן. שים לב: #app כבר מכיל תוכן במצב הזה
   (מסך הבדיקה עצמו!), כך שבדיקת "app ריק" לא הייתה מזהה את התרחיש בכלל — במקום, בודקים
   ישירות את cloudAuthCheckComplete, שהוא הדגל האמיתי שאמור להפוך ל-true תוך ~12 שניות. */
(function(){
  let appErrorShown = false;
  function stillStuckOnAuthCheck(){
    // typeof === 'undefined' מכסה תרחיש קיצון: הסקריפט קרס עוד לפני שהגיע בכלל להצהרה על
    // המשתנה — זה סימן תקיעות מוקדם עוד יותר, לא רק "עדיין false".
    return typeof cloudAuthCheckComplete === 'undefined' || cloudAuthCheckComplete === false;
  }
  function showFatalStartupError(message){
    if(appErrorShown) return;
    appErrorShown = true;
    const reloadUrl = window.location.pathname + '?_r=' + Date.now();
    const el = document.createElement('div');
    el.style.cssText = 'position:fixed; inset:0; z-index:99999; background:#12151a; color:#e8eaed; display:flex; align-items:center; justify-content:center; padding:20px; font-family:system-ui,sans-serif; direction:rtl; text-align:center;';
    // <a> עם href פונקציונלי אמיתי, לא <button> — כפתור תלוי לגמרי בהצלחת JS listener, בעוד
    // שהמסך הזה מוצג בדיוק כשיש חשד שה-JS לא מתפקד כשורה. הקישור חייב לעבוד גם בלי שום JS.
    el.innerHTML = `
      <div style="max-width:420px; background:#1b1f26; border:1px solid #3a3f47; border-radius:12px; padding:28px 22px;">
        <div style="font-size:32px; margin-bottom:12px;">⚠️</div>
        <p style="font-weight:700; margin:0 0 8px;">האפליקציה נתקלה בשגיאה בעת הטעינה</p>
        <p style="font-size:12px; color:#9aa1ab; margin:0 0 18px; word-break:break-word;">${message ? String(message).slice(0,300) : ''}</p>
        <a href="${reloadUrl.replace(/"/g,'&quot;')}" id="fatalErrorReloadBtn" style="display:inline-block; background:#f0b429; color:#1a1200; text-decoration:none; border-radius:8px; padding:10px 18px; font-size:14px; font-weight:700; cursor:pointer;">רענן את הדף</a>
      </div>`;
    document.body.appendChild(el);
  }
  window.addEventListener('error', (e)=>{
    // לא כל שגיאה קטנה מצדיקה מסך חסימה מלא — רק אם נראה שהעלייה הקריטית של האפליקציה עדיין
    // לא הסתיימה (cloudAuthCheckComplete עדיין false), כלומר יש חשד סביר שהשגיאה הזו היא זו
    // שמנעה מהאפליקציה להתקדם, לא שגיאה שולית שקורית אחרי שהיא כבר עובדת ומוצגת תקין.
    setTimeout(()=>{ if(stillStuckOnAuthCheck()) showFatalStartupError(e.message); }, 1500);
  });
  setTimeout(()=>{
    if(stillStuckOnAuthCheck()) showFatalStartupError('הטעינה נמשכת זמן רב מהרגיל.');
  }, 14000);
})();

/* ---------- Storage abstraction ----------
   Inside Claude.ai this uses the built-in artifact storage (window.storage),
   which follows your Claude account — not tied to one device or browser.
   If this file is opened standalone (downloaded, outside Claude.ai), window.storage
   doesn't exist, so we fall back to the browser's own localStorage instead, so the
   app still works and remembers data on that specific device/browser. */
const storageAPI = (typeof window.storage !== 'undefined') ? window.storage : {
  async get(key, shared){
    const k = (shared?'shared:':'personal:') + key;
    const raw = localStorage.getItem('app-storage:' + k);
    if(raw === null) return null;
    return { key, value: raw, shared: !!shared };
  },
  async set(key, value, shared){
    const k = (shared?'shared:':'personal:') + key;
    localStorage.setItem('app-storage:' + k, value);
    return { key, value, shared: !!shared };
  },
  async delete(key, shared){
    const k = (shared?'shared:':'personal:') + key;
    localStorage.removeItem('app-storage:' + k);
    return { key, deleted: true, shared: !!shared };
  },
  async list(prefix, shared){
    const scope = (shared?'shared:':'personal:');
    const keys = [];
    for(let i=0;i<localStorage.length;i++){
      const full = localStorage.key(i);
      if(full && full.startsWith('app-storage:'+scope)){
        const k = full.slice(('app-storage:'+scope).length);
        if(!prefix || k.startsWith(prefix)) keys.push(k);
      }
    }
    return { keys, prefix, shared: !!shared };
  }
};

/* ---------- Supabase cloud integration ----------
   Loaded via CDN in <head>. All calls are gated on supabaseClient existing
   and actually checking the real response — never fabricating success.
   Only the public anon key is ever used here; service_role stays server-side. */

function isSupabaseConfigured(){
  return !!(state.settings.supabaseUrl && state.settings.supabaseAnonKey);
}

// עוטף כל promise בהגבלת זמן — אם הרשת תקועה/איטית מדי, נכשל עם שגיאה ברורה במקום להישאר
// תלוי לצמיתות. זו הייתה סיבת השורש לדיווח על מסך "בודק הרשאת גישה..." שנתקע: getSession()
// (ופונקציות רשת נוספות בהמשך initSupabase) לא היו מוגנות בשום timeout, כך שרשת איטית/תקועה
// (למשל רשת ארגונית חוסמת, DNS תקוע) הייתה משאירה את cloudAuthCheckComplete=false לצמיתות,
// בלי שום מסך שגיאה/כפתור ניסיון חוזר — נעילה מוחלטת של האפליקציה כולה, גם לתוכן מקומי.
function withTimeout(promise, ms, timeoutMessage){
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(()=>reject(new Error(timeoutMessage || 'תם הזמן הקצוב')), ms))
  ]);
}

async function initSupabase(){
  cloudInitError = '';
  if(typeof window.supabase === 'undefined'){
    cloudInitError = 'ספריית Supabase לא נטענה (אין חיבור לאינטרנט, או ה-CDN חסום ברשת הזו).';
    supabaseClient = null;
    return false;
  }
  if(!isSupabaseConfigured()){
    cloudInitError = 'לא הוגדרו כתובת Supabase Project ומפתח anon בהגדרות הענן.';
    supabaseClient = null;
    return false;
  }
  try{
    // תיקון דחוף (v2.195): ה-fetch המותאם אישית שנוסף ב-v2.194 הוסר. בעקבות דיווח קריטי על
    // אי-יכולת להתחבר בכלל, בשני מכשירים, מיד אחרי אותו עדכון — זה היה השינוי הכי חדש והכי
    // פולשני (עוקף את מנגנון ה-fetch המשמש את כל לקוח ה-Supabase כולו), ולכן הגורם הסביר
    // ביותר, גם בלי אישור סופי מהסביבה האמיתית. חוזרים למנגנון הפשוט שכבר הוכח בטוח ועובד:
    // רק getSession() עצמה עטופה ב-timeout (למטה), לא כל קריאת רשת באפליקציה. אם התיקון הזה
    // אכן פתר את הבעיה, ניתן בעתיד לשקול פתרון ל-timeout כללי יותר בזהירות רבה יותר ומול
    // סביבת בדיקה אמיתית, לא רק מוקים.
    supabaseClient = window.supabase.createClient(state.settings.supabaseUrl, state.settings.supabaseAnonKey);
    // מאזין לאירוע PASSWORD_RECOVERY — קורה כשהמשתמש לוחץ על קישור איפוס הסיסמה מהמייל וחוזר
    // לאפליקציה. authListenerAttached מונע הצמדה כפולה אם initSupabase() רץ יותר מפעם אחת
    // (למשל דרך testSupabaseConnection או syncPendingReports).
    if(!authListenerAttached && typeof supabaseClient.auth.onAuthStateChange === 'function'){
      authListenerAttached = true;
      supabaseClient.auth.onAuthStateChange((event, session)=>{
        if(event === 'PASSWORD_RECOVERY'){
          passwordRecoveryMode = true;
          render();
        }
      });
    }
    // Verify the client actually works by requesting the current session — this is a real
    // network call, so a bad URL/key will genuinely fail here rather than silently "succeeding".
    // עטוף ב-timeout: בלי זה, רשת תקועה/איטית משאירה את המשתמש נעול על מסך "בודק הרשאת
    // גישה..." לצמיתות, בלי שום הודעת שגיאה או אפשרות ניסיון חוזר.
    const { data, error } = await withTimeout(
      supabaseClient.auth.getSession(),
      12000,
      'תם הזמן הקצוב בבדיקת החיבור לשרת — בדוק את חיבור הרשת ונסה שוב.'
    );
    if(error) throw error;
    if(data && data.session && data.session.user){
      await withTimeout(
        refreshCloudUserFromSession(data.session),
        12000,
        'תם הזמן הקצוב בטעינת פרטי המשתמש — בדוק את חיבור הרשת ונסה שוב.'
      );
    }
    return true;
  }catch(err){
    cloudInitError = 'שגיאה בהתחברות ל-Supabase: ' + (err && err.message ? err.message : String(err));
    supabaseClient = null;
    return false;
  }
}

/* ---------- גיבוי אוטומטי לגוגל דרייב ----------
   לפי בקשה מפורשת: כל דוח שנשמר/מיוצא עולה אוטומטית לדרייב, תחת תיקייה קבועה בשם
   "גיבוי דוחות בדיקה ממערכת דוחות שקד הנדסת חשמל", עם תת-תיקייה לפי לקוח ובתוכה לפי תאריך.
   כל בודק מתחבר לדרייב האישי שלו בנפרד (לא דרייב משותף אחד) — לכן ה-access token נשמר רק
   בזיכרון (googleDriveAccessToken, לא ב-storage) ומתחדש כל session; googleDriveClientId
   (מוגדר פעם אחת ב-Google Cloud Console) ו-googleDriveEnabled/RootFolderId כן נשמרים
   ב-settings, כי אלה לא סודיים ולא פגי-תוקף. scope=drive.file בכוונה (לא drive מלא) — נותן
   לאפליקציה גישה רק לקבצים שהיא עצמה יצרה, לא לכל הדרייב של המשתמש.
   */
const GOOGLE_DRIVE_BACKUP_ROOT_FOLDER_NAME = "גיבוי דוחות בדיקה ממערכת דוחות שקד הנדסת חשמל";
let googleDriveAccessToken = null;   // בזיכרון בלבד, לעולם לא נשמר ב-storage
let googleDriveTokenClient = null;   // אובייקט ה-token client של Google Identity Services
let googleDriveConnecting = false;

function isGoogleDriveConfigured(){
  return !!(state.settings.googleDriveClientId && typeof google !== 'undefined' && google.accounts && google.accounts.oauth2);
}

// מאתחל את ה-token client פעם אחת (עצל — רק כשצריך, כי הספרייה עצמה נטענת אסינכרונית ב-index.html)
function ensureGoogleDriveTokenClient(){
  if(googleDriveTokenClient || !isGoogleDriveConfigured()) return googleDriveTokenClient;
  googleDriveTokenClient = google.accounts.oauth2.initTokenClient({
    client_id: state.settings.googleDriveClientId,
    scope: 'https://www.googleapis.com/auth/drive.file',
    callback: (resp)=>{
      if(resp && resp.access_token){
        googleDriveAccessToken = resp.access_token;
        state.settings.googleDriveEnabled = true;
        scheduleSave();
        showToast('התחברות לגוגל דרייב הצליחה');
      } else {
        showToast('התחברות לגוגל דרייב נכשלה — נסה שוב');
      }
      googleDriveConnecting = false;
      render();
    }
  });
  return googleDriveTokenClient;
}

// מפעיל את חלון האישור של גוגל (popup) — קריאה זו חייבת לקרות ישירות מתוך אירוע click של
// המשתמש (לא מתוך await מאוחר יותר), אחרת הדפדפן חוסם את ה-popup כ"נפתח לבד".
function connectGoogleDrive(){
  if(!isGoogleDriveConfigured()){
    showToast('לא הוגדר Client ID לגוגל דרייב בהגדרות חברה');
    return;
  }
  const client = ensureGoogleDriveTokenClient();
  if(!client) return;
  googleDriveConnecting = true;
  render();
  client.requestAccessToken({ prompt: googleDriveAccessToken ? '' : 'consent' });
}

function disconnectGoogleDrive(){
  if(googleDriveAccessToken && typeof google !== 'undefined' && google.accounts && google.accounts.oauth2){
    google.accounts.oauth2.revoke(googleDriveAccessToken, ()=>{});
  }
  googleDriveAccessToken = null;
  state.settings.googleDriveEnabled = false;
  state.settings.googleDriveRootFolderId = '';
  scheduleSave();
  render();
  showToast('החיבור לגוגל דרייב נותק');
}

// עוטף כל קריאת Drive API בהגבלת זמן (20 שניות) — מונע תקיעה שקטה של גיבוי ברקע אם הרשת
// בעייתית, באותה רוח בדיוק כמו ההגנות שכבר נוספו לקריאות Supabase.
function driveApiFetch(url, options){
  return withTimeout(
    fetch(url, { ...options, headers: { ...(options&&options.headers), 'Authorization': 'Bearer ' + googleDriveAccessToken } }),
    20000,
    'תם הזמן הקצוב בחיבור לגוגל דרייב'
  );
}

// מחפש תיקייה בשם נתון מתחת ל-parentId; יוצר אותה אם לא נמצאה. מחזיר את מזהה התיקייה.
async function findOrCreateDriveFolder(name, parentId){
  const safeName = name.replace(/'/g, "\\'");
  const parentClause = parentId ? ` and '${parentId}' in parents` : " and 'root' in parents";
  const q = encodeURIComponent(`name = '${safeName}' and mimeType = 'application/vnd.google-apps.folder' and trashed = false${parentClause}`);
  const searchRes = await driveApiFetch(`https://www.googleapis.com/drive/v3/files?q=${q}&fields=files(id,name)`);
  if(!searchRes.ok) throw new Error('חיפוש תיקייה בדרייב נכשל: ' + searchRes.status);
  const searchData = await searchRes.json();
  if(searchData.files && searchData.files.length) return searchData.files[0].id;

  const createRes = await driveApiFetch('https://www.googleapis.com/drive/v3/files?fields=id', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name, mimeType: 'application/vnd.google-apps.folder',
      parents: parentId ? [parentId] : undefined
    })
  });
  if(!createRes.ok) throw new Error('יצירת תיקייה בדרייב נכשלה: ' + createRes.status);
  const createData = await createRes.json();
  return createData.id;
}

// מעלה קובץ בודד לתוך תיקייה נתונה (multipart upload — מטא-דאטה + תוכן בבקשה אחת)
async function uploadFileToDriveFolder(filename, content, mimeType, parentId){
  const boundary = 'shaked_backup_boundary_' + Date.now();
  const metadata = { name: filename, parents: [parentId] };
  const bodyParts = [
    `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n`,
    `--${boundary}\r\nContent-Type: ${mimeType}\r\n\r\n`,
  ];
  const encoder = new TextEncoder();
  const head = encoder.encode(bodyParts.join(''));
  const contentBytes = (content instanceof Uint8Array) ? content : encoder.encode(content);
  const tail = encoder.encode(`\r\n--${boundary}--`);
  const fullBody = new Uint8Array(head.length + contentBytes.length + tail.length);
  fullBody.set(head, 0); fullBody.set(contentBytes, head.length); fullBody.set(tail, head.length + contentBytes.length);

  const res = await driveApiFetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id', {
    method: 'POST',
    headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },
    body: fullBody
  });
  if(!res.ok) throw new Error('העלאת קובץ לדרייב נכשלה: ' + res.status);
  return res.json();
}

// אורכיסטרציה מלאה: מבטיח את מבנה התיקיות (ראשית ← לקוח ← תאריך) ומעלה PDF + קובץ גיבוי
// לתוך תיקיית התאריך. נכשל בשקט (רק toast, לא חוסם את השמירה הרגילה) — גיבוי לדרייב הוא
// שכבה נוספת מעל השמירה הקיימת (ענן/מקומי), לא תחליף לה.
async function backupReportToDrive(pdfBlob, pdfFilename, jsonContent, jsonFilename){
  if(!state.settings.googleDriveEnabled || !googleDriveAccessToken) return { skipped: true };
  try{
    let rootId = state.settings.googleDriveRootFolderId;
    if(!rootId){
      rootId = await findOrCreateDriveFolder(GOOGLE_DRIVE_BACKUP_ROOT_FOLDER_NAME, null);
      state.settings.googleDriveRootFolderId = rootId;
      scheduleSave();
    }
    const clientName = (state.meta.client || 'ללא לקוח').trim() || 'ללא לקוח';
    const clientFolderId = await findOrCreateDriveFolder(clientName, rootId);
    const dateFolderName = formatDateIL(state.meta.date) || new Date().toISOString().slice(0,10);
    const dateFolderId = await findOrCreateDriveFolder(dateFolderName, clientFolderId);

    if(pdfBlob) await uploadFileToDriveFolder(pdfFilename, pdfBlob, 'application/pdf', dateFolderId);
    if(jsonContent) await uploadFileToDriveFolder(jsonFilename, jsonContent, 'application/json', dateFolderId);

    return { success: true };
  }catch(e){
    console.warn('גיבוי לגוגל דרייב נכשל:', e);
    showToast('גיבוי לגוגל דרייב נכשל: ' + e.message, 5000);
    return { success: false, error: e.message };
  }
}

async function refreshCloudUserFromSession(session){
  if(!session || !session.user) { cloudCurrentUser = null; return; }
  let profile = null;
  try{
    const { data, error } = await supabaseClient
      .from('user_profiles')
      .select('name, role, is_super_admin, must_change_password')
      .eq('user_id', session.user.id)
      .maybeSingle();
    if(!error && data) profile = data;
  }catch(e){ /* profile lookup failed — user still counts as logged in, just without a name/role yet */ }
  cloudCurrentUser = {
    id: session.user.id,
    email: session.user.email,
    name: (profile && profile.name) || '',
    role: (profile && profile.role) || 'employee',
    isSuperAdmin: !!(profile && profile.is_super_admin),
    mustChangePassword: !!(profile && profile.must_change_password)
  };
  // שומרים מקומית שהתחברנו לפחות פעם אחת במכשיר הזה — כדי שאם בעתיד ניסיון החיבור עצמו
  // ל-Supabase נכשל בגלל חוסר אינטרנט (לא בגלל שהמשתמש לא מורשה), עדיין נדע לתת גישה
  // לאפליקציה במקום לנעול החוצה מישהו שכבר הורשה בעבר.
  try{ await storageAPI.set('has-logged-in-before', 'true', false); }catch(e){ /* לא קריטי */ }

  // טעינה אוטומטית של רשימת הלקוחות ברגע שיש משתמש מחובר — בין אם דרך login פעיל
  // ובין אם דרך שחזור session קיים בטעינת הדף — כדי שהבורר יהיה מוכן מיד, בלי
  // שהמשתמש יצטרך לגרום לרענון נוסף כדי לראות את הרשימה.
  // *** טעינת הגדרות AI מהענן — בדיוק בנקודת הכניסה היחידה שכבר משמשת לכל "טעינה אוטומטית
  // כשיש משתמש מחובר" (login פעיל וגם שחזור session קיים בטעינת הדף), לפי דרישה מפורשת:
  // "לאחר login: loadUserAISettings() צריך להיטען מהענן". זה פותר את בעיית הסנכרון בין
  // מכשירים — כל מכשיר שמתחבר לאותו חשבון מקבל אוטומטית את אותה הגדרה, בלי localStorage.
  cloudDebugLog('טוען הגדרות AI מהענן אוטומטית אחרי חיבור');
  await loadUserAISettings();

  cloudDebugLog('טוען רשימת לקוחות אוטומטית אחרי חיבור');
  cloudClientOptions = await searchCloudClients('');
  if(state.settings.cloudClientId){
    const chosen = cloudClientOptions.find(c=>c.id===state.settings.cloudClientId);
    cloudActiveClientName = chosen ? chosen.name : '';
    cloudProjectOptions = await loadCloudProjectsForClient(state.settings.cloudClientId);
    const chosenProject = cloudProjectOptions.find(p=>p.id===state.settings.cloudProjectId);
    cloudActiveProjectName = chosenProject ? chosenProject.name : '';
  }
}

function getCurrentUser(){
  return cloudCurrentUser;
}

// הרשמה עצמית — נרשם חדש מקבל תמיד role='viewer' (התפקיד המוגבל ביותר, כמעט ללא הרשאות עריכה).
// אדמין הוא היחיד שיכול לשנות תפקיד אחרי מכן, דרך פאנל ניהול המשתמשים. ההגנה על כך אינה רק כאן
// בקוד — גם ב-RLS עצמו (profiles_insert_own מחייבת role='viewer' על הכנסה עצמית, לא ניתן לעקוף
// מהדפדפן גם אם משנים את הבקשה ידנית).
async function signupUser(email, password, name){
  cloudDebugLog('Signup: מתחיל הרשמה', email); // לא רושמים סיסמה בשום מקרה
  if(!supabaseClient){
    signupResult = { type: 'error', message: 'אין חיבור פעיל ל-Supabase — בדוק את הגדרות הענן קודם' };
    return false;
  }
  if(!email || !password){
    signupResult = { type: 'error', message: 'יש להזין אימייל וסיסמה' };
    return false;
  }
  if(password.length < 6){
    signupResult = { type: 'error', message: 'הסיסמה חייבת להכיל לפחות 6 תווים' };
    return false;
  }
  try{
    const { data, error } = await supabaseClient.auth.signUp({
      email, password,
      options: { data: { full_name: name || '' } } // item 1 — full_name ב-metadata
    });
    if(error){
      cloudDebugLog('Signup: נכשל', error.message);
      // item 6 — "משתמש כבר קיים" מזוהה במפורש מנוסח השגיאה של Supabase, לא רק מוצג כשגיאה גנרית
      if(/already registered|already exists/i.test(error.message)){
        signupResult = { type: 'already-exists', email, message: error.message };
      } else {
        signupResult = { type: 'error', message: error.message }; // item 5 — לעולם לא מוסתר
      }
      return false;
    }
    // דפוס "הצלחה מדומה" של Supabase: כשConfirm Email מופעל, הרשמה עם אימייל שכבר קיים
    // (ולא אושר) לא מחזירה שגיאה כלל — מחזירה data.user עם identities ריק, מטעמי פרטיות
    // (כדי לא לחשוף אילו אימיילים רשומים). זו עדיין "משתמש קיים" בפועל.
    const looksLikeExistingUser = data.user && Array.isArray(data.user.identities) && data.user.identities.length === 0;
    if(looksLikeExistingUser){
      signupResult = { type: 'already-exists', email, message: 'האימייל הזה כבר רשום במערכת.' };
      return false;
    }
    if(data.user){
      try{
        // upsert לפי user_id — לא יוצר פרופיל כפול אם כבר קיים (item 7 במפרט)
        await supabaseClient.from('user_profiles').upsert({ user_id: data.user.id, name: name || '', role: 'viewer' }, { onConflict: 'user_id' });
      }catch(e){ cloudDebugLog('Signup: יצירת פרופיל נכשלה (לא חוסם)', e.message); }
    }
    if(data.session){
      await refreshCloudUserFromSession(data.session);
      hasEverLoggedInOnDevice = true;
      await storageAPI.set('has-logged-in-before', 'true', false);
      signupResult = { type: 'success-session', email };
      saveLocalOnly();
      render();
      await refreshAllCloudDataAfterLogin(); // item 8 — לא רק cloudCurrentUser, גם company settings/clients/projects/drafts בפועל
      return true;
    } else {
      signupResult = { type: 'success-confirm-email', email };
    }
    saveLocalOnly();
    render();
    return true;
  }catch(err){
    cloudDebugLog('Signup: שגיאה בלתי צפויה', err.message);
    signupResult = { type: 'error', message: err && err.message ? err.message : String(err) };
    return false;
  }
}

// שכחתי סיסמה — שולח קישור איפוס מאובטח לאימייל (מנגנון Supabase המובנה), ולא סיסמה
// שהמערכת ממציאה ושולחת בטקסט גלוי במייל. קישור-איפוס בטוח משמעותית: הסיסמה החדשה
// נקבעת ע"י המשתמש עצמו בטופס מאובטח, ולעולם לא עוברת דרך תיבת המייל בטקסט קריא.
async function requestPasswordReset(email){
  if(!supabaseClient){ showToast('אין חיבור פעיל ל-Supabase — בדוק את הגדרות הענן קודם'); return false; }
  if(!email){ showToast('יש להזין כתובת אימייל'); return false; }
  try{
    const { error } = await supabaseClient.auth.resetPasswordForEmail(email, { redirectTo: window.location.origin + window.location.pathname });
    if(error){
      cloudDebugLog('Password reset: נכשל', error.message);
      showToast('שגיאה בשליחת קישור איפוס: ' + error.message);
      return false;
    }
    showToast('אם הכתובת רשומה במערכת, נשלח אליה קישור לאיפוס סיסמה. בדוק גם בתיקיית הספאם.');
    return true;
  }catch(err){
    showToast('שגיאה בשליחת קישור איפוס: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

async function submitNewPassword(password, confirm){
  if(!supabaseClient) return false;
  if(!password || password.length < 6){ showToast('הסיסמה חייבת להכיל לפחות 6 תווים'); return false; }
  if(password !== confirm){ showToast('הסיסמאות לא תואמות'); return false; }
  try{
    const { error } = await supabaseClient.auth.updateUser({ password });
    if(error){ showToast('שגיאה בקביעת הסיסמה: ' + error.message); return false; }
    passwordRecoveryMode = false;
    newPasswordFormState = { password: '', confirm: '' };
    try{ await storageAPI.set('has-logged-in-before', 'true', false); }catch(e){ /* לא קריטי */ }
    showToast('הסיסמה עודכנה בהצלחה — אתה מחובר כעת.');
    render();
    return true;
  }catch(err){
    showToast('שגיאה בקביעת הסיסמה: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

// עבור משתמש עם סיסמה זמנית (must_change_password=true) — מעדכן גם את user_profiles כדי
// שהמסך החוסם לא יופיע שוב בכניסות הבאות.
async function submitForcedPasswordChange(password, confirm){
  if(!supabaseClient || !cloudCurrentUser) return false;
  if(!password || password.length < 6){ showToast('הסיסמה חייבת להכיל לפחות 6 תווים'); return false; }
  if(password !== confirm){ showToast('הסיסמאות לא תואמות'); return false; }
  try{
    const { error } = await supabaseClient.auth.updateUser({ password });
    if(error){ showToast('שגיאה בקביעת הסיסמה: ' + error.message); return false; }
    const { error: profileErr } = await supabaseClient.from('user_profiles').update({ must_change_password: false }).eq('user_id', cloudCurrentUser.id);
    if(profileErr){ showToast('הסיסמה עודכנה, אך הייתה שגיאה בעדכון הפרופיל: ' + profileErr.message); }
    cloudCurrentUser.mustChangePassword = false;
    forcedPasswordFormState = { password: '', confirm: '' };
    showToast('הסיסמה נקבעה בהצלחה — ברוך הבא!');
    render();
    return true;
  }catch(err){
    showToast('שגיאה בקביעת הסיסמה: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

// רענון "קליל" — רק שליפת נתונים עדכניים, בלי הצעות migration (שלא צריכות לחזור על עצמן
// בכל חזרה לטאב אם המשתמש כבר דחה אותן פעם אחת). משמש לחזרה לטאב ולכפתור "רענן".
async function refreshCloudDataOnly(){
  if(!supabaseClient || !cloudCurrentUser) return;
  await verifyOpenReportFreshness('resume'); // Phase 2C
  // עוטף את כל העבודה (כולל 3 הפונקציות למטה, שקוראות render() פנימית בעצמן — פעמיים כל
  // אחת) ב-backgroundRefreshInProgress, כדי שה-guard החדש ב-render() (למעלה) יגן על כל
  // הקריאות האלה גם יחד, בלי לגעת בשלוש הפונקציות הקיימות כלל (הן ממשיכות להתנהג בדיוק
  // כמו קודם כשנקראות בהקשר הרגיל — פתיחת טאב ע"י המשתמש, שם backgroundRefreshInProgress
  // הוא false ו-render() לא מוגן/לא משתנה).
  backgroundRefreshInProgress = true;
  try{
    const cloudRow = await fetchCompanySettingsFromCloud();
    if(cloudRow) await applyCloudCompanySettings(cloudRow);
    await loadCloudClientsIfNeeded(true);
    await loadCloudEquipmentIfNeeded(true);
    await loadCloudDraftsIfNeeded(true);
    lastCloudSyncAt = new Date();
    // render() סופי — נדרש כי applyCloudCompanySettings לא קוראת render() בעצמה (משנה רק
    // state.settings). מוגן ע"י אותו guard בדיוק: אם המשתמש עורך שדה פעיל כרגע, זה רק
    // מסמן pendingBackgroundRender ולא הורס כלום — יוחל אוטומטית ב-focusout הבא (מיד כשהמשתמש
    // עצמו עוזב את השדה). זה בדיוק העיקרון שנדרש: foreground refresh נשמר במלואו (הנתונים
    // תמיד מגיעים ל-state ומוצגים בהקדם הבטוח ביותר), בלי לעולם להרוס DOM פעיל.
    render();
  } finally {
    backgroundRefreshInProgress = false;
  }
}

// רענון מלא — כולל הצעות migration. משמש רק בעליית האפליקציה ומיד אחרי login מפורש, לא
// בכל חזרה לטאב (section 5 במפרט).
async function refreshAllCloudDataAfterLogin(){
  if(!supabaseClient || !cloudCurrentUser) return;
  await verifyOpenReportFreshness('open'); // Phase 2C: לפני עריכה — הגרסה העדכנית מהענן
  await checkAndOfferCompanySettingsMigration(); // כולל טעינת/הצעת הגדרות חברה
  await loadCloudClientsIfNeeded(true);          // force=true: לא מסתפקים במטמון ישן
  await checkAndOfferClientsProjectsMigration();
  await loadCloudEquipmentIfNeeded(true);
  await checkAndOfferEquipmentMigration();
  await loadCloudDraftsIfNeeded(true);
  lastCloudSyncAt = new Date();
  render();
}

async function loginUser(email, password){
  cloudDebugLog('Login: מתחיל התחברות', email); // לא רושמים סיסמה בשום מקרה
  if(!supabaseClient){
    cloudDebugLog('Login: נכשל — אין חיבור Supabase פעיל');
    showToast('אין חיבור פעיל ל-Supabase — בדוק את הגדרות הענן קודם');
    return false;
  }
  if(!email || !password){
    cloudDebugLog('Login: נכשל — חסר אימייל/סיסמה');
    showToast('יש להזין אימייל וסיסמה');
    return false;
  }
  try{
    const { data, error } = await supabaseClient.auth.signInWithPassword({ email, password });
    if(error){
      cloudDebugLog('Login: נכשל', error.message);
      showToast('התחברות נכשלה: ' + error.message);
      return false;
    }
    await refreshCloudUserFromSession(data.session);
    cloudDebugLog('Login: הצלחה', cloudCurrentUser);
    showToast(`התחברת בהצלחה כ-${cloudCurrentUser.email}`);
    hasEverLoggedInOnDevice = true;
    await storageAPI.set('has-logged-in-before', 'true', false);
    saveLocalOnly();
    render();
    await refreshAllCloudDataAfterLogin(); // section 5 — לא מסתפקים ב-cloudCurrentUser בלבד
    return true;
  }catch(err){
    cloudDebugLog('Login: שגיאה בלתי צפויה', err.message);
    showToast('שגיאת התחברות: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

async function logoutUser(){
  cloudDebugLog('Logout: מתחיל');
  if(!supabaseClient) return;
  try{
    const { error } = await supabaseClient.auth.signOut();
    if(error){ cloudDebugLog('Logout: נכשל', error.message); showToast('שגיאה בהתנתקות: ' + error.message); return; }
    cloudCurrentUser = null;
    cloudClientOptions = []; cloudProjectOptions = []; // מנקים מטמון שיוך משתמש קודם
    cloudActiveClientName = ''; cloudActiveProjectName = '';
    cloudDebugLog('Logout: הצלחה');
    showToast('התנתקת בהצלחה');
    render();
  }catch(err){
    cloudDebugLog('Logout: שגיאה בלתי צפויה', err.message);
    showToast('שגיאת התנתקות: ' + (err && err.message ? err.message : String(err)));
  }
}

// בודק אם קיימת גרסה חדשה יותר של האפליקציה זמינה בשרת. שולף קובץ קליל נפרד (version.json),
// לא את כל app.js (~1.2MB), כדי לא לבזבז רוחב פס בכל בדיקה תקופתית. cache:'no-store' מוודא
// בדיקה אמיתית מול השרת בכל פעם, לא תשובה ישנה מהמטמון של הדפדפן עצמו.
async function checkForAppUpdate(){
  try{
    const res = await fetch('/version.json?t=' + Date.now(), { cache: 'no-store' });
    if(!res.ok) return;
    const data = await res.json();
    if(data && data.version && data.version !== APP_VERSION && (!pendingAppUpdate || pendingAppUpdate.version !== data.version)){
      pendingAppUpdate = { version: data.version, notes: data.notes || '', userSummary: data.userSummary || '' };
      showAppUpdateModal();
    }
  }catch(e){ /* בדיקת עדכון לא קריטית לתפקוד השוטף - נכשלת בשקט, מנסה שוב בפעם הבאה */ }
}

function showAppUpdateModal(){
  if(!pendingAppUpdate) return;
  document.getElementById('appUpdateVersionLabel').textContent = 'v' + pendingAppUpdate.version;
  // מעדיפים תקציר קצר וידידותי (userSummary) על פני התיעוד הטכני המפורט (notes) — האחרון
  // נכתב לצורך אימות/תיעוד פנימי, לא להצגה למשתמש הקצה. נופל חזרה ל-notes רק אם אין תקציר.
  document.getElementById('appUpdateNotesBody').textContent = pendingAppUpdate.userSummary || pendingAppUpdate.notes || '(אין פרטים זמינים)';
  document.getElementById('appUpdateModal').classList.add('show');
}

// גרסה של אותו חלון בדיוק, אך למצב "מה חדש" בעליית האפליקציה (לא זיהוי חי תוך כדי שימוש) —
// אין מה "לרענן אליו" כי הגרסה כבר טעונה, ולכן מוסתר כפתור "עדכן עכשיו"/"מאוחר יותר" ומוצג
// כפתור "הבנתי" בודד. לא נבנה חלון נפרד — שימוש חוזר באותו appUpdateModal.
function showWhatsNewModal(){
  if(!pendingWhatsNew) return;
  document.getElementById('appUpdateVersionLabel').textContent = 'v' + pendingWhatsNew.version;
  document.getElementById('appUpdateNotesBody').textContent = pendingWhatsNew.userSummary || '(אין פרטים זמינים)';
  const okBtn = document.getElementById('appUpdateOk');
  const laterBtn = document.getElementById('appUpdateLater');
  if(okBtn){ okBtn.textContent = '✓ הבנתי, תודה'; okBtn.setAttribute('data-mode', 'whats-new'); }
  if(laterBtn) laterBtn.style.display = 'none';
  // הפסקה הראשונה ("גרסה חדשה X זמינה. העדכון כולל:") לא משתנה — נשארת נכונה מספיק גם
  // כאן, ומכילה את b#appUpdateVersionLabel המקונן שחייב להישאר קיים ב-DOM.
  const paragraphs = document.querySelectorAll('#appUpdateModal .form-type-modal-body p');
  if(paragraphs[1]) paragraphs[1].style.display = 'none'; // "העדכון ירענן את הדף..." — לא רלוונטי, אין מה לרענן אליו
  document.getElementById('appUpdateModal').classList.add('show');
}

// בודק אם המשתמש כבר "ראה" את הגרסה הנוכחית (item שהמשתמש ביקש: עדכון שקורה "אוטומטית"
// בטלפון בלי הסבר — כי טעינה טרייה כבר מגיעה עם הקוד העדכני, אז אין זיהוי-חי של עדכון
// להציג בכלל). משווה מול last-seen-app-version מקומי; לא מציג בביקור הראשון אי-פעם (אין מה
// להשוות אליו).
async function checkForUnseenVersionOnStartup(){
  try{
    const stored = await storageAPI.get('last-seen-app-version', false);
    const lastSeen = stored && stored.value;
    if(lastSeen && lastSeen !== APP_VERSION && CHANGELOG[0] && CHANGELOG[0].version === APP_VERSION){
      pendingWhatsNew = { version: APP_VERSION, userSummary: CHANGELOG[0].userSummary || CHANGELOG[0].notes || '' };
      showWhatsNewModal();
    } else if(!lastSeen){
      // ביקור ראשון אי-פעם במכשיר הזה — לא מציגים "מה חדש", אבל כן שומרים את הגרסה הנוכחית
      // כנקודת ייחוס להשוואות עתידיות.
      await storageAPI.set('last-seen-app-version', APP_VERSION, false);
    }
  }catch(e){ /* לא קריטי לתפקוד השוטף */ }
}

function hideAppUpdateModal(){
  document.getElementById('appUpdateModal').classList.remove('show');
  // איפוס לברירת המחדל (מצב live-update) — כדי שהפעם הבאה שהחלון נפתח לא תישאר עם השינויים
  // שהוחלו במצב "מה חדש" (טקסט כפתור, הסתרת "מאוחר יותר"/הפסקה השנייה).
  const okBtn = document.getElementById('appUpdateOk');
  const laterBtn = document.getElementById('appUpdateLater');
  if(okBtn){ okBtn.textContent = '✓ עדכן עכשיו'; okBtn.removeAttribute('data-mode'); }
  if(laterBtn) laterBtn.style.display = '';
  const paragraphs = document.querySelectorAll('#appUpdateModal .form-type-modal-body p');
  if(paragraphs[1]) paragraphs[1].style.display = '';
}

// שומר קודם (מקומית — לא ממתין לענן, כדי לא לעכב את הריענון), כדי שלא לאבד עבודה לא-שמורה
// כשהדף מתרענן בפועל.
async function applyAppUpdate(){
  try{ await storageAPI.set('inspection-current', JSON.stringify(sanitizeStateForLocalSave(state)), false); }catch(e){ /* לא קריטי */ }
  // מסמנים שהגרסה הזו כבר "נראתה" (דרך חלון העדכון החי עצמו) — כדי שמסך "מה חדש" הנפרד
  // לא יופיע שוב מיותר מיד אחרי הרענון, על אותו מידע בדיוק.
  if(pendingAppUpdate){
    try{ await storageAPI.set('last-seen-app-version', pendingAppUpdate.version, false); }catch(e){ /* לא קריטי */ }
  }
  // cache-busting מפורש (לא reload() רגיל) — מבטיח בקשת רשת טרייה ל-index.html עצמו, לא רק
  // ל-app.js (שכבר מוגן ע"י ה-?v= הקיים). זה בדיוק הרגע שבו דווח על מסך שנתקע, כך שכל מקור
  // אפשרי לתוכן ישן/לא-עקבי מהמטמון כדאי לסגור כאן, לא רק להסתמך על טיימאאוט הרשת.
  window.location.href = window.location.pathname + '?_r=' + Date.now();
}

function startAppUpdatePolling(){
  if(appUpdateCheckIntervalId) return; // כבר רץ, לא מכפילים
  checkForAppUpdate(); // בדיקה ראשונה מיד בעליית האפליקציה
  appUpdateCheckIntervalId = setInterval(checkForAppUpdate, 5 * 60 * 1000); // כל 5 דקות
  document.addEventListener('visibilitychange', ()=>{
    if(document.visibilityState === 'visible'){
      checkForAppUpdate();
      // item 7 במפרט: חזרה לטאב מרעננת נתוני ענן, לא מסתפקים במטמון ישן — רק אם כבר מחוברים,
      // לא מפעיל את זרימת ההתחברות מחדש בכל חזרה לטאב.
      if(supabaseClient && cloudCurrentUser) refreshCloudDataOnly();
    }
  });
}

async function testSupabaseConnection(){
  const ok = await initSupabase();
  if(ok){
    showToast(cloudCurrentUser ? `חיבור תקין — מחובר כ-${cloudCurrentUser.email}` : 'חיבור ל-Supabase תקין (לא מחובר כרגע)');
  }else{
    showToast('בדיקת חיבור נכשלה: ' + cloudInitError);
  }
  render();
  return ok;
}

/* ---------- Cloud client/project management ----------
   These operate on the Supabase clients/projects tables specifically (real UUIDs,
   never names as identifiers). Returns null on any failure — callers must check for
   that rather than assuming success. */

async function createClient(clientData){
  cloudDebugLog('יצירת לקוח: מתחיל', clientData.name);
  if(!supabaseClient){ showToast('אין חיבור לענן — לא ניתן ליצור לקוח'); return null; }
  try{
    const { data, error } = await supabaseClient
      .from('clients')
      .insert({
        name: clientData.name || '',
        company_number: clientData.companyNumber || null,
        contact_name: clientData.contactName || (clientData.contacts && clientData.contacts[0] && clientData.contacts[0].name) || null,
        phone: clientData.phone || (clientData.contacts && clientData.contacts[0] && clientData.contacts[0].phone) || null,
        email: clientData.email || (clientData.emails && clientData.emails[0]) || null,
        address: clientData.address || null,
        contacts_json: clientData.contacts || [],
        emails_json: clientData.emails || [],
        // שדות קישור Fireberry — אופציונליים, לא שוברים קריאות קיימות שלא מעבירות אותם.
        // Supabase UUID (data.id) נשאר המזהה הפנימי היחיד — אלה רק קישור חיצוני, לפי בקשה
        // מפורשת: "Supabase Client UUID = המזהה הפנימי... fireberryClientId = הקישור החיצוני".
        fireberry_client_id: clientData.fireberryClientId || null,
        fireberry_contact_id: clientData.fireberryContactId || null,
      })
      .select()
      .single();
    if(error){ cloudDebugLog('יצירת לקוח: נכשל', error.message); showToast('שגיאה ביצירת לקוח בענן: ' + error.message); return null; }
    cloudDebugLog('יצירת לקוח: הצלחה', data.id);
    return data; // { id, name, ... } — id is the real Supabase UUID
  }catch(err){
    cloudDebugLog('יצירת לקוח: שגיאה בלתי צפויה', err.message);
    showToast('שגיאה ביצירת לקוח בענן: ' + (err && err.message ? err.message : String(err)));
    return null;
  }
}

async function updateClient(cloudClientId, clientData){
  if(!supabaseClient){ showToast('אין חיבור לענן — לא ניתן לעדכן לקוח'); return null; }
  if(!cloudClientId){ showToast('חסר מזהה לקוח בענן'); return null; }
  try{
    const updatePayload = {
      name: clientData.name,
      company_number: clientData.companyNumber || null,
      contact_name: clientData.contactName || (clientData.contacts && clientData.contacts[0] && clientData.contacts[0].name) || null,
      phone: clientData.phone || (clientData.contacts && clientData.contacts[0] && clientData.contacts[0].phone) || null,
      email: clientData.email || (clientData.emails && clientData.emails[0]) || null,
      address: clientData.address || null,
      contacts_json: clientData.contacts || [],
      emails_json: clientData.emails || []
    };
    // מעדכן קישור Fireberry רק אם סופק במפורש — לא דורס קישור קיים בטעות בעדכונים רגילים
    // שלא נוגעים ב-Fireberry בכלל (למשל עריכת טלפון דרך מסך "לקוחות" הרגיל).
    if(clientData.fireberryClientId !== undefined) updatePayload.fireberry_client_id = clientData.fireberryClientId || null;
    if(clientData.fireberryContactId !== undefined) updatePayload.fireberry_contact_id = clientData.fireberryContactId || null;
    const { data, error } = await supabaseClient
      .from('clients')
      .update(updatePayload)
      .eq('id', cloudClientId)
      .select()
      .single();
    if(error){ showToast('שגיאה בעדכון לקוח בענן: ' + error.message); return null; }
    return data;
  }catch(err){
    showToast('שגיאה בעדכון לקוח בענן: ' + (err && err.message ? err.message : String(err)));
    return null;
  }
}

// מחפשת לקוח קיים ב-Supabase לפי fireberry_client_id — למניעת כפילויות. לפי בקשה מפורשת:
// "לפני יצירת לקוח חדש חפש לפי fireberryClientId, לא רק לפי שם". שם זהה לא אמור להניח
// שזה אותו לקוח (סעיף 6 בבקשה) — לכן זו חייבת להיות הבדיקה הראשונה, לא fallback לפי שם.
async function findCloudClientByFireberryId(fireberryClientId){
  if(!supabaseClient || !fireberryClientId) return null;
  try{
    const { data, error } = await supabaseClient
      .from('clients')
      .select('*')
      .eq('fireberry_client_id', fireberryClientId)
      .eq('status', 'active')
      .maybeSingle();
    if(error){ cloudDebugLog('חיפוש לקוח לפי fireberryClientId: שגיאה', error.message); return null; }
    return data; // null אם לא נמצא, אחרת הרשומה המלאה
  }catch(err){
    cloudDebugLog('חיפוש לקוח לפי fireberryClientId: שגיאה בלתי צפויה', err.message);
    return null;
  }
}

let fireberryBulkImportProgress = null; // {status, fetched, existing, toInsert, inserted, error}

function renderFireberryBulkImportStatus(){
  const p = fireberryBulkImportProgress;
  if(!p) return '';
  const box = (color, content) => `<div style="border:1px solid ${color}; border-radius:8px; padding:10px 12px; margin-top:8px; background:${color}1a;">${content}</div>`;
  if(p.status === 'fetching') return box('#5cc2f2', `🔄 שולף לקוחות מ-Fireberry...`);
  if(p.status === 'checking') return box('#5cc2f2', `🔄 נשלפו ${p.fetched} לקוחות — בודק אילו כבר קיימים...`);
  if(p.status === 'inserting') return box('#4ade80', `🔄 יוצר לקוחות חדשים: ${p.inserted} / ${p.toInsert}...`);
  if(p.status === 'done') return box('#4ade80', `✅ הייבוא הושלם — נמצאו ${p.fetched} לקוחות בפירבארי, ${p.inserted} נוצרו כחדשים, ${p.existing} כבר היו מקושרים (דילוג, ללא כפילות).`)
    + (p.fetched === 0 && p.diagnosticInfo ? box('#e7cc76', `⚠️ נמצאו 0 לקוחות — מידע אבחוני מהתגובה הגולמית של Fireberry: <pre style="white-space:pre-wrap; font-size:11px; margin-top:6px;">${escapeHtml(JSON.stringify(p.diagnosticInfo, null, 2))}</pre>אם זה ממשיך לקרות, שלח את המידע הזה לתמיכה.`) : '');
  if(p.status === 'error') return box('#e57373', `🔴 הייבוא נכשל: ${escapeHtml(p.error||'')}`);
  return '';
}

// ייבוא מרוכז של כל הלקוחות מ-Fireberry — לפי בקשה מפורשת. יעיל למערכות עם מאות לקוחות:
// שאילתה *אחת* לבדיקת מי כבר קיים (לפי fireberry_client_id, לא שם — מניעת כפילויות אמיתית,
// אותו עיקרון כמו linkFireberryClientToCloud), ואז הכנסה בקבוצות (chunks של 200) במקום
// קריאה נפרדת לכל לקוח — משמעותית מהיר יותר מ-300+ קריאות רצופות.
async function bulkImportClientsFromFireberry(){
  if(!supabaseClient || !cloudCurrentUser){ showToast('אין חיבור לענן פעיל'); return; }
  fireberryBulkImportProgress = { status: 'fetching', fetched:0, existing:0, toInsert:0, inserted:0, error:null };
  render();

  try{
    const token = await getFireberrySessionToken();
    if(!token){ fireberryBulkImportProgress = { status:'error', error:'לא מחובר' }; render(); return; }
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-bulk-import-clients`, {
      method: 'POST', headers: { 'Authorization': `Bearer ${token}`, 'Content-Type':'application/json' }
    });
    const body = await resp.json();
    if(!resp.ok || body.error){
      fireberryBulkImportProgress = { status:'error', error: body.error || `שגיאה (${resp.status})` };
      render(); return;
    }

    const fireberryClients = body.clients || [];
    fireberryBulkImportProgress.fetched = fireberryClients.length;
    fireberryBulkImportProgress.diagnosticInfo = body.diagnosticInfo || null; // לתצוגה אם 0 נמצאו
    fireberryBulkImportProgress.status = 'checking';
    render();

    // תיקון קריטי — לפי דיווח משתמש ("הרצתי שוב את הייבוא, עדיין ריק"): עד כה הייבוא היה
    // מדלג *לגמרי* על לקוחות שכבר קיימים (רק מוסיף חדשים) — כך שגם אחרי תיקון בצד השרת
    // (הוספת billingstreet לשאילתת Fireberry), לקוחות שכבר יובאו לפני התיקון לעולם לא
    // קיבלו את הכתובת המלאה החדשה, כי הם נחשבו "כבר קיימים" ולא נגעו בהם כלל. עכשיו נבדק
    // גם address הנוכחי (לא רק fireberry_client_id) — לקוחות קיימים שחסרה להם כתובת
    // מתעדכנים בכתובת מ-Fireberry; לקוחות עם כתובת קיימת (גם אם הוזנה ידנית דרך עריכה
    // מהירה, v2.346) לא נדרסים.
    const { data: existingRows, error: existErr } = await supabaseClient
      .from('clients').select('id, fireberry_client_id, address').not('fireberry_client_id', 'is', null);
    if(existErr){ fireberryBulkImportProgress = { status:'error', error: existErr.message }; render(); return; }
    const existingById = new Map((existingRows||[]).map(r => [r.fireberry_client_id, r]));

    const newClients = fireberryClients.filter(c => !existingById.has(c.fireberryClientId));
    const toUpdate = fireberryClients
      .map(c => ({ c, existing: existingById.get(c.fireberryClientId) }))
      .filter(({c, existing}) => existing && !existing.address && c.city);
    fireberryBulkImportProgress.existing = fireberryClients.length - newClients.length;
    fireberryBulkImportProgress.toInsert = newClients.length;
    fireberryBulkImportProgress.toUpdate = toUpdate.length;
    fireberryBulkImportProgress.status = 'inserting';
    render();

    const CHUNK_SIZE = 200; // הכנסה בקבוצות — לא כל 300+ הלקוחות בקריאה אחת ולא אחד-אחד
    let insertedTotal = 0;
    for(let i=0; i<newClients.length; i+=CHUNK_SIZE){
      const chunk = newClients.slice(i, i+CHUNK_SIZE).map(c => ({
        name: c.name,
        phone: c.phone || null,
        email: c.email || null,
        // אין עמודת city ייעודית בטבלת clients הקיימת — משולב לתוך address, כדי לא לאבד
        // את המידע, לפי בקשה מפורשת "כולל כל הפרטים שלה".
        address: c.city || null,
        fireberry_client_id: c.fireberryClientId,
      }));
      const { error: insErr } = await supabaseClient.from('clients').insert(chunk);
      if(insErr){
        fireberryBulkImportProgress = { ...fireberryBulkImportProgress, status:'error', error: insErr.message };
        render(); return;
      }
      insertedTotal += chunk.length;
      fireberryBulkImportProgress.inserted = insertedTotal;
      render();
    }

    // עדכון כתובת ללקוחות קיימים שחסרה להם — כתובות (לא בקבוצות; מספר הלקוחות שדורשים עדכון
    // בפועל בדרך כלל קטן משמעותית מסך כל הלקוחות, כי רוב הלקוחות הקיימים כבר יובאו תקין).
    let updatedTotal = 0;
    for(const {c, existing} of toUpdate){
      const { error: updErr } = await supabaseClient.from('clients').update({ address: c.city }).eq('id', existing.id);
      if(!updErr) updatedTotal++;
      fireberryBulkImportProgress.updated = updatedTotal;
      render();
    }

    fireberryBulkImportProgress.status = 'done';
    render();
    loadCloudClientsIfNeeded(true); // מרענן את ה-cache המקומי כדי לשקף את הלקוחות החדשים/המעודכנים
    showToast(`הייבוא הושלם: ${insertedTotal} לקוחות חדשים, ${updatedTotal} כתובות הושלמו ללקוחות קיימים`);
  }catch(err){
    fireberryBulkImportProgress = { status:'error', error: err && err.message ? err.message : String(err) };
    render();
  }
}


// סנכרון רקע שקט מ-Fireberry — לפי בקשה מפורשת ("אוטומטי ברקע כל פעם שנכנסים לרשימת
// הלקוחות, בודק בשקט אם יש חדשים"). לא מציג את תצוגת ההתקדמות המפורטת של הכפתור הידני —
// רק toast עדין אם בפועל נוספו לקוחות חדשים. Cooldown של 10 דקות (נשמר ב-storageAPI, שורד
// רענון דף) כדי לא לקרוא ל-Fireberry API בכל כניסה חוזרת למסך הלקוחות באותה ישיבה.
let clientsSyncSilentInProgress = false;
async function silentClientsSyncFromFireberry(){
  if(!supabaseClient || !cloudCurrentUser) return; // דורש חיבור ענן פעיל, כמו הכפתור הידני
  if(clientsSyncSilentInProgress) return; // מונע ריצות מקבילות אם render() נקרא שוב לפני שהקודם סיים
  const COOLDOWN_MS = 10 * 60 * 1000; // 10 דקות
  try{
    const last = await storageAPI.get('fireberry-clients-last-silent-sync', false);
    if(last && last.value && (Date.now() - parseInt(last.value, 10)) < COOLDOWN_MS) return;
  }catch(e){ /* אם השדה לא קיים עדיין — ממשיכים לסנכרון הראשון */ }

  clientsSyncSilentInProgress = true;
  try{
    const token = await getFireberrySessionToken();
    if(!token) return; // לא מחובר ל-Fireberry — לא מציגים שגיאה, זה בדיקת רקע שקטה
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-bulk-import-clients`, {
      method: 'POST', headers: { 'Authorization': `Bearer ${token}`, 'Content-Type':'application/json' }
    });
    const body = await resp.json();
    if(!resp.ok || body.error){ cloudDebugLog('סנכרון רקע שקט מ-Fireberry נכשל', body.error || resp.status); return; }

    const fireberryClients = body.clients || [];
    const { data: existingRows, error: existErr } = await supabaseClient
      .from('clients').select('fireberry_client_id').not('fireberry_client_id', 'is', null);
    if(existErr){ cloudDebugLog('סנכרון רקע שקט — שגיאה בבדיקת קיימים', existErr.message); return; }
    const existingIds = new Set((existingRows||[]).map(r => r.fireberry_client_id));
    const newClients = fireberryClients.filter(c => !existingIds.has(c.fireberryClientId));

    if(newClients.length){
      const CHUNK_SIZE = 200;
      let insertedTotal = 0;
      for(let i=0; i<newClients.length; i+=CHUNK_SIZE){
        const chunk = newClients.slice(i, i+CHUNK_SIZE).map(c => ({
          name: c.name, phone: c.phone || null, email: c.email || null,
          address: c.city || null, fireberry_client_id: c.fireberryClientId,
        }));
        const { error: insErr } = await supabaseClient.from('clients').insert(chunk);
        if(insErr){ cloudDebugLog('סנכרון רקע שקט — שגיאת הכנסה', insErr.message); break; }
        insertedTotal += chunk.length;
      }
      if(insertedTotal){
        loadCloudClientsIfNeeded(true);
        showToast(`נוספו ${insertedTotal} לקוחות חדשים מ-Fireberry`);
      }
    }
    await storageAPI.set('fireberry-clients-last-silent-sync', String(Date.now()), false);
  }catch(err){
    cloudDebugLog('סנכרון רקע שקט מ-Fireberry — שגיאה בלתי צפויה', err && err.message ? err.message : String(err));
  }finally{
    clientsSyncSilentInProgress = false;
  }
}

// המסלול המאוחד היחיד לקישור/יצירת לקוח מתוך Fireberry — לפי בקשה מפורשת (שלב 2):
// Fireberry Client → בדיקה אם כבר קיים fireberryClientId → קיים: updateClient() /
// לא קיים: createClient() → Supabase → UUID אמיתי → local cache. לא עוד addOrUpdateClient()
// + makePanelId() ישירות כשמחוברים לענן. Offline: fallback מקומי מותר במפורש, עם
// syncStatus:'pending_sync' לטיפול עתידי (migration בחזרת הרשת — לא ממומש עדיין בשלב זה).
async function linkFireberryClientToCloud(fireberryClientId, fireberryClientName, fireberryContactId){
  const usingCloud = !!(supabaseClient && cloudCurrentUser);

  if(!usingCloud){
    let localClient = findClientByName(fireberryClientName);
    if(!localClient){
      localClient = { id: makePanelId(), name: fireberryClientName, address:'', contactName:'', phone:'', email:'' };
    }
    localClient.fireberryClientId = fireberryClientId;
    localClient.fireberryContactId = fireberryContactId || '';
    localClient.syncStatus = 'pending_sync'; // לפי בקשה מפורשת — מסומן לצורך migration עתידי
    await addOrUpdateClient(localClient);
    return { cloudClientId: null, localClient, wasExisting: false };
  }

  // 1. חיפוש לפי fireberryClientId קודם — מונע כפילויות אמיתי. שם זהה לא מספיק (סעיף 6
  // בבקשה: "בדוק גם שני לקוחות בעלי אותו שם — המערכת לא יכולה להניח ששם זהה = אותו לקוח").
  let cloudRow = await findCloudClientByFireberryId(fireberryClientId);
  const wasExisting = !!cloudRow;

  if(cloudRow){
    cloudRow = await updateClient(cloudRow.id, { name: fireberryClientName, fireberryClientId, fireberryContactId: fireberryContactId||'' }) || cloudRow;
  } else {
    cloudRow = await createClient({ name: fireberryClientName, fireberryClientId, fireberryContactId: fireberryContactId||'' });
  }
  if(!cloudRow) return null;

  // 2. עדכון ה-cache המקומי עם הרשומה האמיתית מהענן — id הוא UUID אמיתי מ-Supabase,
  // לא makePanelId(). זה מה שמאפשר לדוח להשתמש ב-cloudClientId אמיתי.
  const localEquivalent = {
    id: cloudRow.id,
    name: cloudRow.name,
    address: cloudRow.address || '',
    contactName: cloudRow.contact_name || '',
    phone: cloudRow.phone || '',
    email: cloudRow.email || '',
    fireberryClientId: cloudRow.fireberry_client_id || '',
    fireberryContactId: cloudRow.fireberry_contact_id || '',
  };
  await addOrUpdateClient(localEquivalent);
  if(cloudClientsCache){
    const idx = cloudClientsCache.findIndex(c => c.id === cloudRow.id);
    const normalized = normalizeCloudClient(cloudRow);
    if(idx >= 0) cloudClientsCache[idx] = normalized; else cloudClientsCache.push(normalized);
  }

  return { cloudClientId: cloudRow.id, localClient: localEquivalent, wasExisting };
}

// ארכוב לקוח (soft delete) — לא מחיקה פיזית, כדי לא לפגוע בדוחות שכבר משויכים אליו.
async function archiveClient(cloudClientId){
  if(!supabaseClient) return false;
  try{
    const { error } = await supabaseClient.from('clients').update({ status: 'archived' }).eq('id', cloudClientId);
    if(error){ showToast('שגיאה בארכוב לקוח: ' + error.message); return false; }
    return true;
  }catch(err){
    showToast('שגיאה בארכוב לקוח: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

async function createProject(cloudClientId, projectData){
  cloudDebugLog('יצירת פרויקט: מתחיל', projectData.name);
  if(!supabaseClient){ showToast('אין חיבור לענן — לא ניתן ליצור פרויקט'); return null; }
  if(!cloudClientId){ showToast('יש לבחור/ליצור לקוח בענן קודם'); return null; }
  try{
    const { data, error } = await supabaseClient
      .from('projects')
      .insert({
        client_id: cloudClientId,
        name: projectData.name || '',
        project_number: projectData.projectNumber || null,
        address: projectData.address || null,
        description: projectData.description || null
      })
      .select()
      .single();
    if(error){ cloudDebugLog('יצירת פרויקט: נכשל', error.message); showToast('שגיאה ביצירת פרויקט בענן: ' + error.message); return null; }
    cloudDebugLog('יצירת פרויקט: הצלחה', data.id);
    return data;
  }catch(err){
    cloudDebugLog('יצירת פרויקט: שגיאה בלתי צפויה', err.message);
    showToast('שגיאה ביצירת פרויקט בענן: ' + (err && err.message ? err.message : String(err)));
    return null;
  }
}

async function updateProject(cloudProjectId, projectData){
  if(!supabaseClient){ showToast('אין חיבור לענן — לא ניתן לעדכן פרויקט'); return null; }
  if(!cloudProjectId){ showToast('חסר מזהה פרויקט בענן'); return null; }
  try{
    const { data, error } = await supabaseClient
      .from('projects')
      .update({
        name: projectData.name,
        project_number: projectData.projectNumber || null,
        address: projectData.address || null,
        description: projectData.description || null
      })
      .eq('id', cloudProjectId)
      .select()
      .single();
    if(error){ showToast('שגיאה בעדכון פרויקט בענן: ' + error.message); return null; }
    return data;
  }catch(err){
    showToast('שגיאה בעדכון פרויקט בענן: ' + (err && err.message ? err.message : String(err)));
    return null;
  }
}

// ארכוב פרויקט (soft delete)
async function archiveProject(cloudProjectId){
  if(!supabaseClient) return false;
  try{
    const { error } = await supabaseClient.from('projects').update({ status: 'archived' }).eq('id', cloudProjectId);
    if(error){ showToast('שגיאה בארכוב פרויקט: ' + error.message); return false; }
    return true;
  }catch(err){
    showToast('שגיאה בארכוב פרויקט: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

