// מחפש/טוען את כל מכשירי הבדיקה הפעילים בענן
async function searchCloudEquipment(){
  if(!supabaseClient) return [];
  try{
    const { data, error } = await supabaseClient.from('equipment').select('*').eq('status', 'active').order('name');
    if(error){ cloudDebugLog('שגיאה בטעינת מכשירי בדיקה', error.message); return []; }
    cloudDebugLog(`נמצאו ${data.length} מכשירי בדיקה בענן`);
    return data || [];
  }catch(err){
    cloudDebugLog('שגיאה בטעינת מכשירי בדיקה (חריגה)', err.message);
    return [];
  }
}

// מחפש לקוחות בענן לפי שם/איש קשר/אימייל (חיפוש חלקי). מחרוזת ריקה = כל הלקוחות.
// מציג רק status='active' — ארכוב לא נכלל בתצוגה הרגילה.
async function searchCloudClients(searchTerm){
  if(!supabaseClient) return [];
  try{
    // v2.2.535 — טעינה בעמודים של 1000 (ברירת המחדל של השרת מחזירה עד 1000 שורות בלבד — לקוחות מעבר לזה "נעלמו")
    const data = [];
    for(let from = 0; from < 20000; from += 1000){
      let query = supabaseClient.from('clients').select('*').eq('status', 'active').order('name').range(from, from + 999);
      if(searchTerm && searchTerm.trim()){
        const term = `%${searchTerm.trim()}%`;
        query = query.or(`name.ilike.${term},contact_name.ilike.${term},email.ilike.${term},phone.ilike.${term}`);
      }
      const { data: page, error } = await query;
      if(error){ cloudDebugLog('שגיאה בחיפוש לקוחות', error.message); return data; }
      data.push(...(page || []));
      if(!page || page.length < 1000) break;
    }
    cloudDebugLog(`נמצאו ${data.length} לקוחות בענן`);
    return data || [];
  }catch(err){
    cloudDebugLog('שגיאה בחיפוש לקוחות (חריגה)', err.message);
    return [];
  }
}

// טוען פרויקטים של לקוח ספציפי בענן — רק status='active'
async function loadCloudProjectsForClient(clientId){
  if(!supabaseClient || !clientId) return [];
  try{
    const { data, error } = await supabaseClient
      .from('projects')
      .select('*')
      .eq('client_id', clientId)
      .eq('status', 'active')
      .order('name');
    if(error){ cloudDebugLog('שגיאה בטעינת פרויקטים', error.message); return []; }
    cloudDebugLog(`נמצאו ${data.length} פרויקטים ללקוח ${clientId}`);
    return data || [];
  }catch(err){
    cloudDebugLog('שגיאה בטעינת פרויקטים (חריגה)', err.message);
    return [];
  }
}

/* ---------- Cloud report save/load/list/versions ----------
   state IS the collected report data already (the whole app mutates it directly on
   every input), so there's no separate "collect" step — it's used as report_data as-is. */

// מזהה קבוע למכשיר/דפדפן הזה (נשמר מקומית). נכתב לתוך הדוח בכל שמירה לענן, כדי להבחין בין שינוי
// שנעשה *במכשיר הזה* (לשונית נוספת, טעינה מחדש, מעבר בין טיוטות) לבין שינוי אמיתי ממכשיר אחר.
function getDeviceId(){
  try{
    let id = localStorage.getItem('rdDeviceId');
    if(!id){ id = 'dev_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10); localStorage.setItem('rdDeviceId', id); }
    return id;
  }catch(e){ return 'dev_unknown'; }
}
// *** Phase 2B (v2.2.551) — זהות קבועה לדוח. ה-UUID של הדוח נקבע *בצד הלקוח* ברגע שהמשתמש
// יוצר דוח חדש במפורש (בדיקה חדשה / החלפת סוג דוח / שמירה כדוח נפרד / אישור מפורש), ונשמר
// ב-state.settings.cloudReportId עוד לפני ה-INSERT. cloudInsertPending=true מסמן "טרם נוצר
// בענן". כך ה-INSERT אידמפוטנטי: אם כבר נשלח (מירוץ / ריענון / מכשיר שני) — שגיאת מפתח
// כפול 23505 → עוברים ל-UPDATE של אותו UUID, אף פעם לא רשומה נוספת. בלי cloudReportId אין
// INSERT בכלל (שגיאת סנכרון), ושינוי פרויקט/לקוח/מיקום לעולם לא מחליף זהות או מספר.
function generateClientUuid(){
  try{ if(window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID(); }catch(e){}
  const b = new Uint8Array(16);
  try{ window.crypto.getRandomValues(b); }catch(e){ for(let i=0;i<16;i++) b[i] = Math.floor(Math.random()*256); }
  b[6] = (b[6] & 0x0f) | 0x40; b[8] = (b[8] & 0x3f) | 0x80;
  const h = Array.from(b, x => x.toString(16).padStart(2,'0')).join('');
  return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;
}
// נקרא רק מפעולות "דוח חדש" מפורשות. לא נוגע ב-report_number — הקורא קובע אותו.
function assignNewCloudReportIdentity(settings){
  const s = settings || state.settings;
  s.cloudReportId = generateClientUuid();
  s.cloudInsertPending = true;
  s.cloudInsertRequiresContent = false;
  s.cloudKnownUpdatedAt = null; s.cloudEditSeq = 0; s.cloudSyncedSeq = 0; // Phase 2C
  if(s === (state && state.settings)) cloudLastKnownUpdatedAt = null;
  s.cloudReportBaseline = null;
  return s.cloudReportId;
}
// דוח שכבר קיים בענן (יש מזהה ואין INSERT ממתין) — זהותו ומספרו קפואים.
function isCloudIdentityLocked(){
  return !!(state && state.settings && state.settings.cloudReportId && !state.settings.cloudInsertPending);
}
let cloudIdentityErrorToastAt = 0;
function reportCloudSyncError(msg){
  cloudSyncStatus = 'error';
  updateCompactStatusBarOnly();
  try{ setSavePill('שגיאת סנכרון — לא נשמר בענן', false); }catch(e){}
  const now = Date.now();
  if(now - cloudIdentityErrorToastAt > 20000){ cloudIdentityErrorToastAt = now; showToast('⚠️ שגיאת סנכרון: ' + msg); }
  cloudDebugLog('Sync error', msg);
}
// לחיצה מפורשת על שמירה כשאין לדוח זהות ענן (תוכן ישן/מיובא) — שואלים לפני יצירה.
async function ensureCloudIdentityExplicit(){
  state.settings.cloudInsertRequiresContent = false; // לחיצה מפורשת על שמירה = כוונה ליצור/לעדכן
  if(state.settings.cloudReportId) return true;
  const ok = await showAppConfirm(`הדוח הפתוח עדיין לא קיים בענן. ליצור אותו בענן כדוח חדש (מספר ${state.meta.reportNumber || '—'})?`);
  if(!ok) return false;
  assignNewCloudReportIdentity(state.settings);
  saveLocalOnly();
  return true;
}

// *** Phase 2C — גרסת הענן שהתוכן המקומי מבוסס עליה. נשמרת ב-state.settings.cloudKnownUpdatedAt,
// כלומר יחד עם הדוח עצמו ב-localStorage ('inspection-current' וכל draft-N) — שורדת refresh,
// logout/login וסגירת דפדפן, וקשורה לתוכן (טיוטה מקומית ישנה נושאת את הגרסה הישנה שלה).
// cloudLastKnownUpdatedAt בזיכרון נשאר רק כמראה לתאימות. cloudEditSeq/cloudSyncedSeq: מונה
// עריכות מקומיות מול מה שכבר הגיע לענן — "יש שינויים שלא נשמרו" שורד refresh.
function setKnownCloudVersion(v){
  state.settings.cloudKnownUpdatedAt = v || null;
  cloudLastKnownUpdatedAt = v || null;
}
function isLocalDirtySinceCloud(){
  return (state.settings.cloudEditSeq || 0) > (state.settings.cloudSyncedSeq || 0);
}
function markLoadedFromCloud(updatedAt){
  // טיימר Auto-Save שתוזמן לפני הטעינה (עריכות של התוכן הקודם) לא ישמור את התוכן שזה עתה נטען
  try{ clearTimeout(cloudAutoSaveTimer); }catch(e){}
  setKnownCloudVersion(updatedAt);
  state.settings.cloudInsertPending = false;
  state.settings.cloudInsertRequiresContent = false;
  state.settings.cloudEditSeq = 0;
  state.settings.cloudSyncedSeq = 0;
}
async function fetchCloudVersionMeta(reportId){
  try{
    const { data, error } = await supabaseClient.from('reports')
      .select('id, updated_at, status, saved_by_device:report_data->settings->>savedByDevice')
      .eq('id', reportId).maybeSingle();
    if(error) return { error };
    return { row: data || null };
  }catch(e){ return { error: e }; }
}
function raiseCloudConflict(reportId, isDeleted){
  cloudSyncStatus = 'error';
  pendingCloudConflictReportId = reportId;
  pendingCloudConflictIsDeleted = !!isDeleted;
  updateCompactStatusBarOnly();
  try{ setSavePill(isDeleted ? 'הדוח נמחק/נארכב בענן — לא נשמר' : 'קונפליקט — לא נשמר בענן', false); }catch(e){}
  openCloudConflictModal();
  return 'conflict';
}
// בפתיחת דוח קיים (טעינת האפליקציה / login / חזרה לטאב / חזרת רשת / טעינת טיוטה מקומית):
// מוודא שהעריכה מתחילה מהגרסה העדכנית בענן. גרסה זהה → ממשיכים. גרסה אחרת בענן ואין שינויים
// מקומיים שלא נשמרו → טוענים את גרסת הענן. יש שינויים מקומיים (או שלא ידוע) → conflict מיד,
// בלי לכתוב כלום ובלי למחוק את העבודה המקומית.
let freshnessCheckInFlight = false;
async function verifyOpenReportFreshness(reason){
  if(!supabaseClient || !cloudCurrentUser || navigator.onLine === false) return 'skip';
  if(!isCloudIdentityLocked() || freshnessCheckInFlight) return 'skip';
  const reportId = state.settings.cloudReportId;
  freshnessCheckInFlight = true;
  try{
    const meta = await fetchCloudVersionMeta(reportId);
    if(meta.error) return 'error';
    if(state.settings.cloudReportId !== reportId) return 'skip'; // המשתמש עבר לדוח אחר בינתיים
    if(!meta.row){ reportCloudSyncError('הדוח הפתוח לא נמצא בענן (מזהה ' + reportId.slice(0,8) + '). הנתונים שמורים מקומית.'); return 'missing'; }
    if(meta.row.status === 'archived' || meta.row.status === 'deleted') return 'tombstone'; // יטופל בשמירה
    const known = state.settings.cloudKnownUpdatedAt || null;
    if(known && meta.row.updated_at === known) return 'current';
    if(!known && meta.row.saved_by_device && meta.row.saved_by_device === getDeviceId()){
      setKnownCloudVersion(meta.row.updated_at); saveLocalOnly(); return 'adopted';
    }
    if(known && !isLocalDirtySinceCloud() && reason !== 'local-draft'){
      cloudDebugLog('Freshness: בענן גרסה חדשה יותר ואין שינויים מקומיים — טוען מהענן', meta.row.updated_at);
      const keepTab = activeTab;
      const ok = await loadReportFromCloud(reportId);
      if(ok){ activeTab = keepTab; render(); showToast('נטענה הגרסה העדכנית של הדוח מהענן'); }
      return ok ? 'reloaded' : 'error';
    }
    cloudDebugLog('Freshness: בענן גרסה אחרת ויש כאן שינויים שלא נשמרו — conflict');
    raiseCloudConflict(reportId, false);
    return 'conflict';
  } finally { freshnessCheckInFlight = false; }
}

async function checkCloudConflict(reportId){
  if(!supabaseClient || !reportId) return 'unknown';
  try{
    const { data, error } = await supabaseClient.from('reports').select('updated_at, status, saved_by_device:report_data->settings->>savedByDevice').eq('id', reportId).maybeSingle();
    if(error) return 'unknown';
    if(!data) return 'missing'; // Phase 2B: ה-UUID לא קיים בענן — עוצרים, לעולם לא INSERT חלופי
    // זיהוי מפורש של tombstone — הרשומה נארכבה/נמחקה במכשיר אחר, לא רק "עודכנה". לפי בקשה
    // מפורשת (תרחיש: מכשיר B היה Offline בזמן שמכשיר A מחק/ארכב) — לא מזהים את זה כ-conflict
    // רגיל (עריכה מתחרה), אלא כמצב נפרד וברור יותר: 'deleted'.
    if(data.status === 'archived' || data.status === 'deleted') return 'deleted';
    if(cloudLastKnownUpdatedAt && data.updated_at !== cloudLastKnownUpdatedAt){
      // הגרסה בענן נשמרה ע"י המכשיר הזה עצמו → לא "מכשיר אחר". מעדכנים את נקודת הייחוס וממשיכים לשמור.
      return 'conflict'; // Phase 2C: אין יותר פטור "אותו מכשיר" — טאב/מכשיר ישן לא דורס
    }
    return 'ok';
  }catch(e){
    return 'unknown';
  }
}

// שולף את כל הטיוטות (status='draft') מהענן — מקור האמת החדש למסך "ניהול טיוטות" (item 5 במפרט).
// כולל שמות לקוח/פרויקט דרך join, כי reports שומר רק UUID. RLS כבר מגביל לאותה חברה בלבד
// (reports_select_authenticated — כל משתמש מאומת רואה הכל, אין הפרדה בין organizations כאן).
// PHASE 1 — הגדרות חברה כישות ענן עצמאית, נפרדת מ-report_data של כל דוח בודד.
// שדות "זהות חברה" אמיתיים בלבד — נבדל במפורש משדות תצורת אפליקציה/מכשיר/דוח נוכחי
// (formTypeName, cloudClientId, supabaseUrl, maxDrafts וכו') שממשיכים להישאר מקומיים בלבד,
// כי אלה לא "מי החברה" אלא "איך המכשיר הזה מתנהג" — לא שייכים לסנכרון בין מכשירים.
const COMPANY_SETTINGS_FIELDS = ['companyName','companyTagline','engineerName','engineerLicenseNo','testerLicenseNo','licenseType','phone','officePhone','email','companyAddress','accessibilityCoordinatorName','inspectorIdNumber','licenseValidUntil'];

async function fetchCompanySettingsFromCloud(){
  if(!supabaseClient) return null;
  try{
    const { data, error } = await supabaseClient.from('company_settings').select('*').eq('id', 1).maybeSingle();
    if(error){ cloudDebugLog('fetchCompanySettings: שגיאה', error.message); return null; }
    return data; // null = עדיין אין שורה בכלל (טרם בוצעה שמירה ראשונה על ידי אף אחד)
  }catch(err){
    cloudDebugLog('fetchCompanySettings: שגיאה בלתי צפויה', err.message);
    return null;
  }
}

// שומר את הגדרות החברה הנוכחיות לענן. מעלה לוגו/חתימה ל-Storage רק אם הם base64 חדש (לא
// path קיים שכבר הועלה) — נמנע מהעלאה חוזרת מיותרת של אותה תמונה בכל שמירה.
async function saveCompanySettingsToCloud(){
  if(!supabaseClient || !cloudCurrentUser) return false;
  try{
    const settingsJson = {};
    COMPANY_SETTINGS_FIELDS.forEach(f => { settingsJson[f] = state.settings[f] || ''; });
    const payload = { id: 1, settings_json: settingsJson, updated_at: new Date().toISOString() };

    if(state.settings.logo && state.settings.logo.startsWith('data:')){
      const result = await uploadFileToCloudStorage('company', state.settings.logo, 'logo.jpg');
      if(result) payload.logo_path = result.path;
    } else if(state.settings.logoCloudPath){
      payload.logo_path = state.settings.logoCloudPath;
    }
    if(state.settings.signature && state.settings.signature.startsWith('data:')){
      const result = await uploadFileToCloudStorage('company', state.settings.signature, 'signature.png');
      if(result) payload.signature_path = result.path;
    } else if(state.settings.signatureCloudPath){
      payload.signature_path = state.settings.signatureCloudPath;
    }
    // לוגו תחתון — משתמש בעמודת stamp_path הקיימת בענן (הייתה מוגדרת בסכמה אך לא בשימוש
    // בקוד בכלל, אומת ישירות מול הטבלה לפני שימוש) — אותו מנגנון Storage/company_settings
    // בדיוק כמו logo/signature, לפי בקשה מפורשת לא ליצור מנגנון חדש. בניגוד ל-logo/signature
    // למעלה, כאן payload.stamp_path נשלח *במפורש* גם כשריק (else{payload.stamp_path=''}) —
    // כדי שמחיקה תסתנכרן נכון לענן (upsert חלקי לא מאפס עמודה שלא נכללת ב-payload בכלל).
    if(state.settings.footerLogo && state.settings.footerLogo.startsWith('data:')){
      const result = await uploadFileToCloudStorage('company', state.settings.footerLogo, 'footer-logo.jpg');
      if(result) payload.stamp_path = result.path;
    } else if(state.settings.footerLogoCloudPath){
      payload.stamp_path = state.settings.footerLogoCloudPath;
    } else {
      payload.stamp_path = '';
    }

    // v2.2.524 — צילום רישיון בודק: נשמר ב-Storage, הנתיב בתוך settings_json (בלי שינוי סכמה)
    if(state.settings.inspectorLicense && state.settings.inspectorLicense.startsWith('data:')){
      const result = await uploadFileToCloudStorage('company', state.settings.inspectorLicense, 'inspector-license.jpg');
      if(result) settingsJson.inspectorLicensePath = result.path;
    } else {
      settingsJson.inspectorLicensePath = state.settings.inspectorLicenseCloudPath || '';
    }
    settingsJson.attachLicenseToReports = state.settings.attachLicenseToReports ? 'yes' : '';
    settingsJson.hideElectricianDeclaration = state.settings.hideElectricianDeclaration ? 'yes' : '';
    const { error } = await supabaseClient.from('company_settings').upsert(payload, { onConflict: 'id' });
    if(error){ cloudDebugLog('saveCompanySettings: שגיאה', error.message); return false; }
    state.settings.inspectorLicenseCloudPath = settingsJson.inspectorLicensePath || '';
    if(payload.logo_path) state.settings.logoCloudPath = payload.logo_path;
    if(payload.signature_path) state.settings.signatureCloudPath = payload.signature_path;
    state.settings.footerLogoCloudPath = payload.stamp_path || '';
    return true;
  }catch(err){
    cloudDebugLog('saveCompanySettings: שגיאה בלתי צפויה', err.message);
    return false;
  }
}

// טוען הגדרות חברה מהענן לתוך ה-state הנוכחי. משמש גם בעליית האפליקציה וגם בכל דוח חדש.
// לא דורס שדות אם אין להם ערך בענן (שורה עדיין ריקה/לא קיימת) — כדי לא לאבד נתונים מקומיים
// בטעות אם הענן פשוט עדיין לא סונכרן.
async function applyCloudCompanySettings(cloudRow){
  if(!cloudRow) return false;
  const sj = cloudRow.settings_json || {};
  COMPANY_SETTINGS_FIELDS.forEach(f => {
    if(sj[f] !== undefined && sj[f] !== '') state.settings[f] = sj[f];
  });
  if(cloudRow.logo_path){
    state.settings.logoCloudPath = cloudRow.logo_path;
    const url = await getCloudFileSignedUrl(cloudRow.logo_path);
    if(url) state.settings.logo = url;
  }
  if(cloudRow.signature_path){
    state.settings.signatureCloudPath = cloudRow.signature_path;
    const url = await getCloudFileSignedUrl(cloudRow.signature_path);
    if(url) state.settings.signature = url;
  }
  // לוגו תחתון — בשונה מ-logo/signature למעלה, מטפל גם במקרה שבו stamp_path קיים בתגובה
  // אך *ריק* (לא undefined/חסר) — זה אומר שהמשתמש מחק את הלוגו התחתון במכשיר אחר, וצריך
  // לנקות אותו גם כאן, לא רק לטעון כשיש ערך. נדרש במפורש לבדיקת "מחיקה מסתנכרנת".
  if(sj.inspectorLicensePath !== undefined){
    state.settings.inspectorLicenseCloudPath = sj.inspectorLicensePath;
    if(sj.inspectorLicensePath){ const url = await getCloudFileSignedUrl(sj.inspectorLicensePath); if(url) state.settings.inspectorLicense = url; }
    else state.settings.inspectorLicense = '';
  }
  if(sj.attachLicenseToReports !== undefined) state.settings.attachLicenseToReports = sj.attachLicenseToReports === 'yes';
  if(sj.hideElectricianDeclaration !== undefined) state.settings.hideElectricianDeclaration = sj.hideElectricianDeclaration === 'yes';
  if(cloudRow.stamp_path !== undefined){
    state.settings.footerLogoCloudPath = cloudRow.stamp_path;
    if(cloudRow.stamp_path){
      const url = await getCloudFileSignedUrl(cloudRow.stamp_path);
      if(url) state.settings.footerLogo = url;
    } else {
      state.settings.footerLogo = ''; // נמחק במכשיר אחר — מנקה גם מקומית
    }
  }
  return true;
}

// PHASE 1, item 8 — Migration בטוח: אם יש הגדרות מקומיות משמעותיות אבל הענן עדיין ריק
// לגמרי (לא רק שדה בודד — כל הטבלה, כלומר אף אחד עדיין לא שמר פעם), מציעים להעלות.
// לעולם לא דורס ענן קיים בלי אישור מפורש מהמשתמש.
function localCompanySettingsHaveData(){
  return COMPANY_SETTINGS_FIELDS.some(f => state.settings[f] && state.settings[f].trim());
}

// PHASE 2, item 5-6 — Migration בטוח של לקוחות/פרויקטים מקומיים לענן. מזהה כפילויות לפי שם
// (case-insensitive, מגוזם רווחים) כדי לא ליצור רשומות כפולות. לא דורס נתונים בענן, רק מעלה
// מה שבאמת חסר, ומבקש אישור מפורש לפני כל העלאה.
async function checkAndOfferClientsProjectsMigration(){
  if(!supabaseClient || !cloudCurrentUser) return;
  // תיקון ממוקד: role='viewer'/'employee' לא יכולים ליצור לקוח/פרויקט בענן בכלל (RLS דורשת
  // admin/inspector) — הצעת migration הייתה חוסמת אותם עם מודל שנכשל תמיד, בכל login מחדש,
  // לנצח. אין טעם להציע משהו שלעולם לא יכול להצליח.
  if(!['admin','inspector'].includes(cloudCurrentUser.role)) return;
  if(!clientsList.length) return; // אין מה להעלות

  // אם המשתמש כבר דחה/נכשל בעבר במכשיר הזה, לא חוסמים שוב בכל כניסה — זו רק הצעת נוחות,
  // לא בטיחות קריטית כמו שער הכניסה.
  try{
    const dismissed = await storageAPI.get('clients-migration-dismissed', false);
    if(dismissed && dismissed.value === 'true') return;
  }catch(e){ /* ממשיכים כרגיל אם אין מידע קודם */ }

  const cloudClients = await searchCloudClients('');
  const cloudNamesLower = new Set(cloudClients.map(c=>(c.name||'').trim().toLowerCase()));
  const missingLocal = clientsList.filter(c => c.name && !cloudNamesLower.has(c.name.trim().toLowerCase()));

  if(!missingLocal.length) return; // כל הלקוחות המקומיים כבר קיימים בענן (לפי שם) — אין מה להציע

  const confirmed = await showAppConfirm(`נמצאו ${missingLocal.length} לקוחות שנשמרו במכשיר הזה ואינם בענן. להעלות אותם כדי שיהיו זמינים בכל המכשירים?`);
  if(!confirmed){
    try{ await storageAPI.set('clients-migration-dismissed', 'true', false); }catch(e){ /* לא קריטי */ }
    return;
  }

  let uploadedClients = 0, uploadedProjects = 0;
  for(const localClient of missingLocal){
    const cloudRow = await createClient({
      name: localClient.name,
      address: localClient.address,
      contacts: localClient.contacts || [],
      emails: localClient.emails || []
    });
    if(!cloudRow) continue;
    uploadedClients++;
    // מעלים גם את הפרויקטים המקומיים של אותו לקוח, משויכים ל-client_id החדש שנוצר בענן
    for(const localProject of (localClient.projects || [])){
      const projectRow = await createProject(cloudRow.id, { name: localProject.name });
      if(projectRow) uploadedProjects++;
    }
  }
  showToast(`הועלו ${uploadedClients} לקוחות ו-${uploadedProjects} פרויקטים לענן`);
  cloudClientsCache = null; // מאלץ רענון אמיתי בפעם הבאה שנפתח את מסך הלקוחות, לא מציג מטמון מיושן
  // גם אם ההעלאה נכשלה חלקית/לגמרי (uploadedClients=0), לא שואלים שוב בכל login — מונע
  // לולאה חוזרת של אותה שגיאה, בדיוק כמו שקרה בפועל.
  try{ await storageAPI.set('clients-migration-dismissed', 'true', false); }catch(e){ /* לא קריטי */ }
}

// אותו דפוס בדיוק כמו checkAndOfferClientsProjectsMigration, עבור מכשירי בדיקה
async function checkAndOfferEquipmentMigration(){
  if(!supabaseClient || !cloudCurrentUser) return;
  if(!['admin','inspector'].includes(cloudCurrentUser.role)) return;
  if(!equipmentList.length) return;

  try{
    const dismissed = await storageAPI.get('equipment-migration-dismissed', false);
    if(dismissed && dismissed.value === 'true') return;
  }catch(e){ /* ממשיכים כרגיל אם אין מידע קודם */ }

  const cloudEquipment = await searchCloudEquipment();
  const cloudNamesLower = new Set(cloudEquipment.map(e=>(e.name||'').trim().toLowerCase()));
  const missingLocal = equipmentList.filter(e => e.name && !cloudNamesLower.has(e.name.trim().toLowerCase()));

  if(!missingLocal.length) return;

  const confirmed = await showAppConfirm(`נמצאו ${missingLocal.length} מכשירי בדיקה שנשמרו במכשיר הזה ואינם בענן. להעלות אותם כדי שיהיו זמינים בכל המכשירים?`);
  if(!confirmed){
    try{ await storageAPI.set('equipment-migration-dismissed', 'true', false); }catch(e){ /* לא קריטי */ }
    return;
  }

  let uploadedCount = 0;
  for(const localEquip of missingLocal){
    const cloudRow = await createEquipment(localEquip);
    if(cloudRow) uploadedCount++;
  }
  showToast(`הועלו ${uploadedCount} מכשירי בדיקה לענן`);
  cloudEquipmentCache = null;
  try{ await storageAPI.set('equipment-migration-dismissed', 'true', false); }catch(e){ /* לא קריטי */ }
}

async function checkAndOfferCompanySettingsMigration(){
  if(!supabaseClient || !cloudCurrentUser) return;
  const cloudRow = await fetchCompanySettingsFromCloud();
  if(cloudRow){
    // הענן כבר מוגדר — הוא מקור האמת, טוענים ממנו (לא מציעים migration, זה לא ריק)
    await applyCloudCompanySettings(cloudRow);
    render();
    return;
  }
  // תיקון ממוקד: אותה בעיה בדיוק כמו בלקוחות — role='viewer'/'employee' לא יכולים לכתוב
  // ל-company_settings בכלל (RLS דורשת admin/inspector), אז המודל היה נכשל תמיד ושואל שוב
  // בכל login. זה בדיוק מה שהמשתמש דיווח: שני מודלים חוסמים שמופיעים בכל כניסה, אחד נכשל
  // עם 'שגיאה בהעלאת הגדרות החברה לענן', וחוסמים גישה לכפתור 'שמור' עד שנסגרים.
  if(!['admin','inspector'].includes(cloudCurrentUser.role)) return;
  try{
    const dismissed = await storageAPI.get('company-settings-migration-dismissed', false);
    if(dismissed && dismissed.value === 'true') return;
  }catch(e){ /* ממשיכים כרגיל אם אין מידע קודם */ }
  // אין שורה בענן בכלל
  if(localCompanySettingsHaveData()){
    const confirmed = await showAppConfirm('נמצאו הגדרות חברה שמורות במכשיר הזה, אך הענן עדיין ריק. להעלות אותן לענן כדי שיהיו זמינות בכל המכשירים?');
    if(confirmed){
      const ok = await saveCompanySettingsToCloud();
      showToast(ok ? 'הגדרות החברה הועלו לענן בהצלחה' : 'שגיאה בהעלאת הגדרות החברה לענן');
    }
    // בכל מקרה (אישר-ונכשל, או ביטל) — לא שואלים שוב בכל login הבא
    try{ await storageAPI.set('company-settings-migration-dismissed', 'true', false); }catch(e){ /* לא קריטי */ }
  }
}

async function fetchCloudDrafts(){
  if(!supabaseClient || !cloudCurrentUser) return null; // null = לא ניתן לשלוף (הקורא נופל חזרה למקומי)
  try{
    const { data, error } = await supabaseClient
      .from('reports')
      .select('id, report_number, report_type, report_title, status, updated_at, created_at, report_data, client_id, project_id, created_by, clients(name), projects(name)')
      .eq('status', 'draft')
      .order('updated_at', { ascending: false });
    if(error){ cloudDebugLog('fetchCloudDrafts: שגיאה', error.message); return null; }
    return data || [];
  }catch(err){
    cloudDebugLog('fetchCloudDrafts: שגיאה בלתי צפויה', err.message);
    return null;
  }
}

// אוכפת עד 5 טיוטות פעילות לכל קבוצה (item 10-11 במפרט). מפתח הקבוצה: project (אם יש),
// אחרת client, אחרת המשתמש שיצר — תמיד בשילוב עם report_type. organization מובלע: כל
// המשתמשים המאומתים באפליקציה הזו שייכים לאותה חברה יחידה (כפי ש-RLS כבר קובע).
async function enforceCloudDraftLimit(reportType, clientId, projectId, createdBy){
  // *** Phase 2A (v2.2.551) — ארכוב אוטומטי בוטל לחלוטין. דוח לעולם לא מועבר ל-archived בגלל
  // מגבלת כמות טיוטות; archive רק מפעולה מפורשת של משתמש. הפונקציה נשארת כ-no-op בלבד (אין
  // לה עוד קוראים) כדי שכל קריאה עתידית בטעות לא תשנה סטטוס של אף דוח.
  return;
  // eslint-disable-next-line no-unreachable
  if(!supabaseClient) return;
  try{
    let query = supabaseClient.from('reports').select('id, updated_at').eq('status', 'draft').eq('report_type', reportType);
    if(projectId) query = query.eq('project_id', projectId);
    else if(clientId) query = query.eq('client_id', clientId);
    else query = query.eq('created_by', createdBy);
    const { data, error } = await query;
    if(error || !data) return;
    const sorted = data.slice().sort((a,b)=> new Date(b.updated_at) - new Date(a.updated_at));
    const toArchive = sorted.slice(5); // משאירים את 5 החדשות ביותר, מארכבים את השאר
    for(const old of toArchive){
      await supabaseClient.from('reports').update({ status: 'archived' }).eq('id', old.id);
    }
  }catch(err){
    cloudDebugLog('enforceCloudDraftLimit: שגיאה', err.message);
  }
}

// section 33 במפרט — מעלה תמונות שצולמו/נוספו לפני שהיה cloudReportId (סומנו pendingUpload
// בזמן ההוספה, כי לא ניתן היה להעלות אותן מיד). נקראת אחרי שנוצר cloudReportId בפועל
// (רק בענף ה-INSERT הראשון בתוך saveReportToCloud, לא בכל UPDATE נוסף). לא חוסמת/ממתינה —
// רצה ברקע, בדיוק כמו העלאת תמונה רגילה.
async function processPendingPhotoUploads(){
  if(!supabaseClient || !state.settings.cloudReportId) return;
  const reportId = state.settings.cloudReportId;

  const generalPending = (state.generalPhotos || []).filter(p => p.pendingUpload);
  for(const entry of generalPending){
    try{
      const result = await uploadFileToCloudStorage(reportId, entry.dataUrl, entry.fileName || 'photo.jpg');
      if(result){ entry.cloudPath = result.path; delete entry.pendingUpload; }
    }catch(e){ cloudDebugLog('processPendingPhotoUploads: כשל בהעלאת תמונה כללית ממתינה', e.message); }
  }

  for(const key of Object.keys(state.itemPhotos || {})){
    const arr = state.itemPhotos[key] || [];
    for(const entry of arr){
      if(!entry.pendingUpload) continue;
      try{
        const result = await uploadFileToCloudStorage(reportId, entry.dataUrl, entry.fileName || 'photo.jpg');
        if(result){ entry.cloudPath = result.path; delete entry.pendingUpload; }
      }catch(e){ cloudDebugLog('processPendingPhotoUploads: כשל בהעלאת תמונת פריט ממתינה', e.message); }
    }
  }

  // *** תמונות-לפי-סעיף בדוח הגמיש — תיקון פער: הפונקציה הזו לא הייתה גנרית, רק
  // generalPhotos/itemPhotos. בלי זה, תמונת-סעיף שהועלתה לפני שהיה cloudReportId (הדוח
  // טרם נשמר בענן בכלל) הייתה נשארת pendingUpload לצמיתות, אף פעם לא מסתנכרנת. אותו
  // דפוס בדיוק כמו לולאת itemPhotos למעלה.
  let sectionPhotosPendingCount = 0;
  for(const sec of (state.flexibleReport && state.flexibleReport.sections) || []){
    const arr = sec.sectionPhotos || [];
    for(const entry of arr){
      if(!entry.pendingUpload) continue;
      sectionPhotosPendingCount++;
      try{
        const result = await uploadFileToCloudStorage(reportId, entry.dataUrl, entry.fileName || 'photo.jpg');
        if(result){ entry.cloudPath = result.path; delete entry.pendingUpload; }
      }catch(e){ cloudDebugLog('processPendingPhotoUploads: כשל בהעלאת תמונת סעיף ממתינה', e.message); }
    }
  }

  if(generalPending.length || Object.keys(state.itemPhotos || {}).length || sectionPhotosPendingCount){
    scheduleSave();
    render();
  }
}

// *** saveReportToCloud — wrapper מוגן (התיקון המרכזי ל-False Conflict). כל 8 הקוראים
// הקיימים ממשיכים לעבוד בלי שום שינוי (אותו שם פונקציה, אותו חוזה החזרה — true/'conflict'/
// 'offline'/false). saveReportToCloudInner (למעלה) היא הלוגיקה המקורית *בדיוק* — 0 שינוי.
// המפתח: reportId (state.settings.cloudReportId) בזמן הקריאה, או '__new__' אם עוד לא נוצר
// — "לכל report לכל היותר שמירה פעילה אחת בו-זמנית", בדיוק לפי הדרישה. אם שמירה לאותו
// מפתח כבר פעילה: מסמנים pending, לא מתחילים שמירה מקבילה (זה בדיוק מה שהיה גורם ל-
// checkCloudConflict לקרוא cloudLastKnownUpdatedAt ישן בזמן ששמירה אחרת כבר עדכנה את
// השרת). ברגע שהשמירה הפעילה מסתיימת, אם סומן pending — שומרים שוב מיד (לא מחכים לעוד
// טיימר), כדי שהשינוי האחרון תמיד יגיע לענן בלי לאבד אותו.
async function saveReportToCloud(){
  const saveKey = state.settings.cloudReportId || '__new__';
  if(cloudSaveInProgressKeys.has(saveKey)){
    cloudSavePendingKeys.add(saveKey);
    cloudDebugLog('Save report: שמירה כבר פעילה לדוח הזה — מסומן pending, לא נפתחת שמירה מקבילה', saveKey);
    return 'queued';
  }
  cloudSaveInProgressKeys.add(saveKey);
  try{
    return await saveReportToCloudInner();
  } finally {
    cloudSaveInProgressKeys.delete(saveKey);
    // *** אם שינוי נוסף הגיע תוך כדי השמירה (pending), שומרים שוב מיד — לפי המפתח *העדכני*
    // (state.settings.cloudReportId יכול היה להשתנות בתוך saveReportToCloudInner, למשל
    // מ-'__new__' למזהה אמיתי אחרי INSERT מוצלח) — לא לפי saveKey הישן, כדי לא ליצור INSERT
    // כפול לדוח שכבר נוצר.
    const currentKey = state.settings.cloudReportId || '__new__';
    if(cloudSavePendingKeys.has(saveKey) || cloudSavePendingKeys.has(currentKey)){
      cloudSavePendingKeys.delete(saveKey);
      cloudSavePendingKeys.delete(currentKey);
      saveReportToCloud();
    }
  }
}

async function saveReportToCloudInner(){
  console.log('[FBDEBUG] saveReportToCloud START'); // DEBUG זמני
  fbDebugSnapshot('saveReportToCloud START'); // DEBUG זמני
  cloudDebugLog('Save report: מתחיל');
  // 1. אסוף את כל נתוני הדוח — state הוא כבר הנתונים המלאים, בלי צורך בשלב איסוף נפרד
  state.settings.savedByDevice = getDeviceId(); // לזיהוי שמירות מאותו מכשיר (ראה checkCloudConflict)
  const reportData = state;

  // 2. ודא שמשתמש מחובר
  if(!cloudCurrentUser){ cloudDebugLog('Save report: נכשל — לא מחובר'); showToast('יש להתחבר לענן קודם'); return false; }

  // 3-4. client_id/project_id הם אופציונליים כעת (השדות הפכו nullable ב-DB) — תואם ל-fallback
  // שכבר מתואר ב-item 11 של המפרט: project+type → client+type → רק user+type. לפני התיקון,
  // חוסר בחירה ידנית של לקוח/פרויקט (שלב נפרד, לא חלק מזרימת "שמור טיוטה" הרגילה) היה גורם
  // ל-INSERT להיכשל בשקט בשלב הזה — הדוח מעולם לא הגיע ל-Supabase בכלל. זו הייתה סיבת השורש
  // האמיתית לכך שטיוטות לא הופיעו ב-📁 דוחות טיוטה בענן.
  const clientId = state.settings.cloudClientId || null;
  const projectId = state.settings.cloudProjectId || null;

  if(!supabaseClient){ cloudDebugLog('Save report: נכשל — אין חיבור Supabase'); showToast('אין חיבור פעיל לענן'); return false; }
  if(navigator.onLine === false){
    cloudDebugLog('Save report: אין אינטרנט — נכנס לתור offline');
    queueOfflineSave();
    return 'offline';
  }

  cloudSyncStatus = 'syncing-cloud';
  updateCompactStatusBarOnly();
  // לא קוראים render() מלא כאן — לפי בקשה מפורשת ("כל פעם שהדוח מתעדכן הוא סוגר לי מה
  // שאני עובד עליו"). זה רץ כל 5 שניות (auto-save לענן) כל עוד המשתמש עורך משהו — render()
  // מלא כל כך תדיר היה מכווץ כרטיסים/סעיפים פתוחים ומאבד פוקוס משדה טקסט פעיל, רק בשביל
  // עדכון קוסמטי של אייקון סטטוס קטן. עדכון קל (updateCompactStatusBarOnly) שומר על
  // האייקון מעודכן בזמן אמת, בלי לגעת בשאר ה-DOM.

  // Phase 2B: הוסר המנגנון שהחליף מספר דוח ויצר INSERT חדש כשהשתנו פרויקט/מיקום/תיאור.
  // שינוי פרטים בדוח קיים = UPDATE של אותו UUID ואותו report_number, תמיד.

  const reportId = state.settings.cloudReportId;

  if(!reportId){
    // Phase 2B: אין זהות ענן ואין פעולת "דוח חדש" מפורשת — אסור להמציא דוח בשקט.
    reportCloudSyncError('לדוח הפתוח אין זהות בענן. לחץ "שמור" כדי ליצור אותו במפורש, או "בדיקה חדשה".');
    return false;
  }

  const editSeqAtStart = state.settings.cloudEditSeq || 0;
  try{
    let insertedNow = false;
    if(state.settings.cloudInsertPending && state.settings.cloudInsertRequiresContent && !hasMeaningfulReportData()){
      cloudDebugLog('Save report: דוח ריק שנפתח אוטומטית בהפעלת המכשיר — לא נוצר בענן עד שיוזן תוכן');
      cloudSyncStatus = 'idle'; updateCompactStatusBarOnly();
      return 'empty';
    }
    if(state.settings.cloudInsertPending){
      state.settings.cloudInsertRequiresContent = false;
      // 5. דוח חדש שנוצר במפורש — INSERT עם ה-UUID שנקבע מראש (אידמפוטנטי)
      cloudDebugLog('Save report: יוצר דוח חדש בענן', reportId);
      // מספר דוח תפוס ע"י רשומה אחרת? (מונה מקומי/מירוץ) — מקצים מספר חדש *לפני* היצירה,
      // כי הדוח טרם נוצר; אחרי היצירה המספר קפוא.
      if(state.meta.reportNumber){
        const { data: numClash } = await supabaseClient.from('reports').select('id').eq('report_number', state.meta.reportNumber).neq('id', reportId).limit(1);
        if(numClash && numClash.length){
          const freshNumber = await getNextReportNumber();
          cloudDebugLog('Save report: מספר הדוח כבר תפוס בענן — הוקצה מספר חדש לפני יצירה', state.meta.reportNumber + ' → ' + freshNumber);
          state.meta.reportNumber = freshNumber;
        }
      }
      const insertData = JSON.parse(JSON.stringify(reportData));
      insertData.settings.cloudInsertPending = false; // ברשומה בענן הדוח כבר "קיים"
      insertData.settings.cloudReportId = reportId;
      const { data, error } = await supabaseClient
        .from('reports')
        .insert({
          id: reportId,
          project_id: projectId,
          client_id: clientId,
          report_number: state.meta.reportNumber || null,
          report_type: getPrimaryReportTypeCode(),
          report_title: state.meta.siteName || null,
          status: 'draft',
          inspection_date: state.meta.date || null,
          report_data: insertData, // 7. שמור report_data
          created_by: cloudCurrentUser.id
        })
        .select('id, updated_at')
        .single();
      if(error && (error.code === '23505' || /duplicate key/i.test(error.message||''))){
        // ה-INSERT של אותו UUID כבר בוצע (מירוץ/ריענון/מכשיר אחר) — זה אותו דוח. לא יוצרים
        // שום רשומה נוספת; מסמנים כקיים וממשיכים ל-UPDATE רגיל של אותו UUID.
        cloudDebugLog('Save report: ה-UUID כבר קיים בענן — עובר ל-UPDATE מותנה', reportId);
        state.settings.cloudInsertPending = false;
        setKnownCloudVersion(null); // לא ידוע על איזו גרסה התוכן הזה מבוסס — ייבדק לפני UPDATE
      } else {
      if(error) throw error;
      insertedNow = true;
      state.settings.cloudInsertPending = false;
      state.settings.cloudReportId = data.id;
      state.settings.cloudReportBaseline = { project: state.meta.project, address: state.meta.address, description: state.meta.description };
      setKnownCloudVersion(data.updated_at); // 8. Phase 2C: הגרסה שנוצרה — נשמרת מקומית (לא רק בזיכרון)
      cloudDebugLog('Save report: דוח חדש נוצר, מזהה', data.id);
      // Phase 2A: אין יותר ארכוב אוטומטי אחרי יצירת דוח (enforceCloudDraftLimit הוסר מכאן).
      processPendingPhotoUploads(); // section 33 — מעלה תמונות שצולמו לפני שהיה cloudReportId
      }
    }
    if(!insertedNow){
      // *** Phase 2C — Optimistic Concurrency בצד השרת. UPDATE מותנה: WHERE id = :id AND
      // updated_at = :הגרסה-שהמכשיר-מכיר. אם בינתיים נשמרה בענן גרסה אחרת (מכשיר אחר / טאב אחר /
      // מכשיר שעבר refresh עם תוכן ישן) — Postgres לא מעדכן אף שורה (0 rows) ושום דבר לא נדרס.
      // אין INSERT, אין דריסה, אין merge — רק חלונית conflict. הטריגר trg_reports_updated_at
      // מחליף updated_at בכל UPDATE, כך שכל שמירה מוצלחת "מבטלת" את כל העותקים הישנים.
      let known = state.settings.cloudKnownUpdatedAt || null;
      if(!known){
        // דוח מגרסה קודמת / ממתין מ-INSERT כפול, בלי גרסה ידועה. מאמצים את גרסת הענן רק אם
        // המכשיר הזה הוא האחרון ששמר אותה (אין שינוי של אף אחד אחר מאז); אחרת — conflict.
        const meta = await fetchCloudVersionMeta(reportId);
        if(meta.error){ reportCloudSyncError('לא ניתן לאמת את הדוח בענן כרגע. השמירה נעצרה, הנתונים שמורים מקומית — נסה שוב.'); return false; }
        if(!meta.row){ reportCloudSyncError('הדוח לא נמצא בענן (מזהה ' + reportId.slice(0,8) + '). השמירה נעצרה — לא נוצר דוח חדש. הנתונים שמורים מקומית.'); return false; }
        if(meta.row.status === 'archived' || meta.row.status === 'deleted'){ return raiseCloudConflict(reportId, true); }
        if(meta.row.saved_by_device && meta.row.saved_by_device === getDeviceId()){
          known = meta.row.updated_at;
          setKnownCloudVersion(known);
          cloudDebugLog('Save report: אין גרסה ידועה — המכשיר הזה הוא השומר האחרון, מאמץ', known);
        } else {
          cloudDebugLog('Save report: אין גרסה ידועה והגרסה בענן נשמרה ממכשיר אחר — conflict');
          return raiseCloudConflict(reportId, false);
        }
      }
      cloudDebugLog('Save report: UPDATE מותנה', reportId + ' @ ' + known);
      const { data: updRows, error } = await supabaseClient
        .from('reports')
        .update(Object.assign({
          // Phase 2B: report_number לא נשלח ב-UPDATE — המספר נקבע פעם אחת ב-INSERT ונשאר קבוע.
          report_type: getPrimaryReportTypeCode(),
          report_title: state.meta.siteName || null,
          inspection_date: state.meta.date || null,
          report_data: reportData // 7. שמור report_data
        },
        // Phase 2B: שינוי לקוח/פרויקט בדוח קיים = עדכון אותה רשומה (לא דוח חדש). נשלח רק כשנבחר
        // ערך, כדי שמכשיר בלי בחירה לא ינתק קישור קיים.
        clientId ? { client_id: clientId } : {},
        projectId ? { project_id: projectId } : {}))
        .eq('id', reportId)
        .eq('updated_at', known)       // Phase 2C: התנאי בצד השרת
        .select('id, updated_at');
      if(error) throw error;
      if(!updRows || !updRows.length){
        // 0 שורות עודכנו — מבררים למה (בלי לכתוב דבר): לא קיים / נמחק / גרסה חדשה יותר.
        const meta = await fetchCloudVersionMeta(reportId);
        if(meta.error){ reportCloudSyncError('השמירה לא בוצעה ולא ניתן לאמת את מצב הדוח בענן. הנתונים שמורים מקומית — נסה שוב.'); return false; }
        if(!meta.row){ reportCloudSyncError('הדוח לא נמצא בענן (מזהה ' + reportId.slice(0,8) + '). השמירה נעצרה — לא נוצר דוח חדש. הנתונים שמורים מקומית.'); return false; }
        if(meta.row.status === 'archived' || meta.row.status === 'deleted') return raiseCloudConflict(reportId, true);
        cloudDebugLog('Save report: conflict — בענן ' + meta.row.updated_at + ', המכשיר מכיר ' + known);
        return raiseCloudConflict(reportId, false);
      }
      setKnownCloudVersion(updRows[0].updated_at); // 8. הגרסה החדשה שהשרת קבע
    }
    state.settings.cloudSyncedSeq = editSeqAtStart; // Phase 2C: כל עריכה עד תחילת השמירה הגיעה לענן

    // 9. לאחר הצלחה: עדכן גם את השמירה המקומית (הגיבוי המקומי נשאר תמיד תקף).
    // חשוב: קריאה ישירה ל-storageAPI, לא ל-scheduleSave() — קריאה ל-scheduleSave כאן הייתה
    // מפעילה שוב את טיימר ה-Cloud Auto-Save (5 שניות), ויוצרת לולאה אינסופית של שמירות לענן
    // כל 5 שניות לנצח, גם בלי שום עריכה נוספת מהמשתמש. נמצא ותוקן תוך כדי בדיקה.
    try{ await storageAPI.set('inspection-current', JSON.stringify(sanitizeStateForLocalSave(state)), false); }catch(e){ /* הגיבוי המקומי לא קריטי כאן — השמירה לענן כבר הצליחה */ }

    cloudSyncStatus = 'synced-cloud';
    cloudLastSyncAt = Date.now();
    // תיקון תקלה נוספת שנתגלתה תוך כדי: lastCloudSyncAt (אובייקט Date, נקרא ע"י
    // renderCompactStatusBar ומקומות נוספים) הוא משתנה נפרד מ-cloudLastSyncAt (מספר,
    // Date.now()) שכבר נעדכן למעלה — בלי השורה הזו, "סנכרון אחרון" בסרגל הקומפקטי אף פעם
    // לא היה מתעדכן מסנכרוני ענן מוצלחים דרך saveReportToCloud, רק ממקומות אחרים שמעדכנים
    // את lastCloudSyncAt (שורות 492/506). לא הוסר cloudLastSyncAt — עדיין בשימוש במקום נפרד
    // (הגדרות ← ענן).
    lastCloudSyncAt = new Date();
    updateCompactStatusBarOnly();
    // אותה סיבה בדיוק כמו בתחילת הפונקציה — עדכון קל בלבד, לא render() מלא.

    // 11. רענון מיידי של מטמון הטיוטות בענן — עד עכשיו cloudDrafts לא התאפס אחרי שמירה
    // חדשה, כך שהתיקייה "📁 דוחות טיוטה בענן" המשיכה להציג ספירה/רשימה ישנה (למשל 0) גם
    // אחרי ששמירה חדשה כן הגיעה בהצלחה ל-Supabase, עד רענון ידני או טעינה מחדש של הדף.
    // force=true כדי לא להסתפק בבדיקת "כבר נטען", אלא לשלוף בפועל את המצב העדכני עכשיו.
    loadCloudDraftsIfNeeded(true);

    // 10. הצג הצלחה — רק כאן, אחרי תשובה מוצלחת מאושרת מהשרת. לעולם לא לפני.
    cloudDebugLog('Save report: הצלחה');
    console.log('[FBDEBUG] SUPABASE RESPONSE = success | ERROR = none | render() CALLED = no (עדכון קל בלבד)'); // DEBUG זמני
    showToast('הדוח נשמר בענן בהצלחה');
    return true;
  }catch(err){
    cloudDebugLog('Save report: שגיאה בלתי צפויה', err.message);
    cloudSyncStatus = 'error';
    // לפי בקשה מפורשת ("Save error does not close active work") — לא render() מלא, רק
    // עדכון פס הסטטוס הקומפקטי. אותו תיקון בדיוק כמו בענף הקונפליקט למעלה.
    updateCompactStatusBarOnly();
    showToast('שגיאה בשמירה לענן: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

function openCloudConflictModal(){
  const titleEl = document.querySelector('#cloudConflictModal h3');
  const descEl = document.querySelector('#cloudConflictModal .form-type-modal-body > p');
  const loadBtn = document.getElementById('cloudConflictLoadCloud');
  if(pendingCloudConflictIsDeleted){
    if(titleEl) titleEl.textContent = '🗑️ הדוח נמחק/נארכב ממכשיר אחר';
    if(descEl) descEl.textContent = 'הדוח הזה נמחק או הועבר לארכיון ממכשיר אחר בזמן שהיית לא-מחובר. אין גרסת ענן פעילה לטעון — הוא לא יופיע יותר ברשימת הדוחות הפעילים.';
    if(loadBtn) loadBtn.style.display = 'none';
  } else {
    if(titleEl) titleEl.textContent = '⚠️ הדוח עודכן ממכשיר אחר מאז שפתחת אותו';
    if(descEl) descEl.textContent = 'הדוח עודכן ממכשיר אחר מאז שפתחת אותו. השמירה שלך לא בוצעה ושום דבר לא נדרס. בחר: לטעון את גרסת הענן, לשמור את הגרסה שלך כעותק נפרד, או להשוות שינויים.';
    if(loadBtn) loadBtn.style.display = '';
  }
  const cmpBtn = document.getElementById('cloudConflictCompare');
  if(cmpBtn) cmpBtn.style.display = pendingCloudConflictIsDeleted ? 'none' : '';
  const diffEl = document.getElementById('cloudConflictDiff');
  if(diffEl){ diffEl.innerHTML = ''; diffEl.style.display = 'none'; }
  document.getElementById('cloudConflictModal').classList.add('show');
}

// *** Phase 2C — "השווה שינויים": קריאה בלבד. מציג אילו שדות שונים בין מה שרשום כאן לבין
// הגרסה בענן. לא ממזג ולא כותב שום דבר.
function flattenForCompare(obj, prefix, out){
  if(obj === null || obj === undefined) return out;
  if(typeof obj !== 'object'){ out[prefix] = String(obj); return out; }
  if(Array.isArray(obj)){ obj.forEach((v,i)=>flattenForCompare(v, prefix + '[' + i + ']', out)); if(!obj.length) out[prefix] = '[]'; return out; }
  for(const k of Object.keys(obj)){
    if(!prefix && k === 'settings') continue; // הגדרות מכשיר/סנכרון — לא תוכן הדוח
    if(['dataUrl','cloudPath','signedUrl','thumbUrl','pendingUpload'].includes(k)){ if(obj[k]) out[(prefix?prefix+'.':'')+k] = '[קובץ]'; continue; }
    flattenForCompare(obj[k], prefix ? prefix + '.' + k : k, out);
  }
  return out;
}
function buildConflictDiffRows(mine, cloud){
  const a = flattenForCompare(mine, '', {}), b = flattenForCompare(cloud, '', {});
  const keys = Array.from(new Set(Object.keys(a).concat(Object.keys(b)))).sort();
  return keys.filter(k => (a[k] || '') !== (b[k] || '')).map(k => ({ path: k, mine: a[k] || '', cloud: b[k] || '' }));
}
async function resolveCloudConflictCompare(){
  const diffEl = document.getElementById('cloudConflictDiff');
  const reportId = pendingCloudConflictReportId;
  if(!diffEl || !reportId || !supabaseClient) return;
  diffEl.style.display = 'block';
  diffEl.innerHTML = '<div style="font-size:12px;">טוען את גרסת הענן להשוואה…</div>';
  try{
    const { data, error } = await supabaseClient.from('reports').select('report_data, updated_at').eq('id', reportId).maybeSingle();
    if(error || !data){ diffEl.innerHTML = '<div style="font-size:12px;">לא ניתן לטעון את גרסת הענן כרגע.</div>'; return; }
    const rows = buildConflictDiffRows(state, data.report_data || {});
    const cut = v => escapeHtml(v.length > 120 ? v.slice(0,120) + '…' : v);
    diffEl.innerHTML = rows.length
      ? `<div style="font-size:12px; margin-bottom:6px;">${rows.length} שדות שונים (מקומי מול ענן). לא בוצע שום מיזוג.</div>
         <div style="max-height:260px; overflow:auto;"><table style="width:100%; border-collapse:collapse; font-size:11px;">
         <tr><th style="text-align:right;border-bottom:1px solid #ccc;">שדה</th><th style="text-align:right;border-bottom:1px solid #ccc;">אצלי</th><th style="text-align:right;border-bottom:1px solid #ccc;">בענן</th></tr>
         ${rows.slice(0,300).map(r=>`<tr><td style="vertical-align:top;padding:2px 4px;direction:ltr;text-align:left;">${escapeHtml(r.path)}</td><td style="vertical-align:top;padding:2px 4px;">${cut(r.mine)}</td><td style="vertical-align:top;padding:2px 4px;">${cut(r.cloud)}</td></tr>`).join('')}
         </table></div>`
      : '<div style="font-size:12px;">אין הבדלים בתוכן הדוח (ההבדל רק בגרסה). עדיין לא נשמר — בחר "טען את גרסת הענן" כדי להמשיך ממנה.</div>';
  }catch(e){ diffEl.innerHTML = '<div style="font-size:12px;">שגיאה בהשוואה.</div>'; }
}

function closeCloudConflictModal(){
  document.getElementById('cloudConflictModal').classList.remove('show');
  pendingCloudConflictReportId = null;
  pendingCloudConflictIsDeleted = false;
}

// אפשרות 1: טוען את גרסת הענן, מחליף את מה שערוך כרגע. loadReportFromCloud() כבר בנויה
// נכון בעצמה (כולל render() אחד, סביר וצפוי כאן — טעינת דוח חדש אמורה לרענן את כל הטופס).
async function resolveCloudConflictLoadCloud(){
  const reportId = pendingCloudConflictReportId;
  closeCloudConflictModal();
  if(reportId) await loadReportFromCloud(reportId);
}

// אפשרות 2: שומר את מה שערוך כאן כדוח *נפרד* חדש — לא דורס את גרסת הענן/לא "מחייה" רשומה
// שנמחקה (tombstone). משתמש באותו ניקוי זהות-דוח שכבר תוקן בשלב 1 (v2.297, "התחלה חדשה")
// — אבל בלי לאבד את תוכן הדוח הנוכחי, רק את זהות-הענן שלו, כדי שהשמירה הבאה תיצור רשומה
// חדשה במקום UPDATE על הרשומה הקיימת (או המחוקה).
async function resolveCloudConflictSaveAsNew(){
  closeCloudConflictModal();
  assignNewCloudReportIdentity(state.settings); // Phase 2B: בחירה מפורשת "שמור כדוח נפרד"
  state.meta.reportNumber = await getNextReportNumber(); // דוח נפרד = מספר נפרד (לא כפילות מספר)
  showToast('שומר את הדוח שלך כרשומה נפרדת בענן...');
  await saveReportToCloud();
  updateCompactStatusBarOnly();
}

// אפשרות 3: ביטול — לא שומר כלום, המשתמש ממשיך לערוך. אין render() בכלל.
function resolveCloudConflictCancel(){
  closeCloudConflictModal();
  showToast('השמירה בוטלה — ממשיך לערוך. נסה שוב לשמור כשתהיה מוכן.');
}

async function loadReportFromCloud(reportId){
  cloudDebugLog('Load report: מתחיל, מזהה', reportId);
  if(!supabaseClient){ cloudDebugLog('Load report: נכשל — אין חיבור'); showToast('אין חיבור פעיל לענן'); return false; }
  if(!reportId){ cloudDebugLog('Load report: נכשל — חסר מזהה'); showToast('חסר מזהה דוח'); return false; }
  try{
    // 1. טוענת את רשומת הדוח
    const { data, error } = await supabaseClient
      .from('reports')
      .select('*')
      .eq('id', reportId)
      .single();
    if(error){ cloudDebugLog('Load report: נכשל', error.message); showToast('שגיאה בטעינת הדוח מהענן: ' + error.message); return false; }
    if(!data){ cloudDebugLog('Load report: לא נמצא'); showToast('הדוח לא נמצא בענן'); return false; }

    // 2. קוראת report_data, 3. מעבירה למנגנון הטעינה הקיים (מיזוג עם ברירות מחדל, כמו טעינת טיוטה מקומית)
    state = mergeDefaults(newState(), data.report_data);
    state.settings.cloudReportId = data.id;
    markLoadedFromCloud(data.updated_at); // Phase 2B/2C: נטען מהענן = קיים, בגרסה הזו
    state.settings.cloudClientId = data.client_id;
    state.settings.cloudProjectId = data.project_id;
    state.settings.cloudReportBaseline = { project: state.meta.project, address: state.meta.address, description: state.meta.description };

    // 4-5. תמונות/נספחים/מודולים דינמיים משוחזרים אוטומטית — הם כבר חלק מ-report_data (state המלא)
    openSections = new Set(["meta"]); alreadySeededOpenCards.clear(); // איפוס יחד עם openSections, כדי שכרטיסים "פתוחים כברירת מחדל" יחזרו לפתוחים בדוח/פרק החדש
    openSubheads = new Set();
    activeTab = 'inspection';
    saveLocalOnly();

    // 6. מציגה את הדוח לעריכה
    render();
    cloudDebugLog('Load report: הצלחה');
    showToast('הדוח נטען מהענן בהצלחה');
    return true;
  }catch(err){
    cloudDebugLog('Load report: שגיאה בלתי צפויה', err.message);
    showToast('שגיאה בטעינת הדוח מהענן: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

async function listCloudReports(){
  if(!supabaseClient){ showToast('אין חיבור פעיל לענן'); return []; }
  try{
    const { data, error } = await supabaseClient
      .from('reports')
      .select('id, report_number, report_type, report_title, status, inspection_date, updated_at, created_by, client_id, project_id, clients(name), projects(name)')
      .order('updated_at', { ascending: false });
    if(error){ showToast('שגיאה בטעינת רשימת הדוחות: ' + error.message); return []; }
    return data || [];
  }catch(err){
    showToast('שגיאה בטעינת רשימת הדוחות: ' + (err && err.message ? err.message : String(err)));
    return [];
  }
}

async function createReportVersion(reportId){
  cloudDebugLog('יצירת גרסה: מתחיל', reportId);
  if(!supabaseClient){ showToast('אין חיבור פעיל לענן'); return null; }
  if(!reportId){ showToast('יש לשמור את הדוח בענן קודם ליצירת גרסה'); return null; }
  try{
    const { data: existing, error: fetchErr } = await supabaseClient
      .from('report_versions')
      .select('version_number')
      .eq('report_id', reportId)
      .order('version_number', { ascending: false })
      .limit(1);
    if(fetchErr) throw fetchErr;
    const nextVersion = (existing && existing.length ? existing[0].version_number : 0) + 1;
    const { data, error } = await supabaseClient
      .from('report_versions')
      .insert({
        report_id: reportId,
        version_number: nextVersion,
        report_data: state,
        created_by: cloudCurrentUser ? cloudCurrentUser.id : null
      })
      .select()
      .single();
    if(error) throw error;
    cloudDebugLog('יצירת גרסה: הצלחה, מספר גרסה', nextVersion);
    showToast(`נשמרה גרסה מס' ${nextVersion}`);
    return data;
  }catch(err){
    cloudDebugLog('יצירת גרסה: שגיאה', err.message);
    showToast('שגיאה ביצירת גרסה: ' + (err && err.message ? err.message : String(err)));
    return null;
  }
}

// רשימת כל הגרסאות של דוח, כולל שם המשתמש שביצע כל שמירה (אם ידוע — מחפש ב-user_profiles
// לפי created_by בנפרד, כי אין קשר-זרות ישיר בין report_versions ל-user_profiles בסכימה).
async function listReportVersionsForUI(reportId){
  if(!supabaseClient || !reportId) return [];
  try{
    const { data: versions, error } = await supabaseClient
      .from('report_versions')
      .select('id, version_number, created_at, created_by')
      .eq('report_id', reportId)
      .order('version_number', { ascending: false });
    if(error){ cloudDebugLog('שגיאה בטעינת היסטוריית גרסאות', error.message); return []; }
    if(!versions || !versions.length) return [];

    const userIds = [...new Set(versions.filter(v=>v.created_by).map(v=>v.created_by))];
    let namesByUserId = {};
    if(userIds.length){
      const { data: profiles } = await supabaseClient
        .from('user_profiles')
        .select('user_id, name')
        .in('user_id', userIds);
      if(profiles) profiles.forEach(p => { namesByUserId[p.user_id] = p.name; });
    }
    const result = versions.map(v => ({
      ...v,
      authorName: v.created_by ? (namesByUserId[v.created_by] || 'משתמש לא ידוע') : 'לא ידוע'
    }));
    cloudDebugLog(`נטענו ${result.length} גרסאות עבור דוח ${reportId}`);
    return result;
  }catch(err){
    cloudDebugLog('שגיאה בטעינת היסטוריית גרסאות (חריגה)', err.message);
    return [];
  }
}

// טוען את התוכן המלא (report_data) של גרסה ספציפית, לצפייה
async function loadReportVersionData(reportId, versionNumber){
  if(!supabaseClient) return null;
  try{
    const { data, error } = await supabaseClient
      .from('report_versions')
      .select('*')
      .eq('report_id', reportId)
      .eq('version_number', versionNumber)
      .single();
    if(error){ cloudDebugLog('שגיאה בטעינת גרסה', error.message); return null; }
    return data;
  }catch(err){
    cloudDebugLog('שגיאה בטעינת גרסה (חריגה)', err.message);
    return null;
  }
}

// משחזר גרסה קודמת: טוען את תוכנה, מעדכן את הדוח הראשי אליו, ויוצר גרסה *חדשה* שמכילה
// אותו תוכן — לא מוחק אף גרסה קיימת, ההיסטוריה המלאה נשארת (בדיוק כמו שהתבקש).
async function restoreReportVersionAsNew(reportId, versionNumber){
  const versionData = await loadReportVersionData(reportId, versionNumber);
  if(!versionData){ showToast('שגיאה בטעינת הגרסה לשחזור'); return false; }

  try{
    const { data, error } = await supabaseClient
      .from('reports')
      .update({ report_data: versionData.report_data })
      .eq('id', reportId)
      .select()
      .single();
    if(error) throw error;
    const restoredUpdatedAt = data.updated_at;

    // יוצרים רשומת גרסה חדשה עם תוכן הגרסה המשוחזרת בדיוק (לא state הנוכחי) —
    // ההיסטוריה הקיימת נשארת שלמה, זו רק תוספת חדשה בסוף הרצף.
    const { data: existing } = await supabaseClient
      .from('report_versions')
      .select('version_number')
      .eq('report_id', reportId)
      .order('version_number', { ascending: false })
      .limit(1);
    const nextVersion = (existing && existing.length ? existing[0].version_number : 0) + 1;
    await supabaseClient.from('report_versions').insert({
      report_id: reportId,
      version_number: nextVersion,
      report_data: versionData.report_data,
      created_by: cloudCurrentUser ? cloudCurrentUser.id : null
    });

    // טוען את התוכן המשוחזר גם לתוך הטופס הפעיל, כדי שהמשתמש יראה אותו מיד
    state = mergeDefaults(newState(), versionData.report_data);
    state.settings.cloudReportId = reportId;
    markLoadedFromCloud(restoredUpdatedAt);
    state.settings.cloudReportBaseline = { project: state.meta.project, address: state.meta.address, description: state.meta.description };
    openSections = new Set(["meta"]); alreadySeededOpenCards.clear(); // איפוס יחד עם openSections, כדי שכרטיסים "פתוחים כברירת מחדל" יחזרו לפתוחים בדוח/פרק החדש
    openSubheads = new Set();
    saveLocalOnly();
    cloudDebugLog(`שוחזרה גרסה ${versionNumber} לדוח ${reportId}, נוצרה כגרסה ${nextVersion}`);
    showToast(`גרסה ${versionNumber} שוחזרה בהצלחה (כגרסה חדשה מס' ${nextVersion})`);
    render();
    return true;
  }catch(err){
    cloudDebugLog('שגיאה בשחזור גרסה (חריגה)', err.message);
    showToast('שגיאה בשחזור גרסה: ' + (err && err.message ? err.message : String(err)));
    return false;
  }
}

/* ---------- Offline queue & auto-sync ---------- */

function queueOfflineSave(){
  cloudSyncStatus = 'offline';
  const reportId = state.settings.cloudReportId || null; // null = not yet created in the cloud at all
  cloudPendingQueue = cloudPendingQueue.filter(q => q.reportId !== reportId);
  cloudPendingQueue.push({ reportId, timestamp: Date.now() });
  // שמירה מקומית ישירה (לא scheduleSave) — מונעת הפעלה חוזרת של טיימר ה-Cloud Auto-Save,
  // שהייתה גורמת ללולאת ניסיונות-שמירה-לענן חוזרת כל 5 שניות כל עוד אין חיבור.
  saveLocalOnly();
  setSavePill('ללא רשת – שומר מקומית', false, true);
  updateCompactStatusBarOnly();
  showToast('אין חיבור – נשמר מקומית בלבד');
}

async function syncPendingReports(){
  if(navigator.onLine === false) return; // still offline, nothing to do yet
  if(!cloudPendingQueue.length) return;
  if(!supabaseClient){ await initSupabase(); }
  if(!supabaseClient || !cloudCurrentUser) return; // can't sync without a live, authenticated connection

  const stillPending = [];
  for(const item of cloudPendingQueue){
    // Only auto-sync the report currently open in the editor — for any other queued entry,
    // silently pushing a possibly-stale snapshot could overwrite newer cloud data without the
    // user ever seeing the same conflict-resolution choice they'd get interactively. Those are
    // left pending for the user to reopen and save manually.
    if((item.reportId || null) === (state.settings.cloudReportId || null)){
      const result = await saveReportToCloud();
      if(result !== true) stillPending.push(item);
    } else {
      stillPending.push(item);
    }
  }
  cloudPendingQueue = stillPending;
  if(!cloudPendingQueue.length) showToast('החיבור חזר — כל הדוחות הממתינים סונכרנו לענן');
  updateCompactStatusBarOnly();
}

window.addEventListener('online', ()=>{
  setSavePill('מחובר לרשת', true, false);
  syncPendingReports().then(()=>verifyOpenReportFreshness('online')); // Phase 2C
});
window.addEventListener('offline', ()=>{
  cloudSyncStatus = 'offline';
  setSavePill('ללא רשת – שומר מקומית', false, true);
  updateCompactStatusBarOnly();
  showToast('החיבור לאינטרנט נותק — השמירה תמשיך מקומית');
});

/* ---------- Supabase Storage — תמונות וקבצים מצורפים ----------
   ה-bucket 'report-files' פרטי. הצגת קובץ תמיד דרך Signed URL זמני שנוצר בעת הצורך,
   לא URL קבוע/ציבורי. הנתיב בתוך ה-bucket: <reportId>/<uuid>-<filename> — מבודד לפי דוח. */

const REPORT_FILES_BUCKET = 'report-files';

function dataUrlToBlob(dataUrl){
  const [header, base64] = dataUrl.split(',');
  const mimeMatch = header.match(/data:(.*?);base64/);
  const mime = mimeMatch ? mimeMatch[1] : 'application/octet-stream';
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for(let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}

// מעלה קובץ (מ-dataURL, כמו שהאפליקציה כבר מייצרת מתמונות מצולמות) ל-bucket הפרטי.
// מחזיר { path } בהצלחה, או null בכישלון (ומציג showToast עם הסיבה).
async function uploadFileToCloudStorage(reportId, dataUrl, originalFileName){
  if(!supabaseClient){ cloudDebugLog('אין חיבור לענן — לא ניתן להעלות קובץ'); return null; }
  if(!reportId){ showToast('יש לשמור את הדוח לענן קודם, לפני העלאת קבצים'); return null; }
  try{
    const blob = dataUrlToBlob(dataUrl);
    const safeName = (originalFileName || 'file').replace(/[^\w.\-]/g, '_');
    const path = `${reportId}/${crypto.randomUUID()}-${safeName}`;
    const { data, error } = await supabaseClient.storage
      .from(REPORT_FILES_BUCKET)
      .upload(path, blob, { contentType: blob.type, upsert: false });
    if(error){ cloudDebugLog('שגיאה בהעלאת קובץ', error.message); showToast('שגיאה בהעלאת קובץ: ' + error.message); return null; }
    cloudDebugLog('קובץ הועלה בהצלחה', data.path);
    return { path: data.path };
  }catch(err){
    cloudDebugLog('שגיאה בהעלאת קובץ (חריגה)', err.message);
    showToast('שגיאה בהעלאת קובץ: ' + (err && err.message ? err.message : String(err)));
    return null;
  }
}

// מטמון קצר-מועד של URL חתומים כדי לא ליצור URL חדש בכל render() (הם תקפים לשעה)
const signedUrlCache = {}; // { path: { url, expiresAt } }

async function getCloudFileSignedUrl(storagePath){
  if(!supabaseClient || !storagePath) return null;
  const cached = signedUrlCache[storagePath];
  if(cached && cached.expiresAt > Date.now()) return cached.url;
  try{
    const { data, error } = await supabaseClient.storage
      .from(REPORT_FILES_BUCKET)
      .createSignedUrl(storagePath, 3600);
    if(error){ cloudDebugLog('שגיאה ביצירת קישור זמני', error.message); return null; }
    signedUrlCache[storagePath] = { url: data.signedUrl, expiresAt: Date.now() + 55*60*1000 };
    cloudDebugLog('קישור זמני נוצר בהצלחה', storagePath);
    return data.signedUrl;
  }catch(err){
    cloudDebugLog('שגיאה ביצירת קישור זמני (חריגה)', err.message);
    return null;
  }
}

// אוסף רקורסיבית את כל ה-cloudPath הקיימים בכל state (אותו דפוס מעבר גנרי בדיוק כמו
// sanitizeStateForLocalSave — לא רשימה קשיחה של מיקומי תמונות שעלולה להחמיץ מיקום חדש
// שיתווסף בעתיד), וממתינה בפועל (Promise.all) שלכולם יהיה URL חתום תקף במטמון (דרך
// getCloudFileSignedUrl הקיים, שכבר בודק cache ומביא רק את החסר) — לפני שמפיקים PDF/תצוגה
// מקדימה. עד עכשיו לא היה מנגנון כזה עבור תמונות דוח (ensureSettingsImagesAreBase64 מטפל
// רק בלוגו/חתימה) — תמונה שה-URL החתום שלה עדיין לא הגיע מהרקע (prefetchMissingSignedUrls,
// לא ממתין) הייתה עלולה להיטען כתמונה שבורה (resolvePhotoSrc מחזיר '' עד שה-cache מתמלא).
async function ensureAllPhotoSignedUrlsReady(obj){
  if(!supabaseClient) return; // אין חיבור לענן כלל — אין cloudPath שרלוונטי, מפסיק מיד
  const paths = new Set();
  (function collect(o){
    if(Array.isArray(o)){ o.forEach(collect); return; }
    if(o && typeof o === 'object'){
      if(typeof o.cloudPath === 'string' && o.cloudPath) paths.add(o.cloudPath);
      for(const k in o) collect(o[k]);
    }
  })(obj);
  await Promise.all(Array.from(paths).map(p => getCloudFileSignedUrl(p)));
}

// פותר את מקור התמונה להצגה, סינכרונית (נדרש כי render() כולו סינכרוני):
// אם יש cloudPath ויש כבר URL חתום תקף במטמון — משתמשים בו. אחרת (אין cloudPath,
// או שעדיין לא נטען URL חתום, או שהוא פג) — נופלים חזרה ל-dataUrl המקומי, כדי
// שהתמונה תמיד תוצג מיד ולעולם לא תישבר, כולל בדוחות ישנים בלי cloudPath בכלל.
function resolvePhotoSrc(photo){
  if(photo.cloudPath){
    const cached = signedUrlCache[photo.cloudPath];
    if(cached && cached.expiresAt > Date.now()) return cached.url;
  }
  return photo.dataUrl || '';
}

// רץ ברקע אחרי כל render(): מוצא את כל התמונות עם cloudPath שעדיין אין להן URL חתום
// תקף במטמון, מביא אותם, ואז מעדכן ישירות את ה-DOM (לא render() מלא) — עדכון נקודתי,
// כדי לא לאבד מיקום גלילה/פוקוס בטופס בגלל תמונה אחת שמסתנכרנת ברקע.
let signedUrlPrefetchInFlight = new Set();
function prefetchMissingSignedUrls(){
  if(!supabaseClient) return;
  document.querySelectorAll('img[data-cloudpath]').forEach(img=>{
    const path = img.getAttribute('data-cloudpath');
    if(!path || signedUrlPrefetchInFlight.has(path)) return;
    const cached = signedUrlCache[path];
    if(cached && cached.expiresAt > Date.now()) return; // כבר יש URL תקף, אין צורך לבקש שוב
    signedUrlPrefetchInFlight.add(path);
    getCloudFileSignedUrl(path).then(url=>{
      signedUrlPrefetchInFlight.delete(path);
      if(!url) return;
      // עדכון נקודתי של כל התמונות שמפנות לאותו path (אותה תמונה עלולה להופיע כמה פעמים)
      document.querySelectorAll(`img[data-cloudpath="${CSS.escape(path)}"]`).forEach(el=>{ el.src = url; });
    });
  });
}

// מחיקת קובץ מהאחסון (בהתאם להרשאות RLS על storage.objects — admin/inspector/employee בלבד)
async function deleteCloudFile(storagePath){
  if(!supabaseClient || !storagePath) return false;
  try{
    const { error } = await supabaseClient.storage.from(REPORT_FILES_BUCKET).remove([storagePath]);
    if(error){ cloudDebugLog('שגיאה במחיקת קובץ', error.message); showToast('שגיאה במחיקת קובץ: ' + error.message); return false; }
    delete signedUrlCache[storagePath];
    cloudDebugLog('קובץ נמחק בהצלחה', storagePath);
    return true;
  }catch(err){
    cloudDebugLog('שגיאה במחיקת קובץ (חריגה)', err.message);
    return false;
  }
}

