// יחידות מאושרות לטבלת בדיקת בידוד (DAR/PI/בדיקה רגילה) — משותפות לכל שיטות הבדיקה, לא
// כפילות. נבדק לפני הוספה: הרשימה הקרובה ביותר שקיימת בקוד (['kΩ','MΩ','GΩ','TΩ']) שייכת
// לטבלה שונה לגמרי (5.1 בדיקת בידוד, v2.385 נעול) ומכילה GΩ במקום Ω — לא תואמת לרשימה
// המאושרת כאן במפורש.
const INSULATION_METHOD_UNIT_OPTIONS = ["Ω","kΩ","MΩ","GΩ","TΩ"];

// ערכי סף ל-DAR (יחס R60/R15) ו-PI (יחס R10min/R1min) — הפניה כללית מקובלת בתעשייה
// (IEEE 43 להתקני סיבוב, IEEE C57.152 לשנאים — ערכי שנאי נוטים להיות נמוכים יותר מערכי מנוע).
// אלה קווים מנחים כלליים, לא תחליף לשיפוט ההנדסי של הבודק המוסמך ביחס לתקן/מפרט הספציפי החל.
const DAR_THRESHOLDS = { bad: 1.0, questionable: 1.25 }; // <1.0 לא תקין, 1.0-1.25 נדרש בדיקה נוספת, ≥1.25 תקין
const PI_THRESHOLDS = { bad: 1.0, questionable: 2.0 };   // <1.0 לא תקין, 1.0-2.0 נדרש בדיקה נוספת, ≥2.0 תקין

// תיקון טמפרטורה לבדיקת בידוד רגילה (ערך בודד, לא יחס) — כלל אצבע מתועד ומאומת במקורות
// מרובים (NETA MTS, IEEE 43, יצרני ציוד בדיקה): ההתנגדות נחצית בערך בכל 10°C עלייה בטמפרטורה.
// מתייחס ל-20°C כטמפרטורת ייחוס (מוסכמה נפוצה למתקנים כלליים לפי NETA MTS).
// זהו קירוב מקובל בשטח — לא תחליף לטבלאות מדויקות לפי סוג בידוד ספציפי כשנדרשת דיוק מרבי.
const INSULATION_REFERENCE_TEMP_C = 20;
function correctInsulationForTemperature(measuredValue, measuredTempC){
  if(isNaN(measuredValue) || isNaN(measuredTempC)) return null;
  return measuredValue * Math.pow(2, (measuredTempC - INSULATION_REFERENCE_TEMP_C) / 10);
}

function classifyInsulationRatio(method, value){
  if(value === null || value === undefined || isNaN(value)) return null;
  const t = method === 'pi' ? PI_THRESHOLDS : DAR_THRESHOLDS;
  if(value < t.bad) return { label: 'לא תקין', cls: 'ins-bad' };
  if(value < t.questionable) return { label: 'נדרש בדיקה נוספת', cls: 'ins-questionable' };
  return { label: 'תקין', cls: 'ins-good' };
}

