function makeF3Panel(){ return { name:'', location:'', amperage:'', detection:'', disconnect:'', extinguish:'' }; }
function makeFireForm3(){
  return { fireFileNumber:'', facilityName:'', businessType:'', companyId:'', city:'', street:'', houseNumber:'', zipCode:'', poBox:'',
    contactName:'', contactRole:'', contactPhone:'', contactEmail:'',
    inspectorName:'', inspectorId:'', licenseType:'', inspectorLicense:'', inspectorLicenseValidity:'', inspectionDate:'', inspectorPhone:'', reportDate:'',
    electricalSystemStatus:'', electricalSystemExplanation:'', emergencyBreakerStatus:'', emergencyBreakerLocation:'', emergencyBreakerExplanation:'',
    upsStatus:'', upsLocation:'', upsExplanation:'', panels:[ makeF3Panel() ] };
}
function isFireForm3Report(){ return getReportType() === 'FIRE_FORM3'; }
// פרטי הבודק נזכרים מהטופס הקודם (במכשיר) + ברירת מחדל מההגדרות
// v2.2.526 — פרטי הבודק נלקחים מההגדרות (מקור אחד): שם, ת"ז, סוג רישיון, מספר רישיון בודק, תוקף, טלפון וחתימה.
// ערך שהגיע מייבוא JSON משמש רק אם השדה בהגדרות ריק.
function f3Inspector(f){
  const s = state.settings; f = f || {};
  const pick = (a, b) => String(a || '').trim() || String(b || '').trim();
  // מה שבטופס קובע; שדה ריק — מההגדרות
  return { inspectorName: pick(f.inspectorName, s.engineerName), inspectorId: pick(f.inspectorId, s.inspectorIdNumber), licenseType: pick(f.licenseType, s.licenseType),
    inspectorLicense: pick(f.inspectorLicense, s.testerLicenseNo || s.engineerLicenseNo), inspectorLicenseValidity: pick(f.inspectorLicenseValidity, s.licenseValidUntil),
    inspectorPhone: pick(f.inspectorPhone, s.phone) };
}
// מילוי אוטומטי של פרטי הבודק מההגדרות (כמו בתוכנה הקודמת) — רק לשדות ריקים
function f3InspectorDefaults(){ return f3Inspector({}); }
function getFireForm3(){
  if(!state.fireForm3 || typeof state.fireForm3 !== 'object') state.fireForm3 = makeFireForm3();
  const f = state.fireForm3, d = makeFireForm3();
  Object.keys(d).forEach(k => { if(f[k] === undefined) f[k] = d[k]; });
  if(!Array.isArray(f.panels) || !f.panels.length) f.panels = [makeF3Panel()];
  { const def = f3InspectorDefaults(); Object.keys(def).forEach(k => { if(!String(f[k] || '').trim() && def[k]) f[k] = def[k]; }); }
  if(!f.reportDate) f.reportDate = new Date().toISOString().slice(0,10);
  // שם העסק / כתובת / תאריך — גם בפרטי הדוח הכלליים, כדי שהטיוטה תזוהה ברשימת הטיוטות
  state.meta.siteName = f.facilityName || state.meta.siteName; state.meta.client = f.facilityName || state.meta.client;
  state.meta.address = [f.street, f.city].filter(Boolean).join(', ') || state.meta.address; if(f.inspectionDate) state.meta.date = f.inspectionDate;
  return f;
}
function f3Remember(){ /* פרטי הבודק נשמרים בהגדרות — אין צורך בזיכרון נפרד במכשיר */ }
// ייבוא קובץ JSON שיוצא מהתוכנה הקודמת (templateType: fire_form3) — אותם שמות שדות
function f3ImportJson(obj){
  const f = getFireForm3();
  const keys = Object.keys(makeFireForm3()).filter(k => k !== 'panels');
  keys.forEach(k => { if(obj[k] !== undefined && obj[k] !== null) f[k] = String(obj[k]).trim(); });
  const n = parseInt(obj.electricalPanelsCount, 10) || Object.keys(obj).filter(k => /^panel_\d+_name$/.test(k)).length;
  if(n){
    f.panels = [];
    for(let i = 0; i < n; i++){
      f.panels.push({ name: String(obj[`panel_${i}_name`]||'').trim(), location: String(obj[`panel_${i}_facility_location`] || obj[`panel_${i}_location`] || '').trim(),
        amperage: String(obj[`panel_${i}_amperage`]||'').trim(), detection: f3Flag(obj[`panel_${i}_detection`]), disconnect: f3Flag(obj[`panel_${i}_disconnect`]), extinguish: f3Flag(obj[`panel_${i}_extinguish`]) });
    }
  }
  f.__inspectorSeeded = true;
  return f.panels.length;
}
function f3Flag(v){
  const t = String(v == null ? '' : v).trim();
  if(!t) return '';
  if(/^(לא|אין|-|–|x|✗|לא קיים|no|false)$/i.test(t)) return 'לא קיים';
  if(/^(כן|קיים|יש|v|✓|✔|yes|true)$/i.test(t)) return 'קיים';
  return '';
}
function f3Date(d){ if(!d) return ''; const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? `${parseInt(m[3],10)}.${parseInt(m[2],10)}.${m[1]}` : d; }

// ----------------------------- טופס (UI) -----------------------------
function f3Opts(field, val, options){
  return `<div class="f3-opts">${options.map(o => `<button type="button" class="f3-opt${val === o ? ' on' : ''}" data-f3opt="${field}|${escapeAttr(o)}"><span class="f3-radio"></span>${escapeHtml(o)}</button>`).join('')}</div>`;
}
function f3Txt(path, val, label, extra){ return `<div class="field"><label>${label}</label><input type="text" dir="auto" data-textpath="fireForm3.${path}" value="${escapeAttr(val||'')}" ${extra||''}></div>`; }
function f3Date_(path, val, label){ return `<div class="field"><label>${label}</label><input type="date" data-textpath="fireForm3.${path}" value="${escapeAttr(val||'')}"></div>`; }
function f3FlagSel(path, val, label){
  const cls = val === 'קיים' ? 'f3-yes' : (val === 'לא קיים' ? 'f3-no' : 'f3-empty');
  return `<select class="f3-sel ${cls}" data-textpath="${path}" aria-label="${label}"><option value="">${label}</option><option value="קיים" ${val==='קיים'?'selected':''}>✔ קיים</option><option value="לא קיים" ${val==='לא קיים'?'selected':''}>✗ לא קיים</option></select>`;
}
function renderFireForm3Cards(){
  const f = getFireForm3();
  const card = (key, num, title, body) => `<section class="card" data-key="${key}"><div class="card-head" data-toggle="${key}"><h2><span class="num">${num}</span> ${title}</h2><span class="chev">▾</span></div><div class="card-body">${body}</div></section>`;
  const lic = state.settings.inspectorLicense;
  const head = `<div class="f3-import">
      <label class="add-btn" style="display:inline-flex; width:auto; cursor:pointer;">📥 ייבוא טופס 3 מקובץ JSON<input type="file" accept=".json,application/json" data-f3json="1" style="display:none;"></label>
      <span class="sp-grp-hint">קובץ שיוצא מהתוכנה הקודמת — כל השדות והלוחות נטענים אוטומטית.</span></div>
    ${lic ? '' : `<p class="sp-grp-hint" style="color:var(--bad); font-weight:700;">⚠ עדיין לא הועלה צילום רישיון בודק — הגדרות ← רישיון בודק. הוא מצורף בעמוד האחרון של הטופס.</p>`}`;
  const business = head + `
    <div class="sp-sub">פרטי בית הנכס/עסק</div>
    <div class="grid2">${f3Txt('fireFileNumber', f.fireFileNumber, "מס' תיק ברשות הכבאות", 'inputmode="numeric"')}${f3Txt('facilityName', f.facilityName, 'שם העסק *')}${f3Txt('businessType', f.businessType, 'מהות העסק')}${f3Txt('companyId', f.companyId, 'ח.פ / ע.מ / ע.ר / ת"ז', 'inputmode="numeric"')}</div>
    <div class="sp-sub">כתובת הנכס/עסק</div>
    <div class="grid2">${f3Txt('city', f.city, 'יישוב')}${f3Txt('street', f.street, 'רחוב / גוש, חלקה, מגרש')}${f3Txt('houseNumber', f.houseNumber, "מס' בית")}${f3Txt('zipCode', f.zipCode, 'מיקוד', 'inputmode="numeric"')}${f3Txt('poBox', f.poBox, 'ת"ד')}</div>
    <div class="sp-sub">פרטי התקשרות איש קשר ראשי</div>
    <div class="grid2">${f3Txt('contactName', f.contactName, 'שם מלא')}${f3Txt('contactRole', f.contactRole, 'תפקיד')}${f3Txt('contactPhone', f.contactPhone, "מס' טלפון נייד", 'inputmode="tel"')}${f3Txt('contactEmail', f.contactEmail, 'כתובת דואר אלקטרוני', 'inputmode="email"')}</div>
    <div class="grid2">${f3Date_('reportDate', f.reportDate, 'תאריך הטופס')}</div>`;
  const inspector = `<div class="grid2">${f3Txt('inspectorName', f.inspectorName, 'שם מלא *')}${f3Txt('inspectorId', f.inspectorId, 'תעודת זהות *', 'inputmode="numeric"')}${f3Txt('licenseType', f.licenseType, 'סוג רישיון *')}${f3Txt('inspectorLicense', f.inspectorLicense, "מס' רישיון *", 'inputmode="numeric"')}
      ${f3Date_('inspectorLicenseValidity', f.inspectorLicenseValidity, 'בתוקף עד ליום *')}${f3Date_('inspectionDate', f.inspectionDate, 'תאריך ביצוע הבדיקה *')}</div>`;
  const elec = `<label class="f3-q">מערכת החשמל לרבות תאורת חירום ושילוט מואר *</label>${f3Opts('electricalSystemStatus', f.electricalSystemStatus, F3_ELEC_OPTIONS)}
    ${f3Txt('electricalSystemExplanation', f.electricalSystemExplanation, 'הסבר (במקרה של אי תקינות)')}`;
  const ups = `<label class="f3-q">מפסק חשמל חירום *</label>${f3Opts('emergencyBreakerStatus', f.emergencyBreakerStatus, F3_EMERG_OPTIONS)}
    <div class="grid2">${f3Txt('emergencyBreakerLocation', f.emergencyBreakerLocation, 'מיקום מפסק חירום')}${f3Txt('emergencyBreakerExplanation', f.emergencyBreakerExplanation, 'הסבר מה לא תקין (אם רלוונטי)')}</div>
    <label class="f3-q" style="margin-top:12px;">מערכת UPS *</label>${f3Opts('upsStatus', f.upsStatus, F3_UPS_OPTIONS)}
    <div class="grid2">${f3Txt('upsLocation', f.upsLocation, 'מיקום מערכת UPS')}${f3Txt('upsExplanation', f.upsExplanation, 'הסבר מה לא תקין (אם רלוונטי)')}</div>`;
  const panels = `
    <div class="rd-bulk">${F3_PANEL_FLAGS.map(([k,l]) => `<span class="sp-colset-wrap">${l}: <select class="f3-colset" data-f3colset="${k}"><option value="">לכל הלוחות ▾</option><option value="קיים">✔ כולם קיים</option><option value="לא קיים">✗ כולם לא קיים</option></select></span>`).join('')}<span>${f.panels.length} לוחות</span></div>
    ${f.panels.map((p, i) => { const b = `fireForm3.panels.${i}`; return `<div class="f3-panel">
      <div class="f3-panel-head"><span class="sp-row-num">${i+1}</span><b>לוח חשמל ${i+1}</b><span style="flex:1"></span>
        <button type="button" class="del-panel-btn" data-f3move="${i}|-1" ${i===0?'disabled':''} title="הזז למעלה">↑</button><button type="button" class="del-panel-btn" data-f3move="${i}|1" ${i===f.panels.length-1?'disabled':''} title="הזז למטה">↓</button>
        <button type="button" class="del-panel-btn" data-delrow="fireForm3.panels|${i}">🗑 הסר</button></div>
      <div class="f3-panel-grid">
        <input type="text" dir="auto" data-textpath="${b}.name" value="${escapeAttr(p.name||'')}" placeholder="שם לוח">
        <input type="text" dir="auto" data-textpath="${b}.location" value="${escapeAttr(p.location||'')}" placeholder="מיקום">
        <input type="text" dir="ltr" list="f3AmpList" data-textpath="${b}.amperage" value="${escapeAttr(p.amperage||'')}" placeholder="גודל אמפר (לדוגמה 3X40A)">
      </div>
      <div class="f3-panel-flags">${F3_PANEL_FLAGS.map(([k,l]) => f3FlagSel(`${b}.${k}`, p[k], l)).join('')}</div>
    </div>`; }).join('')}
    <datalist id="f3AmpList">${F3_AMP_OPTIONS.map(v=>`<option value="${v}">`).join('')}</datalist>
    <button type="button" class="add-panel-card" data-addrow="fireForm3.panels|${escapeAttr(JSON.stringify(makeF3Panel()))}">+ הוסף לוח חשמל</button>
    <details class="sp-gen"><summary>📥 ייבוא לוחות — Excel / CSV / Word / PDF / הדבקה</summary>
      <p style="font-size:12.5px; color:var(--text-dim); margin:0 0 8px;">טבלה עם עמודות: שם הלוח, מיקום, גודל חיבור / אמפר, גילוי, ניתוק, כיבוי. הלוחות שיזוהו יתווספו לרשימה (או יחליפו אותה).</p>
      <label class="add-btn" style="display:inline-flex; width:auto; cursor:pointer;">📄 בחר קובץ<input type="file" accept=".xlsx,.xls,.csv,.docx,.pdf,.txt,image/*" data-f3panelsfile="1" style="display:none;"></label>
      <div class="field"><label>או הדבק טבלה</label><textarea id="f3PanelsPaste" rows="3" placeholder="שם הלוח	מיקום	גודל חיבור	גילוי	ניתוק	כיבוי"></textarea></div>
      <div class="sp-gen-actions"><button type="button" class="add-btn" data-f3panelspaste="add">הוסף לרשימה</button><button type="button" class="add-btn" data-f3panelspaste="replace">החלף את הרשימה</button></div>
    </details>`;
  return card('f3-business', '02', 'פרטי בית העסק / הנכס', business)
    + card('f3-inspector', '03', 'פרטי מבצע הבדיקה', inspector)
    + card('f3-elec', '04', '1. בדיקת מערכת החשמל ותאורת החירום', elec)
    + card('f3-ups', '05', '2. בדיקת מפסק חשמל חירום ומערכת UPS', ups)
    + card('f3-panels', '06', '3. פירוט לוחות החשמל בנכס/עסק', panels)
    + card('f3-license', '07', 'צילום רישיון בודק (עמוד אחרון)', lic ? `<img src="${lic}" alt="רישיון בודק" style="max-width:100%; max-height:320px; object-fit:contain; border:1px solid var(--line); border-radius:8px; background:#fff;"><p class="sp-grp-hint">הרישיון נלקח מההגדרות. להחלפה: הגדרות ← רישיון בודק.</p>` : `<p class="sp-grp-hint">לא הועלה רישיון בודק. הגדרות ← רישיון בודק.</p>`);
}

// ----------------------------- מסמך PDF (עצמאי, 1:1) -----------------------------
const F3_CHECK_ON = '<svg width="15" height="15" viewBox="0 0 16 16" style="vertical-align:-2px;"><rect x="1" y="1" width="14" height="14" fill="#fff" stroke="#222" stroke-width="1.4"/><path d="M3.5 8.5 L6.5 11.5 L13 3.5" fill="none" stroke="#111" stroke-width="2.2"/></svg>';
const F3_CHECK_OFF = '<svg width="15" height="15" viewBox="0 0 16 16" style="vertical-align:-2px;"><rect x="1" y="1" width="14" height="14" fill="#fff" stroke="#222" stroke-width="1.4"/></svg>';
function f3Header(){
  return `<table class="f3-hdr"><tr><td class="f3-logo"><img src="${F3_LOGO_RIGHT}" alt=""></td><td class="f3-hdr-title">כבאות והצלה לישראל<br>אגף הגנה מאש</td><td class="f3-logo"><img src="${F3_LOGO_LEFT}" alt=""></td></tr></table>`;
}
function f3Footer(n){
  return `<div class="f3-foot">טופס זה הורד מאתר האינטרנט של הרשות הארצית לכבאות והצלה.<br>אין לערוך שינויים בטופס זה (טופס מס' 3 נכסים/רישוי- סה"כ 2 עמודים)<br><b>מוקד שירות ומידע כבאות והצלה לישראל</b><br>מענה טלפוני בימים א עד ה' בשעות 8:00 עד 17:00 בטלפון: <span dir="ltr">0772704121 *4964</span> דוא"ל <span dir="ltr">tservice@102.gov.il</span></div><div class="f3-pnum">${n}</div>`;
}
function f3Page(inner, n){ return `<div class="f3-page">${f3Header()}<div class="f3-body">${inner}</div>${f3Footer(n)}</div>`; }
function buildFireForm3Pages(){
  const f0 = getFireForm3(), s = state.settings;
  const f = Object.assign({}, f0, f3Inspector(f0)); // פרטי הבודק מההגדרות
  const v = x => escapeHtml(x || '');
  const ck = on => on ? F3_CHECK_ON : F3_CHECK_OFF;
  const line = '<span class="f3-blank"></span>';
  const p1 = `
    <div class="f3-badge">רישוי עסקים/נכסים</div>
    <div class="f3-title">טופס מס' 3<br>אישור תקינות מערכת חשמל ותאורת חירום</div>
    <div class="f3-sub">(בהתאם לדרישה מס' 30.03.03 במערכת "שלהבת" של הרשות הארצית לכבאות והצלה)</div>
    <div class="f3-date">תאריך: ${v(f3Date(f.reportDate))}</div>
    <div class="f3-to"><u><b>לכבוד:</b></u></div>
    <div class="f3-to2">מוקד שירות ומידע עבור כבאות והצלה לישראל - מדור הגנה מאש באמצעות דוא"ל <span dir="ltr">tservice@102.gov.il</span></div>
    <table class="f3-t"><tr><th colspan="4" class="f3-cap">פרטי בית הנכס/עסק:</th></tr>
      <tr><th>מס' תיק ברשות הכבאות</th><th>שם העסק</th><th>מהות העסק</th><th>ח.פ / ע.מ / ע.ר / ת"ז</th></tr>
      <tr><td><b>${v(f.fireFileNumber)}</b></td><td><b>${v(f.facilityName)}</b></td><td><b>${v(f.businessType)}</b></td><td><b>${v(f.companyId)}</b></td></tr></table>
    <table class="f3-t"><tr><th colspan="5" class="f3-cap">כתובת הנכס/עסק:</th></tr>
      <tr><th>יישוב</th><th>רחוב / גוש, חלקה, מגרש</th><th>מס' בית</th><th>מיקוד</th><th>ת"ד</th></tr>
      <tr><td><b>${v(f.city)}</b></td><td><b>${v(f.street)}</b></td><td><b>${v(f.houseNumber)}</b></td><td><b>${v(f.zipCode)}</b></td><td><b>${v(f.poBox)}</b></td></tr></table>
    <table class="f3-t"><tr><th colspan="4" class="f3-cap">פרטי התקשרות איש קשר ראשי:</th></tr>
      <tr><th>שם מלא</th><th>תפקיד</th><th>מס' טלפון נייד</th><th>כתובת דואר אלקטרוני</th></tr>
      <tr><td><b>${v(f.contactName)}</b></td><td><b>${v(f.contactRole)}</b></td><td><b dir="ltr">${v(f.contactPhone)}</b></td><td><b dir="ltr">${v(f.contactEmail)}</b></td></tr></table>
    <p class="f3-p">אני הח"מ (שם מלא): <b>${v(f.inspectorName)}</b> ת"ז: <b>${v(f.inspectorId)}</b> בעל/ת רישיון לעבודות חשמל לפי חוק החשמל, התשי"ד-1954 ותקנות החשמל (רישיונות), התש"ם-1985;</p>
    <p class="f3-p">רישיון מסוג: <b>${v(f.licenseType)}</b> מס' רישיון: <b>${v(f.inspectorLicense)}</b> <b>בתוקף עד ליום: ${v(f3Date(f.inspectorLicenseValidity))} (יש לצרף צילום רישיון)</b>,</p>
    <p class="f3-p">הרשאי/ת בהתאם לסוג רישיוני לתת אישור זה, מאשר/ת בזאת, כדלקמן:</p>
    <p class="f3-p f3-num"><b>1.</b> בתאריך: <b>${v(f3Date(f.inspectionDate))}</b> ביקרתי בנכס/עסק המפורט לעיל ובדקתי את מערכת החשמל המותקנת בנכס/עסק, לרבות תאורת החירום, שילוט מואר ומפסק חשמל חירום ומבדיקתי עולה כי [יש לסמן במקום המתאים]:</p>
    <div class="f3-ck">${ck(f.electricalSystemStatus === F3_ELEC_OPTIONS[0])} מערכת החשמל לרבות תאורת חירום ושילוט מואר נמצאו <b>תקינים</b> בהתאם לחוק החשמל, התשי"ד-1954 והתקנות על-פיו.</div>
    <div class="f3-ck">${ck(f.electricalSystemStatus === F3_ELEC_OPTIONS[1])} מערכת החשמל או תאורת החירום ושילוט מואר נמצאו <b>לא תקינים</b> בהתאם לחוק החשמל, התשי"ד-1954 והתקנות על-פיו.${f.electricalSystemStatus === F3_ELEC_OPTIONS[1] && f.electricalSystemExplanation ? ` <b>פירוט:</b> ${v(f.electricalSystemExplanation)}` : ''}</div>
    <p class="f3-p f3-num"><b>2.</b> בדקתי קיומו של מפסק חשמל חירום ומבדיקתי עולה כי [יש לסמן במקום המתאים]:</p>
    <div class="f3-ck">${ck(f.emergencyBreakerStatus === F3_EMERG_OPTIONS[0])} בנכס/עסק המפורט לעיל קיים מפסק חשמל חירום <b>תקין</b> אשר מיקומו: ${f.emergencyBreakerStatus === F3_EMERG_OPTIONS[0] ? v(f.emergencyBreakerLocation) || line : line}</div>
    <div class="f3-ck">${ck(f.emergencyBreakerStatus === F3_EMERG_OPTIONS[1])} בנכס/עסק המפורט לעיל קיים מפסק חשמל חירום <b>לא תקין</b> אשר מיקומו: ${f.emergencyBreakerStatus === F3_EMERG_OPTIONS[1] ? (v(f.emergencyBreakerLocation) || line) + (f.emergencyBreakerExplanation ? ` (${v(f.emergencyBreakerExplanation)})` : '') : line}</div>
    <div class="f3-ck">${ck(f.emergencyBreakerStatus === F3_EMERG_OPTIONS[2])} בנכס/עסק <b>לא קיים</b> מפסק חשמל חירום.</div>
    <div class="f3-ck">${ck(f.upsStatus === F3_UPS_OPTIONS[0])} בנכס/עסק המפורט לעיל קיים מפסק UPS <b>תקין</b> אשר מיקומו: ${f.upsStatus === F3_UPS_OPTIONS[0] ? v(f.upsLocation) || line : line}</div>
    <div class="f3-ck">${ck(f.upsStatus === F3_UPS_OPTIONS[1])} בנכס/עסק המפורט לעיל קיים מפסק UPS <b>לא תקין</b> אשר מיקומו: ${f.upsStatus === F3_UPS_OPTIONS[1] ? (v(f.upsLocation) || line) + (f.upsExplanation ? ` (${v(f.upsExplanation)})` : '') : line}</div>
    <div class="f3-ck">${ck(f.upsStatus === F3_UPS_OPTIONS[2])} בנכס/עסק <b>לא קיים</b> מפסק UPS</div>`;
  const pages = [p1];
  const panels = f.panels.filter(p => p.name || p.location || p.amperage || p.detection || p.disconnect || p.extinguish);
  const rows = panels.length ? panels : [makeF3Panel()];
  const per = 20;
  const mark = val => val === 'קיים' ? '<span class="f3-v">✓</span>' : (val === 'לא קיים' ? '<span class="f3-x">✗</span>' : '');
  const sig = `<div class="f3-sig">${s.signature ? `<img src="${s.signature}" alt="חתימה">` : '<span class="f3-blank" style="width:140px;"></span>'}<span>טלפון: <b dir="ltr">${v(f.inspectorPhone)}</b></span></div>`;
  for(let i = 0; i < rows.length; i += per){
    const chunk = rows.slice(i, i + per), first = i === 0, last = i + per >= rows.length;
    pages.push(`
      <div class="f3-p2head">עמוד 2 של טופס מס' 3 - אישור תקינות מערכת חשמל ותאורת חירום<br>מס' תיק כיבוי (בהתאמה ובהמשך לעמוד 1 של טופס זה) ${v(f.fireFileNumber)}</div>
      ${first ? '<p class="f3-p f3-num"><b>3.</b> להלן פירוט ביחס ללוחות החשמל בנכס/עסק המפורט לעיל:</p>' : ''}
      <table class="f3-pt">
        <tr><th rowspan="2" class="f3-pt-num">מספר לוח החשמל</th><th rowspan="2" class="f3-pt-name">שם הלוח</th><th rowspan="2" class="f3-pt-loc">מיקום</th><th rowspan="2" class="f3-pt-amp">גודל האמפר</th>
          <th colspan="3" class="f3-pt-grp"><b>יש לסמן ✓ אם קיים או לסמן X אם לא קיים*</b><br><span>*אין בסימון בעמודות אלו כדי לאשר את תקינות המערכות או כדי להעיד על חובת התקנתן</span></th></tr>
        <tr><th>ניתוק</th><th>גילוי</th><th>כיבוי</th></tr>
        ${chunk.map((p, k) => `<tr><td class="f3-pt-num"><b>${i + k + 1}</b></td><td>${v(p.name)}</td><td>${v(p.location)}</td><td dir="ltr" style="text-align:center;">${v(p.amperage)}</td><td class="f3-m">${mark(p.disconnect)}</td><td class="f3-m">${mark(p.detection)}</td><td class="f3-m">${mark(p.extinguish)}</td></tr>`).join('')}
      </table>
      ${last ? sig : ''}`);
  }
  if(s.inspectorLicense){
    pages.push(`
      <div class="f3-p2head">עמוד רישיון בודק של טופס מס' 3 - אישור תקינות מערכת חשמל ותאורת חירום<br>מס' תיק כיבוי (בהתאמה ובהמשך לעמוד 1 של טופס זה) ${v(f.fireFileNumber)}</div>
      <div class="f3-lic-title">צילום רישיון בודק חשמל</div>
      <div class="f3-lic-meta"><b>שם הבודק:</b> ${v(f.inspectorName)}<br><b>מספר רישיון:</b> ${v(f.inspectorLicense)}<br><b>סוג רישיון:</b> ${v(f.licenseType)}</div>
      <div class="f3-lic-img"><img src="${s.inspectorLicense}" alt="רישיון בודק"></div>`);
  }
  return pages;
}
const F3_CSS = `
  @page{ size:A4; margin:0; }
  *{ box-sizing:border-box; }
  html,body{ margin:0; padding:0; background:#fff; color:#1d2633; font-family:Arial, "Noto Sans Hebrew", Tahoma, sans-serif; direction:rtl; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .f3-page{ width:210mm; height:297mm; padding:9mm 24mm 0; position:relative; page-break-after:always; break-after:page; overflow:hidden; }
  .f3-page:last-child{ page-break-after:auto; break-after:auto; }
  .f3-hdr{ width:100%; border-collapse:collapse; border:1.4px solid #222; margin-top:3mm; }
  .f3-hdr td{ border:1.4px solid #222; height:19mm; text-align:center; vertical-align:middle; }
  .f3-logo{ width:23mm; } .f3-logo img{ max-width:15mm; max-height:15mm; }
  .f3-hdr-title{ font-size:13.2pt; font-weight:800; line-height:1.45; color:#2b3550; }
  .f3-body{ padding-top:5mm; font-size:8.6pt; }
  .f3-badge{ width:36mm; margin:0 auto 3.5mm; border:1.2px solid #333; background:#e6e6e6; text-align:center; font-weight:800; font-size:8.4pt; padding:1.5mm 0; }
  .f3-title{ text-align:center; font-weight:800; text-decoration:underline; font-size:9.2pt; line-height:1.55; }
  .f3-sub{ text-align:center; font-size:7.6pt; margin:1.2mm 0 5mm; }
  .f3-date{ font-size:8.7pt; margin-bottom:3.5mm; }
  .f3-to{ font-size:8.7pt; margin-bottom:1.2mm; } .f3-to2{ font-size:8.5pt; margin-bottom:5mm; }
  .f3-t{ width:100%; border-collapse:collapse; border:1.4px solid #222; margin-bottom:4.2mm; }
  .f3-t th, .f3-t td{ border:1.1px solid #222; padding:1.3mm 1.6mm; text-align:center; font-size:8.3pt; height:6.4mm; }
  .f3-t th{ background:#fff; font-weight:800; }
  .f3-t th.f3-cap{ background:#ececec; text-align:right; font-weight:800; }
  .f3-p{ margin:0 0 1.9mm; line-height:1.55; font-size:8.7pt; }
  .f3-num{ margin-top:2.6mm; }
  .f3-ck{ margin:0 2.5mm 1.8mm 0; line-height:1.5; font-size:8.5pt; }
  .f3-ck svg{ width:13px; height:13px; }
  .f3-blank{ display:inline-block; width:30mm; border-bottom:1px solid #333; height:2.6mm; vertical-align:baseline; }
  .f3-foot{ position:absolute; bottom:13mm; left:24mm; right:24mm; text-align:center; font-size:7pt; line-height:1.8; color:#333; }
  .f3-pnum{ position:absolute; bottom:5mm; left:0; right:0; text-align:center; font-size:9pt; font-weight:700; }
  .f3-p2head{ text-align:center; font-size:8.5pt; line-height:1.75; margin:1.5mm 0 3.5mm; }
  .f3-pt{ width:100%; border-collapse:collapse; border:1.4px solid #222; table-layout:fixed; }
  .f3-pt th, .f3-pt td{ border:1.1px solid #222; padding:0.9mm 1.3mm; font-size:7.5pt; height:6.1mm; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
  .f3-pt th{ white-space:normal; }
  .f3-pt th{ background:#e2effa; font-weight:800; text-align:right; vertical-align:top; }
  .f3-pt-num{ width:13mm; text-align:center; } .f3-pt-name{ width:30mm; } .f3-pt-loc{ width:30mm; } .f3-pt-amp{ width:14mm; }
  .f3-pt-grp{ font-size:7.6pt !important; } .f3-pt-grp span{ font-weight:400; font-size:5.8pt; }
  .f3-pt td.f3-pt-num{ text-align:right; }
  .f3-pt td.f3-m{ text-align:left; font-size:13pt; padding-left:2.5mm; line-height:1; } .f3-v{ color:#1a1f26; font-weight:800; } .f3-x{ color:#222; font-style:italic; font-size:10pt; }
  .f3-sig{ display:flex; align-items:center; gap:14mm; margin-top:7mm; font-size:8pt; flex-direction:row-reverse; justify-content:flex-end; }
  .f3-sig img{ max-height:15mm; max-width:32mm; }
  .f3-lic-title{ text-align:center; font-weight:800; text-decoration:underline; font-size:9.5pt; margin:4mm 0 3.5mm; }
  .f3-lic-meta{ text-align:center; font-size:8.4pt; line-height:2.1; margin-bottom:5mm; }
  .f3-lic-img{ text-align:center; } .f3-lic-img img{ width:118mm; max-height:140mm; object-fit:contain; border:2.4px solid #222; }
  @media screen{ body{ background:#7a8590; } .f3-page{ background:#fff; margin:10px auto; box-shadow:0 4px 18px rgba(0,0,0,.35); } }
`;
function buildFireForm3Doc(filename){
  const pages = buildFireForm3Pages();
  return `<!DOCTYPE html><html lang="he" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(filename || 'טופס 3')}</title><style>${F3_CSS}</style></head><body>${pages.map((p, i) => f3Page(p, i + 1)).join('')}</body></html>`;
}
// לדוח משולב (פרקים): אותו תוכן כבלוקים רגילים
function buildFireForm3Blocks(){
  return buildFireForm3Pages().map((p, i) => ({ level:1, sectionKey:'f3-page-' + i, title: i === 0 ? 'טופס 3' : 'טופס 3 — עמוד ' + (i+1), pageBreak: i > 0, html: `<style>${F3_CSS.replace(/@page\{[^}]*\}/, '').replace(/\.f3-page\{[^}]*\}/, '')}</style>${f3Header()}<div class="f3-body">${p}</div>` }));
}


