function makePvParty(){ return { name:'', phone:'', email:'', license:'' }; }
function makePvRcd(){ return { desc:'מפסק מגן (לפי סימון בסכמה)', idn:'300 mA', type:'Type A', size:'4x63A', rampPlusI:'', rampPlusT:'', rampMinusI:'', rampMinusT:'', t1x:'', t5x:'', half:'', status:'' }; }
function makePvItMonitor(){ return { desc:'', setR:'', setUnit:'kΩ', time:'', measR:'', measUnit:'kΩ', status:'' }; }
function makePvInspection(){
  const rows = (arr, extra) => arr.map(()=>Object.assign({ status:'' }, extra || {}));
  return {
    consumerName:'', contractNo:'', testType:'בדיקה תקופתית', connVoltage:'0.4 kV', connSize:'3x63A', powerKVA:'', powerKW:'', inverterCount:'', moduleCount:'', dcKWp:'',
    inverterMaker:'', inverterModel:'', moduleMaker:'', moduleModel:'', installationType:'',
    parties: { owner: makePvParty(), rep: makePvParty(), electrician: makePvParty(), designer: makePvParty() },
    verdict: '',
    t1: rows(PV_T1_ITEMS), t1Notes:'', t2: rows(PV_T2_ITEMS), t2Notes:'',
    t4: rows(PV_T4_ITEMS, { value:'' }), t4Notes:'',
    t5dc: rows(PV_T5DC_ITEMS, { min:'', max:'' }), t5dcLines:'', t5ac: rows(PV_T5AC_ITEMS, { min:'', max:'' }), t5acLines:'',
    t6: [ { location:'מיקום 1', rows: rows(PV_T6_ITEMS, { value:'' }) } ], t6Notes:'',
    t7: rows(PV_T7_ITEMS, { value:'' }), t7Notes:'',
    t8: rows(PV_T8_ITEMS, { value:'' }), t8Notes:'במיתקן עם מספר לוחות יש לבצע את הבדיקה בכל לוח',
    t9: [ makePvRcd() ], t9Notes:'יש להמשיך את הרשימה לפי מספר מפסקי מגן המותקנים בכל הלוחות זרם חילופין במיתקן',
    t10: [ makePvItMonitor(), makePvItMonitor() ], t10Notes:'יש להמשיך את הרשימה לפי מספר משגוחים בלוחות זרם חילופין',
    t11: rows(PV_T11_ITEMS), t11Notes:'',
    t12: PV_NOTE_PRESETS.slice(2,4).map(t=>({ text:t, response:'' })),
    t13: [1,2,3,4].map(()=>({ defect:'', date:'', sign:'' })), t13Notes:'',
    decl: { name:'', licenseType:'', licenseNo:'', date:'', signature:'' }
  };
}
function getPvInspection(){
  if(!state.pvInspection || typeof state.pvInspection !== 'object') state.pvInspection = makePvInspection();
  const d = makePvInspection(), pv = state.pvInspection;
  Object.keys(d).forEach(k=>{ if(pv[k] === undefined) pv[k] = d[k]; });
  ['owner','rep','electrician','designer'].forEach(k=>{ if(!pv.parties[k]) pv.parties[k] = makePvParty(); });
  return pv;
}

// ----------------------------- טופס (UI) -----------------------------
function pvLabel(t){
  return escapeHtml(t).replace(/[+\-]?[A-Za-z][A-Za-z0-9]*[+\-]?(?:\s*-\s*[+\-]?[A-Za-z][A-Za-z0-9]*[+\-]?)*/g, m => `<bdi dir="ltr">${m}</bdi>`);
}
function pvCard(key, num, title, body){
  return `<section class="card" data-key="${key}">
      <div class="card-head" data-toggle="${key}"><h2><span class="num">${num}</span> ${title}</h2><span class="chev">▾</span></div>
      <div class="card-body">${body}</div></section>`;
}
function pvSelect(path, val, opts, label){
  return `<div class="field">${label ? `<label>${label}</label>` : ''}<select data-textpath="${path}"><option value="">— בחר —</option>${opts.map(o=>`<option value="${escapeAttr(o)}" ${val===o?'selected':''}>${escapeHtml(o)}</option>`).join('')}${val && !opts.includes(val) ? `<option selected>${escapeHtml(val)}</option>` : ''}</select></div>`;
}
function pvText(path, val, label, ph, mode){
  return `<div class="field">${label ? `<label>${label}</label>` : ''}<input type="text" dir="auto" ${mode ? `inputmode="${mode}"` : ''} data-textpath="${path}" value="${escapeAttr(val||'')}" placeholder="${escapeAttr(ph||'')}"></div>`;
}
function pvInput(path, val, ph){ return `<input type="text" dir="auto" inputmode="decimal" data-textpath="${path}" value="${escapeAttr(val||'')}" placeholder="${escapeAttr(ph||'')}">`; }
function pvNotes(path, val, label){ return `<div class="field" style="margin-top:10px;"><label>${label || 'הערות'}</label><textarea data-textpath="${path}" rows="2">${escapeHtml(val||'')}</textarea></div>`; }
// טבלת סעיפים: מס' | סעיף | [שדות מדידה] | סטטוס (חלונית) — עם "לכל השורות ▾"
function pvChecklist(listPath, items, rows, measureCols){
  measureCols = measureCols || [];
  return `<div class="dc-table-wrap"><table class="dc-table dc-table-compact pv-table">
    <thead><tr><th style="width:38px;">מס'</th><th>הסעיף</th>${measureCols.map(c=>`<th style="width:${c.w || 110}px;">${c.label}</th>`).join('')}<th style="width:170px;"><div class="sp-colhead">סטטוס ${spColumnSet(listPath, 'status', 'לכל השורות ▾')}</div></th></tr></thead>
    <tbody>${items.map((t, i)=>`<tr><td style="text-align:center; font-weight:700;">${i+1}</td><td class="pv-item">${pvLabel(t)}</td>${measureCols.map(c=>`<td>${c.render ? c.render(`${listPath}.${i}.${c.key}`, rows[i][c.key]) : pvInput(`${listPath}.${i}.${c.key}`, rows[i][c.key], c.ph)}</td>`).join('')}<td>${spStatusSelect(`${listPath}.${i}.status`, rows[i].status)}</td></tr>`).join('')}</tbody>
  </table></div>`;
}
function renderPvInspectionCards(){
  const pv = getPvInspection(), P = 'pvInspection';
  const s = state.settings;
  let n = 1; const num = () => String(++n).padStart(2,'0');
  const general = `
    <div class="grid2">
      ${pvText(P+'.consumerName', pv.consumerName, 'שם צרכן המתקן', state.meta.siteName || state.meta.client || '')}
      ${pvText(P+'.contractNo', pv.contractNo, 'מספר חוזה / הזמנה')}
      ${pvSelect(P+'.testType', pv.testType, PV_TEST_TYPE_OPTIONS, 'סוג הבדיקה')}
      ${pvSelect(P+'.installationType', pv.installationType, PV_INSTALL_TYPE_OPTIONS, 'תיאור המתקן')}
      ${pvSelect(P+'.connVoltage', pv.connVoltage, PV_CONN_VOLTAGE_OPTIONS, 'גודל החיבור במתקן הצריכה [kV]')}
      ${pvSelect(P+'.connSize', pv.connSize, PV_CONN_SIZE_OPTIONS, 'גודל החיבור [A]')}
      ${pvSelect(P+'.powerKVA', pv.powerKVA, PV_POWER_OPTIONS.map(x=>x.replace('kW','kVA')), 'הספק מותקן [kVA]')}
      ${pvSelect(P+'.powerKW', pv.powerKW, PV_POWER_OPTIONS, 'הספק מותקן [kW]')}
      ${pvText(P+'.inverterCount', pv.inverterCount, 'מספר מהפכים', '', 'numeric')}
      ${pvText(P+'.moduleCount', pv.moduleCount, 'מספר מודולים', '', 'numeric')}
      ${pvText(P+'.dcKWp', pv.dcKWp, 'הספק מצרפי [kWp]', '', 'decimal')}
      ${pvText(P+'.inverterMaker', pv.inverterMaker, 'יצרן מהפך', 'למשל: SMA / Huawei / SolarEdge')}
      ${pvText(P+'.inverterModel', pv.inverterModel, 'דגם מהפך')}
      ${pvText(P+'.moduleMaker', pv.moduleMaker, 'יצרן מודול')}
      ${pvText(P+'.moduleModel', pv.moduleModel, 'דגם מודול')}
    </div>
    <p class="sp-grp-hint">כתובת המתקן ותאריך הבדיקה נלקחים מסעיף 01. (*) הספק מותקן — בהתאם לנתוני היצרן של המהפכים, בקילו-וולט-אמפר או בקילו-וואט.</p>`;
  const partyRow = (k, label, withLic) => `<div class="pv-party"><div class="pv-party-title">${label}</div><div class="grid2">
      ${pvText(`${P}.parties.${k}.name`, pv.parties[k].name, 'שם')}${withLic ? pvText(`${P}.parties.${k}.license`, pv.parties[k].license, "מס' רישיון", '', 'numeric') : ''}
      ${pvText(`${P}.parties.${k}.phone`, pv.parties[k].phone, 'טלפון', '', 'tel')}${pvText(`${P}.parties.${k}.email`, pv.parties[k].email, 'דוא"ל', '', 'email')}</div></div>`;
  const parties = partyRow('owner','בעל המתקן') + partyRow('rep','נציג בעל המתקן בבדיקה') + partyRow('electrician','החשמלאי המבצע', true) + partyRow('designer','המתכנן', true);
  const verdict = `
    <label class="sp-ln-toggle"><input type="radio" name="pvVerdict" data-pvverdict="approved" ${pv.verdict==='approved'?'checked':''}> א. הנני מאשר בזאת שהמתקן נבדק ונמצא כי הוא עומד בדרישות חוק החשמל ותקנותיו וכן בתנאים שנקבעו על ידי מנהל מינהל החשמל, ובהתאם לכך הנני מאשר לחברו לרשת החשמל.</label>
    <label class="sp-ln-toggle"><input type="radio" name="pvVerdict" data-pvverdict="not_approved" ${pv.verdict==='not_approved'?'checked':''}> ב. המתקן לא אושר לחיבור עד לתיקון הליקויים המפורטים בדו"ח הבדיקה.</label>
    <p class="sp-grp-hint">פרטי הבודק (שם, טלפון, סוג ומספר רישיון, חתימה) נלקחים מההגדרות: ${escapeHtml(s.engineerName || '— לא הוגדר —')}${s.engineerLicenseNo ? ' · רישיון ' + escapeHtml(s.engineerLicenseNo) : ''}.</p>`;
  const t1 = pvChecklist(P+'.t1', PV_T1_ITEMS, pv.t1) + pvNotes(P+'.t1Notes', pv.t1Notes);
  const t2 = pvChecklist(P+'.t2', PV_T2_ITEMS, pv.t2) + pvNotes(P+'.t2Notes', pv.t2Notes);
  const t3 = `<p class="sp-grp-hint">מכשירי המדידה נלקחים מהרשימה בסעיף 01 (שם, דגם, מס' סידורי ותוקף כיול — מההגדרות ← מכשירי בדיקה).</p>`;
  const t4 = pvChecklist(P+'.t4', PV_T4_ITEMS, pv.t4, [{ key:'value', label:'תוצאות המדידה [Ω]', ph:'Ω' }]) + pvNotes(P+'.t4Notes', pv.t4Notes);
  const minmax = [{ key:'min', label:'min [MΩ]', w:90 }, { key:'max', label:'max [MΩ]', w:90 }];
  const t5 = `<div class="sp-sub">א. בדיקת התנגדות הבידוד בצד הזרם הישר (DC)</div>${pvChecklist(P+'.t5dc', PV_T5DC_ITEMS, pv.t5dc, minmax)}
    ${pvText(P+'.t5dcLines', pv.t5dcLines, 'נבדקו ___ קוים (בטבלה רשומות תוצאות הקיצון)', '', 'numeric')}
    <div class="sp-sub" style="margin-top:14px;">ב. בדיקת התנגדות הבידוד בצד זרם החילופין (AC)</div>${pvChecklist(P+'.t5ac', PV_T5AC_ITEMS, pv.t5ac, minmax)}
    ${pvText(P+'.t5acLines', pv.t5acLines, 'נבדקו ___ קוים (בטבלה רשומות תוצאות הקיצון)', '', 'numeric')}`;
  const t6 = pv.t6.map((loc, li)=>`<div class="dc-group-block" style="margin-bottom:10px;">
      <div style="display:flex; align-items:center; gap:10px; margin-bottom:6px;">${pvText(`${P}.t6.${li}.location`, loc.location, 'מיקום בדיקה')}${pv.t6.length > 1 ? `<button type="button" class="del-panel-btn" data-delrow="${P}.t6|${li}">🗑 הסר</button>` : ''}</div>
      ${pvChecklist(`${P}.t6.${li}.rows`, PV_T6_ITEMS, loc.rows, [{ key:'value', label:'[Ω]', ph:'Ω' }])}</div>`).join('')
    + `<button type="button" class="add-btn" data-addrow="${P}.t6|${escapeAttr(JSON.stringify({ location:'מיקום ' + (pv.t6.length+1), rows: PV_T6_ITEMS.map(()=>({ value:'', status:'' })) }))}">+ הוסף מיקום בדיקה</button>` + pvNotes(P+'.t6Notes', pv.t6Notes);
  const t7 = pvChecklist(P+'.t7', PV_T7_ITEMS, pv.t7, [{ key:'value', label:'מתח [V]', w:120, render:(p,v)=>`<input type="text" inputmode="decimal" list="pvVoltList" data-textpath="${p}" value="${escapeAttr(v||'')}" placeholder="V">` }]) + `<datalist id="pvVoltList">${PV_T7_VOLTAGE_OPTIONS.map(v=>`<option value="${v}">`).join('')}</datalist>` + pvNotes(P+'.t7Notes', pv.t7Notes);
  const t8 = pvChecklist(P+'.t8', PV_T8_ITEMS, pv.t8, [{ key:'value', label:'תוצאות המדידה [Ω]', ph:'Ω' }]) + pvNotes(P+'.t8Notes', pv.t8Notes);
  const t9 = pv.t9.map((r, ri)=>{ const b = `${P}.t9.${ri}`;
    return `<div class="sp-row-card"><div class="sp-row-head"><span class="sp-row-num">${ri+1}</span><span class="sp-row-title">מפסק מגן #${ri+1}${r.desc ? ' — ' + escapeHtml(r.desc) : ''}</span><span style="flex:1"></span>
        <button type="button" class="del-panel-btn" data-duprow="${P}.t9|${ri}">⧉ שכפל</button>${pv.t9.length > 1 ? `<button type="button" class="del-panel-btn" data-delrow="${P}.t9|${ri}">✕</button>` : ''}</div>
      <div class="sp-row-grid">
        <div class="field sp-span2"><label>תיאור מפסק</label><input type="text" data-textpath="${b}.desc" value="${escapeAttr(r.desc||'')}"></div>
        ${pvSelect(b+'.idn', r.idn, PV_RCD_IDN_OPTIONS, 'זרם הפעלה נקוב (IΔN)')}${pvSelect(b+'.type', r.type, PV_RCD_TYPE_OPTIONS, 'סוג מפסק')}${pvSelect(b+'.size', r.size, PV_RCD_SIZE_OPTIONS, 'גודל מפסק')}
        <div class="sp-sub sp-span-all">בדיקות (ממלאים רק את מה שבוצע)</div>
        ${pvText(b+'.rampPlusI', r.rampPlusI, 'RAMP + — זרם ניתוק [mA]', '', 'decimal')}${pvText(b+'.rampPlusT', r.rampPlusT, 'RAMP + — זמן [ms]', '', 'decimal')}
        ${pvText(b+'.rampMinusI', r.rampMinusI, 'RAMP − — זרם ניתוק [mA]', '', 'decimal')}${pvText(b+'.rampMinusT', r.rampMinusT, 'RAMP − — זמן [ms]', '', 'decimal')}
        ${pvText(b+'.t1x', r.t1x, '1×IΔN — זמן [ms]', '', 'decimal')}${pvText(b+'.t5x', r.t5x, '5×IΔN — זמן [ms]', '', 'decimal')}
        ${pvSelect(b+'.half', r.half, ['לא ניתק (תקין)', 'ניתק (לא תקין)'], '0.5×IΔN')}
        ${spStatusSelect(b+'.status', r.status, 'תוצאה')}
      </div></div>`; }).join('')
    + `<button type="button" class="add-btn" data-addrow="${P}.t9|${escapeAttr(JSON.stringify(makePvRcd()))}">+ הוסף מפסק מגן</button>` + pvNotes(P+'.t9Notes', pv.t9Notes);
  const unitSel = (p, v) => `<select data-textpath="${p}" style="width:74px;">${['Ω','kΩ','MΩ'].map(u=>`<option ${v===u?'selected':''}>${u}</option>`).join('')}</select>`;
  const t10 = `<div class="dc-table-wrap"><table class="dc-table dc-table-compact pv-table"><thead><tr><th style="width:38px;">מס'</th><th>נתוני המשגוח (תיאור)</th><th>כיוונון ההתנגדות R</th><th>זמן ההפעלה שנמדד t [s]</th><th>התנגדות ההפעלה שנמדדה R</th><th style="width:150px;">סטטוס</th><th style="width:46px;"></th></tr></thead><tbody>
      ${pv.t10.map((r, ri)=>{ const b = `${P}.t10.${ri}`; return `<tr><td style="text-align:center; font-weight:700;">${ri+1}</td><td><input type="text" data-textpath="${b}.desc" value="${escapeAttr(r.desc||'')}" placeholder="תיאור המשגוח"></td>
        <td><div class="sp-meas">${pvInput(b+'.setR', r.setR)}${unitSel(b+'.setUnit', r.setUnit)}</div></td><td>${pvInput(b+'.time', r.time, 's')}</td>
        <td><div class="sp-meas">${pvInput(b+'.measR', r.measR)}${unitSel(b+'.measUnit', r.measUnit)}</div></td><td>${spStatusSelect(b+'.status', r.status)}</td>
        <td>${pv.t10.length > 1 ? `<button type="button" class="del-panel-btn" data-delrow="${P}.t10|${ri}">✕</button>` : ''}</td></tr>`; }).join('')}
    </tbody></table></div><button type="button" class="add-btn" data-addrow="${P}.t10|${escapeAttr(JSON.stringify(makePvItMonitor()))}">+ הוסף משגוח</button>` + pvNotes(P+'.t10Notes', pv.t10Notes);
  const t11 = pvChecklist(P+'.t11', PV_T11_ITEMS, pv.t11) + pvNotes(P+'.t11Notes', pv.t11Notes);
  const t12 = `<div class="sp-notes">${pv.t12.map((r, ri)=>`<div class="pv-note-row"><span class="sp-note-num">${ri+1}.</span>
        <textarea rows="2" data-textpath="${P}.t12.${ri}.text" placeholder="ההערה">${escapeHtml(r.text||'')}</textarea>
        <textarea rows="2" data-textpath="${P}.t12.${ri}.response" placeholder="התייחסות החשמלאי המבצע / המתכנן">${escapeHtml(r.response||'')}</textarea>
        <button type="button" class="del-panel-btn" data-delrow="${P}.t12|${ri}">✕</button></div>`).join('')}</div>
      <div class="rd-bulk"><button type="button" class="add-btn" style="width:auto;" data-addrow="${P}.t12|${escapeAttr(JSON.stringify({ text:'', response:'' }))}">+ הוסף הערה</button>
        <select data-pvnotepreset="1" style="width:auto; min-width:260px;"><option value="">+ הוסף הערה מהרשימה ▾</option>${PV_NOTE_PRESETS.map((t, i)=>`<option value="${i}">${escapeHtml(t)}</option>`).join('')}</select></div>`;
  const t13 = `<div class="dc-table-wrap"><table class="dc-table dc-table-compact pv-table"><thead><tr><th style="width:38px;">מס'</th><th>הליקוי</th><th style="width:150px;">תאריך התיקון</th><th style="width:150px;">חתימת החשמלאי</th><th style="width:46px;"></th></tr></thead><tbody>
      ${pv.t13.map((r, ri)=>{ const b = `${P}.t13.${ri}`; return `<tr><td style="text-align:center; font-weight:700;">${ri+1}</td><td><input type="text" data-textpath="${b}.defect" value="${escapeAttr(r.defect||'')}"></td><td><input type="date" data-textpath="${b}.date" value="${escapeAttr(r.date||'')}"></td><td><input type="text" data-textpath="${b}.sign" value="${escapeAttr(r.sign||'')}"></td><td><button type="button" class="del-panel-btn" data-delrow="${P}.t13|${ri}">✕</button></td></tr>`; }).join('')}
    </tbody></table></div><button type="button" class="add-btn" data-addrow="${P}.t13|${escapeAttr(JSON.stringify({ defect:'', date:'', sign:'' }))}">+ הוסף ליקוי</button>` + pvNotes(P+'.t13Notes', pv.t13Notes);
  const decl = `<p class="sp-grp-hint">הערות כלליות (מודפסות קבוע): ${PV_GENERAL_NOTES.map((t,i)=>`${i+1}. ${escapeHtml(t)}`).join(' ')}</p>
    <div class="grid2">${pvText(P+'.decl.name', pv.decl.name, 'שם החשמלאי', pv.parties.electrician.name)}${pvText(P+'.decl.licenseType', pv.decl.licenseType, 'סוג רישיון')}
      ${pvText(P+'.decl.licenseNo', pv.decl.licenseNo, "מס' רישיון", pv.parties.electrician.license, 'numeric')}<div class="field"><label>תאריך</label><input type="date" data-textpath="${P}.decl.date" value="${escapeAttr(pv.decl.date||'')}"></div></div>
    <div class="field"><label>חתימת החשמלאי (חתימה דיגיטלית — לחתום באצבע או בעט)</label>
      <canvas class="pv-sig" width="500" height="150"></canvas>
      <div style="margin-top:6px;"><button type="button" class="del-panel-btn" data-pvsigclear="1">🗑 נקה חתימה</button></div></div>`;
  return pvCard('pv-general', num(), 'נתונים כלליים של המתקן', general)
    + pvCard('pv-parties', num(), 'פרטי בעל המתקן, המתכנן והמבצע', parties)
    + pvCard('pv-verdict', num(), 'הצהרת בעל רישיון חשמלאי בודק', verdict)
    + pvCard('pv-t1', num(), 'טבלה 1: רישום תוצאות הביקורת של המסמכים הטכניים שהוגשו כתנאי לבדיקה', t1)
    + pvCard('pv-t2', num(), 'טבלה 2: רישום תוצאות הבדיקה החזותית של המיתקן הפוטו-וולטאי', t2)
    + pvCard('pv-t3', num(), 'טבלה 3: תיעוד מכשירי מדידה', t3)
    + pvCard('pv-t4', num(), 'טבלה 4: בדיקת הרציפות של מוליכי הארקה', t4)
    + pvCard('pv-t5', num(), 'טבלה 5: בדיקת התנגדות הבידוד', t5)
    + pvCard('pv-t6', num(), 'טבלה 6: בדיקת התנגדות אלקטרודות הארקה למסה הכללית של האדמה', t6)
    + pvCard('pv-t7', num(), 'טבלה 7: בדיקת מתח במיתקן בצד הזרם החילופין', t7)
    + pvCard('pv-t8', num(), 'טבלה 8: בדיקת העכבה של לולאת התקלה', t8)
    + pvCard('pv-t9', num(), 'טבלה 9: בדיקת מפסקי מגן (RCD)', t9)
    + pvCard('pv-t10', num(), 'טבלה 10: בדיקת משגוח בידוד במתקן המוגן בשיטה IT', t10)
    + pvCard('pv-t11', num(), 'טבלה 11: בדיקת התפקוד של ציוד מיתוג ייעודי', t11)
    + pvCard('pv-t12', num(), 'טבלה 12: רשימת הערות של הבודק', t12)
    + pvCard('pv-t13', num(), 'טבלה 13: רשימת הליקויים שהתגלו במהלך הבדיקה', t13)
    + pvCard('pv-decl', num(), 'הערות כלליות והצהרת החשמלאי המבצע', decl);
}

// ----------------------------- PDF -----------------------------
const PV_PDF_CSS = `<style>
  table.pv-t{width:100%; border-collapse:collapse; border:2px solid #111; margin:0 0 14px; font-size:12px; line-height:1.45; page-break-inside:auto;}
  table.pv-t th, table.pv-t td{border:1px solid #111; padding:5px 7px; vertical-align:middle;}
  table.pv-t th{background:#f2f2f2; font-weight:800; text-align:right;}
  table.pv-t .pv-cap{font-size:13.5px; font-weight:800; text-align:right; background:#f2f2f2; padding:8px 10px;}
  table.pv-t .pv-sub{font-weight:800; font-size:11.5px; background:#fff;}
  table.pv-t .pv-num{width:30px; text-align:center;}
  table.pv-t .pv-mark{width:58px; text-align:center; font-size:14px; font-weight:800;}
  table.pv-t .ok{color:#1b7f2a;} table.pv-t .bad{color:#c62828;} table.pv-t .na{color:#666; font-size:11px;}
  table.pv-t td.pv-val{width:90px; text-align:center;}
  table.pv-t .pv-notes{font-size:10.5px; color:#222;}
  .pv-cover-title{font-size:20px; font-weight:800; text-decoration:underline; text-align:center; margin:6px 0 10px;}
  .pv-cover-no{border:2px solid #111; padding:4px 10px; font-weight:800; font-size:12px; white-space:nowrap; flex-shrink:0;}
  table.pv-c{width:100%; border-collapse:collapse; border:2.5px solid #111; margin:0 0 6px; font-size:12px;}
  table.pv-c td, table.pv-c th{border:1.5px solid #111; padding:6px 8px; text-align:right; vertical-align:middle;}
  table.pv-c .pv-band{background:#f2f2f2; font-weight:800; text-align:center;}
</style>`;
function pvMarks(st){
  return `<td class="pv-mark ok">${st==='ok'?'✓':''}</td><td class="pv-mark bad">${st==='bad'?'✗':''}</td><td class="pv-mark na">${st==='na'?'N/A':''}</td>`;
}
function pvChecklistPdf(caption, items, rows, measureHeads, measureCells, notes, opts){
  opts = opts || {};
  const mh = measureHeads || [];
  const colsTotal = 2 + mh.length + 3;
  return `<table class="pv-t"><tr><th class="pv-cap" colspan="${colsTotal}">${caption}</th></tr>
    ${opts.sub ? `<tr><td class="pv-sub" colspan="${colsTotal}">${opts.sub}</td></tr>` : ''}
    <tr><th class="pv-num">מס'</th><th>${opts.itemHead || 'פרטי הבדיקה'}</th>${mh.map(h=>`<th style="text-align:center;">${h}</th>`).join('')}<th class="pv-mark">תקין</th><th class="pv-mark">לא תקין</th><th class="pv-mark">לא רלוונטי</th></tr>
    ${items.map((t, i)=>`<tr><td class="pv-num">${i+1}</td><td>${pvLabel(t)}</td>${measureCells ? measureCells(rows[i] || {}, i) : ''}${pvMarks((rows[i]||{}).status)}</tr>`).join('')}
    ${notes !== undefined ? `<tr><td class="pv-notes" colspan="${colsTotal}"><b>הערות:</b> ${escapeHtml(notes || '')}</td></tr>` : ''}
  </table>`;
}
function buildPvCoverHtml(){
  const pv = getPvInspection(), m = state.meta, s = state.settings;
  const p = pv.parties;
  const chk = on => on ? '☑' : '☐';
  const sig = s.signature ? `<img src="${s.signature}" alt="חתימה" style="max-height:60px; max-width:150px;">` : '';
  return `${PV_PDF_CSS}
    <div style="display:flex; align-items:center; justify-content:space-between; gap:12px; margin:6px 0 10px;">
      <div class="pv-cover-title" style="margin:0; flex:1;">טופס בדיקה של מתקן פוטו-וולטאי</div>
      ${m.reportNumber ? `<div class="pv-cover-no">דוח מס': <bdi dir="ltr">${escapeHtml(m.reportNumber)}</bdi></div>` : ''}
    </div>
    <table class="pv-c">
      <tr><td colspan="4">שם צרכן המתקן: ${escapeHtml(pv.consumerName || m.siteName || m.client || '')}</td></tr>
      <tr><td colspan="4">מספר חוזה / הזמנה: ${escapeHtml(pv.contractNo || '________________________')}</td></tr>
      <tr><td colspan="4"><b>סוג הבדיקה: ${escapeHtml(pv.testType || '')}</b></td></tr>
    </table>
    <table class="pv-c">
      <tr><td class="pv-band" colspan="4">נתונים כלליים של המתקן:</td></tr>
      <tr><td>גודל החיבור במתקן הצריכה שאליו מחובר המתקן הפוטו-וולטאי</td><td colspan="2"><bdi dir="ltr">${escapeHtml((pv.connVoltage||'').replace(' kV',''))} [kV]</bdi></td><td><bdi dir="ltr">${escapeHtml((pv.connSize||'').replace('A',''))} [A]</bdi></td></tr>
      <tr><td>ההספק המותקן של המתקן הפוטו-וולטאי (*): <bdi dir="ltr">${escapeHtml(pv.powerKW || pv.powerKVA || '')}</bdi></td><td>מספר מהפכים: ${escapeHtml(pv.inverterCount||'')}</td><td>מספר מודולים: ${escapeHtml(pv.moduleCount||'')}</td><td>הספק מצרפי: <bdi dir="ltr">${escapeHtml(pv.dcKWp||'')} kWp</bdi></td></tr>
      <tr><td>יצרן מהפך: ${spBdi(pv.inverterMaker||'')}</td><td>דגם מהפך: ${spBdi(pv.inverterModel||'')}</td><td>יצרן מודול: ${spBdi(pv.moduleMaker||'')}</td><td>דגם מודול: ${spBdi(pv.moduleModel||'')}</td></tr>
      <tr><td colspan="2">כתובת המתקן הפוטו-וולטאי: ${escapeHtml(m.address || '')}</td><td colspan="2">תיאור המתקן: ${pv.installationType ? '<b>' + escapeHtml(pv.installationType) + '</b>' : 'מבנה מגורים / מבנה מסחרי / תעשייה / חקלאי / אחר'}</td></tr>
    </table>
    <table class="pv-c">
      <tr><td class="pv-band" colspan="4">פרטי בעל המתקן, המתכנן והמבצע</td></tr>
      <tr><th></th><th>שם</th><th>טלפון</th><th>דוא"ל</th></tr>
      <tr><td>בעל המתקן</td><td>${escapeHtml(p.owner.name)}</td><td><bdi dir="ltr">${escapeHtml(p.owner.phone)}</bdi></td><td><bdi dir="ltr">${escapeHtml(p.owner.email)}</bdi></td></tr>
      <tr><td>נציג בעל המתקן בבדיקה</td><td>${escapeHtml(p.rep.name)}</td><td><bdi dir="ltr">${escapeHtml(p.rep.phone)}</bdi></td><td><bdi dir="ltr">${escapeHtml(p.rep.email)}</bdi></td></tr>
      <tr><td>החשמלאי המבצע</td><td>${escapeHtml(p.electrician.name)} , מס' רישיון: ${escapeHtml(p.electrician.license)}</td><td><bdi dir="ltr">${escapeHtml(p.electrician.phone)}</bdi></td><td><bdi dir="ltr">${escapeHtml(p.electrician.email)}</bdi></td></tr>
      <tr><td>המתכנן</td><td>${escapeHtml(p.designer.name)} , מס' רישיון: ${escapeHtml(p.designer.license)}</td><td><bdi dir="ltr">${escapeHtml(p.designer.phone)}</bdi></td><td><bdi dir="ltr">${escapeHtml(p.designer.email)}</bdi></td></tr>
    </table>
    <table class="pv-c">
      <tr><td class="pv-band">הצהרת בעל רישיון חשמלאי בודק (לסמן):</td></tr>
      <tr><td style="line-height:1.7;">${chk(pv.verdict==='approved')} א. הנני מאשר בזאת שהמתקן נבדק ונמצא כי הוא עומד בדרישות חוק החשמל ותקנותיו וכן בתנאים שנקבעו על ידי מנהל מינהל החשמל, ובהתאם לכך הנני <u>מאשר לחברו לרשת החשמל.</u><br>
        ${chk(pv.verdict==='not_approved')} ב. המתקן <u>לא אושר לחיבור</u> עד לתיקון הליקויים המפורטים בדו"ח הבדיקה.</td></tr>
    </table>
    <table class="pv-c">
      <tr><td class="pv-band" colspan="4">פרטי הבודק וחתימתו</td></tr>
      <tr><td>שם הבודק</td><td>${escapeHtml(s.engineerName || '')}</td><td>טלפון / נייד</td><td><bdi dir="ltr">${escapeHtml(s.engineerPhone || s.companyPhone || '')}</bdi></td></tr>
      <tr><td>סוג רישיון</td><td>${escapeHtml(s.engineerLicenseType || 'בודק סוג 3')}</td><td>מספר רישיון</td><td>${escapeHtml(s.engineerLicenseNo || '')}</td></tr>
      <tr><td style="height:70px;">תאריך הבדיקה</td><td>${m.date ? formatDateIL(m.date) : ''}</td><td>חתימה</td><td style="text-align:center;">${sig}</td></tr>
    </table>
    <div style="font-size:10px;">(*) הספק מותקן - ההספק בהתאם לנתוני היצרן של המהפכים בקילו וולט אמפר או בקילו-וואט.</div>`;
}
function buildPvInspectionBlocks(){
  const pv = getPvInspection(), blocks = [];
  const add = (key, title, html, pageBreak) => blocks.push({ level:1, sectionKey:key, title, html: (blocks.length ? '' : PV_PDF_CSS) + html, pageBreak: !!pageBreak });
  const val = v => String(v||'').trim() ? `<bdi dir="ltr">${escapeHtml(v)}</bdi>` : '';
  add('pv-t1', 'טבלה 1', pvChecklistPdf('טבלה 1: רישום תוצאות הביקורת של המסמכים הטכניים שהוגשו כתנאי לבדיקה', PV_T1_ITEMS, pv.t1, null, null, pv.t1Notes || undefined, { itemHead:'המסמכים הטכניים שהוגשו כתנאי לבדיקה' }), true);
  add('pv-t2', 'טבלה 2', pvChecklistPdf('טבלה 2: רישום תוצאות הבדיקה החזותית של המיתקן הפוטו-וולטאי', PV_T2_ITEMS, pv.t2, null, null, pv.t2Notes || undefined, { itemHead:'בדיקה חזותית' }), true);
  // טבלה 3 — מכשירי מדידה מסעיף 01 + פרטים מההגדרות
  const instr = (state.meta.testInstrumentsSelected || []).filter(x=>x && x !== 'אחר').map(name=>{ const e = findMatchingEquipment(name) || {}; return [name, e.model || '', e.serialNo || e.serial || '', e.calibrationDate ? formatDateIL(e.calibrationDate) : '']; });
  add('pv-t3', 'טבלה 3', `<table class="pv-t"><tr><th class="pv-cap" colspan="5">טבלה 3: תיעוד מכשירי מדידה שבאמצעותם נערכו מדידות</th></tr>
    <tr><th class="pv-num">מס'</th><th>שם המכשיר</th><th>דגם</th><th>מס' סידורי</th><th>תוקף תאריך כיול</th></tr>
    ${(instr.length ? instr : [['','','','']]).map((r, i)=>`<tr><td class="pv-num">${i+1}</td><td>${escapeHtml(r[0])}</td><td>${val(r[1])}</td><td>${val(r[2])}</td><td>${escapeHtml(r[3])}</td></tr>`).join('')}</table>`, true);
  add('pv-t4', 'טבלה 4', pvChecklistPdf('טבלה 4: בדיקת הרציפות של מוליכי הארקה', PV_T4_ITEMS, pv.t4, ['תוצאות המדידה [Ω]'], r=>`<td class="pv-val">${val(r.value)}</td>`, pv.t4Notes));
  const mm = r=>`<td class="pv-val">${val(r.min)}</td><td class="pv-val">${val(r.max)}</td>`;
  const lines = n => `נבדקו ${String(n||'').trim() ? escapeHtml(n) : '_____'} קוים. בטבלה רשומות תוצאות הקיצון.`;
  add('pv-t5', 'טבלה 5', `<table class="pv-t" style="margin-bottom:0;"><tr><th class="pv-cap">טבלה 5: בדיקת התנגדות הבידוד</th></tr></table>`
    + pvChecklistPdf('א. בדיקת התנגדות הבידוד בצד הזרם הישר (DC)', PV_T5DC_ITEMS, pv.t5dc, ['min [MΩ]', 'max [MΩ]'], mm, lines(pv.t5dcLines)));
  add('pv-t5b', 'טבלה 5 ב', pvChecklistPdf('ב. בדיקת התנגדות הבידוד בצד זרם החילופין (AC)', PV_T5AC_ITEMS, pv.t5ac, ['min [MΩ]', 'max [MΩ]'], mm, lines(pv.t5acLines)), true);
  // טבלה 6 — לפי מיקומים
  const t6rows = pv.t6.map((loc)=>`<tr><td class="pv-sub" colspan="6">${escapeHtml(loc.location || '')}</td></tr>` + PV_T6_ITEMS.map((t, i)=>{ const r = loc.rows[i] || {}; return `<tr><td class="pv-num">${i+1}</td><td>${escapeHtml(t)}</td><td class="pv-val">${val(r.value)}</td>${pvMarks(r.status)}</tr>`; }).join('')).join('');
  add('pv-t6', 'טבלה 6', `<table class="pv-t"><tr><th class="pv-cap" colspan="6">טבלה 6: בדיקת התנגדות אלקטרודות הארקה למסה הכללית של האדמה במתקני מתח גבוה</th></tr>
    <tr><th class="pv-num">מס'</th><th>תוצאות המדידה</th><th style="text-align:center;">[Ω]</th><th class="pv-mark">תקין</th><th class="pv-mark">לא תקין</th><th class="pv-mark">לא רלוונטי</th></tr>${t6rows}
    ${pv.t6Notes ? `<tr><td class="pv-notes" colspan="6"><b>הערות:</b> ${escapeHtml(pv.t6Notes)}</td></tr>` : ''}</table>`, true);
  add('pv-t7', 'טבלה 7', pvChecklistPdf('טבלה 7: בדיקת מתח במיתקן בצד הזרם החילופין', PV_T7_ITEMS, pv.t7, ['מתח'], r=>`<td class="pv-val">${String(r.value||'').trim() ? val(r.value + ' V') : ''}</td>`, pv.t7Notes || undefined, { itemHead:'תוצאות המדידה' }));
  add('pv-t8', 'טבלה 8', pvChecklistPdf('טבלה 8: בדיקת העכבה של לולאת התקלה', PV_T8_ITEMS, pv.t8, ['תוצאות המדידה'], r=>`<td class="pv-val">${String(r.value||'').trim() ? val(r.value + 'Ω') : ''}</td>`, pv.t8Notes));
  // טבלה 9 — מפסקי מגן
  const rcdDesc = r => [r.desc ? 'מפסק מגן - ' + r.desc : 'מפסק מגן', r.idn ? 'זרם הפעלה נקוב ' + r.idn.replace(' mA','') + ' [mA]' : '', r.type ? 'סוג: ' + r.type : '', r.size ? 'גודל: ' + r.size : ''].filter(Boolean).join(', ');
  add('pv-t9', 'טבלה 9', `<table class="pv-t"><tr><th class="pv-cap" colspan="6">טבלה 9: בדיקת מפסקי מגן</th></tr>
    <tr><td class="pv-sub" colspan="6">בדיקה זו הכרחית עבור מתקן באתר חקלאי או במתקנים בהם מיישמים מפסק מגן כהגנה בלעדית</td></tr>
    <tr><th class="pv-num">מס'</th><th>תיאור מפסק מגן</th><th style="text-align:center;">זרם ההפעלה שנמדד IΔn [mA]</th><th style="text-align:center;">זמן ההפעלה שנמדד tΔ [ms]</th><th class="pv-mark">תקין</th><th class="pv-mark">לא תקין</th></tr>
    ${pv.t9.map((r, i)=>`<tr><td class="pv-num">${i+1}</td><td>${escapeHtml(rcdDesc(r))}</td><td class="pv-val">${val(r.rampPlusI || r.rampMinusI)}</td><td class="pv-val">${val(r.t1x || r.rampPlusT || r.rampMinusT)}</td><td class="pv-mark ok">${r.status==='ok'?'✓':''}</td><td class="pv-mark bad">${r.status==='bad'?'✗':''}</td></tr>`).join('')}
    <tr><td class="pv-notes" colspan="6"><b>הערות:</b> ${escapeHtml(pv.t9Notes || '')}</td></tr></table>`, true);
  add('pv-t10', 'טבלה 10', `<table class="pv-t"><tr><th class="pv-cap" colspan="6">טבלה 10: בדיקת משגוח בידוד במתקן המוגן בשיטה IT</th></tr>
    <tr><th class="pv-num">מס'</th><th>נתוני המשגוח</th><th style="text-align:center;">זמן ההפעלה שנמדד t [S]</th><th style="text-align:center;">התנגדות ההפעלה שנמדדה R</th><th class="pv-mark">תקין</th><th class="pv-mark">לא תקין</th></tr>
    ${pv.t10.map((r, i)=>`<tr><td class="pv-num">${i+1}</td><td>משגוח: ${escapeHtml(r.desc||'')}, כיוונון התנגדות R = ${String(r.setR||'').trim() ? val(r.setR + ' ' + (r.setUnit||'')) : '........ Ω'}</td><td class="pv-val">${val(r.time)}</td><td class="pv-val">${String(r.measR||'').trim() ? val(r.measR + ' ' + (r.measUnit||'')) : ''}</td><td class="pv-mark ok">${r.status==='ok'?'✓':''}</td><td class="pv-mark bad">${r.status==='bad'?'✗':''}</td></tr>`).join('')}
    <tr><td class="pv-notes" colspan="6"><b>הערות:</b> ${escapeHtml(pv.t10Notes || '')}</td></tr></table>`);
  add('pv-t11', 'טבלה 11', pvChecklistPdf('טבלה 11: בדיקת התפקוד של ציוד מיתוג ייעודי', PV_T11_ITEMS, pv.t11, null, null, pv.t11Notes || undefined, { itemHead:'תיאור הבדיקה' }));
  const notesRows = (pv.t12 || []).filter(r=>String(r.text||'').trim());
  add('pv-t12', 'טבלה 12', `<table class="pv-t"><tr><th class="pv-cap" colspan="3">טבלה 12: רשימת הערות של הבודק</th></tr>
    <tr><th class="pv-num">מס'</th><th>ההערה</th><th style="width:160px;">התייחסות החשמלאי המבצע/המתכנן</th></tr>
    ${(notesRows.length ? notesRows : [{text:'',response:''}]).map((r, i)=>`<tr><td class="pv-num">${i+1}</td><td>${escapeHtml(r.text)}</td><td>${escapeHtml(r.response||'')}</td></tr>`).join('')}</table>`, true);
  add('pv-t13', 'טבלה 13', `<table class="pv-t"><tr><th class="pv-cap" colspan="4">טבלה 13: רשימת הליקויים שהתגלו במהלך הבדיקה</th></tr>
    <tr><th class="pv-num">מס'</th><th>הליקוי</th><th style="width:80px;">תאריך התיקון</th><th style="width:80px;">חתימת החשמלאי</th></tr>
    ${pv.t13.map((r, i)=>`<tr><td class="pv-num">${i+1}</td><td>${escapeHtml(r.defect||'')}</td><td>${r.date ? formatDateIL(r.date) : ''}</td><td>${escapeHtml(r.sign||'')}</td></tr>`).join('')}</table>
    <div style="font-size:11px;"><b>הערות:</b> ${escapeHtml(pv.t13Notes || '')}</div>`);
  const d = pv.decl;
  add('pv-decl', 'הצהרת החשמלאי המבצע', `<div style="border:2px solid #111; border-radius:6px; padding:8px 12px; font-size:12px; line-height:1.7; margin-bottom:10px;">${PV_GENERAL_NOTES.map((t, i)=>`${i+1}. ${escapeHtml(t)}`).join('<br>')}</div>
    <table class="pv-t"><tr><th class="pv-cap" colspan="4">הצהרת החשמלאי המבצע</th></tr>
      <tr><td colspan="4" style="line-height:1.7;">אני החשמלאי החתום מטה, מצהיר בזאת שמתקן החשמל בוצע על ידי לפי כללי המקצוע והבטיחות הטובים ובהתאם לחוק החשמל ותקנותיו התשי"ד 1954 ותקני מכון התקנים הישראלי הנוגעים למתקני צריכה חשמליים.</td></tr>
      <tr><th>שם החשמלאי</th><th>סוג רישיון</th><th>מס' רישיון</th><th>תאריך</th></tr>
      <tr><td>${escapeHtml(d.name || pv.parties.electrician.name || '_______________')}</td><td>${escapeHtml(d.licenseType || '_______________')}</td><td>${escapeHtml(d.licenseNo || pv.parties.electrician.license || '_______________')}</td><td>${d.date ? formatDateIL(d.date) : '_______________'}</td></tr>
      <tr><td colspan="4" style="height:70px; vertical-align:top;"><b>חתימת החשמלאי:</b>${d.signature ? `<div style="text-align:center;"><img src="${d.signature}" alt="חתימת החשמלאי" style="max-height:70px; max-width:220px;"></div>` : ''}</td></tr></table>`, true);
  return blocks;
}

const TOUCH_VOLTAGE_REPORT_TYPE_NAME = "דוח בדיקת מתח מגע";
const TRANSFORMER_WINDING_REPORT_TYPE_NAME = "דוח בדיקת התנגדות סלילים בשטח";
const HV_CABLE_REPORT_TYPE_NAME = "דוח בדיקת כבל מתח גבוה";
const FLEXIBLE_REPORT_TYPE_NAME = "דוח גמיש";
const MAIN_PANEL_REPORT_TYPE_NAME = "דוח בדיקת לוח חשמל ראשי";
// דוח חדש — בדיקת שנאי מתח גבוה (נפרד מ-TRANSFORMER_WINDING, שהוא ספציפית בדיקת התנגדות
// סלילים). לפי בקשה מפורשת ("זה דוח חדש"), מבוסס על תבנית עיצוב מפורטת שהועלתה: תומך בכמה
// שנאים באותו דוח, checklist ויזואלי של 22 פריטים, בדיקת בידוד עם 5 סוגי מדידה (כולל Screen),
// ומערכת הארקה (שיטה+הגנה).
const TRANSFORMER_INSPECTION_REPORT_TYPE_NAME = "דוח בדיקת שנאי מתח גבוה";
// תווית תצוגה גלובלית וקבועה — לא תלוית הקשר/תיקייה. לפי בקשה חוזרת: הגישה הקודמת (תווית
// שונה רק כשנבחר מתוך תיקיית "בדיקות מתח גבוה" הספציפית) לא יכלה לעבוד באופן עקבי, כי ברוב
// מקומות התצוגה (כותרת ראשית, הבורר המהיר בראש הטופס) יש גישה רק לערך הפונקציונלי עצמו
// (state.settings.formTypeName) — לא לזיכרון "מאיזו תיקייה זה נבחר". פתרון עקבי: אותה תווית
// בכל מקום שבו סוג הדוח הזה מוצג, ללא יוצא מן הכלל.
const GLOBAL_TYPE_DISPLAY_LABELS = {
  [MAIN_PANEL_REPORT_TYPE_NAME]: "בדיקת לוח מתח גבוה"
};
function getTypeDisplayLabel(typeName){
  return GLOBAL_TYPE_DISPLAY_LABELS[typeName] || typeName;
}

// רשימת בדיקות אל-פסק (UPS) קבועה — 12 פריטים, לפי המבנה המקצועי שנמצא בנתוני ייחוס.
// לא כל לוח כולל בפועל מערכת אל-פסק — הרשימה מוצגת תמיד, אך כל פריט מסומן בנפרד כרלוונטי/תקין.
const MAIN_PANEL_UPS_CHECKLIST = [
  { id: "installation", name: "התקנה בהתאם לתקנות החשמל" },
  { id: "n-conductor-sign", name: "שילוט מוליך ה-\"N\" המשמש כמוליך הארקת השיטה של מערכת אל פסק" },
  { id: "silent-transfer", name: "תקינות מערכת העברה שקטה" },
  { id: "panel-warning-sign", name: "שילוט בלוח - זהירות, הלוח מוזן ממספר מקורות מתח" },
  { id: "neutral-separation", name: "הפרדה ברורה בין פסי אפס של השדות השונים" },
  { id: "battery-room-doors", name: "קיום דלתות עמידות בעירה לחדר מצברים" },
  { id: "exit-signs", name: "קיום ותקינות שלטי יציאת חירום" },
  { id: "emergency-lighting", name: "קיום ותקינות תאורת חירום בחדר אל פסק וחדר מצברים" },
  { id: "emergency-disconnect", name: "תקינות לחצן ניתוק חירום מערכת אל פסק" },
  { id: "battery-voltage-warning-sign", name: "הימצאות שילוט: זהירות - מערכת אל פסק, קיים מתח גם לאחר הפסקת הזינה" },
  { id: "battery-base-grounding", name: "הארקת מסד מצברים" },
  { id: "battery-protection-cover", name: "הימצאות כיסוי הגנה בפני מגע מקרי של מערך המצברים" }
];

