function makeFlexPanelChecklist(){ return FLEX_PANEL_CHECKLIST_DEFAULT.map(x=>({ label: x.label, hasValue: !!x.hasValue, value: '', status: '' })); }
function isFlexPanelSection(sec){ return !!sec && FLEX_PANEL_TYPES.includes(sec.type); }
// v2.2.521 — פרק "בדיקת תאורת חירום ויציאות חירום" עם צ'ק ליסט משלו (ת"י 20 חלק 2.22 / הנחיות כבאות)
const FLEX_EMERGENCY_TYPE = "בדיקת תאורת חירום ויציאות חירום";
const FLEX_EMERGENCY_CHECKLIST_DEFAULT = [
  { label: 'גופי תאורת חירום נדלקים בהפסקת חשמל' }, { label: 'זמן גיבוי (דקות) — נדרש לפחות 60', hasValue: true },
  { label: 'שלטי יציאה מוארים ותקינים' }, { label: 'השלטים מכוונים נכון לדרכי המילוט' },
  { label: 'נוריות טעינה דולקות' }, { label: 'מצב סוללות / תאריך החלפה אחרון', hasValue: true },
  { label: 'ניקיון גופי התאורה והשלטים' }, { label: 'מעגל תאורת חירום מסומן בלוח' },
  { label: 'דרכי מילוט ויציאות חירום פנויות ממכשולים' }, { label: 'דלתות יציאת חירום נפתחות בקלות (ידית בהלה)' },
  { label: 'מספר גופים שנבדקו', hasValue: true }, { label: 'מספר גופים לא תקינים', hasValue: true }
];
function flexChecklistTemplate(sec){ return sec && sec.type === FLEX_EMERGENCY_TYPE ? FLEX_EMERGENCY_CHECKLIST_DEFAULT : (sec && FLEX_PANEL_TYPES.includes(sec.type) ? FLEX_PANEL_CHECKLIST_DEFAULT : null); }
function isFlexChecklistSection(sec){ return !!flexChecklistTemplate(sec); }
function makeFlexChecklistFor(sec){ const t = flexChecklistTemplate(sec) || []; return t.map(x=>({ label: x.label, hasValue: !!x.hasValue, value: '', status: '' })); }
// v2.2.520 — סדר קבוע בדוח טיפול בלוחות: קודם כל הלוחות וכל פרקי המלל, ובסוף תמיד — ממצאים, המלצות,
// הערות, סיכום (בסדר הזה). לוח / פרק חדש נכנס אוטומטית לפני החלק הזה, גם אם מזיזים ידנית.
const FLEX_PANEL_REPORT_TAIL = ['ממצאים', 'המלצות', 'הערות', 'סיכום'];
function flexNormalizeOrder(fr){
  if(!fr || fr.reportType !== 'PANEL_MAINTENANCE' || !Array.isArray(fr.sections)) return;
  // דירוג: לוחות (0) → פרקי מלל אחרים, למשל עבודות שבוצעו (1) → ממצאים, המלצות, הערות, סיכום (2..5)
  const tailRank = sec => { const i = FLEX_PANEL_REPORT_TAIL.indexOf(sec.type); return i >= 0 ? 2 + i : (FLEX_PANEL_TYPES.includes(sec.type) ? 0 : 1); };
  const sorted = fr.sections.slice().sort((a, b) => {
    const ra = tailRank(a), rb = tailRank(b);
    if(ra !== rb) return ra - rb;
    return a.order - b.order;
  });
  sorted.forEach((sec, i) => { sec.order = i; });
}

