const TOUCH_VOLTAGE_SYSTEM_VOLTAGE_PRESETS = ["230V", "400V", "6.6kV", "11kV", "22kV", "33kV", "66kV", "110kV", "161kV", "230kV", "400kV"];
const TOUCH_VOLTAGE_FAULT_CURRENT_PRESETS = ["1kA", "5kA", "10kA", "16kA", "20kA", "25kA", "31.5kA", "40kA", "50kA"];
const TOUCH_VOLTAGE_CLEARING_TIME_PRESETS = ["0.1s", "0.2s", "0.3s", "0.5s", "1s", "3s", "5s"];
const TOUCH_VOLTAGE_UNITS = {
  voltage: ["mV", "V", "kV"],
  current: ["mA", "A", "kA"],
  time: ["ms", "s"],
  resistance: ["mΩ", "Ω", "kΩ"]
};

// select עם רשימת ברירת מחדל; בבחירת "אחר" נפתחים שדה ערך + בורר יחידה נפרד (לא מוטמעים ברשימה עצמה)
function selectWithUnitFallback(label, path, valueObj, presets, unitKind){
  const isOther = valueObj.preset === 'אחר';
  return `
    <div class="field">
      <label>${label}</label>
      <select data-unitfallback="${path}">
        <option value="">-- בחר --</option>
        ${presets.map(p=>`<option value="${escapeAttr(p)}" ${valueObj.preset===p?'selected':''}>${escapeHtml(p)}</option>`).join('')}
        <option value="אחר" ${isOther?'selected':''}>אחר (הזנה ידנית)</option>
      </select>
    </div>
    ${isOther ? `
      <div class="grid2" style="margin-top:-8px;">
        <div class="field"><label>ערך</label><input type="text" inputmode="decimal" data-textpath="${path}.customValue" data-restrict="decimal" value="${escapeAttr(valueObj.customValue)}"></div>
        <div class="field"><label>יחידה</label>
          <select data-textpath="${path}.customUnit">
            ${TOUCH_VOLTAGE_UNITS[unitKind].map(u=>`<option value="${u}" ${valueObj.customUnit===u?'selected':''}>${u}</option>`).join('')}
          </select>
        </div>
      </div>
    ` : ''}
  `;
}
function touchVoltageFieldDisplay(valueObj){
  if(!valueObj.preset) return '';
  if(valueObj.preset === 'אחר') return valueObj.customValue ? `${valueObj.customValue}${valueObj.customUnit}` : '';
  return valueObj.preset;
}

