// factory functions — בדיוק לפי רשימת השדות שצוינה, ללא מחיקת שדות גם אם לא כולם מוצגים כרגע ב-UI.
function makeGroundingClampTest(){
  return {
    id: (crypto && crypto.randomUUID) ? crypto.randomUUID() : ('ct_' + Date.now() + '_' + Math.random().toString(36).slice(2)),
    location: "", electrodeDescription: "", conductorDescription: "",
    parallelEarthPathExists: "", returnPathDescription: "", connectionState: "",
    clampPosition: "", measuredResistance: "", unit: "Ω",
    seasonalFactor: "1.00", seasonalFactorSource: "", correctedResistance: "",
    maxAllowed: "", status: "", notes: "", photos: [],
  };
}
function makeGroundingSelectiveTest(){
  return {
    id: (crypto && crypto.randomUUID) ? crypto.randomUUID() : ('st_' + Date.now() + '_' + Math.random().toString(36).slice(2)),
    location: "", electrodeDescription: "",
    currentStakeDistance: "", potentialStakeDistance: "", clampPosition: "",
    measuredResistance: "", unit: "Ω",
    seasonalFactor: "1.00", seasonalFactorSource: "", correctedResistance: "",
    maxAllowed: "", status: "", notes: "", photos: [],
  };
}

// *** חישוב תיקון עונתי ל-Clamp/Selective — בדיוק לפי הנוסחה שצוינה. אין המרת יחידות
// סמויה. אם seasonalFactor ריק (לא מספר) — לא מבצעים תיקון אוטומטי (מחזירים '').
function calcGroundingCorrectedResistance(measured, factor) {
  const r = Number(measured);
  const k = Number(factor);
  if (!Number.isFinite(r)) return '';
  if (!Number.isFinite(k)) return '';
  return +(r * k).toFixed(2);
}
// מסקנה אוטומטית — רק אם גם המתוקן וגם ה-Rmax קיימים; המשתמש יכול לשנות ידנית תמיד
// (ה-UI לא ינעל את שדה הסטטוס, זו רק הצעת ברירת מחדל בעת חישוב).
function calcGroundingAutoStatus(correctedResistance, maxAllowed) {
  const r = Number(correctedResistance);
  const max = Number(maxAllowed);
  if (!Number.isFinite(r) || !Number.isFinite(max) || String(maxAllowed).trim() === '') return '';
  return r <= max ? 'תקין' : 'לא תקין';
}

