// הצהרה קבועה להגנת הבודק — לפי בקשה מפורשת: 5 סעיפים קבועים, תמיד פעילים, לא ניתנים
// לביטול על ידי המשתמש (בשונה מ-DECLARATIONS הישנה שהייתה checkbox-list הניתנת לביטול).
// נפרדת לגמרי מ"הצהרת הבודק" (state.approvalStatus, 3 אפשרויות בחירה) — שתי הצהרות
// שונות בתכלית, לא מתמזגות.
const DECLARATIONS = [
  'מתקן החשמל נבדק עפ"י חוק החשמל ותקנותיו.',
  'היתר הבדיקה מתייחס למתקן וללוחות כפי שהיו קיימים במועד הבדיקה.',
  'כל שינוי עתידי במתקן מבטל את ההיתר הנוכחי ומחייב בדיקה נוספת.',
  'לא נבדק ציוד חשמלי מטלטל ומכשירים המחוברים באמצעות תקע.',
  'תוצאות הבדיקה תקפות ליום הבדיקה ואין הבודק אחראי לכל שינוי שלאחר הבדיקה.'
];

const ELECTRICIAN_DECLARATION = 'אני החשמלאי החתום מטה, מצהיר בזאת שמתקן החשמל בוצע על ידי לפי כללי המקצוע והבטיחות הטובים ובהתאם לחוק החשמל ותקנותיו התשי"ד 1954 ותקני מכון התקנים הישראלי הנוגעים למתקני צריכה חשמליים.';

// *** Renderer משותף אחד להצהרת החשמלאי המבצע — לכל סוגי הדוח, לפי בקשה מפורשת
// למניעת "פתרונות נקודתיים לפי סוג דוח". מקבל data (לא state ישירות) כדי שכל סוג
// דוח יוכל להעביר את מקור הנתונים שלו (גנרי או ייעודי) דרך getElectricianDeclarationData
// למטה, בלי לשכפל HTML. data.enabled=false (או data=null) -> מחזיר '' (בלי רווח/placeholder).
function buildElectricianDeclarationBlock(data){
  // v2.2.530 — ביטול גלובלי מההגדרות: לא מודפסת בשום דוח
  if(state.settings && state.settings.hideElectricianDeclaration) return '';
  if(!data || !data.enabled) return '';
  const declText = (state.electricianDeclarationText && state.electricianDeclarationText.trim()) || ELECTRICIAN_DECLARATION;
  let html = `
    <div class="decl-box" style="text-align:right; margin-top:18px;">
      <div class="decl-box-title">הצהרת החשמלאי המבצע</div>
      <p style="font-size:12px; padding:0 14px; margin:10px 0;">${escapeHtml(declText)}</p>
      <table class="electrician-table">
        <thead><tr><th>שם החשמלאי</th><th>סוג רישיון</th><th>מס' רישיון</th><th>תאריך</th></tr></thead>
        <tbody><tr>
          <td>${escapeHtml(data.name)||'____________________'}</td>
          <td>${escapeHtml(data.licenseType)||'____________________'}</td>
          <td>${escapeHtml(data.licenseNo)||'____________________'}</td>
          <td>${formatDateIL(data.date)||'____________________'}</td>
        </tr></tbody>
      </table>`;
  if(data.notComplete){
    html += `<p style="font-size:12px; color:#c67405; font-weight:700; background:#fdf1e0; padding:8px 10px; margin:8px 14px 0;">⚠ הצהרת החשמלאי לא הושלמה או לא הוצגה.</p>`;
  }
  if(data.signature){
    html += `<div style="padding:10px 14px;"><img src="${data.signature}" style="max-width:220px; max-height:80px; border-bottom:1px solid #999;"><div style="font-size:11px; color:#666;">חתימה</div></div>`;
  } else {
    html += `<div style="font-size:12px; padding:10px 14px 4px;">חתימת החשמלאי: ________________________</div>`;
  }
  html += `</div>`;
  return html;
}

// *** Resolver — מזהה לכל סוג דוח מהו מקור הנתונים הנכון עבור הצהרת החשמלאי, ואת
// תנאי ה"מופעל" הנכון שלו. Audit אישר (לא ניחוש): EV_DC/GENERATOR/GENERAL שומרים
// את ההצהרה ב-state sub-object ייעודי משלהם (evDcReport.page2/generatorReport/
// generalElectricalInspectionReport), לא ב-state.workingElectricianName הגנרי —
// לכן הם חייבים resolver נפרד, אחרת הנתונים שהמשתמש הזין בעורך לא היו מוצגים כלל
// בהדפסה (זה בדיוק מה שקרה בפועל לפני התיקון: נבדק ואומת עם נתוני בדיקה ייחודיים).
function getElectricianDeclarationData(){
  const rt = getReportType();
  if(rt === 'EV_DC'){
    const ed = state.evDcReport.page2.electricianDeclaration;
    return {
      enabled: !!(ed.name || ed.licenseNo || ed.licenseType || ed.companyName || ed.declared || ed.signature),
      name: ed.name, licenseType: ed.licenseType, licenseNo: ed.licenseNo, date: ed.date, signature: ed.signature,
      notComplete: !!(ed.declared && ed.declared !== 'כן'),
    };
  }
  if(rt === 'GENERATOR'){
    const ed = state.generatorReport.electricianDeclaration;
    return { enabled: ed.status === 'הצהרת חשמלאי מצורפת', name: ed.name, licenseType: ed.licenseType, licenseNo: ed.licenseNo, date: ed.date, signature: ed.signature };
  }
  if(rt === 'GENERAL'){
    const ed = state.generalElectricalInspectionReport.electricianDeclaration;
    return { enabled: ed.status === 'הצהרת חשמלאי מצורפת', name: ed.name, licenseType: ed.licenseType, licenseNo: ed.licenseNo, date: ed.date, signature: ed.signature };
  }
  // כל שאר סוגי הדוח (GROUNDING/SMA/MAIN_PANEL/EVCS/SOIL/DC_CABLE/MEDICAL/HV_CABLE/
  // FLEXIBLE/TRANSFORMER_*/TOUCH_VOLTAGE/LIGHTNING/וכו') — המנגנון הגנרי הקיים.
  return {
    enabled: !!state.showElectricianDeclaration,
    name: state.workingElectricianName, licenseType: state.workingElectricianLicenseType,
    licenseNo: state.workingElectricianLicenseNo, date: state.meta.date, signature: state.settings.signature,
  };
}

// הצהרת חשמלאי לתיקון ליקוי — לפי בקשה מפורשת, מופיעה אוטומטית בדוח כאשר קיים ליקוי (לא
// toggle ידני כמו ההצהרה הרגילה). נוסח זה הוצע ואושר במפורש על ידי המשתמש לפני הבנייה — אינו
// טקסט משפטי רשמי ממקור חיצוני מאומת; מומלץ למשתמש לוודא מול מקור מקצועי/משפטי משלו ולערוך
// בהתאם דרך שדה הטקסט הניתן לעריכה (כמו ELECTRICIAN_DECLARATION למעלה).
const DEFECT_REPAIR_DECLARATION = 'הריני מצהיר/נו כי הליקוי שצוין בדוח זה תוקן על ידי/נו בהתאם לכללי המקצוע הטובים, בהתאם לחוק החשמל התשי"ד 1954 ותקנותיו ותקני מכון התקנים הישראלי, וכי המתקן נבדק ונמצא תקין ובטוח. אין בהצהרה זו כדי להוות אישור רשמי או תחליף לבדיקה נוספת של בודק מוסמך/מהנדס חשמל בהתאם לדרישות הרשויות.';

function makePanelId(){ return 'panel_' + Date.now().toString(36) + Math.random().toString(36).slice(2,6); }

function makeItemPair(){ return { torque:'', cleaning:'' }; }

