// ==== איחוד דוחות (v2.187) — "פרק" = דוח מסוג נפרד לגמרי, מוטמע בתוך אותו דו"ח מאוחד ====
// הרעיון: הדוח ה"ראשי" ממשיך לחיות ישירות בשדות ה-state הרגילים כרגיל (state.mainPanelReport,
// state.generalPhotos וכו') — אפס שינוי סיכון/התנהגות למי שלא משתמש בפיצ'ר בכלל. פרקים נוספים
// נשמרים כ-snapshot נפרד (עותק מלא, כולל תמונות משלו) בתוך state.reportChapters. מעבר בין
// פרקים "מחליף" את השדות הפר-פרק בתוך ה-state החי — אותו state, אותן פונקציות רינדור/הדפסה
// לכל סוגי הדוח, בלי לגעת בהן כלל. זה מה ששומר על התמונות מופרדות בדיוק כמו שהתבקש: כל פרק
// הוא state.generalPhotos/itemPhotos נפרד משלו, לא רשימה משותפת.
const CHAPTER_SCOPED_FIELDS = [
  'generalPhotos', 'itemPhotos',
  'generalVisual', 'generalPanelDetails', 'voltageSystem', 'mainSwitchgear', 'mainSwitchgearExtra', 'panelOrder', 'panels', 'standaloneTransformer', 'standaloneTransformerExtra',
  'soilTest', 'groundingTest', 'dcCableTest', 'evDcReport', 'generalElectricalInspectionReport', 'medicalReport',
  'lightningProtectionInspectionReport', 'touchVoltageReport', 'transformerWindingReport', 'hvCableReport', 'flexibleReport', 'mainPanelReport',
  'stringPolarityReport', 'protectionRelays', 'pvInspection', 'fireForm3', 'aiSummary'
];

function makeChapterId(){ return 'chapter_' + Date.now().toString(36) + Math.random().toString(36).slice(2,6); }

// לוכד את כל השדות הפר-פרק מה-state החי כרגע (כולל formTypeName, שקובע איזה סוג דוח זה)
// כעותק עצמאי לחלוטין (JSON round-trip) — כדי שעריכה בפרק אחד לא תזלוג לעותק השמור של פרק אחר.
// meta.description ("תיאור המתקן/העבודה") גם הוא פר-פרק בכוונה, לא משותף כמו שאר meta —
// כל פרק בודק דבר שונה לגמרי (מתח נמוך/לוח מתח גבוה/שנאי), אין הגיון שהתיאור יחזור על עצמו זהה.
function snapshotChapterScopedState(){
  const snap = { formTypeName: state.settings.formTypeName, description: state.meta.description };
  CHAPTER_SCOPED_FIELDS.forEach(key => { snap[key] = JSON.parse(JSON.stringify(state[key])); });
  return snap;
}

// מחזיר snapshot שמור לתוך ה-state החי — הפוך מ-snapshotChapterScopedState().
function applyChapterScopedSnapshot(snap){
  state.settings.formTypeName = snap.formTypeName;
  state.meta.description = snap.description || '';
  // *** תיקון תאימות (v2.2.503): פרק שנשמר בגרסה ישנה לא מכיל שדות פר-פרק שנוספו אחריו (למשל
  // stringPolarityReport). JSON.parse(JSON.stringify(undefined)) זורק שגיאה — וזה היה מפיל את המעבר
  // לפרק ואת בניית ה-PDF. שדה חסר מקבל את ברירת המחדל הריקה של סוג הדוח; שום נתון קיים לא נגע.
  let fresh = null;
  CHAPTER_SCOPED_FIELDS.forEach(key => {
    if(snap[key] === undefined){ if(!fresh) fresh = newState(); state[key] = JSON.parse(JSON.stringify(fresh[key] === undefined ? null : fresh[key])); return; }
    state[key] = JSON.parse(JSON.stringify(snap[key]));
  });
}

// בונה snapshot ריק/חדש לגמרי עבור סוג דוח נתון — לשימוש כשמוסיפים פרק חדש. מריץ newState()
// מלא (בטוח וזול, לא ריצה תכופה) ושואב ממנו רק את השדות הפר-פרק, כדי לא לשכפל את כל ברירות
// המחדל (למשל panels[firstId]) בנפרד ולסכן חוסר-עקביות עם newState() עצמה בעתיד.
function makeFreshChapterSnapshot(formTypeName){
  const fresh = newState();
  const snap = { formTypeName, description: '' };
  CHAPTER_SCOPED_FIELDS.forEach(key => { snap[key] = fresh[key]; });
  return snap;
}

// עובר לעריכת פרק אחר (-1 = הדוח הראשי). שומר קודם את מצב הפרק הנוכחי (איפה שהוא היה), ורק
// אז טוען את מצב הפרק היעד — כדי שאף פרק לא יאבד נתונים כשעוברים הלאה־ואילך ביניהם.
function switchToChapter(targetIndex){
  const currentSnapshot = snapshotChapterScopedState();
  if(state.activeChapterIndex === -1){
    state.primaryChapterBackup = currentSnapshot;
  } else if(state.reportChapters[state.activeChapterIndex]){
    state.reportChapters[state.activeChapterIndex].snapshot = currentSnapshot;
  }

  const targetSnapshot = targetIndex === -1 ? state.primaryChapterBackup : (state.reportChapters[targetIndex] && state.reportChapters[targetIndex].snapshot);
  if(targetSnapshot) applyChapterScopedSnapshot(targetSnapshot);
  state.activeChapterIndex = targetIndex;
  openSections.clear(); alreadySeededOpenCards.clear(); // כרטיסים פתוחים שייכים לפרק הקודם - לא רלוונטיים לפרק החדש שנטען
  scheduleSave();
  render();
}

// v2.2.504 — סדר הדוחות (פרקים) ב-PDF: 'primary' + מזהי הפרקים. נשמר ב-state.chapterPrintOrder;
// פרק חדש מצטרף לסוף, פרק שנמחק יוצא. הסדר בעריכה (הכרטיסיות) לא משתנה — רק סדר ההדפסה.
function getChapterPrintOrder(){
  const ids = ['primary'].concat((state.reportChapters || []).map(c=>c.id));
  const saved = Array.isArray(state.chapterPrintOrder) ? state.chapterPrintOrder.filter(id=>ids.includes(id)) : [];
  ids.forEach(id=>{ if(!saved.includes(id)) saved.push(id); });
  return saved;
}
function addNewChapter(formTypeName, label){
  const id = makeChapterId();
  state.reportChapters.push({ id, label: label || formTypeName, snapshot: makeFreshChapterSnapshot(formTypeName) });
  switchToChapter(state.reportChapters.length - 1);
}

function deleteChapter(index){
  const wasActive = state.activeChapterIndex === index;
  state.reportChapters.splice(index, 1);
  if(wasActive){
    state.activeChapterIndex = -1; // חוזרים לראשי בלי לעבור דרך switchToChapter (אין מה "לשמור" מפרק שנמחק)
    if(state.primaryChapterBackup) applyChapterScopedSnapshot(state.primaryChapterBackup);
    openSections.clear(); alreadySeededOpenCards.clear();
  } else if(state.activeChapterIndex > index){
    state.activeChapterIndex--; // האינדקסים שאחרי הנמחק זזו אחורה במערך
  }
  scheduleSave();
  render();
}

