// חישוב תיקון התנגדות כבל הזנה — R = 2×ρ×L/A (Ω). ρ = התנגדות סגולית (Ω·mm²/m), L = אורך
// (מ'), A = שטח חתך (מ"מ²). הכפלה ב-2 כי הבדיקה תמיד מתבצעת עם שני גידים — הזרם עובר הלוך
// (למתקן) וחזור (מהמתקן), כך שההתנגדות הכוללת בנתיב המדידה כפולה מהתנגדות גיד בודד לאורך זה.
// ρ_נחושת = 0.0175 Ω·mm²/m, ρ_אלומיניום = 0.0282 Ω·mm²/m (ערכים סטנדרטיים ב-20°C).
const CABLE_RESISTIVITY = { Cu: 0.0175, Al: 0.0282 };
function calcCableCorrectionResistance(cc){
  const area = parseFloat(cc.crossSection);
  const length = parseFloat(cc.length);
  const rho = CABLE_RESISTIVITY[cc.material] || CABLE_RESISTIVITY.Cu;
  if(!area || area <= 0 || !length || length <= 0) return null;
  return 2 * rho * length / area; // Ω
}
// מפחית את תיקון הכבל מערך התנגדות נמדד (Ω, כמחרוזת) — מחזיר "" אם אין ערך נמדד או תיקון
function applyCableCorrection(measuredStr, correctionOhm){
  const measured = parseFloat(measuredStr);
  if(isNaN(measured) || correctionOhm === null) return "";
  const corrected = measured - correctionOhm;
  return corrected.toFixed(4);
}

