function computeEvDcFullSummary(p2){
  const vi = p2.visualInspection, ft = p2.functionalTests;
  const allChecks = [...vi, ...ft];
  const done = allChecks.filter(c=>c.result==='תקין' || c.result==='לא תקין').length;
  const ok = allChecks.filter(c=>c.result==='תקין').length;
  const bad = allChecks.filter(c=>c.result==='לא תקין').length;
  const notDone = allChecks.length - done - allChecks.filter(c=>c.result==='N.A').length;
  const na = allChecks.filter(c=>c.result==='N.A').length;
  const criticalFindings = p2.findings2.filter(f=>f.severity==='קריטי').length;
  const majorFindings = p2.findings2.filter(f=>f.severity==='חמור').length;
  return { total: allChecks.length, done, ok, bad, notDone, na, criticalFindings, majorFindings };
}

function computeEvDcAutoConclusion2(p2){
  const s = computeEvDcFullSummary(p2);
  if(s.done === 0) return 'undetermined';
  if(s.bad > 0 || s.criticalFindings > 0) return 'bad';
  if(s.notDone > 0) return 'undetermined';
  if(s.majorFindings > 0 || p2.findings2.length > 0) return 'ok_cond';
  return 'ok';
}

function renderEvDcConclusion2Section(p2){
  const s = computeEvDcFullSummary(p2);
  const auto = computeEvDcAutoConclusion2(p2);
  const conclusionOptions = [
    { key:'ok', label:'תקין', text:'הריני מאשר כי בדקתי את עמדת הטעינה ואת המתקן המזין, ובבדיקות שבוצעו נמצאו תקינים בהתאם לקריטריונים שהוגדרו בדוח.' },
    { key:'ok_cond', label:'תקין בתנאי', text:'הריני מאשר את חיבור המתקן בתנאי, וזאת לאחר השלמת תיקון הליקויים המפורטים בדוח.' },
    { key:'bad', label:'לא תקין', text:'המתקן אינו תקין ואינו ראוי לחיבור או להפעלה עד לתיקון הליקויים וביצוע בדיקה חוזרת.' },
    { key:'undetermined', label:'לא ניתן לקבוע', text:'לא ניתן לקבוע תקינות מלאה מאחר שלא כל הבדיקות הנדרשות בוצעו או שחסרים נתונים מהותיים.' }
  ];
  const effectiveKey = p2.conclusion2Key || auto;
  const effectiveText = p2.conclusion2CustomText || conclusionOptions.find(o=>o.key===effectiveKey).text;
  return `
    <section class="card" data-key="ev-conclusion2">
      <div class="card-head" data-toggle="ev-conclusion2">
        <h2><span class="num">11</span> סיכום ומסקנה</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        <table class="dc-summary-table">
          <tr><td>בדיקות שבוצעו</td><td><b>${s.done}</b></td></tr>
          <tr><td>תקינות</td><td><b>${s.ok}</b></td></tr>
          <tr><td>לא תקינות</td><td><b>${s.bad}</b></td></tr>
          <tr><td>לא בוצעו</td><td><b>${s.notDone}</b></td></tr>
          <tr><td>סעיפי N.A</td><td><b>${s.na}</b></td></tr>
          <tr><td>ליקויים קריטיים</td><td><b>${s.criticalFindings}</b></td></tr>
          <tr><td>ליקויים חמורים</td><td><b>${s.majorFindings}</b></td></tr>
        </table>
        <p style="font-size:11px; color:var(--text-dim); margin-top:8px;">מסקנה אוטומטית מוצעת לפי תוצאות הבדיקה: <b>${conclusionOptions.find(o=>o.key===auto).label}</b></p>
        <div class="field"><label>מסקנה</label>
          <select id="evDcConclusion2Select">
            ${conclusionOptions.map(o=>`<option value="${o.key}" ${effectiveKey===o.key?'selected':''}>${o.label}</option>`).join('')}
          </select>
        </div>
        <div class="field"><label>נוסח המסקנה (ניתן לעריכה חופשית)</label>
          <textarea id="evDcConclusion2TextArea" rows="4">${escapeHtml(effectiveText)}</textarea>
        </div>
      </div>
    </section>`;
}

