// קורא ל-admin-create-user Edge Function — service_role לעולם לא חשוף בדפדפן, רק ב-Edge
// Function עצמה בצד השרת. הפונקציה בודקת בעצמה שהמבקש הוא super admin לפני שהיא עושה כלום.
async function createUserViaAdmin(userData){
  if(!supabaseClient) { createUserResult = { success:false, error: 'אין חיבור לענן' }; return; }
  try{
    const { data: sessionData } = await supabaseClient.auth.getSession();
    const accessToken = sessionData && sessionData.session && sessionData.session.access_token;
    if(!accessToken){ createUserResult = { success:false, error: 'לא מחובר' }; return; }
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/admin-create-user`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: userData.email, name: userData.name, role: userData.role, company: userData.company,
        subscriptionStart: userData.subscriptionStart || null, subscriptionEnd: userData.subscriptionEnd || null,
        isSuperAdmin: !!userData.isSuperAdmin
      })
    });
    const body = await resp.json();
    if(!resp.ok){ createUserResult = { success:false, error: body.error || `שגיאה (${resp.status})` }; return; }
    createUserResult = { success:true, email: body.email, tempPassword: body.tempPassword, inviteEmailSent: body.inviteEmailSent };
  }catch(err){
    createUserResult = { success:false, error: err && err.message ? err.message : String(err) };
  }
}

// בודקת חיבור ל-Fireberry דרך fireberry-test-connection Edge Function. אותו דפוס בדיוק
// כמו createUserViaAdmin — Bearer token מה-session של המשתמש עצמו, לא Token של Fireberry
// (שהאפליקציה אף פעם לא רואה בכלל, לא כאן ולא בשום מקום אחר בקוד ה-Frontend).
// *** טעינת הגדרות AI מהענן — נקראת אוטומטית אחרי login/שחזור session (ראו
// refreshCloudUserFromSession). אותו דפוס אבטחה בדיוק כמו testFireberryConnection:
// Bearer token מה-session של המשתמש עצמו. metadata בלבד חוזר — לעולם לא ה-Key הגולמי.
async function loadUserAISettings(){
  if(!supabaseClient || !cloudCurrentUser){ return; }
  try{
    const { data: sessionData } = await supabaseClient.auth.getSession();
    const accessToken = sessionData && sessionData.session && sessionData.session.access_token;
    if(!accessToken) return;
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/ai-settings-get`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
    });
    if(!resp.ok) return; // כשל שקט — לא חוסם את שאר האתחול, ה-UI פשוט יראה "לא מוגדר"
    const body = await resp.json();
    cloudAiSettings = {
      loaded: true, configured: !!body.configured, aiEnabled: !!body.aiEnabled,
      provider: body.provider || 'anthropic', model: body.model || '', keyLast4: body.keyLast4 || '',
      featureWording: body.featureWording !== false, featureSpellcheck: body.featureSpellcheck !== false,
      featureImprove: body.featureImprove !== false,
    };
  }catch(e){ /* offline/רשת נכשלה — cloudAiSettings.loaded נשאר false, ה-UI מטפל בזה */ }
}

// *** שמירת/החלפת הגדרות AI — apiKey אופציונלי (אם לא סופק, רק שדות אחרים מתעדכנים,
// ה-Key הקיים לא נדרס). מחזירה true/false להצלחה; לעולם לא מטפלת ב-Key הגולמי אחרי
// השליחה החד-פעמית הזו — cloudAiSettings מתעדכן רק ממה שהשרת מחזיר (metadata בלבד).
async function saveUserAISettings(payload){
  if(!supabaseClient || !cloudCurrentUser) return false;
  try{
    const { data: sessionData } = await supabaseClient.auth.getSession();
    const accessToken = sessionData && sessionData.session && sessionData.session.access_token;
    if(!accessToken) return false;
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/ai-settings-save`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const body = await resp.json();
    if(!resp.ok){ showToast(body.error || 'שמירת הגדרות AI נכשלה'); return false; }
    cloudAiSettings = {
      loaded: true, configured: !!body.configured, aiEnabled: !!body.aiEnabled,
      provider: body.provider || 'anthropic', model: body.model || '', keyLast4: body.keyLast4 || '',
      featureWording: body.featureWording !== false, featureSpellcheck: body.featureSpellcheck !== false,
      featureImprove: body.featureImprove !== false,
    };
    return true;
  }catch(e){ showToast('שמירת הגדרות AI נכשלה (בעיית רשת)'); return false; }
}

// *** מחיקת ה-API Key (גם מה-Vault בצד שרת, גם מה-metadata) — משבית AI calls עד להזנת Key חדש.
async function deleteUserAIKey(){
  if(!supabaseClient || !cloudCurrentUser) return false;
  try{
    const { data: sessionData } = await supabaseClient.auth.getSession();
    const accessToken = sessionData && sessionData.session && sessionData.session.access_token;
    if(!accessToken) return false;
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/ai-settings-delete`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
    });
    const body = await resp.json();
    if(!resp.ok){ showToast(body.error || 'מחיקת המפתח נכשלה'); return false; }
    cloudAiSettings = { ...cloudAiSettings, configured: false, aiEnabled: false, keyLast4: '' };
    return true;
  }catch(e){ showToast('מחיקת המפתח נכשלה (בעיית רשת)'); return false; }
}

async function testFireberryConnection(){
  if(!supabaseClient){ fireberryConnectionStatus = 'error'; fireberryConnectionError = 'אין חיבור לענן'; render(); return; }
  fireberryConnectionStatus = 'checking';
  fireberryConnectionError = null;
  render();
  try{
    const { data: sessionData } = await supabaseClient.auth.getSession();
    const accessToken = sessionData && sessionData.session && sessionData.session.access_token;
    if(!accessToken){ fireberryConnectionStatus = 'error'; fireberryConnectionError = 'לא מחובר'; render(); return; }
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-test-connection`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' }
    });
    const body = await resp.json();
    if(!resp.ok || body.error){
      fireberryConnectionStatus = 'error';
      fireberryConnectionError = body.error || `שגיאה (${resp.status})`;
    } else if(body.connected){
      fireberryConnectionStatus = 'connected';
      fireberryLastCheckedAt = new Date();
      // שומר רק את תוצאת הבדיקה (מחובר/לא + מתי) — לעולם לא את ה-Token עצמו, שהאפליקציה
      // אף פעם לא רואה בכלל. לפי בקשה מפורשת: לא ללחוץ שוב על "בדוק חיבור" בכל כניסה.
      await persistFireberryConnectionStatus();
    } else {
      fireberryConnectionStatus = 'error';
      fireberryConnectionError = body.error || 'החיבור נכשל';
    }
  }catch(err){
    fireberryConnectionStatus = 'error';
    fireberryConnectionError = err && err.message ? err.message : String(err);
  }
  render();
}

// שומרת/טוענת רק את תוצאת בדיקת החיבור (סטטוס+זמן) — לא את ה-Token, שלעולם לא נגיש
// מהדפדפן. מאפשרת להציג "🟢 מחובר (נבדק לאחרונה: ...)" מיד בכניסה לאפליקציה, בלי חובה
// ללחוץ שוב על "בדוק חיבור" בכל פעם — בדיוק לפי הבקשה.
async function persistFireberryConnectionStatus(){
  try{
    await storageAPI.set('fireberry-last-connection-check', JSON.stringify({
      status: fireberryConnectionStatus,
      lastCheckedAt: fireberryLastCheckedAt ? fireberryLastCheckedAt.toISOString() : null
    }), false);
  }catch(e){ /* כישלון שמירה של תצוגת-מטמון בלבד — לא קריטי, לא חוסם כלום */ }
}

async function loadPersistedFireberryConnectionStatus(){
  try{
    const res = await storageAPI.get('fireberry-last-connection-check', false);
    if(!res || !res.value) return;
    const saved = JSON.parse(res.value);
    if(saved.status === 'connected' && saved.lastCheckedAt){
      // טוען כתוצאה *ידועה-מהעבר* (cached) — לא בדיקה חיה. אם ה-Token הוסר/שונה בענן מאז,
      // זה יתגלה רק בלחיצה הבאה על "בדוק חיבור" (או בבדיקה יזומה עתידית) — אבל לפחות
      // המשתמש לא רואה "טרם נבדק" בכל כניסה מחדש, כמבוקש.
      fireberryConnectionStatus = 'connected';
      fireberryLastCheckedAt = new Date(saved.lastCheckedAt);
    }
  }catch(e){ /* אין cache שמור, או פגום — פשוט נשאר null (טרם נבדק), כמו קודם */ }
}

// בודקת חיבור לחשבונית ירוקה דרך greeninvoice-test-connection Edge Function. אותו דפוס
// בדיוק כמו testFireberryConnection — Bearer token מה-session של המשתמש עצמו, לא Token של
// חשבונית ירוקה (שהאפליקציה אף פעם לא רואה בכלל, לא כאן ולא בשום מקום אחר בקוד ה-Frontend).
// כלי אבחון זמני נוסף — קורא ל-fireberry-list-object-types, מציג את כל סוגי האובייקטים
// הקיימים בחשבון Fireberry הזה (System Name + Object Number לכל אחד) — נדרש כדי לאתר את
// מספר האובייקט המדויק של "פרויקטים", לצורך תכונת יצירת/סנכרון פרויקטים עם Fireberry.
async function callFireberryListObjectTypes(){
  const outEl = document.getElementById('fbDebugRawOutput');
  if(outEl){ outEl.style.display = 'block'; outEl.textContent = '🔄 טוען רשימת סוגי אובייקטים...'; }
  try{
    const token = await getFireberrySessionToken();
    if(!token){ if(outEl) outEl.textContent = 'שגיאה: לא מחובר'; return; }
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-list-object-types`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({})
    });
    const body = await resp.json();
    if(outEl) outEl.textContent = JSON.stringify(body, null, 2);
  }catch(err){
    if(outEl) outEl.textContent = 'שגיאה: ' + (err && err.message ? err.message : String(err));
  }
}

