async function testGreenInvoiceConnection(){
  if(!supabaseClient){ greenInvoiceConnectionStatus = 'error'; greenInvoiceConnectionError = 'אין חיבור לענן'; render(); return; }
  greenInvoiceConnectionStatus = 'checking';
  greenInvoiceConnectionError = null;
  render();
  try{
    const token = await getFireberrySessionToken(); // אותה פונקציית עזר כללית — לא ספציפית ל-Fireberry, למרות השם
    if(!token){ greenInvoiceConnectionStatus = 'error'; greenInvoiceConnectionError = 'לא מחובר'; render(); return; }
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/greeninvoice-test-connection`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' }
    });
    const body = await resp.json();
    if(!resp.ok || body.error){
      greenInvoiceConnectionStatus = 'error';
      greenInvoiceConnectionError = body.error || `שגיאה (${resp.status})`;
    } else if(body.connected){
      greenInvoiceConnectionStatus = 'connected';
      greenInvoiceConnectionEnv = body.environment;
      greenInvoiceLastCheckedAt = new Date();
    } else {
      greenInvoiceConnectionStatus = 'error';
      greenInvoiceConnectionError = body.error || 'החיבור נכשל';
    }
  }catch(err){
    greenInvoiceConnectionStatus = 'error';
    greenInvoiceConnectionError = err && err.message ? err.message : String(err);
  }
  render();
}

// עוזר משותף — session token של המשתמש עצמו, לכל קריאות ה-Fireberry Edge Functions
async function getFireberrySessionToken(){
  if(!supabaseClient) return null;
  const { data: sessionData } = await supabaseClient.auth.getSession();
  return sessionData && sessionData.session && sessionData.session.access_token || null;
}

// מזהה fireberryClientId לפי הלקוח בדוח הנוכחי. סדר עדיפויות: (1) כבר נשמר על הדוח עצמו,
// (2) כבר קושר פעם אחת ללקוח המקומי (clientsList) דרך "קשר ל-Fireberry" בטופס — הדרך
// המהימנה, לא תלויה בהתאמת שם מדויקת, (3) נפילה חזרה לחיפוש-שם אוטומטי (עלול לא למצוא
// אם השם לא זהה מילה-במילה ל-Fireberry — לכן (2) עדיף ומומלץ).
async function resolveFireberryClientId(){
  if(state.meta.fireberryClientId) return state.meta.fireberryClientId;
  const clientName = (state.meta.client || '').trim();
  if(!clientName){ fireberryClientResolveError = 'אין שם לקוח בדוח'; return null; }
  const localClient = findClientByName(clientName);
  if(localClient && localClient.fireberryClientId){
    state.meta.fireberryClientId = localClient.fireberryClientId;
    scheduleSave();
    return localClient.fireberryClientId;
  }
  fireberryClientResolving = true; fireberryClientResolveError = null; render();
  try{
    const token = await getFireberrySessionToken();
    if(!token){ fireberryClientResolveError = 'לא מחובר'; return null; }
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-search-clients`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ search: clientName })
    });
    const body = await resp.json();
    if(!resp.ok || body.error){ fireberryClientResolveError = body.error || `שגיאה (${resp.status})`; return null; }
    const exact = (body.results||[]).find(r => r.name === clientName);
    const best = exact || (body.results||[])[0];
    if(!best){ fireberryClientResolveError = `לא נמצא לקוח תואם ל-"${clientName}" ב-Fireberry — מומלץ לקשר את הלקוח באופן קבוע דרך "קשר ל-Fireberry" בסעיף 01`; return null; }
    state.meta.fireberryClientId = best.fireberryClientId;
    scheduleSave();
    return best.fireberryClientId;
  }catch(err){
    fireberryClientResolveError = err && err.message ? err.message : String(err);
    return null;
  }finally{
    fireberryClientResolving = false; render();
  }
}

// מחפשת זימונים תואמים ללקוח+תאריך הבדיקה. התאמה אוטומטית: אם נמצא זימון אחד ברור — מסמן
// אותו, אך המשתמש עדיין יכול לשנות. כמה זימונים — לא בוחר לבד. אין זימון — מאפשר להמשיך
// בלי קישור. לא יוצר זימון חדש אף פעם — לפי בקשה מפורשת בשלושת המקרים.
async function searchFireberryMeetingsForCurrentReport(){
  fireberryMeetingsSearching = true; fireberryMeetingsError = null; fireberryMeetingsFound = []; render();
  try{
    const clientId = await resolveFireberryClientId();
    if(!clientId){ fireberryMeetingsError = fireberryClientResolveError || 'לא ניתן לזהות לקוח'; return; }
    const token = await getFireberrySessionToken();
    if(!token){ fireberryMeetingsError = 'לא מחובר'; return; }
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-search-meetings`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ fireberryClientId: clientId, inspectionDate: state.meta.date || '' })
    });
    const body = await resp.json();
    if(!resp.ok || body.error){ fireberryMeetingsError = body.error || `שגיאה (${resp.status})`; return; }
    fireberryMeetingsFound = body.meetings || [];
    if(fireberryMeetingsFound.length === 0){
      fireberryMeetingsError = 'לא נמצא זימון מתאים ב-Fireberry';
    } else if(fireberryMeetingsFound.length === 1){
      fireberrySelectedMeetingId = fireberryMeetingsFound[0].fireberryMeetingId; // התאמה אוטומטית — זימון יחיד וברור
    }
    // אם יש כמה — משאירים fireberrySelectedMeetingId ריק, המשתמש חייב לבחור בעצמו
  }catch(err){
    fireberryMeetingsError = err && err.message ? err.message : String(err);
  }finally{
    fireberryMeetingsSearching = false; render();
  }
}

function openFireberryFinalizeModal(){
  document.getElementById('fireberryFinalizationModal').classList.add('show');
  renderFireberryFinalizeModalBody();
  // אם כבר קיים קישור (נבחר קודם דרך החלונית המאוחדת) — לא מחפשים מחדש, לפי בקשה מפורשת:
  // "אם כבר בחרתי וקישרתי Fireberry קודם: אל תחפש שוב. טען את fireberryClientId/MeetingId".
  if(fireberrySyncEnabled && fireberryLinkToMeeting && !state.meta.fireberryMeetingId) searchFireberryMeetingsForCurrentReport();
}

function closeFireberryFinalizeModal(){
  document.getElementById('fireberryFinalizationModal').classList.remove('show');
}

// בונה PDF אמיתי (בייטים) מאותו תוכן בדיוק כמו הדוח שנשלח/מודפס — לא PDF נפרד לצורך
// Fireberry, לפי בקשה מפורשת. משתמשת באותה שיטת jsPDF+html2canvas שכבר קיימת ופעילה
// (exportRealPdf) — לא בונה מסלול ייצור PDF מקביל.
async function buildReportPdfBase64(){
  if(typeof window.jspdf === 'undefined' || typeof window.html2canvas === 'undefined'){
    throw new Error('ספריות ה-PDF לא נטענו — בדוק חיבור לאינטרנט ונסה שוב');
  }
  const reportHtml = buildPrintReport(excludedSections instanceof Set ? excludedSections : new Set());
  const container = document.createElement('div');
  container.style.cssText = 'position:fixed; top:0; left:-99999px; width:794px; background:#fff; direction:rtl;';
  container.innerHTML = `<div style="padding:30px; font-family:Arial, Tahoma, sans-serif; color:#000;">${reportHtml}</div>`;
  document.body.appendChild(container);
  try{
    await new Promise(r => setTimeout(r, 250));
    const canvas = await html2canvas(container, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF('p', 'mm', 'a4');
    const pageWidthMm = 210, pageHeightMm = 297;
    const imgWidthMm = pageWidthMm;
    const imgHeightMm = (canvas.height * imgWidthMm) / canvas.width;
    const imgData = canvas.toDataURL('image/jpeg', 0.92);
    let heightLeft = imgHeightMm, position = 0;
    pdf.addImage(imgData, 'JPEG', 0, position, imgWidthMm, imgHeightMm);
    heightLeft -= pageHeightMm;
    while(heightLeft > 0){
      position = heightLeft - imgHeightMm;
      pdf.addPage();
      pdf.addImage(imgData, 'JPEG', 0, position, imgWidthMm, imgHeightMm);
      heightLeft -= pageHeightMm;
    }
    const arrayBuffer = pdf.output('arraybuffer');
    const bytes = new Uint8Array(arrayBuffer);
    let binary = '';
    for(let i=0; i<bytes.length; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  }finally{
    document.body.removeChild(container);
  }
}

// מבצעת את הסנכרון בפועל — עם אידמפוטנטיות מלאה: מעבירה ל-Backend מה כבר הצליח (state.meta.
// fireberry*Synced), כדי ש-Retry ידלג על שלבים שכבר הצליחו ויתמקד רק במה שנכשל. לפי בקשה
// מפורשת: "אם העלאה ללקוח הצליחה והעלאה לזימון נכשלה, שמור סטטוס חלקי ואפשר Retry רק לזימון".
async function executeFireberrySync(){
  if(!fireberrySyncEnabled){ return; } // בלי checkbox ראשי — אפס קריאות Fireberry, אין מה לעשות כאן בכלל
  fireberrySyncing = true; fireberrySyncResult = null; render();
  try{
    const clientId = await resolveFireberryClientId();
    if(!clientId){
      fireberrySyncResult = { status:'failed', errors:{ client: fireberryClientResolveError || 'לא ניתן לזהות לקוח' } };
      return;
    }
    const pdfBase64 = await buildReportPdfBase64();
    const filename = buildReportFilename();
    let jsonContent = null;
    if(fireberryBackupJsonOpt){
      jsonContent = JSON.stringify({ meta: state.meta, reportType: getReportType(), version: APP_VERSION }, null, 2);
    }
    const token = await getFireberrySessionToken();
    if(!token){ fireberrySyncResult = { status:'failed', errors:{ client:'לא מחובר' } }; return; }

    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-sync-report`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        fireberryClientId: clientId,
        fireberryMeetingId: fireberryLinkToMeeting ? fireberrySelectedMeetingId : '',
        pdfBase64, pdfFilename: filename + '.pdf',
        jsonContent, jsonFilename: filename + '.json',
        saveToClient: fireberrySaveToClient,
        linkToMeeting: fireberryLinkToMeeting,
        attachPdfToMeeting: fireberryAttachPdfToMeeting,
        backupJson: fireberryBackupJsonOpt,
        // אידמפוטנטיות: מעבירים מה כבר הצליח בעבר על הדוח הזה, כדי ש-Retry לא יעלה פעמיים
        alreadySynced: {
          client: !!state.meta.fireberryClientFileSynced,
          meeting: !!state.meta.fireberryMeetingFileSynced,
          json: !!state.meta.fireberryJsonSynced,
        }
      })
    });
    const body = await resp.json();
    if(!resp.ok || body.error){
      fireberrySyncResult = { status:'failed', errors:{ client: body.error || `שגיאה (${resp.status})` } };
      return;
    }
    // שמירת התוצאה ברשומת הדוח — כולל דגלי האידמפוטנטיות המעודכנים
    state.meta.fireberryClientFileSynced = !!body.clientFileSynced;
    state.meta.fireberryMeetingFileSynced = !!body.meetingFileSynced;
    state.meta.fireberryJsonSynced = !!body.jsonSynced;
    state.meta.fireberrySyncStatus = body.status;
    state.meta.fireberryLastError = JSON.stringify(body.errors || {});
    if(fireberryLinkToMeeting && fireberrySelectedMeetingId){
      const m = fireberryMeetingsFound.find(x => x.fireberryMeetingId === fireberrySelectedMeetingId);
      state.meta.fireberryMeetingId = fireberrySelectedMeetingId;
      if(m){ state.meta.fireberryMeetingSubject = m.subject; state.meta.fireberryMeetingStart = m.start; state.meta.fireberryMeetingEnd = m.end; }
    }
    scheduleSave();
    fireberrySyncResult = body;
  }catch(err){
    fireberrySyncResult = { status:'failed', errors:{ client: err && err.message ? err.message : String(err) } };
  }finally{
    fireberrySyncing = false; render();
    renderFireberryFinalizeModalBody();
  }
}

