function cloudDebugLog(label, details){
  if(!cloudDebugMode) return;
  const time = new Date().toLocaleTimeString('he-IL');
  if(details !== undefined) console.log(`[CLOUD ${time}] ${label}`, details);
  else console.log(`[CLOUD ${time}] ${label}`);
}

