function renderClientsView(){
  // מקור הנתונים: Supabase כשמחוברים (PHASE 2) — נופל חזרה ל-clientsList המקומי (עדיין נשמר
  // כ-cache/offline, לא נמחק) רק כשאין חיבור ענן פעיל.
  const usingCloud = !!(supabaseClient && cloudCurrentUser);
  const sourceList = usingCloud && cloudClientsCache !== null
    ? cloudClientsCache.map(normalizeCloudClient)
    : clientsList.map(c => ({...c, source: 'local'}));

  const q = clientSearchQuery.trim().toLowerCase();
  const filtered = !q ? sourceList : sourceList.filter(c =>
    (c.name||'').toLowerCase().includes(q) ||
    (c.contacts||[]).some(ct => (ct.name||'').toLowerCase().includes(q) || (ct.phone||'').includes(q)) ||
    (c.emails||[]).some(e => (e||'').toLowerCase().includes(q))
  );

  const sorted = filtered.slice().sort((a,b)=> a.name.localeCompare(b.name, 'he'));
  const items = sorted.map(c=>{
    const contacts = (c.contacts||[]).filter(ct=>ct.name||ct.phone);
    const emails = (c.emails||[]).filter(Boolean);
    const isExpanded = expandedClientId === c.id;
    const newProjectName = clientProjectNameDraft[c.id] || '';

    const contactsHtml = contacts.length
      ? `<div class="draft-card-date">${contacts.map(ct=>escapeHtml([ct.name, ct.phone].filter(Boolean).join(' - '))).join(' | ')}</div>` : '';
    const emailsHtml = emails.length
      ? `<div class="draft-card-date">${emails.map(escapeHtml).join(', ')}</div>` : '';

    let projectsHtml = '';
    if(isExpanded){
      const projects = c.source === 'cloud' ? cloudProjectsByClient[c.id] : (findLocalClientById(c.id)||{}).projects || [];
      const projectsListHtml = projects === undefined || projects === null
        ? '<div class="empty-hint" style="padding:8px;">⏳ טוען פרויקטים...</div>'
        : (projects.map(p=>`
          <div class="project-row">
            <span>${escapeHtml(p.name)}</span>
            <button type="button" class="del-panel-btn" data-delproject="${c.id}|${p.id}" data-clientsource="${c.source}">מחק</button>
          </div>`).join('') || '<div class="empty-hint" style="padding:8px;">אין פרויקטים עדיין</div>');
      projectsHtml = `
        <div class="subhead" style="margin-top:10px; font-size:12px;">פרויקטים אצל לקוח זה</div>
        <div class="decl-list" style="margin-top:4px;">${projectsListHtml}</div>
        <div class="project-add-row">
          <input type="text" placeholder="שם פרויקט חדש..." data-newprojectname="${c.id}" value="${escapeAttr(newProjectName)}">
          <button type="button" class="add-btn" data-addproject="${c.id}" data-clientsource="${c.source}">+ הוסף פרויקט</button>
        </div>`;
    }

    return `<div class="draft-card client-card">
      <div class="draft-card-info" data-toggleclientprojects="${c.id}" data-clientsource="${c.source}" style="cursor:pointer;">
        <div class="draft-card-name">${escapeHtml(c.name)} <span style="color:var(--text-dim); font-size:11px;">${isExpanded?'▾':'▸'} ${c.source==='cloud'?'☁️':'💾'}</span></div>
        <div class="draft-card-date">${escapeHtml(c.address||'')}</div>
        ${contactsHtml}
        ${emailsHtml}
      </div>
      ${projectsHtml}
      <div class="draft-card-actions">
        <button type="button" class="today-btn" data-editclient="${c.id}" data-clientsource="${c.source}">ערוך</button>
        ${clientDeleteConfirmId === c.id
          ? `<button type="button" class="del-panel-btn confirm-armed" data-delclient-confirm="${c.id}" data-clientsource="${c.source}">בטוח? מחק סופית</button>`
          : `<button type="button" class="del-panel-btn" data-delclient="${c.id}">מחק</button>`}
      </div>
    </div>`;
  }).join('');

  const contactsFormHtml = (clientFormDraft.contacts||[]).map((ct,i)=>`
    <div class="project-row">
      <input type="text" placeholder="שם איש קשר *" data-clientcontact="${i}|name" value="${escapeAttr(ct.name)}">
      <input type="tel" placeholder="טלפון *" data-restrict="digits" data-clientcontact="${i}|phone" value="${escapeAttr(ct.phone)}">
      <button type="button" class="del-panel-btn" data-delcontact="${i}">מחק</button>
    </div>`).join('');

  const emailsFormHtml = (clientFormDraft.emails||[]).map((em,i)=>`
    <div class="project-row">
      <input type="email" placeholder="דוא&quot;ל *" data-restrict="email" data-clientemail="${i}" value="${escapeAttr(em)}">
      <button type="button" class="del-panel-btn" data-delemail="${i}">מחק</button>
    </div>`).join('');

  const sourceLabel = usingCloud
    ? `<p style="font-size:12px; color:var(--text-dim); margin-top:0;">☁️ מקור: ענן — מסונכרן בין כל המכשירים המחוברים לאותה חברה.</p>`
    : `<p style="font-size:12px; color:var(--amber); margin-top:0;">💾 מקור: מקומי בלבד (לא מחובר לענן).</p>`;
  const refreshBtn = usingCloud
    ? `<button type="button" class="add-btn" id="btnRefreshCloudClients" ${cloudClientsLoading?'disabled':''}>${cloudClientsLoading ? '⏳ טוען...' : '🔄 רענן'}</button>`
    : '';

  return `
    <section class="card open" data-key="clients">
      <div class="card-head" data-toggle="clients">
        <h2>🗂️ לקוחות (${sorted.length})</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        ${sourceLabel}
        <p style="font-size:12.5px; color:var(--text-dim); margin-top:0;">
          נהל כאן את רשימת הלקוחות, אנשי הקשר, והפרויקטים של כל לקוח. בטופס הבדיקה, בחירת לקוח + פרויקט תארגן את הדוחות והטיוטות יחד לפי לקוח ופרויקט.
        </p>
        <div style="display:flex; gap:8px; align-items:flex-end;">
          <div class="field" style="flex:1;"><label>חפש (שם / איש קשר / טלפון / מייל)</label>
            <input type="text" id="clientSearchInput" value="${escapeAttr(clientSearchQuery)}"></div>
          ${refreshBtn}
        </div>
        <div class="subhead">${clientFormDraft.id ? 'עריכת לקוח' : 'הוספת לקוח חדש'}</div>
        <p style="font-size:11.5px; color:var(--text-dim); margin-top:0;">שדות עם * הם שדות חובה — יש למלא את כולם כדי לשמור לקוח.</p>
        <div class="grid2">
          <div class="field"><label>שם הלקוח *</label><input type="text" data-clientfield="name" value="${escapeAttr(clientFormDraft.name)}"></div>
          <div class="field"><label>כתובת *</label><input type="text" data-clientfield="address" value="${escapeAttr(clientFormDraft.address)}"></div>
        </div>

        <div class="subhead" style="font-size:12px;">אנשי קשר</div>
        ${contactsFormHtml}
        <button type="button" class="add-btn" id="btnAddContact">+ הוסף איש קשר</button>

        <div class="subhead" style="font-size:12px;">כתובות דוא"ל</div>
        ${emailsFormHtml}
        <button type="button" class="add-btn" id="btnAddEmail">+ הוסף מייל</button>

        <div class="grid2" style="margin-top:14px;">
          <button type="button" class="add-panel-card" id="btnSaveClient">💾 ${clientFormDraft.id ? 'עדכן לקוח' : 'הוסף לקוח'}</button>
          ${clientFormDraft.id ? `<button type="button" class="add-panel-card" id="btnCancelEditClient">✕ בטל עריכה</button>` : ''}
        </div>
        <div class="draft-list" style="margin-top:14px;">
          ${items || '<div class="empty-hint">אין לקוחות שמורים עדיין</div>'}
        </div>
      </div>
    </section>`;
}

function findLocalClientById(id){
  return clientsList.find(c=>c.id===id);
}

function normalizeCloudEquipment(row){
  return { id: row.id, source: 'cloud', name: row.name || '', model: row.model || '', serialNo: row.serial_no || '', calibrationDate: row.calibration_date || '' };
}

function renderEquipmentView(){
  const usingCloud = !!(supabaseClient && cloudCurrentUser);
  const sourceList = usingCloud && cloudEquipmentCache !== null
    ? cloudEquipmentCache.map(normalizeCloudEquipment)
    : equipmentList.map(e => ({...e, source: 'local'}));

  const sorted = sourceList.slice().sort((a,b)=> a.name.localeCompare(b.name, 'he'));
  const items = sorted.map(e=>{
    const calStatus = getCalibrationStatus(e.calibrationDate);
    // צביעה כתומה (מתקרב לפוג תוקף, עד חודשיים) / אדומה (פג תוקף בפועל) — לפי בקשה מפורשת
    const nameColor = calStatus === 'expired' ? 'var(--bad,#d9534f)' : (calStatus === 'warning' ? '#e08a00' : 'inherit');
    const calBadge = calStatus === 'expired' ? ' ⚠️ פג תוקף כיול'
      : calStatus === 'warning' ? ' ⚠️ תוקף הכיול מתקרב לסיום'
      : '';
    return `
    <div class="draft-card">
      <div class="draft-card-info">
        <div class="draft-card-name" style="color:${nameColor};">${escapeHtml(e.name)} <span style="color:var(--text-dim); font-size:11px;">${e.source==='cloud'?'☁️':'💾'}</span>${calBadge ? `<span style="color:${nameColor}; font-size:11px; font-weight:600;">${calBadge}</span>` : ''}</div>
        <div class="draft-card-date">
          ${e.model ? 'דגם: '+escapeHtml(e.model) : ''}${e.serialNo ? ' • מס\' סידורי: '+escapeHtml(e.serialNo) : ''}${e.calibrationDate ? ' • תוקף כיול: '+formatDateIL(e.calibrationDate) : ''}
        </div>
      </div>
      <div class="draft-card-actions">
        <button type="button" class="today-btn" data-editequipment="${e.id}" data-equipsource="${e.source}">ערוך</button>
        ${equipmentDeleteConfirmId === e.id
          ? `<button type="button" class="del-panel-btn confirm-armed" data-delequipment-confirm="${e.id}" data-equipsource="${e.source}">בטוח? מחק סופית</button>`
          : `<button type="button" class="del-panel-btn" data-delequipment="${e.id}">מחק</button>`}
      </div>
    </div>`;
  }).join('');

  const sourceLabel = usingCloud
    ? `<p style="font-size:12px; color:var(--text-dim); margin-top:0;">☁️ מקור: ענן — מסונכרן בין כל המכשירים המחוברים לאותה חברה.</p>`
    : `<p style="font-size:12px; color:var(--amber); margin-top:0;">💾 מקור: מקומי בלבד (לא מחובר לענן).</p>`;
  const refreshBtn = usingCloud
    ? `<button type="button" class="add-btn" id="btnRefreshCloudEquipment" ${cloudEquipmentLoading?'disabled':''}>${cloudEquipmentLoading ? '⏳ טוען...' : '🔄 רענן'}</button>`
    : '';

  return `
    <section class="card open" data-key="equipment">
      <div class="card-head" data-toggle="equipment">
        <h2>🔧 מכשירי בדיקה (${sorted.length})</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        ${sourceLabel}
        <p style="font-size:12.5px; color:var(--text-dim); margin-top:0;">
          נהל כאן את רשימת מכשירי הבדיקה שברשותך — שם המכשיר, דגם, מספר סידורי, ותאריך כיול.
        </p>
        ${refreshBtn}
        <div class="subhead">${equipmentFormDraft.id ? 'עריכת מכשיר' : 'הוספת מכשיר חדש'}</div>
        <div class="grid2">
          <div class="field"><label>שם המכשיר</label><input type="text" data-equipfield="name" value="${escapeAttr(equipmentFormDraft.name)}"></div>
          <div class="field"><label>דגם</label><input type="text" data-equipfield="model" value="${escapeAttr(equipmentFormDraft.model)}"></div>
          <div class="field"><label>מס' סידורי</label><input type="text" data-equipfield="serialNo" value="${escapeAttr(equipmentFormDraft.serialNo)}"></div>
          <div class="field"><label>תאריך כיול</label><input type="date" data-equipfield="calibrationDate" value="${escapeAttr(equipmentFormDraft.calibrationDate)}"></div>
        </div>
        <div class="grid2">
          <button type="button" class="add-panel-card" id="btnSaveEquipment">💾 ${equipmentFormDraft.id ? 'עדכן מכשיר' : 'הוסף מכשיר'}</button>
          ${equipmentFormDraft.id ? `<button type="button" class="add-panel-card" id="btnCancelEditEquipment">✕ בטל עריכה</button>` : ''}
        </div>
        <div class="draft-list" style="margin-top:14px;">
          ${items || '<div class="empty-hint">אין מכשירים שמורים עדיין</div>'}
        </div>
      </div>
    </section>`;
}

function normalizeInsulation(saved, template){
  let rows;
  if(Array.isArray(saved) && saved.length){
    rows = saved; // oldest format: plain array, no unit at all
  } else if(saved && Array.isArray(saved.rows) && saved.rows.length){
    rows = saved.rows; // either {unit, rows} (table-wide) or {rows:[{...,unit}]} (per-row)
  } else {
    return template;
  }
  const fallbackUnit = (saved && saved.unit) || 'MΩ';
  return { rows: rows.map(r=>({
    r15: r.r15||'', r60: r.r60||'', dar: r.dar||'', note: r.note||'', unit: r.unit || fallbackUnit
  })) };
}

function normalizeDccb(saved){
  // New format: already a dynamic array
  if(Array.isArray(saved) && saved.length){
    return saved.map(v=>({
      name: v.name||'', torque: v.torque||'', cleaning: v.cleaning||''
    }));
  }
  // Legacy formats: object keyed by DCCB1..DCCB11 (either flat status strings or {torque,cleaning} objects)
  if(saved && typeof saved === 'object'){
    const keys = Object.keys(saved);
    if(keys.length){
      return keys.map(id=>{
        const v = saved[id];
        if(typeof v === 'string'){
          return { name:id, torque: v, cleaning: '' };
        }
        return { name:id, torque: (v&&v.torque)||'', cleaning: (v&&v.cleaning)||'' };
      });
    }
  }
  return [ makeDccbItem('DCCB1') ];
}

function normalizeDps(saved){
  // New format: already a dynamic array
  if(Array.isArray(saved) && saved.length){
    return saved.map(v=>({
      name: v.name||'', wiresPlus: v.wiresPlus||'2', wiresMinus: v.wiresMinus||'2',
      torque: v.torque||'', cleaning: v.cleaning||'', filterReplace: v.filterReplace||'', notes: v.notes||''
    }));
  }
  // Legacy formats: object keyed by DPS1..DPS6 (either flat status strings or detail objects)
  if(saved && typeof saved === 'object'){
    const keys = Object.keys(saved);
    if(keys.length){
      return keys.map(id=>{
        const v = saved[id];
        if(typeof v === 'string'){
          return { name:id, wiresPlus:'2', wiresMinus:'2', torque:v, cleaning:'', filterReplace:'', notes:'' };
        }
        return {
          name:id, wiresPlus: v.wiresPlus||'2', wiresMinus: v.wiresMinus||'2',
          torque: v.torque||'', cleaning: v.cleaning||'', filterReplace: v.filterReplace||'', notes: v.notes||''
        };
      });
    }
  }
  return [ makeDpsItem('DPS1') ];
}

function mergeDefaults(base, loaded){
  try{
    const merged = Object.assign({}, base, loaded);
    merged.meta = Object.assign({}, base.meta, loaded.meta || {});
    merged.settings = Object.assign({}, base.settings, loaded.settings || {});
    merged.declarationsOn = DECLARATIONS.map((_,i)=>{
      const saved = loaded.declarationsOn || (loaded.settings && loaded.settings.declarationsOn);
      return (Array.isArray(saved) && typeof saved[i]==='boolean') ? saved[i] : true;
    });
    merged.customDeclaration = (loaded.customDeclaration !== undefined) ? loaded.customDeclaration
      : ((loaded.settings && loaded.settings.customDeclaration) || '');
    merged.showElectricianDeclaration = (loaded.showElectricianDeclaration !== undefined) ? loaded.showElectricianDeclaration
      : ((loaded.settings && loaded.settings.showElectricianDeclaration !== undefined) ? loaded.settings.showElectricianDeclaration : true);
    merged.electricianDeclarationText = (loaded.electricianDeclarationText !== undefined) ? loaded.electricianDeclarationText
      : ((loaded.settings && loaded.settings.electricianDeclarationText) || ELECTRICIAN_DECLARATION);


    // soil resistivity report data — deep-merge against defaults so older saves without this section still work
    const soilBase = base.soilTest;
    const soilSaved = loaded.soilTest || {};
    merged.soilTest = {
      purpose: {
        reasons: Object.assign({}, soilBase.purpose.reasons, soilSaved.purpose && soilSaved.purpose.reasons),
        notes: (soilSaved.purpose && soilSaved.purpose.notes) || ''
      },
      scope: Object.assign({}, soilBase.scope, soilSaved.scope),
      standardsOn: RESISTIVITY_STANDARDS.map((_,i)=>{
        const saved = soilSaved.standardsOn;
        return (Array.isArray(saved) && typeof saved[i]==='boolean') ? saved[i] : true;
      }),
      equipment: (Array.isArray(soilSaved.equipment) && soilSaved.equipment.length) ? soilSaved.equipment : soilBase.equipment.map(e=>Object.assign({},e)),
      methodNotes: soilSaved.methodNotes || '',
      methodPhotos: Array.isArray(soilSaved.methodPhotos) ? soilSaved.methodPhotos
        : (soilSaved.methodSketch ? [{id:'legacy_sketch', dataUrl:soilSaved.methodSketch, title:'סקיצת סידור האלקטרודות', note:''}] : []),
      locations: (Array.isArray(soilSaved.locations) && soilSaved.locations.length) ? soilSaved.locations : soilBase.locations.map(l=>Object.assign({},l)),
      locationPhotos: Array.isArray(soilSaved.locationPhotos) ? soilSaved.locationPhotos
        : (soilSaved.aerialPhoto ? [{id:'legacy_aerial', dataUrl:soilSaved.aerialPhoto, title:'תצלום אוויר', note:''}] : []),
      environment: Object.assign({}, soilBase.environment, soilSaved.environment),
      resistivityData: (Array.isArray(soilSaved.resistivityData) && soilSaved.resistivityData.length)
        ? soilSaved.resistivityData.map(loc=>({
            name: loc.name || '',
            northSouth: RESISTIVITY_DISTANCES.map((_,i)=> (loc.northSouth && loc.northSouth[i]) || ''),
            eastWest: RESISTIVITY_DISTANCES.map((_,i)=> (loc.eastWest && loc.eastWest[i]) || '')
          }))
        : soilBase.resistivityData.map(l=>JSON.parse(JSON.stringify(l))),
      graphs: Array.isArray(soilSaved.graphs) ? soilSaved.graphs : [],
      engineeringAnalysis: soilSaved.engineeringAnalysis || '',
      conclusions: soilSaved.conclusions || '',
      recommendations: soilSaved.recommendations || '',
      appendixPhotos: Array.isArray(soilSaved.appendixPhotos) ? soilSaved.appendixPhotos : [],
      translatedEn: Object.assign({purposeNotes:"", methodNotes:"", engineeringAnalysis:"", conclusions:"", recommendations:""}, soilSaved.translatedEn)
    };

    // mainPanelReport — מיזוג מפורש, לא רק Object.assign שטחי ברמה העליונה: בלי זה, שדה חדש
    // שנוסף ישירות ל-mainPanelReport (למשל testInstruments ב-v2.190, accompaniedBy ב-v2.184)
    // אחרי ששמורה נתונים ישנה יותר — נעלם לגמרי, כי loaded.mainPanelReport כולו מחליף את
    // base.mainPanelReport (לא ממוזג שדה-שדה). זו סיבת שורש שנייה, נפרדת מנרמול facilities[]
    // (מטופל בנפרד ב-boot, כי זה מערך אובייקטים דינמיים, לא שדה קבוע).
    const mpBase = base.mainPanelReport;
    const mpSaved = loaded.mainPanelReport || {};
    merged.mainPanelReport = {
      protectionMethod: mpSaved.protectionMethod || mpBase.protectionMethod,
      electricalApproval: mpSaved.electricalApproval || mpBase.electricalApproval,
      accompaniedBy: mpSaved.accompaniedBy || mpBase.accompaniedBy,
      testInstruments: Array.isArray(mpSaved.testInstruments) ? mpSaved.testInstruments : mpBase.testInstruments,
      facilities: Array.isArray(mpSaved.facilities) ? mpSaved.facilities : mpBase.facilities,
      summaryItems: Array.isArray(mpSaved.summaryItems) ? mpSaved.summaryItems : mpBase.summaryItems,
      // מסדר מתח גבוה ראשי (v2.202) — שדה מקונן עמוק (assemblyDetails/checklist/panelRows בתוכו),
      // deepMergeGeneric ממלא כל שדה חסר בכל עומק קינון בבת אחת, בלי צורך לפרט כל שדה ידנית —
      // אותה תבנית בדיוק כמו soilTest/evDcReport, כדי שדוח ישן (בלי mainSwitchgear בכלל,
      // מלפני שהוא נוסף) לא יקרוס בטעינה (אותה מחלקת באג שתוקנה ב-v2.195-196).
      mainSwitchgear: deepMergeGeneric(mpBase.mainSwitchgear, mpSaved.mainSwitchgear),
      // תאי מתח גבוה (v2.203) — מערך דינמי, כמו facilities: אם קיים ב-loaded נכנס כמות שהוא,
      // אחרת נופל לברירת מחדל ריקה — לא צריך deepMerge פר-פריט כי makeHvCell() הפשוט לא
      // משתנה בקרוב, ופריטים חדשים שכבר יש להם את כל השדות (הועתקו ישירות מ-SMA שכבר קיים).
      hvCells: Array.isArray(mpSaved.hvCells) ? mpSaved.hvCells : mpBase.hvCells,
      // בדיקות בידוד (v2.213) — אותה גישה בדיוק כמו mainSwitchgear: deepMergeGeneric ממלא כל
      // שדה חסר בעומק, כדי שדוח ישן (מלפני שהסעיף נוסף) לא יקרוס בטעינה.
      insulationTests: deepMergeGeneric(mpBase.insulationTests, mpSaved.insulationTests)
    };

    // generalElectricalInspectionReport — אותה בעיה בדיוק, אובייקט גדול יותר עם הרבה שדות
    // ישירים (reportDetails, testInstruments, inspectionItems, boards, finalCircuits,
    // hvSwitchgear, summaryRows, conclusionKey ועוד) — deepMergeDefaults הגנרי ממלא את כולם
    // בבת אחת בלי לפרט כל שדה ידנית. installations מטופל בנפרד (מערך אובייקטים דינמי, מיזוג
    // פר-פריט משלו כבר קיים ב-boot) — לכן משמרים כאן את הגרסה הגולמית של loaded, לא נוגעים.
    const geiBase = base.generalElectricalInspectionReport;
    const geiSaved = loaded.generalElectricalInspectionReport || {};
    const geiSavedInstallations = geiSaved.installations;
    merged.generalElectricalInspectionReport = deepMergeGeneric(geiBase, { ...geiSaved, installations: [] });
    merged.generalElectricalInspectionReport.installations = Array.isArray(geiSavedInstallations) ? geiSavedInstallations : geiBase.installations;

    const groundBase = base.groundingTest;
    const groundSaved = loaded.groundingTest || {};
    merged.groundingTest = {
      siteEquipmentName: groundSaved.siteEquipmentName || '',
      instrumentName: groundSaved.instrumentName || '',
      instrumentModel: groundSaved.instrumentModel || '',
      instrumentSerial: groundSaved.instrumentSerial || '',
      currentStakeDistance: groundSaved.currentStakeDistance || groundBase.currentStakeDistance,
      measurementPeriod: groundSaved.measurementPeriod || '',
      maxAllowedResistance: groundSaved.maxAllowedResistance || '',
      standardsOn: GROUNDING_STANDARDS.map((_,i)=>{
        const saved = groundSaved.standardsOn;
        return (Array.isArray(saved) && typeof saved[i]==='boolean') ? saved[i] : true;
      }),
      locations: (Array.isArray(groundSaved.locations) && groundSaved.locations.length)
        ? groundSaved.locations.map(l=>({
            name: l.name || '',
            readings: (l.readings && typeof l.readings === 'object' && !Array.isArray(l.readings))
              ? { r52: l.readings.r52||'', r62: l.readings.r62||'', r72: l.readings.r72||'' }
              : { r52:'', r62:'', r72:'' } // old array-based format from an earlier version — can't map distanceLabel to percentages, reset
          }))
        : groundBase.locations.map(l=>JSON.parse(JSON.stringify(l))),
      connectionPhotos: Array.isArray(groundSaved.connectionPhotos) ? groundSaved.connectionPhotos : [],
      customDiagramImage: groundSaved.customDiagramImage || '',
      notes: groundSaved.notes || '',
      notesPhotos: Array.isArray(groundSaved.notesPhotos) ? groundSaved.notesPhotos : [],
      // *** שדות חדשים (testMethod/clamp/selective) — נוספו לאותו בלוק deep-merge קיים,
      // לא בלוק נפרד. דוח ישן (בלי השדות האלה כלל) -> נופל לברירת המחדל כאן ('slope',
      // מערכים ריקים). כל רשומת clamp/selective ממוזגת עם makeGroundingClampTest/
      // makeGroundingSelectiveTest טרי (לא רק Array.isArray check) — כדי שגם אם שדה
      // ספציפי יתווסף בעתיד לרשומה, רשומות שמורות ישנות יקבלו אותו כברירת מחדל ולא
      // "יאבדו" שדות בטעינה חוזרת.
      testMethod: (groundSaved.testMethod === 'clamp' || groundSaved.testMethod === 'selective') ? groundSaved.testMethod : 'slope',
      clampTests: Array.isArray(groundSaved.clampTests)
        ? groundSaved.clampTests.map(t => Object.assign(makeGroundingClampTest(), t, { id: (t && t.id) || (crypto && crypto.randomUUID ? crypto.randomUUID() : ('ct_'+Date.now()+'_'+Math.random().toString(36).slice(2))) }))
        : [],
      selectiveTests: Array.isArray(groundSaved.selectiveTests)
        ? groundSaved.selectiveTests.map(t => Object.assign(makeGroundingSelectiveTest(), t, { id: (t && t.id) || (crypto && crypto.randomUUID ? crypto.randomUUID() : ('st_'+Date.now()+'_'+Math.random().toString(36).slice(2))) }))
        : [],
      clampInstrumentType: groundSaved.clampInstrumentType || '',
      clampInstrumentModel: groundSaved.clampInstrumentModel || '',
      clampInstrumentManual: !!groundSaved.clampInstrumentManual,
      supportsSelectiveGroundTest: !!groundSaved.supportsSelectiveGroundTest,
      envMeasurementPeriod: groundSaved.envMeasurementPeriod || '',
      groundCondition: groundSaved.groundCondition || '',
      ambientTemp: groundSaved.ambientTemp || '',
      environmentalNotes: groundSaved.environmentalNotes || '',
      principleImages: Array.isArray(groundSaved.principleImages) ? groundSaved.principleImages : [],
      selectedPresetImageId: groundSaved.selectedPresetImageId || '',
    };

    const dcBase = base.dcCableTest;
    const dcSaved = loaded.dcCableTest || {};
    function mergeDcGroup(g, i){
      const savedRows = Array.isArray(g.rows) && g.rows.length ? g.rows : [makeDcCableRow(1)];
      return {
        groupNumber: g.groupNumber || (i+1),
        title: g.title || '', description: g.description || '',
        generalSource: g.generalSource || '', generalDest: g.generalDest || '',
        systemVoltage: g.systemVoltage || '', numConductors: g.numConductors || '',
        notes: g.notes || '',
        rows: savedRows.map((r,ri)=>({
          number: r.number || (ri+1), from: r.from||'', to: r.to||'',
          crossSection: r.crossSection||'', conductorCount: r.conductorCount||'', type: r.type||'',
          visual: r.visual||'',
          polarityResult: r.polarityResult||'', insulationPositive: r.insulationPositive||'',
          insulationPositiveUnit: r.insulationPositiveUnit||'MΩ',
          insulationNegative: r.insulationNegative||'', insulationNegativeUnit: r.insulationNegativeUnit||'MΩ',
          minRequired: r.minRequired||'', minRequiredUnit: r.minRequiredUnit||'MΩ',
          r30Positive: r.r30Positive||'', r30Negative: r.r30Negative||'',
          r60Positive: r.r60Positive||'', r60Negative: r.r60Negative||'',
          r1minPositive: r.r1minPositive||'', r1minNegative: r.r1minNegative||'',
          r10minPositive: r.r10minPositive||'', r10minNegative: r.r10minNegative||'',
          notes: r.notes||''
        }))
      };
    }
    merged.dcCableTest = {
      systemVoltageDC: dcSaved.systemVoltageDC || '', testVoltage: dcSaved.testVoltage || '',
      testVoltageUnit: dcSaved.testVoltageUnit || 'VDC',
      testTime: dcSaved.testTime || '', minInsulationRequired: dcSaved.minInsulationRequired || '',
      unit: dcSaved.unit || dcBase.unit, ambientTemp: dcSaved.ambientTemp || '',
      weather: dcSaved.weather || '', cableCondition: dcSaved.cableCondition || '',
      instrumentName: dcSaved.instrumentName || '', instrumentManufacturer: dcSaved.instrumentManufacturer || '',
      instrumentModel: dcSaved.instrumentModel || '', instrumentSerial: dcSaved.instrumentSerial || '',
      calibrationCertNo: dcSaved.calibrationCertNo || '', calibrationExpiry: dcSaved.calibrationExpiry || '',
      conductorMaterial: dcSaved.conductorMaterial || '', insulationType: dcSaved.insulationType || '', ratedVoltage: dcSaved.ratedVoltage || '',
      performDAR: !!dcSaved.performDAR, darMin: dcSaved.darMin || '',
      performPI: !!dcSaved.performPI, piMin: dcSaved.piMin || '',
      groups: (Array.isArray(dcSaved.groups) && dcSaved.groups.length)
        ? dcSaved.groups.map(mergeDcGroup)
        : dcBase.groups.map(g=>JSON.parse(JSON.stringify(g))),
      findings: Array.isArray(dcSaved.findings) ? dcSaved.findings.map((f,i)=>({
        number: f.number || ('2.'+(i+1)), description: f.description||'', severity: f.severity||'',
        recommendation: f.recommendation||'', status: f.status||''
      })) : [],
      conclusionKey: dcSaved.conclusionKey || '',
      conclusionOverride: !!dcSaved.conclusionOverride,
      conclusionJustification: dcSaved.conclusionJustification || '',
      testerName: dcSaved.testerName || '', testerRole: dcSaved.testerRole || '',
      testerLicenseNo: dcSaved.testerLicenseNo || '', testerDate: dcSaved.testerDate || '',
      testerSignature: dcSaved.testerSignature || '',
      clientRepName: dcSaved.clientRepName || '', clientRepRole: dcSaved.clientRepRole || '',
      clientRepDate: dcSaved.clientRepDate || '', clientRepSignature: dcSaved.clientRepSignature || ''
    };
    // backward-compat: earlier versions stored these fields under meta.*
    if(loaded.meta){
      ['logo','companyName','engineerName','licenseNo','phone','email','companyAddress'].forEach(k=>{
        if(!merged.settings[k] && loaded.meta[k]) merged.settings[k] = loaded.meta[k];
      });
    }
    // backward-compat: earlier versions had one combined "licenseNo" field instead of separate engineer/tester numbers
    if(!merged.settings.engineerLicenseNo){
      const oldLicenseNo = (loaded.settings && loaded.settings.licenseNo) || merged.settings.licenseNo;
      if(oldLicenseNo) merged.settings.engineerLicenseNo = oldLicenseNo;
    }
    const order = (loaded.panelOrder && loaded.panelOrder.length) ? loaded.panelOrder.slice() : base.panelOrder.slice();
    const panels = {};
    order.forEach(id=>{
      const saved = (loaded.panels && loaded.panels[id]) || {};
      const tmpl = makePanel(saved.name);
      panels[id] = Object.assign({}, tmpl, saved);
      panels[id].photos = Array.isArray(saved.photos) ? saved.photos.map(p=>({
        id: p.id, dataUrl: p.dataUrl, title: p.title||'', note: p.note||''
      })) : [];
      panels[id].checklist = Object.assign({}, tmpl.checklist, saved.checklist);
      panels[id].cables = Object.assign({}, tmpl.cables, saved.cables);
      panels[id].dccb = normalizeDccb(saved.dccb);
      panels[id].dps = normalizeDps(saved.dps);
      panels[id].houseTransformer = Object.assign({}, tmpl.houseTransformer, saved.houseTransformer);
      panels[id].auxFeed = Object.assign({}, tmpl.auxFeed, saved.auxFeed);
      panels[id].storageContainers = (Array.isArray(saved.storageContainers) && saved.storageContainers.length)
        ? saved.storageContainers.map(c=>Object.assign(makeStorageContainer(''), c))
        : tmpl.storageContainers;
      panels[id].inverterCleaning = Object.assign({}, tmpl.inverterCleaning, saved.inverterCleaning);
      panels[id].transformer = Object.assign({}, tmpl.transformer, saved.transformer, {
        checklist: Object.assign({}, tmpl.transformer.checklist, saved.transformer && saved.transformer.checklist)
      });
      // backward-compat: older versions had a single "voltage" field instead of primary/secondary
      if(saved.transformer && saved.transformer.voltage && !saved.transformer.voltagePrimary){
        panels[id].transformer.voltagePrimary = saved.transformer.voltage;
      }
      panels[id].insulationTransformer = normalizeInsulation(saved.insulationTransformer, tmpl.insulationTransformer);
      panels[id].insulationHouse = normalizeInsulation(saved.insulationHouse, tmpl.insulationHouse);
    });
    merged.panelOrder = order;
    merged.panels = panels;
    merged.notes = (loaded.notes && loaded.notes.length) ? loaded.notes : base.notes;
    merged.generalVisual = Object.assign({}, base.generalVisual, loaded.generalVisual);
    merged.safetyEquipment = Object.assign({}, base.safetyEquipment, loaded.safetyEquipment);
    merged.mainSwitchgear = Object.assign({}, base.mainSwitchgear, loaded.mainSwitchgear, {
      checklist: Object.assign({}, base.mainSwitchgear.checklist, loaded.mainSwitchgear && loaded.mainSwitchgear.checklist)
    });
    // עותקים משוכפלים של מסדר מתח גבוה (SMA, סעיף 03) — כל פריט מקבל checklist עם מיזוג
    // עמוק, אותו עיקרון בדיוק כמו mainSwitchgear המקורי מעליו (לא Object.assign שטחי שהיה
    // מאבד סעיפי checklist חדשים בעותקים ישנים שנשמרו לפני הוספתם).
    merged.mainSwitchgearExtra = Array.isArray(loaded.mainSwitchgearExtra) ? loaded.mainSwitchgearExtra.map(item => Object.assign({}, base.mainSwitchgear, item, {
      checklist: Object.assign({}, base.mainSwitchgear.checklist, item && item.checklist)
    })) : [];
    // בדיקת שנאי (SMA, סעיף 05) — נדרש בפועל (לא רק עקביות): dualCoilInsulation הוא שדה חדש
    // (Dyn11yn11/Dy11y11) — דוח ישן שנשמר לפניו לא יכיל אותו כלל, כך שבלי מיזוג עמוק כאן
    // הרינדור היה מקבל undefined ונכשל. אותו עיקרון בדיוק כמו mainSwitchgear למעלה.
    merged.standaloneTransformer = Object.assign({}, base.standaloneTransformer, loaded.standaloneTransformer, {
      checklist: Object.assign({}, base.standaloneTransformer.checklist, loaded.standaloneTransformer && loaded.standaloneTransformer.checklist),
      dualCoilInsulation: Object.assign({}, base.standaloneTransformer.dualCoilInsulation, loaded.standaloneTransformer && loaded.standaloneTransformer.dualCoilInsulation)
    });
    merged.standaloneTransformerExtra = Array.isArray(loaded.standaloneTransformerExtra) ? loaded.standaloneTransformerExtra.map(item => Object.assign({}, base.standaloneTransformer, item, {
      checklist: Object.assign({}, base.standaloneTransformer.checklist, item && item.checklist),
      dualCoilInsulation: Object.assign({}, base.standaloneTransformer.dualCoilInsulation, item && item.dualCoilInsulation)
    })) : [];
    merged.evDcReport = deepMergeGeneric(base.evDcReport, loaded.evDcReport);
    // דוח שנאי מתח גבוה — פער קיים שלא היה קשור במקור ל-DGPT: לא היה לו בכלל מיזוג עמוק (רק
    // ה-Object.assign השטחי הכללי בתחילת הפונקציה), כך שדוח ישן שנשמר לפני הוספת שדה מקונן
    // חדש (dgptTest עכשיו, אך גם כל שדה עתידי אחר) היה עלול לקרוס בטעינה — אותה מחלקת באג
    // שכבר תוקנה בעבר לכמה דוחות אחרים (v2.196 ואילך). לא נדרש טיפול מיוחד למערכים דינמיים
    // (אין כאלה בדוח הזה, בשונה מ-mainPanelReport/generalElectricalInspectionReport).
    merged.transformerWindingReport = deepMergeGeneric(base.transformerWindingReport, loaded.transformerWindingReport);
    // דוח בדיקת שנאי מתח גבוה (חדש) — אותה הגנה מראש, לא אחרי שנמצא פער כמו ב-transformerWindingReport
    // לעיל. transformers[] (מערך דינמי, כמו facilities[]) מטופל בנפרד ב-boot() עם מיזוג פר-פריט —
    // מיזוג עמוק כללי כאן היה מחליף את כל המערך בשלמותו בלי למזג כל שנאי בנפרד מול ברירת המחדל.
    merged.transformerInspectionReport = deepMergeGeneric(
      { ...base.transformerInspectionReport, transformers: [] },
      loaded.transformerInspectionReport ? { ...loaded.transformerInspectionReport, transformers: [] } : undefined
    );
    merged.transformerInspectionReport.transformers = (loaded.transformerInspectionReport && Array.isArray(loaded.transformerInspectionReport.transformers))
      ? loaded.transformerInspectionReport.transformers : base.transformerInspectionReport.transformers;
    return merged;
  }catch(e){ return base; }
}

function deepMergeGeneric(base, loaded){
  if(loaded == null) return JSON.parse(JSON.stringify(base));
  if(Array.isArray(base)) return Array.isArray(loaded) ? loaded : JSON.parse(JSON.stringify(base));
  if(typeof base === 'object' && base !== null){
    const out = {};
    Object.keys(base).forEach(key=>{
      out[key] = deepMergeGeneric(base[key], loaded ? loaded[key] : undefined);
    });
    return out;
  }
  return (loaded !== undefined && loaded !== null) ? loaded : base;
}

// מנקה dataUrl (base64 מלא) מכל "רשומת תמונה" שכבר יש לה cloudPath — כלומר כבר בטוחה בענן,
// ולכן אין צורך לשמור אותה שוב, כפולה, ב-localStorage. עובד רקורסיבית על כל מבנה ה-state,
// כדי לתפוס כל מיקום תמונה (generalPhotos/itemPhotos/soilTest/groundingTest/mainPanelReport
// וכו') בלי לתחזק רשימה נפרדת שעלולה להחמיץ מיקום. לא נוגע ב-state החי עצמו — בונה עותק
// חדש, כדי שהתצוגה בזיכרון (שעדיין משתמשת ב-dataUrl כגיבוי מקומי, לפי עיצוב מכוון) לא תיפגע.
// זו הייתה סיבת השורש לתקלת "האחסון המקומי מלא" — כל תמונה שהועלתה לענן נשארה גם כפולה
// במלואה ב-state, מנפחת את השמירה המקומית שוב ושוב ללא צורך.
function sanitizeStateForLocalSave(obj){
  if(Array.isArray(obj)) return obj.map(sanitizeStateForLocalSave);
  if(obj && typeof obj === 'object'){
    if(typeof obj.dataUrl === 'string' && obj.cloudPath){
      const { dataUrl, ...rest } = obj;
      const cleaned = {};
      for(const k in rest) cleaned[k] = sanitizeStateForLocalSave(rest[k]);
      return cleaned;
    }
    const result = {};
    for(const key in obj) result[key] = sanitizeStateForLocalSave(obj[key]);
    return result;
  }
  return obj;
}

// ============ DEBUG LOGGING זמני — לאבחון תקלת "חלון נסגר בזמן שמירה" ============
// לפי בקשה מפורשת: אבחון בלבד, לא מתקן/משנה שום לוגיקת שמירה או render קיימת. יוסר לאחר
// שנמצא Root Cause מוכח. כל הפונקציות מתחילות ב-fbDebug כדי שיהיה קל לזהות ולהסיר בהמשך.
const FB_DEBUG_MODAL_IDS = ['previewModal','formTypeModal','soilHelpModal','dcDetailsModal',
  'textReviewModal','aiConclusionModal','fatReviewModal','appConfirmModal','appUpdateModal',
  'calibrationWarningModal','fireberryUnifiedModal','fireberryMeetingPickerModal','fireberryFinalizationModal'];

function fbDebugOpenModals(){
  return FB_DEBUG_MODAL_IDS.filter(id => {
    const el = document.getElementById(id);
    return el && el.classList.contains('show');
  });
}

function fbDebugSnapshot(label){
  try{
    const active = document.activeElement;
    const activeDesc = active && active !== document.body
      ? `${active.tagName}${active.id ? '#'+active.id : ''}${active.name ? '['+active.name+']' : ''}${active.getAttribute && active.getAttribute('data-textpath') ? '[data-textpath='+active.getAttribute('data-textpath')+']' : ''}`
      : '(none/body)';
    const activeValuePreview = active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA')
      ? JSON.stringify(String(active.value||'').slice(0,40))
      : undefined;
    console.log(`[FBDEBUG ${new Date().toISOString().slice(11,23)}] ${label}`, {
      ACTIVE_REPORT_ID: (state && state.settings && state.settings.cloudReportId) || '(none)',
      CURRENT_VIEW: typeof activeTab !== 'undefined' ? activeTab : '(n/a)',
      ACTIVE_ELEMENT: activeDesc,
      ACTIVE_ELEMENT_VALUE_PREVIEW: activeValuePreview,
      SCROLL_POSITION: window.scrollY,
      OPEN_MODALS: fbDebugOpenModals(),
    });
  }catch(e){ console.log('[FBDEBUG] snapshot error', e && e.message); }
}


function scheduleSave(){
  // Phase 2C: כל עריכה מקדמת מונה (נשמר יחד עם הדוח) — כך "יש שינויים שלא הגיעו לענן" שורד refresh
  if(state && state.settings) state.settings.cloudEditSeq = (state.settings.cloudEditSeq || 0) + 1;
  console.log('[FBDEBUG] scheduleSave START'); // DEBUG זמני
  fbDebugSnapshot('scheduleSave START'); // DEBUG זמני
  setSavePill('שומר…', false);
  clearTimeout(saveTimer);
  saveTimer = setTimeout(async ()=>{
    try{
      await storageAPI.set('inspection-current', JSON.stringify(sanitizeStateForLocalSave(state)), false);
      console.log('[FBDEBUG] LOCAL SAVE COMPLETE'); // DEBUG זמני
      fbDebugSnapshot('LOCAL SAVE COMPLETE'); // DEBUG זמני
      if(navigator.onLine === false){ setSavePill('ללא רשת – שומר מקומית', false, true); }
      else{ setSavePill('נשמר', true); }
    }catch(e){
      setSavePill('שגיאת שמירה', false);
      // כשל שמירה עלול לקרות בשקט מדי אם רק הפיל הקטן משתנה — במיוחד עם תמונות (base64 גדול
      // עלול לחרוג ממכסת האחסון של הדפדפן). מציגים גם התראה בולטת, כדי שהמשתמש לא יאבד תיעוד
      // בלי לשים לב.
      const isQuotaIssue = e && (e.name === 'QuotaExceededError' || /quota/i.test(e.message||''));
      showToast(isQuotaIssue
        ? '⚠️ השמירה נכשלה — נראה שהאחסון המקומי מלא (יתכן בגלל כמות/גודל התמונות). מומלץ לייצא גיבוי מיד ולפנות מקום.'
        : '⚠️ השמירה האוטומטית נכשלה — מומלץ לייצא גיבוי כדי לא לאבד נתונים.');
    }
  }, 400);

  // Cloud auto-save: debounce נפרד וארוך יותר (5 שניות), רק אם המשתמש מחובר בפועל לענן.
  // תיקון: עד v2.168 נדרשו גם cloudClientId/cloudProjectId — למרות ש-v2.167 כבר הסירה את
  // אותה דרישה בדיוק מתוך saveReportToCloud() עצמה (client/project אופציונליים כעת, item 11
  // במפרט). זה היה שער חיצוני נשכח שמנע מהטיימר להיות מופעל בכלל, כך שה-Auto Save לענן
  // מעולם לא היה מתחיל אלא אם המשתמש בחר ידנית לקוח+פרויקט מראש — בדיוק סיבת השורש שכבר
  // תוקנה במקום הלא נכון.
  if(supabaseClient && cloudCurrentUser){
    clearTimeout(cloudAutoSaveTimer);
    console.log('[FBDEBUG] CLOUD AUTOSAVE scheduled in 5000ms'); // DEBUG זמני
    cloudAutoSaveTimer = setTimeout(()=>{
      console.log('[FBDEBUG] CLOUD AUTOSAVE START'); // DEBUG זמני
      fbDebugSnapshot('CLOUD AUTOSAVE START'); // DEBUG זמני
      scheduleCloudAutoSave();
    }, 5000);
  }
}

// עוטפת את saveReportToCloud הקיימת עבור זרימת ה-Auto Save הספציפית — לא כופלת לוגיקה,
// רק מוסיפה את חיווי הפילה המדויק שנדרש (item 10/20 במפרט) סביב אותה קריאה.
async function scheduleCloudAutoSave(){
  if(navigator.onLine === false){
    queueOfflineSave();
    return;
  }
  setSavePill('מסנכרן לענן…', false);
  const result = await saveReportToCloud();
  if(result === true){
    setSavePill('נשמר בענן ✓', true);
  } else if(result === 'conflict'){
    // הקונפליקט כבר טופל (cloudSyncStatus='error' + render) בתוך saveReportToCloud עצמה —
    // כאן רק מעדכנים את הפילה לשקף זאת; ה-UI לפתרון קונפליקט (item 27) ייבנה בשלב הבא.
    setSavePill('שגיאה בשמירה בענן', false);
  } else if(result === 'offline'){
    setSavePill('אין חיבור – נשמר מקומית וממתין לסנכרון', false, true);
  } else if(result === 'empty'){
    setSavePill('נשמר', true);
  } else {
    setSavePill('שגיאה בשמירה בענן', false);
  }
}

function setSavePill(text, saved, offline){
  const el = document.getElementById('savePill');
  el.textContent = text;
  el.classList.toggle('saved', !!saved && !offline);
  el.classList.toggle('offline', !!offline);
}

/* ---------- Rendering helpers ---------- */

function statusGroup(path, idx, current){
  const opts = [["ok","תקין"],["bad","לא תקין"],["na","לא רל'"]];
  return `<div class="status-group">` + opts.map(([val,label])=>
    `<button type="button" class="status-btn ${val} ${current===val?'active':''}"
       data-path="${path}" data-idx="${idx}" data-val="${val}">${label}</button>`
  ).join('') + `</div>`;
}

// עוזר צ'קליסט לדוח עמדת טעינה — פריסת כרטיס (אותו דפוס מוכח שכבר עובד היטב במובייל
// ב-TRANSFORMER_INSPECTION, v2.248-249), לא itemList()/סגנון-רדיו הישן (שלא תואם למבנה
// הנתונים {status,notes} שתוכנן לדוח החדש). ממלא בעצלנות אם המערך עדיין ריק.
function evcsChecklistHtml(path, textArray, dataArray){
  if(!dataArray.length){
    dataArray.push(...textArray.map(()=>({status:"", notes:""})));
  }
  return `<div class="ti-checklist-list">${textArray.map((label, i) => `
    <div class="ti-checklist-item">
      <div class="ti-checklist-desc">${escapeHtml(label)}</div>
      <div class="ti-checklist-controls">
        ${mainPanelStatusSelectHtml(`${path}.${i}.status`, dataArray[i].status)}
        <input type="text" data-textpath="${path}.${i}.notes" value="${escapeAttr(dataArray[i].notes)}" placeholder="הערות...">
      </div>
    </div>`).join('')}</div>`;
}
// בחירה מרובה (checkboxes) לתקנים — path.selected הוא מערך מחרוזות
function evcsMultiCheckbox(path, selected, options){
  return `<div style="display:flex; flex-wrap:wrap; gap:8px;">${options.map(o => `
    <label class="decl-item ${selected.includes(o)?'on':''}" style="flex:1 1 140px;">
      <input type="checkbox" data-evcsmulti="${path}|${escapeAttr(o)}" ${selected.includes(o)?'checked':''}>
      <span>${escapeHtml(o)}</span>
    </label>`).join('')}</div>`;
}
// גרסה קומפקטית יותר, ייעודית — לפי בקשה מפורשת ("יותר קטן כי יש לי עוד מכשירים"). פדינג
// ופונט קטנים יותר, ורוחב מינימלי צר יותר (90px במקום 140px) כדי שיותר תגים ייכנסו בכל שורה
// ברוחב מסך נתון, בלי לגלול אנכית יותר מדי כשמוסיפים עוד אפשרויות לרשימה. לא נגעתי ב-
// evcsMultiCheckbox הרגילה, כדי לא להשפיע על שימושים אחרים שלה (בחירת תקנים).
function evcsMultiCheckboxCompact(path, selected, options, colorFn){
  return `<div style="display:flex; flex-wrap:wrap; gap:5px;">${options.map(o => {
    const color = colorFn ? colorFn(o) : null;
    return `
    <label class="decl-item ${selected.includes(o)?'on':''}" style="flex:0 1 auto; padding:5px 8px; font-size:11.5px; gap:5px;">
      <input type="checkbox" data-evcsmulti="${path}|${escapeAttr(o)}" ${selected.includes(o)?'checked':''} style="width:13px; height:13px;">
      <span${color ? ` style="color:${color}; font-weight:600;"` : ''}>${escapeHtml(o)}</span>
    </label>`;
  }).join('')}</div>`;
}

function itemList(items, statusMap, path){
  return items.map((label,i)=>{
    const photoKey = `${path}|${i}`;
    const photos = state.itemPhotos[photoKey] || [];
    const existingNote = state.itemNotes[photoKey] || '';
    const noteOpen = expandedItemNotes.has(photoKey) || !!existingNote;
    return `
    <div class="item-row">
      <span class="lbl">${label}</span>
      ${statusGroup(path, i, statusMap[i])}
      <button type="button" class="item-photo-btn ${photos.length?'has-photos':''}" data-itemgallerybtn="${escapeAttr(photoKey)}" title="הוסף תמונה (בחר מהגלריה, צלם, או בחר קובץ)">🖼️ הוסף תמונה${photos.length ? ' '+photos.length : ''}</button>
      <button type="button" class="item-photo-btn ${existingNote?'has-photos':''}" data-itemnotebtn="${escapeAttr(photoKey)}" title="הוסף הערה">📝${existingNote ? ' •' : ''}</button>
    </div>
    ${photos.length ? `<div class="item-photo-thumbs">${photos.map((p,pi)=>`<div class="item-photo-thumb"><img src="${resolvePhotoSrc(p)}" data-cloudpath="${escapeAttr(p.cloudPath||'')}"><button type="button" data-itemphotoremove="${escapeAttr(photoKey)}|${pi}">✕</button></div>`).join('')}</div>` : ''}
    ${noteOpen ? `<div class="item-note-box"><textarea data-itemnotepath="${escapeAttr(photoKey)}" placeholder="הערה לסעיף זה...">${escapeHtml(existingNote)}</textarea></div>` : ''}
  `;
  }).join('');
}

