function breakerModelField(manufacturerValue, modelPath, modelValue){
  if(!manufacturerValue){
    return `<div class="field"><label>דגם מפסק</label>
      <input type="text" data-textpath="${modelPath}" value="${escapeAttr(modelValue)}" placeholder="בחר יצרן קודם, או הזן דגם ישירות">
    </div>`;
  }
  const options = getBreakerModelOptions(manufacturerValue);
  const isPreset = options.includes(modelValue);
  const showCustomInput = customModeFields.has(modelPath) || (!!modelValue && !isPreset);
  const selectValue = showCustomInput ? '__custom__' : modelValue;
  const alreadySaved = !!modelValue && options.includes(modelValue);
  return `<div class="field"><label>דגם מפסק — ${escapeHtml(manufacturerValue)}</label>
    <select data-customselect="${modelPath}">
      <option value="" ${selectValue===''?'selected':''}>-- בחר --</option>
      ${options.map(o=>`<option value="${escapeAttr(o)}" ${selectValue===o?'selected':''}>${o}</option>`).join('')}
      <option value="__custom__" ${selectValue==='__custom__'?'selected':''}>אחר (הזנה ידנית)</option>
    </select>
    ${showCustomInput ? `
      <div style="display:flex; gap:6px; align-items:center; margin-top:6px;">
        <input type="text" style="flex:1;" data-textpath="${modelPath}" value="${escapeAttr(modelValue)}" placeholder="הזן דגם משלך">
        ${(!alreadySaved) ? `<button type="button" class="add-btn" data-addbreakermodel="${manufacturerValue}|${modelPath}" style="white-space:nowrap;">+ הוסף לרשימה</button>` : `<span style="font-size:11px; color:var(--ok,#3fa34d);">✓ נשמר ברשימה</span>`}
      </div>` : ''}
  </div>`;
}

function clientSelectField(){
  const path = 'meta.client';
  const value = state.meta.client;
  // תוקן — לפי דיווח משתמש ("התוכנה הסתנכרנה עם הלקוחות של Fireberry ואני לא רואה אותם
  // כשאני מכין דוח"): קודם לכן השתמשנו תמיד ב-clientsList (מקומי בלבד) — אבל ייבוא/סנכרון
  // Fireberry כותב ל-Supabase clients, שמאוכלס דרך cloudClientsCache, לא clientsList. אותו
  // דפוס מודע-לענן בדיוק כמו renderClientsView(): אם מחוברים לענן וה-cache כבר נטען,
  // המקור הוא cloudClientsCache; אחרת נופלים חזרה ל-clientsList המקומי (offline/גיבוי).
  const usingCloud = !!(supabaseClient && cloudCurrentUser);
  const sourceClients = usingCloud && cloudClientsCache !== null
    ? cloudClientsCache.map(normalizeCloudClient)
    : clientsList;
  const sortedClients = sourceClients.slice().sort((a,b)=>a.name.localeCompare(b.name, 'he'));
  const isPreset = sortedClients.some(c=>c.name === value);
  const currentClient = isPreset ? findClientByName(value) : (value.trim() ? { id: 'NEW:'+value.trim(), name: value.trim(), _unsaved: true } : null);
  // שדה טקסט יחיד עם datalist — לפי בקשה מפורשת "אפשרות חיפוש ע"י כתיבה" (מאות לקוחות,
  // select רגיל לא מעשי לגלילה/חיפוש). datalist נותן type-ahead טבעי של הדפדפן, בלי JS
  // מותאם. מחליף לגמרי את המתג "מצב מותאם אישית" הקודם — אותו שדה משרת גם חיפוש/בחירה
  // מרשימה וגם הקלדת שם חדש, כי datalist לא מגביל את הערך לרשימת ה-option בלבד.
  return `<div class="field" style="min-width:0;">
    <label>המזמין *</label>
    <div style="display:flex; gap:6px; align-items:center;">
      <input type="text" data-clienttextselect="${path}" list="clientsSearchDatalist" value="${escapeAttr(value)}" placeholder="הקלד לחיפוש בין ${sortedClients.length} לקוחות, או שם חדש..." style="flex:1;">
      <button type="button" id="btnOpenClientPicker" title="חיפוש לקוח" style="flex-shrink:0; padding:8px 12px; font-size:16px; background:var(--panel2); border:1px solid var(--line); border-radius:8px; cursor:pointer;">🔍</button>
      <button type="button" id="btnOpenClientQuickEdit" title="ערוך פרטי לקוח (כתובת/איש קשר)" style="flex-shrink:0; padding:8px 12px; font-size:16px; background:var(--panel2); border:1px solid var(--line); border-radius:8px; cursor:pointer;">✏️</button>
      <button type="button" id="btnOpenFireberryDiagnostic" title="אבחון Fireberry (זמני)" style="flex-shrink:0; padding:8px 12px; font-size:16px; background:var(--panel2); border:1px solid var(--line); border-radius:8px; cursor:pointer;">🔧</button>
    </div>
    <datalist id="clientsSearchDatalist">
      ${sortedClients.map(c=>`<option value="${escapeAttr(c.name)}">`).join('')}
    </datalist>
    <div style="margin-top:8px;">
      ${renderFbLinkedStatusOrButton()}
    </div>
  </div>`;
}

// מצב "מקושר" קומפקטי — מוצג במקום הכפתור לאחר קישור מוצלח, לפי בקשה מפורשת (סעיף 17
// במפרט המקורי). "שנה קישור" פותח שוב את החלונית המאוחדת (המשתמש יכול לבחור אחרת).
function renderFbLinkedStatusOrButton(){
  if(!state.meta.fireberryClientId && !state.meta.fireberryMeetingId){
    return `<div>
      <div style="font-size:12px; color:var(--text-dim); margin-bottom:6px;">⚪ Fireberry לא מקושר</div>
      <button type="button" class="add-btn" data-fbopenunified="1" style="font-size:12px; padding:8px 14px; font-weight:600;">🔗 קשר ל-Fireberry</button>
    </div>`;
  }
  const isMeeting = state.meta.fireberrySyncMode === 'meeting' && state.meta.fireberryMeetingId;
  let dateLine = '';
  if(isMeeting && state.meta.fireberryMeetingStart){
    const d = new Date(state.meta.fireberryMeetingStart);
    dateLine = `<div style="font-size:12px; color:var(--text-dim); margin-top:2px;">📅 ${d.toLocaleDateString('he-IL')} ${d.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'})}${state.meta.fireberryMeetingSubject ? ' — '+escapeHtml(state.meta.fireberryMeetingSubject) : ''}</div>`;
  }
  return `<div style="border:1px solid #4ade80; border-radius:8px; padding:10px 12px; background:rgba(74,222,128,0.08);">
    <div style="font-size:12.5px; font-weight:700; color:#4ade80;">🟢 Fireberry מקושר</div>
    ${dateLine}
    ${state.meta.fireberryClientName ? `<div style="font-size:12px; color:var(--text-dim); margin-top:2px;">👤 לקוח: ${escapeHtml(state.meta.fireberryClientName)}</div>` : ''}
    ${state.meta.fireberryContactName ? `<div style="font-size:12px; color:var(--text-dim); margin-top:2px;">📇 איש קשר: ${escapeHtml(state.meta.fireberryContactName)}</div>` : ''}
    <div style="display:flex; gap:8px; margin-top:8px;">
      <button type="button" class="today-btn" data-fbopenunified="1" style="font-size:11px; padding:5px 10px; flex:1;">שנה קישור</button>
      <button type="button" class="del-panel-btn" data-fbdisconnect="1" style="font-size:11px; padding:5px 10px; flex:1;">נתק קישור</button>
    </div>
  </div>`;
}

// ווידג'ט קישור לקוח ל-Fireberry — לפי בקשה מפורשת: קישור חד-פעמי, נשמר לצמיתות על הלקוח,
// לא ניחוש-שם בכל דוח. שלושה מצבים: מקושר (ירוק), לא מקושר (כפתור), תיבת חיפוש פתוחה.
function fireberryClientLinkWidget(client){
  const isOpen = fireberryClientLinkOpenForId === client.id;
  if(client.fireberryClientId && !isOpen){
    return `<div style="margin-top:6px; font-size:11.5px; color:#4ade80; display:flex; align-items:center; gap:6px;">
      <span>🔗 מקושר ל-Fireberry${client.fireberryClientName ? ': '+escapeHtml(client.fireberryClientName) : ''}</span>
      <button type="button" class="today-btn" data-fbclientlinktoggle="${client.id}" style="font-size:10.5px; padding:2px 8px;">שנה</button>
    </div>`;
  }
  if(!isOpen){
    return `<div style="margin-top:6px;">
      <button type="button" class="add-btn" data-fbclientlinktoggle="${client.id}" style="font-size:11.5px; padding:5px 10px;">🔗 קשר ל-Fireberry</button>
    </div>`;
  }
  // תיבת חיפוש פתוחה — שדה הקלט עצמו קבוע (לא נבנה מחדש בכל חיפוש), רק אזור התוצאות
  // (renderFireberryClientLinkResultsArea) מתעדכן באופן ממוקד בזמן הקלדה — לפי בקשה מפורשת:
  // "הלקוחות יתחילו להיחשף עד שאני משלים את השם" (חיפוש חי, לא לחיצה על כפתור בלבד).
  return `<div style="margin-top:6px; padding:10px; border:1px solid var(--line); border-radius:8px; background:var(--panel2); width:100%; box-sizing:border-box;">
    <div style="font-size:11.5px; color:var(--text-dim); margin-bottom:6px;">הקלד שם לקוח לחיפוש חי ב-Fireberry:</div>
    <div style="display:flex; gap:6px;">
      <input type="text" id="fbClientLinkSearchInput" data-fbclientid="${client.id}" placeholder="התחלת שם הלקוח ב-Fireberry (חיפוש חי)" value="${escapeAttr(client.name)}" style="flex:1;">
      <button type="button" class="add-btn" data-fbclientlinksearch="${client.id}" style="flex-shrink:0;">חפש</button>
    </div>
    <div id="fbClientLinkResultsArea">${renderFireberryClientLinkResultsArea(client.id)}</div>
    <button type="button" class="del-panel-btn" data-fbclientlinktoggle="${client.id}" style="font-size:11px; margin-top:6px;">סגור</button>
  </div>`;
}

// אזור התוצאות בלבד — נפרד משדה הקלט, כדי שאפשר יהיה לעדכן רק אותו (updateFireberryClient
// LinkResultsOnly) בזמן הקלדה חיה, בלי להרוס/לבנות מחדש את שדה הקלט עצמו (שהיה מאבד פוקוס
// וסמן בכל תו — בדיוק אותה בעיה שכבר נתקלנו בה ותוקנה קודם ב-v2.272 עם דפוס דומה).
function renderFireberryClientLinkResultsArea(clientId){
  // תצוגה ברורה — שם הלקוח בשורה נפרדת ובולטת, פרטים נוספים (טלפון/עיר) בשורה נפרדת
  // ומעומעמת מתחתיו — לפי בקשה מפורשת, עם דוגמה חזותית: "לא ניתן להבין מי רשום שם".
  const resultsHtml = fireberryClientLinkResults.map(r => `
    <div style="padding:8px 10px; border:1px solid var(--line); border-radius:6px; margin-top:6px; display:flex; justify-content:space-between; align-items:center; gap:10px; width:100%; box-sizing:border-box;">
      <div style="min-width:0; flex:1;">
        <div style="font-size:13px; font-weight:600; color:var(--text); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(r.name)}</div>
        ${(r.phone || r.city) ? `<div style="font-size:11px; color:var(--text-dim); margin-top:2px;">${[r.phone, r.city].filter(Boolean).map(escapeHtml).join(' · ')}</div>` : ''}
      </div>
      <button type="button" class="add-btn" data-fbclientlinkselect="${clientId}|${escapeAttr(r.fireberryClientId)}|${escapeAttr(r.name)}" style="font-size:11px; padding:5px 12px; flex-shrink:0; width:auto;">בחר</button>
    </div>`).join('');
  return `
    ${fireberryClientLinkSearching ? `<p style="font-size:11px; color:var(--text-dim); margin-top:6px;">🔄 מחפש...</p>` : ''}
    ${fireberryClientLinkError ? `<p style="font-size:11px; color:var(--amber); margin-top:6px;">⚠️ ${escapeHtml(fireberryClientLinkError)}</p>` : ''}
    ${resultsHtml}
  `;
}

function projectSelectField(){
  const path = 'meta.project';
  const value = state.meta.project;
  const currentClient = findClientByName(state.meta.client);
  if(!currentClient){
    return `<div class="field">
      <label>פרויקט *</label>
      <input type="text" data-textpath="${path}" value="${escapeAttr(value)}" placeholder="בחר קודם 'מזמין' למעלה כדי לראות רשימת פרויקטים" disabled style="opacity:.6; cursor:not-allowed;">
      <p style="font-size:11px; color:var(--amber); margin:4px 0 0;">⚠️ יש לבחור לקוח (מזמין) קודם — אז תופיע כאן רשימת הפרויקטים שלו לבחירה.</p>
    </div>`;
  }
  const projects = currentClient.projects || [];
  const isPreset = projects.some(p=>p.name === value);
  const showCustomInput = customModeFields.has(path) || (!!value && !isPreset);
  const selectValue = showCustomInput ? '__custom__' : value;
  return `<div class="field">
    <label>פרויקט * (אצל ${escapeHtml(currentClient.name)})</label>
    <select data-projectselect="${path}">
      <option value="" ${selectValue===''?'selected':''}>-- בחר פרויקט --</option>
      ${projects.map(p=>`<option value="${escapeAttr(p.name)}" ${selectValue===p.name?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}
      <option value="__custom__" ${selectValue==='__custom__'?'selected':''}>אחר (פרויקט חדש)</option>
    </select>
    ${showCustomInput ? `<input type="text" style="margin-top:6px;" placeholder="הזן שם פרויקט חדש" data-textpath="${path}" value="${escapeAttr(value)}">` : ''}
    ${projects.length === 0 ? `<p style="font-size:11px; color:var(--text-dim); margin:4px 0 0;">ללקוח זה אין עדיין פרויקטים שמורים. בחר "אחר (פרויקט חדש)" למעלה והקלד שם — הוא יישמר ללקוח לצמיתות.</p>` : ''}
  </div>`;
}

function textField(label, path, value, type="text", restrict=null, placeholder=""){
  const restrictAttr = restrict ? ` data-restrict="${restrict}"` : '';
  const inputMode = restrict === 'digits' ? ' inputmode="numeric"' : (restrict === 'decimal' ? ' inputmode="decimal"' : '');
  const placeholderAttr = placeholder ? ` placeholder="${escapeAttr(placeholder)}"` : '';
  return `<div class="field"><label>${label}</label>
    <input type="${type}" data-textpath="${path}"${restrictAttr}${inputMode}${placeholderAttr} value="${escapeAttr(value)}"></div>`;
}

function textareaField(label, path, value, rows){
  return `<div class="field"><label>${label}</label>
    <textarea data-textpath="${path}" ${rows?`rows="${rows}"`:''}>${escapeHtml(value)}</textarea></div>`;
}

// הערות כלליות קומפקטיות ברמת כרטיס/סעיף — UI אחיד לכל המקומות שסומנו ADD CARD NOTES ב-Audit.
// בלי label נפרד (לפי בקשה מפורשת "לא ליצור אזור גדול ונפרד") — placeholder בלבד, קומפקטי.
function compactSectionNotesField(path, value){
  return `<textarea data-textpath="${path}" placeholder="הערות נוספות..." rows="2" style="width:100%; margin-top:10px; font-size:12.5px; resize:vertical;">${escapeHtml(value||'')}</textarea>`;
}
// גרסת ההדפסה התואמת — מציגה "הערות: [טקסט]" רק אם יש תוכן בפועל (לא ריק/רווחים בלבד),
// אחרת מחזירה מחרוזת ריקה — אין כותרת, אין textarea ריק, אין רווח שנשאר. שימוש אחיד בכל
// המקומות, כדי שהתנהגות ה-PDF תהיה עקבית בכל הסעיפים.
function printSectionNotesBlock(value){
  if(!value || !value.trim()) return '';
  return `<p style="font-size:12px; margin-top:6px;"><b>הערות:</b> ${escapeHtml(value)}</p>`;
}

function escapeAttr(s){ return (s||"").replace(/"/g,'&quot;'); }
function escapeHtml(s){ return (s||"").replace(/&/g,'&amp;').replace(/</g,'&lt;'); }

// ממיר תאריך מפורמט ISO (כפי שמחזיר תמיד <input type="date">, למשל 2026-08-21) לפורמט ישראלי
// עקבי (DD/MM/YYYY) — כדי שכל התאריכים בדוח יופיעו באותו פורמט, כמו "הופק בתאריך" שכבר משתמש
// ב-he-IL. T00:00:00 מונע הזזת יום אפשרית שקשורה לאזור זמן בפירוש התאריך.
function formatDateIL(isoDateStr){
  if(!isoDateStr) return '';
  const d = new Date(isoDateStr + 'T00:00:00');
  if(isNaN(d.getTime())) return isoDateStr;
  return d.toLocaleDateString('he-IL');
}

// בדיקת סטטוס תוקף כיול מכשיר — לפי בקשה מפורשת: התראה כתומה החל מחודשיים לפני פג התוקף,
// אדומה אחרי שפג בפועל. מחזיר: null (אין תאריך כלל), 'ok' (תקין, יותר מחודשיים), 'warning'
// (נותרו 0-60 יום), 'expired' (כבר עבר).
// מוצא רשומת ציוד קיימת (מהגדרות ← ציוד) שמתאימה לשם תג מרשימת מכשירי הבדיקה המהירה —
// לפי בקשה מפורשת: לא לבקש מהמשתמש להזין שוב דגם/מספר סידורי/תוקף כיול שכבר קיימים שם,
// אלא לשלוף אוטומטית. התאמה מדויקת קודם, ואם אין — התאמה חלקית (התכלה הדדית, לא תלוית
// אותיות גדולות/קטנות) כדי לכסות מקרים כמו "SONEL" מול "מגהומטר SONEL MIC-30".
// רשימת מכשירי הבדיקה בסעיף 01 (כל הדוחות) — v2.2.494: המכשירים ששמורים בהגדרות ← מכשירי בדיקה
// (אותו מקור בדיוק כמו מסך ההגדרות: ענן כשמחוברים, אחרת רשימה מקומית). מכשיר שכבר נבחר בדוח ישן
// ואינו ברשימה — נשאר מוצג כדי לא לאבד אותו. אם עדיין לא נשמרו מכשירים — הרשימה המהירה הקבועה.
function getFirstPageInstrumentOptions(){
  const usingCloud = !!(supabaseClient && cloudCurrentUser);
  if(usingCloud && cloudEquipmentCache === null && !cloudEquipmentLoading) setTimeout(() => { loadCloudEquipmentIfNeeded(false); }, 0);
  const src = usingCloud && cloudEquipmentCache !== null ? cloudEquipmentCache.map(normalizeCloudEquipment) : equipmentList;
  const names = [];
  (src || []).forEach(e=>{ const n = String((e && e.name) || '').trim(); if(n && !names.includes(n)) names.push(n); });
  if(!names.length) return TEST_INSTRUMENT_QUICK_OPTIONS;
  (state.meta.testInstrumentsSelected || []).forEach(n=>{ if(n && n !== 'אחר' && !names.includes(n)) names.push(n); });
  names.push('אחר');
  return names;
}
// ===== כבל מתח גבוה — רשימות מקובלות (v2.2.495) =====
// מוליך: אלומיניום / נחושת. בידוד: סוגי בידוד לכבלי מתח גבוה בלבד.
const HV_CABLE_CONDUCTOR_OPTIONS = ['אלומיניום', 'נחושת'];
const HV_CABLE_INSULATION_OPTIONS = ['XLPE', 'TR-XLPE', 'EPR', 'HEPR', 'נייר ספוג שמן (PILC)'];
// מתח בידוד Uo/U (Um) לפי IEC 60502-2 / IEC 60840, כולל 12.7/22 ו-19/33 הנפוצים ברשת בישראל
// תו LRM (\u200E) בתחילת כל ערך — כדי שבממשק בעברית הערך יוצג משמאל לימין ("12.7/22 (24) kV" ולא "kV (24) 12.7/22")
const HV_CABLE_RATED_VOLTAGE_OPTIONS = ['3.6/6 (7.2) kV', '6/10 (12) kV', '8.7/15 (17.5) kV', '12/20 (24) kV', '12.7/22 (24) kV', '18/30 (36) kV', '19/33 (36) kV', '26/45 (52) kV', '36/66 (72.5) kV'].map(v=>'\u200E' + v);
const HV_CABLE_CORES_OPTIONS = ['1', '3', '4'];
// חתכי מוליך נפוצים בכבלי מתח גבוה (mm²) — IEC 60228 / IEC 60502-2
const HV_CABLE_SECTION_OPTIONS = ['25', '35', '50', '70', '95', '120', '150', '185', '240', '300', '400', '500', '630', '800', '1000'];
// חתך סיכוך נחושת / מוליך הארקה נפוצים (mm²)
const HV_CABLE_SCREEN_OPTIONS = ['16', '25', '35', '50', '70', '95'];
// ===== כמה סוגי כבל בדוח (v2.2.497): כבל #1 = השדות הראשיים, כבלים נוספים = hc.extraCables[] =====
function hvCableDefs(hc){
  const first = { cableType: hc.cableType, insulationType: hc.insulationType, ratedVoltage: hc.ratedVoltage, cores: hc.cores, crossSection: hc.crossSection, screenSection: hc.screenSection };
  return [first].concat(Array.isArray(hc.extraCables) ? hc.extraCables : []);
}
function hvCableDefText(d){
  if(!d) return '';
  const size = hvCableSizeText(d);
  const mat = d.cableType === 'אלומיניום' ? 'Al' : (d.cableType === 'נחושת' ? 'Cu' : (d.cableType || ''));
  return [size ? size + ' mm²' : '', mat, d.insulationType, String(d.ratedVoltage || '').replace(/\u200E/g, '')].filter(Boolean).join(' ');
}
function hvCableRowCableText(hc, row){
  const defs = hvCableDefs(hc);
  if(row.cableRef !== undefined && row.cableRef !== '' && defs[+row.cableRef]) return hvCableDefText(defs[+row.cableRef]);
  if(row.cableDescription) return row.cableDescription;
  return hvCableDefText(defs[0]);
}
const HV_CABLE_ROW_STATUS_OPTIONS = ['תקין', 'לא תקין', 'לא רלוונטי'];
// ===== שיטות בדיקת בידוד בדוח כבל מ"ג (v2.2.498) =====
const HV_TEST_METHODS = [
  ['standard', 'בדיקת רמת בידוד', 'ערך בידוד לכל מוליך — L-E ובין המוליכים (ב-60 שניות)'],
  ['temp', 'תיקון לטמפרטורת סביבה', 'הערכים מחושבים מחדש לטמפרטורת ייחוס (20°C) לפי טמפרטורת הסביבה בזמן הבדיקה'],
  ['dar', 'DAR — יחס ספיגה דיאלקטרי', 'R60 / R15 לכל מוליך מול הארקה (תקין ≥ 1.25)'],
  ['pi', 'PI — מקדם קיטוב', 'R600 (10 דק׳) / R60 לכל מוליך מול הארקה (תקין ≥ 2.0)'],
  ['sheath', 'סיכוך להארקה (בדיקת מעטה)', 'בידוד בין הסיכוך (Screen) של כל פאזה להארקה — IEC 60229 / IEC 60502-2']
];
const HV_SHEATH_COLS = [['S1_E','סיכוך L1 – E'], ['S2_E','סיכוך L2 – E'], ['S3_E','סיכוך L3 – E']];
function hvMethods(hc){
  const m = Object.assign({ standard: true, temp: false, dar: false, pi: false, sheath: false }, hc.testMethods || {});
  if(!m.standard && !m.temp && !m.dar && !m.pi && !m.sheath) m.standard = true;
  return m;
}
// ערך מספרי לחישוב ("> 100" ← לא ניתן לחשב)
function hvNum(v){ const t = String(v == null ? '' : v).trim(); if(!t || /^[>≥<]/.test(t)) return NaN; return parseFloat(t.replace(',', '.')); }
function hvFmt(n){ if(isNaN(n) || n === null) return '—'; const a = Math.abs(n); return a >= 100 ? n.toFixed(0) : (a >= 10 ? n.toFixed(1) : n.toFixed(2)); }
function hvTempCorrected(hc, v){
  const R = hvNum(v), T = parseFloat(hc.ambientTempC), Tr = parseFloat(hc.refTempC || '20');
  if(isNaN(R) || isNaN(T) || isNaN(Tr)) return NaN;
  return R * Math.pow(2, (T - Tr) / 10);
}
function hvSelect(path, val, options, label, extraAttr){
  const cls = val === 'תקין' ? 'hc-st-ok' : (val === 'לא תקין' ? 'hc-st-bad' : (val ? 'hc-st-na' : 'hc-st-empty'));
  const opts = options.slice(); if(val && !opts.includes(val)) opts.push(val);
  const sel = `<select data-textpath="${path}" class="hc-sel ${cls}" ${extraAttr||''} aria-label="${label||''}"><option value="" ${!val?'selected':''}>— בחר —</option>${opts.map(o=>`<option value="${escapeAttr(o)}" ${val===o?'selected':''}>${o === 'תקין' ? '✓ ' : (o === 'לא תקין' ? '✕ ' : '')}${escapeHtml(o)}</option>`).join('')}</select>`;
  return label ? `<div class="field"><label>${label}</label>${sel}</div>` : sel;
}
// חתך מלא לדוח: "1x95+35" (גידים × חתך מוליך + חתך סיכוך/הארקה)
function hvCableSizeText(hc){
  const cs = String(hc.crossSection || '').trim();
  if(!cs) return '';
  const cores = String(hc.cores || '').trim();
  const scr = String(hc.screenSection || '').trim();
  return (cores ? cores + 'x' : '') + cs + (scr ? '+' + scr : '');
}

