function buildProtectionRelayBlocks(){
  if(!RELAY_REPORT_TYPES.includes(getReportType())) return [];
  const list = (state.protectionRelays || []).filter(r => r && (r.location || Object.values(r.info||{}).some(Boolean) || Object.values(r.settings||{}).some(Boolean) || Object.values(r.extra||{}).some(Boolean)));
  if(!list.length) return [];
  const key = k => k.replace(/[^A-Za-z0-9]/g, c => ({'>':'gt','<':'lt'}[c] || '_'));
  const color = v => v==='תקין' ? '#2e7d32' : (v==='לא תקין' ? '#c62828' : '#555');
  const parts = list.map((r, i)=>{
    const lib = RELAY_LIBRARY[r.model] || RELAY_LIBRARY['אחר'];
    const rows = lib.info.map(([k,l])=>[l, (r.info||{})[key(k)]]).filter(x=>x[1]);
    const setRows = lib.settings.map(([k,l,u])=>[l, (r.settings||{})[key(k)], u && !u.startsWith('select') ? u : '']).filter(x=>x[1]);
    const exRows = lib.extra.map(([k,l])=>[l, (r.extra||{})[key(k)]]).filter(x=>x[1]);
    // מצב DIP — רק לקבוצות שסומנו בפועל; מתג 1 משמאל (כמו על הממסר), ■ = ON
    const dips = lib.dips.filter(([k])=>(r.dips||{})[k] !== undefined).map(([k,l,n])=>{ const b = relayDipBits((r.dips||{})[k], n); return `<div style="margin:3px 0; display:flex; align-items:center; gap:8px;"><b style="min-width:140px;">${escapeHtml(l)}:</b><span style="display:inline-flex; direction:ltr; gap:2px;">${b.split('').map((x, xi)=>`<span style="display:inline-block; min-width:15px; text-align:center; border:1px solid #777; font-size:9.5px; -webkit-print-color-adjust:exact; print-color-adjust:exact; background:${x==='1'?'#1f3a5c':'#fff'}; color:${x==='1'?'#fff':'#333'};">${xi+1}</span>`).join('')}</span></div>`; }).join('');
    return `<h3>ממסר הגנה #${i+1}: ${escapeHtml(r.model)}${r.location ? ' — ' + escapeHtml(r.location) : ''}</h3>
      <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px; align-items:start; break-inside:avoid; page-break-inside:avoid;">
        <div style="min-width:0;"><table class="tinfo-table">${[['יצרן', lib.maker || (r.info||{}).maker || ''], ...rows].filter(x=>x[1]).map(x=>`<tr><td class="tinfo-label">${escapeHtml(x[0])}</td><td>${spBdi(x[1])}</td></tr>`).join('')}
          ${exRows.map(x=>`<tr><td class="tinfo-label">${escapeHtml(x[0])}</td><td style="color:${color(x[1])}; font-weight:700;">${escapeHtml(x[1])}</td></tr>`).join('')}</table></div>
        <div style="min-width:0;">${setRows.length ? `<table class="tinfo-table"><tr><td class="tinfo-label" style="text-align:center;">הגדרה</td><td style="font-weight:700; text-align:center;">ערך</td></tr>${setRows.map(x=>`<tr><td class="tinfo-label">${escapeHtml(x[0])}</td><td><bdi dir="ltr">${escapeHtml(x[1])}${x[2] ? ' <span style="color:#666;">' + escapeHtml(x[2].split(' / ')[0] === x[2] ? x[2] : '') + '</span>' : ''}</bdi></td></tr>`).join('')}</table>` : ''}</div>
      </div>
      ${dips ? `<div style="font-size:11px; margin:6px 0 2px;">${dips}<div style="color:#666; font-size:10px;">■ = ON · □ = OFF</div></div>` : ''}
      ${r.notes ? `<p style="font-size:12px; margin:4px 0;"><b>הערות:</b> ${escapeHtml(r.notes)}</p>` : ''}`;
  });
  return [{ level:1, sectionKey:'protection-relays', title:'ממסרי הגנה', html:`<h2>ממסרי הגנה</h2>${parts.join('')}` }];
}


// =====================================================================================
// ===== 📚 חוק החשמל ותקנותיו — ספר תקנות חכם (v2.2.523) ===============================
// הקובץ (PDF) מועלה ע"י מנהל-על בלבד; האפליקציה מפרקת אותו בדפדפן לתקנות → פרקים → סעיפים,
// שומרת בענן (טבלת library_docs + קובץ המקור ב-bucket "library") — כל משתמש מחובר יכול לקרוא.
// ההרשאות נאכפות בשרת (RLS: is_super_admin), לא רק בהסתרת כפתור. הטקסט נשמר גם במכשיר לעבודה בלי רשת.
// =====================================================================================
const LAW_DOC_ID = 'electricity-law';
const LAW_PDFJS = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js';
const LAW_PDFJS_WORKER = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
let lawDoc = null, lawLoading = false, lawTried = false, lawError = '', lawIsAdmin = null, lawQuery = '', lawOpenReg = -1, lawOpenSec = null, lawUploadInfo = null;
// מפרק PDF של חוק/תקנות החשמל: תוכן עניינים → תקנות → פרקים → סעיפים. רץ גם בדפדפן (pdf.js) וגם ב-Node.
async function lawExtractLines(pdfDoc, onProgress){
  const pages = [];
  for(let pn = 1; pn <= pdfDoc.numPages; pn++){
    const page = await pdfDoc.getPage(pn);
    const tc = await page.getTextContent();
    const rows = [];
    tc.items.forEach(it => {
      if(!it.str) return;
      const y = it.transform[5], x = it.transform[4], w = it.width || 0;
      let r = rows.find(r => Math.abs(r.y - y) < 2.5);
      if(!r){ r = { y, items: [] }; rows.push(r); }
      r.items.push({ x, w, s: it.str });
    });
    rows.sort((a, b) => b.y - a.y);
    pages.push(rows.map(r => {
      r.items.sort((a, b) => (b.x + b.w) - (a.x + a.w));
      let out = '', prevLeft = null;
      r.items.forEach(it => {
        const right = it.x + it.w;
        if(prevLeft !== null && prevLeft - right > 1.5 && !/\s$/.test(out) && !/^\s/.test(it.s)) out += ' ';
        out += it.s; prevLeft = it.x;
      });
      return out.replace(/[\u200e\u200f\u202a-\u202e]/g, '').replace(/\s+/g, ' ').trim();
    }).filter(Boolean));
    if(onProgress) onProgress(pn, pdfDoc.numPages);
  }
  return pages;
}
function lawStructure(pages){
  const junk = l => /^תוכן זה הועתק באישור/.test(l) || /^חזרה לעמוד/.test(l) || /^\d{1,3}$/.test(l) || /^תוכן$/.test(l);
  const toc = [];
  for(let p = 0; p < Math.min(3, pages.length); p++){
    pages[p].forEach(l => {
      const m = l.match(/^(.*?)\s*\.{4,}[\s.]*(\d{1,3})\s*(.*)$/);
      if(m){ const title = (m[1] + ' ' + (m[3]||'')).replace(/\s*\.{2,}\s*/g, ' ').replace(/\s+/g,' ').replace(/\s*-\s*$/, '').trim(); toc.push({ title, page: parseInt(m[2], 10) }); }
    });
  }
  toc.sort((a,b)=>a.page-b.page);
  const key = t => t.replace(/[^א-ת0-9]/g, '').slice(0, 18);
  // תחילת כל תקנה: השורה בעמוד ההתחלה שתואמת לכותרת (תקנה יכולה להתחיל באמצע עמוד)
  const regs = toc.map((t, i) => {
    const lines = pages[t.page - 1] || [];
    let li = lines.findIndex(l => key(l) && key(l) === key(t.title));
    if(li < 0) li = lines.findIndex(l => key(l).slice(0, 12) === key(t.title).slice(0, 12));
    return { id: 'r' + (i+1), title: t.title, page: t.page, startLine: li < 0 ? 0 : li, sections: [] };
  });
  regs.forEach((reg, ri) => {
    const next = regs[ri + 1];
    let chapter = '', cur = null, last = 0, lastSuf = '';
    // סגנון הסעיפים בתקנה: "N. כותרת" (כותרת קצרה) או "N. (א) טקסט" — לפי מה שנפוץ יותר בה. בתקנה בסגנון
    // כותרות, שורה ממוספרת ארוכה היא פסקה בתוך סעיף ולא סעיף חדש.
    let shortCnt = 0, longCnt = 0;
    for(let p = reg.page; p <= Math.min(pages.length, next ? next.page : pages.length); p++){
      (pages[p - 1] || []).forEach(l => { const mm = l.match(/^(\d{1,3})[א-ת]?\s*\.\s*(.*)$/); if(!mm) return; const r = mm[2].trim(); if(/^\([א-ת]\)/.test(r)) longCnt++; else if(r.length > 0 && r.length <= 70 && !/[;,.:]$/.test(r)) shortCnt++; });
    }
    const allowLong = longCnt >= shortCnt;
    for(let p = reg.page; p <= pages.length; p++){
      const lines = pages[p - 1] || [];
      for(let li = 0; li < lines.length; li++){
        if(p === reg.page && li <= reg.startLine) continue;
        if(next && (p > next.page || (p === next.page && li >= next.startLine))) { p = pages.length + 1; break; }
        const l = lines[li];
        if(junk(l)) continue;
        if(/^(פרק|סימן)\s+[^\s]+\s*[:\-–']/.test(l) && l.length < 90){ chapter = l; continue; }
        const m = l.match(/^(?:(\d{1,3})([א-ת]?)\s*\.|\((\d{1,3})([א-ת]?)\)(?=\s))\s*(.*)$/);
        if(m){
          const n = parseInt(m[1] || m[3], 10), suf = m[2] || m[4] || '', rest = (m[5] || '').trim();
          const shortTitle = rest.length > 0 && rest.length <= 70 && !/[;,.:]$/.test(rest);
          const strictNext = (last === 0 && n <= 2) || n === last + 1 || (n === last && suf && suf !== lastSuf);
          // דילוג קדימה (סעיף שבוטל / הופיע בטבלה): כותרת קצרה עד +4, או סגנון "N. טקסט" עד +3
          // "N. טקסט" עם דילוג — רק כשזה נראה כמו פתיחת סעיף: "N. (א) …", שורה שמסתיימת ב-':' או ארוכה מאוד (פסקאות ממוספרות בתוך סעיף מסתיימות ב-';' או '.')
          const longStart = /^\([א-ת]\)/.test(rest) || /:$/.test(rest) || rest.length > 90;
          const jumpOk = n > last && ((n <= last + 4 && shortTitle) || (!m[3] && n <= last + 3 && last >= 3 && longStart));
          const paren = !!m[3];   // סגנון "(N) כותרת" — חייב כותרת קצרה (אחרת זו פסקה ממוספרת בתוך סעיף)
          if(rest && (strictNext || jumpOk) && (shortTitle || ((strictNext || jumpOk) && !paren && (allowLong || /^\([א-ת]\)/.test(rest))))){
            last = n; lastSuf = suf;
            cur = shortTitle ? { num: n + suf, title: rest, chapter, page: p, text: '' }
                             : { num: n + suf, title: rest.replace(/^\([א-ת]\)\s*/, '').slice(0, 60) + (rest.length > 60 ? '…' : ''), chapter, page: p, text: rest };
            reg.sections.push(cur); continue;
          }
        }
        if(!cur){ cur = { num: '', title: 'מבוא', chapter, page: p, text: '' }; reg.sections.push(cur); }
        cur.text += (cur.text ? '\n' : '') + l;
      }
    }
    reg.sections.forEach(x => { x.text = x.text.trim(); });
    delete reg.startLine;
  });
  return { toc, regs };
}


function lawCacheGet(){ try{ return JSON.parse(localStorage.getItem('rdLawCache') || 'null'); }catch(e){ return null; } }
function lawCacheSet(d){ try{ localStorage.setItem('rdLawCache', JSON.stringify(d)); }catch(e){} }
function lawFavs(){ try{ return JSON.parse(localStorage.getItem('rdLawFavs') || '[]'); }catch(e){ return []; } }
function lawSetFavs(a){ try{ localStorage.setItem('rdLawFavs', JSON.stringify(a)); }catch(e){} }
async function lawLoad(force){
  if(lawLoading) return;
  if(!lawDoc) lawDoc = lawCacheGet();
  if(!(supabaseClient && cloudCurrentUser)){ if(!lawDoc) lawError = 'יש להתחבר לחשבון כדי לטעון את חוק החשמל בפעם הראשונה (אחר כך הוא נשמר במכשיר).'; return; }
  lawLoading = true;
  try{
    if(lawIsAdmin === null){ try{ const { data } = await supabaseClient.rpc('is_super_admin'); lawIsAdmin = !!data; }catch(e){ lawIsAdmin = false; } }
    const { data: meta, error: e1 } = await supabaseClient.from('library_docs').select('updated_at').eq('id', LAW_DOC_ID).maybeSingle();
    if(e1) throw e1;
    if(!meta){ lawDoc = null; lawError = ''; }
    else if(force || !lawDoc || lawDoc.updated_at !== meta.updated_at){
      const { data, error } = await supabaseClient.from('library_docs').select('id,title,version_label,source_note,data,pdf_path,pages,sections_count,updated_at').eq('id', LAW_DOC_ID).maybeSingle();
      if(error) throw error;
      lawDoc = data; lawCacheSet(data); lawError = '';
    }
  }catch(e){ lawError = lawDoc ? '' : ('טעינת חוק החשמל נכשלה: ' + (e.message || e)); }
  lawLoading = false;
  if(activeTab === 'toolbox') render();
}
function lawRegShort(title){ return String(title||'').replace(/^תקנות החשמל\s*-\s*/, '').replace(/^תקנות\s*/, ''); }
// הפניה לציטוט בדוח, למשל: "תקנה 13 לתקנות החשמל (הארקות יסוד), תשמ"א-1981"
function lawCitation(reg, sec){
  const m = String(reg.title||'').match(/^(תקנות [^-–(]+?)\s*[-–]\s*(.+?),\s*(.+)$/);
  const regName = m ? `${m[1].trim()} (${m[2].trim()}), ${m[3].trim()}` : reg.title;
  return sec && sec.num ? `תקנה ${sec.num} ל${regName}${sec.title && sec.title !== 'מבוא' ? ` — ${sec.title.replace(/…$/, '')}` : ''}` : regName;
}
function lawHighlight(text, q){
  const t = escapeHtml(text);
  if(!q) return t;
  const words = q.split(/\s+/).filter(w => w.length > 1).map(w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  if(!words.length) return t;
  return t.replace(new RegExp('(' + words.join('|') + ')', 'g'), '<mark>$1</mark>');
}
function lawSearch(q){
  const words = q.split(/\s+/).filter(w => w.length > 1);
  const out = [];
  if(!lawDoc || !words.length) return out;
  const numQ = q.match(/^(?:תקנה|סעיף)?\s*(\d{1,3}[א-ת]?)$/);
  lawDoc.data.regs.forEach((reg, ri) => reg.sections.forEach((sec, si) => {
    const hay = (sec.title + ' ' + sec.text + ' ' + sec.chapter);
    let score = 0;
    if(numQ && sec.num === numQ[1]) score = 5;
    else if(words.every(w => hay.includes(w))) score = words.every(w => sec.title.includes(w)) ? 3 : 1;
    if(score) out.push({ ri, si, score });
  }));
  return out.sort((a, b) => b.score - a.score).slice(0, 80);
}
function lawSnippet(text, q){
  const w = q.split(/\s+/).find(x => x.length > 1) || '';
  const i = w ? text.indexOf(w) : -1;
  const start = Math.max(0, i - 60);
  return (start ? '…' : '') + text.slice(start, start + 180).replace(/\n/g, ' ') + (text.length > start + 180 ? '…' : '');
}
function renderLawLibraryCard(){
  if(!lawDoc) lawDoc = lawCacheGet();
  // טעינה אחת לכל כניסה לארגז הכלים (בלי לולאת טעינות כשעוד לא הועלה מסמך)
  if(!lawTried && !lawLoading){ lawTried = true; setTimeout(()=>lawLoad(false), 0); }
  const favs = lawFavs();
  const d = lawDoc && lawDoc.data;
  const adminTools = lawIsAdmin ? `
      <details class="sp-gen" ${!lawDoc ? 'open' : ''}><summary>🔐 ניהול (מנהל בלבד) — העלאה / עדכון של חוק החשמל</summary>
        <p style="font-size:12.5px; color:var(--text-dim); margin:0 0 8px;">מעלים את קובץ ה-PDF המלא. האפליקציה מפרקת אותו לתקנות וסעיפים, מציגה סיכום לבדיקה, ורק אחרי אישור מפרסמת לכל המשתמשים. הגרסה הקודמת מוחלפת.</p>
        <label class="add-btn" style="display:inline-flex; width:auto; cursor:pointer;">📄 בחר קובץ PDF<input type="file" accept="application/pdf,.pdf" data-lawupload="1" style="display:none;"></label>
        <div id="lawUploadStatus">${lawUploadInfo ? lawUploadInfo.html : ''}</div>
      </details>` : '';
  let body = '';
  if(lawLoading && !lawDoc) body = `<p class="sp-grp-hint">⏳ טוען את חוק החשמל…</p>`;
  else if(!lawDoc) body = `<p class="sp-grp-hint">${escapeHtml(lawError || 'חוק החשמל עדיין לא הועלה למערכת. מנהל המערכת יכול להעלות אותו כאן.')}</p>`;
  else if(lawOpenSec){
    const reg = d.regs[lawOpenSec.ri], sec = reg && reg.sections[lawOpenSec.si];
    if(sec){
      const key = reg.id + '|' + sec.num + '|' + sec.title;
      const isFav = favs.includes(key);
      body = `<div class="law-sec">
        <button type="button" class="del-panel-btn" data-lawback="1">→ חזרה</button>
        <div class="law-crumb">${escapeHtml(lawRegShort(reg.title))}${sec.chapter ? ' · ' + escapeHtml(sec.chapter) : ''}</div>
        <h3 class="law-sec-title">${sec.num ? `<span class="law-num">${escapeHtml(sec.num)}</span>` : ''}${lawHighlight(sec.title, lawQuery)}</h3>
        <div class="law-text">${lawHighlight(sec.text || '', lawQuery)}</div>
        <div class="law-actions">
          <button type="button" class="add-btn" data-lawcite="${lawOpenSec.ri}|${lawOpenSec.si}">📋 העתק הפניה לדוח</button>
          <button type="button" class="add-btn" data-lawfav="${escapeAttr(key)}">${isFav ? '★ הסר ממועדפים' : '☆ הוסף למועדפים'}</button>
          ${lawDoc.pdf_path ? `<button type="button" class="add-btn" data-lawpdf="${sec.page}">📄 פתח בעמוד ${sec.page} במקור</button>` : ''}
        </div>
        <p class="sp-grp-hint">ההפניה: «${escapeHtml(lawCitation(reg, sec))}»</p>
      </div>`;
    }
  } else if(lawQuery.trim().length >= 2){
    const res = lawSearch(lawQuery.trim());
    body = `<div class="law-results-count">${res.length ? `נמצאו ${res.length >= 80 ? '80+' : res.length} סעיפים` : 'לא נמצאו תוצאות'}</div>` + res.map(r => {
      const reg = d.regs[r.ri], sec = reg.sections[r.si];
      return `<button type="button" class="law-item" data-lawopen="${r.ri}|${r.si}">
        <div class="law-item-head">${sec.num ? `<span class="law-num">${escapeHtml(sec.num)}</span>` : ''}<b>${lawHighlight(sec.title, lawQuery)}</b></div>
        <div class="law-item-reg">${escapeHtml(lawRegShort(reg.title))}</div>
        <div class="law-item-snip">${lawHighlight(lawSnippet(sec.text || '', lawQuery.trim()), lawQuery)}</div></button>`;
    }).join('');
  } else {
    const favItems = favs.map(k => { const [rid, num, title] = k.split('|'); const ri = d.regs.findIndex(r => r.id === rid); const si = ri >= 0 ? d.regs[ri].sections.findIndex(s => s.num === num && s.title === title) : -1; return si >= 0 ? { ri, si } : null; }).filter(Boolean);
    body = (favItems.length ? `<div class="sp-sub">⭐ מועדפים</div>` + favItems.map(f => { const reg = d.regs[f.ri], sec = reg.sections[f.si]; return `<button type="button" class="law-item" data-lawopen="${f.ri}|${f.si}"><div class="law-item-head">${sec.num ? `<span class="law-num">${escapeHtml(sec.num)}</span>` : ''}<b>${escapeHtml(sec.title)}</b></div><div class="law-item-reg">${escapeHtml(lawRegShort(reg.title))}</div></button>`; }).join('') : '')
      + `<div class="sp-sub">התקנות (${d.regs.length})</div>`
      + d.regs.map((reg, ri) => `<div class="law-reg${lawOpenReg === ri ? ' open' : ''}">
          <button type="button" class="law-reg-head" data-lawreg="${ri}"><span>${escapeHtml(lawRegShort(reg.title))}</span><span class="law-reg-count">${reg.sections.length} סעיפים · עמ' ${reg.page} ${lawOpenReg === ri ? '▲' : '▼'}</span></button>
          ${lawOpenReg === ri ? `<div class="law-reg-body">${(()=>{ let lastCh = null; return reg.sections.map((sec, si) => { const ch = sec.chapter && sec.chapter !== lastCh ? `<div class="law-ch">${escapeHtml(sec.chapter)}</div>` : ''; lastCh = sec.chapter; return ch + `<button type="button" class="law-row" data-lawopen="${ri}|${si}">${sec.num ? `<span class="law-num">${escapeHtml(sec.num)}</span>` : '<span class="law-num">·</span>'}<span>${escapeHtml(sec.title)}</span></button>`; }).join(''); })()}</div>` : ''}
        </div>`).join('');
  }
  return `
    <section class="card open" data-key="toolbox-law">
      <div class="card-head" data-toggle="toolbox-law"><h2>📚 חוק החשמל ותקנותיו</h2><span class="chev">▾</span></div>
      <div class="card-body">
        ${lawDoc ? `<p class="sp-grp-hint" style="margin-top:0;">${escapeHtml(lawDoc.version_label || '')}${lawDoc.updated_at ? ' · עודכן ' + new Date(lawDoc.updated_at).toLocaleDateString('he-IL') : ''} · ${lawDoc.sections_count || ''} סעיפים${lawDoc.source_note ? '<br>' + escapeHtml(lawDoc.source_note) : ''}</p>` : ''}
        ${lawDoc ? `<div class="law-search"><input type="search" id="lawSearch" value="${escapeAttr(lawQuery)}" placeholder="🔎 חיפוש: מילה, ביטוי או מספר תקנה (למשל: פס השוואת פוטנציאלים / תקנה 13)"></div>` : ''}
        <div class="law-body">${body}</div>
        ${adminTools}
      </div>
    </section>`;
}
// מנהל: פירוק ה-PDF בדפדפן → סיכום לבדיקה → פרסום (העלאת המקור + שמירת הטקסט המפורק)
async function lawParseUpload(file, onProgress){
  if(typeof pdfjsLib === 'undefined' && !window['pdfjs-dist/build/pdf']) await loadScriptOnce(LAW_PDFJS);
  const lib = window.pdfjsLib || window['pdfjs-dist/build/pdf'];
  lib.GlobalWorkerOptions.workerSrc = LAW_PDFJS_WORKER;
  const doc = await lib.getDocument({ data: new Uint8Array(await file.arrayBuffer()) }).promise;
  const pages = await lawExtractLines(doc, onProgress);
  const st = lawStructure(pages);
  return { st, pages: doc.numPages };
}
async function lawPublish(file, parsed, versionLabel){
  const path = LAW_DOC_ID + '.pdf';
  const up = await supabaseClient.storage.from('library').upload(path, file, { upsert: true, contentType: 'application/pdf' });
  if(up.error) throw up.error;
  const sections = parsed.st.regs.reduce((a, r) => a + r.sections.length, 0);
  const row = { id: LAW_DOC_ID, title: 'חוק החשמל ותקנותיו', version_label: versionLabel || ('גרסה ' + new Date().toLocaleDateString('he-IL')),
    source_note: 'מקור: הקובץ שהועלה ע"י מנהל המערכת. במידה ויימצאו הבדלים — הגרסה הרשמית היא הקובעת.', data: parsed.st, pdf_path: path,
    pages: parsed.pages, sections_count: sections, updated_at: new Date().toISOString(), updated_by: cloudCurrentUser.id };
  const { error } = await supabaseClient.from('library_docs').upsert(row);
  if(error) throw error;
  lawDoc = row; lawCacheSet(row);
  return sections;
}
function lawSetState(k, v){ if(k==='q') lawQuery = v; else if(k==='reg') lawOpenReg = v; else if(k==='sec') lawOpenSec = v; else if(k==='upload') lawUploadInfo = v; }
function lawGetDoc(){ return lawDoc; }
async function lawOpenPdfPage(page){
  const { data, error } = await supabaseClient.storage.from('library').createSignedUrl(lawDoc.pdf_path, 3600);
  if(error || !data) throw (error || new Error('לא ניתן לפתוח את הקובץ'));
  window.open(data.signedUrl + '#page=' + page, '_blank');
}

function findMatchingEquipment(checkboxName){
  if(!checkboxName || checkboxName === 'אחר') return null;
  // v2.2.536 — קודם חיפש רק ברשימה המקומית, בזמן שהרשימה בסעיף 01 נלקחת מהענן → מס' סידורי ותוקף כיול
  // לא נמצאו ולא הודפסו. עכשיו: קודם ברשימת הענן, ואז ברשימה המקומית.
  const cloud = (supabaseClient && cloudCurrentUser && cloudEquipmentCache) ? cloudEquipmentCache.map(normalizeCloudEquipment) : [];
  const pool = cloud.concat(equipmentList || []);
  const exact = pool.find(e => e.name === checkboxName);
  if(exact) return exact;
  const needle = checkboxName.toLowerCase();
  return pool.find(e => {
    const hay = (e.name||'').toLowerCase();
    return hay.includes(needle) || needle.includes(hay);
  }) || null;
}

function instrumentDetailsText(name){
  const label = name === 'אחר' ? (state.meta.testInstrumentsOther || 'אחר') : name;
  const eq = findMatchingEquipment(name);
  const parts = [];
  if(eq && eq.model && eq.model !== label) parts.push(`דגם ${eq.model}`);
  parts.push(`מס' סידורי: ${eq && eq.serialNo ? eq.serialNo : '—'}`);
  parts.push(`תוקף כיול: ${eq && eq.calibrationDate ? formatDateIL(eq.calibrationDate) : '—'}`);
  return name === 'אחר' && !eq ? label : `${label} — ${parts.join(' · ')}`;
}
function getCalibrationStatus(calibrationDateStr){
  if(!calibrationDateStr) return null;
  const calDate = new Date(calibrationDateStr + 'T00:00:00');
  if(isNaN(calDate.getTime())) return null;
  const today = new Date(); today.setHours(0,0,0,0);
  const daysLeft = Math.round((calDate - today) / (1000*60*60*24));
  if(daysLeft < 0) return 'expired';
  if(daysLeft <= 60) return 'warning';
  return 'ok';
}

function insulationTable(path, data, rowLabels){
  const labels = rowLabels || INSULATION_ROWS;
  const rowsData = data.rows;
  const method = data.testMethod || 'dar';
  const isPI = method === 'pi';
  const isSpot = method === 'spot';
  const label1 = isSpot ? 'ערך נמדד' : (isPI ? 'R (1 דקה)' : 'R (15 שנ\')');
  const label2 = isSpot ? `טמפרטורה (°C)` : (isPI ? 'R (10 דקות)' : 'R (60 שנ\')');
  const ratioLabel = isSpot ? `מתוקן ל-${INSULATION_REFERENCE_TEMP_C}°C` : (isPI ? 'PI' : 'DAR');
  let rows = labels.map((label,i)=>{
    const d = rowsData[i];
    const unit = d.unit || 'MΩ';
    let computedDisplay, classification = null;
    if(isSpot){
      const measured = parseFloat(d.r15), temp = parseFloat(d.temp);
      const corrected = correctInsulationForTemperature(measured, temp);
      computedDisplay = corrected !== null ? `${corrected.toFixed(2)} ${unit}` : '—';
    } else {
      const v1 = parseFloat(d.r15), v2 = parseFloat(d.r60);
      const ratio = (!isNaN(v1) && !isNaN(v2) && v1 > 0) ? (v2/v1) : null;
      classification = ratio !== null ? classifyInsulationRatio(method, ratio) : null;
      computedDisplay = ratio !== null ? ratio.toFixed(2) : '—';
    }
    const col2 = isSpot
      ? `<input type="text" inputmode="decimal" placeholder="${unit}" data-inspath="${path}.rows.${i}.r15" data-restrict="decimal" value="${escapeAttr(d.r15)}">`
      : `<input type="text" inputmode="decimal" placeholder="${unit}" data-inspath="${path}.rows.${i}.r15" data-restrict="decimal" value="${escapeAttr(d.r15)}">`;
    const col3 = isSpot
      ? `<input type="text" inputmode="decimal" placeholder="°C" data-inspath="${path}.rows.${i}.temp" data-restrict="decimal" value="${escapeAttr(d.temp)}">`
      : `<input type="text" inputmode="decimal" placeholder="${unit}" data-inspath="${path}.rows.${i}.r60" data-restrict="decimal" value="${escapeAttr(d.r60)}">`;
    return `<tr>
      <td class="lbl-cell">
        ${label}
        <select class="unit-toggle" data-textpath="${path}.rows.${i}.unit" style="width:auto; min-width:56px; padding:2px 4px; font-size:11px;">${INSULATION_METHOD_UNIT_OPTIONS.map(u=>`<option value="${u}" ${unit===u?'selected':''}>${u}</option>`).join('')}</select>
      </td>
      <td>${col2}</td>
      <td>${col3}</td>
      <td class="ins-ratio-display" data-inscomputed="${path}.rows.${i}">${computedDisplay}</td>
      <td>
        ${classification ? `<span class="ins-badge ${classification.cls}">${classification.label}</span><br>` : `
        <select data-inspath="${path}.rows.${i}.manualClassification" style="margin-bottom:4px; width:100%;">
          <option value="">-- סיווג --</option>
          <option value="תקין" ${d.manualClassification==='תקין'?'selected':''}>תקין</option>
          <option value="לא תקין" ${d.manualClassification==='לא תקין'?'selected':''}>לא תקין</option>
          <option value="נדרש לטפל" ${d.manualClassification==='נדרש לטפל'?'selected':''}>נדרש לטפל</option>
        </select>`}
        <input type="text" placeholder="הערה" data-inspath="${path}.rows.${i}.note" value="${escapeAttr(d.note)}" style="margin-top:4px;">
      </td>
    </tr>`;
  }).join('');
  return `
    <div class="field ins-method-select">
      <label>שיטת בדיקה</label>
      <select data-textpath="${path}.testMethod">
        <option value="dar" ${method==='dar'?'selected':''}>DAR — יחס R60/R15 שניות (בדיקה מהירה)</option>
        <option value="pi" ${isPI?'selected':''}>PI — יחס R10/R1 דקות (בדיקה מלאה, 10 דק')</option>
        <option value="spot" ${isSpot?'selected':''}>בדיקה רגילה — ערך בודד עם תיקון טמפרטורה</option>
      </select>
      <p style="font-size:10.5px; color:var(--text-dim); margin:4px 0 0;">
        ${isSpot
          ? `הערך מתוקן לטמפרטורת ייחוס ${INSULATION_REFERENCE_TEMP_C}°C לפי כלל האצבע המקובל (התנגדות נחצית בכל 10°C עלייה) — קירוב שדה מקובל, אינו מחליף טבלה מדויקת לפי סוג בידוד ספציפי. אין סף תקין/לא-תקין אוטומטי — יש להשוות לערך הנדרש לפי המפרט/תקן החל.`
          : `הסיווג האוטומטי מבוסס על ערכי סף כלליים מקובלים בתעשייה — אינו מחליף שיפוט הנדסי מול תקן/מפרט ספציפי.`}
      </p>
    </div>
    <table class="ins-table">
    <thead><tr><th></th><th>${label1}</th><th>${label2}</th><th>${ratioLabel}</th><th>סיווג / הערה</th></tr></thead>
    <tbody>${rows}</tbody></table>`;
}

