// שדות תצורת כבל מובנים (מספר גידים/שטח חתך/גיד נוסף/כמות במקביל/סוג כבל) לצד אחד (ראשוני
// או משני) של שנאי בית — Reuse יחיד לשני הצדדים, לא שכפול קוד. לפי בקשה מפורשת: כל שדה הוא
// dropdown מובנה (selectWithCustom הקיים, שכבר תומך ב"אחר"+הזנה ידנית מובנית), לא טקסט חופשי.
function cableConfigFields(prefix, path, d){
  const coreCount = d[prefix+'CoreCount'], coreSection = d[prefix+'CoreSection'], additionalCoreSection = d[prefix+'AdditionalCoreSection'], parallelRuns = d[prefix+'ParallelRuns'], cableType = d[prefix+'CableType'];
  const preview = formatCableConfig(coreCount, coreSection, additionalCoreSection, parallelRuns);
  const legacySpec = d[prefix+'Spec'];
  return `
    ${legacySpec && !coreCount && !coreSection ? `<p style="font-size:11px; color:var(--text-dim); background:#12161a; border:1px solid var(--line); border-radius:8px; padding:8px 10px; margin-bottom:8px;">ערך קודם (טקסט חופשי, מדוח ישן): <b>${escapeHtml(legacySpec)}</b> — ניתן להזין להלן תצורה מובנית עדכנית; הערך הקודם נשמר ולא נמחק.</p>` : ''}
    <div class="grid2">
      ${selectWithCustom('סוג כבל', `${path}.${prefix}CableType`, cableType, INSTALLATION_CABLE_TYPE_OPTIONS)}
      ${selectWithCustom('מספר גידים', `${path}.${prefix}CoreCount`, coreCount, INSTALLATION_CONDUCTOR_COUNT_OPTIONS)}
      ${selectWithCustom('שטח חתך גיד (mm²)', `${path}.${prefix}CoreSection`, coreSection, CABLE_CROSS_SECTION_OPTIONS)}
      ${selectWithCustom('גיד נוסף / אפס / הארקה (mm², ריק=ללא)', `${path}.${prefix}AdditionalCoreSection`, additionalCoreSection, CABLE_CROSS_SECTION_OPTIONS)}
      ${selectWithCustom('כמות כבלים/סטים במקביל', `${path}.${prefix}ParallelRuns`, parallelRuns, CABLE_PARALLEL_RUNS_OPTIONS)}
    </div>
    ${preview ? `<p style="font-size:12.5px; font-weight:700; color:var(--amber); margin:4px 0 10px;">תצורת כבל: ${escapeHtml(preview)}</p>` : ''}`;
}

