/* ---------- Panel section builder ---------- */

// סרגל הפרקים (איחוד דוחות, v2.187) — מוצג תמיד מעל תוכן הדוח, כדי שהפיצ'ר יהיה גלוי גם
// למי שעדיין לא השתמש בו. הדוח הראשי מוצג ככרטיסיה ראשונה קבועה; פרקים נוספים אחריו.
function renderChaptersBar(){
  // כשפרק אחר פעיל, formTypeName החי מציג את סוג הפרק הנוכחי, לא את הראשי — שם הראשי נשלף
  // מה-backup השמור, כדי שהכרטיסייה שלו תמיד תציג את הסוג הנכון בלי קשר לאיפה שנמצאים כרגע.
  const primaryLabel = getTypeDisplayLabel(state.activeChapterIndex === -1
    ? state.settings.formTypeName
    : (state.primaryChapterBackup ? state.primaryChapterBackup.formTypeName : 'הדוח הראשי'));

  const tabs = [
    `<button type="button" class="chapter-tab ${state.activeChapterIndex===-1?'active':''}" data-chapterswitch="-1">📄 ${escapeHtml(primaryLabel)}</button>`,
    ...state.reportChapters.map((ch,i) => `
      <span class="chapter-tab-wrap">
        <button type="button" class="chapter-tab ${state.activeChapterIndex===i?'active':''}" data-chapterswitch="${i}">📄 ${escapeHtml(ch.label)}</button>
        <button type="button" class="chapter-tab-del" data-chapterdel="${i}" title="מחק פרק">✕</button>
      </span>`)
  ].join('');

  return `
    <div class="chapters-bar">
      ${tabs}
      <button type="button" class="chapter-tab chapter-tab-add" id="btnAddChapter">+ הוסף פרק (דוח נוסף)</button>
      ${state.reportChapters.length ? `<button type="button" class="chapter-tab chapter-tab-order" data-rdchorder="toggle">⇅ סדר הדוחות ב-PDF</button>` : ''}
    </div>
    ${state.reportChapters.length && window.__rdChOrderOpen ? (()=>{
      const order = getChapterPrintOrder();
      const pl = getTypeDisplayLabel(state.activeChapterIndex === -1 ? state.settings.formTypeName : (state.primaryChapterBackup ? state.primaryChapterBackup.formTypeName : 'הדוח הראשי'));
      return `<div class="rd-chorder"><div class="rd-chorder-title">סדר הדוחות בקובץ ה-PDF (עמוד השער תמיד ראשון, האישור והחתימות תמיד בסוף):</div>
        ${order.map((id, pos)=>{ const lbl = id === 'primary' ? pl : ((state.reportChapters.find(c=>c.id===id)||{}).label || ''); return `<div class="rd-chorder-row"><span class="sp-row-num">${pos+1}</span><b>${escapeHtml(lbl)}</b>${id==='primary' ? ' <span style="font-size:12px; color:var(--text-dim);">(הדוח הראשי — פרטי המזמין)</span>' : ''}<span style="flex:1"></span>
          <button type="button" class="del-panel-btn" data-rdchorder="up|${pos}" ${pos===0?'disabled':''} title="הזז למעלה">↑</button>
          <button type="button" class="del-panel-btn" data-rdchorder="down|${pos}" ${pos===order.length-1?'disabled':''} title="הזז למטה">↓</button></div>`; }).join('')}
      </div>`; })() : ''}`;
}

function openAddChapterModal(){
  const categoryButtons = FORM_TYPE_CATEGORIES.map(cat => `
    <button type="button" class="form-type-option" data-chapteraddtype-folder="${escapeAttr(cat.name)}">${escapeHtml(cat.name)} ›</button>`).join('');
  const modal = document.createElement('div');
  modal.className = 'modal-overlay';
  modal.innerHTML = `
    <div class="modal-box" style="max-width:480px;">
      <h3 style="margin-top:0;">איזה סוג בדיקה להוסיף כפרק נוסף?</h3>
      <p style="font-size:12.5px; color:var(--text-dim);">הפרק החדש יתווסף לדוח הנוכחי כחלק נפרד, עם התמונות והנתונים שלו בנפרד — לא ישפיע על מה שכבר מולא.</p>
      <div id="chapterAddTypeBody" style="display:flex; flex-direction:column; gap:8px; max-height:50vh; overflow-y:auto;">${categoryButtons}</div>
      <button type="button" class="secondary-btn" id="btnCloseChapterAddModal" style="margin-top:14px; width:100%;">ביטול</button>
    </div>`;
  document.body.appendChild(modal);

  const body = modal.querySelector('#chapterAddTypeBody');
  const showCategory = (catName) => {
    const cat = FORM_TYPE_CATEGORIES.find(c=>c.name===catName);
    if(!cat) return;
    body.innerHTML = `
      <button type="button" class="secondary-btn" id="btnBackToChapterFolders" style="align-self:flex-start;">‹ חזרה לתיקיות</button>
      ${cat.types.map(t => `<button type="button" class="form-type-option" data-chapteraddtype="${escapeAttr(t)}">${escapeHtml(t)}</button>`).join('')}`;
    body.querySelector('#btnBackToChapterFolders').addEventListener('click', ()=>{ body.innerHTML = categoryButtons; attachFolderHandlers(); });
    body.querySelectorAll('[data-chapteraddtype]').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const typeName = btn.getAttribute('data-chapteraddtype');
        modal.remove();
        addNewChapter(typeName);
      });
    });
  };
  const attachFolderHandlers = () => {
    body.querySelectorAll('[data-chapteraddtype-folder]').forEach(btn=>{
      btn.addEventListener('click', ()=> showCategory(btn.getAttribute('data-chapteraddtype-folder')));
    });
  };
  attachFolderHandlers();
  modal.querySelector('#btnCloseChapterAddModal').addEventListener('click', ()=> modal.remove());
  modal.addEventListener('click', (e)=>{ if(e.target === modal) modal.remove(); });
}

