/* ---------- Soil resistivity report cards ---------- */

function convertToMegaOhm(value, unit){
  const number = Number(value);
  if(!Number.isFinite(number) || number < 0) return null;
  switch(unit){
    case 'Ω': return number / 1000000;
    case 'kΩ': return number / 1000;
    case 'MΩ': return number;
    case 'GΩ': return number * 1000;
    case 'TΩ': return number * 1000000;
    default: return null;
  }
}

function formatMeasurement(value, unit){
  if(value === '' || value === null || value === undefined || value === '—' || !Number.isFinite(Number(value))) return 'לא נמדד';
  const n = Number(value);
  return `${n.toLocaleString('he-IL', { maximumFractionDigits: 2 })} ${unit || ''}`.trim();
}

function formatInsulationValue(value, unit){
  if(value === '' || value === null || value === undefined) return 'לא נמדד';
  const trimmed = String(value).trim();
  if(trimmed.startsWith('>') || trimmed.startsWith('<')) return `${trimmed} ${unit || ''}`.trim();
  return formatMeasurement(value, unit);
}

function highlightWrongWord(sentence, wrongWord){
  if(!wrongWord) return escapeHtml(sentence);
  const escapedSentence = escapeHtml(sentence);
  const escapedWord = escapeHtml(wrongWord);
  // Escape must happen before highlighting so we don't break HTML, then find the (now-escaped) word to wrap.
  const idx = escapedSentence.indexOf(escapedWord);
  if(idx === -1) return escapedSentence; // word not found verbatim (e.g. escaped differently) — show plain
  return escapedSentence.slice(0, idx) +
    `<mark style="background:#ffe08a; color:#5a3e00; font-weight:700; padding:0 2px; border-radius:3px;">${escapedWord}</mark>` +
    escapedSentence.slice(idx + escapedWord.length);
}

function resultCheckmarkHtml(result){
  if(result === 'תקין') return `<span style="color:#1e7e42; font-weight:700;">✓ תקין</span>`;
  if(result === 'לא תקין') return `<span style="color:#c0392b; font-weight:700;">✗ לא תקין</span>`;
  if(result === 'N.A' || result === 'לא רלוונטי') return `<span style="color:#888; font-weight:700;">${escapeHtml(result)}</span>`;
  return escapeHtml(result || '');
}

function buildDarResult(row){
  const dc = state.dcCableTest;
  if(!dc.performDAR) return null;
  const darMin = parseFloat(dc.darMin);
  const hasMin = !isNaN(darMin);

  const r30p = parseFloat(row.r30Positive), r60p = parseFloat(row.r60Positive);
  const r30n = parseFloat(row.r30Negative), r60n = parseFloat(row.r60Negative);
  const hasPos = !isNaN(r30p) && !isNaN(r60p) && r30p !== 0;
  const hasNeg = !isNaN(r30n) && !isNaN(r60n) && r30n !== 0;
  const darPos = hasPos ? r60p / r30p : null;
  const darNeg = hasNeg ? r60n / r30n : null;

  const hasReadings = hasPos || hasNeg;
  const dar = hasReadings ? Math.min(...[darPos, darNeg].filter(v => v !== null)) : null;
  let ok = null;
  if(dar !== null && hasMin) ok = dar >= darMin;
  return { dar, darPos, darNeg, hasReadings, hasMin, ok };
}

function buildPiResult(row){
  const dc = state.dcCableTest;
  if(!dc.performPI) return null;
  const piMin = parseFloat(dc.piMin);
  const hasMin = !isNaN(piMin);

  const r1p = parseFloat(row.r1minPositive), r10p = parseFloat(row.r10minPositive);
  const r1n = parseFloat(row.r1minNegative), r10n = parseFloat(row.r10minNegative);
  const hasPos = !isNaN(r1p) && !isNaN(r10p) && r1p !== 0;
  const hasNeg = !isNaN(r1n) && !isNaN(r10n) && r1n !== 0;
  const piPos = hasPos ? r10p / r1p : null;
  const piNeg = hasNeg ? r10n / r1n : null;

  const hasReadings = hasPos || hasNeg;
  const pi = hasReadings ? Math.min(...[piPos, piNeg].filter(v => v !== null)) : null;
  let ok = null;
  if(pi !== null && hasMin) ok = pi >= piMin;
  return { pi, piPos, piNeg, hasReadings, hasMin, ok };
}

function buildDcCableRowResult(row){
  const posMO = (row.insulationPositive !== '' && row.insulationPositive !== null && row.insulationPositive !== undefined)
    ? convertToMegaOhm(row.insulationPositive, row.insulationPositiveUnit) : null;
  const negMO = (row.insulationNegative !== '' && row.insulationNegative !== null && row.insulationNegative !== undefined)
    ? convertToMegaOhm(row.insulationNegative, row.insulationNegativeUnit) : null;
  const hasPos = posMO !== null, hasNeg = negMO !== null;
  const minRequiredMO = (row.minRequired !== '' && row.minRequired !== null && row.minRequired !== undefined)
    ? convertToMegaOhm(row.minRequired, row.minRequiredUnit) : null;
  const hasMinRequired = minRequiredMO !== null;

  let rMinMeasured = null; // expressed in MΩ (common base unit) for accurate cross-unit comparison
  if(hasPos && hasNeg) rMinMeasured = Math.min(posMO, negMO);
  else if(hasPos) rMinMeasured = posMO;
  else if(hasNeg) rMinMeasured = negMO;

  const hasInsulationData = rMinMeasured !== null;
  const visualOk = row.visual === 'תקין' || row.visual === 'לא רלוונטי';
  const visualBad = row.visual === 'לא תקין';
  const polarityOk = row.polarityResult === 'תקין' || row.polarityResult === 'לא רלוונטי';
  const polarityBad = row.polarityResult === 'קוטביות הפוכה';
  const insulationOk = hasInsulationData && hasMinRequired && rMinMeasured >= minRequiredMO;
  const insulationBad = hasInsulationData && hasMinRequired && rMinMeasured < minRequiredMO;

  const darCalc = buildDarResult(row);
  const piCalc = buildPiResult(row);
  const darOk = !darCalc || darCalc.ok === null || darCalc.ok === true;
  const darBad = darCalc && darCalc.ok === false;
  const piOk = !piCalc || piCalc.ok === null || piCalc.ok === true;
  const piBad = piCalc && piCalc.ok === false;

  const hasCriticalMissing = !hasInsulationData || !hasMinRequired || !row.visual || !row.polarityResult
    || (darCalc && (!darCalc.hasReadings)) || (piCalc && (!piCalc.hasReadings));

  let result, cls;
  if(insulationBad){
    result = 'לא תקין – ערך הבידוד נמוך מהערך הנדרש';
    cls = 'dc-bad';
  } else if(polarityBad){
    result = 'לא תקין – נמצאה קוטביות הפוכה';
    cls = 'dc-bad';
  } else if(visualBad){
    result = 'לא תקין – נמצא ליקוי בבדיקה הוויזואלית';
    cls = 'dc-bad';
  } else if(darBad){
    result = 'לא תקין – תוצאת DAR נמוכה מהנדרש';
    cls = 'dc-bad';
  } else if(piBad){
    result = 'לא תקין – תוצאת PI נמוכה מהנדרש';
    cls = 'dc-bad';
  } else if(hasCriticalMissing){
    result = 'לא ניתן לקבוע';
    cls = 'dc-undetermined';
  } else if(visualOk && polarityOk && insulationOk && darOk && piOk){
    result = 'תקין';
    cls = 'dc-ok';
  } else {
    result = 'לא ניתן לקבוע';
    cls = 'dc-undetermined';
  }

  const printClsMap = { 'dc-ok': 'row-pass', 'dc-bad': 'row-fail', 'dc-undetermined': 'row-warning' };
  return { rMinMeasured, hasInsulationData, hasMinRequired, darCalc, piCalc, result, cls, printCls: printClsMap[cls] };
}

function buildGroundingReadingCalc(location){
  const r52 = parseFloat(location.readings.r52);
  const r62 = parseFloat(location.readings.r62);
  const r72 = parseFloat(location.readings.r72);
  if(isNaN(r52) || isNaN(r62) || isNaN(r72)) return null;

  // שלב 1 – חישוב התנגדות ממוצעת
  const avgRaw = (r52 + r62 + r72) / 3;
  const avg = Math.round(avgRaw * 100) / 100; // rounded to 2 decimals, used in subsequent steps

  // שלב 2 – חישוב הסטייה של כל מדידה מהממוצע
  const dR52 = Math.abs(r52 - avg);
  const dR62 = Math.abs(r62 - avg);
  const dR72 = Math.abs(r72 - avg);

  // שלב 3 – בחירת הסטייה הגדולה ביותר
  const dRmax = Math.max(dR52, dR62, dR72);

  // שלב 4 – חישוב אחוז הסטייה (הגנה מחלוקה באפס)
  const devPct = avg !== 0 ? (dRmax / avg) * 100 : null;

  // שלב 5 – בדיקת יציבות המדידה
  const deviationOk = devPct !== null && devPct <= 10;

  // שלב 6 – חישוב התנגדות האלקטרודה
  const periodOpt = GROUNDING_PERIOD_OPTIONS.find(p=>p.label === state.groundingTest.measurementPeriod);
  const k = periodOpt ? parseFloat(periodOpt.k) : 1.0;
  const corrected = avg * k; // Re

  // שלב 7 – בדיקת תקינות מול הערך המרבי המותר
  const maxAllowed = parseFloat(state.groundingTest.maxAllowedResistance);
  const hasMaxAllowed = !isNaN(maxAllowed);
  const withinLimit = hasMaxAllowed ? corrected <= maxAllowed : null;
  const isValid = deviationOk && (withinLimit === true);

  return { r52, r62, r72, avg, dR52, dR62, dR72, dRmax, devPct, deviationOk, k, corrected, maxAllowed, hasMaxAllowed, withinLimit, isValid };
}

function buildGroundingCalcTraceHtml(calc){
  if(!calc) return '<p style="font-size:11px; color:var(--text-dim);">הזן את כל שלוש הקריאות (52%, 62%, 72%) כדי לראות חישוב אוטומטי.</p>';

  const devColor = calc.deviationOk ? 'var(--ok, #3fa34d)' : 'var(--bad, #e0503a)';
  const stabilityText = calc.deviationOk
    ? 'תקין – יציבות המדידה עומדת בדרישות'
    : 'לא תקין – הסטייה בין המדידות עולה על 10%, יש להגדיל את מרחק האלקטרודות ולבצע בדיקה חוזרת';
  const pillBg = calc.deviationOk ? '#eaf7ec' : '#fbeae7';

  const devLine = calc.devPct !== null
    ? `&Delta;Rmax = ${calc.dRmax.toFixed(2)} Ω &middot; Deviation = <b style="color:${devColor};">${calc.devPct.toFixed(2)}%</b>`
    : '&Delta;Rmax = לא ניתן לחשב — הממוצע הוא אפס';

  return `
    <div class="ground-calc-box">
      <div class="ground-calc-trace" style="font-family:'Consolas','Courier New',monospace; font-size:12px; direction:ltr; text-align:left; line-height:1.6;">
        <div>Ravg = (${calc.r52} + ${calc.r62} + ${calc.r72}) / 3 = <b>${calc.avg.toFixed(2)} Ω</b></div>
        <div>${devLine}</div>
        <div>Re = <b>${calc.corrected.toFixed(2)} Ω</b></div>
      </div>
      <div class="ground-status-pill" style="margin-top:8px; direction:rtl; text-align:center; color:${devColor}; font-weight:700; background:${pillBg}; border-radius:14px; padding:5px 10px;">${stabilityText}</div>
    </div>`;
}

function buildGroundingSlopeChartSvg(location, currentStakeDistanceStr, isEn, correctedValue){
  const D = parseFloat(currentStakeDistanceStr);
  const r52 = parseFloat(location.readings.r52);
  const r62 = parseFloat(location.readings.r62);
  const r72 = parseFloat(location.readings.r72);
  const points = [
    { pct: 52, dist: D * 0.52, val: r52 },
    { pct: 62, dist: D * 0.62, val: r62 },
    { pct: 72, dist: D * 0.72, val: r72 }
  ].filter(p => !isNaN(p.val) && !isNaN(D) && D > 0);

  const W = 460, H = 205;
  const padL = 44, padR = 14, padT = 18, padB = 32;
  const plotW = W - padL - padR, plotH = H - padT - padB;

  const hasCorrected = typeof correctedValue === 'number' && !isNaN(correctedValue);
  const validD = !isNaN(D) && D > 0;

  if(!validD || !points.length){
    return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" style="background:#fff; max-width:100%;">
      <text x="${W/2}" y="${H/2}" font-size="9.5" text-anchor="middle" fill="#999">מלא את מרחק יתד הזרם (D) וקריאות ההתנגדות</text>
    </svg>`;
  }

  const yVals = points.map(p=>p.val).concat(hasCorrected ? [correctedValue] : []);
  const yLow = Math.min(...yVals);
  const yHigh = Math.max(...yVals);
  const yMin = Math.max(0, yLow - yLow * 0.10);
  let yMax = yHigh + yHigh * 0.10;
  if(yMax === yMin) yMax = yMin + 1;

  const xAt = (x) => padL + (x / D) * plotW;
  const yAt = (v) => padT + plotH - ((v - yMin) / (yMax - yMin)) * plotH;

  // Grid + axis ticks (X in real meters from 0 to D)
  const gridLines = [];
  const xTickCount = 6;
  for(let i=0; i<=xTickCount; i++){
    const xVal = (D / xTickCount) * i;
    const px = xAt(xVal);
    gridLines.push(`<line x1="${px}" y1="${padT}" x2="${px}" y2="${padT+plotH}" stroke="#e2e2e2" stroke-width="1"></line>`);
    gridLines.push(`<text x="${px}" y="${padT+plotH+14}" font-size="8" text-anchor="middle" fill="#666">${xVal.toFixed(1)}</text>`);
  }
  const yTickCount = 5;
  for(let i=0; i<=yTickCount; i++){
    const yVal = yMin + ((yMax - yMin) / yTickCount) * i;
    const py = yAt(yVal);
    gridLines.push(`<line x1="${padL}" y1="${py}" x2="${padL+plotW}" y2="${py}" stroke="#e2e2e2" stroke-width="1"></line>`);
    gridLines.push(`<text x="${padL-5}" y="${py+3}" font-size="8" text-anchor="end" fill="#666">${yVal.toFixed(1)}</text>`);
  }

  // Smooth Catmull-Rom-style curve through the (up to) 3 measured points — visual guide only
  function smoothPath(pts){
    if(pts.length < 2) return '';
    let d = `M ${pts[0].x} ${pts[0].y}`;
    for(let i=0; i<pts.length-1; i++){
      const p0 = pts[i===0?0:i-1], p1 = pts[i], p2 = pts[i+1], p3 = pts[i+2<pts.length?i+2:i+1];
      for(let t=0.05; t<=1.0001; t+=0.05){
        const t2=t*t, t3=t2*t;
        const x = 0.5*((2*p1.x)+(-p0.x+p2.x)*t+(2*p0.x-5*p1.x+4*p2.x-p3.x)*t2+(-p0.x+3*p1.x-3*p2.x+p3.x)*t3);
        const y = 0.5*((2*p1.y)+(-p0.y+p2.y)*t+(2*p0.y-5*p1.y+4*p2.y-p3.y)*t2+(-p0.y+3*p1.y-3*p2.y+p3.y)*t3);
        d += ` L ${x} ${y}`;
      }
    }
    return d;
  }
  const pts = points.map(p => ({ x: xAt(p.dist), y: yAt(p.val) }));
  const curveHtml = pts.length >= 2
    ? `<path d="${smoothPath(pts)}" fill="none" stroke="#3366cc" stroke-width="2.5"></path>`
    : '';

  // Vertical dashed line at 62% + label directly on the line (לפי עיצוב הדוגמה — לא
  // שורת R62 כתומה נפרדת, אלא התווית המלאה של הנקודה ישירות ליד הקו המקווקו הסגול).
  const p62 = points.find(p => p.pct === 62);
  const x62val = p62 ? xAt(p62.dist) : xAt(D*0.62);
  let line62Html = '';
  if(p62){
    line62Html = `<line x1="${x62val}" y1="${padT}" x2="${x62val}" y2="${padT+plotH}" stroke="#9b59b6" stroke-width="1.5" stroke-dasharray="5 4"></line>`;
  }

  // Corrected-value reference line (average × k), kept as an additional analytical aid
  const correctedLineHtml = hasCorrected
    ? `<line x1="${padL}" y1="${yAt(correctedValue)}" x2="${padL+plotW}" y2="${yAt(correctedValue)}" stroke="#3fa34d" stroke-width="1.5" stroke-dasharray="2 3"></line>
       <text x="${padL+plotW-3}" y="${yAt(correctedValue)-5}" font-size="8.5" text-anchor="end" fill="#2d7d3a" font-weight="700">מתוקן: ${correctedValue.toFixed(2)}Ω</text>`
    : '';

  // Data point markers + labels ("52% · dist m · val Ω", בדיוק כמו בדוגמה), 62% עם
  // סמן גדול יותר ותווית משלה (לא מודחקת) ליד הקו המקווקו.
  const markersHtml = points.map((p,i) => {
    const px = xAt(p.dist), py = yAt(p.val);
    const isMain = p.pct === 62;
    const color = isMain ? '#9b59b6' : '#1c3f6e';
    const r = isMain ? 5.5 : 3.5;
    const label = `${p.pct}% &middot; ${p.dist.toFixed(1)}m &middot; ${p.val}Ω`;
    // *** שכבות אנכיות ברורות לפי pct (לא רק אינדקס) — מונע חפיפה גם כש-D קטן וכל
    // הנקודות קרובות זו לזו אופקית (נצפה בבדיקה חזותית: תוויות 52%/72% התנגשו). ***
    const yOff = p.pct === 52 ? -20 : p.pct === 62 ? -14 : 20;
    const dx = isMain ? 0 : (p.pct === 52 ? -10 : 10);
    const anchor = isMain ? 'middle' : (dx < 0 ? 'end' : 'start');
    return `
      <circle cx="${px}" cy="${py}" r="${r}" fill="${color}" stroke="#fff" stroke-width="1.2"></circle>
      <text x="${px+dx}" y="${py+yOff}" font-size="8.5" text-anchor="${anchor}" fill="${color}" font-weight="700">${label}</text>`;
  }).join('');

  const xAxisLabel = isEn ? 'Distance from electrode [m]' : 'מרחק מהאלקטרודה [m]';
  const yAxisLabel = isEn ? 'Resistance [Ω]' : 'התנגדות [Ω]';

  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" style="background:#fff; max-width:100%; display:block;">
    ${gridLines.join('')}
    <line x1="${padL}" y1="${padT}" x2="${padL}" y2="${padT+plotH}" stroke="#333" stroke-width="1.5"></line>
    <line x1="${padL}" y1="${padT+plotH}" x2="${padL+plotW}" y2="${padT+plotH}" stroke="#333" stroke-width="1.5"></line>
    ${line62Html}
    ${correctedLineHtml}
    ${curveHtml}
    ${markersHtml}
    <text x="${W/2}" y="${H-4}" font-size="9" text-anchor="middle" fill="#333">${xAxisLabel}</text>
    <text x="11" y="${padT+plotH/2}" font-size="9" text-anchor="middle" fill="#333" transform="rotate(-90 11 ${padT+plotH/2})">${yAxisLabel}</text>
  </svg>`;
}

function renderGroundingTestCards(){
  const gt = state.groundingTest;
  const method = gt.testMethod || 'slope'; // 'slope' | 'clamp' | 'selective' — לא שם עברי כ-key

  const helpButtonHtml = `
    <button type="button" class="add-panel-card" id="btnGroundingHelp" style="margin-bottom:14px; border-color:var(--amber); color:var(--amber);">
      ❓ עזרה — הסבר על הבדיקה ואופן ביצועה
    </button>`;

  // *** בורר שיטת בדיקה — GROUNDING אחד, לא Report Type נפרד. Visibility בלבד: מחליף
  // איזה UI מוצג, לעולם לא מוחק state (clampTests/selectiveTests/locations נשארים
  // שמורים גם כשלא מוצגים כרגע — ראו mergeDefaults, שכבר תומך בזה). ***
  const methodSelectorHtml = `
    <section class="card open" data-key="ground-method">
      <div class="card-head" data-toggle="ground-method">
        <h2><span class="num">01</span> שיטת בדיקה</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        <div class="field">
          <label>שיטת בדיקה</label>
          <select data-textpath="groundingTest.testMethod">
            ${GROUNDING_TEST_METHOD_OPTIONS.map(o=>`<option value="${o.key}" ${method===o.key?'selected':''}>${o.label}</option>`).join('')}
          </select>
        </div>
      </div>
    </section>`;

  const equipSection = `
    <section class="card" data-key="ground-equip">
      <div class="card-head" data-toggle="ground-equip">
        <h2><span class="num">02</span> פרטי הבדיקה והמכשיר</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        ${textField('שם המתקן/המבנה הנבדק', 'groundingTest.siteEquipmentName', gt.siteEquipmentName)}
        <div class="field">
          <label>מרחק יתד הזרם מהאלקטרודה הנבדקת (מ', מומלץ 50)</label>
          <input type="text" data-restrict="decimal" id="groundCurrentStakeInput" value="${escapeAttr(gt.currentStakeDistance)}">
        </div>
        <p style="font-size:11px; color:var(--text-dim); margin-top:4px;">
          לפי שיטת ה-Fall of Potential: יתד הפוטנציאל ימוקם ב-52%, 62%, ו-72% מהמרחק הזה — המרחקים בפועל (במטרים) יחושבו אוטומטית למטה בכל מיקום מדידה.
        </p>
        ${selectWithCustom('תקופת מדידה של התנגדות הארקה', 'groundingTest.measurementPeriod', gt.measurementPeriod, GROUNDING_PERIOD_OPTIONS.map(p=>p.label))}
        <p style="font-size:11px; color:var(--text-dim); margin-top:4px;">התקופה קובעת את מקדם התיקון (k) המוחל אוטומטית על ההתנגדות הממוצעת.</p>
        <div class="field" style="margin-top:10px;">
          <label>ערך התנגדות מרבי מותר — Rmax (Ω)</label>
          <input type="text" data-restrict="decimal" data-textpath="groundingTest.maxAllowedResistance" value="${escapeAttr(gt.maxAllowedResistance)}">
        </div>
      </div>
    </section>`;

  const standardsSection = `
    <section class="card" data-key="ground-standards">
      <div class="card-head" data-toggle="ground-standards">
        <h2><span class="num">03</span> מסמכי ייחוס ותקנים</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        <p style="font-size:11px; color:var(--text-dim); margin-top:0;">בטל סימון של תקן שאינו רלוונטי לבדיקה זו.</p>
        <div class="decl-list">
          ${GROUNDING_STANDARDS.map((s,i)=>`
            <label class="decl-item ${gt.standardsOn[i] ? 'on' : ''}">
              <input type="checkbox" data-groundstandardtoggle="${i}" ${gt.standardsOn[i] ? 'checked' : ''}>
              <span><b>${s.code}</b> — ${s.purpose}</span>
            </label>`).join('')}
        </div>
      </div>
    </section>`;

  const dist = parseFloat(gt.currentStakeDistance) || 0;
  const d52 = (dist*0.52).toFixed(1), d62 = (dist*0.62).toFixed(1), d72 = (dist*0.72).toFixed(1);

  const locationsHtml = gt.locations.map((loc, li) => {
    const calc = buildGroundingReadingCalc(loc);
    const validReadings = [loc.readings.r52, loc.readings.r62, loc.readings.r72].map(v=>parseFloat(v)).filter(v=>!isNaN(v));
    const avgReading = validReadings.length ? validReadings.reduce((s,v)=>s+v,0)/validReadings.length : null;
    const calcHtml = buildGroundingCalcTraceHtml(calc);
    const chartSvg = buildGroundingSlopeChartSvg(loc, gt.currentStakeDistance, false, calc ? calc.corrected : NaN);
    return `
      <div class="resistivity-loc-block">
        <div class="project-row">
          <input type="text" placeholder="שם מיקום המדידה * (למשל: חדר מתח גבוה ראשי)" data-inspath="groundingTest.locations.${li}.name" value="${escapeAttr(loc.name)}">
          <button type="button" class="del-panel-btn" data-delrow="groundingTest.locations|${li}">מחק מיקום</button>
        </div>
        <div class="subhead" style="font-size:11.5px;">קריאות התנגדות (Ω) בשלוש נקודות הבדיקה</div>
        <div class="resistivity-grid">
          <div class="field" style="min-width:110px;"><label style="font-size:10px;">52% (${d52} מ')</label><input type="text" data-restrict="decimal" data-groundreading="${li}|r52" value="${escapeAttr(loc.readings.r52)}"></div>
          <div class="field" style="min-width:110px;"><label style="font-size:10px;">62% (${d62} מ') — עיקרי</label><input type="text" data-restrict="decimal" data-groundreading="${li}|r62" value="${escapeAttr(loc.readings.r62)}"></div>
          <div class="field" style="min-width:110px;"><label style="font-size:10px;">72% (${d72} מ')</label><input type="text" data-restrict="decimal" data-groundreading="${li}|r72" value="${escapeAttr(loc.readings.r72)}"></div>
          <div class="field" style="min-width:110px;"><label style="font-size:10px;">ממוצע 3 הקריאות</label><input type="text" value="${avgReading !== null ? avgReading.toFixed(2) : ''}" readonly style="opacity:.8;"></div>
        </div>
        ${calcHtml}
        ${chartSvg ? `<div class="chart-preview">${chartSvg}</div>` : ''}
      </div>`;
  }).join('');

  const resultsSection = `
    <section class="card" data-key="ground-results">
      <div class="card-head" data-toggle="ground-results">
        <h2><span class="num">04</span> מיקומי מדידה ותוצאות</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        ${locationsHtml}
        <button type="button" class="add-btn" data-addrow="groundingTest.locations|${escapeAttr(JSON.stringify({name:'',readings:{r52:'',r62:'',r72:''}}))}">+ הוסף מיקום מדידה</button>
      </div>
    </section>`;

  const connectionSection = `
    <section class="card" data-key="ground-connection">
      <div class="card-head" data-toggle="ground-connection">
        <h2><span class="num">05</span> תיעוד חיבור וביצוע</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        <p style="font-size:11px; color:var(--text-dim); margin-top:0;">
          תמונה או סקיצה של אופן ביצוע החיבור בשטח (מיקום יתדות הזרם והפוטנציאל ביחס לאלקטרודה הנבדקת).
        </p>
        ${soilPhotoGallery('groundingTest.connectionPhotos', gt.connectionPhotos)}
      </div>
    </section>`;

  const anyValid = method === 'slope'
    ? gt.locations.some(loc => { const c = buildGroundingReadingCalc(loc); return c && c.isValid; })
    : (method === 'clamp' ? gt.clampTests : gt.selectiveTests).some(t => {
        const st = t.status || calcGroundingAutoStatus(t.correctedResistance, t.maxAllowed);
        return st === 'תקין';
      });
  const validNoteHtml = method === 'slope'
    ? (anyValid ? `<div class="ground-valid-note">✓ בבדיקה נמצא שהערך הנמדד תקין. הערך שהתקבל: ${gt.locations.map(l=>buildGroundingReadingCalc(l)).filter(c=>c&&c.isValid).map(c=>c.corrected.toFixed(2)+' Ω').join(', ')} (מתחת לערך המרבי המותר: ${escapeHtml(gt.maxAllowedResistance)} Ω).</div>` : '')
    : (anyValid ? `<div class="ground-valid-note">✓ נמצאו תוצאות תקינות בבדיקה.</div>` : '');

  const notesSection = `
    <section class="card" data-key="ground-notes">
      <div class="card-head" data-toggle="ground-notes">
        <h2><span class="num">06</span> הערות</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        ${validNoteHtml}
        ${textareaField('הערות נוספות', 'groundingTest.notes', gt.notes)}
        <div class="subhead" style="font-size:11.5px;">תיעוד/צילום נוסף</div>
        ${soilPhotoGallery('groundingTest.notesPhotos', gt.notesPhotos)}
      </div>
    </section>`;

  const slopeBlocksHtml = (method === 'slope') ? (equipSection + standardsSection + resultsSection + connectionSection) : '';
  const clampBlocksHtml = (method === 'clamp') ? (buildGroundingClampEquipSection(gt) + buildGroundingClampCardsSection(gt)) : '';
  const selectiveBlocksHtml = (method === 'selective') ? (buildGroundingSelectiveEquipSection(gt) + buildGroundingSelectiveCardsSection(gt)) : '';

  return helpButtonHtml + methodSelectorHtml + slopeBlocksHtml + clampBlocksHtml + selectiveBlocksHtml + notesSection;
}

// *** Clamp — פרטי מכשיר ותנאי סביבה. שדות ריקים לא יוצגו ב-PDF בהמשך (זו רק בדיקת
// "אם שדה ריק" בשלב ה-PDF, לא כאן). supportsSelectiveGroundTest לא רלוונטי ל-clamp
// עצמו (רק ל-selective, ראו למטה) — לא מוצג כאן.
// בורר תמונת-ברירה קבועה, מסונן לפי method (Clamp/Selective) - נפרד מ-principleImages
// (העלאה אישית). Reuse בשתי הפונקציות למטה, לא בלוק קוד משוכפל.
function buildGroundingPrincipleImagePresetSelector(method, gt){
  const options = GROUNDING_PRINCIPLE_PRESET_IMAGES.filter(p=>p.method===method);
  if(!options.length) return '';
  return `
    <div class="field">
      <label>אפשרויות 1–3: תרשים אוטומטי, או תמונת המחשה מרשימה קבועה</label>
      <select data-textpath="groundingTest.selectedPresetImageId">
        <option value="">אפשרות 1 — ללא, השתמש בתרשים האוטומטי</option>
        ${options.map((p,i)=>`<option value="${p.id}" ${gt.selectedPresetImageId===p.id?'selected':''}>אפשרות ${i+2} — ${escapeHtml(p.label)}</option>`).join('')}
      </select>
    </div>`;
}

