    cloudDebugLog('טוען רשימת דוחות מהענן…');
    cloudReportBrowserResults = await listCloudReports();
    cloudDebugLog(`נטענו ${cloudReportBrowserResults.length} דוחות`);
    cloudReportBrowserLoading = false;
    render();
