  const btnSaveClient = document.getElementById('btnSaveClient');
  if(btnSaveClient) btnSaveClient.addEventListener('click', async ()=>{
    if(!clientFormDraft.name || !clientFormDraft.name.trim()){
      showToast('יש להזין שם לקוח');
      return;
    }
    if(!clientFormDraft.address || !clientFormDraft.address.trim()){
      showToast('יש להזין כתובת לקוח');
      return;
    }
    const validContacts = (clientFormDraft.contacts||[]).filter(c=>c.name && c.name.trim() && c.phone && c.phone.trim());
    if(!validContacts.length){
      showToast('יש להזין לפחות איש קשר אחד עם שם וטלפון');
      return;
    }
    const validEmails = (clientFormDraft.emails||[]).filter(e=>e && e.trim());
    if(!validEmails.length){
      showToast('יש להזין לפחות כתובת דוא"ל אחת');
      return;
    }
    const invalidEmail = validEmails.find(e=>!e.includes('@'));
    if(invalidEmail){
      showToast('כתובת הדוא"ל חייבת להכיל @');
      return;
    }
    const toSave = JSON.parse(JSON.stringify(clientFormDraft));
    toSave.contacts = validContacts;
    toSave.emails = validEmails;

    const usingCloud = !!(supabaseClient && cloudCurrentUser);
    if(usingCloud){
      // PHASE 2: Supabase הוא מקור האמת — יוצרים/מעדכנים שם קודם, ורק אחרי הצלחה מעדכנים
      // את שני המטמונים (cloudClientsCache + clientsList המקומי) כדי שיישארו עקביים.
      const cloudRow = clientFormDraft.id
        ? await updateClient(clientFormDraft.id, toSave)
        : await createClient(toSave);
      if(cloudRow){
        if(cloudClientsCache){
          const idx = cloudClientsCache.findIndex(c=>c.id===cloudRow.id);
          if(idx >= 0) cloudClientsCache[idx] = cloudRow; else cloudClientsCache.push(cloudRow);
        }
        toSave.id = cloudRow.id;
        await addOrUpdateClient(toSave); // מעדכן גם את ה-cache המקומי, item 9 במפרט
        showToast('הלקוח נשמר בענן');
      } else {
        showToast('שגיאה בשמירת הלקוח בענן — נשמר מקומית בלבד');
        if(!toSave.id) toSave.id = 'client_' + Date.now() + '_' + Math.random().toString(36).slice(2,7);
        await addOrUpdateClient(toSave);
      }
    } else {
      if(!toSave.id) toSave.id = 'client_' + Date.now() + '_' + Math.random().toString(36).slice(2,7);
      await addOrUpdateClient(toSave);
      showToast('הלקוח נשמר מקומית');
    }
    clientFormDraft = makeEmptyClientDraft();
    render();
  });

