  document.querySelectorAll('.dc-table tr[class] input, .dc-table tr[class] select').forEach(el=>{
    el.addEventListener('input', ()=>{
      const path = el.getAttribute('data-textpath');
      if(!path) return;
      const m = path.match(/^dcCableTest\.groups\.(\d+)\.rows\.(\d+)\./);
      if(!m) return;
      const gi = parseInt(m[1],10), ri = parseInt(m[2],10);
      const row = state.dcCableTest.groups[gi] && state.dcCableTest.groups[gi].rows[ri];
      if(!row) return;
      const tr = el.closest('tr');
      const calc = buildDcCableRowResult(row);
      tr.className = calc.cls;
      const resultCell = tr.querySelector('.dc-result-cell');
      if(resultCell) resultCell.textContent = calc.result;

      const pidarCells = tr.querySelectorAll('.dc-pidar-cell');
      if(pidarCells.length >= 2){
        function badgeHtml(c, ratioVal){
          if(!c) return '<span style="color:var(--text-dim); font-size:11px;">—</span>';
          if(!c.hasReadings) return '<span style="color:var(--warn,#c67405); font-size:10px;">חסרות קריאות</span>';
          const color = c.ok === true ? 'var(--ok,#3fa34d)' : (c.ok === false ? 'var(--bad,#e0503a)' : 'var(--text-dim)');
          return `<span style="color:${color}; font-weight:700; font-size:11px;">${ratioVal.toFixed(2)}</span>`;
        }
        function updateBadgeCell(cell, calcResult, ratioVal){
          // If the cell has input fields (DAR/PI reading inputs), only update the badge div within it,
          // never replace the cell's whole innerHTML — doing so would destroy the input the user is typing into.
          const badgeDiv = cell.querySelector('.dc-pidar-badge');
          if(badgeDiv){ badgeDiv.innerHTML = badgeHtml(calcResult, ratioVal); }
          else { cell.innerHTML = badgeHtml(calcResult, ratioVal); }
        }
        updateBadgeCell(pidarCells[0], calc.darCalc, calc.darCalc ? calc.darCalc.dar : null);
        updateBadgeCell(pidarCells[1], calc.piCalc, calc.piCalc ? calc.piCalc.pi : null);
      }
    });
  });

