      const inst = genRoot.installations[idx];
      if(!inst) return;
      const titlePreview = inst.installationName
        ? (inst.location ? `${inst.installationName} – ${inst.location}` : inst.installationName)
        : `מתקן ${idx+1}`;
      const cardEl = document.querySelector(`[data-instid="${inst.id}"]`);
      const titleEl = cardEl ? cardEl.querySelector('h3') : null;
      if(titleEl) titleEl.textContent = `🏢 ${titlePreview}`;
