function openMedicalHelpModal(kind){
  let body;
  if(kind === 'transformer'){
    body = `<div style="font-size:12.5px; line-height:1.7;">${MEDICAL_ISOLATION_TRANSFORMER_HELP}</div>`;
  } else if(kind === 'floatingSupply'){
    body = `<div style="font-size:12.5px; line-height:1.7;">${MEDICAL_FLOATING_SUPPLY_HELP}</div>`;
  } else if(kind === 'insulationMonitor'){
    body = `<div style="font-size:12.5px; line-height:1.7;">${MEDICAL_INSULATION_MONITOR_HELP}</div>`;
  } else if(kind === 'paPe'){
    body = `<div style="font-size:12.5px; line-height:1.7;">${MEDICAL_PA_PE_HELP}</div>`;
  } else {
    const roomType = state.medicalReport.roomType;
    const idx = MEDICAL_ROOM_TYPE_OPTIONS.indexOf(roomType);
    if(idx === -1){
      body = `<p style="font-size:12.5px; color:var(--text-dim);">יש לבחור קודם סוג מתקן רפואי בסעיף "05 — סוג המתקן הרפואי הנבדק", וההסבר המתאים יופיע כאן אוטומטית.</p>`;
    } else {
      body = `
        <p style="font-size:12.5px; font-weight:700; color:var(--amber); margin-top:0;">${escapeHtml(roomType)}</p>
        <div style="font-size:12.5px; line-height:1.7;">${MEDICAL_ROOM_TYPE_HELP[idx]}</div>`;
    }
  }
  const headerTitle = document.querySelector('#dcDetailsModal .preview-modal-header h3');
  if(headerTitle) headerTitle.textContent = '❓ איך מבצעים את הבדיקה';
  document.getElementById('dcDetailsBody').innerHTML = body;
  document.getElementById('dcDetailsModal').classList.add('show');
}

