function validateRequiredInspectionFields(){
  const missing = [];
  if(!state.meta.siteName || !state.meta.siteName.trim()) missing.push('שם המתקן/האתר');
  if(!state.meta.address || !state.meta.address.trim()) missing.push('כתובת המתקן');
  if(!state.meta.client || !state.meta.client.trim()) missing.push('המזמין');
  if(!state.meta.project || !state.meta.project.trim()) missing.push('פרויקט');
  if(!state.meta.attentionTo || !state.meta.attentionTo.trim()) missing.push('לידי (איש קשר)');
  if(!state.meta.description || !state.meta.description.trim()) missing.push('תיאור העבודה/המתקן');
  if(getReportType() === 'GROUNDING'){
    const hasNamedLocation = (state.groundingTest.locations||[]).some(l => l.name && l.name.trim());
    if(!hasNamedLocation) missing.push('מיקום המדידה');
  }
  return missing;
}

