// ===== בדיקת חוסרים לפני תצוגה מקדימה (v2.2.538) =====
// מחזיר רשימת פריטים חסרים: { label, card, path } — card = מפתח הכרטיס בטופס, path = השדה (אם יש)
function collectMissingReportItems(){
  const out = [];
  const add = (label, card, path) => out.push({ label, card, path: path || '' });
  const empty = v => !String(v == null ? '' : v).trim();
  const t = getReportType();
  if(t === 'FIRE_FORM3'){
    const f = getFireForm3();
    if(empty(f.fireFileNumber)) add("מס' תיק ברשות הכבאות", 'f3-business', 'fireForm3.fireFileNumber');
    if(empty(f.facilityName)) add('שם העסק', 'f3-business', 'fireForm3.facilityName');
    if(empty(f.city)) add('יישוב', 'f3-business', 'fireForm3.city');
    if(empty(f.inspectorName)) add('פרטי מבצע הבדיקה — שם מלא', 'f3-inspector', 'fireForm3.inspectorName');
    if(empty(f.inspectorId)) add('פרטי מבצע הבדיקה — תעודת זהות', 'f3-inspector', 'fireForm3.inspectorId');
    if(empty(f.inspectorLicense)) add("פרטי מבצע הבדיקה — מס' רישיון", 'f3-inspector', 'fireForm3.inspectorLicense');
    if(empty(f.inspectorLicenseValidity)) add('פרטי מבצע הבדיקה — בתוקף עד ליום', 'f3-inspector', 'fireForm3.inspectorLicenseValidity');
    if(empty(f.inspectionDate)) add('תאריך ביצוע הבדיקה', 'f3-inspector', 'fireForm3.inspectionDate');
    if(empty(f.electricalSystemStatus)) add('סעיף 1 — מערכת החשמל ותאורת החירום (תקינים / לא תקינים)', 'f3-elec');
    if(empty(f.emergencyBreakerStatus)) add('סעיף 2 — מפסק חשמל חירום', 'f3-ups');
    if(empty(f.upsStatus)) add('סעיף 2 — מערכת UPS', 'f3-ups');
    if(!(f.panels || []).some(p => p.name || p.location)) add('סעיף 3 — פירוט לוחות החשמל', 'f3-panels');
    if(!state.settings.inspectorLicense) add('צילום רישיון בודק (הגדרות ← רישיון בודק)', 'f3-license');
    return out;
  }
  if(empty(state.meta.client)) add('המזמין', 'meta', 'meta.client');
  if(empty(state.meta.attentionTo)) add('לידי (איש קשר)', 'meta', 'meta.attentionTo');
  if(empty(state.meta.siteName)) add('שם המתקן / האתר', 'meta', 'meta.siteName');
  if(empty(state.meta.address)) add('כתובת המתקן', 'meta', 'meta.address');
  if(empty(state.meta.project)) add('פרויקט', 'meta', 'meta.project');
  if(empty(state.meta.date)) add('תאריך הבדיקה', 'meta', 'meta.date');
  if(empty(state.meta.description)) add('תיאור העבודה / המתקן', 'meta', 'meta.description');
  const instr = (state.meta.testInstrumentsSelected || []).filter(n => n !== 'אחר');
  if(!(state.meta.testInstrumentsSelected || []).length) add('מכשירי בדיקה — לא נבחר מכשיר', 'meta');
  instr.forEach(n => { const eq = findMatchingEquipment(n); if(!eq || empty(eq.serialNo) || empty(eq.calibrationDate)) add(`מכשיר "${n}" — חסר מס' סידורי / תוקף כיול (הגדרות ← מכשירי בדיקה)`, 'meta'); });
  if(t === 'GROUNDING' && !(state.groundingTest.locations || []).some(l => l.name && l.name.trim())) add('מיקום המדידה', 'ground-results');
  if(t === 'PV_INSPECTION'){
    const pv = getPvInspection();
    if(empty(pv.verdict)) add('הצהרת הבודק — מאושר / לא מאושר לחיבור', 'pv-verdict');
  }
  return out;
}
// חלון "חסרים פרטים בדוח": רשימה (לחיצה על פריט = מעבר אליו) + "בדוק סעיף חסר" / "הצג תצוגה מקדימה ללא שינוי"
function showMissingItemsModal(items){
  return new Promise(resolve => {
    let m = document.getElementById('missingItemsModal');
    if(!m){ m = document.createElement('div'); m.id = 'missingItemsModal'; m.className = 'preview-modal'; document.body.appendChild(m); }
    m.innerHTML = `<div class="preview-modal-inner form-type-modal-inner missing-modal" role="dialog" aria-modal="true" aria-labelledby="missingTitle" style="max-width:560px;">
      <div class="preview-modal-header"><h3 id="missingTitle">⚠️ חסרים פרטים בדוח (${items.length})</h3><button type="button" data-mclose="1" aria-label="סגור">✕</button></div>
      <div class="form-type-modal-body">
        <p style="margin:0 0 8px; font-size:14px;">הפרטים הבאים עדיין לא מולאו. לחיצה על פריט מעבירה אליו בטופס:</p>
        <div class="missing-list">${items.map((it, i) => `<button type="button" class="missing-item" data-mgo="${i}"><span class="missing-dot"></span>${escapeHtml(it.label)}</button>`).join('')}</div>
        <div class="missing-actions">
          <button type="button" class="add-btn missing-primary" data-mgo="0">🔍 בדוק סעיף חסר</button>
          <button type="button" class="add-btn" data-mcontinue="1">👁 הצג תצוגה מקדימה ללא שינוי</button>
        </div>
      </div></div>`;
    m.classList.add('show');
    const close = (v) => { m.classList.remove('show'); resolve(v); };
    m.onclick = (e) => {
      if(e.target === m || e.target.closest('[data-mclose]')) return close({ action: 'cancel' });
      if(e.target.closest('[data-mcontinue]')) return close({ action: 'preview' });
      const g = e.target.closest('[data-mgo]'); if(g) return close({ action: 'goto', item: items[parseInt(g.getAttribute('data-mgo'), 10)] });
    };
  });
}
function gotoMissingItem(it){
  if(!it) return;
  activeTab = 'inspection';
  if(it.card) openSections.add(it.card);
  render();
  setTimeout(() => {
    const field = it.path ? document.querySelector(`[data-textpath="${it.path}"]`) : null;
    const target = field || (it.card ? document.querySelector(`section.card[data-key="${it.card}"]`) : null);
    if(!target) return;
    target.scrollIntoView({ behavior: 'smooth', block: 'center' });
    const hl = field ? (field.closest('.field') || field) : target;
    hl.classList.add('missing-flash'); setTimeout(() => hl.classList.remove('missing-flash'), 2600);
    if(field && field.focus) setTimeout(() => { try{ field.focus({ preventScroll: true }); }catch(e){} }, 450);
  }, 80);
}
function validateAndPrepareForPdf(){
  const missing = validateRequiredInspectionFields();
  if(missing.length){
    activeTab = 'inspection';
    openSections.add('meta');
    if(missing.includes('מיקום המדידה')) openSections.add('ground-results');
    render();
    // גלילה לראש הטופס (שם נמצא סעיף "01" עם השדות החסרים) — כדי שההודעה לא תוחמץ
    // אם המשתמש היה גלול למטה בטופס ארוך, ומשך תצוגה ארוך יותר מהטוסט הרגיל.
    window.scrollTo({ top: 0, behavior: 'smooth' });
    const t = document.getElementById('toast');
    t.textContent = '⚠️ שדות חובה חסרים: ' + missing.join(', ');
    t.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>t.classList.remove('show'), 5000);
    return false;
  }
  return true;
}

async function triggerDirectPrint(excludeKeys){
  try{
    await ensureProjectExistsForCurrentClient();
    const reportHtml = buildPrintReport(excludeKeys || new Set());
    const footerHtml = buildFooterHtml();
    const filename = buildReportFilename();
    const standalone = buildStandaloneDoc(reportHtml, footerHtml, filename);
    const frame = document.getElementById('directPrintFrame');
    frame.onload = () => {
      try{
        frame.contentWindow.focus();
        frame.contentWindow.print();
      }catch(e){
        showToast('שגיאה בפתיחת חלון ההדפסה — נסה שוב');
      }
    };
    frame.srcdoc = standalone;
  }catch(e){
    showToast('שגיאה בהכנת הדוח להדפסה');
  }
}

document.getElementById('btnPdf').addEventListener('click', async ()=>{
  // v2.2.538 — אם חסרים פרטים: חלון עם הרשימה + "בדוק סעיף חסר" / "הצג תצוגה מקדימה ללא שינוי"
  const missingItems = collectMissingReportItems();
  if(missingItems.length){
    const r = await showMissingItemsModal(missingItems);
    if(r.action === 'goto'){ gotoMissingItem(r.item); return; }
    if(r.action !== 'preview') return;
  }
  const overlay = document.getElementById('pdfOverlay');
  overlay.classList.add('show');
  setTimeout(()=>{
    overlay.classList.remove('show');
    openPreviewModal();
  }, 100);
});

// מזהה גיבוי אחרון שנכשלה העלאתו ל-Fireberry — נשמר לצורך "נסה שוב" בלי ליצור גיבוי כפול
// (סעיף 8, מניעת כפילויות): אותו backupId/blob בדיוק נשלח שוב, לא backup חדש.
let pendingFireberryBackupRetry = null;

// בונה שם קובץ ברור לפי המפרט המבוקש: לקוח_מתקן_סוג-דוח_תאריך_שעה
function buildFireberryBackupFilename(){
  const client = (state.meta.client || 'ללא_לקוח').replace(/[^\p{L}\p{N}]+/gu, '_');
  const site = (state.meta.site || '').replace(/[^\p{L}\p{N}]+/gu, '_');
  const formType = (state.settings.formTypeName || 'דוח').replace(/[^\p{L}\p{N}]+/gu, '_');
  const now = new Date();
  const dateStr = now.toISOString().slice(0,10);
  const timeStr = String(now.getHours()).padStart(2,'0') + String(now.getMinutes()).padStart(2,'0');
  const parts = ['Shaked_Backup', client, site, formType, dateStr, timeStr].filter(Boolean);
  return parts.join('_') + '.json';
}

// מעלה גיבוי לכרטיס הלקוח ב-Fireberry — Reuse מלא של אותו דפוס קיים ומוכח (Browser ->
// Supabase Edge Function -> Fireberry, בדיוק כמו fireberry-get-related-contacts). ה-Fireberry
// API token עצמו נשאר Server Side בלבד בתוך ה-Edge Function — לעולם לא בדפדפן. משתמש
// ב-fireberryClientId הקיים על הדוח (לא חיפוש-שם מחדש). לא חוסם/מפיל את הגיבוי המקומי אם
// נכשל — הגיבוי המקומי כבר ירד בהצלחה לפני הקריאה הזו, ללא תלות בתוצאה כאן.
async function uploadBackupToFireberry(backup, filename, backupId){
  const accountId = await resolveFireberryClientId();
  if(!accountId){
    showToast('הגיבוי נשמר, אך לא הועלה ל-Fireberry — הדוח אינו מקושר ללקוח.');
    pendingFireberryBackupRetry = null;
    setExportBackupBtnRetryMode(false);
    return;
  }
  // *** v2.435 — Production Hardening: השרת אינו סומך על ה-accountId שהדפדפן שולח (זה היה
  // חור אבטחה פוטנציאלי — לקוח יכול לשלוח כל Account ID שרירותי). במקום זאת, השרת גוזר את
  // ה-Account ID *בעצמו* משרשרת בעלות מאומתת: reports.id (=cloudReportId, מאומת created_by
  // = המשתמש המחובר) -> reports.client_id -> clients.fireberry_client_id. בלי cloudReportId
  // (הדוח עדיין לא נשמר לענן ולו פעם אחת) אין שרשרת בעלות שהשרת יכול לאמת בכלל — מוצגת
  // הודעה ספציפית וברורה, לא כישלון גנרי, כי הגיבוי המקומי כבר הצליח בכל מקרה.
  if(!isCloudIdentityLocked()){
    showToast('הגיבוי נשמר מקומית. להעלאה ל-Fireberry יש לשמור את הדוח לענן פעם אחת קודם (Autosave עושה זאת אוטומטית תוך מספר שניות — נסה שוב מיד).', 4500);
    pendingFireberryBackupRetry = null;
    setExportBackupBtnRetryMode(false);
    return;
  }
  pendingFireberryBackupRetry = { backup, filename, backupId, accountId };
  try{
    const token = await getFireberrySessionToken();
    if(!token) throw new Error('אין session token');
    const fd = new FormData();
    fd.append('reportId', state.settings.cloudReportId); // המקור הסמכותי — השרת מאמת בעליו
    fd.append('accountId', accountId); // Hint לא-מחייב בלבד (לוגים/דיבוג), לא נסמך עליו לאבטחה
    fd.append('backupId', backupId);
    fd.append('filename', filename);
    fd.append('file', new Blob([JSON.stringify(backup, null, 2)], {type:'application/json'}), filename);
    const resp = await fetch(`${state.settings.supabaseUrl}/functions/v1/fireberry-upload-backup`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}` },
      body: fd
    });
    const body = await resp.json().catch(()=>({}));
    if(!resp.ok || body.error){
      throw new Error(body.error || `שגיאת שרת (${resp.status})`);
    }
    showToast('✅ הגיבוי נשמר וצורף לכרטיס הלקוח ב-Fireberry');
    pendingFireberryBackupRetry = null;
    setExportBackupBtnRetryMode(false);
  }catch(err){
    console.error('Fireberry backup upload failed:', err);
    // מציגים את ההודעה הספציפית שהשרת החזיר (err.message = body.error המדויק,
    // למשל "הדוח אינו מקושר ללקוח ולכן לא ניתן להעלות את הגיבוי ל-Fireberry")
    // ולא הודעה גנרית קבועה — כדי שהודעות ה-Fail-Closed הספציפיות שהוגדרו בצד
    // השרת (v2.436) אכן יגיעו למשתמש, לא רק יירשמו ב-console.
    const specificMsg = (err && err.message) ? `הגיבוי נשמר במערכת. Fireberry: ${err.message}` : 'הגיבוי נשמר במערכת, אך העלאה ל-Fireberry נכשלה.';
    showToast(specificMsg, 4000);
    setExportBackupBtnRetryMode(true);
  }
}

// אחרי כישלון — הופך את כפתור הגיבוי הקיים עצמו למצב "נסה שוב" זמנית, כדי לא להוסיף UI
// חדש (banner וכו') — אותו backupId/backup נשלחים שוב, לא גיבוי חדש (מניעת כפילויות).
function setExportBackupBtnRetryMode(on){
  const btn = document.getElementById('btnExportBackup');
  if(!btn) return;
  if(on){
    btn.textContent = '🔁 נסה שוב להעלות ל-Fireberry';
    btn.dataset.fireberryRetry = '1';
  } else {
    btn.textContent = '⬇️ ייצוא גיבוי';
    delete btn.dataset.fireberryRetry;
  }
}

document.getElementById('btnExportBackup').addEventListener('click', async ()=>{
  // מצב "נסה שוב" — רק מעלה מחדש ל-Fireberry את אותו גיבוי שכבר ירד בהצלחה, לא יוצר
  // גיבוי/הורדה כפולה (סעיף 8, מניעת כפילויות).
  if(document.getElementById('btnExportBackup').dataset.fireberryRetry === '1' && pendingFireberryBackupRetry){
    const { backup, filename, backupId } = pendingFireberryBackupRetry;
    await uploadBackupToFireberry(backup, filename, backupId);
    return;
  }
  try{
    const slots = {};
    for(const d of draftsIndex){
      try{
        const res = await storageAPI.get('draft-'+d.slot, false);
        if(res && res.value) slots[d.slot] = JSON.parse(res.value);
      }catch(e){ /* skip missing slot */ }
    }
    const backup = {
      version: 1,
      exportedAt: new Date().toISOString(),
      inspection: state,
      drafts: { index: draftsIndex, slots }
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], {type:'application/json'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const dateStr = new Date().toISOString().slice(0,10);
    a.download = `גיבוי_טיפול_מתח_גבוה_${dateStr}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 4000);
    showToast('קובץ הגיבוי ירד — שמור אותו בעצמך במקום שתבחר');
    // *** חדש: אם הדוח מקושר ללקוח Fireberry (fireberryClientId), מעלה את אותו קובץ גיבוי
    // גם לכרטיס הלקוח שם — רק בפעולת גיבוי מפורשת זו, לא ב-autosave (סעיף 5, מפורש).
    // הגיבוי המקומי כבר הצליח למעלה, בלי תלות בתוצאת ההעלאה ל-Fireberry (סעיף 7).
    const backupId = 'bkp_' + Date.now().toString(36) + Math.random().toString(36).slice(2,8);
    const fbFilename = buildFireberryBackupFilename();
    uploadBackupToFireberry(backup, fbFilename, backupId);
  }catch(err){
    console.error(err);
    showToast('שגיאה בייצוא הגיבוי');
  }
});

document.getElementById('importBackupInput').addEventListener('change', async (e)=>{
  const input = e.target;
  const file = input.files && input.files[0];
  if(!file) return;
  try{
    const text = await file.text();
    const backup = JSON.parse(text);
    if(!backup || !backup.inspection){ throw new Error('invalid backup file'); }

    if(!confirm('לייבא את הגיבוי? זה יחליף את הבדיקה הנוכחית ואת כל הטיוטות השמורות.')){
      input.value = '';
      return;
    }

    state = mergeDefaults(newState(), backup.inspection);
    draftsIndex = (backup.drafts && backup.drafts.index) || [];
    await storageAPI.set('inspection-current', JSON.stringify(sanitizeStateForLocalSave(state)), false);
    await storageAPI.set('drafts-index', JSON.stringify(draftsIndex), false);
    if(backup.drafts && backup.drafts.slots){
      for(const slot of Object.keys(backup.drafts.slots)){
        await storageAPI.set('draft-'+slot, JSON.stringify(backup.drafts.slots[slot]), false);
      }
    }
    // שחזור רשימות ציוד/לקוחות אם קיימות בקובץ הגיבוי — מתמזג לתוך הרשימה הקיימת
    // לפי id (לא דורס פריטים קיימים עם אותו id, ומוסיף פריטים חדשים בלבד).
    if(Array.isArray(backup.equipmentList)){
      const existingIds = new Set(equipmentList.map(e=>e.id));
      backup.equipmentList.forEach(eq=>{ if(eq && eq.id && !existingIds.has(eq.id)) equipmentList.push(eq); });
      await storageAPI.set('equipment-list', JSON.stringify(equipmentList), false);
    }
    if(Array.isArray(backup.clientsList)){
      const existingClientIds = new Set(clientsList.map(c=>c.id));
      backup.clientsList.forEach(c=>{ if(c && c.id && !existingClientIds.has(c.id)) clientsList.push(c); });
      await storageAPI.set('clients-list', JSON.stringify(clientsList), false);
    }
    activeTab = 'inspection';
    render();
    showToast('הגיבוי יובא בהצלחה');
  }catch(err){
    console.error(err);
    showToast('שגיאה בייבוא הגיבוי — ודא שזה קובץ גיבוי תקין');
  }
  input.value = '';
});

// טבלת Checklist קומפקטית משותפת — 2 פריטים בכל שורה (ימין ואז שמאל, RTL, לא הפוך) — לפי
// מפרט מאושר, ליישום גלובלי בכל סוגי הדוח (לא נקודתי). מרחיבה את printEvcsChecklistTable2Col
// שכבר הוכיחה את הרעיון (הערה בקוד: "לעת עתה, עד שיאושר ונרחיב לשאר הדוחות" — זה הרחבה הזו).
// חשוב: מקבלת labelHtml/resultHtml *מוכנים מראש* מהקורא, לא בונה לוגיקת סטטוס/צבע בעצמה —
// כך משתמרת 100% הלוגיקה הקיימת בכל טבלה (סוגי סטטוס/צבעים שונים: ok/bad/na עם statusLabel(),
// V/X/N/A עם MAIN_PANEL_STATUS_LABELS, טקסט חופשי וכו') בלי לשכפל/לסכן אותה, לפי דרישה
// מפורשת "אל תשנה את הנתונים עצמם, רק את אופן הצגתם".
// rows: מערך של {labelHtml, resultHtml, fullWidth (אופציונלי, ברירת מחדל false)}.
function buildCompactChecklistTable(rows, options = {}){
  const { itemTitle = 'פירוט הבדיקה', resultTitle = 'תוצאה', title = null, className = '' } = options;
  if(!rows || !rows.length) return '';

  const bodyParts = [];
  let i = 0;
  while(i < rows.length){
    const right = rows[i];
    if(right.fullWidth){
      bodyParts.push(`<tr class="compact-check-row compact-check-full-row">
        <td class="compact-check-item" colspan="3">${right.labelHtml}</td>
        <td class="compact-check-result">${right.resultHtml}</td>
      </tr>`);
      i += 1;
      continue;
    }
    // פריט אי-זוגי אחרון, או שהפריט הבא דורש שורה מלאה משלו — לא מצמידים אליו פריט שני,
    // הוא נשאר בצד ימין בלבד (לפי דרישה מפורשת: לא למתוח, לא להעביר שמאלה).
    const next = rows[i+1];
    const left = (next && !next.fullWidth) ? next : null;
    bodyParts.push(`<tr class="compact-check-row">
      <td class="compact-check-item">${right.labelHtml}</td>
      <td class="compact-check-result">${right.resultHtml}</td>
      <td class="compact-check-item">${left ? left.labelHtml : ''}</td>
      <td class="compact-check-result">${left ? left.resultHtml : ''}</td>
    </tr>`);
    i += left ? 2 : 1;
  }

  const titleRow = title ? `<tr style="break-inside:avoid; page-break-inside:avoid;"><td colspan="4" style="background:#eef0f2; border:1px solid #999; font-weight:700; text-align:center; padding:8px 10px; font-size:13px;">${escapeHtml(title)}</td></tr>` : '';

  return `<table class="compact-checklist-table ${className}" dir="rtl">
    <thead>
      ${titleRow}
      <tr><th class="compact-check-item">${escapeHtml(itemTitle)}</th><th class="compact-check-result">${escapeHtml(resultTitle)}</th><th class="compact-check-item">${escapeHtml(itemTitle)}</th><th class="compact-check-result">${escapeHtml(resultTitle)}</th></tr>
    </thead>
    <tbody>${bodyParts.join('')}</tbody>
  </table>`;
}
// פריט/הערה ארוכים מדי לחצי-שורה — מקבל שורה מלאה במקום להיות מוצמד לפריט נוסף, לפי דרישה
// מפורשת. הסף (70/100 תווים) נבדק על טקסט גולמי (labelText/noteText), לא HTML.
function shouldUseFullWidthChecklistItem(labelText, noteText){
  return (labelText && labelText.length > 70) || (noteText && noteText.length > 100);
}

function statusLabel(v){
  if(v==='ok') return '<span class="status-ok">✓ תקין</span>';
  if(v==='bad') return '<span class="status-bad">✕ לא תקין</span>';
  return '<span class="status-na">— לא רלוונטי</span>';
}

function withHeading(tag, title, bodyHtml){
  return bodyHtml ? `<${tag}>${title}</${tag}>${bodyHtml}` : '';
}

// טבלה קומפקטית — אותם [label, value] pairs כמו tinfo-table הרגילה, אבל שני זוגות בכל שורה
// במקום זוג אחד (חוצה בערך את הגובה) — לפי בקשה מפורשת לצמצום עמודים, במקומות עם הרבה שדות
// קצרים ברצף. אם מספר הזוגות אי-זוגי, התא האחרון בשורה האחרונה פשוט נשאר ריק.
// title אופציונלי — אם מסופק, מוצג כשורה ראשונה בתוך אותה טבלה ממש (colspan=4), לא כ-<p>
// נפרד לפניה. אומת ישירות שזו התבנית האמינה היחידה שמונעת באג אמיתי בפיצול עמודים: כותרת+טבלה
// נפרדות (גם עם break-inside:avoid משותף על div עוטף) איבדו סנכרון והובילו לאובדן שורות נתונים
// בגלישה בין עמודים — כותרת כשורה בתוך אותה טבלה ממש נשארת מסונכרנת תמיד.
// טבלת תא (v2.2.546): שתי עמודות — כותרת | ערך — כדי שבפריסת שני תאים זה לצד זה שום תווית/ערך לא יידחס וישבר לשורות
function printCellTable(rows, title){
  if(!rows.length) return '';
  const H = reportHeadingColors();
  let html = `<table class="tinfo-table cell-2col" style="break-inside:avoid; page-break-inside:avoid; table-layout:fixed; width:100%; margin-bottom:6px;">`;
  if(title) html += `<tr><td colspan="2" style="background:${H.bg}; color:${H.text}; border:1px solid #bbb; border-bottom:2px solid ${H.accent}; font-weight:800; text-align:center; padding:7px 10px; font-size:12.5px; -webkit-print-color-adjust:exact; print-color-adjust:exact;">${escapeHtml(title)}</td></tr>`;
  rows.forEach(([l, v]) => { html += `<tr><td class="tinfo-label" style="width:42%;">${escapeHtml(l)}</td><td style="overflow-wrap:anywhere;">${escapeHtml(String(v))}</td></tr>`; });
  return html + `</table>`;
}
function printCompact2ColTable(rows, title){
  if(!rows.length) return '';
  let html = `<table class="tinfo-table-2col" style="break-inside:avoid; page-break-inside:avoid;">`;
  if(title) html += `<tr><td colspan="4" style="background:${reportHeadingColors().bg}; color:${reportHeadingColors().text}; border:1px solid #bbb; border-bottom:2px solid ${reportHeadingColors().accent}; font-weight:800; text-align:center; padding:8px 10px; font-size:13px; -webkit-print-color-adjust:exact; print-color-adjust:exact;">${escapeHtml(title)}</td></tr>`;
  for(let i=0; i<rows.length; i+=2){
    const [l1,v1] = rows[i];
    const pair2 = rows[i+1];
    html += `<tr><td class="tinfo-label">${escapeHtml(l1)}</td><td class="tinfo-value">${escapeHtml(String(v1))}</td>`;
    html += pair2
      ? `<td class="tinfo-label">${escapeHtml(pair2[0])}</td><td class="tinfo-value">${escapeHtml(String(pair2[1]))}</td></tr>`
      : `<td class="tinfo-label"></td><td class="tinfo-value"></td></tr>`;
  }
  html += `</table>`;
  return html;
}

function printItemsTable(items, map, path){
  const rows = items.map((label,i)=>{
    const note = path ? state.itemNotes[`${path}|${i}`] : null;
    if(!map[i] && !note) return null;
    const noteHtml = note ? `<div class="compact-check-note">📝 ${escapeHtml(note)}</div>` : '';
    return {
      labelHtml: `${escapeHtml(label)}${noteHtml}`,
      resultHtml: statusLabel(map[i]),
      fullWidth: shouldUseFullWidthChecklistItem(label, note)
    };
  }).filter(Boolean);
  return buildCompactChecklistTable(rows, { itemTitle:'פירוט הבדיקה', resultTitle:'תוצאה' });
}

// טבלת בדיקה ויזואלית — מסדר (דוח לוח מתח גבוה בלבד) — סגנון תואם לטבלת "בדיקות ויזואליות לוח
// מ"ג" (טקסט סטטוס פשוט, בלי אייקוני ✓/✕), לפי בקשה מפורשת: "הטבלה השנייה נראית יותר טוב".
// פונקציה נפרדת מ-printItemsTable() הכללית בכוונה — זו משמשת גם דוחות אחרים (SMA וכו') שלא
// התבקש לשנות אותם, אז לא נוגעים בה.
function printMainSwitchgearChecklistTable(items, map, title){
  const STATUS_TEXT = { ok: 'תקין', bad: 'לא תקין', na: 'לא רלוונטי' };
  const rows = items.map((label,i)=> map[i] ? { labelHtml: escapeHtml(label), resultHtml: escapeHtml(STATUS_TEXT[map[i]]||map[i]), fullWidth: shouldUseFullWidthChecklistItem(label) } : null).filter(Boolean);
  return buildCompactChecklistTable(rows, { itemTitle:'תיאור הבדיקה', resultTitle:'סטטוס', title });
}

function printInsulationTable(data, title, rowLabels){
  const labels = rowLabels || INSULATION_ROWS;
  const rowsData = (data && data.rows) || [];
  const method = (data && data.testMethod) || 'dar';
  const isPI = method === 'pi';
  const isSpot = method === 'spot';
  const label1 = isSpot ? 'ערך נמדד' : (isPI ? 'R (1 דקה)' : 'R (15 שנ\')');
  const label2 = isSpot ? 'טמפרטורה' : (isPI ? 'R (10 דקות)' : 'R (60 שנ\')');
  const ratioLabel = isSpot ? `מתוקן ל-${INSULATION_REFERENCE_TEMP_C}°C` : (isPI ? 'PI' : 'DAR');
  const colors = { 'ins-good':'#3fa34d', 'ins-questionable':'#d4a63c', 'ins-bad':'#c43c3c' };
  const rows = labels.map((label,i)=>{
    const d = rowsData[i];
    if(!d || (!d.r15 && !d.r60 && !d.note && !d.manualClassification)) return '';
    const unit = d.unit || 'MΩ';
    let col2Text, col3Text, resultText;
    if(isSpot){
      col2Text = d.r15 ? `<span dir="ltr">${escapeHtml(d.r15)} ${unit}</span>` : '—';
      col3Text = d.temp ? `<span dir="ltr">${escapeHtml(d.temp)}°C</span>` : '—';
      const measured = parseFloat(d.r15), temp = parseFloat(d.temp);
      const corrected = correctInsulationForTemperature(measured, temp);
      resultText = corrected !== null ? `<span dir="ltr">${corrected.toFixed(2)} ${unit}</span>` : '—';
    } else {
      col2Text = d.r15 ? `<span dir="ltr">${escapeHtml(d.r15)} ${unit}</span>` : '—';
      col3Text = d.r60 ? `<span dir="ltr">${escapeHtml(d.r60)} ${unit}</span>` : '—';
      const v1 = parseFloat(d.r15), v2 = parseFloat(d.r60);
      const ratio = (!isNaN(v1) && !isNaN(v2) && v1 > 0) ? (v2/v1) : null;
      resultText = ratio !== null ? ratio.toFixed(2) : '—';
      const classification = ratio !== null ? classifyInsulationRatio(method, ratio) : null;
      if(classification) resultText = `<b style="color:${colors[classification.cls]};">${classification.label}</b> (${resultText})`;
    }
    const noteText = [d.manualClassification ? `<b>${escapeHtml(d.manualClassification)}</b>` : '', escapeHtml(d.note) || ''].filter(Boolean).join(' — ');
    return `<tr><td>${label}</td><td>${col2Text}</td><td>${col3Text}</td><td>${resultText}</td><td>${noteText}</td></tr>`;
  }).filter(Boolean).join('');
  if(!rows) return '';
  // title אופציונלי — כשמסופק, מוצג כשורה בתוך ה-thead עצמו (לא <h2> נפרד לפניו), אותה תבנית
  // בטוחה שכבר הוכחה עובדת בשאר טבלאות הדוח. שאר 3 אתרי הקריאה (SMA/שנאי עצמאי) לא מושפעים —
  // לא מעבירים title בכלל, ממשיכים לעבוד בדיוק כמו קודם.
  const titleRow = title ? `<tr style="break-inside:avoid; page-break-inside:avoid;"><td colspan="5" style="background:#eef0f2; border:1px solid #999; font-weight:700; text-align:center; padding:8px 10px; font-size:13px;">${escapeHtml(title)}</td></tr>` : '';
  return `<table><thead>${titleRow}<tr><th></th><th>${label1}</th><th>${label2}</th><th>${ratioLabel}</th><th>סיווג / הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
}

function printDccbTable(dccbData){
  const rows = (dccbData||[]).map(d=>{
    if(!d || (!d.torque && !d.cleaning)) return '';
    const label = d.name || 'כבל';
    return `<tr><td>${escapeHtml(label)}</td><td>${statusLabel(d.torque)}</td><td>${statusLabel(d.cleaning)}</td></tr>`;
  }).filter(Boolean).join('');
  if(!rows) return '';
  return `<table><thead><tr><th>כבל</th><th>חיזוק מומנט</th><th>ניקיון</th></tr></thead><tbody>${rows}</tbody></table>`;
}

function printDpsTable(dpsData){
  const rows = (dpsData||[]).map(d=>{
    if(!d || (!d.torque && !d.cleaning && !d.filterReplace && !d.notes)) return '';
    const wires = (d.wiresPlus || d.wiresMinus) ? `<span dir="ltr">${escapeHtml(d.wiresPlus)||'-'} / ${escapeHtml(d.wiresMinus)||'-'}</span>` : '—';
    return `<tr><td>${escapeHtml(d.name)||'—'}</td><td>${wires}</td><td>${statusLabel(d.torque)}</td><td>${statusLabel(d.cleaning)}</td><td>${statusLabel(d.filterReplace)}</td><td>${escapeHtml(d.notes)||''}</td></tr>`;
  }).filter(Boolean).join('');
  if(!rows) return '';
  return `<table><thead><tr><th>DPS</th><th>גידים (+/-)</th><th>חיזוק מומנט</th><th>ניקיון</th><th>החלפת פילטרים</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
}

function printHouseTransformer(data){
  const rows = [];
  // "פרטי שנאי בית" — בלוק חדש בראש ההדפסה, לפי בקשה מפורשת ("שם שנאי: TR1" וכו').
  // כל שורה מוצגת רק אם יש בה ערך בפועל — "אם שדה ריק — לא להציג שורה ריקה ב-PDF".
  const infoLines = [];
  if(data.name) infoLines.push(['שם שנאי', data.name]);
  if(data.serialNumber) infoLines.push(['מספר סידורי', data.serialNumber]);
  if(data.ratedPower) infoLines.push(['הספק', formatMeasurement(data.ratedPower, data.powerUnit)]);
  if(data.primaryVoltage) infoLines.push(['מתח ראשוני', formatMeasurement(data.primaryVoltage, data.primaryVoltageUnit)]);
  if(data.primaryCurrent) infoLines.push(['זרם ראשוני', `${data.primaryCurrent} A`]);
  if(data.secondaryVoltage) infoLines.push(['מתח משני', formatMeasurement(data.secondaryVoltage, data.secondaryVoltageUnit)]);
  if(data.secondaryCurrent) infoLines.push(['זרם משני', `${data.secondaryCurrent} A`]);
  if(data.vectorGroup) infoLines.push(['קבוצת חיבורים', data.vectorGroup]);
  if(data.coolingType) infoLines.push(['קירור', data.coolingType]);
  const infoHtml = infoLines.length
    ? `<table class="tinfo-table">${infoLines.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`
    : '';
  // בונה את תיאור הכבל: "סוג כבל – Nxסימון mm²" מהשדות המובנים (סעיף 8: "כבל: N2XY – 4x35
  // mm²"); אם אין נתונים מובנים כלל אבל יש primarySpec/secondarySpec ישן (טקסט חופשי מדוח
  // קודם) — מוצג כפי שהיה, לא נמחק/מוסתר (תאימות לאחור).
  function cableDesc(prefix){
    const cfg = formatCableConfig(data[prefix+'CoreCount'], data[prefix+'CoreSection'], data[prefix+'AdditionalCoreSection'], data[prefix+'ParallelRuns']);
    const cableType = data[prefix+'CableType'];
    if(cfg) return cableType ? `${cableType} – ${cfg}` : cfg;
    return data[prefix+'Spec'] || '';
  }
  const primaryDesc = cableDesc('primary');
  const secondaryDesc = cableDesc('secondary');
  if(primaryDesc || data.primaryTorque || data.primaryCleaning || data.primaryNotes){
    rows.push(`<tr><td>צד ראשוני</td><td>${escapeHtml(primaryDesc)||'—'}</td><td>${statusLabel(data.primaryTorque)}</td><td>${statusLabel(data.primaryCleaning)}</td><td>${escapeHtml(data.primaryNotes)||''}</td></tr>`);
  }
  if(secondaryDesc || data.secondaryTorque || data.secondaryCleaning || data.secondaryNotes){
    rows.push(`<tr><td>צד משני</td><td>${escapeHtml(secondaryDesc)||'—'}</td><td>${statusLabel(data.secondaryTorque)}</td><td>${statusLabel(data.secondaryCleaning)}</td><td>${escapeHtml(data.secondaryNotes)||''}</td></tr>`);
  }
  const cableHtml = rows.length ? `<table><thead><tr><th>צד</th><th>כבל</th><th>חיזוק מומנט</th><th>ניקיון</th><th>הערות</th></tr></thead><tbody>${rows.join('')}</tbody></table>` : '';
  if(!infoHtml && !cableHtml) return '';
  return infoHtml + cableHtml;
}

function printAuxFeed(data){
  if(!data.spec && !data.torque && !data.cleaning && !data.notes) return '';
  return `<table><thead><tr><th>חתך כבל</th><th>חיזוק מומנט</th><th>ניקיון</th><th>הערות</th></tr></thead>
    <tbody><tr><td>${escapeHtml(data.spec)||'—'}</td><td>${statusLabel(data.torque)}</td><td>${statusLabel(data.cleaning)}</td><td>${escapeHtml(data.notes)||''}</td></tr></tbody></table>`;
}

function printStorageContainers(containers){
  const rows = (containers||[]).map(c=>{
    // תוקן — c.name הוסר מהתנאי: ערך ברירת המחדל הראשוני (storageContainers[0] מקבל שם
    // "GOTION1" אוטומטית, לא רק תווית placeholder) לא יעיד על מידע שהוזן בפועל, לפי בקשה
    // מפורשת. עקבי עכשיו עם printDccbTable/printDpsTable/printHouseTransformer/printAuxFeed
    // שכבר לא סמכו על name לבדו — רק שדות בדיקה בפועל (torque/cleaning/notes) קובעים אם
    // השורה "אמיתית".
    if(!c.torque && !c.cleaning && !c.notes) return '';
    const wires = (c.wiresPlus || c.wiresMinus) ? `<span dir="ltr">${escapeHtml(c.wiresPlus)||'-'} / ${escapeHtml(c.wiresMinus)||'-'}</span>` : '—';
    return `<tr><td>${escapeHtml(c.name)||'—'}</td><td>${wires}</td><td>${statusLabel(c.torque)}</td><td>${statusLabel(c.cleaning)}</td><td>${escapeHtml(c.notes)||''}</td></tr>`;
  }).filter(Boolean).join('');
  if(!rows) return '';
  return `<table><thead><tr><th>מכולה</th><th>גידים (+/-)</th><th>חיזוק מומנט</th><th>ניקיון</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
}

// המודל המאוחד להערות הדוח — לפי מפרט מאושר: לא נוגע ב-state.notes (נשאר להערות ידניות
// בלבד), לא מעתיק פיזית הערות מתמונות לשום מקום. בונה בכל render/print מחדש רשימה מאוחדת:
// (1) הערות ידניות מ-state.notes[] קודם, (2) אחר כך תמונות מ-generalPhotos[] מקובצות לפי
// title זהה (לא כותרת כפולה לכל תמונה בנפרד) — כל תמונה/קבוצת-תמונות עם אותה כותרת הופכת
// לסעיף ראשי אחד, וכל איבר ב-notes[] שלה (מסונן לריקים) הופך לתת-סעיף ממוספר. המספור
// (number/subNumber) מחושב כאן בלבד, בכל קריאה מחדש — לא נשמר ב-state בשום מקום, כך
// שהוספה/מחיקה/שינוי סדר תמיד מניבים מספור רציף נכון, בלי "חורים" ובלי לוגיקת עדכון נפרדת.
// Source of Truth נשאר generalPhotos[i].notes[] — עריכה/מחיקה שם משתקפת כאן אוטומטית
// בקריאה הבאה, בלי מנגנון סנכרון/מניעת-כפילות נפרד.
function buildReportNotesModel(){
  const items = [];

  (state.notes || []).forEach((text, i) => {
    if(text && text.trim()){
      items.push({ text: text.trim(), source: 'manual', manualIndex: i, subItems: [] });
    }
  });

  const photoGroups = []; // [{ title, subItems: [{text, photoId, noteIndex}] }] — סדר לפי סדר התמונות הראשון עם כל כותרת
  (state.generalPhotos || []).forEach(p => {
    const validNotes = (p.notes || [])
      .map((n, ni) => ({ text: (n||'').trim(), photoId: p.id, noteIndex: ni }))
      .filter(n => n.text);
    if(!validNotes.length) return;
    const title = (p.title && p.title.trim()) || '(תמונה ללא כותרת)';
    let group = photoGroups.find(g => g.title === title);
    if(!group){ group = { title, subItems: [] }; photoGroups.push(group); }
    group.subItems.push(...validNotes);
  });
  photoGroups.forEach(g => {
    items.push({ text: g.title, source: 'photo-title', subItems: g.subItems });
  });

  items.forEach((item, i) => {
    item.number = i + 1;
    item.subItems.forEach((sub, si) => { sub.number = `${item.number}.${si+1}`; });
  });
  return items;
}

function printPhotos(photos, startNum){
  if(!photos || !photos.length) return '';
  const base = startNum || 1;
  const boxes = photos.map((p,i)=>{
    const num = base + i;
    const isSolo = photos.length === 1 || ((photos.length % 2 === 1) && (i === photos.length - 1));
    const title = p.title ? `תמונה ${num} - ${escapeHtml(p.title)}` : `תמונה ${num}`;
    // תוקן — p.note (יחיד) לא היה קיים בכלל באובייקט; השדה האמיתי הוא p.notes[] (מערך,
    // כמה הערות נפרדות לכל תמונה). באג זה גרם להערות תמונה לא להופיע בהדפסה בכלל, גם לפני
    // התכונה הנוכחית. מציג את כל ההערות לפי הסדר, ממוספרות ${num}.1/${num}.2/וכו'.
    const lines = (p.notes || []).map(n=>(n||'').trim()).filter(Boolean);
    const notesHtml = lines.map((l,li)=>`<div class="photo-note">${num}.${li+1}. ${escapeHtml(l)}</div>`).join('');
    return `<div class="photo-box${isSolo ? ' solo' : ''}">
      <img src="${resolvePhotoSrc(p)}" data-cloudpath="${escapeAttr(p.cloudPath||'')}" alt="">
      <div class="photo-caption">${title}</div>
      ${notesHtml}
    </div>`;
  }).join('');
  return `<div class="photo-report-grid">${boxes}</div>`;
}

// מחלץ טקסט גולמי מקובץ PDF או DOCX שהמשתמש העלה, לצורך שליחה ל-AI לפענוח.
// PDF: pdf.js (עמוד-עמוד). DOCX: mammoth.js (ממיר ל-HTML/טקסט, קורא ישירות מ-ArrayBuffer).
function fileToBase64(file){
  return new Promise((resolve, reject)=>{
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result.split(',')[1]); // strip the "data:...;base64," prefix
    reader.onerror = () => reject(new Error('שגיאה בקריאת הקובץ'));
    reader.readAsDataURL(file);
  });
}

// DOCX בלבד: מחלץ טקסט גולמי (mammoth.js) — DOCX הוא פורמט טקסט/XML, לא מסמך חזותי,
// אז חילוץ טקסט הוא הדרך הנכונה עבורו (לא נשלח כתמונה/מסמך).
async function extractTextFromDocx(file){
  if(typeof mammoth === 'undefined') throw new Error('ספריית קריאת Word לא נטענה — בדוק חיבור אינטרנט ונסה שוב');
  const buffer = await file.arrayBuffer();
  const result = await mammoth.extractRawText({ arrayBuffer: buffer });
  return result.value;
}

const FAT_JSON_SCHEMA_INSTRUCTIONS = `החזר **רק** אובייקט JSON תקין, בלי שום טקסט נוסף לפניו או אחריו, בלי \`\`\`.

חשוב מאוד: אם ערך מסוים לא נמצא במסמך בבירור, השאר אותו כמחרוזת ריקה "" — לעולם אל תמציא/תשלים ערך שלא נמצא במקור. זהו מסמך הנדסי, דיוק קריטי.

מבנה ה-JSON הנדרש (בדיוק כך, כולל שמות השדות):
{
  "productType": "", "serialNo": "", "drawingNo": "",
  "powerRating": "", "coolingType": "", "ratedVoltage": "", "numberOfPhases": "",
  "ratedCurrent": "", "ratedFrequency": "", "vectorGroup": "", "pei": "", "bilHV": "", "bilLV": "",
  "factory": {
    "temp": "", "humidity": "", "hvUnit": "Ω", "lvUnit": "Ω",
    "hv": [ {"tap":1,"ab":"","bc":"","ca":""}, {"tap":2,"ab":"","bc":"","ca":""}, {"tap":3,"ab":"","bc":"","ca":""}, {"tap":4,"ab":"","bc":"","ca":""}, {"tap":5,"ab":"","bc":"","ca":""} ],
    "lv": {"ab":"","bc":"","ca":""}
  },
  "insulationFactory": {
    "testVoltage": "", "topOilTemp": "", "humidity": "",
    "rows": [ {"r15":"","r60":""}, {"r15":"","r60":""}, {"r15":"","r60":""} ]
  }
}

הערות לזיהוי נכון:
- "hvUnit"/"lvUnit": אם הערכים בטבלת ה-HV/LV קטנים מאוד (למשל 0.0004...), ציין "μΩ" והמר את הערכים המספריים בהתאם (0.0004371 → "437.1"); אם רגילים (כמו 1.5), השאר "Ω" והערך כפי שהוא.
- "insulationFactory.rows": 3 שורות בסדר הזה בדיוק — [0]=H.V↔L.V&Earth, [1]=L.V↔H.V&Earth, [2]=H.V,L.V↔Earth.
- "numberOfPhases": מספר בלבד (למשל "3"), לא "3 Phases".
- אם יש כמה tap positions בטבלת ההתנגדות אבל פחות מ-5, מלא רק את מה שקיים והשאר את שאר המערך עם ערכים ריקים באותו tap number הבא ברצף.
- המסמך עשוי להיות סרוק (תמונה) ולא טקסט דיגיטלי — קרא אותו חזותית כמו שתקרא כל מסמך/טבלה סרוקים.`;

// מריץ את כל הצינור: קובץ → (PDF: נשלח כמסמך ישירות; DOCX: טקסט מחולץ) → AI → JSON מפוענח.
// לא נוגע ב-state כלל — הקורא (ה-handler) מציג את התוצאה למשתמש לאישור לפני שמשהו נכנס בפועל לדוח.
async function parseFatReportWithAi(file){
  const name = (file.name || '').toLowerCase();
  let aiResponse;

  if(name.endsWith('.pdf')){
    // שולחים את ה-PDF כמסמך ישירות ל-Claude — עובד גם למסמכים דיגיטליים וגם לסריקות/תמונות,
    // כי Claude קורא אותו חזותית, לא דרך שכבת טקסט שאולי לא קיימת בכלל (כמו בסריקה ממכונת צילום).
    const base64 = await fileToBase64(file);
    const contentBlocks = [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } },
      { type: 'text', text: `להלן תעודת בדיקת יצור (FAT / Factory Test Report) של שנאי כוח, כקובץ PDF מצורף (ייתכן שזהו מסמך סרוק). קרא אותו וחלץ ממנו את הנתונים.\n\n${FAT_JSON_SCHEMA_INSTRUCTIONS}` }
    ];
    aiResponse = await callClaudeApi(null, 4000, contentBlocks);
  } else if(name.endsWith('.docx')){
    const rawText = await extractTextFromDocx(file);
    if(!rawText || rawText.trim().length < 30){
      throw new Error('לא הצלחתי לחלץ טקסט קריא מקובץ ה-Word — ייתכן שהוא כמעט ריק');
    }
    const prompt = `להלן טקסט שחולץ מתעודת בדיקת יצור (FAT / Factory Test Report) של שנאי כוח. חלץ ממנו את הנתונים.\n\n${FAT_JSON_SCHEMA_INSTRUCTIONS}\n\nהטקסט שחולץ מהמסמך:\n"""\n${rawText.slice(0, 15000)}\n"""`;
    aiResponse = await callClaudeApi(prompt, 2500);
  } else {
    throw new Error('סוג קובץ לא נתמך — יש להעלות PDF או DOCX בלבד');
  }

  const parsed = extractJsonFromAiResponse(aiResponse);
  return parsed;
}

// מנתח את תשובת ה-AI בצורה עמידה — למרות ההנחיה המפורשת "רק JSON", מודלי שפה
// לעיתים מוסיפים הקדמה/הסבר סביב ה-JSON (בעיקר במסמכים מורכבים/סרוקים שקשה לקרוא).
// מנסה קודם פענוח ישיר, ואם נכשל — מחפש את הבלוק שבין ה-{ הראשון ל-} האחרון בתשובה.
function extractJsonFromAiResponse(aiResponse){
  try{
    return JSON.parse(aiResponse);
  }catch(e){ /* ננסה חילוץ */ }

  const firstBrace = aiResponse.indexOf('{');
  const lastBrace = aiResponse.lastIndexOf('}');
  if(firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace){
    const candidate = aiResponse.slice(firstBrace, lastBrace + 1);
    try{
      return JSON.parse(candidate);
    }catch(e){ /* עדיין נכשל, נופלים לשגיאה עם התשובה הגולמית לאבחון */ }
  }

  const preview = aiResponse.length > 400 ? aiResponse.slice(0, 400) + '…' : aiResponse;
  throw new Error(`תשובת ה-AI לא הייתה JSON תקין. תחילת התשובה שהתקבלה בפועל (לאבחון): "${preview}"`);
}

// prompt: מחרוזת רגילה, כמו עד כה. contentBlocks (אופציונלי): אם סופק, נשלח כתוכן ההודעה
// במקום prompt כמחרוזת — משמש לצירוף מסמך (PDF) + טקסט יחד, ל-Claude vision/document understanding.
// כל שאר הקוראים הקיימים לפונקציה הזו לא מושפעים כלל — חוזה הפלט (מחרוזת טקסט) נשאר זהה.
//
// *** תיקון אבטחה (Audit + יישום): לא עוד state.settings.anthropicApiKey ולא עוד fetch
// ישיר מהדפדפן ל-api.anthropic.com עם Key גולמי ב-header (anthropic-dangerous-direct-
// browser-access הוסר לחלוטין). הקריאה עוברת דרך ai-proxy-call — Edge Function מאומתת
// (JWT), שמאתרת את ה-Key של המשתמש המחובר ב-Vault *בצד שרת בלבד* ומחזירה רק את התוצאה.
// ה-Key לעולם לא מגיע/חוזר לדפדפן, לא ב-header, לא בתשובה, לא ב-state, לא ב-log.
async function callClaudeApi(prompt, maxTokens, contentBlocks){
  // fallback ל"רץ בתוך Claude.ai כארטיפקט חי": ללא Key כלל, ללא secret של אף משתמש —
  // לא קשור לדאגת האבטחה (אין כאן שום דבר שדולף), רלוונטי רק לתצוגה מקדימה/פיתוח, לא
  // לאפליקציה הפרוסה ב-Vercel שמשתמשים אמיתיים נכנסים אליה.
  if(!supabaseClient || !cloudCurrentUser){
    let response;
    try{
      response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: maxTokens, messages: [{ role: "user", content: contentBlocks || prompt }] })
      });
    }catch(networkErr){
      throw new Error('לא ניתן להתחבר לשירות ה-AI. יש להתחבר לחשבון ולהגדיר מפתח API בהגדרות AI כדי שבדיקת הכתיב תעבוד.');
    }
    if(!response.ok) throw new Error('קריאה ל-AI נכשלה (סטטוס ' + response.status + ')');
    const data = await response.json();
    const text = (data.content || []).map(c => c.text || '').join('');
    return text.replace(/```json|```/g, '').trim();
  }

  const { data: sessionData } = await supabaseClient.auth.getSession();
  const accessToken = sessionData && sessionData.session && sessionData.session.access_token;
  if(!accessToken){
    throw new Error('לא מחובר — יש להתחבר לחשבון כדי להשתמש ב-AI.');
  }
  let response;
  try{
    response = await fetch(`${state.settings.supabaseUrl}/functions/v1/ai-proxy-call`, {
      method: "POST",
      headers: { 'Authorization': `Bearer ${accessToken}`, "Content-Type": "application/json" },
      body: JSON.stringify({ prompt, maxTokens, contentBlocks })
    });
  }catch(networkErr){
    throw new Error('החיבור לשירות ה-AI נכשל (בעיית רשת). ודא חיבור אינטרנט תקין ונסה שוב.');
  }
  const body = await response.json();
  if(!response.ok){
    if(response.status === 401 || response.status === 400){
      throw new Error(body.error || 'מפתח ה-API אינו תקין, פג תוקף, או לא הוגדר. יש לבדוק בהגדרות AI.');
    }
    throw new Error(body.error || ('קריאה ל-AI נכשלה (סטטוס ' + response.status + ')'));
  }
  return body.text || '';
}

// ===================== מסקנת AI לדוח בדיקת מתח מגע =====================
// עקרון מנחה: ה-AI מסייע בניסוח בלבד. אסור לו להמציא ערכי סף/קריטריון שלא
// הוזנו בדוח, אסור לו לקבוע תקינות כשיש תוצאה "לא תקין"/"נדרש קריטריון"
// באחת השורות, ואסור לו "לאשר" את המתקן. שום טקסט לא נכנס לדוח בלי אישור
// מפורש של המשתמש בלחיצת כפתור.
function buildTouchVoltageDataSummaryForAI(){
  const tv = state.touchVoltageReport;
  const lines = [];
  lines.push(`סוג מתקן: ${tv.facilityType || 'לא צוין'}`);
  const sysV = touchVoltageFieldDisplay(tv.systemVoltage);
  const faultC = touchVoltageFieldDisplay(tv.faultCurrent);
  const clearT = touchVoltageFieldDisplay(tv.clearingTime);
  if(sysV) lines.push(`מתח מערכת: ${sysV}`);
  if(faultC) lines.push(`זרם תקלה: ${faultC}`);
  if(clearT) lines.push(`זמן ניתוק תקלה: ${clearT}`);
  if(tv.bodyWeight) lines.push(`משקל גוף לחישוב: ${tv.bodyWeight} ק"ג`);
  lines.push('');
  lines.push('בדיקת רציפות הארקה:');
  const relevantContinuity = tv.continuityItems.filter(it=>it.from || it.to || it.resistance);
  if(!relevantContinuity.length) lines.push('(לא הוזנו נקודות בדיקת רציפות)');
  relevantContinuity.forEach((it,i)=>{
    lines.push(`${i+1}. מ-${it.from||'לא צוין'} אל ${it.to||'לא צוין'} — התנגדות: ${it.resistance||'—'}${it.unit}, קריטריון: ${it.criterion||'לא הוזן'}, תוצאה: ${it.result||'לא סומן'}`);
  });
  lines.push('');
  lines.push('נקודות בדיקה:');
  const relevant = tv.items.filter(it=>it.location || it.touchVoltage || it.stepVoltage);
  if(!relevant.length) lines.push('(לא הוזנו נקודות בדיקה)');
  relevant.forEach((it,i)=>{
    const eq = equipmentList.find(e=>e.id===it.instrumentId);
    lines.push(`${i+1}. ${it.location||'ללא ציון מיקום'} — מתח מגע: ${it.touchVoltage||'—'}${it.unit}, מתח צעד: ${it.stepVoltage||'—'}${it.unit}, מכשיר: ${eq?eq.name:'לא צוין'}, קריטריון: ${it.criterion||'לא הוזן'}, תוצאה: ${it.result||'לא סומן'}, הערות: ${it.notes||'—'}`);
  });
  if(tv.generalNotes) lines.push(`\nהערות כלליות: ${tv.generalNotes}`);
  return lines.join('\n');
}

async function runAiSuggestConclusion(){
  const modal = document.getElementById('aiConclusionModal');
  const body = document.getElementById('aiConclusionBody');
  document.getElementById('aiConclusionTitle').textContent = '✨ הצעת מסקנה — דוח בדיקת מתח מגע';
  body.innerHTML = '<p style="text-align:center; padding:20px;">⏳ פונה ל-AI...</p>';
  modal.classList.add('show');
  const prompt = `אתה מסייע לבודק חשמל מוסמך בניסוח מסקנה לדוח בדיקת מתח מגע/צעד. הנה הנתונים שהוזנו בפועל בדוח:

${buildTouchVoltageDataSummaryForAI()}

הנחיות מחייבות:
- אסור לך להמציא ערך סף או קריטריון שלא הוזן בנתונים לעיל.
- אם קיימת ולו שורה אחת עם תוצאה "לא תקין" או "נדרש קריטריון", אינך רשאי להציע מסקנה של "תקין" ללא הסתייגות — יש לציין זאת במפורש.
- אם המידע חסר או לא מספיק כדי לגבש מסקנה, כתוב זאת במפורש במקום לנחש.
- הצע ניסוח מקצועי קצר (2-4 משפטים) שמסכם את הממצאים בפועל בלבד — זו הצעת ניסוח לבודק, לא קביעה סופית; הבודק המוסמך הוא זה שמאשר.
- החזר אך ורק את הטקסט המוצע לשדה "הרחבה", ללא הקדמות, ללא כותרות, ללא מירכאות.`;
  try{
    const suggestion = await callClaudeApi(prompt, 400);
    body.innerHTML = `
      <p style="font-size:12px; color:var(--text-dim);">הצעת ה-AI (לא נכנסה עדיין לדוח):</p>
      <div style="background:#12161a; border:1px solid var(--line); border-radius:8px; padding:12px; font-size:13px; white-space:pre-wrap;">${escapeHtml(suggestion)}</div>
      <p style="font-size:10.5px; color:var(--text-dim); margin-top:10px;">בדוק שהניסוח משקף נכון את הממצאים לפני אישור. המסקנה הסופית באחריותך כבודק המוסמך.</p>
      <div style="display:flex; gap:8px; margin-top:10px;">
        <button type="button" class="add-panel-card" id="btnAiConclusionApprove">✓ אשר והוסף לשדה "הרחבה"</button>
        <button type="button" class="del-panel-btn" id="btnAiConclusionReject">דחה</button>
      </div>`;
    document.getElementById('btnAiConclusionApprove').addEventListener('click', ()=>{
      state.touchVoltageReport.conclusion.freeText = suggestion;
      scheduleSave(); render();
      document.getElementById('aiConclusionModal').classList.remove('show');
      showToast('ההצעה נוספה לשדה "הרחבה" — ניתן לערוך לפני שמירה');
    });
    document.getElementById('btnAiConclusionReject').addEventListener('click', ()=>{
      document.getElementById('aiConclusionModal').classList.remove('show');
    });
  }catch(err){
    body.innerHTML = `<p style="color:var(--bad); padding:16px;">${escapeHtml(err.message || 'שגיאה בפנייה ל-AI')}</p>`;
  }
}

// ✨ שיפור ניסוח לפרק בודד בדוח הגמיש (item 13) — מציג מקור+הצעה, שום שינוי לא נכנס בלי אישור מפורש.
async function runAiImproveFlexibleSection(idx){
  const fr = state.flexibleReport;
  const sec = fr.sections[idx];
  if(!sec) return;
  const originalText = sec.content || '';
  if(!originalText.trim()){ showToast('אין טקסט בפרק הזה לשיפור'); return; }
  const modal = document.getElementById('aiConclusionModal');
  const body = document.getElementById('aiConclusionBody');
  document.getElementById('aiConclusionTitle').textContent = `✨ שיפור ניסוח — ${sec.title}`;
  body.innerHTML = '<p style="text-align:center; padding:20px;">⏳ פונה ל-AI...</p>';
  modal.classList.add('show');
  const prompt = `אתה מסייע לכתוב דוחות מקצועיים בעברית. הנה טקסט שנכתב על ידי בודק/מפקח עבור פרק "${sec.title}" בדוח:

"""
${originalText}
"""

הצע ניסוח מקצועי, ברור ותקני יותר לאותו תוכן — אל תשנה עובדות, אל תמציא מידע חדש, רק שפר ניסוח/בהירות/מקצועיות. החזר אך ורק את הטקסט המשופר, ללא הקדמות, ללא כותרות, ללא מירכאות.`;
  try{
    const suggestion = await callClaudeApi(prompt, 800);
    body.innerHTML = `
      <p style="font-size:11.5px; color:var(--text-dim); margin-top:0;">הטקסט המקורי:</p>
      <div style="background:#12161a; border:1px solid var(--line); border-radius:8px; padding:10px; font-size:12.5px; white-space:pre-wrap; margin-bottom:12px;">${escapeHtml(originalText)}</div>
      <p style="font-size:11.5px; color:var(--text-dim);">הניסוח המוצע (ניתן לערוך):</p>
      <textarea id="aiFlexSuggestionEdit" style="width:100%; min-height:120px; font-size:12.5px;">${escapeHtml(suggestion)}</textarea>
      <div style="display:flex; gap:8px; margin-top:10px;">
        <button type="button" class="add-panel-card" id="btnAiFlexApprove">✓ אשר</button>
        <button type="button" class="del-panel-btn" id="btnAiFlexReject">דחה</button>
      </div>`;
    document.getElementById('btnAiFlexApprove').addEventListener('click', ()=>{
      const editedText = document.getElementById('aiFlexSuggestionEdit').value;
      state.flexibleReport.sections[idx].content = editedText;
      scheduleSave(); render();
      document.getElementById('aiConclusionModal').classList.remove('show');
      showToast('הניסוח עודכן בפרק');
    });
    document.getElementById('btnAiFlexReject').addEventListener('click', ()=>{
      document.getElementById('aiConclusionModal').classList.remove('show');
    });
  }catch(err){
    body.innerHTML = `<p style="color:var(--bad); padding:16px;">${escapeHtml(err.message || 'שגיאה בפנייה ל-AI')}</p>`;
  }
}

// ✨ יצירת סיכום מקצועי (item 15) — קורא את כל הפרקים הרלוונטיים ומציע ניסוח מותאם לסוג הדוח.
// אין להמציא ממצאים שלא נכתבו — הפרומפט מדגיש זאת במפורש, ותמיד מוצגת תצוגה מקדימה לאישור.
async function runAiGenerateFlexibleSummary(idx){
  const fr = state.flexibleReport;
  const sec = fr.sections[idx];
  if(!sec) return;

  // אוספים את תוכן כל הפרקים הרלוונטיים לסיכום (item 15), לא כולל הסיכום עצמו
  const relevantTypes = ['פירוט','רקע','פרטי האירוע','מהלך הבדיקה','אופן ביצוע הבדיקה','ממצאים','ליקויים','המלצות','פעולות נדרשות','תמצית','תמצית פרטי האירוע'];
  const relevantSections = fr.sections.filter(s => relevantTypes.includes(s.type) && s.content && s.content.trim());
  let sourceText = fr.subject.trim() ? `הנדון: ${fr.subject.trim()}\n\n` : '';
  sourceText += relevantSections.map(s => `### ${s.title}\n${s.content}`).join('\n\n');
  if(fr.manualNotes && fr.manualNotes.trim()) sourceText += `\n\n### הערות\n${fr.manualNotes}`;
  const photoNotes = (state.generalPhotos||[]).flatMap(p=>(p.notes||[]).filter(n=>n&&n.trim()));
  if(fr.includePhotoNotesInNotes && photoNotes.length) sourceText += `\n\n### הערות תמונות\n${photoNotes.map((n,i)=>`${i+1}. ${n}`).join('\n')}`;

  const modal = document.getElementById('aiConclusionModal');
  const body = document.getElementById('aiConclusionBody');
  document.getElementById('aiConclusionTitle').textContent = `✨ יצירת סיכום — ${sec.title}`;
  if(!sourceText.trim()){
    modal.classList.add('show');
    body.innerHTML = `<p style="padding:16px;">אין עדיין תוכן בפרקים האחרים (פירוט/ממצאים/המלצות וכו') ליצור מהם סיכום. יש למלא אותם קודם.</p>`;
    return;
  }
  body.innerHTML = '<p style="text-align:center; padding:20px;">⏳ יוצר סיכום...</p>';
  modal.classList.add('show');

  const kindLabel = (FLEXIBLE_REPORT_KIND_OPTIONS.find(o=>o.value===fr.reportType)||{}).label || 'דוח';
  const styleHint = {
    SUPERVISION_REPORT: 'נסח כסיכום פיקוח — התמקד במה שנבדק ובמצב הכללי שנמצא.',
    GENERAL_INSPECTION_REPORT: 'נסח כסיכום בדיקה — התמקד בתוצאות הבדיקה ובממצאים העיקריים.',
    GENERAL_REPORT: 'נסח כסיכום כללי קצר וברור.',
    SUMMARY_REPORT: 'נסח כסיכום אירוע — התמקד באירוע עצמו, בממצאים ובפעולות שננקטו/נדרשות.',
    CUSTOM_REPORT: 'נסח כסיכום מקצועי המתאים לתוכן שנכתב.'
  }[fr.reportType] || 'נסח כסיכום מקצועי קצר.';

  const prompt = `אתה מסייע לכתוב דוחות מקצועיים בעברית. זהו "${kindLabel}". הנה תוכן הדוח שנכתב בפועל עד כה:

${sourceText}

המשימה: כתוב סיכום מקצועי קצר (3-6 משפטים) המבוסס אך ורק על התוכן שסופק לעיל.
הנחיות מחייבות:
- ${styleHint}
- אסור לך להמציא ממצאים, נתונים או מסקנות שלא נכתבו בפועל בתוכן שסופק.
- אם התוכן חסר או לא מספיק כדי לגבש סיכום משמעותי, ציין זאת במפורש במקום להמציא.
- החזר אך ורק את טקסט הסיכום, ללא הקדמות, ללא כותרות, ללא מירכאות.`;

  try{
    const suggestion = await callClaudeApi(prompt, 500);
    body.innerHTML = `
      <p style="font-size:11.5px; color:var(--text-dim); margin-top:0;">תצוגה מקדימה — הסיכום המוצע (ניתן לערוך לפני אישור):</p>
      <textarea id="aiFlexSummaryEdit" style="width:100%; min-height:120px; font-size:12.5px;">${escapeHtml(suggestion)}</textarea>
      <p style="font-size:10.5px; color:var(--text-dim); margin-top:6px;">הסיכום מבוסס רק על הפרקים שכבר מולאו. בדוק שהוא משקף נכון את הדוח לפני אישור.</p>
      <div style="display:flex; gap:8px; margin-top:10px;">
        <button type="button" class="add-panel-card" id="btnAiFlexSummaryApprove">✓ אשר והכנס לפרק</button>
        <button type="button" class="del-panel-btn" id="btnAiFlexSummaryReject">דחה</button>
      </div>`;
    document.getElementById('btnAiFlexSummaryApprove').addEventListener('click', ()=>{
      const editedText = document.getElementById('aiFlexSummaryEdit').value;
      state.flexibleReport.sections[idx].content = editedText;
      scheduleSave(); render();
      document.getElementById('aiConclusionModal').classList.remove('show');
      showToast('הסיכום נוסף לפרק');
    });
    document.getElementById('btnAiFlexSummaryReject').addEventListener('click', ()=>{
      document.getElementById('aiConclusionModal').classList.remove('show');
    });
  }catch(err){
    body.innerHTML = `<p style="color:var(--bad); padding:16px;">${escapeHtml(err.message || 'שגיאה בפנייה ל-AI')}</p>`;
  }
}

// ✨ בדיקת AI לדוח הגמיש כולו (item 14) — שגיאות כתיב/ניסוח/אי-התאמות. כל תיקון מאושר בנפרד,
// שום דבר לא משתנה אוטומטית. תוצאה מובנית (JSON) כדי לאפשר אישור/דחייה פר-הערה.
async function runAiCheckFlexibleReport(){
  const fr = state.flexibleReport;
  const modal = document.getElementById('aiConclusionModal');
  const body = document.getElementById('aiConclusionBody');
  document.getElementById('aiConclusionTitle').textContent = '✨ בדיקת AI לדוח כולו';

  const sectionsText = fr.sections.filter(s=>s.content && s.content.trim()).map(s=>`### ${s.title}\n${s.content}`).join('\n\n');
  if(!fr.subject.trim() && !sectionsText.trim()){
    modal.classList.add('show');
    body.innerHTML = `<p style="padding:16px;">יש למלא תוכן בדוח לפני הבדיקה.</p>`;
    return;
  }
  body.innerHTML = '<p style="text-align:center; padding:20px;">⏳ בודק את הדוח...</p>';
  modal.classList.add('show');

  const prompt = `אתה בודק דוח מקצועי בעברית לפני שליחה. הנה תוכן הדוח:

הנדון: ${fr.subject || '(לא הוזן)'}

${sectionsText}

חפש: שגיאות כתיב, טעויות הקלדה, מילים חסרות, מילים לא נכונות, ניסוח לא ברור, ניסוח לא מקצועי, חזרה מיותרת על משפטים, ואי-התאמה בין חלקי הדוח (לא רק פיסוק).

החזר אך ורק אובייקט JSON תקין (ללא טקסט נוסף, ללא markdown), במבנה:
{"issues":[{"location":"שם הפרק או 'הנדון'","original":"הקטע המקורי (עד 20 מילים)","suggestion":"התיקון המוצע","reason":"הסבר קצר למה"}]}

אם לא נמצאו בעיות, החזר {"issues":[]}.`;

  try{
    const raw = await callClaudeApi(prompt, 1500);
    const parsed = extractJsonFromAiResponse(raw);
    const issues = (parsed && Array.isArray(parsed.issues)) ? parsed.issues : [];
    if(!issues.length){
      body.innerHTML = `<p style="padding:16px; text-align:center;">✓ לא נמצאו בעיות משמעותיות בדוח.</p>
        <button type="button" class="add-panel-card" id="btnAiFlexCheckClose" style="margin-top:10px;">סגור</button>`;
    } else {
      body.innerHTML = `
        <p style="font-size:11.5px; color:var(--text-dim); margin-top:0;">נמצאו ${issues.length} הערות. כל תיקון דורש אישור נפרד — שום דבר לא משתנה אוטומטית.</p>
        ${issues.map((iss,ii)=>`
          <div class="ai-flex-issue-card" data-issueidx="${ii}" style="background:#12161a; border:1px solid var(--line); border-radius:8px; padding:10px; margin-bottom:10px;">
            <p style="font-size:11px; color:var(--amber); font-weight:700; margin:0 0 6px;">${escapeHtml(iss.location||'')}</p>
            <p style="font-size:12px; margin:4px 0;"><b>מקור:</b> ${escapeHtml(iss.original||'')}</p>
            <p style="font-size:12px; margin:4px 0;"><b>הצעה:</b> ${escapeHtml(iss.suggestion||'')}</p>
            <p style="font-size:11px; color:var(--text-dim); margin:4px 0;"><b>סיבה:</b> ${escapeHtml(iss.reason||'')}</p>
            <div style="display:flex; gap:8px; margin-top:8px;">
              <button type="button" class="add-panel-card" data-flexissueapprove="${ii}" style="flex:1; padding:6px; font-size:11.5px;">✓ אשר והחלף</button>
              <button type="button" class="del-panel-btn" data-flexissuereject="${ii}" style="flex:1; padding:6px; font-size:11.5px;">דחה</button>
            </div>
          </div>`).join('')}
        <button type="button" class="add-panel-card" id="btnAiFlexCheckClose" style="margin-top:6px;">סגור</button>`;

      issues.forEach((iss,ii)=>{
        const approveBtn = document.querySelector(`[data-flexissueapprove="${ii}"]`);
        if(approveBtn) approveBtn.addEventListener('click', ()=>{
          const fr2 = state.flexibleReport;
          let applied = false;
          if(iss.original && fr2.subject.includes(iss.original)){
            fr2.subject = fr2.subject.replace(iss.original, iss.suggestion);
            applied = true;
          } else if(iss.original){
            const sec = fr2.sections.find(s => s.content && s.content.includes(iss.original));
            if(sec){ sec.content = sec.content.replace(iss.original, iss.suggestion); applied = true; }
          }
          scheduleSave(); render();
          showToast(applied ? 'התיקון הוחל' : 'לא נמצא הטקסט המדויק להחלפה אוטומטית — יש לערוך ידנית');
          document.getElementById('aiConclusionModal').classList.remove('show');
        });
        const rejectBtn = document.querySelector(`[data-flexissuereject="${ii}"]`);
        if(rejectBtn) rejectBtn.addEventListener('click', ()=>{
          const card = document.querySelector(`.ai-flex-issue-card[data-issueidx="${ii}"]`);
          if(card) card.style.opacity = '0.4';
          approveBtn.disabled = true;
          rejectBtn.disabled = true;
        });
      });
    }
    const closeBtn = document.getElementById('btnAiFlexCheckClose');
    if(closeBtn) closeBtn.addEventListener('click', ()=>{
      document.getElementById('aiConclusionModal').classList.remove('show');
    });
  }catch(err){
    body.innerHTML = `<p style="color:var(--bad); padding:16px;">${escapeHtml(err.message || 'שגיאה בפנייה ל-AI')}</p>`;
  }
}

