// ===================== בדיקת כתיב וניסוח מקצועי =====================

function isTechnicalCode(text){
  const trimmed = (text||'').trim();
  if(!trimmed) return true;
  if(TEXT_REVIEW_SKIP_CODES.includes(trimmed)) return true;
  if(/^[A-Za-z0-9.\-\/×Δ]+$/.test(trimmed)) return true; // pure codes/numbers/units, no Hebrew letters
  if(/^\S+@\S+\.\S+$/.test(trimmed)) return true; // email
  if(/^https?:\/\//.test(trimmed)) return true; // URL
  return false;
}

function collectReportTextFields(){
  const fields = [];
  document.querySelectorAll('#app [data-textpath]').forEach(el=>{
    if(el.tagName !== 'TEXTAREA' && el.tagName !== 'INPUT') return;
    if(el.tagName === 'INPUT' && (el.type === 'number' || el.type === 'date' || el.type === 'email' || el.type === 'url')) return;
    const restrict = el.getAttribute('data-restrict');
    if(restrict === 'decimal' || restrict === 'digits') return;
    const path = el.getAttribute('data-textpath');
    const value = el.value;
    if(!value || !value.trim()) return;
    if(isTechnicalCode(value)) return;
    // Use the nearest section title + field label for readable context
    const section = el.closest('section.card');
    const sectionKey = section ? section.getAttribute('data-key') : '';
    const sectionName = section ? (section.querySelector('h2') ? section.querySelector('h2').textContent.replace(/^\d+(\.\d+)?\s*/, '').trim() : '') : '';
    const fieldWrap = el.closest('.field');
    const fieldName = fieldWrap && fieldWrap.querySelector('label') ? fieldWrap.querySelector('label').textContent.trim() : path.split('.').pop();
    const isHidden = section ? !section.classList.contains('open') : false;
    fields.push({ fieldId: path, sectionKey, sectionName, fieldName, text: value, isHidden, pageNumber: 1 });
  });
  return fields;
}

function splitTextFieldsIntoBatches(fields){
  const batches = [];
  let current = [];
  let currentChars = 0;
  fields.forEach(f=>{
    const fieldChars = f.text.length + 40; // rough overhead per field in the prompt
    if(current.length >= 20 || (currentChars + fieldChars) > 6000){
      if(current.length) batches.push(current);
      current = [];
      currentChars = 0;
    }
    current.push(f);
    currentChars += fieldChars;
  });
  if(current.length) batches.push(current);
  return batches;
}

function focusReportField(fieldId){
  document.getElementById('textReviewModal').classList.remove('show');
  const section = document.querySelector(`[data-textpath="${fieldId}"]`)?.closest('section.card');
  if(section && !section.classList.contains('open')){
    const key = section.getAttribute('data-key');
    openSections.add(key);
    render();
  }
  setTimeout(()=>{
    const el = document.querySelector(`[data-textpath="${fieldId}"]`);
    if(!el){ showToast('לא ניתן היה לאתר את השדה (ייתכן שהוא בעמוד אחר).'); return; }
    el.scrollIntoView({ behavior:'smooth', block:'center' });
    el.focus();
    el.style.outline = '3px solid var(--amber)';
    el.style.transition = 'outline 0.3s';
    setTimeout(()=>{ el.style.outline = ''; }, 3000);
  }, 200);
}

function findCrossReportContradictions(fields){
  const contradictions = [];
  const dc = getReportType() === 'DC_CABLE' ? state.dcCableTest : null;
  const ev = getReportType() === 'EV_DC' ? state.evDcReport.page2 : null;

  // Example 1: approvalStatus vs. free-text notes mentioning the opposite result
  if(state.approvalStatus && Array.isArray(state.notes)){
    const approvedOk = state.approvalStatus === APPROVAL_OPTIONS[0];
    state.notes.forEach((n,i)=>{
      if(!n) return;
      if(approvedOk && /לא\s*תקין/.test(n)){
        contradictions.push({ fieldA: 'approvalStatus', textA: state.approvalStatus, fieldB: `notes.${i}`, textB: n,
          explanation: 'המסקנה הכללית מציינת אישור, אך נמצאה הערה המזכירה "לא תקין".' });
      }
    });
  }

  // Example 2 (EV_DC): protection method on the intake page vs. protection-system section
  if(ev && ev.protectionSystem && ev.supplyDetails){
    const a = ev.supplyDetails.protectionMethod;
    const bKey = ev.protectionSystem.protectionMethod;
    const bLabel = (EV_DC_PROTECTION_METHOD_OPTIONS.find(o=>o.value===bKey)||{}).label || bKey;
    if(a && bLabel && a.trim() && bLabel.trim() && a.trim() !== bLabel.trim()){
      contradictions.push({ fieldA: 'evDcReport.page2.supplyDetails.protectionMethod', textA: a,
        fieldB: 'evDcReport.page2.protectionSystem.protectionMethod', textB: bLabel,
        explanation: 'שיטת ההגנה בפני חשמול שונה בין פרטי ההזנה לבין פרק ההגנות המרוכז.' });
    }
  }

  return contradictions;
}

function findRepeatedWords(text){
  const issues = [];
  // Note: \b in JS regex only recognizes [A-Za-z0-9_] as "word" characters, so it fails
  // to detect boundaries around Hebrew text. Using (?:^|\s) / (?=\s|$) instead works for any script.
  const re = /(?:^|\s)(\S+)\s+\1(?=\s|$)/g;
  let m;
  while((m = re.exec(text))){
    issues.push({ type:'חזרה מיותרת', snippet:m[1]+' '+m[1], explanation:`המילה "${m[1]}" חוזרת פעמיים ברצף.` });
  }
  return issues;
}

function findPunctuationIssues(text){
  const issues = [];
  if(/ {2,}/.test(text)) issues.push({ type:'פיסוק', explanation:'נמצא רווח כפול או יותר.' });
  if(/[,.;:!?][^\s"'\)]/.test(text.replace(/\d+[.,]\d+/g,''))) issues.push({ type:'פיסוק', explanation:'חסר רווח אחרי סימן פיסוק.' });
  if(/\s[,.;:!?]/.test(text)) issues.push({ type:'פיסוק', explanation:'נמצא רווח מיותר לפני סימן פיסוק.' });
  if(/[,.;:!?]{2,}/.test(text)) issues.push({ type:'פיסוק', explanation:'נמצא סימן פיסוק כפול.' });
  if(/^\s|\s$/.test(text)) issues.push({ type:'הקלדה', explanation:'השדה מתחיל או מסתיים ברווח מיותר.' });
  return issues;
}

function findMissingEndPunctuation(text){
  const issues = [];
  const trimmed = text.trim();
  // Only flag genuinely sentence-like text (multiple words), not short labels/fragments
  if(trimmed.split(/\s+/).length >= 5 && !/[.!?׃:]$/.test(trimmed)){
    issues.push({ type:'ניסוח', explanation:'המשפט אינו מסתיים בסימן פיסוק (נקודה/סימן שאלה/קריאה).' });
  }
  return issues;
}

function findSuspiciousLetterSequences(text){
  const issues = [];
  // Hebrew: same letter repeated 3+ times in a row is almost never intentional (e.g. "שלולום")
  const m = text.match(/([א-ת])\1{2,}/);
  if(m) issues.push({ type:'שגיאת כתיב', explanation:`נמצאה אות "${m[1]}" חוזרת ${m[0].length} פעמים ברצף — כנראה שגיאת הקלדה.` });
  return issues;
}

function findUnnecessaryLanguageMixing(text){
  const issues = [];
  // Flag Hebrew and Latin letters mixed WITHIN the same word (not just co-occurring in the sentence,
  // which is normal for standards/codes like "IEC 61851") — e.g. "בdיקה" or "מכשirה".
  if(/[א-ת][A-Za-z]|[A-Za-z][א-ת]/.test(text)){
    issues.push({ type:'הקלדה', explanation:'נמצא ערבוב של אותיות עבריות ולטיניות בתוך אותה מילה — ייתכן שינוי שפת מקלדת בטעות.' });
  }
  return issues;
}

function findTerminologyInconsistencies(allFields){
  const synonymGroups = [
    ['מוליך הארקה','גיד הארקה','כבל הארקה'],
    ['מפסק מגן','ממסר פחת'],
    ['עמדת טעינה','מטען'],
    ['בדיקה חזותית','בדיקה ויזואלית']
  ];
  const issues = [];
  const combinedText = allFields.map(f=>f.text).join(' \n ');
  synonymGroups.forEach(group=>{
    const found = group.filter(term => combinedText.includes(term));
    if(found.length > 1){
      issues.push({ type:'מונח מקצועי לא אחיד', explanation:`נמצא שימוש לא אחיד במונחים: ${found.join(', ')}. מומלץ לבחור מונח אחד ולהשתמש בו לאורך כל הדוח.`, terms: found });
    }
  });
  return issues;
}

function runLocalTextChecks(fields){
  const issues = [];
  let idCounter = 1;
  fields.forEach(f=>{
    const repeats = findRepeatedWords(f.text);
    const letterSeq = findSuspiciousLetterSequences(f.text);
    const langMix = findUnnecessaryLanguageMixing(f.text);
    [...repeats, ...letterSeq, ...langMix].forEach(iss=>{
      issues.push({
        id: 'local_' + (idCounter++), fieldId: f.fieldId, sectionName: f.sectionName, fieldName: f.fieldName,
        originalText: f.text, issueType: iss.type, explanation: iss.explanation,
        suggestedText: '', confidence: 'גבוהה', status: 'pending', source: 'local'
      });
    });
  });
  return issues;
}

function sanitizeSensitiveInformation(fields){
  const sensitivePaths = ['meta.client','meta.address','meta.attentionTo'];
  return fields.map(f=>{
    if(sensitivePaths.includes(f.fieldId)) return { ...f, text: '[פרט מזוהה הוסר לצורך הבדיקה]' };
    return f;
  });
}

async function runAiTextReviewBatch(fields){
  const dictList = professionalDictionary.join(', ');
  const fieldsForPrompt = fields.map((f,i)=>`[${i}] (${f.sectionName} — ${f.fieldName}): "${f.text}"`).join('\n');
  const prompt = `אתה בודק איות בעברית עבור דוחות בדיקה הנדסיים.

בדוק כל מילה בטקסט בצורה קפדנית.

המטרה היחידה שלך היא לאתר שגיאות כתיב והקלדה.

התעלם לחלוטין מפסיקים, נקודות, רווחים, פיסוק, תחביר, סגנון וניסוח מקצועי.

אל תציע שיפור סגנון.
אל תשנה את מבנה המשפט.
אל תנסח מחדש משפטים.

חפש במיוחד:
- אות חסרה
- אות מיותרת
- אות כפולה
- החלפת אות
- סדר אותיות שגוי
- שגיאה פונטית
- חיבור שגוי של מילים
- הפרדה שגויה של מילה
- מילה כפולה
- מילה לא תקינה בעברית
- שיבוש של מונח מקצועי

אל תתעלם ממילה שגויה רק מפני שניתן להבין את משמעותה.

המילון המקצועי הבא הוא רשימת מונחים תקינים שאסור לסמן כשגיאה: ${dictList}.
אין לשנות מספרים, ערכי מדידה, דגמים, תקנים, קודים או שמות מסחריים.
אם אינך בטוח מהי המילה הנכונה, אל תתקן — סמן requiresClarification=true עם שאלת הבהרה, והשאר suggestedWord ריק.

השדות שיש לבדוק:
${fieldsForPrompt}

עבור כל שגיאה החזר: מזהה השדה (fieldIndex), המילה השגויה (wrongWord), המילה המוצעת (suggestedWord), המשפט המלא שבו נמצאה המילה (originalSentence), הסבר קצר, רמת ביטחון.

החזר JSON בלבד, ללא טקסט נוסף לפני או אחריו, במבנה המדויק הבא:
{"spellingErrors": [{"fieldIndex": 0, "originalSentence": "המשפט המלא", "wrongWord": "המילה השגויה", "suggestedWord": "המילה המוצעת", "explanation": "הסבר קצר בעברית", "confidence": "high|medium|low", "requiresClarification": false, "clarificationQuestion": ""}]}
אם לא נמצאו שגיאות כתיב, החזר {"spellingErrors": []}.`;

  const raw = await callClaudeApi(prompt, 2500);
  let parsed;
  try{ parsed = extractJsonFromAiResponse(raw); }catch(e){ throw new Error('התקבלה תשובה לא תקינה משירות ה-AI (JSON לא תקין) — לא בוצע שינוי.'); }
  if(!parsed || !Array.isArray(parsed.spellingErrors)) throw new Error('התקבלה תשובה לא תקינה משירות ה-AI (מבנה לא תקין) — לא בוצע שינוי.');

  return parsed.spellingErrors.map(item=>{
    const f = fields[item.fieldIndex];
    if(!f) return null;
    const requiresClarification = !!item.requiresClarification;
    // Build the corrected full-field text by replacing the wrong word with the suggested one,
    // since corrections are applied to the actual field (not just the isolated word).
    const suggestedText = (!requiresClarification && item.wrongWord && item.suggestedWord)
      ? f.text.replace(item.wrongWord, item.suggestedWord) : '';
    return {
      fieldId: f.fieldId, sectionName: f.sectionName, fieldName: f.fieldName,
      originalText: item.originalSentence || f.text, problemText: item.wrongWord || '',
      issueType: requiresClarification ? 'דרושה הבהרה' : 'שגיאת כתיב',
      explanation: item.explanation || '',
      suggestedText: requiresClarification ? '' : suggestedText,
      confidence: item.confidence === 'high' ? 'גבוהה' : item.confidence === 'low' ? 'נמוכה' : 'בינונית',
      requiresClarification, clarificationQuestion: item.clarificationQuestion || '',
      wrongWord: item.wrongWord || '', suggestedWord: item.suggestedWord || '',
      status: 'pending', source: 'ai'
    };
  }).filter(Boolean);
}

async function runAiChecksForAllFields(fields){
  const batches = splitTextFieldsIntoBatches(fields);
  const allResults = [];
  const batchErrors = [];
  for(let i=0; i<batches.length; i++){
    showToast(`שולח קבוצה ${i+1} מתוך ${batches.length} לבדיקת AI…`);
    try{
      const batchResults = await runAiTextReviewBatch(batches[i]);
      allResults.push(...batchResults);
    }catch(e){
      console.error(e);
      batchErrors.push(`קבוצה ${i+1}: ${e.message}`);
      showToast(`שגיאה בקבוצה ${i+1}: ${e.message} — ממשיך לקבוצה הבאה.`);
    }
  }
  let idCounter = 1;
  const issues = allResults.map(r => ({ ...r, id: 'ai_' + (idCounter++) }));
  return { issues, batchErrors, totalBatches: batches.length, failedBatches: batchErrors.length };
}

async function reviewEntireReport(){
  const btn = document.getElementById('btnTextReview');
  if(btn.disabled) return;
  btn.disabled = true;
  try{
    const fields = collectReportTextFields();
    if(!fields.length){
      showToast('לא נמצאו שדות טקסט לבדיקה בדוח הנוכחי.');
      return;
    }
    showToast(`נמצאו ${fields.length} שדות. בודק ברמה מקומית…`);
    const localIssues = runLocalTextChecks(fields);

    const hasApiKey = cloudAiSettings.configured;
    // Default to AI checking whenever a key is configured — pressing OK without changing
    // the value should not silently downgrade to local-only checking (which cannot catch
    // real spelling errors, only spacing/punctuation/repetition issues).
    const defaultChoice = hasApiKey ? '1' : '3';
    const choice = prompt(
      'המערכת עומדת לבדוק את כל הדוח (כולל אזורים מכווצים).\n' +
      'הקלד אחת מהאפשרויות:\n' +
      '1 = אישור ושליחת הטקסט לבדיקת AI חיצונית (Claude) — מזהה שגיאות כתיב אמיתיות\n' +
      '2 = הסר פרטים מזהים ושלח ל-AI\n' +
      '3 = בדיקה מקומית בלבד (ללא AI — לא מזהה שגיאות כתיב, רק רווחים/פיסוק/חזרות)\n' +
      'ביטול = לבטל את הבדיקה כולה' +
      (hasApiKey ? '' : '\n\n⚠ לא הוגדר מפתח API בהגדרות — בדיקת AI לא תהיה זמינה.'),
      defaultChoice
    );
    let aiIssues = [];
    let mode = 'local-only';
    let aiError = null;
    if(choice === '1' || choice === '2'){
      if(!hasApiKey){
        showToast('לא הוגדר מפתח API — לא ניתן להריץ בדיקת AI. כשהקובץ נפתח כקובץ עצמאי (מחוץ ל-claude.ai), חובה להזין מפתח API בהגדרות (⚙) כדי שבדיקת ה-AI תעבוד. מציג בינתיים תוצאות בדיקה מקומית בלבד.');
      } else {
        mode = 'local+ai';
        const fieldsToSend = choice === '2' ? sanitizeSensitiveInformation(fields) : fields;
        const batches = splitTextFieldsIntoBatches(fieldsToSend);
        showToast(`נבדקו 0 מתוך ${fields.length} שדות — שולח ${batches.length} קבוצות ל-AI…`);
        try{
          const result = await runAiChecksForAllFields(fieldsToSend);
          aiIssues = result.issues;
          if(result.failedBatches > 0){
            aiError = result.batchErrors.join(' | ');
            if(result.failedBatches === result.totalBatches){
              mode = 'local-only'; // every single batch failed — this was not actually an AI check
              showToast(`בדיקת ה-AI נכשלה לחלוטין (${result.failedBatches}/${result.totalBatches} קבוצות) — מוצגות רק תוצאות מקומיות. ${aiError}`);
            } else {
              showToast(`נבדקו ${fields.length} שדות — ${result.failedBatches} מתוך ${result.totalBatches} קבוצות AI נכשלו. ${aiError}`);
            }
          } else {
            showToast(`נבדקו ${fields.length} מתוך ${fields.length} שדות (כולל AI).`);
          }
        }catch(e){
          aiError = e.message;
          mode = 'local-only';
          showToast('שגיאה בבדיקת ה-AI: ' + e.message + ' — מוצגות רק תוצאות הבדיקה המקומית.');
        }
      }
    } else if(choice === null){
      showToast('הבדיקה בוטלה.');
      return;
    } else {
      showToast('בדיקה מקומית בלבד הופעלה (ללא AI) — שגיאות כתיב אמיתיות לא ייבדקו.');
    }

    const contradictions = findCrossReportContradictions(fields);

    textReview = {
      reviewedAt: new Date().toISOString(), provider: mode==='local+ai' ? 'Anthropic Claude' : '', mode, aiError,
      issues: [...localIssues, ...aiIssues], contradictions,
      revisionHistory: textReview.revisionHistory || [],
      totalFields: fields.length, checkedFields: fields.length
    };
    renderTextReviewDialog();
  } finally {
    btn.disabled = false;
  }
}

async function startTextReview(){
  return reviewEntireReport();
}

function renderTextReviewDialog(filterKey){
  filterKey = filterKey || 'all';
  const allIssues = textReview.issues;
  const approved = allIssues.filter(i=>i.status==='approved').length;
  const rejected = allIssues.filter(i=>i.status==='rejected').length;
  const pending = allIssues.filter(i=>i.status==='pending').length;
  const clarify = allIssues.filter(i=>i.issueType==='דרושה הבהרה' || i.issueType==='משפט לא ברור').length;
  const contradictions = textReview.contradictions || [];

  const issues = filterKey==='all' ? allIssues
    : filterKey==='pending' ? allIssues.filter(i=>i.status==='pending')
    : filterKey==='approved' ? allIssues.filter(i=>i.status==='approved')
    : filterKey==='rejected' ? allIssues.filter(i=>i.status==='rejected')
    : filterKey==='clarify' ? allIssues.filter(i=>i.issueType==='דרושה הבהרה' || i.issueType==='משפט לא ברור')
    : allIssues;

  const modeLabel = textReview.mode === 'local+ai'
    ? '✓ נבדק כולל AI (Claude) — כולל שגיאות כתיב אמיתיות'
    : '⚠ נבדק ברמה מקומית בלבד (ללא AI) — רווחים/פיסוק/חזרות בלבד, שגיאות כתיב אמיתיות לא נבדקו';
  const modeColor = textReview.mode === 'local+ai' ? 'var(--ok,#3fa34d)' : 'var(--warn,#c67405)';
  const summaryHtml = `
    <div class="ground-calc-box" style="border-color:${modeColor};">
      <div style="color:${modeColor}; font-weight:700; margin-bottom:6px;">${modeLabel}</div>
      ${textReview.aiError ? `<div style="color:var(--bad,#e0503a); font-size:11.5px; margin-bottom:6px;">שגיאת AI: ${escapeHtml(textReview.aiError)}</div>` : ''}
      נבדקו ${textReview.checkedFields || collectReportTextFields().length} שדות | נמצאו ${allIssues.length} הערות | אושרו: ${approved} | נדחו: ${rejected} | ממתינות: ${pending} | דורשות הבהרה: ${clarify} | סתירות: ${contradictions.length}
    </div>
    <div class="field" style="margin-top:8px;">
      <label>סינון תוצאות</label>
      <select id="trFilterSelect">
        <option value="all" ${filterKey==='all'?'selected':''}>כל הדוח (${allIssues.length})</option>
        <option value="pending" ${filterKey==='pending'?'selected':''}>ממתין לאישור (${pending})</option>
        <option value="approved" ${filterKey==='approved'?'selected':''}>אושר (${approved})</option>
        <option value="rejected" ${filterKey==='rejected'?'selected':''}>נדחה (${rejected})</option>
        <option value="clarify" ${filterKey==='clarify'?'selected':''}>דורש הבהרה (${clarify})</option>
      </select>
    </div>`;

  const contradictionsHtml = contradictions.length ? `
    <div class="subhead">סתירות אפשריות בין חלקי הדוח</div>
    ${contradictions.map(c=>`
      <div class="dc-group-block" style="border-color:var(--bad,#e0503a);">
        <div style="font-size:12px; margin-bottom:4px;"><b>שדה א׳:</b> ${escapeHtml(c.fieldA)} — "${escapeHtml(String(c.textA))}"</div>
        <div style="font-size:12px; margin-bottom:4px;"><b>שדה ב׳:</b> ${escapeHtml(c.fieldB)} — "${escapeHtml(String(c.textB))}"</div>
        <div style="font-size:11.5px; color:var(--text-dim);">${escapeHtml(c.explanation)}</div>
        <p style="font-size:11px; color:var(--warn,#c67405); margin-top:6px;">⚠ יש לבדוק ידנית איזה ערך נכון — המערכת אינה מתקנת סתירות אוטומטית.</p>
      </div>`).join('')}
  ` : '';

  const issuesHtml = issues.length ? issues.map(iss=>{
    const statusColor = iss.status==='approved' ? 'var(--ok,#3fa34d)' : (iss.status==='rejected' ? 'var(--bad,#e0503a)' : 'var(--text-dim)');
    const identicalCount = allIssues.filter(o => o.id !== iss.id && o.status==='pending' && o.problemText && o.problemText === iss.problemText && o.suggestedText === iss.suggestedText).length;
    if(iss.requiresClarification && iss.status === 'pending'){
      return `
      <div class="dc-group-block" data-issue-id="${iss.id}" style="border-color:var(--warn,#c67405);">
        <div class="dc-group-head">
          <h3 style="font-size:13px;">${escapeHtml(iss.sectionName)} — ${escapeHtml(iss.fieldName)} <span style="font-size:10px; color:var(--warn,#c67405); font-weight:700;">דרושה הבהרה</span></h3>
        </div>
        <div style="font-size:12px; background:var(--panel2); padding:8px; border-radius:6px; margin-bottom:6px;"><b>המשפט:</b> ${escapeHtml(iss.originalText)}</div>
        <div style="font-size:12px; color:var(--warn,#c67405); margin-bottom:6px;"><b>שאלה:</b> ${escapeHtml(iss.clarificationQuestion || iss.explanation)}</div>
        <div class="field"><label>הסבר למה התכוונת</label>
          <textarea data-tr-clarify-input="${iss.id}" rows="2" placeholder="כתוב כאן את הכוונה המדויקת..."></textarea>
        </div>
        <div style="display:flex; gap:6px; flex-wrap:wrap;">
          <button type="button" class="add-btn" data-tr-clarify-send="${iss.id}">שלח לבדיקה חוזרת</button>
          <button type="button" class="del-panel-btn" data-tr-reject="${iss.id}">דחה</button>
          ${iss.fieldId ? `<button type="button" class="del-panel-btn" data-tr-goto="${iss.fieldId}">עבור לשדה בדוח</button>` : ''}
        </div>
      </div>`;
    }
    return `
    <div class="dc-group-block" data-issue-id="${iss.id}">
      <div class="dc-group-head">
        <h3 style="font-size:13px;">${escapeHtml(iss.sectionName)} — ${escapeHtml(iss.fieldName)} ${iss.isHidden ? '<span style="font-size:10px; color:var(--text-dim); font-weight:400;">(אזור מכווץ)</span>' : ''}</h3>
        <span style="font-size:11px; color:${statusColor}; font-weight:700;">${iss.status==='approved'?'✓ אושר':(iss.status==='rejected'?'✗ נדחה':'ממתין')}</span>
      </div>
      <div style="font-size:11.5px; color:var(--text-dim); margin-bottom:6px;">
        סוג בעיה: <b>${escapeHtml(iss.issueType)}</b> &nbsp;|&nbsp; רמת ביטחון: ${escapeHtml(iss.confidence)} &nbsp;|&nbsp; מקור: ${iss.source==='ai'?'AI':'מקומי'}
      </div>
      <div style="font-size:12px; background:var(--panel2); padding:8px; border-radius:6px; margin-bottom:4px;">
        <b>המשפט:</b> ${iss.wrongWord ? highlightWrongWord(iss.originalText, iss.wrongWord) : escapeHtml(iss.originalText)}
      </div>
      ${iss.wrongWord && iss.suggestedWord ? `<div style="font-size:12.5px; margin-bottom:4px;"><span style="color:var(--bad,#e0503a); text-decoration:line-through;">${escapeHtml(iss.wrongWord)}</span> &nbsp;←&nbsp; <span style="color:var(--ok,#3fa34d); font-weight:700;">${escapeHtml(iss.suggestedWord)}</span></div>`
        : (iss.problemText ? `<div style="font-size:11.5px; color:var(--bad,#e0503a); margin-bottom:4px;"><b>החלק הבעייתי:</b> "${escapeHtml(iss.problemText)}"</div>` : '')}
      <div style="font-size:11.5px; color:var(--text-dim); margin-bottom:8px;">${escapeHtml(iss.explanation)}</div>
      <div style="display:flex; gap:6px; flex-wrap:wrap;">
        <button type="button" class="add-btn" data-tr-approve="${iss.id}" ${!iss.suggestedText?'disabled':''}>אשר תיקון</button>
        <button type="button" class="del-panel-btn" data-tr-reject="${iss.id}">דחה</button>
        <button type="button" class="del-panel-btn" data-tr-edit="${iss.id}">ערוך ידנית</button>
        <button type="button" class="del-panel-btn" data-tr-dict="${iss.id}">הוסף למילון</button>
        ${iss.fieldId ? `<button type="button" class="del-panel-btn" data-tr-goto="${iss.fieldId}">עבור לשדה בדוח</button>` : ''}
        ${identicalCount > 0 ? `<button type="button" class="del-panel-btn" data-tr-approve-identical="${iss.id}">אשר את כל ${identicalCount+1} המופעים הזהים</button>` : ''}
      </div>
    </div>`;
  }).join('') : `<p style="text-align:center; color:var(--text-dim);">אין הערות בסינון הנוכחי.</p>`;

  const bodyHtml = summaryHtml + contradictionsHtml + `<div style="margin-top:12px;">${issuesHtml}</div>` +
    (allIssues.some(i=>i.status==='approved') ? `<button type="button" class="add-panel-card" id="btnApplyApprovedCorrections">✓ החל את כל התיקונים שאושרו</button>` : '') +
    `<button type="button" class="add-btn" id="btnRerunReview" style="margin-top:8px;">🔁 בדוק שוב את כל הדוח</button>`;

  document.getElementById('textReviewBody').innerHTML = bodyHtml;
  document.getElementById('textReviewModal').classList.add('show');
  attachTextReviewHandlers(filterKey);
}

function attachTextReviewHandlers(filterKey){
  filterKey = filterKey || 'all';
  document.querySelectorAll('[data-tr-approve]').forEach(btn=>btn.addEventListener('click', ()=>{
    const iss = textReview.issues.find(i=>i.id===btn.getAttribute('data-tr-approve'));
    if(iss) iss.status = 'approved';
    renderTextReviewDialog(filterKey);
  }));
  document.querySelectorAll('[data-tr-reject]').forEach(btn=>btn.addEventListener('click', ()=>{
    const iss = textReview.issues.find(i=>i.id===btn.getAttribute('data-tr-reject'));
    if(iss) iss.status = 'rejected';
    renderTextReviewDialog(filterKey);
  }));
  document.querySelectorAll('[data-tr-edit]').forEach(btn=>btn.addEventListener('click', ()=>{
    const iss = textReview.issues.find(i=>i.id===btn.getAttribute('data-tr-edit'));
    if(!iss) return;
    const edited = prompt('ערוך את הניסוח המוצע:', iss.suggestedText || iss.originalText);
    if(edited !== null){ iss.suggestedText = edited; iss.status = 'approved'; }
    renderTextReviewDialog(filterKey);
  }));
  document.querySelectorAll('[data-tr-dict]').forEach(btn=>btn.addEventListener('click', ()=>{
    const iss = textReview.issues.find(i=>i.id===btn.getAttribute('data-tr-dict'));
    if(!iss) return;
    addWordToProfessionalDictionary(iss.wrongWord || iss.problemText || iss.originalText);
    iss.status = 'rejected';
    renderTextReviewDialog(filterKey);
    showToast('נוסף למילון המקצועי');
  }));
  document.querySelectorAll('[data-tr-goto]').forEach(btn=>btn.addEventListener('click', ()=>{
    focusReportField(btn.getAttribute('data-tr-goto'));
  }));
  document.querySelectorAll('[data-tr-approve-identical]').forEach(btn=>btn.addEventListener('click', ()=>{
    const iss = textReview.issues.find(i=>i.id===btn.getAttribute('data-tr-approve-identical'));
    if(!iss) return;
    let count = 0;
    textReview.issues.forEach(o=>{
      if(o.status==='pending' && o.problemText && o.problemText===iss.problemText && o.suggestedText===iss.suggestedText){
        o.status = 'approved'; count++;
      }
    });
    renderTextReviewDialog(filterKey);
    showToast(`אושרו ${count} מופעים זהים.`);
  }));
  document.querySelectorAll('[data-tr-clarify-send]').forEach(btn=>btn.addEventListener('click', async ()=>{
    const issId = btn.getAttribute('data-tr-clarify-send');
    const iss = textReview.issues.find(i=>i.id===issId);
    const textarea = document.querySelector(`[data-tr-clarify-input="${issId}"]`);
    if(!iss || !textarea) return;
    const clarification = textarea.value.trim();
    if(!clarification){ showToast('נא לכתוב הסבר לפני השליחה.'); return; }
    const hasApiKey = cloudAiSettings.configured;
    if(!hasApiKey){ showToast('לא הוגדר מפתח API — לא ניתן לשלוח לבדיקה חוזרת.'); return; }
    showToast('שולח לבדיקה חוזרת עם ההבהרה...');
    try{
      const clarifiedField = { fieldId: iss.fieldId, sectionName: iss.sectionName, fieldName: iss.fieldName,
        text: `${iss.originalText}\n[הבהרת הבודק לגבי הכוונה: ${clarification}]` };
      const results = await runAiTextReviewBatch([clarifiedField]);
      if(results.length && results[0].suggestedText){
        iss.suggestedText = results[0].suggestedText;
        iss.explanation = results[0].explanation;
        iss.requiresClarification = false;
        iss.issueType = results[0].issueType;
      } else {
        iss.explanation = 'גם לאחר ההבהרה לא התקבל נוסח סופי — ניתן לערוך ידנית.';
      }
    }catch(e){
      showToast('שגיאה בבדיקה החוזרת: ' + e.message);
    }
    renderTextReviewDialog(filterKey);
  }));
  const filterSelect = document.getElementById('trFilterSelect');
  if(filterSelect) filterSelect.addEventListener('change', ()=>{
    renderTextReviewDialog(filterSelect.value);
  });
  const btnRerun = document.getElementById('btnRerunReview');
  if(btnRerun) btnRerun.addEventListener('click', ()=>{
    document.getElementById('textReviewModal').classList.remove('show');
    reviewEntireReport();
  });
  const btnApply = document.getElementById('btnApplyApprovedCorrections');
  if(btnApply) btnApply.addEventListener('click', applyApprovedCorrections);
}

async function addWordToProfessionalDictionary(word){
  const trimmed = (word||'').trim();
  if(!trimmed || professionalDictionary.includes(trimmed)) return;
  professionalDictionary.push(trimmed);
  try{ await storageAPI.set('professional-dictionary', JSON.stringify(professionalDictionary), false); }catch(e){ /* ignore */ }
}

function applyApprovedCorrections(){
  const approvedIssues = textReview.issues.filter(i=>i.status==='approved' && i.fieldId && i.suggestedText);
  if(!approvedIssues.length){ showToast('אין תיקונים מאושרים להחלה.'); return; }
  const revisions = [];
  approvedIssues.forEach(iss=>{
    const currentValue = getDeep(state, iss.fieldId);
    revisions.push({ fieldId: iss.fieldId, originalText: currentValue, correctedText: iss.suggestedText, approvedAt: new Date().toISOString(), correctionType: iss.issueType });
    setDeep(state, iss.fieldId, iss.suggestedText);
  });
  textReview.revisionHistory = (textReview.revisionHistory || []).concat(revisions);
  scheduleSave();
  document.getElementById('textReviewModal').classList.remove('show');
  document.getElementById('btnUndoTextReview').style.display = 'inline-block';
  render();
  showToast('התיקונים שאושרו הוחלו בהצלחה.');
}

function undoLastTextCorrections(){
  const history = textReview.revisionHistory || [];
  if(!history.length){ showToast('אין תיקוני כתיב להחזרה.'); return; }
  history.forEach(rev=>{
    setDeep(state, rev.fieldId, rev.originalText);
  });
  textReview.revisionHistory = [];
  scheduleSave();
  document.getElementById('btnUndoTextReview').style.display = 'none';
  render();
  showToast('תיקוני הכתיב האחרונים בוטלו.');
}

async function generateSoilAIAnalysis(){
  const st = state.soilTest;
  const locs = (st.resistivityData||[]).filter(l=>l.name || l.northSouth.some(v=>v) || l.eastWest.some(v=>v));
  if(!locs.length) throw new Error('אין עדיין נתוני התנגדות סגולית שהוזנו — יש למלא לפחות מיקום מדידה אחד בסעיף "תוצאות המדידה" לפני הניתוח.');

  const dataSummary = locs.map(loc => {
    const ns = RESISTIVITY_DISTANCES.map((d,i)=>`d=${d}m: ${loc.northSouth[i]||'-'}`).join(', ');
    const ew = RESISTIVITY_DISTANCES.map((d,i)=>`d=${d}m: ${loc.eastWest[i]||'-'}`).join(', ');
    return `מיקום ${loc.name || '(ללא שם)'}:\n  צפון-דרום: ${ns}\n  מזרח-מערב: ${ew}`;
  }).join('\n');

  const env = st.environment;
  const prompt = `אתה מהנדס חשמל בכיר המתמחה בבדיקות התנגדות סגולית של קרקע (שיטת Wenner) לתכנון מערכות הארקה במתקני חשמל.

נתוני המדידה (יחידות Ω·מ', מרחק במטרים):
${dataSummary}

תנאי סביבה: טמפ' קרקע ${env.soilTemp||'לא צוין'}°C, טמפ' אוויר ${env.airTemp||'לא צוין'}°C, לחות ${env.humidity||'לא צוין'}%, מצב קרקע: ${env.soilCondition||'לא צוין'}.

כתוב תשובה בעברית מקצועית ותמציתית, בסגנון דוח הנדסי, בשלושה חלקים:
1. ניתוח הנדסי של המגמות בנתונים (2-4 משפטים) — למשל שינויים בהתנגדות עם העומק, הבדלים בין הכיוונים.
2. מסקנות לגבי התאמת הקרקע להקמת מערכת הארקה (2-3 משפטים).
3. המלצות מעשיות לתכנון מערכת ההארקה (3-5 נקודות, כל נקודה משפט קצר).

החזר את התשובה בדיוק בפורמט הבא — שלוש כותרות, כל אחת בשורה נפרדת, ואחריה הטקסט (בלי JSON, בלי Markdown, בלי טקסט נוסף לפני או אחרי):
###ניתוח###
(הניתוח ההנדסי)
###מסקנות###
(המסקנות)
###המלצות###
(ההמלצות — כל המלצה בשורה נפרדת)`;

  // v2.2.529 — קודם התשובה התבקשה כ-JSON: גרשיים בעברית (מ"מ, תשי"ד) וקיטוע ב-1000 טוקנים גרמו
  // לשגיאה "Unterminated string in JSON". עכשיו: כותרות מסומנות + יותר טוקנים + פענוח סלחני.
  const raw = await callClaudeApi(prompt, 3000);
  const parsed = parseAiTaggedSections(raw, { analysis: 'ניתוח', conclusions: 'מסקנות', recommendations: 'המלצות' });
  if(!parsed.analysis && !parsed.conclusions && !parsed.recommendations){
    throw new Error('התשובה מה-AI לא הייתה בפורמט הצפוי — נסה שוב');
  }
  return parsed;
}
// פענוח תשובת AI עם כותרות ###שם### — עמיד לגרשיים, למירכאות ולקיטוע. גיבוי: JSON אם המודל החזיר JSON בכל זאת.
function parseAiTaggedSections(raw, keys){
  const text = String(raw || '').replace(/```[a-z]*|```/gi, '').trim();
  const esc = t => String(t).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const names = Object.entries(keys);
  const marks = [];
  names.forEach(([k, label]) => { const m = text.match(new RegExp('#{2,}\\s*' + esc(label) + '\\s*#{2,}')); if(m) marks.push({ k, start: m.index, end: m.index + m[0].length }); });
  marks.sort((a, b) => a.start - b.start);
  const out = {};
  marks.forEach((m, i) => { out[m.k] = text.slice(m.end, i + 1 < marks.length ? marks[i + 1].start : text.length).trim(); });
  if(!marks.length){
    try{ const j = extractJsonFromAiResponse(text); names.forEach(([k]) => { if(j && j[k]) out[k] = String(j[k]); }); }catch(e){}
  }
  return out;
}

async function translateSoilTextsToEnglish(){
  const st = state.soilTest;
  const fields = {
    purposeNotes: st.purpose.notes,
    methodNotes: st.methodNotes,
    engineeringAnalysis: st.engineeringAnalysis,
    conclusions: st.conclusions,
    recommendations: st.recommendations
  };
  const nonEmpty = Object.entries(fields).filter(([,v])=>v && v.trim());
  if(!nonEmpty.length) throw new Error('אין עדיין טקסט חופשי למלא (הערות מטרה, שיטת מדידה, ניתוח, מסקנות, או המלצות) — יש למלא לפחות שדה אחד לפני התרגום.');

  const prompt = `תרגם לאנגלית מקצועית, בסגנון דוח הנדסי, את הטקסטים הבאים. שמור על המשמעות המדויקת, בלי להוסיף או להשמיט מידע.
${nonEmpty.map(([k,v])=>`[${k}]: ${v}`).join('\n\n')}

החזר את התרגום בדיוק בפורמט הבא — לכל מפתח כותרת בשורה נפרדת ###שם_המפתח### ואחריה התרגום (בלי JSON ובלי טקסט נוסף). המפתחות: ${nonEmpty.map(([k])=>k).join(', ')}`;

  const raw = await callClaudeApi(prompt, 4000);
  const keys = {}; nonEmpty.forEach(([k]) => { keys[k] = k; });
  const parsed = parseAiTaggedSections(raw, keys);
  if(!Object.keys(parsed).length) throw new Error('התשובה מה-AI לא הייתה בפורמט הצפוי — נסה שוב');
  return parsed;
}

