function soilFreeText(key, heValue){
  if(state.settings.reportLanguage === 'en'){
    return (state.soilTest.translatedEn && state.soilTest.translatedEn[key]) || heValue;
  }
  return heValue;
}

function buildEvDcProtectionReportBlocks(ps){
  const blocks = [];
  const sel = ps.selectedProtectionTypes || [];
  const methodLabel = (EV_DC_PROTECTION_METHOD_OPTIONS.find(o=>o.value===ps.protectionMethod)||{}).label || (ps.protectionMethod==='other' ? ps.protectionMethodOther : '');
  const typesLabel = sel.map(k=>{
    if(k==='other') return ps.protectionTypesOther || 'אחר';
    return (EV_DC_PROTECTION_TYPE_OPTIONS.find(o=>o.value===k)||{}).label || k;
  }).join(', ');

  const sb = ps.supplyBreaker, ub = ps.upstreamBreaker;
  const mainRows = [
    ['שיטת ההגנה בפני חשמול', methodLabel],
    ['אמצעי הגנה בפני זרם זליגה', typesLabel],
    ['מפסק ההזנה', [sb.manufacturer, sb.model].filter(Boolean).join(' — ')],
    ['זרם נקוב In (מפסק הזנה)', sb.In ? formatMeasurement(sb.In, sb.InUnit) : ''],
    ['מפסק מגן במעלה הזינה', [ub.manufacturer, ub.model].filter(Boolean).join(' — ')],
    ['סוג מפסק מגן', ub.breakerType],
    ['IΔn (מפסק מגן)', ub.iDeltaN ? formatMeasurement(ub.iDeltaN, ub.iDeltaNUnit) : ''],
    ['הערות כלליות', ps.generalNotes]
  ].filter(r=>r[1]);
  let mainHtml = `<h2>מפסקים, הגנות ושיטת ההגנה בפני חשמול</h2>`;
  if(mainRows.length) mainHtml += `<table class="tinfo-table">${mainRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  const protActiveList = ['L','S','I','G'].map(k=>{
    const p = sb['prot'+k];
    if(!p.active) return '';
    return `<tr><td class="tinfo-label">הגנת ${k}</td><td>${p.value?formatMeasurement(p.value,p.unit):''}${p.delay?' | השהיה: '+formatMeasurement(p.delay,p.delayUnit):''}</td></tr>`;
  }).filter(Boolean).join('');
  if(protActiveList) mainHtml += `<table class="tinfo-table">${protActiveList}</table>`;
  blocks.push({level:1, sectionKey:'ev-protection', title:'מפסקים, הגנות ושיטת ההגנה בפני חשמול', html:mainHtml});

  const rcdRelevant = ['rcd','rccb','rcbo','typeAC','typeA','typeF','typeB','typeBplus','ev'].some(k=>sel.includes(k));
  if(rcdRelevant){
    const rt = ps.rcdTest;
    const rows = rt.rows.map(r=>`<tr>
      <td>${escapeHtml(r.phase)}</td><td>${escapeHtml(r.angle)}</td><td>${escapeHtml(r.multiplier)}</td>
      <td>${r.testCurrent?formatMeasurement(r.testCurrent,r.testCurrentUnit):''}</td>
      <td>${r.tripTime?formatMeasurement(r.tripTime,r.tripTimeUnit):''}</td>
      <td>${resultCheckmarkHtml(r.result)}</td><td>${escapeHtml(r.notes)}</td>
    </tr>`).join('');
    let html = `<h2>בדיקת ממסר פחת</h2><table class="tinfo-table">
      <tr><td class="tinfo-label">יצרן / דגם</td><td>${escapeHtml([rt.manufacturer,rt.model].filter(Boolean).join(' — '))}</td></tr>
      <tr><td class="tinfo-label">IΔn</td><td>${rt.iDeltaN?formatMeasurement(rt.iDeltaN,rt.iDeltaNUnit):''}</td></tr>
    </table>`;
    if(rows) html += `<table><thead><tr><th>פאזה</th><th>זווית</th><th>מכפיל</th><th>זרם בדיקה</th><th>זמן ניתוק</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
    blocks.push({level:1, sectionKey:'ev-rcd-test', title:'בדיקת ממסר פחת', html});
  }

  const rdcDdRelevant = sel.includes('rdcDdInternal') || sel.includes('rdcDdExternal');
  if(rdcDdRelevant){
    const rd = ps.rdcDdTest;
    const rows = rd.rows.map(r=>`<tr>
      <td>${escapeHtml(r.setLeakage)}</td><td>${escapeHtml(r.multiplier)}</td>
      <td>${r.actualInjected?formatMeasurement(r.actualInjected,r.actualInjectedUnit):''}</td>
      <td>${r.responseTime?formatMeasurement(r.responseTime,r.responseTimeUnit):''}</td>
      <td>${escapeHtml(r.tripAction)}</td><td>${escapeHtml(r.alarmAction)}</td>
      <td>${resultCheckmarkHtml(r.result)}</td><td>${escapeHtml(r.notes)}</td>
    </tr>`).join('');
    let html = `<h2>בדיקת RDC-DD והגנת זליגה DC</h2><table class="tinfo-table">
      <tr><td class="tinfo-label">יצרן / דגם</td><td>${escapeHtml([rd.manufacturer,rd.model].filter(Boolean).join(' — '))}</td></tr>
    </table>`;
    if(rows) html += `<table><thead><tr><th>זרם דלף מוגדר</th><th>מכפיל</th><th>זרם מוזרק</th><th>זמן תגובה</th><th>ניתוק</th><th>התרעה</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
    blocks.push({level:1, sectionKey:'ev-rdcdd-test', title:'בדיקת RDC-DD', html});
  }

  const residualRelayRelevant = sel.includes('residualRelay');
  if(residualRelayRelevant){
    const rr = ps.residualRelayTest;
    const rows = rr.rows.map(r=>`<tr>
      <td>${escapeHtml(r.testNumber)}</td>
      <td>${r.injectedCurrent?formatMeasurement(r.injectedCurrent,r.injectedCurrentUnit):''}</td>
      <td>${r.activationTime?formatMeasurement(r.activationTime,r.activationTimeUnit):''}</td>
      <td>${resultCheckmarkHtml(r.result)}</td><td>${escapeHtml(r.notes)}</td>
    </tr>`).join('');
    let html = `<h2>בדיקת ממסר זליגה עם שנאי מסכם</h2><table class="tinfo-table">
      <tr><td class="tinfo-label">ממסר — יצרן / דגם</td><td>${escapeHtml([rr.relayManufacturer,rr.relayModel].filter(Boolean).join(' — '))}</td></tr>
      <tr><td class="tinfo-label">שנאי מסכם — יצרן / דגם</td><td>${escapeHtml([rr.transformerManufacturer,rr.transformerModel].filter(Boolean).join(' — '))}</td></tr>
    </table>`;
    if(rows) html += `<table><thead><tr><th>מס' בדיקה</th><th>זרם מוזרק</th><th>זמן הפעלה</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
    blocks.push({level:1, sectionKey:'ev-relay-test', title:'בדיקת ממסר זליגה', html});
  }

  const itRelevant = ps.protectionMethod === 'it' || sel.includes('itMonitor');
  if(itRelevant){
    const it = ps.itMonitorTest;
    const rows = it.rows.map(r=>`<tr>
      <td>${escapeHtml(r.testType)}</td>
      <td>${r.injectedResistance?formatMeasurement(r.injectedResistance,r.injectedResistanceUnit):''}</td>
      <td>${r.responseTime?formatMeasurement(r.responseTime,r.responseTimeUnit):''}</td>
      <td>${resultCheckmarkHtml(r.result)}</td><td>${escapeHtml(r.notes)}</td>
    </tr>`).join('');
    let html = `<h2>בדיקת משגוח בידוד במערכת IT</h2><table class="tinfo-table">
      <tr><td class="tinfo-label">יצרן / דגם</td><td>${escapeHtml([it.manufacturer,it.model].filter(Boolean).join(' — '))}</td></tr>
      <tr><td class="tinfo-label">סוג מערכת</td><td>${escapeHtml(it.systemType)}</td></tr>
    </table>`;
    if(rows) html += `<table><thead><tr><th>סוג בדיקה</th><th>התנגדות שהוזרקה</th><th>זמן תגובה</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
    blocks.push({level:1, sectionKey:'ev-it-test', title:'בדיקת משגוח בידוד IT', html});
  }

  blocks.push({level:1, sectionKey:'ev-protection-summary', title:'סיכום פרק ההגנות', html: computeEvDcProtectionSummaryHtml(ps, rcdRelevant, rdcDdRelevant, residualRelayRelevant, itRelevant)});

  return blocks;
}

function buildLightningReportBlocks(photoCounter){
  const lr = state.lightningProtectionInspectionReport;
  const blocks = [];
  const rd = lr.reportDetails;

  const rdInstrumentsText = rd.instrumentIds
    .map(id=>equipmentList.find(e=>e.id===id))
    .filter(Boolean)
    .map(eq=>[eq.name, eq.model, eq.serialNo].filter(Boolean).join(' – '))
    .join('; ');
  const rdRows = [
    ['מבצע הבדיקה', rd.inspectorName], ['מספר רישיון', rd.licenseNo],
    ['סוג רישיון', rd.licenseType]
  ].filter(r=>r[1]);
  if(rdRows.length || rd.notes){
    let html = `<h2>פרטי בדיקה נוספים</h2>`;
    if(rdRows.length) html += `<table class="tinfo-table">${rdRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    if(rd.notes) html += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(rd.notes)}</p>`;
    blocks.push({level:1, sectionKey:'lp-reportdetails', title:'פרטי בדיקה נוספים', html});
  }

  const ts = lr.touchStepTests;
  if(ts.enabled && ts.items.length){
    const rows = ts.items.filter(it=>it.location || it.touchVoltage || it.stepVoltage).map(it=>{
      const eq = equipmentList.find(e=>e.id===it.instrumentId);
      return `<tr>
        <td>${escapeHtml(it.location)}</td>
        <td>${it.touchVoltage ? escapeHtml(it.touchVoltage)+' '+it.unit : '—'}</td>
        <td>${it.stepVoltage ? escapeHtml(it.stepVoltage)+' '+it.unit : '—'}</td>
        <td>${eq ? escapeHtml(eq.name) : '—'}</td>
        <td>${escapeHtml(it.criterion) || '—'}</td>
        <td>${escapeHtml(it.result) || '—'}</td>
        <td>${escapeHtml(it.notes)}</td>
      </tr>`;
    }).join('');
    if(rows){
      blocks.push({level:1, sectionKey:'lp-touchstep', title:'בדיקת מתח מגע וצעד', html:`
        <h2>בדיקת מתח מגע וצעד</h2>
        <table><thead><tr><th>נקודת בדיקה</th><th>מתח מגע</th><th>מתח צעד</th><th>מכשיר</th><th>קריטריון</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>
      `});
    }
  }

  return blocks;
}

function buildMainPanelReportBlocks(){
  const mp = state.mainPanelReport;
  const blocks = [];

  // מסדר מתח גבוה ראשי — הועתק במדויק מלוגיקת ההדפסה של דוח SMA, לפי בקשה מפורשת. מודפס
  // ראשון (02), לפני לוח מתח גבוה (03) — תואם להחלפת הסדר בממשק העריכה, לפי בקשה נוספת.
  const msTable = printMainSwitchgearChecklistTable(MAIN_SWITCHGEAR_CHECKLIST, mp.mainSwitchgear.checklist, 'בדיקה ויזואלית — מסדר');
  const relevantPanelRows = mp.mainSwitchgear.panelRows.filter(r=>r.panelName || r.cellNo || r.cellName || r.switchgearSerialNo || r.protections);
  const ad = mp.mainSwitchgear.assemblyDetails;
  const adRows = [
    ['שם המסדר', ad.name], ['יצרן', ad.manufacturer], ['דגם', ad.model], ['מספר סידורי', ad.serialNo],
    ['שנת ייצור', ad.yearOfManufacture],
    ['מתח נקוב', ad.ratedVoltage?formatMeasurement(ad.ratedVoltage,ad.ratedVoltageUnit):''],
    ['זרם נקוב', ad.ratedCurrent?formatMeasurement(ad.ratedCurrent,ad.ratedCurrentUnit):''],
    ['כושר ניתוק', ad.breakingCapacity?formatMeasurement(ad.breakingCapacity,ad.breakingCapacityUnit):''],
    ['מספר תאים', ad.numberOfCells], ['סוג בידוד', ad.insulationType],
    ['תקן', ad.standard], ['מיקום התקנה', ad.installLocation]
  ].filter(r=>r[1]);
  // שלוש חלוניות משנה זרם ברמת המסדר עצמו — לפי בקשה מפורשת, החליפו את "דרגת הגנה IP" שהוסרה.
  const mCt = ad.measurementCT, pCt = ad.protectionCT, sCt = ad.summaryCT;
  const measurementCTRows = [['סוג',mCt.type],['דגם',mCt.model],['הספק (VA)',mCt.va],['ALF',mCt.alf],['CLASS',mCt.cls],['יחס זרם',mCt.ratio]].filter(r=>r[1]);
  const protectionCTRows = [['יצרן',pCt.manufacturer],['דגם',pCt.model],['מספר סידורי',pCt.serialNo],['זרם משני (A)',pCt.secondaryCurrent],['עמידות פסי צבירה בזרם קצר',pCt.busbarWithstand]].filter(r=>r[1]);
  const summaryCTRows = [['סוג',sCt.type],['דגם',sCt.model],['הספק (VA)',sCt.va],['ALF',sCt.alf],['יחס זרם',sCt.ratio]].filter(r=>r[1]);
  if(adRows.length || ad.notes || measurementCTRows.length || protectionCTRows.length || summaryCTRows.length){
    let h = '';
    if(adRows.length) h += printCompact2ColTable(adRows, 'פרטי מסדר מתח גבוה');
    if(ad.notes) h += `<p style="font-size:12px;"><b>הערות למסדר:</b> ${escapeHtml(ad.notes)}</p>`;
    if(measurementCTRows.length) h += printCompact2ColTable(measurementCTRows, 'משנה זרם מדידה');
    if(protectionCTRows.length) h += printCompact2ColTable(protectionCTRows, 'משנה זרם הגנה');
    if(summaryCTRows.length) h += printCompact2ColTable(summaryCTRows, 'משנה זרם מסכם');
    blocks.push({level:1, sectionKey:'mp-mainSwitchgear', title:'מסדר מתח גבוה', html:`<h2>מסדר מתח גבוה</h2>${h}`});
  }
  // הצ'קליסט הארוך (עם הכותרת שלו כשורה בתוך ה-thead) מקבל בלוק נפרד משלו, עם pageBreak:true
  // עצמאי — כדי שהוא תמיד יתחיל בעמוד חדש משלו, בלי קשר לכמות התוכן שקדם לו (פרטי מסדר + 3
  // חלוניות CT). לפני זה, הכל היה בלוק אחד ארוך; אם התוכן שקדם לצ'קליסט מילא כמעט עמוד שלם,
  // הכותרת של הצ'קליסט הייתה עלולה להישאר לבד בתחתית העמוד, עם הנתונים בעמוד הבא — באג אמיתי
  // שדווח ואומת ישירות.
  if(msTable || mp.mainSwitchgear.cabinetDetails || mp.mainSwitchgear.notes){
    let h2 = '';
    if(msTable) h2 += msTable;
    if(mp.mainSwitchgear.cabinetDetails) h2 += `<p style="font-size:12px;"><b>פרטי תאים וציוד:</b> ${escapeHtml(mp.mainSwitchgear.cabinetDetails)}</p>`;
    if(mp.mainSwitchgear.notes) h2 += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(mp.mainSwitchgear.notes)}</p>`;
    blocks.push({level:1, sectionKey:'mp-mainSwitchgear-checklist', title:'מסדר מתח גבוה — בדיקה ויזואלית', html:h2});
  }

  // תאי מתח גבוה — הועתק במדויק מלוגיקת ההדפסה של דוח SMA, לפי בקשה מפורשת (חלק מסעיף 02).
  // מוקם כאן, מיד אחרי בלוק המסדר ולפני הלוחות (סעיף 03), תואם לסדר החדש בממשק העריכה (הועבר
  // מתוך סעיף 03 לתוך סעיף 02 לפי בקשה מפורשת).
  const relevantHvCells = mp.hvCells.filter(c=>c.cellType || c.cellName || c.manufacturer || c.serialNo);
  if(relevantHvCells.length){
    const cellBlocks = relevantHvCells.map((c,i)=>{
      const rows = [
        ['סוג תא', c.cellType], ['שם התא', c.cellName], ['מספר תא', c.cellNumber],
        ['יצרן', c.manufacturer], ['דגם', c.model], ['מספר סידורי', c.serialNo], ['שנת ייצור', c.yearOfManufacture],
        ['מתח נקוב', c.ratedVoltage?formatMeasurement(c.ratedVoltage,c.ratedVoltageUnit):''],
        ['זרם נקוב', c.ratedCurrent?formatMeasurement(c.ratedCurrent,c.ratedCurrentUnit):''],
        ['כושר ניתוק', c.breakingCapacity?formatMeasurement(c.breakingCapacity,c.breakingCapacityUnit):''],
        ['סוג בידוד', c.insulationType], ['סוג מפסק', c.breakerType], ['סוג מנתק', c.disconnectorType],
        ['סוג הארקה', c.groundingType], ['ממסר הגנה', c.protectionRelay], ['CT', c.ct], ['VT', c.vt]
      ].filter(r=>r[1]);
      let html = '';
      if(rows.length) html += printCellTable(rows, `תא ${i+1}${c.cellName?' — '+c.cellName:''}`);
      else html += `<div class="mp-facility-header">תא ${i+1}${c.cellName?' — '+escapeHtml(c.cellName):''}</div>`;
      if(c.description) html += `<p style="font-size:12px;"><b>תיאור:</b> ${escapeHtml(c.description)}</p>`;
      if(c.notes) html += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(c.notes)}</p>`;
      // break-inside:avoid — לא לפצל טבלת תא בין שני עמודים ב-PDF, אותה דרישה כמו ב-SMA.
      return `<div style="break-inside:avoid; page-break-inside:avoid;">${html}</div>`;
    });
    // רשת שתי עמודות RTL (תא 1 מימין). כל זוג תאים = בלוק נפרד (v2.2.546), כך שזוג ראשון נכנס בעמוד הנוכחי
    // במקום שכל התאים יקפצו יחד לעמוד הבא וישאירו עמוד ריק.
    for(let x = 0; x < cellBlocks.length; x += 2){
      const grid = `<div style="display:grid; grid-template-columns:repeat(2, minmax(0, 1fr)); gap:10px 14px; align-items:start; margin-bottom:10px;">${cellBlocks.slice(x, x+2).join('')}</div>`;
      blocks.push({level:1, sectionKey: x === 0 ? 'mp-hvCells' : 'mp-hvCells-' + x, title: x === 0 ? 'תאי מתח גבוה' : 'תאי מתח גבוה (המשך)', html: (x === 0 ? `<h2>תאי מתח גבוה</h2>` : '') + grid});
    }
  }

  // בדיקות בידוד — לפי בקשה מפורשת, ממוקם בתוך סעיף 02 (לא סעיף נפרד יותר), מיד אחרי תאי מתח
  // גבוה ולפני הלוחות — תואם לסדר החדש בממשק העריכה.
  const insulationTableHtml = printInsulationTable(mp.insulationTests, 'בדיקות בידוד');
  if(insulationTableHtml){
    blocks.push({level:1, sectionKey:'mp-insulation-tests', title:'בדיקות בידוד', html:insulationTableHtml});
  }

  // סעיף "לוחות מתח גבוה" (facilities) הוסר לגמרי מהדוח — גם מהעריכה וגם מה-PDF — לפי
  // בקשה מפורשת. mp.facilities עדיין קיים ב-state (עם לוח ברירת מחדל, לא מוצג בשום מקום),
  // אך אין יותר בלוק PDF לכל לוח בנפרד.

  if(mp.summaryItems.length && mp.summaryItems.some(s=>s.text && s.text.trim())){
    blocks.push({level:1, sectionKey:'mp-summary-print', title:'ממצאים מסכמים', html:
      `<h2>ממצאים מסכמים</h2>${mp.summaryItems.filter(s=>s.text&&s.text.trim()).map(s=>`<p style="font-size:12px; margin:4px 0;"><b>${s.number}.</b> ${escapeHtml(s.text)}</p>`).join('')}`});
  }

  return blocks;
}

// *** תמונות-לפי-סעיף (דוח גמיש) — Reuse ישיר של printPhotos הקיימת (לא שכפול קוד):
// עכשיו כש-buildPhotoDocumentationGrid המשותפת מזינה את הנתונים כאן, sectionPhotos
// משתמשת באותה צורה בדיוק כמו generalPhotos (notes[] מערך, לא note יחיד) — אז אותה
// פונקציית PDF בדיוק, אותן מחלקות CSS (photo-report-grid/photo-box, break-inside:avoid),
// אותו מספור "N.M". מספור מתחיל מ-1 לכל סעיף (לא רץ גלובלי על כל הדוח) — תואם בדיוק את
// מספור "תמונה 1/2/3" שכבר מוצג בעורך לאותו סעיף.
function printSectionPhotos(photos, sectionTitle){
  if(!photos || !photos.length) return '';
  // *** כותרת "תמונות – [שם הסעיף]" מחושבת כאן מתוך sec.title בזמן בניית ה-PDF עצמה —
  // לא שדה שמור בנפרד — לכן שינוי כותרת הסעיף תמיד מתעדכן אוטומטית, בלי סנכרון ידני.
  return `<h3 style="font-size:13px; margin:14px 0 8px;">תמונות – ${escapeHtml(sectionTitle)}</h3>${printPhotos(photos, 1)}`;
}

function buildFlexibleReportBlocks(){
  const fr = state.flexibleReport;
  const blocks = [];

  // הנדון — שדה ייעודי, מודפס לפני הפרקים (item 2, 17)
  if(fr.subject && fr.subject.trim()){
    blocks.push({level:1, sectionKey:'flex-subject', title:'הנדון', html:`<p style="font-size:12.5px; white-space:pre-wrap; margin:0 0 14px;"><b>הנדון:</b> ${escapeHtml(fr.subject)}</p>`});
  }

  // הפרקים שנבחרו, לפי הסדר שנקבע — אותו סדר גם ב-PDF (item 7, 17)
  flexNormalizeOrder(fr);
  const sortedSections = fr.sections.slice().sort((a,b)=>a.order-b.order);
  // ריכוז לוחות (טופס 3) — טבלה אחת לכל הלוחות לפני הפירוט, כשיש נתוני גילוי / ניתוק / כיבוי
  if(fr.reportType === 'PANEL_MAINTENANCE'){
    const fireSecs = sortedSections.filter(x => isFlexPanelSection(x) && x.fire && (x.fire.location || x.fire.connection || FIRE_FIELDS.some(([k])=>x.fire[k])));
    if(fireSecs.length){
      const mk = v => v==='ok' ? '<span style="color:#1b7f2a; font-weight:800;">✓</span>' : (v==='bad' ? '<span style="color:#c62828; font-weight:800;">✗</span>' : (v==='na' ? '<span style="color:#666;">ל״ר</span>' : ''));
      blocks.push({ level:1, sectionKey:'flex-form3-summary', title:'ריכוז לוחות — גילוי, ניתוק וכיבוי', html:`<h2>ריכוז לוחות — גילוי, ניתוק וכיבוי (טופס 3)</h2>
        <table><thead><tr><th>מס'</th><th>מיקום</th><th>שם הלוח</th><th>גודל חיבור</th>${FIRE_FIELDS.map(([,l])=>`<th>${l}</th>`).join('')}</tr></thead><tbody>
        ${fireSecs.map((x, i)=>`<tr><td>${i+1}</td><td>${escapeHtml(x.fire.location||'')}</td><td>${escapeHtml(x.title)}</td><td><bdi dir="ltr">${escapeHtml(x.fire.connection||'')}</bdi></td>${FIRE_FIELDS.map(([k])=>`<td style="text-align:center;">${mk(x.fire[k])}</td>`).join('')}</tr>`).join('')}
        </tbody></table>` });
    }
  }
  sortedSections.forEach(sec => {
    let html = `<h2>${escapeHtml(sec.title)}</h2>`;
    if(fr.reportType === 'PANEL_MAINTENANCE' && isFlexPanelSection(sec) && sec.fire && (sec.fire.location || sec.fire.connection || FIRE_FIELDS.some(([k])=>sec.fire[k]))){
      const st = v => v==='ok' ? '<span style="color:#1b7f2a; font-weight:800;">✓ תקין</span>' : (v==='bad' ? '<span style="color:#c62828; font-weight:800;">✗ לא תקין</span>' : (v==='na' ? '<span style="color:#666;">ל״ר</span>' : '—'));
      html += `<table><thead><tr><th>מיקום</th><th>גודל חיבור</th>${FIRE_FIELDS.map(([,l])=>`<th>${l}</th>`).join('')}</tr></thead><tbody><tr><td>${escapeHtml(sec.fire.location||'—')}</td><td><bdi dir="ltr">${escapeHtml(sec.fire.connection||'—')}</bdi></td>${FIRE_FIELDS.map(([k])=>`<td>${st(sec.fire[k])}</td>`).join('')}</tr></tbody></table>`;
    }
    if(isFlexChecklistSection(sec) && Array.isArray(sec.checklist)){
      const rows = sec.checklist.filter(c => String(c.label||'').trim() && (c.status || String(c.value||'').trim()));
      if(rows.length){
        const st = v => v==='ok' ? '<span style="color:#1b7f2a; font-weight:800;">✓ תקין</span>' : (v==='bad' ? '<span style="color:#c62828; font-weight:800;">✗ לא תקין</span>' : (v==='na' ? '<span style="color:#666;">ל״ר</span>' : ''));
        const anyVal = rows.some(c=>String(c.value||'').trim());
        html += `<h3>צ'ק ליסט — ${escapeHtml(sec.title)}</h3><table><thead><tr><th style="width:30px;">מס'</th><th>סעיף</th>${anyVal ? '<th style="width:90px;">ערך</th>' : ''}<th style="width:80px;">תוצאה</th></tr></thead><tbody>${rows.map((c, i)=>`<tr><td>${i+1}</td><td>${escapeHtml(c.label)}</td>${anyVal ? `<td><bdi dir="ltr">${escapeHtml(c.value||'')}</bdi></td>` : ''}<td>${st(c.status)}</td></tr>`).join('')}</tbody></table>`;
      }
    }
    if(sec.type === '__table__'){
      const headers = sec.tableHeaders || [];
      const rows = (sec.tableRows || []).filter(row => row.some(c=>c && c.trim()));
      if(headers.length && rows.length){
        html += `<table><thead><tr>${headers.map(h=>`<th>${escapeHtml(h)}</th>`).join('')}</tr></thead><tbody>`;
        rows.forEach(row => { html += `<tr>${row.map(c=>`<td>${escapeHtml(c)||'—'}</td>`).join('')}</tr>`; });
        html += `</tbody></table>`;
      } else {
        html += `<p style="font-size:12px; color:#666;">הטבלה ריקה.</p>`;
      }
    } else if(sec.type === 'ממצאים' && fr.findingsMode === 'structured'){
      if(fr.findings.length){
        html += `<table><thead><tr><th>מס'</th><th>כותרת</th><th>תיאור</th><th>סטטוס</th><th>הערה</th></tr></thead><tbody>`;
        fr.findings.forEach(f=>{
          const statusColor = f.status==='תקין' ? '#2e7d32' : (f.status==='לא תקין' ? '#c62828' : (f.status ? '#b8860b' : '#666'));
          html += `<tr><td>${f.num}</td><td>${escapeHtml(f.title)}</td><td>${escapeHtml(f.description)}</td><td style="color:${statusColor}; font-weight:600;">${escapeHtml(f.status)||'—'}</td><td>${escapeHtml(f.note)||'—'}</td></tr>`;
        });
        html += `</tbody></table>`;
      } else {
        html += `<p style="font-size:12px; color:#666;">לא הוזנו ממצאים.</p>`;
      }
    } else if(sec.type === 'הערות'){
      // הערות ידניות (item 11) ואז הערות תמונות (item 10) — נקראות ישירות מהמקור, לא עותק קפוא
      const photoNotes = (state.generalPhotos||[]).flatMap((p,pi)=>(p.notes||[]).filter(n=>n&&n.trim()).map(n=>({pi,n,title:p.title})));
      let hasAny = false;
      if(fr.manualNotes && fr.manualNotes.trim()){
        html += `<p style="font-size:12px; white-space:pre-wrap;">${escapeHtml(fr.manualNotes)}</p>`;
        hasAny = true;
      }
      if(fr.includePhotoNotesInNotes && photoNotes.length){
        html += `<p style="font-size:11.5px; font-weight:700; margin-top:10px;">הערות מהתמונות:</p><ol style="font-size:12px; padding-right:20px;">`;
        photoNotes.forEach(pn => { html += `<li>תמונה מס' ${pn.pi+1}${pn.title?' — '+escapeHtml(pn.title):''} – ${escapeHtml(pn.n)}</li>`; });
        html += `</ol>`;
        hasAny = true;
      }
      if(!hasAny) html += `<p style="font-size:12px; color:#666;">אין הערות.</p>`;
    } else if(sec.itemsMode){
      const its = (sec.items || []).map(t=>String(t||'').trim()).filter(Boolean);
      const panelHasCore = /<table/.test(html); // לוח עם צ'ק ליסט / שורת טופס 3 — אין צורך ב"לא הוזן תוכן"
      html += its.length ? its.map((t, i)=>`<p style="font-size:12.5px; margin:4px 0; padding-right:24px; text-indent:-24px; white-space:pre-wrap;"><b>${i+1}.</b> ${escapeHtml(t)}</p>`).join('') : (panelHasCore ? `` : `<p style="font-size:12px; color:#666;">לא הוזן תוכן.</p>`);
    } else {
      html += (sec.content && sec.content.trim()) ? `<p style="font-size:12.5px; white-space:pre-wrap;">${escapeHtml(sec.content)}</p>` : `<p style="font-size:12px; color:#666;">לא הוזן תוכן.</p>`;
    }
    // *** תמונות הסעיף — מוצג אחרי התוכן/הממצאים/ההערות, אחיד לכל סוגי הסעיפים (לפי
    // הפריסה המדויקת שנדרשה). init הגנתי זהה לזה שב-renderFlexibleReportCards (דוח ישן
    // בלי השדה מקבל מערך ריק, לא מוצג כלום — 0 כותרת/שטח ריק, בדיוק לפי הדרישה).
    if(!Array.isArray(sec.sectionPhotos)) sec.sectionPhotos = [];
    // לוח (טופס 3 + צ'ק ליסט) = יחידה אחת שלא נחתכת בין עמודים (v2.2.549): אם נכנסת בעמוד הנוכחי — נשארת
    // (שני לוחות בעמוד כשיש מקום), אחרת כל הלוח עובר יחד לעמוד הבא. התמונות אחריו כרגיל.
    if(fr.reportType === 'PANEL_MAINTENANCE' && /<table/.test(html)){
      html = `<div class="flex-panel-unit" style="break-inside:avoid; page-break-inside:avoid; margin-bottom:6px;">${html}</div>`;
      // לוח + התמונות שלו = קבוצה אחת (v2.2.550): אם הקבוצה נכנסת בעמוד — יחד באותו עמוד (או יחד לעמוד הבא).
      // רק אם הקבוצה גבוהה מעמוד שלם — הלוח קודם והתמונות ממשיכות אחריו (ראו applyTablePreflight).
      const ph = printSectionPhotos(sec.sectionPhotos, sec.title);
      if(ph) html = `<div class="flex-panel-group">${html}<div class="flex-panel-photos">${ph}</div></div>`;
      blocks.push({level:1, sectionKey:'flex-sec-'+sec.id, title:sec.title, html});
      return;
    }
    html += printSectionPhotos(sec.sectionPhotos, sec.title);
    blocks.push({level:1, sectionKey:'flex-sec-'+sec.id, title:sec.title, html});
  });

  // חתימה — "בברכה" + שם הבודק/חברה + חתימה וחותמת, מהגדרות קיימות (item 16, 17)
  const s = state.settings;
  let sigHtml = `<p style="font-size:13px; margin-bottom:16px;">בברכה,</p>`;
  if(s.engineerName) sigHtml += `<p style="font-size:12.5px; margin:2px 0;">${escapeHtml(s.engineerName)}</p>`;
  if(s.companyName) sigHtml += `<p style="font-size:12.5px; margin:2px 0;">${escapeHtml(s.companyName)}</p>`;
  sigHtml += s.signature
    ? `<div style="margin-top:14px;"><img src="${s.signature}" style="max-width:200px; max-height:80px;" alt="חתימה וחותמת"></div>`
    : `<p style="font-size:12px; margin-top:14px;">חתימה וחותמת: ________________________</p>`;
  blocks.push({level:1, sectionKey:'flex-signature', title:'חתימה', html:sigHtml});

  return blocks;
}

function buildHvCableReportBlocks(){
  const hc = state.hvCableReport;
  const blocks = [];

  const hcSize = hvCableSizeText(hc);
  const hcExtra = (hc.extraCables || []).map(hvCableDefText).filter(Boolean);
  const detailsRows = [
    ['אזור הבדיקה', hc.testArea], [hcExtra.length ? 'כבל #1 — חומר המוליך' : 'סוג כבל (חומר המוליך)', hc.cableType],
    ['סוג בידוד', hc.insulationType], ['מתח בידוד של הכבל', hc.ratedVoltage],
    ['חתך (mm²)', hcSize]
  ].concat(hcExtra.map((t, i)=>['כבל #' + (i+2), t])).filter(r=>r[1]);
  if(detailsRows.length || hc.testAreaPhoto){
    // מידות מפורשות (מ"מ) — גובה התמונה חייב להיות ידוע מראש, אחרת חישוב שבירת העמודים (Preflight) רץ לפני
    // שהתמונה נטענה (גובה 0) ומזיז טבלאות בהמשך הדוח לעמוד הלא נכון. רוחב = 2/3 מרוחב הטקסט (~120 מ"מ).
    const hcRatio = parseFloat(hc.testAreaPhotoRatio) > 0 ? parseFloat(hc.testAreaPhotoRatio) : (4/3);
    let hcW = 120, hcH = hcW / hcRatio;
    if(hcH > 120){ hcH = 120; hcW = hcH * hcRatio; }
    const photoHtml = hc.testAreaPhoto ? `<div style="text-align:center; margin:10px 0 4px; break-inside:avoid; page-break-inside:avoid;"><img src="${escapeAttr(hc.testAreaPhoto)}" alt="אזור הבדיקה" width="${Math.round(hcW*3.78)}" height="${Math.round(hcH*3.78)}" style="width:${hcW.toFixed(1)}mm; height:${hcH.toFixed(1)}mm; object-fit:contain; border:1px solid #ccc; border-radius:4px;"><div style="font-size:11px; color:#555; margin-top:3px;">אזור הבדיקה${hc.testArea ? ': ' + escapeHtml(hc.testArea) : ''}</div></div>` : '';
    blocks.push({level:1, sectionKey:'hc-details', title:'פרטי כבל ואזור הבדיקה', html:`<h2>פרטי כבל ואזור הבדיקה</h2>${detailsRows.length ? `<table class="tinfo-table">${detailsRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${(r[0]==='חתך (mm²)' || r[0]==='מתח בידוד של הכבל' || /^כבל #\d+$/.test(r[0])) ? `<bdi dir="ltr">${escapeHtml(String(r[1]).replace(/\u200E/g,''))}</bdi>` : escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>` : ''}${photoHtml}`});
  }

  // טבלת 'מכשירי בדיקה' (סעיף 03 לשעבר) הוסרה (v2.2.494) — המכשירים מודפסים מהרשימה בסעיף 01

  const methodRows = [['מתח בדיקה בין לוח ראשי לתחנות ממירים (kV)', hc.testVoltageKV], ['משך זמן הבדיקה (שניות)', hc.testDurationSec]].filter(r=>r[1]);
  {
    let html = `<h2>אופן הבדיקה</h2>
      <p style="font-size:12px;">התבקשתי לבדוק את רמת הבידוד עבור כבלי מתח גבוה: (1) בדיקת רמת הבידוד לכל כבל. (2) בדיקת רמת הבידוד בין הארקות.</p>
      ${hvCableTestDiagramsHtml(true)}`;
    if(methodRows.length) html += `<table class="tinfo-table">${methodRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    { const Mm = hvMethods(hc); const names = HV_TEST_METHODS.filter(([k])=>Mm[k]).map(([,t])=>t);
      if(names.length) html += `<p style="font-size:12px; margin-top:6px;"><b>שיטות הבדיקה שבוצעו:</b> ${escapeHtml(names.join(' · '))}${Mm.temp && hc.ambientTempC ? ` (טמפרטורת סביבה ${escapeHtml(hc.ambientTempC)}°C, ייחוס ${escapeHtml(hc.refTempC||'20')}°C)` : ''}</p>`; }
    blocks.push({level:1, sectionKey:'hc-method', title:'אופן הבדיקה', html});
  }

  const insulationCols = [
    ['L1_E','L1-E'], ['L2_E','L2-E'], ['L3_E','L3-E'],
    ['L1_L2','L1-L2'], ['L1_L3','L1-L3'], ['L2_L3','L2-L3']
  ];
  const cablesWithData = hc.cables.filter(c => c.from || c.to || c.cableDescription || c.status || c.phaseSequenceResult || insulationCols.some(([k])=>c.insulation[k]) || Object.values(c.sheath||{}).some(Boolean));
  if(hc.stationSegmentName || cablesWithData.length){
    let html = `<h2>טבלת סיכום בדיקות כבל מתח גבוה</h2>`;
    if(hc.stationSegmentName) html += `<p style="font-size:12px;"><b>שם תחנה / קטע:</b> ${escapeHtml(hc.stationSegmentName)}</p>`;
    const tv = hc.testVoltageKV ? `מתח בדיקה: <bdi dir="ltr">${escapeHtml(hc.testVoltageKV)} kV</bdi>` : '';
    const td = hc.testDurationSec ? `זמן בדיקה: ${escapeHtml(hc.testDurationSec)} שניות` : '';
    if(tv || td) html += `<p style="font-size:11.5px; margin:2px 0 6px;">${[tv, td].filter(Boolean).join(' · ')}</p>`;
    // טבלה דינמית (v2.2.512): ערך זהה בכל הכבלים (מ־ / סוג כבל) — פעם אחת מעל הטבלה; מעט עמודות → עמוד לאורך
    const hvSame = f => { const v = cablesWithData.map(c=>String(f(c)||'').trim()); return cablesWithData.length > 1 && v[0] && v.every(x=>x===v[0]) ? v[0] : ''; };
    const hvCommonFrom = hvSame(c=>c.from), hvCommonCable = hvSame(c=>hvCableRowCableText(hc, c));
    const hvNotesAny = cablesWithData.some(c=>String(c.notes||'').trim());
    const hvColsCount = ((hvMethods(hc).standard || hvMethods(hc).temp) ? 6 : 3);
    const hvEffCols = 1 + (hvCommonFrom ? 0 : 1) + 1 + (hvCommonCable ? 0 : 1) + 1 + hvColsCount + (hvNotesAny ? 1 : 0) + 1;
    const hvLandscape = hvEffCols > 11 && !((state.reportChapters||[]).length); // בדוח משולב הכל לאורך (v2.2.546)
    const hvCaption = [hvCommonFrom ? `<b>מ־:</b> ${spBdi(hvCommonFrom)}` : '', hvCommonCable ? `<b>סוג כבל:</b> <bdi dir="ltr">${escapeHtml(hvCommonCable)}</bdi>` : ''].filter(Boolean).join(' &nbsp;·&nbsp; ');
    if(hvCaption) html += `<p style="font-size:11.5px; margin:0 0 6px;">${hvCaption}</p>`;
    html += SP_FIT_STYLE_TAG() + `<table class="sp-fit" style="font-size:10px;"><thead>
      <tr><th rowspan="2">מס'</th>${hvCommonFrom ? '' : '<th rowspan="2" class="sp-wrap">מ־</th>'}<th rowspan="2" class="sp-wrap">אל</th>${hvCommonCable ? '' : '<th rowspan="2">סוג כבל</th>'}<th rowspan="2">מקבילות / פאזות</th>
        <th colspan="3">בידוד מוליך – הארקה${(hvMethods(hc).dar || hvMethods(hc).pi) ? ' (R60)' : ''}</th>${(hvMethods(hc).standard || hvMethods(hc).temp) ? '<th colspan="3">בידוד בין המוליכים</th>' : ''}${hvNotesAny ? '<th rowspan="2" class="sp-grow">הערה</th>' : ''}<th rowspan="2">סטטוס</th></tr>
      <tr><th dir="ltr">L1-E</th><th dir="ltr">L2-E</th><th dir="ltr">L3-E</th>${(hvMethods(hc).standard || hvMethods(hc).temp) ? '<th dir="ltr">L1-L2</th><th dir="ltr">L1-L3</th><th dir="ltr">L2-L3</th>' : ''}</tr>
    </thead><tbody>`;
    const hcMp = hvMethods(hc);
    const colsP = (hcMp.standard || hcMp.temp) ? insulationCols : insulationCols.slice(0,3);
    cablesWithData.forEach((cable, ri)=>{
      const st = cable.phaseSequenceResult === 'לא תקין' ? 'לא תקין' : cable.status;
      const color = v => v==='תקין' ? '#2e7d32' : (v==='לא תקין' ? '#c62828' : '#555');
      const u = k => (cable.insUnits && cable.insUnits[k]) || cable.insulationUnit || 'GΩ';
      html += `<tr>
        <td>${ri+1}</td>
        ${hvCommonFrom ? '' : `<td class="sp-wrap">${spBdi(cable.from)||'—'}</td>`}
        <td class="sp-wrap">${spBdi(cable.to)||'—'}</td>
        ${hvCommonCable ? '' : `<td><bdi dir="ltr">${escapeHtml(hvCableRowCableText(hc, cable))||'—'}</bdi></td>`}
        <td style="color:${color(cable.phaseSequenceResult)}; font-weight:600;">${escapeHtml(cable.phaseSequenceResult)||'—'}</td>
        ${colsP.map(([key])=>`<td>${spValUnit(cable.insulation[key], u(key))}</td>`).join('')}
        ${hvNotesAny ? `<td class="sp-grow">${escapeHtml(cable.notes)||''}</td>` : ''}
        <td style="color:${color(st)}; font-weight:700;">${escapeHtml(st)||'—'}</td>
      </tr>`;
    });
    html += `</tbody></table>`;
    // --- טבלאות נוספות לפי שיטות הבדיקה שנבחרו — 2 טבלאות בכל שורה (v2.2.499), באותו עמוד רוחב ---
    const M = hvMethods(hc), U = (c, k) => (c.insUnits && c.insUnits[k]) || c.insulationUnit || 'GΩ';
    const extra = [];
    if(M.temp){
      extra.push(`<h3>ערכים מתוקנים ל-${escapeHtml(hc.refTempC||'20')}°C <span style="font-weight:400; font-size:10px;">(סביבה ${escapeHtml(hc.ambientTempC||'—')}°C · IEEE 43)</span></h3>
      <table class="sp-fit" style="font-size:9.5px;"><thead><tr><th>מס'</th><th>אל</th>${insulationCols.map(([,l])=>`<th dir="ltr">${l}</th>`).join('')}</tr></thead><tbody>
      ${cablesWithData.map((c, ri)=>`<tr><td>${ri+1}</td><td>${spBdi(c.to)||'—'}</td>${insulationCols.map(([k])=>{ const v = hvTempCorrected(hc, c.insulation[k]); return `<td><bdi dir="ltr">${isNaN(v) ? '—' : hvFmt(v) + ' ' + escapeHtml(U(c,k))}</bdi></td>`; }).join('')}</tr>`).join('')}
      </tbody></table>`);
    }
    const ratioTable = (kind) => {
      const isDar = kind === 'dar';
      let t = `<h3>${isDar ? 'DAR — R60 / R15' : 'PI — R600 / R60'} <span style="font-weight:400; font-size:10px;">${isDar ? '(תקין ≥ 1.25 · מעקב 1.0–1.25)' : '(תקין ≥ 2.0 · מעקב 1.0–2.0)'}</span></h3>
      <table class="sp-fit" style="font-size:9.5px;"><thead><tr><th rowspan="2">מס'</th><th rowspan="2">אל</th>${insulationCols.slice(0,3).map(([,l])=>`<th colspan="2" dir="ltr">${l}</th>`).join('')}</tr>
      <tr>${insulationCols.slice(0,3).map(()=> isDar ? '<th>R15</th><th>DAR</th>' : '<th>R600</th><th>PI</th>').join('')}</tr></thead><tbody>`;
      cablesWithData.forEach((c, ri)=>{
        t += `<tr><td>${ri+1}</td><td>${spBdi(c.to)||'—'}</td>`;
        insulationCols.slice(0,3).forEach(([k])=>{
          const extraVal = isDar ? (c.r15||{})[k] : (c.r600||{})[k];
          const ratio = isDar ? hvNum(c.insulation[k]) / hvNum(extraVal) : hvNum(extraVal) / hvNum(c.insulation[k]);
          const cl = classifyInsulationResult(isFinite(ratio) ? ratio : NaN, kind, true);
          t += `<td>${spValUnit(extraVal, U(c,k))}</td><td style="color:${cl.color}; font-weight:700;">${isFinite(ratio) ? ratio.toFixed(2) : '—'}</td>`;
        });
        t += `</tr>`;
      });
      return t + `</tbody></table>`;
    };
    if(M.dar) extra.push(ratioTable('dar'));
    if(M.pi) extra.push(ratioTable('pi'));
    if(M.sheath){
      const sv = hc.sheathTestVoltageKV == null ? '5' : hc.sheathTestVoltageKV, sd = hc.sheathDurationSec == null ? '60' : hc.sheathDurationSec;
      extra.push(`<h3>בידוד סיכוך (מעטה) להארקה <span style="font-weight:400; font-size:10px;">(${sv ? '<bdi dir="ltr">' + escapeHtml(sv) + ' kV DC</bdi>' : ''}${sd ? ' · ' + escapeHtml(sd) + ' שנ׳' : ''})</span></h3>
      <table class="sp-fit" style="font-size:9.5px;"><thead><tr><th>מס'</th><th>אל</th>${HV_SHEATH_COLS.map(([,l])=>`<th>${l}</th>`).join('')}</tr></thead><tbody>
      ${cablesWithData.map((c, ri)=>`<tr><td>${ri+1}</td><td>${spBdi(c.to)||'—'}</td>${HV_SHEATH_COLS.map(([k])=>`<td>${spValUnit((c.sheath||{})[k], (c.sheathUnits||{})[k] || 'MΩ')}</td>`).join('')}</tr>`).join('')}
      </tbody></table>`);
    }
    if(hvLandscape){
      for(let x = 0; x < extra.length; x += 2){
        const pair = extra.slice(x, x + 2);
        // בעמוד רוחב: 2 טבלאות בכל שורה
        html += `<div style="display:grid; grid-template-columns:1fr 1fr; gap:12px; align-items:start; margin-top:6px; break-inside:avoid; page-break-inside:avoid;">${pair.map(h=>`<div style="min-width:0;">${h}</div>`).join('')}</div>`;
      }
    } else {
      // בעמוד לאורך: טבלאות השיטות זו מתחת לזו ברוחב מלא (לא נדחסות)
      extra.forEach(h=>{ html += `<div style="margin-top:6px; break-inside:avoid; page-break-inside:avoid;">${h}</div>`; });
    }
    blocks.push({level:1, sectionKey: hvLandscape ? 'hc-summary' : 'hc-summary-portrait', title:'טבלת סיכום בדיקות כבל מתח גבוה', html});
  }

  const hvRows = [['מתח בדיקה HV (kV)', hc.hvTestVoltageKV]].filter(r=>r[1]);
  const lvRows = [['מתח בדיקה LV (V)', hc.lvTestVoltageV]].filter(r=>r[1]);
  if(hc.insulationStatus || hc.additionalNotes || hvRows.length || lvRows.length || hc.conclusion.status || hc.conclusion.freeText){
    let html = `<h2>סיכום ומסקנה</h2>`;
    if(hc.insulationStatus) html += `<p style="font-size:12.5px;"><b>בבדיקת רמת בידוד נמצא:</b> ${escapeHtml(hc.insulationStatus)}</p>`;
    if(hc.additionalNotes) html += `<p style="font-size:12px;">${escapeHtml(hc.additionalNotes)}</p>`;
    if(hvRows.length) html += `<table class="tinfo-table">${hvRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    if(lvRows.length) html += `<table class="tinfo-table">${lvRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    if(hc.conclusion.status) html += `<p style="font-size:12.5px; font-weight:700; margin-top:10px;">${escapeHtml(hc.conclusion.status)}</p>`;
    if(hc.conclusion.freeText) html += `<p style="font-size:12px;">${escapeHtml(hc.conclusion.freeText)}</p>`;
    html += `<p style="font-size:11px; margin-top:12px;">מכשירי חשמל ניידים המחוברים לבתי תקע ומכשירים אחרים המותקנים במקום ואינם חלק ממתקן החשמל הקבוע לא נבדקו.</p>
      <p style="font-size:11px;">תוקפו של הדוח נכון אך ורק ליום הבדיקה ואין הבודק אחראי לכל שינוי שלא על דעתו.</p>`;
    blocks.push({level:1, sectionKey:'hc-conclusion', title:'סיכום ומסקנה', html});
  }

  return blocks;
}

// ===== דוח בדיקת שנאי מתח גבוה — פלט הדפסה =====
function buildTransformerInspectionReportBlocks(){
  const blocks = [];
  const ti = state.transformerInspectionReport;
  // בלוק "מכשירי בדיקה" (עמוד נפרד) הוסר לגמרי — כל התוכן שלו (תיאור/מכשירים/מלווה הבדיקה)
  // עבר לטבלת עמוד השער (buildCoverPage), לפי בקשה מפורשת.

  ti.transformers.forEach((tr, tri) => {
    const title = tr.model ? `${tri+1}. שנאי — ${tr.model}` : `${tri+1}. שנאי`;
    let h = `<h2>${escapeHtml(title)}</h2>`;

    const basicRows = [
      ['מספר סידורי', tr.serialNo], ['דגם', tr.model], ['יצרן', tr.manufacturer],
      ['הספק (kVA)', tr.powerKVA], ['מתח ראשוני (kV)', tr.primaryVoltageKV], ['מתח משני (V)', tr.secondaryVoltageV],
      ['קבוצת חיבור', tr.connectionGroup], ['שנת ייצור', tr.yearOfManufacture], ['סוג שנאי', tr.transformerType],
      ['דרגת מתח קצר Uk%', tr.shortCircuitVoltagePercent]
    ].filter(r=>r[1]);
    if(basicRows.length) h += printCompact2ColTable(basicRows, 'פרטי שנאי');

    const gm = tr.groundingMethod, gp = tr.groundingProtection;
    const gmRows = [['מוליכים במקביל', gm.parallelConductors], ['חתך מוליך (ממ"ר)', gm.crossSection], ['סוג מוליך', gm.conductorType]].filter(r=>r[1]);
    if(gmRows.length) h += printCompact2ColTable(gmRows, 'הארקת שיטה');
    const gpRows = [['מוליכים במקביל', gp.parallelConductors], ['חתך מוליך (ממ"ר)', gp.crossSection], ['סוג מוליך', gp.conductorType]].filter(r=>r[1]);
    if(gpRows.length) h += printCompact2ColTable(gpRows, 'הארקת הגנה');

    if(tr.checklistEnabled && tr.checklist.some(c=>c.status)){
      const rows = TRANSFORMER_INSPECTION_CHECKLIST.map((label,ci)=>{
        const c = tr.checklist[ci];
        if(!c.status) return null;
        const noteHtml = c.notes ? `<div class="compact-check-note">${escapeHtml(c.notes)}</div>` : '';
        return {
          labelHtml: `${escapeHtml(label)}${noteHtml}`,
          resultHtml: escapeHtml(MAIN_PANEL_STATUS_LABELS[c.status]||c.status),
          fullWidth: shouldUseFullWidthChecklistItem(label, c.notes)
        };
      }).filter(Boolean);
      // תבנית בטוחה — כותרת כשורה בתוך ה-thead עצמו (עכשיו דרך buildCompactChecklistTable,
      // שכבר תומכת באותה תבנית), לא div/p נפרד לפני הטבלה. אותו לקח בדיוק שנלמד ואומת מהבאג
      // האמיתי שתוקן ב-MAIN_PANEL (v2.229-2.234): מונע הפרדת כותרת מנתונים כשהטבלה נופלת על
      // גבול עמוד.
      h += buildCompactChecklistTable(rows, { itemTitle:'תיאור הבדיקה', resultTitle:'סטטוס', title:'בדיקות ויזואליות' });
    }

    if(tr.insulationEnabled && tr.insulationTests.some(r=>r.enabled)){
      const rows = TRANSFORMER_INSPECTION_INSULATION_TESTS.map((t,ii)=>{
        const r = tr.insulationTests[ii];
        if(!r.enabled) return null;
        const statusText = MAIN_PANEL_STATUS_LABELS[r.status]||r.status||'—';
        const valueText = r.value ? ` (${escapeHtml(r.value)} MΩ)` : '';
        return { labelHtml: escapeHtml(t.label), resultHtml: `${escapeHtml(statusText)}${valueText}`, fullWidth: false };
      }).filter(Boolean);
      h += buildCompactChecklistTable(rows, { itemTitle:'סוג בדיקה', resultTitle:'תוצאה', title:'בדיקת בידוד שנאי' });
    }

    h += printSectionNotesBlock(tr.sectionNotes);
    blocks.push({level:1, sectionKey:`ti-transformer-${tri}`, title, html:h});
  });

  if(ti.summaryItems.length && ti.summaryItems.some(s=>s.text && s.text.trim())){
    blocks.push({level:1, sectionKey:'ti-summary', title:'ממצאים מסכמים', html:
      `<h2>ממצאים מסכמים</h2>${ti.summaryItems.filter(s=>s.text&&s.text.trim()).map(s=>`<p style="font-size:12px; margin:4px 0;"><b>${s.number}.</b> ${escapeHtml(s.text)}</p>`).join('')}`});
  }

  if(ti.conclusion.status || ti.conclusion.freeText){
    let h = `<h2>מסקנה</h2>`;
    if(ti.conclusion.status) h += `<p style="font-size:12px; font-weight:600;">${escapeHtml(ti.conclusion.status)}</p>`;
    if(ti.conclusion.freeText) h += `<p style="font-size:12px;">${escapeHtml(ti.conclusion.freeText)}</p>`;
    blocks.push({level:1, sectionKey:'ti-conclusion', title:'מסקנה', html:h});
  }

  return blocks;
}

function buildTransformerWindingReportBlocks(){
  const tw = state.transformerWindingReport;
  const blocks = [];

  const descRows = [
    ['שם המוצר', tw.productName], ['דגם', tw.productType], ["מס' סידורי", tw.serialNo],
    ["מס' שרטוט", tw.drawingNo], ["מס' פרויקט / אתר", tw.projectSite], ['תאריך בדיקה בשטח', formatDateIL(tw.fieldTestDate)],
    ['הספק מדורג (kVA)', tw.powerRating], ['שיטת קירור', tw.coolingType], ['מתח מדורג (kV)', tw.ratedVoltage],
    ['מספר פאזות', tw.numberOfPhases], ['זרם מדורג (A)', tw.ratedCurrent], ['תדר מדורג (Hz)', tw.ratedFrequency],
    ['קבוצת וקטור', tw.vectorGroup], ['יעילות (PEI)', tw.pei], ['BIL HV', tw.bilHV], ['BIL LV', tw.bilLV]
  ].filter(r=>r[1]);
  if(descRows.length){
    blocks.push({level:1, sectionKey:'tw-description', title:'פרטי מוצר ומפרט טכני', html:`<h2>פרטי מוצר ומפרט טכני</h2><table class="tinfo-table">${descRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`});
  }

  const buildWindingSectionHtml = (label, side, extraHtmlAfterHeader) => {
    const data = tw[side];
    const hasHv = data.hv.some(r=>r.ab||r.bc||r.ca);
    const hasLv = data.lv.ab||data.lv.bc||data.lv.ca;
    const hasIns = tw.insulation[side].rows.some(r=>r.r15||r.r60||r.r600);
    if(!hasHv && !hasLv && !hasIns && !data.temp && !extraHtmlAfterHeader) return '';
    let html = `<h2>${label}</h2>`;
    const condRows = [['טמפ\' בעת הבדיקה (°C)', data.temp], ['לחות יחסית (%)', data.humidity]].filter(r=>r[1]);
    if(condRows.length) html += `<table class="tinfo-table">${condRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    // תיקון התנגדות כבל הזנה — מוזרק כאן ישירות (לא .replace() שביר על מחרוזת), מיד אחרי
    // כותרת/טמפ'-לחות, לפני שאר תוכן הבדיקה — נכון גם במקרה קצה שאין בכלל טמפ'/לחות שמולאו.
    if(extraHtmlAfterHeader) html += extraHtmlAfterHeader;
    if(hasHv){
      html += `<h3 style="font-size:12px;">H.V. Windings</h3><table><thead><tr><th>Tap</th><th>A~B (${data.hvUnit})</th><th>B~C (${data.hvUnit})</th><th>C~A (${data.hvUnit})</th><th>Unbalance (%)</th></tr></thead><tbody>`;
      data.hv.forEach(row=>{
        if(!row.ab && !row.bc && !row.ca) return;
        const u = windingUnbalancePercent(row.ab,row.bc,row.ca);
        html += `<tr><td>${row.tap}</td><td>${escapeHtml(row.ab)||'—'}</td><td>${escapeHtml(row.bc)||'—'}</td><td>${escapeHtml(row.ca)||'—'}</td><td>${u===null?'—':u.toFixed(2)+'%'}</td></tr>`;
        // שורת ערכים מתוקנים (קריאה בלבד) — אותה לוגיקה בדיוק כמו בטופס העריכה, לפי בקשה
        // מפורשת: "להשאיר את הערך שנמדד, ולהוסיף לידו את הערך המתוקן". רק בבדיקת שטח.
        if(side === 'field' && cableCorrectionOhm !== null){
          const sub = (v) => { const n = parseFloat(v); return isNaN(n) ? '' : (n - cableCorrectionOhm).toFixed(4); };
          const cAb = sub(row.ab), cBc = sub(row.bc), cCa = sub(row.ca);
          const uCorr = windingUnbalancePercent(cAb, cBc, cCa);
          html += `<tr style="background:#f5f5f5;"><td style="font-size:9.5px; color:#666;">מתוקן</td><td>${cAb || '—'}</td><td>${cBc || '—'}</td><td>${cCa || '—'}</td><td>${uCorr===null?'—':uCorr.toFixed(2)+'%'}</td></tr>`;
        }
      });
      html += `</tbody></table>`;
    }
    if(hasLv){
      const u = windingUnbalancePercent(data.lv.ab,data.lv.bc,data.lv.ca);
      html += `<h3 style="font-size:12px;">L.V. Windings</h3><table><thead><tr><th>a~b (${data.lvUnit})</th><th>b~c (${data.lvUnit})</th><th>c~a (${data.lvUnit})</th><th>Unbalance (%)</th></tr></thead><tbody>
        <tr><td>${escapeHtml(data.lv.ab)||'—'}</td><td>${escapeHtml(data.lv.bc)||'—'}</td><td>${escapeHtml(data.lv.ca)||'—'}</td><td>${u===null?'—':u.toFixed(2)+'%'}</td></tr>
      </tbody></table>`;
    }
    const ins = tw.insulation[side];
    if(hasIns){
      html += `<h3 style="font-size:12px;">התנגדות בידוד (Insulation Resistance)</h3>`;
      const insCondRows = [['מתח בדיקה (V)', ins.testVoltage], ['טמפ\' שמן עליון (°C)', ins.topOilTemp], ['לחות יחסית (%)', ins.humidity]].filter(r=>r[1]);
      if(insCondRows.length) html += `<table class="tinfo-table">${insCondRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;

      const method = (side === 'field') ? (ins.testMethod || 'dar') : 'dar';
      if(method === 'pi'){
        html += `<p style="font-size:11px;"><b>שיטת בדיקה:</b> PI — מדד קיטוב (R10min/R1min)</p>`;
        html += `<table><thead><tr><th>נמדד בין</th><th>R1min</th><th>R10min</th><th>PI</th><th>סטטוס</th></tr></thead><tbody>`;
        ins.rows.forEach(row=>{
          if(!row.r60 && !row.r600) return;
          const r60 = parseFloat(row.r60), r600 = parseFloat(row.r600);
          const piValue = (!isNaN(r60) && !isNaN(r600) && r60!==0) ? (r600/r60) : null;
          const pi = piValue===null ? '—' : piValue.toFixed(2);
          const cls = classifyInsulationResult(piValue, 'pi', true);
          const u = row.unit || 'MΩ';
          html += `<tr><td>${escapeHtml(row.label)}</td><td>${row.r60?escapeHtml(row.r60)+' '+u:'—'}</td><td>${row.r600?escapeHtml(row.r600)+' '+u:'—'}</td><td style="color:${cls.color}; font-weight:600;">${pi}</td><td style="color:${cls.color}; font-weight:600;">${cls.label}</td></tr>`;
        });
        html += `</tbody></table>`;
      } else if(method === 'simple'){
        html += `<p style="font-size:11px;"><b>שיטת בדיקה:</b> רמת בידוד רגילה + תיקון טמפרטורה לטמפרטורת ייחוס ${escapeHtml(ins.referenceTemp)}°C</p>`;
        html += `<table><thead><tr><th>נמדד בין</th><th>R נמדד</th><th>R מתוקן</th></tr></thead><tbody>`;
        ins.rows.forEach(row=>{
          if(!row.r60) return;
          const u = row.unit || 'MΩ';
          const corrected = insulationTempCorrect(row.r60, ins.topOilTemp, ins.referenceTemp);
          html += `<tr><td>${escapeHtml(row.label)}</td><td>${escapeHtml(row.r60)} ${u}</td><td>${corrected===null?'—':corrected.toFixed(1)+' '+u}</td></tr>`;
        });
        html += `</tbody></table>`;
      } else {
        html += `<table><thead><tr><th>נמדד בין</th><th>R15"</th><th>R60"</th><th>יחס ספיגה</th><th>סטטוס</th></tr></thead><tbody>`;
        ins.rows.forEach(row=>{
          if(!row.r15 && !row.r60) return;
          const r15 = parseFloat(row.r15), r60 = parseFloat(row.r60);
          const ratioValue = (!isNaN(r15) && !isNaN(r60) && r15!==0) ? (r60/r15) : null;
          const ratio = ratioValue===null ? '—' : ratioValue.toFixed(2);
          const cls = classifyInsulationResult(ratioValue, 'dar', true);
          const u = row.unit || 'MΩ';
          html += `<tr><td>${escapeHtml(row.label)}</td><td>${row.r15?escapeHtml(row.r15)+' '+u:'—'}</td><td>${row.r60?escapeHtml(row.r60)+' '+u:'—'}</td><td style="color:${cls.color}; font-weight:600;">${ratio}</td><td style="color:${cls.color}; font-weight:600;">${cls.label}</td></tr>`;
        });
        html += `</tbody></table>`;
      }
    }
    if(data.notes) html += `<p style="font-size:12px;">${escapeHtml(data.notes)}</p>`;
    return html;
  };

  const factoryHtml = buildWindingSectionHtml('נתוני יצרן — פ"ט (Factory Test Report)', 'factory');
  if(factoryHtml) blocks.push({level:1, sectionKey:'tw-factory', title:'נתוני יצרן — פ"ט', html:factoryHtml});

  // תיקון התנגדות כבל הזנה — מחושב כאן (לא רק בהמשך, לצורך טבלת ההשוואה) כדי שאפשר יהיה
  // להזריק את הטבלה שלו ישירות לתוך buildWindingSectionHtml('field', ...), בהתאמה למיקום
  // החדש במסך העריכה (בתוך סעיף 04, מיד אחרי טמפרטורה/לחות) — לפי בקשה מפורשת: "מדובר
  // בחישוב [השייך לבדיקת השטח]".
  const cableCorrectionOhm = calcCableCorrectionResistance(tw.cableCorrection);
  let cableCorrectionHtml = '';
  if(cableCorrectionOhm !== null){
    const cc = tw.cableCorrection;
    const matLabel = cc.material === 'Al' ? 'אלומיניום (Al)' : 'נחושת (Cu)';
    cableCorrectionHtml = `<h3 style="font-size:13px; margin:12px 0 4px;">קיזוז התנגדות הגידים מתח גבוה</h3>
      <p style="font-size:11px;">הבדיקה בשטח מתבצעת בתא חיבור השנאי — הערך הנמדד כולל גם את התנגדות כבל ההזנה, ולכן הופחת מהערכים שנמדדו בשטח לפני תיקון הטמפרטורה.</p>
      <table style="font-size:11px;"><thead><tr><th>שטח חתך (מ"מ²)</th><th>סוג חומר</th><th>אורך (מ')</th><th>התנגדות כבל מחושבת (Ω)</th></tr></thead>
      <tbody><tr><td>${escapeHtml(cc.crossSection)}</td><td>${matLabel}</td><td>${escapeHtml(cc.length)}</td><td>${cableCorrectionOhm.toFixed(4)}</td></tr></tbody></table>`;
  }
  const fieldHtml = buildWindingSectionHtml('בדיקת שטח (Field Test)', 'field', cableCorrectionHtml);
  if(fieldHtml) blocks.push({level:1, sectionKey:'tw-field', title:'בדיקת שטח', html:fieldHtml});

  // טבלת השוואה — אותו חישוב בדיוק כמו במסך, כדי שההדפסה תמיד תואמת למה שהמשתמש רואה
  const t2 = tw.referenceTemp;
  const threshold = parseFloat(tw.deviationThreshold) || 5;
  const comparisonRows = [];
  tw.factory.hv.forEach((fRow, i)=>{
    const jRow = tw.field.hv[i];
    ['ab','bc','ca'].forEach(ph=>{
      const label = {ab:'A~B', bc:'B~C', ca:'C~A'}[ph];
      const rFactory = windingTempCorrect(toOhms(fRow[ph], tw.factory.hvUnit), tw.factory.temp, t2, tw.conductorMaterial);
      const fieldOhmRaw = toOhms(jRow[ph], tw.field.hvUnit);
      const fieldOhmCorrected = (fieldOhmRaw !== null && cableCorrectionOhm !== null) ? fieldOhmRaw - cableCorrectionOhm : fieldOhmRaw;
      const rField = windingTempCorrect(fieldOhmCorrected, tw.field.temp, t2, tw.conductorMaterial);
      if(rFactory !== null || rField !== null) comparisonRows.push({ tap: fRow.tap, phase: label, rFactory, rField });
    });
  });
  ['ab','bc','ca'].forEach(ph=>{
    const label = {ab:'a~b', bc:'b~c', ca:'c~a'}[ph];
    const rFactory = windingTempCorrect(toOhms(tw.factory.lv[ph], tw.factory.lvUnit), tw.factory.temp, t2, tw.conductorMaterial);
    const fieldOhmRaw = toOhms(tw.field.lv[ph], tw.field.lvUnit);
    const fieldOhmCorrected = (fieldOhmRaw !== null && cableCorrectionOhm !== null) ? fieldOhmRaw - cableCorrectionOhm : fieldOhmRaw;
    const rField = windingTempCorrect(fieldOhmCorrected, tw.field.temp, t2, tw.conductorMaterial);
    if(rFactory !== null || rField !== null) comparisonRows.push({ tap: '—', phase: label, rFactory, rField });
  });



  if(comparisonRows.length){
    const rowsHtml = comparisonRows.map(r=>{
      let deviation = null, status = '—', statusColor = '#666';
      if(r.rFactory !== null && r.rField !== null && r.rFactory !== 0){
        deviation = ((r.rField - r.rFactory) / r.rFactory) * 100;
        if(Math.abs(deviation) <= threshold){ status = '✓ תקין'; statusColor = '#2e7d32'; }
        else{ status = '⚠ חורג — נדרשת בדיקה'; statusColor = '#c62828'; }
      }
      return `<tr><td>${r.tap}</td><td>${r.phase}</td><td>${r.rFactory===null?'—':formatOhms(r.rFactory)}</td><td>${r.rField===null?'—':formatOhms(r.rField)}</td><td style="color:${statusColor}; font-weight:600;">${deviation===null?'—':deviation.toFixed(2)+'%'}</td><td style="color:${statusColor}; font-weight:600;">${status}</td></tr>`;
    }).join('');
    const html = `<h2>תיקון טמפרטורה והשוואה</h2>
      <p style="font-size:11px;">חומר מוליך: ${tw.conductorMaterial==='Al'?'אלומיניום (Al), T=225':'נחושת (Cu), T=235'} | טמפרטורת ייחוס: ${escapeHtml(tw.referenceTemp)}°C | סף סטייה מקובל: ${escapeHtml(tw.deviationThreshold)}%</p>
      <p style="font-size:10.5px; color:#555; margin:-4px 0 6px;">${TW_STANDARD_NOTE}</p>
      <table style="font-size:11px;"><thead><tr><th>Tap</th><th>פאזה</th><th>R פ"ט מתוקן (Ω)</th><th>R שטח מתוקן (Ω)</th><th>סטייה (%)</th><th>סטטוס</th></tr></thead><tbody>${rowsHtml}</tbody></table>`;
    blocks.push({level:1, sectionKey:'tw-comparison', title:'תיקון טמפרטורה והשוואה', html});
  }

  if(tw.dgptTest.status || tw.dgptTest.notes){
    let html = `<h2>בדיקת ממסר הגנות DGPT</h2>`;
    if(tw.dgptTest.status) html += `<p style="font-size:12px; font-weight:600;">תוצאת הבדיקה: ${escapeHtml(tw.dgptTest.status)}</p>`;
    if(tw.dgptTest.notes) html += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(tw.dgptTest.notes)}</p>`;
    blocks.push({level:1, sectionKey:'tw-dgpt', title:'בדיקת ממסר הגנות DGPT', html});
  }

  const concRows = [['שם הבודק', tw.inspectorName], ['תאריך', formatDateIL(tw.inspectionDate)], ['מאשר / מהנדס אחראי', tw.approverName]].filter(r=>r[1]);
  // הערות ממוספרות מודפסות בעמוד האישור (v2.2.540) — ראה finalizationInner
  if(tw.conclusion.status || tw.conclusion.freeText || concRows.length){
    let html = `<h2>מסקנות</h2>`;
    if(tw.conclusion.status) html += `<div class="approval-banner ${getApprovalColorClass(tw.conclusion.status, TRANSFORMER_CONCLUSION_OPTIONS)}" style="margin-bottom:8px;">${escapeHtml(tw.conclusion.status)}</div>`;
    if(tw.conclusion.freeText) html += `<p style="font-size:12px;">${escapeHtml(tw.conclusion.freeText)}</p>`;
    if(concRows.length) html += `<table class="tinfo-table">${concRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    blocks.push({level:1, sectionKey:'tw-conclusion', title:'מסקנות', html});
  }

  return blocks;
}

function buildTouchVoltageReportBlocks(photoCounter){
  const tv = state.touchVoltageReport;
  const blocks = [];

  const facilityRows = [
    ['סוג מתקן', tv.facilityType], ['מתח המערכת', touchVoltageFieldDisplay(tv.systemVoltage)],
    ['זרם תקלה', touchVoltageFieldDisplay(tv.faultCurrent)], ['זמן ניתוק תקלה', touchVoltageFieldDisplay(tv.clearingTime)],
    ['משקל גוף לחישוב', tv.bodyWeight ? tv.bodyWeight+' ק"ג' : '']
  ].filter(r=>r[1]);
  if(facilityRows.length){
    blocks.push({level:1, sectionKey:'tv-facility', title:'פרטי מתקן ומערכת', html:`<h2>פרטי מתקן ומערכת</h2><table class="tinfo-table">${facilityRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`});
  }

  const relevantContinuity = tv.continuityItems.filter(it=>it.from || it.to || it.resistance);
  if(relevantContinuity.length){
    const rows = relevantContinuity.map(it=>{
      const eq = equipmentList.find(e=>e.id===it.instrumentId);
      return `<tr>
        <td>${escapeHtml(it.from)}</td>
        <td>${escapeHtml(it.to)}</td>
        <td>${it.resistance ? escapeHtml(it.resistance)+' '+it.unit : '—'}</td>
        <td>${eq ? escapeHtml(eq.name) : '—'}</td>
        <td>${escapeHtml(it.criterion) || '—'}</td>
        <td>${escapeHtml(it.result) || '—'}</td>
        <td>${escapeHtml(it.notes)}</td>
      </tr>`;
    }).join('');
    blocks.push({level:1, sectionKey:'tv-continuity', title:'בדיקת רציפות הארקה', html:`<h2>בדיקת רציפות הארקה</h2><table><thead><tr><th>מ- (FROM)</th><th>אל (TO)</th><th>התנגדות</th><th>מכשיר</th><th>קריטריון</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`});
  }

  const relevantItems = tv.items.filter(it=>it.location || it.touchVoltage || it.stepVoltage);
  const tvGeneralNotesBlock = printSectionNotesBlock(tv.generalNotes);
  if(relevantItems.length || tvGeneralNotesBlock){
    let html = '';
    if(relevantItems.length){
      const rows = relevantItems.map(it=>{
        const eq = equipmentList.find(e=>e.id===it.instrumentId);
        return `<tr>
          <td>${escapeHtml(it.location)}</td>
          <td>${it.touchVoltage ? escapeHtml(it.touchVoltage)+' '+it.unit : '—'}</td>
          <td>${it.stepVoltage ? escapeHtml(it.stepVoltage)+' '+it.unit : '—'}</td>
          <td>${eq ? escapeHtml(eq.name) : '—'}</td>
          <td>${escapeHtml(it.criterion) || '—'}</td>
          <td>${escapeHtml(it.result) || '—'}</td>
          <td>${escapeHtml(it.notes)}</td>
        </tr>`;
      }).join('');
      html = `<h2>מדידות מתח מגע וצעד</h2><table><thead><tr><th>נקודת בדיקה</th><th>מתח מגע</th><th>מתח צעד</th><th>מכשיר</th><th>קריטריון</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${rows}</tbody></table>`;
    } else {
      html = `<h2>מדידות מתח מגע וצעד</h2>`;
    }
    // תיקון מפורש (#7): הערה כללית מודפסת גם ללא אף שורת מדידה — לא מקוננת עוד בתוך
    // if(relevantItems.length). לא נוגע ב-state, רק בתנאי ההדפסה עצמו.
    html += tvGeneralNotesBlock;
    blocks.push({level:1, sectionKey:'tv-measurements', title:'מדידות מתח מגע וצעד', html});
  }

  if(tv.conclusion.status || tv.conclusion.freeText){
    let html = `<h2>מסקנת הבודק</h2>`;
    if(tv.conclusion.status) html += `<p style="font-size:13px; font-weight:700;">${escapeHtml(tv.conclusion.status)}</p>`;
    if(tv.conclusion.freeText) html += `<p style="font-size:12px;">${escapeHtml(tv.conclusion.freeText)}</p>`;
    blocks.push({level:1, sectionKey:'tv-conclusion', title:'מסקנת הבודק', html});
  }

  return blocks;
}

function buildMedicalReportBlocks(photoCounter){
  const m = state.medicalReport;
  const blocks = [];

  const statusSymbol = (status) => {
    const opt = MEDICAL_STATUS_OPTIONS.find(o=>o.key===status);
    if(!opt) return '';
    return `<span style="color:${opt.color}; font-weight:700;">${opt.printSymbol}</span>`;
  };
  const checklistTable = (items) => {
    const relevant = items.filter(it=>it.status);
    if(!relevant.length) return '';
    return `<table><thead><tr><th style="width:60px;">תוצאה</th><th>פריט</th></tr></thead><tbody>${relevant.map(it=>
      `<tr><td style="text-align:center;">${statusSymbol(it.status)}</td><td>${escapeHtml(it.label)}${it.status==='F' && it.notes ? `<div style="font-size:11px; color:#c0392b; margin-top:2px;">${escapeHtml(it.notes)}</div>` : ''}</td></tr>`
    ).join('')}</tbody></table>`;
  };

  // פרטי הבודק
  const inspRows = [
    ['שם פרטי ומשפחה', m.inspector.name], ['מ.ר מהנדס חשמל', m.inspector.engineerLicenseNo],
    ['מ.ר בודק סוג 3', m.inspector.testerLicenseType3No]
  ].filter(r=>r[1]);
  if(inspRows.length) blocks.push({level:1, sectionKey:'med-inspector', title:'פרטי הבודק', html:`<h2>פרטי הבודק</h2><table class="tinfo-table">${inspRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`});

  // פרטים טכניים
  const techRows = [
    ['מתח הזנה', m.technical.supplyVoltage], ['גודל חיבור', m.technical.connectionSize],
    ['מקור הזנה', m.technical.supplySource], ['אספקת חירום', m.technical.emergencySupply],
    ['שיטת הגנה נגד התחשמלות', m.technical.protectionMethod]
  ].filter(r=>r[1]);
  if(techRows.length || m.technical.installationDescription){
    let html = `<h2>פרטים טכניים</h2>`;
    if(techRows.length) html += `<table class="tinfo-table">${techRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    if(m.technical.installationDescription) html += `<p style="font-size:12px;"><b>תיאור המתקן:</b> ${escapeHtml(m.technical.installationDescription)}</p>`;
    blocks.push({level:1, sectionKey:'med-technical', title:'פרטים טכניים', html});
  }

  // לוח המזין
  const panelLabels = { essential:'חיוני', superEssential:'סופר חיוני', ups:'UPS' };
  const relevantPanels = Object.keys(panelLabels).filter(k=>m.feedPanels[k].enabled);
  if(relevantPanels.length){
    let html = `<h2>לוח המזין</h2>`;
    relevantPanels.forEach(k=>{
      const p = m.feedPanels[k];
      const rows = [
        ['שם לוח', p.boardName], ['שם מפסק', p.breakerName], ['מפסק ראשי משולב פחת', p.mainCombinedRcdBreaker],
        ['גודל מבטח', p.breakerSize], ['הגנה טרמית', p.thermalProtection], ['הגנת קצר מהשואת', p.shortCircuitProtectionType]
      ].filter(r=>r[1]);
      if(rows.length){
        html += `<h3 style="font-size:13px;">${panelLabels[k]}</h3><table class="tinfo-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
      }
    });
    blocks.push({level:1, sectionKey:'med-feedpanels', title:'לוח המזין', html});
  }

  // סוג המתקן
  if(m.roomType){
    blocks.push({level:1, sectionKey:'med-roomtype', title:'סוג המתקן הרפואי', html:`<h2>סוג המתקן הרפואי הנבדק</h2><p style="font-size:12px;">${escapeHtml(m.roomType)}</p>`});
  }

  // צ'קליסטים
  const checklistSections = [
    ['med-roomChecklist', 'בדיקת המתקן הרפואי', m.roomChecklist, m.roomChecklistNotes],
    ['med-floatingSupplyChecklist', 'בדיקת הזנות — הזנה בזינה צפה', m.floatingSupplyChecklist, m.floatingSupplyChecklistNotes],
    ['med-isolationTransformerChecklist', 'שנאי מבדל', m.isolationTransformerChecklist, m.isolationTransformerChecklistNotes],
    ['med-insulationMonitorChecklist', 'משגוח בידוד', m.insulationMonitorChecklist, m.insulationMonitorChecklistNotes],
    ['med-monitorAlarmChecklist', 'תצוגה והתראה של משגוח בידוד', m.monitorAlarmChecklist, m.monitorAlarmChecklistNotes],
    ['med-protectionBreakerChecklist', 'מפסק מגן', m.protectionBreakerChecklist, m.protectionBreakerChecklistNotes],
    ['med-earthConductorsChecklist', 'מוליכי הארקה', m.earthConductorsChecklist, m.earthConductorsChecklistNotes],
    ['med-peBarChecklist', 'חיבור לפס PE', m.peBarChecklist, m.peBarChecklistNotes]
  ];
  checklistSections.forEach(([key, title, items, sectionNotes])=>{
    const table = checklistTable(items);
    const notesBlock = printSectionNotesBlock(sectionNotes);
    if(table || notesBlock) blocks.push({level:1, sectionKey:key, title, html:`<h2>${title}</h2>${table||''}${notesBlock}`});
  });

  // הערה כללית לכרטיס "בדיקת רצפה אנטי-סטטית" — הכרטיס עצמו (נקודות בדיקה על תמונה) לא היה
  // מודפס כלל עד כה (אין לו בלוק PDF קיים), כך שההערה מודפסת כבלוק עצמאי משלה, לא בתוך
  // טבלה שלא קיימת ממילא. לא נוגע ב-point.notes של כל נקודה בנפרד.
  const antiStaticNotesBlock = printSectionNotesBlock(m.antiStaticFloorTestNotes);
  if(antiStaticNotesBlock) blocks.push({level:1, sectionKey:'med-antistaticfloor', title:'בדיקת רצפה אנטי-סטטית', html:`<h2>בדיקת רצפה אנטי-סטטית</h2>${antiStaticNotesBlock}`});

  // מדידות משגוח
  const relevantMonitors = m.monitorMeasurements.filter(mm=>mm.deltaU || mm.uin || mm.isc1 || mm.isc2);
  if(relevantMonitors.length){
    let html = `<h2>מדידות משגוח בידוד</h2>`;
    relevantMonitors.forEach(mm=>{
      const rows = [
        ['ΔU%', mm.deltaU], ['Uin', mm.uin], ['Isc1', mm.isc1], ['Isc2', mm.isc2],
        ['R1', mm.r1], ['R2', mm.r2], ['I1', mm.i1], ['I2', mm.i2], ['Z(LN)', mm.zLN], ['Ipsc(LN)', mm.ipscLN]
      ].filter(r=>r[1]);
      if(rows.length) html += `<h3 style="font-size:13px;">משגוח מס' ${mm.monitorNumber}</h3><table class="tinfo-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    });
    blocks.push({level:1, sectionKey:'med-monitors', title:'מדידות משגוח בידוד', html});
  }

  // רשימת הסתייגויות
  if(m.reservationsText && m.reservationsText.trim()){
    blocks.push({level:1, sectionKey:'med-reservations', title:'רשימת הסתייגויות', html:`<h2>רשימת הסתייגויות</h2><p style="font-size:12px; white-space:pre-wrap;">${escapeHtml(m.reservationsText)}</p>`});
  }

  // מסקנה
  if(m.conclusion){
    blocks.push({level:1, sectionKey:'med-conclusion', title:'מסקנה', html:`<h2>מסקנה</h2><p style="font-size:12.5px; font-weight:700;">${escapeHtml(m.conclusion)}</p>
      <p style="font-size:11px; margin-top:12px;">מכשירי חשמל ניידים המחוברים לבתי תקע ומכשירים אחרים המותקנים במקום ואינם חלק ממתקן החשמל הקבוע לא נבדקו.</p>
      <p style="font-size:11px;">תוקפו של הדוח נכון אך ורק ליום הבדיקה ואין הבודק אחראי לכל שינוי שלא על דעתו.</p>`});
  }

  return blocks;
}

function buildGeneralReportBlocks(photoCounter){
  const g = state.generalElectricalInspectionReport;
  const blocks = [];

  // Installations
  (g.installations||[]).forEach((inst, idx)=>{
    const titleText = inst.showTitleInReport
      ? (inst.installationName ? (inst.location ? `${inst.installationName} – ${inst.location}` : inst.installationName) : '')
      : '';
    let instHtml = titleText ? `<h2>${escapeHtml(titleText)}</h2>` : `<h2>מתקן ${idx+1}</h2>`;
    let hasContent = false;

    if(inst.electricalBoard.enabled){
      const eb = inst.electricalBoard;
      const ad = eb.additionalDetails;
      const boardTypeDisplay = eb.boardType==='אחר' ? eb.boardTypeOther : eb.boardType;
      const standardDisplay = eb.boardStandard==='אחר' ? eb.boardStandardOther : eb.boardStandard;
      const changeoverDisplay = eb.changeoverSystem.type==='אחר' ? eb.changeoverSystem.other : eb.changeoverSystem.type;
      const statusDisplay = (label, statusObj) => {
        if(!statusObj.status) return '';
        let txt = statusObj.status;
        if(statusObj.status==='קיים ולא תקין' && statusObj.notes) txt += ' — ' + statusObj.notes;
        return txt;
      };
      const ebRows = [
        ['סוג הלוח', boardTypeDisplay], ['מספר עבודה', eb.workNumber], ['תקן הלוח', standardDisplay],
        ['גילוי', statusDisplay('גילוי', eb.detection)], ['ניתוק', statusDisplay('ניתוק', eb.disconnection)],
        ['כיבוי', statusDisplay('כיבוי', eb.fireSuppression)], ['מערכת החלפה', changeoverDisplay]
      ].filter(r=>r[1]);
      if(ebRows.length){
        hasContent = true;
        instHtml += `<h3 style="font-size:13px;">פרטי לוח חשמל</h3><table class="tinfo-table">${ebRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
      }
      const adRows = [
        ['שם הלוח', ad.boardName], ['סימון הלוח', ad.boardDesignation], ['יצרן', ad.manufacturer], ['דגם', ad.model],
        ['מספר סידורי', ad.serialNumber], ['שנת ייצור', ad.year],
        ['מתח נקוב', ad.ratedVoltage?formatMeasurement(ad.ratedVoltage,ad.ratedVoltageUnit):''],
        ['זרם נקוב', ad.ratedCurrent?formatMeasurement(ad.ratedCurrent,ad.ratedCurrentUnit):''],
        ['מספר פאזות', ad.phases], ['מספר קטבים', ad.poles], ['דרגת IP', ad.ipRating],
        ['Icw', ad.icw?formatMeasurement(ad.icw,ad.icwUnit):''], ['Icc', ad.icc?formatMeasurement(ad.icc,ad.iccUnit):''],
        ['מפסק ראשי', ad.mainBreaker], ['יצרן מפסק ראשי', ad.mainBreakerManufacturer], ['דגם מפסק ראשי', ad.mainBreakerModel],
        ['זרם נקוב של המפסק', ad.mainBreakerRatedCurrent?formatMeasurement(ad.mainBreakerRatedCurrent,ad.mainBreakerRatedCurrentUnit):''],
        ['Icu', ad.icu?formatMeasurement(ad.icu,ad.icuUnit):''], ['Ics', ad.ics?formatMeasurement(ad.ics,ad.icsUnit):''],
        ['מיקום הלוח', ad.location]
      ].filter(r=>r[1]);
      if(adRows.length || ad.notes){
        hasContent = true;
        instHtml += `<h3 style="font-size:13px;">פרטים נוספים על הלוח</h3>`;
        if(adRows.length) instHtml += `<table class="tinfo-table">${adRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(ad.notes) instHtml += `<p style="font-size:12px;">${escapeHtml(ad.notes)}</p>`;
      }
    }

    if(inst.testedEquipment.enabled){
      const relevantEquip = inst.testedEquipment.items.filter(it=>it.name || it.type || it.manufacturer || it.model || it.serialNo);
      if(relevantEquip.length){
        hasContent = true;
        instHtml += `<h3 style="font-size:13px;">ציוד ומתקנים נוספים</h3>`;
        relevantEquip.forEach((it,i)=>{
          const rows = [
            ['שם הציוד', it.name], ['סוג הציוד', it.type], ['דגם', it.model], ['מספר סידורי', it.serialNo],
            ['יצרן', it.manufacturer], ['שנת ייצור', it.yearOfManufacture], ['מתח נקוב', it.ratedVoltage],
            ['זרם נקוב', it.ratedCurrent], ['הספק', it.power], ['מיקום במתקן', it.location]
          ].filter(r=>r[1]);
          instHtml += `<p style="font-size:12px; font-weight:700; margin-bottom:4px;">ציוד #${i+1}</p>`;
          if(rows.length) instHtml += `<table class="tinfo-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
          if(it.description) instHtml += `<p style="font-size:11.5px;">${escapeHtml(it.description)}</p>`;
          if(it.notes) instHtml += `<p style="font-size:11.5px;">${escapeHtml(it.notes)}</p>`;
        });
      }
    }

    if(inst.upsTestsEnabled){
      const relevantUps = inst.upsTests.filter(t=>t.status);
      if(relevantUps.length){
        hasContent = true;
        instHtml += `<h3 style="font-size:13px;">בדיקות UPS/אל-פסק</h3><table class="tinfo-table">${relevantUps.map(t=>`<tr><td class="tinfo-label">${escapeHtml(t.name)}</td><td>${escapeHtml(t.status)}</td></tr>`).join('')}</table>`;
      }
    }

    // === סעיפי ליבה ברמת הלוח, לפי MASTER SPEC — היו קיימים בטופס העריכה בלבד, נעדרו לגמרי
    // מההדפסה. אותו דפוס באג בדיוק שכבר תוקן במקומות אחרים (v2.334 סוג מפסק, למשל).
    const relevantLoop = inst.loopTests.filter(r=>r.point && (r.Z || r.Isc || r.status));
    if(relevantLoop.length){
      hasContent = true;
      instHtml += `<h3 style="font-size:13px;">4. לולאות תקלה</h3>
        <table class="tinfo-table"><tr><th>בדיקה</th><th>Z</th><th>Isc</th><th>תקינות</th><th>הערות</th></tr>
        ${relevantLoop.map(r=>`<tr><td>${escapeHtml(r.point)}</td><td>${r.Z?formatMeasurement(r.Z,r.ZUnit):''}</td><td>${r.Isc?formatMeasurement(r.Isc,r.IscUnit):''}</td><td>${escapeHtml(r.status)}</td><td>${escapeHtml(r.notes)}</td></tr>`).join('')}
        </table>`;
    }

    // התנגדות בידוד — טבלה ייעודית, בדיוק כפי שהייתה ב-v2.385 (Baseline נעול, לא נוגע).
    const relevantIns = inst.insulationTests.filter(r=>r.point && (r.value || r.status));
    if(relevantIns.length){
      hasContent = true;
      if(inst.insulationTestLocation){
        instHtml += `<p style="font-size:11.5px; margin:8px 0 2px; font-weight:600;">מיקום ביצוע בדיקה: ${escapeHtml(inst.insulationTestLocation)}</p>`;
      }
      instHtml += `<h3 style="font-size:13px;">5. תוצאות בדיקה</h3>
        <p style="font-size:10.5px; color:#555;">✓ תקין &nbsp; X לא תקין &nbsp; N.R לא רלוונטי &nbsp; N.C לא נבדק &nbsp; N.A לא ישים</p>
        <table class="tinfo-table results-table-v2" style="table-layout:fixed; width:100%;">
        <colgroup>
          <col style="width:10%;"><col style="width:20%;"><col style="width:15%;"><col style="width:13%;"><col style="width:42%;">
        </colgroup>
        <tr><th>סוג בדיקה</th><th>בדיקה</th><th>ערך בידוד</th><th>תקינות</th><th>הערות</th></tr>
        ${relevantIns.map((r,i)=>`<tr>${i===0?`<td rowspan="${relevantIns.length}" style="vertical-align:middle;">התנגדות בידוד</td>`:''}<td>${escapeHtml(r.point)}</td><td style="text-align:center; vertical-align:middle;">${r.value?escapeHtml(r.sign||'')+(r.sign?' ':'')+formatMeasurement(r.value,r.unit):''}</td><td>${escapeHtml(r.status)}</td><td style="text-align:right; overflow-wrap:break-word; word-break:break-word; white-space:normal;">${escapeHtml(r.notes)}</td></tr>`).join('')}
        </table>`;
    }
    // הערה כללית לסעיף 5.1 — עצמאית מ-relevantIns.length בכוונה (לא מקוננת בתוך התנאי של
    // הטבלה למעלה, ש-v2.385 הנעול לא נגע בו כלל) — כדי שהערה לא תיעלם אם עדיין אין שורות
    // מדידה, אותה בעיה בדיוק שתוקנה למתח מגע (#7).
    if(inst.insulationSectionNotes && inst.insulationSectionNotes.trim()){
      hasContent = true;
      instHtml += printSectionNotesBlock(inst.insulationSectionNotes);
    }

    // בדיקות נוספות (5.2) — הועבר לכאן, לפני רציפות הארקה, לפי דרישה מפורשת לסדר
    // 5.1 בידוד -> 5.2 בדיקות נוספות -> 5.3 רציפות. תוכן הבלוק עצמו (כולל RCD אם קיים,
    // דרך renderGenRcd/buildGeneralInspectionExtrasBlocks הנפרדים) לא שונה כלל.
    // בדיקות נוספות (5.2) — לפי הסדר המאוחד (getOrderedAdditionalTests), כדי שה-PDF ישקף
    // בדיוק את הסדר שהמשתמש קבע במסך. שורות visualChecks עוקבות מקובצות לטבלה קומפקטית
    // אחת (לא טבלה נפרדת לכל שורה); פריטים גלובליים (RCD/leakageRelay/custom) — Reuse מלא
    // של buildSingleGenInspectionItemHtml (לא שכפול לוגיקה), מודפסים במיקומם המדויק בסדר.
    const orderedTests = getOrderedAdditionalTests(inst, idx === 0);
    const anyRelevantVisual = orderedTests.some(e => e.ref.type === 'visual' && e.data.description && e.data.status);
    if(anyRelevantVisual){ instHtml += `<h3 style="font-size:13px;">בדיקות כלליות / ויזואליות</h3>`; hasContent = true; }
    let pendingVisualRows = [];
    const flushVisualRows = () => {
      const rel = pendingVisualRows.filter(r=>r.description && r.status);
      if(rel.length){
        instHtml += `<table class="tinfo-table">${rel.map(r=>`<tr><td class="tinfo-label">${escapeHtml(r.description)}</td><td>${escapeHtml(r.status)}${r.notes?' — '+escapeHtml(r.notes):''}</td></tr>`).join('')}</table>`;
      }
      pendingVisualRows = [];
    };
    orderedTests.forEach(entry => {
      if(entry.ref.type === 'visual'){
        pendingVisualRows.push(entry.data);
      } else {
        flushVisualRows();
        const { html: itemHtml } = buildSingleGenInspectionItemHtml(entry.data);
        if(itemHtml){ hasContent = true; instHtml += itemHtml; }
      }
    });
    flushVisualRows();
    // הערה כללית לסעיף 5.2 — עצמאית מהתוכן שלמעלה, אותה סיבה בדיוק כמו 5.1/5.3.
    if(inst.additionalTestsSectionNotes && inst.additionalTestsSectionNotes.trim()){
      hasContent = true;
      instHtml += printSectionNotesBlock(inst.additionalTestsSectionNotes);
    }

    // רציפות הארקה (5.3) — טבלה ייעודית נפרדת (לא "ערך בידוד" של 5.1). תא "בדיקה" מציג point,
    // ומתחתיו description ו/או "מ-X עד Y" רק כשקיימים בפועל — לפי בקשה מפורשת לא להשאיר
    // שורה ריקה עבור שדות שלא מולאו. עמודת "ערך נדרש" מציגה requiredValue כפי שנשמר,
    // בלי לנחש ערך חסר (אם ריק — נשאר ריק בפשטות, לא טקסט ברירת מחדל).
    const relevantGrounding = inst.groundingContinuity.filter(r=>r.point && (r.value || r.status));
    if(relevantGrounding.length){
      hasContent = true;
      if(inst.groundingContinuityTestLocation){
        instHtml += `<p style="font-size:11.5px; margin:8px 0 2px; font-weight:600;">מיקום ביצוע בדיקה: ${escapeHtml(inst.groundingContinuityTestLocation)}</p>`;
      }
      instHtml += `<h3 style="font-size:13px;">5.3 רציפות הארקה</h3>
        <p style="font-size:10.5px; color:#555;">✓ תקין &nbsp; X לא תקין &nbsp; N.R לא רלוונטי &nbsp; N.C לא נבדק &nbsp; N.A לא ישים</p>
        <table class="tinfo-table" style="table-layout:fixed; width:100%;">
        <colgroup>
          <col style="width:27%;"><col style="width:15%;"><col style="width:15%;"><col style="width:13%;"><col style="width:30%;">
        </colgroup>
        <tr><th>בדיקה</th><th>ערך מדידה</th><th>ערך נדרש</th><th>תקינות</th><th>הערות</th></tr>
        ${relevantGrounding.map(r=>{
          const pointLines = [escapeHtml(r.point)];
          if(r.description) pointLines.push(`<div style="font-size:10px; color:#555; margin-top:2px;">${escapeHtml(r.description)}</div>`);
          if(r.fromPoint || r.toPoint) pointLines.push(`<div style="font-size:10px; color:#555; margin-top:2px;">מ-${escapeHtml(r.fromPoint||'')} עד ${escapeHtml(r.toPoint||'')}</div>`);
          return `<tr>
            <td style="text-align:right;">${pointLines.join('')}</td>
            <td style="text-align:center; vertical-align:middle;">${r.value?formatMeasurement(r.value,r.unit):''}</td>
            <td style="text-align:center; vertical-align:middle;">${escapeHtml(r.requiredValue||'')}</td>
            <td>${escapeHtml(r.status)}</td>
            <td style="text-align:right; overflow-wrap:break-word; word-break:break-word; white-space:normal;">${escapeHtml(r.notes)}</td>
          </tr>`;
        }).join('')}
        </table>`;
    }
    // הערה כללית לסעיף 5.3 (רציפות) — עצמאית מ-relevantGrounding.length, אותה סיבה בדיוק כמו 5.1.
    if(inst.groundingContinuitySectionNotes && inst.groundingContinuitySectionNotes.trim()){
      hasContent = true;
      instHtml += printSectionNotesBlock(inst.groundingContinuitySectionNotes);
    }

    if(inst.deficiencies.length){
      hasContent = true;
      instHtml += `<h3 style="font-size:13px;">6. פירוט כללי והסתייגויות</h3>`;
      inst.deficiencies.forEach((d,i)=>{
        if(!d.description) return;
        instHtml += `<p style="font-size:12px;"><b>${d.number||i+1}.</b> ${escapeHtml(d.description)}${d.severity?' <i>('+escapeHtml(d.severity)+')</i>':''}${d.recommendation?'<br>המלצה: '+escapeHtml(d.recommendation):''}</p>`;
      });
    }

    if(inst.boardPhotos && inst.boardPhotos.length){
      const validPhotos = inst.boardPhotos.filter(p=>p.dataUrl || p.cloudPath);
      if(validPhotos.length){
        hasContent = true;
        instHtml += `<h3 style="font-size:13px;">7. תמונות הלוח</h3>`;
        validPhotos.forEach((p,i)=>{
          instHtml += `<div style="border:3px solid #d4a63c; border-radius:8px; overflow:hidden; margin-bottom:14px; break-inside:avoid;">
            <div style="background:#f2f2f2; padding:5px 10px; font-size:12px; font-weight:700; color:#8a6d1e;">תמונה ${p.photoNumber||i+1}${p.caption ? ` — ${escapeHtml(p.caption)}` : ''}</div>
            <img src="${resolvePhotoSrc(p)}" data-cloudpath="${escapeAttr(p.cloudPath||'')}" style="width:100%; max-height:400px; object-fit:contain; display:block;">
          </div>`;
        });
      }
    }

    if(inst.electricalSupplies.enabled){
      const relevantSupplies = inst.electricalSupplies.items.filter(s=>s.supplySource || s.mainBreaker);
      relevantSupplies.forEach(sup=>{
        hasContent = true;
        const rows = [
          ['מקור הזנה', sup.supplySource], ['מתח הזנה', sup.supplyVoltage],
          ['מספר פאזות', sup.phaseCount], ['סוג כבל', sup.cableType==='אחר'?sup.cableTypeOther:sup.cableType],
          ['סוג בידוד', sup.insulationType], ['גודל חיבור', sup.connectionSize ? (sup.connectionSizePoles ? sup.connectionSizePoles+'x'+sup.connectionSize+'A' : sup.connectionSize+' A') : ''],
          ['מספר גידים', sup.conductorCount], ['שטח חתך', sup.crossSection?sup.crossSection+' mm²':''],
          ['חומר מוליך', sup.conductorMaterial], ['מספר כבלים במקביל', sup.parallelCables],
          ['מוליך הארקה', sup.groundConductor], ['מפסק ראשי', sup.mainBreaker], ['סוג מפסק', sup.mainBreakerType], ['יצרן מפסק', sup.breakerManufacturer],
          ['דגם מפסק', sup.breakerModel],
          ['זרם נקוב', sup.ratedCurrent?formatMeasurement(sup.ratedCurrent,sup.ratedCurrentUnit):''],
          ['Icu', sup.icu?formatMeasurement(sup.icu,sup.icuUnit):''], ['Ics', sup.ics?formatMeasurement(sup.ics,sup.icsUnit):''],
          ['לולאת תקלה', sup.loopImpedance]
        ].filter(r=>r[1]);
        const activeProts = ['L','S','I','G'].filter(k=>sup.protections[k].active).map(k=>{
          const p = sup.protections[k];
          return `${k}${p.value?': '+formatMeasurement(p.value,p.unit):''}`;
        });
        instHtml += `<h3 style="font-size:13px;">${escapeHtml(sup.title)}</h3>`;
        if(rows.length) instHtml += `<table class="tinfo-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(activeProts.length) instHtml += `<p style="font-size:12px;"><b>הגנות:</b> ${activeProts.map(escapeHtml).join(', ')}</p>`;
        if(sup.notes) instHtml += `<p style="font-size:12px;">${escapeHtml(sup.notes)}</p>`;
      });
    }

    if(hasContent) blocks.push({level:1, sectionKey:'gen-installation-'+inst.id, title:titleText||('מתקן '+(idx+1)), html:instHtml});
  });

  return blocks;
}

function buildGeneralReportDetailsBlocks(){
  const rd = state.generalElectricalInspectionReport.reportDetails;
  // הוסרו: reportNumber/installationName/installationAddress/ownerOrClient — אלה כבר
  // מודפסים דרך meta.reportNumber/siteName/address/client (הבלוק הכללי של סעיף 01), אחרי
  // שהשדות הכפולים האלה הוסרו מהממשק כאן (v2.179). נוספו title/reportDate — היו עריכים
  // בממשק קודם אך מעולם לא הופיעו בהדפסה בכלל.
  const rows = [
    ['כותרת הדוח', rd.title], ['תאריך הדוח', rd.reportDate ? formatDateIL(rd.reportDate) : ''],
    ['מיקום הבדיקה', rd.location],
    ['לכבוד', rd.recipient], ['מלווה הבדיקה', rd.accompaniedBy],
    ['מבצע הבדיקה', rd.performedBy], ['תפקיד מבצע הבדיקה', rd.performerRole],
    ['שיטת הגנה', rd.protectionMethod]
  ].filter(r=>r[1]);
  if(!rows.length && !rd.generalNotes) return [];
  let html = `<h2>פרטים נוספים לדוח</h2>`;
  if(rows.length) html += `<table class="tinfo-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  if(rd.generalNotes) html += `<p style="font-size:12px;">${escapeHtml(rd.generalNotes)}</p>`;
  return [{level:1, sectionKey:'gen-details', title:'פרטים נוספים לדוח', html}];
}

// באג קריטי שנמצא (v2.183): testInstruments/inspectionItems/boards/finalCircuits/summaryRows
// היו עריכים במלואם בממשק (סעיפים 03/06/07/08/12), אך buildGeneralReportBlocks() המקורית
// כיסתה רק installations — שאר הסעיפים מעולם לא נכללו בהדפסה בכלל. פונקציה חדשה זו משלימה
// את החסר, לפי אותו דפוס פונקציונלי בדיוק כמו buildGeneralReportDetailsBlocks/
// buildGeneralElectricalSuppliesBlocks הסמוכות — לא נבנה מנגנון הדפסה מקביל.
// חולצה מ-buildGeneralInspectionExtrasBlocks לפונקציה גלובלית — כדי שתהיה נגישה גם מקוד
// ה-PDF של 5.2 בסדר המאוחד (buildGeneralReportBlocks, פונקציה נפרדת). מחשבת בעצמה את
// מצב ה-migration, לא צריכה פרמטרים חיצוניים. לא שכפול לוגיקה — המקור היחיד.
function buildSingleGenInspectionItemHtml(sec){
    const g = state.generalElectricalInspectionReport;
    const genMigration = g.migration || {};
    const insulationAlreadyMigrated = genMigration.insulationStatus === 'completed';
    const groundingAlreadyMigrated = genMigration.groundingStatus === 'completed';
    let title = sec.title, html = '';
    if(sec.kind === 'earthContinuity' && !groundingAlreadyMigrated){
      const ec = sec.earthContinuity;
      title = 'רציפות הארקה';
      const rows = [['תיאור', ec.description], ['נקודת מוצא', ec.fromPoint], ['נקודת יעד', ec.toPoint],
        ['ערך מדידה', ec.value?formatMeasurement(ec.value, ec.unit):''], ['ערך נדרש', ec.requiredValue], ['תוצאה', ec.result]].filter(r=>r[1]);
      if(rows.length){
        html = `<h2>${title}</h2><table class="tinfo-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(ec.notes) html += `<p style="font-size:12px;">${escapeHtml(ec.notes)}</p>`;
      }
    } else if(sec.kind === 'insulation' && !insulationAlreadyMigrated){
      title = 'התנגדות בידוד';
      const dataRows = (sec.insulationRows||[]).filter(r=>r.testName || r.value);
      if(dataRows.length){
        html = `<h2>${title}</h2><table><thead><tr><th>שם הבדיקה</th><th>ערך Riso</th><th>סטטוס</th><th>הערות</th></tr></thead><tbody>
          ${dataRows.map(r=>`<tr><td>${escapeHtml(r.testName||'')}</td><td>${escapeHtml((r.sign||'')+(r.value||'')+' '+(r.unit||''))}</td><td>${escapeHtml(r.status||'')}</td><td>${escapeHtml(r.notes||'')}</td></tr>`).join('')}
          </tbody></table>`;
      }
    } else if(sec.kind === 'rcd'){
      const rcd = sec.rcd;
      title = 'בדיקת ממסר פחת / מפסק מגן';
      const rows = [['מספר ציוד / מפסק', rcd.equipmentNumber], ['יצרן', rcd.manufacturer], ['סוג מפסק', rcd.breakerType],
        ['גודל מפסק', rcd.breakerSize], ['זרם הפעלה נקוב IΔn', rcd.idnValue?formatMeasurement(rcd.idnValue,rcd.idnUnit||'mA'):''],
        ['דגם', rcd.model], ['תוצאה כללית', rcd.generalResult]].filter(r=>r[1]);
      const testTableRows = [];
      GENERAL_RCD_TEST_TYPES.forEach(k=>{
        const t = rcd.tests[k];
        if(!t || !t.selected) return;
        ['positive','negative'].forEach(d=>{
          const dir = t[d];
          if(!dir || !dir.selected) return;
          if(!dir.current && !dir.time && !dir.result) return;
          testTableRows.push(`<tr><td>${escapeHtml(k)}</td><td>${d==='positive'?'(+)':'(−)'}</td><td>${dir.current?escapeHtml(formatMeasurement(dir.current,dir.currentUnit||'mA')):'—'}</td><td>${dir.time?escapeHtml(formatMeasurement(dir.time,dir.timeUnit||'ms')):'—'}</td><td>${escapeHtml(dir.result||'—')}</td></tr>`);
        });
      });
      if(rows.length || testTableRows.length || rcd.generalNotes){
        html = `<h2 style="margin:8px 0 4px;">${title}</h2>`;
        if(rows.length) html += `<table class="compact-results-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(testTableRows.length) html += `<table class="compact-results-table"><thead><tr><th>סוג בדיקה</th><th>כיוון</th><th>זרם בדיקה</th><th>זמן ניתוק</th><th>תוצאה</th></tr></thead><tbody>${testTableRows.join('')}</tbody></table>`;
        if(rcd.generalNotes) html += `<p style="font-size:12px; margin:3px 0;"><b>הערות:</b> ${escapeHtml(rcd.generalNotes)}</p>`;
      }
    } else if(sec.kind === 'leakageRelay'){
      const lr = sec.leakageRelay;
      title = 'ממסר זליגה / מפסק משולב פחת';
      const rows = [['מספר מפסק / שם מפסק', lr.breakerName], ['סוג התקן', lr.deviceType], ['זרם הפעלה מכוון IΔn', lr.idnValue?formatMeasurement(lr.idnValue,lr.idnUnit||'mA'):''],
        ['זמן הפעלה מכוון', lr.timeValue?formatMeasurement(lr.timeValue,lr.timeUnit||'ms'):''],
        ['גודל מפסק משולב', lr.combinedBreakerSize], ['שנאי זרם', lr.ctRatio], ['תוצאה כללית', lr.generalResult]].filter(r=>r[1]);
      const testTableRows = [];
      ['RAMP','0.5×IΔn','1×IΔn','5×IΔn'].forEach(k=>{
        const t = lr.tests[k];
        if(!t || !t.selected) return;
        ['positive','negative'].forEach(d=>{
          const dir = t[d];
          if(!dir || !dir.selected) return;
          if(!dir.current && !dir.time && !dir.result) return;
          testTableRows.push(`<tr><td>${escapeHtml(k)}</td><td>${d==='positive'?'(+)':'(−)'}</td><td>${dir.current?escapeHtml(formatMeasurement(dir.current,dir.currentUnit||'mA')):'—'}</td><td>${dir.time?escapeHtml(formatMeasurement(dir.time,dir.timeUnit||'ms')):'—'}</td><td>${escapeHtml(dir.result||'—')}</td></tr>`);
        });
      });
      const extraChecks = [];
      const vd = lr.voltageDropOnCommandDisconnect;
      if(vd && (vd.status || vd.notes)) extraChecks.push(['הפסקת המתח בעת ניתוק פיקוד', vd.status, vd.notes]);
      const lm = lr.loopMatchCheck;
      if(lm && (lm.loopValue || lm.status || lm.notes)) extraChecks.push(['התאמת כוונון זרם הפעלה לערך לולאת תקלה לאדמה', lm.status + (lm.loopValue?` (${escapeHtml(lm.loopValue)}Ω)`:''), lm.notes]);
      if(rows.length || testTableRows.length || extraChecks.length || lr.generalNotes){
        html = `<h2 style="margin:8px 0 4px;">${title}</h2>`;
        if(rows.length) html += `<table class="compact-results-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(testTableRows.length) html += `<table class="compact-results-table"><thead><tr><th>סוג בדיקה</th><th>כיוון</th><th>זרם בדיקה</th><th>זמן ניתוק</th><th>תוצאה</th></tr></thead><tbody>${testTableRows.join('')}</tbody></table>`;
        if(extraChecks.length) html += `<table class="tinfo-table">${extraChecks.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${r[1]}${r[2]?' — '+escapeHtml(r[2]):''}</td></tr>`).join('')}</table>`;
        if(lr.generalNotes) html += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(lr.generalNotes)}</p>`;
      }
    } else {
      title = sec.title || 'בדיקה נוספת';
      if(sec.customDescription || sec.customResult || sec.customNotes){
        html = `<h2>${escapeHtml(title)}</h2>`;
        if(sec.customDescription) html += `<p style="font-size:12px;">${escapeHtml(sec.customDescription)}</p>`;
        if(sec.customResult) html += `<table class="tinfo-table"><tr><td class="tinfo-label">תוצאה</td><td>${escapeHtml(sec.customResult)}</td></tr></table>`;
        if(sec.customNotes) html += `<p style="font-size:12px;">${escapeHtml(sec.customNotes)}</p>`;
      }
    }
    return { title, html };
}

function buildGeneralInspectionExtrasBlocks(){
  const g = state.generalElectricalInspectionReport;
  const blocks = [];

  // סעיף 03 — מכשירי בדיקה — הוסר כליל מההדפסה, לאותה סיבה בדיוק שהוסר ממסך העריכה
  // (v2.378): כפילות מלאה עם "מכשירי בדיקה:" שכבר מוצג בטבלת פרטי הבדיקה בעמוד השער עבור
  // כל סוגי הדוח (state.meta.testInstrumentsSelected, ראו buildCoverPage). לא נמחק
  // g.testInstruments כמבנה נתונים — רק בלוק ההדפסה שלו כאן.

  // סעיף 06 — סעיפי בדיקה (רציפות הארקה / התנגדות בידוד / ממסר פחת / מותאם אישית, כולל אפשרויות מתח גבוה)
  // חשוב: בידוד/רציפות מודפסים מכאן (legacy) *רק* אם התחום המתאים עדיין לא הומר בהצלחה
  // (g.migration.insulationStatus/groundingStatus !== 'completed') — לפי דרישה מפורשת
  // "PDF צריך להשתמש ב-Canonical בלבד... אם נטען דוח Legacy שלא עבר conversion, לשמור
  // עליו ולא להעלים מידע". אם כן הומר, הנתונים כבר מודפסים מה-canonical (per-installation,
  // תמיד מודפס ללא תלות כאן) — הדפסה נוספת מכאן הייתה יוצרת כפילות בפועל ב-PDF עצמו.
  (g.inspectionItems||[]).forEach((sec)=>{
    const { title, html } = buildSingleGenInspectionItemHtml(sec);
    if(html) blocks.push({level:1, sectionKey:'gen-inspitem-'+sec.id, title, html});
  });

  // סעיף 07 — רישום ובדיקת לוחות חשמל
  if(g.boards && g.boards.enabled){
    const rows = (g.boards.rows||[]).filter(r=>r.circuitName || r.circuitNo);
    const notesBlock = printSectionNotesBlock(g.boards.notes);
    if(rows.length || notesBlock){
      let html = '';
      if(rows.length){
        html = `<h2>רישום ובדיקת לוחות חשמל</h2><table><thead><tr><th>מס' מעגל</th><th>שם המעגל</th><th>יעד</th><th>גודל מפסק</th><th>סוג מפסק</th><th>חתך כבל</th><th>סוג כבל</th><th>סוג בידוד</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>
        ${rows.map(r=>`<tr><td>${escapeHtml(r.circuitNo||'')}</td><td>${escapeHtml(r.circuitName||'')}</td><td>${escapeHtml(r.destination||'')}</td><td>${escapeHtml(r.breakerSize||'')}</td><td>${escapeHtml(r.breakerType||'')}</td><td>${escapeHtml(r.cableCrossSection||'')}</td><td>${escapeHtml(r.cableType||'')}</td><td>${escapeHtml(r.insulationType||'')}</td><td>${escapeHtml(r.result||'')}</td><td>${escapeHtml(r.notes||'')}</td></tr>`).join('')}
        </tbody></table>`;
      } else {
        html = `<h2>רישום ובדיקת לוחות חשמל</h2>`;
      }
      blocks.push({level:1, sectionKey:'gen-boards', title:'רישום ובדיקת לוחות חשמל', html: html + notesBlock});
    }
  }

  // סעיף 08 — בדיקת מעגלים סופיים
  if(g.finalCircuits && g.finalCircuits.enabled){
    const rows = (g.finalCircuits.rows||[]).filter(r=>r.description || r.circuitNo);
    const notesBlock = printSectionNotesBlock(g.finalCircuits.notes);
    if(rows.length || notesBlock){
      let html = '';
      if(rows.length){
        html = `<h2>בדיקת מעגלים סופיים</h2><table><thead><tr><th>מס' מעגל</th><th>תיאור</th><th>מפסק</th><th>כבל</th><th>לולאת תקלה</th><th>בידוד</th><th>רציפות הארקה</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>
        ${rows.map(r=>`<tr><td>${escapeHtml(r.circuitNo||'')}</td><td>${escapeHtml(r.description||'')}</td><td>${escapeHtml(r.breaker||'')}</td><td>${escapeHtml(r.cable||'')}</td><td>${escapeHtml(r.loopImpedance||'')}</td><td>${escapeHtml(r.insulation||'')}</td><td>${escapeHtml(r.earthContinuity||'')}</td><td>${escapeHtml(r.result||'')}</td><td>${escapeHtml(r.notes||'')}</td></tr>`).join('')}
        </tbody></table>`;
      } else {
        html = `<h2>בדיקת מעגלים סופיים</h2>`;
      }
      blocks.push({level:1, sectionKey:'gen-finalcircuits', title:'בדיקת מעגלים סופיים', html: html + notesBlock});
    }
  }

  // סעיף 10 — פירוט כללי והסתייגויות
  const notesParas = (g.generalNotesSection && g.generalNotesSection.paragraphs || []).filter(Boolean);
  if(notesParas.length){
    blocks.push({level:1, sectionKey:'gen-notes', title:'פירוט כללי והסתייגויות', html:
      `<h2>פירוט כללי והסתייגויות</h2>${notesParas.map(p=>`<p style="font-size:12px;">${escapeHtml(p)}</p>`).join('')}`});
  }

  // סעיף 11 — מסקנות: היה קיים ועובד בטופס העריכה (g.conclusionKey/GENERAL_CONCLUSION_OPTIONS)
  // אך מעולם לא הודפס בפועל — אותו דפוס באג שכבר תוקן כמה פעמים באותו דוח (למשל סוג מפסק
  // ב-v2.334). לפי קובץ ייחוס אמיתי: תיבה נפרדת בכותרת "מסקנות".
  const concOpt = GENERAL_CONCLUSION_OPTIONS.find(o=>o.key===g.conclusionKey);
  const concText = g.conclusionKey==='free' ? g.conclusionFreeText : (concOpt ? concOpt.text : '');
  if(concText){
    blocks.push({level:1, sectionKey:'gen-conclusion', title:'מסקנות', html:
      `<h2>מסקנות</h2><p style="font-size:13px; font-weight:700;">${escapeHtml(concText)}</p>`});
  }

  // סעיף 12 — טבלת סיכום
  const summaryRows = (g.summaryRows||[]).filter(r=>r.description);
  if(summaryRows.length){
    blocks.push({level:1, sectionKey:'gen-summary', title:'טבלת סיכום', html:
      `<h2>טבלת סיכום</h2><table><thead><tr><th>תיאור</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>
      ${summaryRows.map(r=>`<tr><td>${escapeHtml(r.description||'')}</td><td>${escapeHtml(r.result||'')}</td><td>${escapeHtml(r.notes||'')}</td></tr>`).join('')}
      </tbody></table>`});
  }

  return blocks;
}

function buildGeneralElectricalSuppliesBlocks(){
  const es = state.generalElectricalInspectionReport.electricalSupplies;
  const blocks = [];
  if(!es.enabled) return blocks;
  es.items.forEach((supply, si)=>{
    const rows = [
      ['שם לוח', supply.boardName], ['מיקום הלוח', supply.boardLocation], ['מספר תא', supply.cellNumber],
      ['סוג הלוח', supply.boardType], ['מספר עבודה', supply.workNumber],
      ['תקן הלוח', supply.boardStandard], ['מערכת החלפה', supply.changeoverSystem.type],
      ['מספר כבלים במקביל', supply.parallelCables],
      ['שטח חתך כבל', supply.crossSection ? (supply.crossSection==='אחר'?supply.crossSectionOther:supply.crossSection)+' mm²' : ''],
      ['סוג הכבל', supply.cableType==='אחר'?supply.cableTypeOther:supply.cableType],
      ['מספר מוליכי הארקה במקביל', supply.parallelGroundConductors],
      ['שטח חתך מוליך הארקה', supply.groundCrossSection ? (supply.groundCrossSection==='אחר'?supply.groundCrossSectionOther:supply.groundCrossSection)+' mm²' : ''],
      ['סוג מוליך הארקה', supply.groundConductorType==='אחר'?supply.groundConductorTypeOther:supply.groundConductorType],
      ['מספר מעגל', supply.circuitNumber], ['מספר קטבים', supply.mainBreakerPoles],
      ['גודל מפסק ראשי (In)', supply.mainBreakerSize ? supply.mainBreakerSize+'A' : ''],
      ['סוג מפסק ראשי', supply.mainBreakerType], ['שם יצרן המפסק', supply.breakerManufacturer],
      ['גילוי', supply.detection.status ? supply.detection.status + (supply.detection.notes ? ' — '+supply.detection.notes : '') : ''],
      ['ניתוק', supply.disconnection.status ? supply.disconnection.status + (supply.disconnection.notes ? ' — '+supply.disconnection.notes : '') : ''],
      ['כיבוי', supply.fireSuppression.status ? supply.fireSuppression.status + (supply.fireSuppression.notes ? ' — '+supply.fireSuppression.notes : '') : '']
    ].filter(r=>r[1]);

    const activeProts = GENERAL_BREAKER_PROTECTION_KEYS.filter(k=>supply.breakerProtections[k].active).map(k=>{
      const p = supply.breakerProtections[k];
      let txt = GENERAL_BREAKER_PROTECTION_LABELS[k];
      if(p.value) txt += `: ${escapeHtml(p.value)}${p.unit}`;
      if(p.delay) txt += ` (${escapeHtml(p.delay)}${p.delayUnit})`;
      return txt;
    });

    let html = `<h2>${escapeHtml(supply.boardName || supply.title)}</h2>`;
    if(rows.length) html += `<table class="tinfo-table">${rows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    if(activeProts.length) html += `<p style="font-size:12px;"><b>הגנות מפסק:</b> ${activeProts.join(', ')}</p>`;

    if(supply.powerSourceEnabled){
      const ps = supply.powerSource;
      const psRows = [
        ['תיאור', ps.description], ['מספר מעגל', ps.circuitNumber],
        ['גודל מפסק (In)', ps.breakerSize ? ps.breakerSize+'A' : ''], ['מספר קטבים', ps.poles],
        ['סוג מפסק', ps.breakerType], ['יצרן', ps.manufacturer]
      ].filter(r=>r[1]);
      if(psRows.length) html += `<h3 style="font-size:12px;">מקור הזנה</h3><table class="tinfo-table">${psRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
    }

    if(supply.secondaryBreakerEnabled){
      const sb = supply.secondaryBreaker;
      const sbRows = [
        ['גודל', sb.size], ['סוג', sb.type], ['יצרן', sb.manufacturer], ['דגם', sb.model],
        ['מספר קטבים', sb.poles], ['זרם נקוב', sb.ratedCurrent], ['הגנות', sb.protections]
      ].filter(r=>r[1]);
      if(sbRows.length) html += `<h3 style="font-size:12px;">מפסק משני</h3><table class="tinfo-table">${sbRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
      if(sb.notes) html += `<p style="font-size:12px;">${escapeHtml(sb.notes)}</p>`;
    }

    if(supply.cableEarthMatchEnabled && (supply.cableEarthMatchCriterion || supply.cableEarthMatchResult)){
      html += `<p style="font-size:12px;"><b>התאמת כבל הזנה/הארקה:</b> ${escapeHtml(supply.cableEarthMatchCriterion)} ${supply.cableEarthMatchResult?'— '+escapeHtml(supply.cableEarthMatchResult):''}</p>`;
    }

    const loopRows = GENERAL_LOOP_TEST_POINTS.filter(p=>supply.loopTests[p].selected && supply.loopTests[p].Z).map(p=>{
      const lt = supply.loopTests[p];
      return `<tr><td>${p}</td><td>${escapeHtml(lt.Z)} ${lt.ZUnit}</td><td>${lt.Isc?escapeHtml(lt.Isc)+' '+lt.IscUnit:'—'}</td><td>${escapeHtml(lt.status)||'—'}</td><td>${escapeHtml(lt.notes)}</td></tr>`;
    });
    if(loopRows.length) html += `<h3 style="font-size:12px;">בדיקות לולאת תקלה</h3><table><thead><tr><th>נקודה</th><th>Z</th><th>Isc</th><th>סטטוס</th><th>הערות</th></tr></thead><tbody>${loopRows.join('')}</tbody></table>`;

    if(supply.notes) html += `<p style="font-size:12px;">${escapeHtml(supply.notes)}</p>`;

    blocks.push({level:1, sectionKey:'gen-supply-'+si, title: supply.boardName || supply.title, html});
  });
  return blocks;
}

// ===== דוח בדיקת עמדת טעינה — פלט הדפסה, לפי סעיף 10 במפרט =====
function buildEvcsReportBlocks(){
  const blocks = [];
  const evcs = state.evcsReport;
  // "זנב" כל עמדה (ציוד בדיקה/הערות/ממצאים/סיכום/מסקנה) נאסף כאן במקום להיכנס ישירות לבלוק
  // של העמדה עצמה — לפי בקשה מפורשת: כל הסיכומים מרוכזים יחד בסוף הדוח, לא מפוזרים אחרי כל
  // עמדה בנפרד (מה שיצר בעבר עמודים כמעט-ריקים, רק עם טקסט הסיכום, בין העמדות).
  const summaryParts = [];

  // בלוק "פרטים נוספים לדוח" (מטרת הבדיקה/תקנים משותפים) הוסר לגמרי מפלט ה-PDF — לפי בקשה
  // מפורשת ("עמוד 2 תמיד ריק, תמחק את מה שקיים בו"). הנתונים עצמם עדיין ניתנים לעריכה בטופס
  // (לא הוסרו מהמודל), רק לא מודפסים יותר כעמוד נפרד כמעט-ריק.

  evcs.stations.forEach((st, si) => {
    if(!st.stationType) return; // עמדה בלי סוג נבחר לא מודפסת — אין מה להציג
    // כותרת ברורה לכל עמדה, כולל badge AC/DC — לפי בקשה מפורשת ("גם ב-PDF חייב להיות ברור
    // איזה סוג עמדה נבדקה")
    const title = `עמדה ${si+1} — ${st.stationType}`;
    let h = `<h2>${escapeHtml(title)}</h2>`;

    const stationRows = [
      ['יצרן', st.manufacturer], ['דגם', st.model], ['מספר סידורי', st.serialNo],
      ['שנת ייצור', st.yearOfManufacture], ['הספק נומינלי', st.ratedPower ? st.ratedPower+' '+st.ratedPowerUnit : ''],
      ['מתח נומינלי', st.ratedVoltage], ['זרם נומינלי', st.ratedCurrent],
      ['סוג Connector', st.connectorType], ['מספר שקעים/Connectors', st.numConnectors],
      ['IP Rating', st.ipRating], ['IK Rating', st.ikRating],
      ['מיקום התקנה', st.installLocation], ['Indoor/Outdoor', st.indoorOutdoor]
    ].filter(r=>r[1]);
    if(stationRows.length) h += printCompact2ColTable(stationRows, 'פרטי עמדה');
    if(st.systemDescription) h += `<p style="font-size:12px;"><b>תיאור מערכת:</b> ${escapeHtml(st.systemDescription)}</p>`;

    const supplyRows = [
      ['מקור הזנה', st.supply.supplySource], ['שם לוח מזין', st.supply.panelName], ['מספר מעגל', st.supply.circuitNumber],
      ['מתח', st.supply.voltage], ['זרם', st.supply.current], ['גודל חיבור', st.supply.connectionSize],
      ['סוג כבל', st.supply.cableType], ['חתך כבל', st.supply.cableCrossSection], ['מספר גידים', st.supply.conductorCount],
      ['אורך כבל', st.supply.cableLength], ['מוליך PE', st.supply.peConductor], ['חתך PE', st.supply.peCrossSection],
      ['שיטת הארקה', st.supply.groundingMethod], ['שיטת הגנה בפני חשמול', st.supply.shockProtectionMethod],
      ['אמצעי ניתוק', st.supply.disconnectMeans],
      ['מפסק ההזנה — זרם נקוב', st.supply.supplyBreaker.ratedCurrent], ['מפסק ההזנה — יצרן', st.supply.supplyBreaker.manufacturer],
      ['מפסק מגן במעלה הזינה — זרם נקוב', st.supply.upstreamBreaker.ratedCurrent], ['מפסק מגן במעלה הזינה — יצרן', st.supply.upstreamBreaker.manufacturer]
    ].filter(r=>r[1]);
    if(supplyRows.length) h += printCompact2ColTable(supplyRows, 'פרטי הזנה');

    if(st.stationType === 'AC'){
      h += printEvcsChecklistTable2Col(EV_DC_VISUAL_ITEMS_TEXT, st.ac.visualInspection, 'בדיקה ויזואלית');
      const pe = st.ac.peContinuity.groundContinuity;
      if(pe.value) h += printCompact2ColTable([['נקודת מדידה', pe.measurementPoint], ['ערך (Ω)', pe.value], ['תוצאה', pe.result]].filter(r=>r[1]), 'רציפות מוליך הגנה PE');
      const ir = st.ac.insulationResistance;
      if(ir.r30 || ir.testVoltage) h += printCompact2ColTable([['מתח בדיקה', ir.testVoltage], ['R 30 שנ׳ (MΩ)', ir.r30]].filter(r=>r[1]), 'התנגדות בידוד');
      if(st.ac.rcdTest.manufacturer || st.ac.rcdTest.deviceType) h += printCompact2ColTable([['יצרן', st.ac.rcdTest.manufacturer], ['דגם', st.ac.rcdTest.model], ['סוג התקן', st.ac.rcdTest.deviceType], ['זרם דלף מדורג (mA)', st.ac.rcdTest.iDeltaN]].filter(r=>r[1]), 'RCD');
      if(st.ac.rdcDdTest.manufacturer) h += printCompact2ColTable([['יצרן', st.ac.rdcDdTest.manufacturer], ['זרם ניתוק מוגדר (mA)', st.ac.rdcDdTest.setTripCurrent]].filter(r=>r[1]), 'RDC-DD / הגנת 6mA DC');
      if(st.ac.residualRelayTest.relayManufacturer) h += printCompact2ColTable([['יצרן ממסר', st.ac.residualRelayTest.relayManufacturer], ['זרם מוגדר (mA)', st.ac.residualRelayTest.relaySetCurrent]].filter(r=>r[1]), 'ממסר זליגה עם שנאי מסכם');
      if(st.ac.itImdTest.relevant === 'כן') h += printCompact2ColTable([['יצרן', st.ac.itImdTest.manufacturer], ['סף התראה 1 (Ω)', st.ac.itImdTest.threshold1]].filter(r=>r[1]), 'שיטת IT / IMD');
      // בדיקות פונקציונליות EVSE ו-Connector/Cable הוסרו לגמרי — לא נדרשים, לפי בקשה מפורשת
      if(st.ac.simulatorTest.used === 'כן') h += printCompact2ColTable([['תוצאה', st.ac.simulatorTest.result]].filter(r=>r[1]), 'בדיקות באמצעות Simulator');
      if((st.ac.standards.selected||[]).length) h += `<p style="font-size:12px;"><b>תקנים (AC):</b> ${escapeHtml(st.ac.standards.selected.join(', '))}</p>`;
    } else { // DC
      const dcRows = [['סוג Connector', st.dc.connectorDetails.type], ['מספר', st.dc.connectorDetails.count]].filter(r=>r[1]);
      if(dcRows.length) h += printCompact2ColTable(dcRows, 'פרטי Connector');
      if(st.dc.generalProtections.notes) h += `<p style="font-size:12px;"><b>הגנות כלליות:</b> ${escapeHtml(st.dc.generalProtections.notes)}</p>`;
      h += printEvcsChecklistTable(EVCS_DC_BASIC_VISUAL_ITEMS_TEXT, st.dc.basicVisualChecklist, 'בדיקה ויזואלית בסיסית');
      h += `<p style="font-size:11.5px; color:#666; font-style:italic;">בדיקות ייעודיות לעמדת טעינה DC יוגדרו בשלב הבא.</p>`;
    }

    // תמונות העמדה — מודפסות כאן, מתחת לנתוני העמדה עצמה, לא בסעיף גלובלי משותף בסוף הדוח —
    // לפי בקשה מפורשת.
    h += printEvcsStationPhotos(st.photos, si+1);

    blocks.push({level:1, sectionKey:`evcs-station-${si}`, title, html:h});

    // בונים את "זנב" הסיכום של העמדה הזו בנפרד — יתווסף בבלוק המרוכז בסוף, לא כאן
    const hasSummaryContent = (st.equipmentUsed||[]).length || st.notes || (st.findings||[]).some(f=>f&&f.trim()) || st.summaryText || st.conclusion.status || st.conclusion.freeText;
    if(hasSummaryContent){
      let sh = `<h3 style="font-size:14px; margin-top:20px;">${escapeHtml(title)}</h3>`;
      if((st.equipmentUsed||[]).length) sh += `<p style="font-size:12px;"><b>ציוד בדיקה:</b> ${escapeHtml(st.equipmentUsed.join(', '))}</p>`;
      if(st.notes) sh += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(st.notes)}</p>`;
      if((st.findings||[]).filter(f=>f&&f.trim()).length) sh += `<p style="font-size:12px;"><b>ממצאים:</b></p>` + st.findings.filter(f=>f&&f.trim()).map((f,fi)=>`<p style="font-size:12px; margin:2px 0;">${si+1}.${fi+1}. ${escapeHtml(f)}</p>`).join('');
      if(st.summaryText) sh += `<p style="font-size:12px;"><b>סיכום:</b> ${escapeHtml(st.summaryText)}</p>`;
      if(st.conclusion.status) sh += `<p style="font-size:12px; font-weight:600;">מסקנה: ${escapeHtml(st.conclusion.status)}</p>`;
      if(st.conclusion.freeText) sh += `<p style="font-size:12px;">${escapeHtml(st.conclusion.freeText)}</p>`;
      summaryParts.push(sh);
    }
  });

  // בלוק סיכום מרוכז אחד, אחרי כל העמדות — לפי בקשה מפורשת. כותרת עליונה "סיכום כללי", ואז
  // כל עמדה עם כותרת-משנה ברורה משלה (עמדה N — AC/DC) ותוכן הסיכום שלה, ברצף.
  if(summaryParts.length){
    blocks.push({level:1, sectionKey:'evcs-summary-all', title:'סיכום', html:`<h2>סיכום כללי</h2>${summaryParts.join('')}`});
  }

  return blocks;
}
// עוזר טבלת צ'קליסט להדפסה — תבנית "כותרת בתוך thead" הבטוחה (אותה תבנית מוכחת שתוקנה
// עבור MAIN_PANEL ב-v2.229-234, מונעת מראש את באג הפרדת כותרת-מנתונים)
function printEvcsChecklistTable(textArray, dataArray, title){
  if(!dataArray || !dataArray.some(d=>d && d.status)) return '';
  const rows = textArray.map((label,i)=>{
    const d = dataArray[i];
    if(!d || !d.status) return null;
    const note = d.notes || '';
    const noteHtml = note ? `<div class="compact-check-note">${escapeHtml(note)}</div>` : '';
    return {
      labelHtml: `${escapeHtml(label)}${noteHtml}`,
      resultHtml: escapeHtml(MAIN_PANEL_STATUS_LABELS[d.status]||d.status),
      fullWidth: shouldUseFullWidthChecklistItem(label, note)
    };
  }).filter(Boolean);
  return buildCompactChecklistTable(rows, { itemTitle:'תיאור הבדיקה', resultTitle:'סטטוס', title });
}
// alias דק לתאימות לאחור — printEvcsChecklistTable כבר קומפקטית (2 פריטים בשורה) מאז שהורחבה
// לפי המפרט הגלובלי; לא כפל לוגיקה, רק שם ישן שממשיך לעבוד למי שעדיין קורא לו.
function printEvcsChecklistTable2Col(textArray, dataArray, title){
  return printEvcsChecklistTable(textArray, dataArray, title);
}
// הדפסת תמונות עמדה — מודפסות מתחת לנתוני העמדה עצמה (לא בסעיף גלובלי משותף), עם מספור
// לפי מספר העמדה (תמונה 1.1/1.2 לעמדה 1, 2.1/2.2 לעמדה 2), לפי בקשה מפורשת.
function printEvcsStationPhotos(photos, stationNum){
  const relevant = (photos||[]).filter(p=>p.dataUrl || p.cloudPath);
  if(!relevant.length) return '';
  const cards = relevant.map((p,pi)=>`
    <div style="border:3px solid #d4a63c; border-radius:8px; overflow:hidden; margin-bottom:14px; break-inside:avoid;">
      <div style="background:#f2f2f2; padding:5px 10px; font-size:12px; font-weight:700; color:#8a6d1e;">תמונה ${stationNum}.${pi+1}${p.title ? ` — ${escapeHtml(p.title)}` : ''}</div>
      <img src="${resolvePhotoSrc(p)}" data-cloudpath="${escapeAttr(p.cloudPath||'')}" style="width:100%; max-height:400px; object-fit:contain; display:block;">
      ${p.note && p.note.trim() ? `<p style="font-size:11.5px; padding:6px 10px; margin:0; background:#fff;">${escapeHtml(p.note)}</p>` : ''}
    </div>`).join('');
  return `<h3 style="font-size:13px; margin-top:16px;">תמונות עמדה ${stationNum}</h3>${cards}`;
}

function buildEvDcReportBlocks(photoCounter){
  const p2 = state.evDcReport.page2;
  const ed = p2.electricianDeclaration;
  const cd = p2.chargerDetails;
  const sd = p2.supplyDetails;
  const rcd = p2.residualCurrentProtection;
  const tc = p2.testConditions;
  const summary = computeEvDcSummary();
  const blocks = [];

  // Recipient / letter block
  const letterRows = [
    ['לכבוד', p2.recipient], ['לידי', p2.attentionTo], ['תאריך הבדיקה', p2.reportDate],
    ['מספר דוח', p2.reportNumber], ['שם האתר', p2.siteName], ['כתובת האתר', p2.siteAddress],
    ['מזמין העבודה', p2.customer], ['איש קשר', p2.contactPerson], ['מספר טלפון', p2.phone],
    ['מספר הזמנה/פרויקט', p2.projectNumber]
  ].filter(r=>r[1]);
  let recipientHtml = `<h2>פרטי הפנייה</h2>`;
  if(letterRows.length) recipientHtml += `<table class="tinfo-table">${letterRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  recipientHtml += `<p style="font-size:12px; margin-top:8px;">לבקשתך בדקתי את המתקן החשמלי המתואר להלן.</p>`;
  if(p2.installationDescription) recipientHtml += `<p style="font-size:12px;"><b>תיאור המתקן:</b> ${escapeHtml(p2.installationDescription)}</p>`;
  const testTypeDisplay = p2.testType === 'אחר' ? p2.testTypeOther : p2.testType;
  if(testTypeDisplay) recipientHtml += `<p style="font-size:12px;"><b>סוג הבדיקה:</b> ${escapeHtml(testTypeDisplay)}</p>`;
  blocks.push({level:1, sectionKey:'ev-recipient', title:'פרטי הפנייה', html:recipientHtml});

  // Electrician declaration
  let declHtml = `<h2>הצהרת החשמלאי המבצע</h2>
    <p style="font-size:12px; line-height:1.8;">הריני מצהיר כי המתקן בוצע בהתאם לכללי המקצוע, לחוק החשמל ולתקנותיו, לתקנים החלים ולהוראות היצרן, ובאחריות בעל רישיון מתאים.</p>`;
  const declRows = [
    ['שם החשמלאי', ed.name], ['סוג הרישיון', ed.licenseType], ['מספר רישיון', ed.licenseNo],
    ['שם החברה המבצעת', ed.companyName], ['תאריך', ed.date],
    ['הצהרת החשמלאי נמסרה ונחתמה', ed.declared]
  ].filter(r=>r[1]);
  if(declRows.length) declHtml += `<table class="tinfo-table">${declRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  if(ed.declared && ed.declared !== 'כן'){
    declHtml += `<p style="font-size:12px; color:#c67405; font-weight:700; background:#fdf1e0; padding:8px 10px; border-radius:6px;">⚠ הצהרת החשמלאי לא הושלמה או לא הוצגה.</p>`;
  }
  if(ed.signature) declHtml += `<div style="margin-top:10px;"><img src="${ed.signature}" style="max-width:220px; max-height:80px; border-bottom:1px solid #999;"><div style="font-size:11px; color:#666;">חתימה</div></div>`;
  // Overview: technical details + charger details + breakers + ground continuity, matching the sample report's single "עמדת טעינה" section
  const td = p2.technicalDetails;
  const ps = p2.protectionSystem;
  const sb = ps.supplyBreaker, ub = ps.upstreamBreaker, gc = ps.groundContinuity;
  const overviewRows1 = [
    ['מתח הזנה', td.supplyVoltage==='אחר'?td.supplyVoltageOther:td.supplyVoltage],
    ['גודל חיבור', td.connectionSize==='אחר'?td.connectionSizeOther:td.connectionSize],
    ['מקור הזנה', td.supplySource==='אחר'?td.supplySourceOther:td.supplySource],
    ['שיטת הגנה', td.protectionMethod],
    ['תיאור מערכת', td.systemDescription]
  ].filter(r=>r[1]);
  const overviewRows2 = [
    ['יצרן', cd.manufacturer], ['דגם', cd.model], ['מספר סידורי', cd.serialNo],
    ['הספק', cd.ratedPower ? formatMeasurement(cd.ratedPower, cd.ratedPowerUnit) : ''],
    ['תקן העמדה', cd.standard],
    ['סוג מחבר', cd.connectorType === 'אחר' ? cd.connectorTypeOther : cd.connectorType],
    ['חתך כבל (mm²)', cd.cableCrossSection], ['מוליך הארקה', cd.groundConductorNote]
  ].filter(r=>r[1]);
  const overviewRows3 = [
    ['מפסק ההזנה — יצרן', sb.manufacturer], ['מפסק ההזנה — זרם נקוב', sb.In?formatMeasurement(sb.In,sb.InUnit):''],
    ['מפסק מגן במעלה הזינה — יצרן', ub.manufacturer], ['מפסק מגן — זרם נקוב', ub.ratedCurrent?formatMeasurement(ub.ratedCurrent,ub.ratedCurrentUnit):''],
    ['שיטת הגנה בעמדה', ub.installLocation]
  ].filter(r=>r[1]);
  const overviewRows4 = [
    ['נקודת מדידה', gc.measurementPoint], ['ערך', gc.value?formatMeasurement(gc.value,gc.unit):''],
    ['תוצאה', gc.result ? resultCheckmarkHtml(gc.result) : '']
  ].filter(r=>r[1]);
  let overviewHtml = `<h2>עמדת טעינה</h2>`;
  if(overviewRows1.length) overviewHtml += `<h3 style="font-size:13px;">פרטים טכניים</h3><table class="tinfo-table">${overviewRows1.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  if(overviewRows2.length) overviewHtml += `<h3 style="font-size:13px;">פרטי עמדת טעינה</h3><table class="tinfo-table">${overviewRows2.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  if(overviewRows3.length) overviewHtml += `<h3 style="font-size:13px;">מפסקים והגנות</h3><table class="tinfo-table">${overviewRows3.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  if(overviewRows4.length) overviewHtml += `<h3 style="font-size:13px;">רציפות הארקה</h3><table class="tinfo-table">${overviewRows4.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</table>`;
  blocks.push({level:1, sectionKey:'ev-overview', title:'עמדת טעינה', html:overviewHtml});

  // Visual inspection
  const visRows = p2.visualInspection.filter(v=>v.result).map(v=>`<tr style="background:${v.result==='תקין'?'#e8f5e9':(v.result==='לא תקין'?'#ffebee':'#f5f5f5')};">
    <td>${v.number}</td><td>${escapeHtml(v.description)}</td><td style="font-weight:700;">${escapeHtml(v.result)}</td>
    <td>${escapeHtml(v.severity)}</td><td>${escapeHtml(v.notes)}</td>
  </tr>`).join('');
  if(visRows) blocks.push({level:1, sectionKey:'ev-visual', title:'בדיקה ויזואלית ובדיקת התאמה', html:`<h2>בדיקה ויזואלית ובדיקת התאמה</h2><table><thead><tr><th>מס'</th><th>תיאור</th><th>תוצאה</th><th>חומרה</th><th>הערות</th></tr></thead><tbody>${visRows}</tbody></table>`});

  // Riso
  const ir = p2.insulationResistance;
  const irAmbientTemp = parseFloat(ir.ambientTemp);
  const risoRows = ir.rows.filter(r=>r.testPoint || r.value).map(r=>{
    const valMO = convertToMegaOhm(r.value, r.unit);
    const correctedMO = (!isNaN(valMO) && !isNaN(irAmbientTemp)) ? correctInsulationForTemperature(valMO, irAmbientTemp) : null;
    return `<tr>
    <td>${escapeHtml(r.testPoint)}</td><td>${r.value?formatInsulationValue(r.value,r.unit):''}</td>
    <td>${correctedMO !== null ? correctedMO.toFixed(2)+' MΩ' : '—'}</td>
    <td>${r.minRequired?formatMeasurement(r.minRequired,r.minRequiredUnit):''}</td><td>${resultCheckmarkHtml(r.result)}</td><td>${escapeHtml(r.notes)}</td>
  </tr>`;
  }).join('');
  if(risoRows || ir.testMode){
    let html = `<h2>בדיקת התנגדות בידוד Riso</h2>`;
    if(risoRows) html += `<table><thead><tr><th>בדיקה</th><th>ערך</th><th>מתוקן ל-20°C</th><th>ערך מינימלי</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${risoRows}</tbody></table>`;
    if(ir.testMode==='dar'){
      const c = buildEvDcDarPiCalc(ir.r30, ir.r60, ir.darMin);
      if(c.hasReadings){
        const clr = c.hasMin ? (c.ok?'#2e7d32':'#c62828') : '#b8860b';
        html += `<p style="font-size:12px; color:${clr}; font-weight:600;">DAR = R60/R30 = ${c.value.toFixed(2)}${c.hasMin?(c.ok?' — תקין':' — לא תקין'):' — לא הוגדר סף מינימלי'}</p>`;
      }
    }
    if(ir.testMode==='pi'){
      const c = buildEvDcDarPiCalc(ir.r1min, ir.r10min, ir.piMin);
      if(c.hasReadings){
        const clr = c.hasMin ? (c.ok?'#2e7d32':'#c62828') : '#b8860b';
        html += `<p style="font-size:12px; color:${clr}; font-weight:600;">PI = R10min/R1min = ${c.value.toFixed(2)}${c.hasMin?(c.ok?' — תקין':' — לא תקין'):' — לא הוגדר סף מינימלי'}</p>`;
      }
    }
    blocks.push({level:1, sectionKey:'ev-riso', title:'בדיקת התנגדות בידוד Riso', html});
  }

  // Loop impedance
  const loopRows = p2.loopImpedance.rows.filter(r=>r.testPoint).map(r=>`<tr>
    <td>${escapeHtml(r.testPoint)}</td><td>${r.Z?formatMeasurement(r.Z,r.ZUnit):''}</td>
    <td>${r.Isc?formatMeasurement(r.Isc,r.IscUnit):''}</td><td>${resultCheckmarkHtml(r.result)}</td><td>${escapeHtml(r.notes)}</td>
  </tr>`).join('');
  if(loopRows) blocks.push({level:1, sectionKey:'ev-loop', title:'מדידת לולאת תקלה', html:`<h2>מדידת לולאת תקלה</h2><table><thead><tr><th>בדיקה</th><th>Z</th><th>Isc</th><th>תוצאה</th><th>הערות</th></tr></thead><tbody>${loopRows}</tbody></table>`});

  // Combined RCD / RDC-DD test table, matching the sample's single combined table
  const sel = ps.selectedProtectionTypes || [];
  const rcdRelevant2 = ['rcd','rccb','rcbo','typeAC','typeA','typeF','typeB','typeBplus','ev'].some(k=>sel.includes(k));
  const rdcDdRelevant2 = sel.includes('rdcDdInternal') || sel.includes('rdcDdExternal');
  if(rcdRelevant2 || rdcDdRelevant2){
    const rt = ps.rcdTest, rd = ps.rdcDdTest;
    const rcdCombRows = rcdRelevant2 ? rt.rows.map(r=>`<tr>
      <td>מפסק מגן במעלה הזינה</td><td>IΔn=${escapeHtml(rt.iDeltaN||'—')}${rt.iDeltaNUnit||''}</td>
      <td>${escapeHtml(r.multiplier)}</td><td>${r.testCurrent?formatMeasurement(r.testCurrent,r.testCurrentUnit):''}</td>
      <td>${r.tripTime?formatMeasurement(r.tripTime,r.tripTimeUnit):''}</td><td>${resultCheckmarkHtml(r.result)}</td>
    </tr>`).join('') : '';
    const rdcCombRows = rdcDdRelevant2 ? rd.rows.map(r=>`<tr>
      <td>התקן זליגה DC</td><td>IΔn=${escapeHtml(rd.setTripCurrent||'—')}${rd.setTripCurrentUnit||''}</td>
      <td>${escapeHtml(r.multiplier)}</td><td>${r.actualInjected?formatMeasurement(r.actualInjected,r.actualInjectedUnit):''}</td>
      <td>${r.responseTime?formatMeasurement(r.responseTime,r.responseTimeUnit):''}</td><td>${resultCheckmarkHtml(r.result)}</td>
    </tr>`).join('') : '';
    blocks.push({level:1, sectionKey:'ev-rcd-combined', title:'בדיקת מפסק מגן והתקן זליגה', html:`<h2>בדיקת מפסק מגן והתקן זליגה</h2>
      <table><thead><tr><th>תיאור בדיקה</th><th>IΔn/גודל</th><th>סוג בדיקה</th><th>זרם</th><th>זמן ניתוק</th><th>תוצאה</th></tr></thead>
      <tbody>${rcdCombRows}${rdcCombRows}</tbody></table>`});
  }

  // *** הצהרת החשמלאי הוסרה מכאן (הייתה מוצגת שוב, באמצע/סוף זרימת הדוח) — עברה
  // לעמוד 1 (buildCoverPage, דרך buildElectricianDeclarationBlock/getElectricianDeclarationData
  // המשותפים). אומת בפועל לפני התיקון: ההצהרה הופיעה פעמיים (גם בשער עם נתונים גנריים
  // שגויים, גם כאן עם הנתונים הנכונים) — declTitleOccurrencesInFullPrint===2. תוקן.

  // Conclusion2
  const autoC2 = computeEvDcAutoConclusion2(p2);
  const conclusionTexts2 = {
    ok: 'הריני מאשר כי בדקתי את עמדת הטעינה ואת המתקן המזין, ובבדיקות שבוצעו נמצאו תקינים בהתאם לקריטריונים שהוגדרו בדוח.',
    ok_cond: 'הריני מאשר את חיבור המתקן בתנאי, וזאת לאחר השלמת תיקון הליקויים המפורטים בדוח.',
    bad: 'המתקן אינו תקין ואינו ראוי לחיבור או להפעלה עד לתיקון הליקויים וביצוע בדיקה חוזרת.',
    undetermined: 'לא ניתן לקבוע תקינות מלאה מאחר שלא כל הבדיקות הנדרשות בוצעו או שחסרים נתונים מהותיים.'
  };
  const effC2Key = p2.conclusion2Key || autoC2;
  const effC2Text = p2.conclusion2CustomText || conclusionTexts2[effC2Key];
  let concHtml = `<h2>סיכום ומסקנה</h2><p style="font-size:12.5px; line-height:1.8;">${escapeHtml(effC2Text)}</p>`;
  blocks.push({level:1, sectionKey:'ev-conclusion2', title:'סיכום ומסקנה', html:concHtml});

  // Supply cable table
  if(p2.supplyCableRows.length){
    const rows = p2.supplyCableRows.map(c=>`<tr>
      <td>${escapeHtml(c.from)}</td><td>${escapeHtml(c.to)}</td><td>${escapeHtml(c.manufacturer)}</td>
      <td>${escapeHtml(c.type)}</td><td>${escapeHtml(c.material)}</td><td>${escapeHtml(c.conductorCount)}</td>
      <td>${escapeHtml(c.crossSection)}</td><td>${escapeHtml(c.length)}</td><td>${escapeHtml(c.installMethod)}</td>
      <td>${escapeHtml(c.ratedVoltage)}</td><td>${escapeHtml(c.groundConductor)}</td><td>${escapeHtml(c.condition)}</td>
      <td>${escapeHtml(c.notes)}</td>
    </tr>`).join('');
    blocks.push({level:1, sectionKey:'ev-cable', title:'נתוני כבל ההזנה', html:`<h2>נתוני כבל ההזנה</h2>
      <table><thead><tr>
        <th>FROM</th><th>TO</th><th>יצרן</th><th>סוג</th><th>מוליך</th><th>גידים</th>
        <th>חתך</th><th>אורך</th><th>התקנה</th><th>מתח נקוב</th><th>מוליך הארקה</th><th>מצב</th><th>הערות</th>
      </tr></thead><tbody>${rows}</tbody></table>`});
  }

  // Selected instruments — הוסר (v2.2.494): מכשירי הבדיקה מודפסים רק מהרשימה בסעיף 01 (עמוד השער)

  // Test conditions
  const condRows = [
    ['תאריך', tc.date], ['שעת התחלה', tc.startTime], ['שעת סיום', tc.endTime],
    ['טמפרטורת סביבה', tc.ambientTemp ? tc.ambientTemp + ' °C' : ''], ['לחות יחסית', tc.humidity ? tc.humidity + ' %' : ''],
    ['מזג אוויר', tc.weather], ['מצב הקרקע', tc.groundCondition], ['מצב העמדה בזמן הבדיקה', tc.stationCondition],
    ['העמדה הייתה מנותקת', tc.wasDisconnected], ['בוצעה נעילה ותיוג', tc.lockoutTagout],
    ['בוצעה בדיקת היעדר מתח', tc.voltageAbsenceTest], ['הערות', tc.notes]
  ].filter(r=>r[1]);
  let condHtml = `<h2>תנאי הבדיקה</h2>`;
  if(condRows.length) condHtml += `<table class="tinfo-table">${condRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
  blocks.push({level:1, sectionKey:'ev-conditions', title:'תנאי הבדיקה', html:condHtml});

  // Summary
  const summaryRows = [
    ['סוג הבדיקה', summary.testTypeDisplay], ['יצרן ודגם העמדה', summary.chargerMfgModel],
    ['מספר סידורי', summary.serialNo], ['הספק נקוב', summary.ratedPower], ['מתח כניסה', summary.inputVoltage],
    ['מתח יציאה מרבי', summary.outputVoltageMax], ['זרם יציאה מרבי', summary.outputCurrentMax],
    ['מקור ההזנה', summary.supplySource], ['מפסק ההזנה', summary.breakerSummary],
    ['כבל ההזנה', summary.cableSummary], ['מכשירי הבדיקה שנבחרו', summary.instrSummary]
  ].filter(r=>r[1]);
  blocks.push({level:1, sectionKey:'ev-summary', title:'סיכום נתוני עמוד 2', html:`<h2>סיכום נתוני עמוד 2</h2>
    <table class="tinfo-table">${summaryRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`});

  // Page 3 placeholder
  blocks.push({level:1, sectionKey:'ev-tests-placeholder', title:'מהלך הבדיקה של עמדת הטעינה DC', html:`<h2>מהלך הבדיקה של עמדת הטעינה DC</h2>
    <p style="font-size:12px; color:#666;">טבלאות הבדיקה המפורטות יתווספו בהמשך.</p>`});

  return blocks;
}

function buildDcCableReportBlocks(photoCounter){
  const dc = state.dcCableTest;
  const blocks = [];

  const introText = `בדוח זה מתועדות בדיקות בידוד וקוטביות של כבלי וגידי DC, שבוצעו במתח בדיקה ${escapeHtml(dc.testVoltage)||'____'} על גבי מערכת במתח ${escapeHtml(dc.systemVoltageDC)||'____'}. ערכי הבידוד נמדדו ביחידות ${escapeHtml(dc.unit)}, והושוו לערך המינימלי הנדרש שהוגדר לכל גיד.`;
  blocks.push({level:1, sectionKey:'dc-intro', title:'הקדמה', html:`<h2>הקדמה</h2><p style="font-size:12px; line-height:1.8;">${introText}</p>`});

  const testDataRows = [
    ['מתח המערכת DC', dc.systemVoltageDC], ['מתח הבדיקה', dc.testVoltage ? formatMeasurement(dc.testVoltage, dc.testVoltageUnit) : ''], ['זמן הבדיקה', dc.testTime],
    ['ערך בידוד מינימלי נדרש', dc.minInsulationRequired ? formatMeasurement(dc.minInsulationRequired, dc.unit) : ''],
    ['טמפרטורת סביבה', dc.ambientTemp], ['מזג אוויר', dc.weather], ['מצב הכבלים', dc.cableCondition],
    ['חומר מוליך', dc.conductorMaterial], ['סוג בידוד', dc.insulationType], ['מתח נקוב', dc.ratedVoltage],
    ['בדיקת DAR', dc.performDAR ? `פעילה — ערך מינימום נדרש: ${dc.darMin || '—'} (קריאות בפועל לכל גיד מפורטות בטבלאות הקבוצות)` : ''],
    ['בדיקת PI', dc.performPI ? `פעילה — ערך מינימום נדרש: ${dc.piMin || '—'} (קריאות בפועל לכל גיד מפורטות בטבלאות הקבוצות)` : '']
  ].filter(r => r[1]);
  if(testDataRows.length){
    const rows = testDataRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('');
    blocks.push({level:1, sectionKey:'dc-testdata', title:'נתוני הבדיקה', html:`<h2>נתוני הבדיקה</h2><table class="tinfo-table">${rows}</table>`});
  }

  dc.groups.forEach((g, gi) => {
    const rowsWithData = g.rows.filter(r => r.from || r.to || r.crossSection || r.visual || r.polarityResult || r.insulationPositive || r.insulationNegative);
    if(!rowsWithData.length && !g.title) return;
    const rowsHtml = rowsWithData.map((r, ri) => {
      const calc = buildDcCableRowResult(r);
      const color = calc.cls === 'dc-ok' ? '#e8f5ec' : (calc.cls === 'dc-bad' ? '#fbeae8' : '#fdf1e0');
      const darText = calc.darCalc ? (calc.darCalc.hasReadings ? calc.darCalc.dar.toFixed(2) : 'חסרות קריאות') : '—';
      const piText = calc.piCalc ? (calc.piCalc.hasReadings ? calc.piCalc.pi.toFixed(2) : 'חסרות קריאות') : '—';
      return `<tr style="background:${color};">
        <td>${ri+1}</td><td>${escapeHtml(r.from)}</td><td>${escapeHtml(r.to)}</td><td>${escapeHtml(r.crossSection)}</td><td>${escapeHtml(r.conductorCount)}</td>
        <td>${escapeHtml(r.type)}</td><td>${escapeHtml(r.visual)}</td>
        <td>${escapeHtml(r.polarityResult)}</td>
        <td>${escapeHtml(formatMeasurement(r.insulationPositive, r.insulationPositiveUnit))}</td>
        <td>${escapeHtml(formatMeasurement(r.insulationNegative, r.insulationNegativeUnit))}</td>
        <td>${escapeHtml(formatMeasurement(r.minRequired, r.minRequiredUnit))}</td>
        <td>${darText}</td><td>${piText}</td>
        <td style="font-weight:700;">${escapeHtml(calc.result)}</td>
        <td>${escapeHtml(r.notes)}</td>
      </tr>`;
    }).join('');
    const groupInfoRows = [
      ['תיאור המקטע', g.description], ['מקור כללי', g.generalSource], ['יעד כללי', g.generalDest],
      ['מתח מערכת', g.systemVoltage], ['מספר גידים', g.numConductors]
    ].filter(r=>r[1]).map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('');
    let html = `<h2>קבוצת בדיקה ${gi+1}${g.title ? ': ' + escapeHtml(g.title) : ''}</h2>`;
    if(groupInfoRows) html += `<table class="tinfo-table">${groupInfoRows}</table>`;
    if(g.notes) html += `<p style="font-size:12px;">${escapeHtml(g.notes)}</p>`;
    if(rowsHtml){
      html += `<table><thead><tr>
        <th>מס'</th><th>FROM</th><th>TO</th><th>שטח חתך הכבל</th><th>כמות גידים</th><th>סוג הכבל</th>
        <th>ויזואלית</th><th>קוטביות</th><th>בידוד גיד חיובי (+)</th><th>בידוד גיד שלילי (−)</th>
        <th>ערך מינימום נדרש</th><th>DAR</th><th>PI</th><th>תוצאה</th><th>הערות</th>
      </tr></thead><tbody>${rowsHtml}</tbody></table>`;
    }
    blocks.push({level:1, sectionKey:'dc-group-'+gi, title:'קבוצת בדיקה ' + (gi+1), html});
  });

  const summary = computeDcCableSummary();
  const summaryRows = [
    ['מספר גידים שנבדקו', summary.totalRows], ['גידים תקינים', summary.ok], ['גידים לא תקינים', summary.bad],
    ['גידים שלא נבדקו / לא ניתן לקבוע', summary.untested], ['בדיקות קוטביות תקינות', summary.polarityOk],
    ['בדיקות קוטביות לא תקינות', summary.polarityBad],
    ['ערך בידוד נמוך ביותר שנמדד', summary.minVal!==null?summary.minVal.toFixed(2):'—'],
    ['ערך בידוד גבוה ביותר שנמדד', summary.maxVal!==null?summary.maxVal.toFixed(2):'—'],
    ['ממוצע ערכי בידוד', summary.avgVal!==null?summary.avgVal.toFixed(2):'—'],
    ['מספר ליקויים ויזואליים', summary.visualBad]
  ];
  const summaryHtml = summaryRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${r[1]}</td></tr>`).join('');
  blocks.push({level:1, sectionKey:'dc-summary', title:'סיכום אוטומטי', html:`<h2>סיכום אוטומטי</h2><table class="tinfo-table">${summaryHtml}</table>`});

  if(dc.findings.length){
    const findingsHtml = dc.findings.map(f=>`
      <div style="margin-bottom:10px; padding:8px 10px; border:1px solid #ccc; border-radius:6px;">
        <b>${f.number}</b> — ${escapeHtml(f.description)}<br>
        <span style="font-size:11px; color:#666;">חומרה: ${escapeHtml(f.severity)||'—'} | סטטוס: ${escapeHtml(f.status)||'—'}</span>
        ${f.recommendation ? `<p style="font-size:12px; margin:4px 0 0;">המלצה: ${escapeHtml(f.recommendation)}</p>` : ''}
      </div>`).join('');
    blocks.push({level:1, sectionKey:'dc-findings', title:'סיכום וממצאים', html:`<h2>סיכום וממצאים</h2>${findingsHtml}`});
  }

  const auto = computeDcCableAutoConclusion();
  const effectiveKey = dc.conclusionOverride && dc.conclusionKey ? dc.conclusionKey : auto;
  const conclusionObj = DC_CONCLUSION_OPTIONS.find(o=>o.key===effectiveKey);
  let conclusionHtml = `<h2>מסקנה</h2><p style="font-size:12.5px; line-height:1.8;">${escapeHtml(conclusionObj.text)}</p>`;
  if(dc.conclusionOverride && dc.conclusionJustification){
    conclusionHtml += `<p style="font-size:12px;"><b>נימוק לשינוי המסקנה:</b> ${escapeHtml(dc.conclusionJustification)}</p>`;
  }
  blocks.push({level:1, sectionKey:'dc-conclusion', title:'מסקנה', html:conclusionHtml});

  const disclaimersHtml = `<h2>הסתייגויות</h2>
    <p style="font-size:12px;">תוקפו של דוח זה נכון למועד הבדיקה בלבד. הבודק אינו אחראי לשינויים, חיבורים, נזקים או עבודות שבוצעו לאחר מועד הבדיקה ושלא בידיעתו או באישורו.</p>
    <p style="font-size:12px;">הבדיקה מתייחסת לכבלים ולגידים המפורטים בדוח בלבד, ובהתאם למצבם ולתנאי הבדיקה במועד ביצועה.</p>`;
  blocks.push({level:1, sectionKey:'dc-disclaimers', title:'הסתייגויות', html:disclaimersHtml});

  const sigBlock = (name, role, license, date, sig, roleLabel) => `
    <div style="display:inline-block; width:48%; vertical-align:top; margin-left:2%;">
      <div style="font-size:12px; margin-bottom:4px;"><b>${roleLabel}</b></div>
      ${name ? `<div style="font-size:12px;">שם: ${escapeHtml(name)}</div>` : ''}
      ${role ? `<div style="font-size:12px;">תפקיד: ${escapeHtml(role)}</div>` : ''}
      ${license ? `<div style="font-size:12px;">מס' רישיון: ${escapeHtml(license)}</div>` : ''}
      ${date ? `<div style="font-size:12px;">תאריך: ${formatDateIL(date)}</div>` : ''}
      <div style="margin-top:10px;">
        ${sig ? `<img src="${sig}" style="max-width:220px; max-height:80px; border-bottom:1px solid #999;">` : `<div style="border-bottom:1px solid #333; height:60px; width:220px;"></div>`}
        <div style="font-size:11px; color:#666; margin-top:2px;">חתימה</div>
      </div>
    </div>`;
  const signaturesHtml = `<h2>חתימות</h2>
    ${sigBlock(dc.testerName, dc.testerRole, dc.testerLicenseNo, dc.testerDate, dc.testerSignature, 'הבודק')}
    ${sigBlock(dc.clientRepName, dc.clientRepRole, '', dc.clientRepDate, dc.clientRepSignature, 'נציג המזמין')}`;
  blocks.push({level:1, sectionKey:'dc-signatures', title:'חתימות', html:signaturesHtml});

  return blocks;
}

function buildGroundingReportBlocks(photoCounter){
  const gt = state.groundingTest;
  // *** routing לפי testMethod — המקום היחיד בפונקציה הזו שנדרש שינוי. clamp/selective
  // מואצלים לגמרי לפונקציה נפרדת (buildGroundingClampOrSelectiveReportBlocks) — שאר
  // הפונקציה הזו (זרימת slope) לא נגעה בה בכלל, ממשיכה בדיוק כפי שהייתה.
  if(gt.testMethod === 'clamp' || gt.testMethod === 'selective'){
    return buildGroundingClampOrSelectiveReportBlocks(gt);
  }
  const blocks = [];

  const introText = `הבדיקה בוצעה בשיטת שיפוע (Fall of Potential, המכונה גם שיטת 62%) למדידת התנגדות אלקטרודת ההארקה הנבדקת ביחס למסה הכללית של האדמה. יתד זרם הוצב במרחק ${escapeHtml(gt.currentStakeDistance||'____')} מ' מהאלקטרודה, ויתד הפוטנציאל נמדד בשלוש נקודות — 52%, 62% (ערך עיקרי) ו-72% ממרחק זה — לצורך אימות אמינות המדידה.`;
  blocks.push({level:1, sectionKey:'ground-intro', title:'הקדמה', html:`<h2>הקדמה</h2><p style="font-size:12px; line-height:1.8;">${introText}</p>`});

  // *** בלוק חדש: "עקרון הבדיקה" — הועבר מעמוד השער (coverExplanation, ראו buildCoverPage)
  // לעמוד 2, לפי דרישה מפורשת: "אין להציג בעמוד השער תוכן מקצועי הקשור לשיטת הבדיקה".
  // אותו טקסט בדיוק, רק במיקום חדש. ממוקם מיד אחרי "הקדמה" ולפני "פרטי הבדיקה", לפי
  // הסדר המבוקש: הקדמה -> עקרון הבדיקה -> פרטי הבדיקה -> מסמכי ייחוס -> בדיקות.
  const principleText = 'בדיקה זו בוחנת את איכות מערכת ההארקה על ידי מדידת ההתנגדות של אלקטרודת הארקה בודדת ביחס למסה הכללית של האדמה, בשיטת Fall of Potential. תוצאה נמוכה מעידה על הארקה תקינה ובטוחה; תוצאה גבוהה עלולה להצביע על צורך בשיפור מערכת ההארקה.';
  blocks.push({level:1, sectionKey:'ground-principle', title:'עקרון הבדיקה', html:`<h2>עקרון הבדיקה</h2><p style="font-size:12px; line-height:1.8;">${escapeHtml(principleText)}</p>`});

  const infoRows = [
    gt.siteEquipmentName ? `<tr><td class="tinfo-label">שם המתקן/המבנה הנבדק</td><td>${escapeHtml(gt.siteEquipmentName)}</td></tr>` : '',
    gt.currentStakeDistance ? `<tr><td class="tinfo-label">מרחק יתד הזרם</td><td>${escapeHtml(gt.currentStakeDistance)} מ'</td></tr>` : '',
    gt.measurementPeriod ? `<tr><td class="tinfo-label">תקופת מדידה</td><td>${escapeHtml(gt.measurementPeriod)}</td></tr>` : '',
    gt.maxAllowedResistance ? `<tr><td class="tinfo-label">ערך התנגדות מרבי מותר (Rmax)</td><td>${escapeHtml(gt.maxAllowedResistance)} Ω</td></tr>` : ''
  ].filter(Boolean).join('');
  if(infoRows){
    blocks.push({level:1, sectionKey:'ground-info', title:'פרטי הבדיקה והמכשיר', html:`<h2>פרטי הבדיקה והמכשיר</h2><table class="tinfo-table">${infoRows}</table>`});
  }

  const locsWithData = (gt.locations||[]).filter(l => l.name || l.readings.r52 || l.readings.r62 || l.readings.r72);

  const selectedGroundStandards = GROUNDING_STANDARDS.filter((_,i)=>gt.standardsOn[i]);
  if(selectedGroundStandards.length || gt.customDiagramImage){
    const stdRows = selectedGroundStandards.map(s=>`<tr><td class="tinfo-label"><span dir="ltr">${s.code}</span></td><td>${s.purpose}</td></tr>`).join('');
    let stdHtml = selectedGroundStandards.length ? `<h2>מסמכי ייחוס ותקנים</h2><table class="tinfo-table">${stdRows}</table>` : `<h2>מסמכי ייחוס ותקנים</h2>`;
    if(gt.customDiagramImage){
      stdHtml += `<div class="photo-box solo" style="margin-top:14px;"><img src="${gt.customDiagramImage}" alt="אופן ביצוע הבדיקה"><div class="photo-caption">אופן ביצוע הבדיקה</div></div>`;
    }
    blocks.push({level:1, sectionKey:'ground-standards', title:'מסמכי ייחוס ותקנים', html: stdHtml});
  }

  locsWithData.forEach(loc=>{
    const calc = buildGroundingReadingCalc(loc);
    const dist = parseFloat(gt.currentStakeDistance) || 0;
    const d52 = (dist*0.52).toFixed(1), d62 = (dist*0.62).toFixed(1), d72 = (dist*0.72).toFixed(1);
    const validReadings = [loc.readings.r52, loc.readings.r62, loc.readings.r72].map(v=>parseFloat(v)).filter(v=>!isNaN(v));
    const avgReading = validReadings.length ? validReadings.reduce((s,v)=>s+v,0)/validReadings.length : null;
    const readingRows = `
      <tr><td>52%</td><td>${d52} מ'</td><td>${escapeHtml(loc.readings.r52)} Ω</td></tr>
      <tr><td>62% (עיקרי)</td><td>${d62} מ'</td><td>${escapeHtml(loc.readings.r62)} Ω</td></tr>
      <tr><td>72%</td><td>${d72} מ'</td><td>${escapeHtml(loc.readings.r72)} Ω</td></tr>
      ${avgReading !== null ? `<tr><td colspan="2"><b>ממוצע 3 הקריאות</b></td><td><b>${avgReading.toFixed(2)} Ω</b></td></tr>` : ''}`;
    const title = loc.name || 'מיקום מדידה';
    // *** כרטיס בדיקה קומפקטי (slope-test-card) — עודכן להתאמה מדויקת לדוגמת עיצוב
    // שסופקה: גרף מוצג מימין (div גרף ראשון ב-HTML => מימין ב-RTL), נתונים/טבלה/חישוב
    // משמאל (48%|52%). כותרת-משנה נפרדת בתוך תיבת הגרף (לא בתוך ה-SVG עצמו).
    const dataColHtml = `<table><thead><tr><th>נקודת מדידה</th><th>מרחק בפועל</th><th>התנגדות נמדדת</th></tr></thead><tbody>${readingRows}</tbody></table>
      ${calc ? buildGroundingCalcTraceHtml(calc) : ''}`;
    const chartSvg = calc ? buildGroundingSlopeChartSvg(loc, gt.currentStakeDistance, false, calc.corrected) : '';
    const graphColHtml = chartSvg
      ? `<div class="slope-graph-box"><div class="slope-graph-title">${escapeHtml(title)} - בדיקה בשיטת שיפוע</div><div class="chart-preview">${chartSvg}</div></div>`
      : '';
    const html = `<div class="slope-test-card">
        <h3>${escapeHtml(title)}</h3>
        <div class="slope-test-grid">
          <div class="slope-test-graph">${graphColHtml}</div>
          <div class="slope-test-data">${dataColHtml}</div>
        </div>
      </div>`;
    blocks.push({level:1, sectionKey:'ground-loc-'+title, title, html});
  });

  if(gt.connectionPhotos && gt.connectionPhotos.length){
    blocks.push({level:1, sectionKey:'ground-connection', title:'תיעוד חיבור וביצוע', html:`<h2>תיעוד חיבור וביצוע</h2>${printPhotos(gt.connectionPhotos, photoCounter)}`});
    photoCounter += gt.connectionPhotos.length;
  }

  const anyValid = locsWithData.some(loc => { const c = buildGroundingReadingCalc(loc); return c && c.isValid; });
  let notesHtml = '';
  if(anyValid){
    const validResults = locsWithData.map(l=>buildGroundingReadingCalc(l)).filter(c=>c&&c.isValid).map(c=>c.corrected.toFixed(2)+' Ω').join(', ');
    notesHtml += `<p style="font-size:12px; background:#eaf7ec; border:1px solid #3fa34d; border-radius:6px; padding:8px 10px;">✓ בבדיקה נמצא שהערך הנמדד תקין. הערך שהתקבל: ${validResults} (מתחת לערך המרבי המותר: ${escapeHtml(gt.maxAllowedResistance)} Ω).</p>`;
  }
  if(gt.notes && gt.notes.trim()) notesHtml += `<p style="font-size:12px;">${escapeHtml(gt.notes)}</p>`;
  if(gt.notesPhotos && gt.notesPhotos.length){
    notesHtml += printPhotos(gt.notesPhotos, photoCounter);
    photoCounter += gt.notesPhotos.length;
  }
  if(notesHtml){
    blocks.push({level:1, sectionKey:'ground-notes', title:'הערות', html:`<h2>הערות</h2>${notesHtml}`});
  }

  return blocks;
}

// *** טקסטים משותפים ל-Clamp/Selective — Reuse בין ה-PDF (buildGroundingClampOrSelectiveReportBlocks)
// לבין מודל העזרה (buildGroundingHelpContent) — כדי שהעזרה תציג תוכן נכון לפי testMethod,
// ולא תמיד את תוכן השיפוע (זה הבאג שתוקן: "התמונה של העזרה מתייחסת לבדיקת שיפוע"). מוגדרות
// ברמה גלובלית (לא מקוננות בתוך פונקציה אחרת) כדי שתהיינה נגישות משתי הפונקציות.
function getGroundingClampSelectiveIntroText(isClamp){
  return isClamp
    ? 'כאשר מבוצעת בדיקה בצבת הארקה (Clamp-on / Stakeless), המכשיר מזריק אות מדידה דרך מוליך ההארקה ומודד את הזרם החוזר דרך מסלול הארקה מקביל. מתוך היחס בין המתח המושרה לזרם הנמדד מחושבת התנגדות לולאת ההארקה. לצורך בדיקה תקפה נדרש מסלול חזרה סגור דרך מערכת הארקות מקבילה.'
    : 'בדיקה סלקטיבית משלבת יתדות עזר עם צבת מדידה סביב מוליך ההארקה הנבדק. יתדות העזר יוצרות את מסלול המדידה, והצבת מאפשרת למדוד את הזרם של האלקטרודה הנבדקת באופן סלקטיבי, בהתאם ליכולות מכשיר המדידה ולחיבור המאושר על ידי היצרן.';
}
function getGroundingClampSelectiveProcedureSteps(isClamp){
  return isClamp
    ? ['זיהוי האלקטרודה ומוליך ההארקה הנבדק.', 'וידוא שהצבת נסגרת באופן מלא סביב מוליך אחד בלבד.', 'וידוא שקיים מסלול חזרה מקביל תקין.', 'ניקוי אזור הסגירה של הצבת אם נדרש.', 'ביצוע Zero / Self Test בהתאם למכשיר.', 'סגירת הצבת סביב המוליך.', 'המתנה לייצוב הקריאה.', 'רישום ההתנגדות.', 'חזרה על המדידה אם הקריאה אינה יציבה.', 'תיעוד בתמונה.']
    : ['זיהוי האלקטרודה הנבדקת.', 'הצבת יתד זרם במרחק מתאים.', 'הצבת יתד פוטנציאל בהתאם לשיטת המדידה.', 'חיבור הכבלים בהתאם להוראות המכשיר.', 'סגירת הצבת סביב מוליך האלקטרודה הנבדקת.', 'ביצוע המדידה.', 'בדיקת יציבות הקריאה.', 'רישום התוצאה.', 'תיעוד מרחקי היתדות.', 'תיעוד בתמונה.'];
}

// *** buildGroundingClampOrSelectiveReportBlocks — PDF ל-Clamp/Selective. נבנה בנפרד
// לגמרי מזרימת slope (שלא נגעה בה כלל). Reuse: אותה תבנית "כרטיס atomic" (break-inside:
// avoid, מזוהה ע"י Preflight) שכבר הוכחה עובדת ב-slope-test-card, בלי גרף 52/62/72 (לפי
// דרישה מפורשת — Clamp/Selective מציגים מדידה/מתוקן/limit/status בלבד).
// *** תצוגת "עקרון הבדיקה" — Reuse מלא בין ה-PDF (buildGroundingClampOrSelectiveReportBlocks)
// לבין מודל העזרה (buildGroundingClampSelectiveHelpContent). סדר עדיפות (ללא שינוי מהמקור,
// רק חולץ לפונקציה משותפת): (1) תמונות שהועלו אישית (gt.principleImages) — הכי ספציפי
// לדוח הזה. (2) תמונת-ברירה שנבחרה מרשימה (gt.selectedPresetImageId). (3) תרשים SVG
// אוטומטי — ברירת המחדל כשלא נבחר/הועלה כלום.
function getGroundingPrincipleVisualHtml(gt, isClamp){
  const hasPrincipleImages = gt.principleImages && gt.principleImages.length;
  const selectedPreset = gt.selectedPresetImageId ? GROUNDING_PRINCIPLE_PRESET_IMAGES.find(p=>p.id===gt.selectedPresetImageId) : null;
  return hasPrincipleImages
    ? `<div class="ground-clamp-photo-grid">${gt.principleImages.map(p=>`
        <div class="photo-box"><img src="${resolvePhotoSrc(p)}" alt="${escapeHtml(p.title)||'עקרון הבדיקה'}"><div class="photo-caption">${escapeHtml(p.title)||'תמונת עקרון הבדיקה'}</div></div>`).join('')}</div>`
    : (selectedPreset
      ? `<div class="ground-clamp-diagram"><img src="${selectedPreset.dataUrl}" alt="${escapeHtml(selectedPreset.label)}" style="width:50%; display:block; margin:0 auto;"></div>`
      : `<div class="ground-clamp-diagram">${buildGroundingClampPrincipleDiagramSvg(isClamp)}</div>`);
}

function buildGroundingClampOrSelectiveReportBlocks(gt){
  const blocks = [];
  const isClamp = gt.testMethod === 'clamp';
  const methodLabel = isClamp ? 'בדיקה בצבת הארקה' : 'בדיקה סלקטיבית — צבת + יתדות עזר';
  const tests = isClamp ? gt.clampTests : gt.selectiveTests;

  // הקדמה — פתיח קצר, ממוקד-נתונים (לא כפילות של עקרון הבדיקה למטה).
  const shortIntro = isClamp
    ? `בדיקה זו בוצעה בשיטת צבת הארקה (Clamp-on / Stakeless).`
    : `בדיקה זו בוצעה בשיטה סלקטיבית (צבת + יתדות עזר).`;
  blocks.push({level:1, sectionKey:'ground-intro', title:'הקדמה', html:`<h2>הקדמה</h2><p style="font-size:12px; line-height:1.8;">${shortIntro}</p>`});

  // עקרון הבדיקה — טקסט מקצועי לפי השיטה, כולל הערת המגבלה המפורשת (Clamp: התנגדות לולאה,
  // לא אלקטרודה בודדת בהכרח) שאושרה במפרט ובדוגמה שסופקה.
  const introText = getGroundingClampSelectiveIntroText(isClamp);

  // *** תמונות "עקרון הבדיקה" — Reuse מלא: getGroundingPrincipleVisualHtml (משותפת,
  // גלובלית) מכבדת את אותו סדר עדיפות גם כאן וגם במודל העזרה (תוקן: העזרה הייתה מציגה
  // תמיד את ה-SVG, מתעלמת מתמונות שהמשתמש העלה/בחר — "תשים לי את התמונות שהעליתי, לא
  // את הסרטוט").
  const principleVisualHtml = getGroundingPrincipleVisualHtml(gt, isClamp);

  blocks.push({level:1, sectionKey:'ground-principle', title:'עקרון הבדיקה', html:`<h2>עקרון הבדיקה</h2>
    ${principleVisualHtml}
    <p style="font-size:12px; line-height:1.8; margin-top:10px;">${escapeHtml(introText)}</p>
    ${isClamp ? `<p style="font-size:11.5px; line-height:1.7; background:#fdf1e0; color:#8a6d00; padding:8px 10px; border-radius:6px; margin-top:8px;">⚠ הערה מקצועית: תוצאת Clamp-on אינה בהכרח "התנגדות של אלקטרודה בודדת" אלא התנגדות הכוללת את האלקטרודה הנבדקת ואת מסלול החזרה דרך הארקות מקבילות. יש לציין במפורש מהו מסלול החזרה בכל בדיקה.</p>` : ''}
  `});

  // פרטי מכשיר ותנאי קרקע/עונה — רק שדות שמולאו (לפי דרישה מפורשת).
  const infoRows = [
    gt.maxAllowedResistance ? `<tr><td class="tinfo-label">ערך התנגדות מרבי מותר (Rmax) — ברירת מחדל</td><td>${escapeHtml(gt.maxAllowedResistance)} Ω</td></tr>` : '',
  ].filter(Boolean).join('');
  if(infoRows) blocks.push({level:1, sectionKey:'ground-info', title:'פרטי הבדיקה והמכשיר', html:`<h2>פרטי הבדיקה והמכשיר</h2><table class="tinfo-table">${infoRows}</table>`});

  const envRows = [
    gt.envMeasurementPeriod ? `<tr><td class="tinfo-label">תקופת מדידה</td><td>${escapeHtml(gt.envMeasurementPeriod)}</td></tr>` : '',
    gt.groundCondition ? `<tr><td class="tinfo-label">מצב הקרקע</td><td>${escapeHtml(gt.groundCondition)}</td></tr>` : '',
    gt.ambientTemp ? `<tr><td class="tinfo-label">טמפרטורה חיצונית</td><td>${escapeHtml(gt.ambientTemp)}</td></tr>` : '',
  ].filter(Boolean).join('');
  if(envRows || gt.environmentalNotes){
    blocks.push({level:1, sectionKey:'ground-env', title:'תנאי קרקע / עונה', html:`<h2>תנאי קרקע / עונה</h2>${envRows?`<table class="tinfo-table">${envRows}</table>`:''}${gt.environmentalNotes?`<p style="font-size:12px; margin-top:8px;">${escapeHtml(gt.environmentalNotes)}</p>`:''}`});
  }

  // מהלך הבדיקה — שלבים לפי השיטה, מהמפרט.
  const procedureSteps = getGroundingClampSelectiveProcedureSteps(isClamp);
  blocks.push({level:1, sectionKey:'ground-procedure', title:'מהלך הבדיקה', html:`<h2>מהלך הבדיקה</h2><ol style="font-size:12px; line-height:1.9; padding-inline-start:20px;">${procedureSteps.map(s=>`<li>${escapeHtml(s)}</li>`).join('')}</ol>`});

  // מסמכי ייחוס — רשימה נפרדת מ-slope, כולל אזהרת אימות (לפי הדוגמה שסופקה).
  const stdRows = GROUNDING_CLAMP_STANDARDS.map(s=>`<tr><td class="tinfo-label"><span dir="ltr">${s.code}</span></td><td>${s.purpose}</td></tr>`).join('');
  blocks.push({level:1, sectionKey:'ground-standards', title:'מסמכי ייחוס ותקנים', html:`<h2>מסמכי ייחוס ותקנים</h2><table class="tinfo-table">${stdRows}</table>`});

  // כרטיסי בדיקה — אחד לכל רשומה, atomic (break-inside:avoid), בלי גרף 52/62/72.
  let photoCounter = 1;
  tests.filter(t=>t.location || t.measuredResistance).forEach(t=>{
    const corrected = t.correctedResistance || calcGroundingCorrectedResistance(t.measuredResistance, t.seasonalFactor);
    const status = t.status || calcGroundingAutoStatus(corrected, t.maxAllowed);
    const statusColor = status==='תקין' ? '#3fa34d' : (status==='לא תקין' ? '#e0503a' : '#888');
    const title = t.location || 'מיקום מדידה';
    const rows = isClamp ? [
      ['תיאור האלקטרודה', t.electrodeDescription], ['תיאור מוליך ההארקה', t.conductorDescription],
      ['מסלול הארקה מקביל', t.parallelEarthPathExists], ['תיאור מסלול החזרה', t.returnPathDescription],
      ['מצב האלקטרודה בזמן הבדיקה', t.connectionState], ['מיקום הצבת', t.clampPosition],
    ] : [
      ['תיאור האלקטרודה', t.electrodeDescription], ['מרחק יתד זרם', t.currentStakeDistance],
      ['מרחק יתד פוטנציאל', t.potentialStakeDistance], ['מיקום הצבת', t.clampPosition],
    ];
    const infoRowsHtml = rows.filter(r=>r[1]).map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('');
    const resultRowsHtml = `
      <tr><td class="tinfo-label">התנגדות נמדדת</td><td>${escapeHtml(t.measuredResistance)||'—'} ${escapeHtml(t.unit||'Ω')}</td></tr>
      <tr><td class="tinfo-label">מקדם עונתי Ks</td><td>${escapeHtml(t.seasonalFactor||'1.00')}${t.seasonalFactorSource?` (${escapeHtml(t.seasonalFactorSource)})`:''}</td></tr>
      <tr><td class="tinfo-label">התנגדות מתוקנת</td><td><b>${corrected!==''?corrected:'—'} Ω</b></td></tr>
      <tr><td class="tinfo-label">ערך מרבי מותר (Rmax)</td><td>${escapeHtml(t.maxAllowed)||'—'} Ω</td></tr>`;
    let photosHtml = '';
    if(t.photos && t.photos.length){
      photosHtml = `<div class="ground-clamp-photo-grid">${t.photos.map(p=>`
        <div class="photo-box"><img src="${p.dataUrl||p.cloudUrl||''}" alt="תמונה ${photoCounter}"><div class="photo-caption">תמונה ${photoCounter++}${p.caption?': '+escapeHtml(p.caption):''}</div></div>`).join('')}</div>`;
    }
    const html = `<div class="ground-clamp-card">
        <h3>${escapeHtml(title)}</h3>
        <div class="ground-clamp-grid">
          <div><table class="tinfo-table">${infoRowsHtml}</table></div>
          <div><table class="tinfo-table">${resultRowsHtml}</table></div>
        </div>
        ${status ? `<div class="ground-clamp-result" style="margin-top:8px; text-align:center; font-weight:700; color:${statusColor}; background:${status==='תקין'?'#eaf7ec':(status==='לא תקין'?'#fbeae7':'#f2f2f2')}; border-radius:14px; padding:6px 10px;">סטטוס: ${escapeHtml(status)}</div>` : ''}
        ${t.notes ? `<p style="font-size:11.5px; margin-top:8px;"><b>הערות:</b> ${escapeHtml(t.notes)}</p>` : ''}
        ${photosHtml}
      </div>`;
    blocks.push({level:1, sectionKey:'ground-loc-'+title, title, html});
  });

  // הערות כלליות
  let notesHtml = '';
  if(gt.notes) notesHtml += `<p style="font-size:12px; line-height:1.7;">${escapeHtml(gt.notes)}</p>`;
  if(notesHtml) blocks.push({level:1, sectionKey:'ground-notes', title:'הערות', html:`<h2>הערות</h2>${notesHtml}`});

  return blocks;
}

// תרשים המחשה פשוט (SVG מקורי, לא מבוסס על תמונת reference) — Clamp: אלקטרודה + צבת +
// חץ זרם דרך מסלול חזרה מקביל. Selective: כמו Clamp אך עם יתדות עזר (C/P) בנוסף.
function buildGroundingClampPrincipleDiagramSvg(isClamp){
  const label1 = isClamp ? 'צבת מדידה' : 'צבת + יתד עזר';
  return `<svg viewBox="0 0 460 150" xmlns="http://www.w3.org/2000/svg" style="background:#fff; max-width:100%; display:block;">
    <rect x="0" y="110" width="460" height="40" fill="#e8dcc8"></rect>
    <line x1="80" y1="30" x2="80" y2="115" stroke="#333" stroke-width="4"></line>
    <text x="80" y="20" font-size="11" text-anchor="middle" fill="#333" font-weight="700">E1</text>
    <text x="80" y="135" font-size="9" text-anchor="middle" fill="#555">אלקטרודה נבדקת</text>
    <circle cx="80" cy="65" r="16" fill="none" stroke="#9b59b6" stroke-width="3"></circle>
    <text x="80" y="90" font-size="8.5" text-anchor="middle" fill="#9b59b6" font-weight="700">${label1}</text>
    ${!isClamp ? `
    <line x1="220" y1="60" x2="220" y2="115" stroke="#1c3f6e" stroke-width="3"></line>
    <text x="220" y="50" font-size="9" text-anchor="middle" fill="#1c3f6e" font-weight="700">P</text>
    <line x1="340" y1="60" x2="340" y2="115" stroke="#1c3f6e" stroke-width="3"></line>
    <text x="340" y="50" font-size="9" text-anchor="middle" fill="#1c3f6e" font-weight="700">C</text>
    <line x1="80" y1="130" x2="340" y2="130" stroke="#888" stroke-width="1.5" stroke-dasharray="4 3"></line>` : `
    <path d="M 110 55 Q 220 15 330 55" fill="none" stroke="#3fa34d" stroke-width="2" marker-end="url(#arrow)"></path>
    <text x="220" y="30" font-size="9" text-anchor="middle" fill="#2d7d3a">זרם מדידה — מסלול חזרה מקביל</text>
    <line x1="380" y1="60" x2="380" y2="115" stroke="#888" stroke-width="3"></line>
    <text x="380" y="135" font-size="8.5" text-anchor="middle" fill="#555">הארקה מקבילה</text>`}
    <defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#3fa34d"></path></marker></defs>
  </svg>`;
}

function buildSoilReportBlocks(photoCounter){
  const st = state.soilTest;
  const blocks = [];
  const isEn = state.settings.reportLanguage === 'en';

  const introText = isEn ? buildSoilIntroTextEn() : buildSoilIntroText();
  blocks.push({level:1, sectionKey:'soil-intro', title:sl('intro'), html:`<h2>${sl('intro')}</h2><p style="font-size:12px; line-height:1.8;">${escapeHtml(introText).replace(/\n/g,'<br>')}</p>`});

  const selectedReasons = PURPOSE_REASON_LABELS.filter(r=>st.purpose.reasons[r.key]).map(r=>isEn ? r.labelEn : r.label);
  const purposeNotesText = soilFreeText('purposeNotes', st.purpose.notes);
  if(selectedReasons.length || purposeNotesText){
    let h = selectedReasons.length ? `<ul style="font-size:12px; margin:6px 0;">${selectedReasons.map(r=>`<li>${escapeHtml(r)}</li>`).join('')}</ul>` : '';
    if(purposeNotesText) h += `<p style="font-size:12px;">${escapeHtml(purposeNotesText)}</p>`;
    blocks.push({level:1, sectionKey:'soil-purpose', title:sl('purpose'), html:`<h2>${sl('purpose')}</h2>${h}`});
  }

  const scopeRows = [
    st.scope.numPoints ? `<tr><td class="tinfo-label">${sl('numPoints')}</td><td>${escapeHtml(st.scope.numPoints)}</td></tr>` : '',
    st.scope.method ? `<tr><td class="tinfo-label">${sl('method_field')}</td><td>${escapeHtml(st.scope.method)}</td></tr>` : '',
    st.scope.numDirections ? `<tr><td class="tinfo-label">${sl('numDirections')}</td><td>${escapeHtml(st.scope.numDirections)}</td></tr>` : '',
    st.scope.electrodeDistances ? `<tr><td class="tinfo-label">${sl('electrodeDistances')}</td><td>${escapeHtml(st.scope.electrodeDistances)}</td></tr>` : ''
  ].filter(Boolean).join('');
  if(scopeRows || st.scope.weatherConditions || soilIllustrationOn(st)){
    let h = scopeRows ? `<table class="tinfo-table">${scopeRows}</table>` : '';
    if(st.scope.weatherConditions) h += `<p style="font-size:12px;"><b>${sl('weatherConditions')}:</b> ${escapeHtml(st.scope.weatherConditions)}</p>`;
    if(soilIllustrationOn(st)) h += `<div style="text-align:center; margin:10px 0 4px; break-inside:avoid; page-break-inside:avoid;">
      <img src="${SOIL_METHOD_ILLUSTRATION}" alt="" style="width:78mm; max-width:52%; height:auto;">
      <div style="font-size:10.5px; color:#444; margin-top:3px;">${isEn ? 'Figure — test setup: four electrodes at equal spacing L, connected to the tester (E, ES, S, H) — Wenner method' : 'איור — אופן ביצוע הבדיקה בשיטת <bdi dir="ltr">Wenner</bdi>: ארבע אלקטרודות במרווחים שווים <bdi dir="ltr">L</bdi>, מחוברות למכשיר המדידה (<bdi dir="ltr">E, ES, S, H</bdi>)'}</div></div>`;
    blocks.push({level:1, sectionKey:'soil-scope', title:sl('scope'), html:`<h2>${sl('scope')}</h2>${h}`});
  }

  const selectedStandards = RESISTIVITY_STANDARDS.filter((_,i)=>st.standardsOn[i]);
  if(selectedStandards.length){
    const rows = selectedStandards.map(s=>`<tr><td class="tinfo-label"><span dir="ltr">${s.code}</span></td><td>${isEn ? s.purposeEn : s.purpose}</td></tr>`).join('');
    blocks.push({level:1, sectionKey:'soil-standards', title:sl('standards'), html:`<h2>${sl('standards')}</h2><table class="tinfo-table">${rows}</table>`});
  }

  const equipRows = (st.equipment||[]).filter(e=>e.name||e.model||e.serialNo||e.calibrationValidUntil);
  if(equipRows.length){
    const rowsHtml = equipRows.map(e=>`<tr><td>${escapeHtml(e.name)}</td><td>${escapeHtml(e.model)}</td><td>${escapeHtml(e.serialNo)}</td><td>${escapeHtml(e.calibrationValidUntil)}</td></tr>`).join('');
    blocks.push({level:1, sectionKey:'soil-equipment', title:sl('equipment'), html:`<h2>${sl('equipment')}</h2>
      <table><thead><tr><th>${sl('equipCol')}</th><th>${sl('modelCol')}</th><th>${sl('serialCol')}</th><th>${sl('calibCol')}</th></tr></thead><tbody>${rowsHtml}</tbody></table>`});
  }

  const methodNotesText = soilFreeText('methodNotes', st.methodNotes);
  if((st.methodPhotos && st.methodPhotos.length) || methodNotesText){
    let h = `<p style="font-size:12px; line-height:1.7;">${sl('methodExplain')}</p>`;
    if(st.methodPhotos && st.methodPhotos.length) h += printPhotos(st.methodPhotos, photoCounter);
    if(methodNotesText) h += `<p style="font-size:12px;">${escapeHtml(methodNotesText)}</p>`;
    blocks.push({level:1, sectionKey:'soil-method', title:sl('method'), html:`<h2>${sl('method')}</h2>${h}`, pageBreak:true});
  }

  const locRows = (st.locations||[]).filter(l=>l.point||l.gps||l.direction||l.notes);
  if(locRows.length || (st.locationPhotos && st.locationPhotos.length)){
    let h = '';
    if(locRows.length){
      const rowsHtml = locRows.map(l=>`<tr><td>${escapeHtml(l.point)}</td><td><span dir="ltr">${escapeHtml(l.gps)}</span></td><td>${escapeHtml(l.direction)}</td><td>${escapeHtml(l.notes)}</td></tr>`).join('');
      h += `<table><thead><tr><th>${sl('pointCol')}</th><th>GPS</th><th>${sl('directionCol')}</th><th>${sl('notesCol')}</th></tr></thead><tbody>${rowsHtml}</tbody></table>`;
    }
    if(st.locationPhotos && st.locationPhotos.length) h += printPhotos(st.locationPhotos, photoCounter);
    blocks.push({level:1, sectionKey:'soil-locations', title:sl('locations'), html:`<h2>${sl('locations')}</h2>${h}`});
  }

  const envRows = [
    st.environment.soilTemp ? `<tr><td class="tinfo-label">${sl('soilTemp')}</td><td>${escapeHtml(st.environment.soilTemp)}°C</td></tr>` : '',
    st.environment.airTemp ? `<tr><td class="tinfo-label">${sl('airTemp')}</td><td>${escapeHtml(st.environment.airTemp)}°C</td></tr>` : '',
    st.environment.humidity ? `<tr><td class="tinfo-label">${sl('humidity')}</td><td>${escapeHtml(st.environment.humidity)}%</td></tr>` : '',
    st.environment.soilCondition ? `<tr><td class="tinfo-label">${sl('soilCondition')}</td><td>${escapeHtml(st.environment.soilCondition)}</td></tr>` : '',
    st.environment.rained ? `<tr><td class="tinfo-label">${sl('precipitation')}</td><td>${escapeHtml(st.environment.rained)}</td></tr>` : ''
  ].filter(Boolean).join('');
  if(envRows) blocks.push({level:1, sectionKey:'soil-env', title:sl('env'), html:`<h2>${sl('env')}</h2><table class="tinfo-table">${envRows}</table>`});

  const resistivityLocs = (st.resistivityData||[]).filter(l=>
    l.name || l.northSouth.some(v=>v) || l.eastWest.some(v=>v));
  if(resistivityLocs.length){
    const distHeaders = RESISTIVITY_DISTANCES.map(d=>`<th>d=${d}m</th>`).join('');
    const dataRows = resistivityLocs.map(l=>`
      <tr><td>${escapeHtml(l.name)} — ${sl('northSouth')}</td>${l.northSouth.map(v=>`<td>${escapeHtml(v)}</td>`).join('')}</tr>
      <tr><td>${escapeHtml(l.name)} — ${sl('eastWest')}</td>${l.eastWest.map(v=>`<td>${escapeHtml(v)}</td>`).join('')}</tr>
    `).join('');
    // v2.2.529 — גרף בגודל דוח (כמו בדוח הייחוס): ~120 מ"מ רוחב במרכז, עם כותרת לכל מיקום
    const chartsHtml = resistivityLocs.map((l, li)=>{
      const svg = buildResistivityChartSvg(l.name, l.northSouth, l.eastWest, isEn);
      return svg ? `<div class="soil-chart" style="width:120mm; max-width:68%; margin:4px auto 10px; break-inside:avoid; page-break-inside:avoid;">
        <div style="font-size:11px; font-weight:700; text-align:center; margin-bottom:2px;">${isEn ? 'Graph — Location' : 'גרף — מיקום'} ${escapeHtml(l.name || String(li + 1))}</div>${svg}</div>` : '';
    }).join('');
    blocks.push({level:1, sectionKey:'soil-results', title:sl('results'), html:`<h2>${sl('results')}</h2>
      <table><thead><tr><th>${sl('locationCol')}</th>${distHeaders}</tr></thead><tbody>${dataRows}</tbody></table>
      <h3 style="margin-top:16px;">${isEn?'Graphs':'גרפים'}</h3>${chartsHtml}`}); // v2.2.532 — בלי מעבר עמוד כפוי: ממשיך אחרי תנאי הסביבה כשיש מקום (אחרת עובר לבד)
  }

  const extraGraphsHtml = printGraphs(st.graphs);
  if(extraGraphsHtml) blocks.push({level:1, sectionKey:'soil-graphs', title:sl('graphs'), html:`<h2>${sl('graphs')}</h2>${extraGraphsHtml}`});

  const analysisText = soilFreeText('engineeringAnalysis', st.engineeringAnalysis);
  if(analysisText){
    blocks.push({level:1, sectionKey:'soil-analysis', title:sl('analysis'), html:`<h2>${sl('analysis')}</h2><p style="font-size:12px; line-height:1.7; white-space:pre-line;">${escapeHtml(analysisText)}</p>`}); // v2.2.529 — ממשיך באותו עמוד אחרי הגרפים (הגרפים קטנים יותר עכשיו)
  }
  const conclusionsText = soilFreeText('conclusions', st.conclusions);
  if(conclusionsText){
    blocks.push({level:1, sectionKey:'soil-conclusions', title:sl('conclusions'), html:`<h2>${sl('conclusions')}</h2><p style="font-size:12px; line-height:1.7; white-space:pre-line;">${escapeHtml(conclusionsText)}</p>`});
  }
  const recommendationsText = soilFreeText('recommendations', st.recommendations);
  if(recommendationsText){
    blocks.push({level:1, sectionKey:'soil-recommendations', title:sl('recommendations'), html:`<h2>${sl('recommendations')}</h2><p style="font-size:12px; line-height:1.7; white-space:pre-line;">${escapeHtml(recommendationsText)}</p>`});
  }

  // v2.2.533 — חתימה עם חותמת, תמיד מתחת להמלצות (מוצמדת לבלוק האחרון — המלצות / מסקנות / ניתוח — כדי
  // שלא תיפרד ממנו לעמוד אחר). שם הבודק + חברה + תמונת "חתימה וחותמת" מההגדרות.
  {
    const s0 = state.settings;
    let sigHtml = `<div class="soil-sign" style="margin-top:18px; break-inside:avoid; page-break-inside:avoid;">
      <p style="font-size:13px; margin:0 0 10px;">${isEn ? 'Sincerely,' : 'בברכה,'}</p>
      ${s0.engineerName ? `<p style="font-size:12.5px; margin:2px 0; font-weight:700;">${escapeHtml(s0.engineerName)}</p>` : ''}
      ${(s0.testerLicenseNo || s0.engineerLicenseNo) ? `<p style="font-size:12px; margin:2px 0;">${isEn ? 'License No.' : "מס' רישיון"}: ${escapeHtml(s0.testerLicenseNo || s0.engineerLicenseNo)}</p>` : ''}
      ${s0.companyName ? `<p style="font-size:12px; margin:2px 0;">${escapeHtml(s0.companyName)}</p>` : ''}
      ${s0.signature ? `<div style="margin-top:10px;"><img src="${s0.signature}" style="max-width:200px; max-height:85px;" alt="${isEn ? 'Signature and stamp' : 'חתימה וחותמת'}"></div>`
                     : `<p style="font-size:12px; margin-top:14px;">${isEn ? 'Signature and stamp' : 'חתימה וחותמת'}: ________________________</p>`}
    </div>`;
    // v2.2.534 — מסקנות + המלצות בעמוד נפרד (מתחיל בעמוד חדש), והחתימה עם החותמת מתחת להמלצות באותו עמוד
  { const firstEnd = blocks.find(b => b.sectionKey === 'soil-conclusions') || blocks.find(b => b.sectionKey === 'soil-recommendations'); if(firstEnd) firstEnd.pageBreak = true; }
  const lastText = ['soil-recommendations', 'soil-conclusions', 'soil-analysis'].map(k => blocks.find(b => b.sectionKey === k)).find(Boolean);
    if(lastText) lastText.html += sigHtml;
    else blocks.push({ level:1, sectionKey:'soil-signature', title: isEn ? 'Signature' : 'חתימה', html: sigHtml });
  }

  if(st.appendixPhotos && st.appendixPhotos.length){
    blocks.push({level:1, sectionKey:'soil-appendices', title:sl('appendices'), html:`<h2>${sl('appendices')}</h2>${printPhotos(st.appendixPhotos, photoCounter)}`, pageBreak:true});
  }

  if(isEn){
    blocks.forEach(b=>{ b.html = `<div dir="ltr" style="text-align:left;">${b.html}</div>`; });
  }

  return blocks;
}

// כותרת עמוד השער (v2.2.547): "תעודת רישום ודו"ח בדיקה של מתקן חשמלי — בהתאם לחוק החשמל תשי"ד 1954"
// ברירת מחדל בדוח משולב; בכל דוח אפשר לבחור אותה (או טקסט חופשי) בשדה "כותרת עמוד השער".
const COVER_TITLE_OFFICIAL = 'תעודת רישום ודו"ח בדיקה של מתקן חשמלי.\nבהתאם לחוק החשמל תשי"ד 1954.';
function getCoverTitleMode(){
  const m = state.meta || {};
  if(m.coverTitleMode) return m.coverTitleMode;               // 'auto' | 'official' | 'custom'
  return (state.reportChapters && state.reportChapters.length) ? 'official' : 'auto';
}
function coverTitleOverrideHtml(){
  const mode = getCoverTitleMode();
  const txt = mode === 'official' ? COVER_TITLE_OFFICIAL : (mode === 'custom' ? String((state.meta && state.meta.coverTitleCustom) || '').trim() : '');
  if(!txt) return '';
  const lines = txt.split('\n').map(l => l.trim()).filter(Boolean);
  return lines.map((l, i) => i === 0 ? escapeHtml(l) : `<span style="display:block; font-size:0.72em; font-weight:700; margin-top:4px;">${escapeHtml(l)}</span>`).join('');
}
function buildCoverPage(totalPages){
  const m = state.meta;
  const s = state.settings;

  const now = new Date();
  const dateStr = now.toLocaleDateString('he-IL');
  const timeStr = now.toLocaleTimeString('he-IL', {hour:'2-digit', minute:'2-digit'});
  // "הופק בתאריך" מוצג ללא שעה, לכל סוגי הדוח באפליקציה — לפי בקשה מפורשת להרחיב מ-EVCS
  // (v2.255) לכל הדוחות. עכשיו גם ניתן לעריכה מפורשת (meta.issueDate, שדה תאריך חדש בסעיף
  // "01") — לפי בקשה מפורשת. אם לא נקבע במפורש (דוחות ישנים, או דוח חדש שעדיין לא מולא),
  // נופל חזרה להיום כברירת מחדל — אותה התנהגות בדיוק כמו קודם.
  const genStampValue = m.issueDate ? formatDateIL(m.issueDate) : dateStr;

  const letterhead = s.logo ? `
    <div class="letterhead">
      <div class="letterhead-logo-full">
        <img src="${s.logo}" alt="לוגו">
      </div>
    </div>` : '';
  // טופס בדיקה של מתקן פוטו-וולטאי — עמוד שער ייעודי לפי הטופס הרשמי (v2.2.513)
  if(getReportType() === 'PV_INSPECTION') return `${letterhead}<div class="cover-page">${buildPvCoverHtml()}</div>`;

  // סדר שורות ומבנה מאוחד לכל סוגי הדוח באפליקציה — לפי בקשה מפורשת להרחיב מ-EVCS (v2.256)
  // לכל הדוחות. מספר הדו"ח כבר לא בטבלה (רק במסגרת הבולטת מתחת לכותרת, ראה למטה). שורת
  // הלקוח מתויגת "מזמין הבדיקה:" (לא "שם הלקוח:") — לפי בקשה מפורשת מפורשת בעקבות דוגמה
  // ממשית שהועלתה. אותו שדה נתונים בדיוק (m.client) — רק שינוי תווית, לא שורה נוספת (זה
  // בדיוק מה שהוסר ב-v2.274 כדי למנוע כפילות בין "מזמין הבדיקה" ל"שם הלקוח" ששניהם הצביעו
  // לאותו מושג בפועל).
  const infoRows = [
    ['מזמין הבדיקה:', m.client],
    // "לידי (איש קשר)" — שדה חובה קיים בטופס לכל סוגי הדוח, אך אותר תוך כדי מימוש בחירת
    // אנשי קשר מ-Fireberry שמעולם לא הודפס בפועל בשום מקום — אותו דפוס באג שכבר תוקן כמה
    // פעמים באותו פרויקט (v2.334 סוג מפסק, v2.340 מסקנות). תוקן כאן, לא רק לדוח הכללי.
    ['לידי (איש קשר):', m.attentionTo],
    ['שם המתקן:', m.siteName],
    ['מיקום המתקן:', m.address],
    ['תאריך הבדיקה:', formatDateIL(m.date)],
    ['תאריך הפקת הדוח:', genStampValue],
    // "מבצע הבדיקה" — שם + סוג רישיון בשורה אחת, ואז שני מספרי הרישיון בנפרד (לא מספר יחיד
    // עם fallback כמו קודם) — לפי בקשה מפורשת: "אפשרות לרשום את שני הרישיונות לצורך הצגה...
    // מר' בודק, מר' מהנדס". כל שורה מוצגת רק אם יש לה ערך (השדות עצמם כבר קיימים בהגדרות ←
    // פרטי בודק, לא נוספו שדות חדשים, רק שונה אופן ההצגה בטבלה).
    ['מבצע הבדיקה:', [s.engineerName, s.licenseType].filter(Boolean).join(' — ')],
    ['מספר רישיון בודק:', s.testerLicenseNo],
    ['מספר רישיון מהנדס:', s.engineerLicenseNo],
    ['תיאור המתקן/העבודה:', m.description],
    // שדות ספציפיים לדוח הכללי — נמצאו חסרים לחלוטין מעמוד השער מול קובץ ייחוס אמיתי (VLF,
    // "מרפאת גפן"): מלווה הבדיקה/מהות הבדיקה/פרטי מתקן נבדק/שיטת הגנה. מוצגים רק לסוג הדוח
    // הזה — לא משפיע על שאר סוגי הדוח שלא מכירים את reportDetails הזה בכלל.
    ...(getReportType()==='GENERAL' ? (()=>{
      const rd = state.generalElectricalInspectionReport.reportDetails;
      return [
        ['מלווה הבדיקה:', rd.accompaniedBy],
        ['מהות הבדיקה:', rd.inspectionNature],
        ['פרטי מתקן נבדק:', rd.testedFacilityType],
        ['שיטת הגנה:', rd.protectionMethod]
      ];
    })() : []),
    // מכשירי בדיקה — נשלפים מהצ'קבוקסים שנבחרו (state.meta.testInstrumentsSelected), לא
    // מרשימת ציוד רשומה נפרדת. "אחר" מוחלף בטקסט החופשי (testInstrumentsOther) אם קיים.
    // מכשירי בדיקה — דגם/מס' סידורי/תוקף כיול נשלפים אוטומטית מהמכשיר התואם ברשימת הציוד
    // הקיימת (הגדרות ← ציוד), לא משדות ידניים בטופס עצמו — לפי בקשה מפורשת ודוגמה ממשית
    // שהועלתה: "שם המכשיר ותאריך הכיול מופיעים בטבלה... אוטומטית". פורמט מצומצם, לפי בקשה
    // מפורשת נוספת ("רק שם המכשיר... ואת תאריך הכיול וזהו") — הוסר מספר סידורי מהתצוגה,
    // נשארים רק שם + דגם (אם קיים) + תוקף כיול.
    // v2.2.536 — חובה בכל הדוחות: מס' סידורי + תוקף כיול לכל מכשיר, כל מכשיר בשורה נפרדת
    ['מכשירי בדיקה:', (state.meta.testInstrumentsSelected||[]).map(instrumentDetailsText).join('\n')]
  ];
  const infoRowsHtml = infoRows
    .filter(([,val])=>val)
    .map(([label,val])=>
      `<tr><td class="cov-label">${label}</td><td style="white-space:pre-line;">${escapeHtml(val)}</td></tr>`
    ).join('');

  const signatureBlock = s.signature
    ? `<div class="cover-sig-img-wrap"><img class="cover-sig-img" src="${s.signature}" alt="חתימה וחותמת"></div>`
    : `<div class="cover-sig-line">חתימה וחותמת: ________________________</div>`;

  const reportType = getReportType();
  const vs = state.voltageSystem;
  const voltageSuffix = (reportType === 'SMA' && vs.voltageClass)
    ? ` – מסדר ${vs.voltageClass}${vs.nominalVoltage ? ' ' + vs.nominalVoltage + (vs.voltageUnit||'') : ''}`
    : '';
  const flexKindLabel = reportType === 'FLEXIBLE' ? (FLEXIBLE_REPORT_KIND_OPTIONS.find(o=>o.value===state.flexibleReport.reportType)||{}).label : null;
  const coverTitle = reportType === 'STRING_POLARITY' ? getStringPolarityCoverTitle()
    : reportType === 'GROUNDING'
    ? 'דו"ח מדידת איכות ההארקה ביחס למסה הכללית של האדמה'
    : (reportType === 'SOIL' ? 'דו"ח בדיקת התנגדות סגולית של הקרקע'
    : (reportType === 'DC_CABLE' ? 'דו"ח בדיקת בידוד וקוטביות כבלי וגידי DC'
    : (reportType === 'EV_DC' ? 'דו"ח בדיקת עמדת טעינה DC'
    : (reportType === 'MAIN_PANEL' ? getTypeDisplayLabel(MAIN_PANEL_REPORT_TYPE_NAME)
    : (reportType === 'TRANSFORMER_INSPECTION' ? TRANSFORMER_INSPECTION_REPORT_TYPE_NAME
    : (reportType === 'EVCS' ? (() => {
        // כותרת דינמית — AC בלבד → "...AC", DC בלבד → "...DC", מעורב → "...AC/DC" (לפי בקשה
        // מפורשת: "במידה והיה דוח משותף אז יופיעו שניהם DC/AC").
        const types = new Set(state.evcsReport.stations.map(s=>s.stationType).filter(Boolean));
        if(types.size === 1) return `${EVCS_REPORT_TYPE_NAME} ${[...types][0]}`;
        if(types.size === 2) return `${EVCS_REPORT_TYPE_NAME} AC/DC`;
        return EVCS_REPORT_TYPE_NAME;
      })()
    : (reportType === 'FLEXIBLE' ? (state.flexibleReport.reportType==='CUSTOM_REPORT' ? (state.flexibleReport.customReportTitle||'דוח מותאם אישית') : (flexKindLabel||'דוח'))
    : 'דו"ח בדיקת מתקן חשמל' + voltageSuffix)))))));

  // *** GROUNDING בלבד: coverExplanation הוסר מעמוד השער (היה "בדיקה זו בוחנת את איכות
  // מערכת ההארקה... בשיטת Fall of Potential") — זהו "תוכן מקצועי הקשור לשיטת הבדיקה"
  // לפי הגדרת המשתמש המפורשת, ואין להציגו בעמוד השער. הועבר לעמוד 2 כבלוק "עקרון
  // הבדיקה" נפרד (ראו buildGroundingReportBlocks). שאר סוגי הדוח (SOIL/DC_CABLE/EV_DC)
  // לא שונו כלל, לפי Scope מפורש.
  const coverExplanation = (reportType === 'DC_CABLE'
    ? `<p class="cover-explanation">בדיקה זו בוחנת את התנגדות הבידוד ואת תקינות הקוטביות של כבלי וגידי ה-DC במתקן, לצורך אימות בטיחותם ותקינותם לפני חיבור והפעלה.</p>`
    : (reportType === 'EV_DC'
    ? `<p class="cover-explanation">בדוח זה מתועדים פרטי עמדת טעינה DC, הזנתה, אמצעי ההגנה שלה (מפסק, הגנת זרם דלף) ותנאי הבדיקה, כשלב מקדים לבדיקות התפקוד המפורטות.</p>`
    : ''));

  // הצהרת החשמלאי המבצע — לכל סוגי הדוח, בעמוד הראשון (מתחת לטבלת הפרטים). *** עודכן:
  // עכשיו דרך renderer/resolver משותפים (buildElectricianDeclarationBlock +
  // getElectricianDeclarationData) — לא HTML מקומי קשיח. Audit מקיף (לא grep שטחי)
  // גילה שהמנגנון הישן קרא תמיד רק את state.workingElectricianName הגנרי, בעוד ש-3
  // סוגי דוח (EV_DC/GENERATOR/GENERAL) שומרים את ההצהרה במקור נתונים ייעודי משלהם
  // (evDcReport.page2/generatorReport/generalElectricalInspectionReport) — אומת
  // בפועל עם נתוני-בדיקה ייחודיים: השער הציג את השדה הגנרי (הלא-נכון) במקום הנתונים
  // שהמשתמש באמת הזין בעורך שלו. עבור EV_DC זה אף גרם להצגה כפולה (גם בשער עם נתונים
  // שגויים, גם באמצע הדוח עם נתונים נכונים — ראו buildEvDcReportBlocks, הוסר משם).
  // כל שאר סוגי הדוח (כולל GROUNDING) ממשיכים להשתמש במקור הגנרי, ללא שינוי בפועל.
  const mainPanelElectricianDeclHtml = buildElectricianDeclarationBlock(getElectricianDeclarationData());

  return `
    ${letterhead}
    <div class="cover-page">
      <h1 class="cover-title2${reportType==='GENERAL'?' cover-title2-plain':''}">${coverTitleOverrideHtml() || coverTitle}</h1>
      ${m.reportNumber ? `<div class="cover-report-no${reportType==='GENERAL'?' cover-report-no-plain':''}">מספר דו"ח: ${escapeHtml(m.reportNumber)}</div>` : ''}
      ${coverExplanation}
      <table class="cover-table2">${infoRowsHtml}</table>
      <div class="cover-decl-and-sig-wrap">
        ${mainPanelElectricianDeclHtml}
        <div class="cover-sig-area">${signatureBlock}</div>
      </div>
    </div>`;
}

// *** buildPhotoDocumentationGrid — ה-grid הפנימי של "תיעוד תמונות" (כרטיס תמונה, מספור,
// מחיקה, כותרת, הערות ממוספרות N.M, "+ הוסף הערה"), מחולץ לפונקציה גנרית משותפת. מקבלת
// photosPath (לבניית data-delrow/data-photonoteadd/data-textpath הנכונים) ואת מערך
// ה-photos עצמו. renderPhotoDocumentationCard (תיעוד תמונות הכללי) הופכת לעטיפה דקה
// שקוראת לפונקציה הזו עם photosPath='generalPhotos' — 0 שינוי בהתנהגות/HTML הקיימים.
// תמונות-לפי-סעיף בדוח הגמיש קוראות לאותה פונקציה בדיוק עם photosPath שונה — Reuse מלא,
// לא שכפול קוד, בדיוק לפי הדרישה המפורשת.
// *** buildPhotoDocumentationGrid — Lazy Rendering (Performance Audit אישר: gallery
// מכווצת עדיין בנתה 100% מה-<img> tags ב-DOM, render() סקאלי ליניארית עם מספר התמונות,
// גם כשהמשתמש לא רואה כלום). עכשיו זו wrapper דקה: בודקת openPhotoGalleries.has(galleryKey)
// — אם סגור, מחזירה placeholder קליל בלבד (מספר תמונות + כפתור פתיחה), 0 תגי <img>, 0
// photo cards, 0 עלות render() תלוית-מספר-תמונות. buildPhotoDocumentationGridInner (למטה)
// היא הלוגיקה המקורית *בדיוק* — 0 שינוי ב-HTML/CSS/detay של הגלריה עצמה, נקראת רק כשפתוחה.
function buildPhotoDocumentationGrid(photosPath, photos, galleryKey){
  // מיגרציה חד-פעמית — זול (בדיקת קיום שדה בלבד, לא HTML), רץ תמיד ללא קשר למצב הפתיחה,
  // כדי ש-state יהיה תקין גם אם הגלריה נפתחת מאוחר יותר או שקוד אחר קורא ל-photos[i].notes.
  photos.forEach(p=>{
    if(!p.notes) p.notes = [];
    if(!p.notes.length && p.caption){ p.notes = [p.caption]; p.caption = ''; }
    if(!p.notes.length) p.notes = [''];
    if(p.title === undefined) p.title = '';
  });
  if(!photos.length) return '<p style="font-size:12px; color:var(--text-dim);">עדיין לא הועלו תמונות.</p>';

  const isOpen = openPhotoGalleries.has(galleryKey);
  if(!isOpen){
    // *** Placeholder בלבד — 0 <img>, 0 photo cards. לחיצה פותחת בפועל (local render, לא
    // Full App render) דרך data-photogalleryopen (handler ב-attachHandlers).
    return `<div data-photogalleryplaceholder="${escapeAttr(galleryKey)}">
      <button type="button" class="add-panel-card" data-photogalleryopen="${escapeAttr(galleryKey)}|${escapeAttr(photosPath)}" style="width:100%; margin-top:10px;">
        🖼️ הצג ${photos.length} תמונות
      </button>
    </div>`;
  }
  return `<div data-photogallerycontainer="${escapeAttr(galleryKey)}">
    <button type="button" class="del-panel-btn" data-photogalleryclose="${escapeAttr(galleryKey)}|${escapeAttr(photosPath)}" style="margin-top:10px;">▲ צמצם גלריה</button>
    ${buildPhotoDocumentationGridInner(photosPath, photos)}
  </div>`;
}

function buildPhotoDocumentationGridInner(photosPath, photos){
  return `
    <div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(260px, 1fr)); gap:16px; margin-top:14px;">
      ${photos.map((p,i)=>`
        <div style="position:relative; border:3px solid var(--amber); border-radius:10px; overflow:hidden; background:#000;">
          <div style="position:absolute; top:8px; right:8px; background:rgba(0,0,0,0.65); color:var(--amber); font-size:11.5px; font-weight:700; padding:3px 9px; border-radius:6px; z-index:2;">תמונה ${i+1}</div>
          <button type="button" class="del-panel-btn" data-delrow="${photosPath}|${i}" title="מחק תמונה" style="position:absolute; top:8px; left:8px; z-index:2; width:26px; height:26px; padding:0; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:13px;">🗑️</button>
          <img src="${resolvePhotoSrc(p)}" data-cloudpath="${escapeAttr(p.cloudPath||'')}" style="width:100%; display:block; max-height:260px; object-fit:cover;">
          <div style="background:rgba(0,0,0,0.82); padding:10px;">
            <input type="text" data-textpath="${photosPath}.${i}.title" placeholder="כותרת לתמונה (לדוגמה: לוח חשמל ראשי)..." style="background:rgba(255,255,255,0.1); color:#fff; border-color:rgba(255,255,255,0.3); font-weight:700; margin-bottom:8px;" value="${escapeAttr(p.title)}">
            <div style="max-height:170px; overflow-y:auto; padding-left:2px;">
              ${p.notes.map((note,ni)=>`
                <div style="margin-bottom:6px;">
                  <div style="font-size:11px; color:var(--amber); margin-bottom:2px; display:flex; justify-content:space-between;">
                    <span>הערה ${i+1}.${ni+1}</span>
                    ${p.notes.length > 1 ? `<button type="button" data-photonoteremove="${photosPath}|${i}|${ni}" style="background:none; border:none; color:#ff8a80; cursor:pointer; font-size:11px; padding:0;">✕ הסר</button>` : ''}
                  </div>
                  <textarea data-textpath="${photosPath}.${i}.notes.${ni}" placeholder="הערה..." style="height:60px; resize:none; overflow-y:auto; background:rgba(255,255,255,0.08); color:#fff; border-color:rgba(255,255,255,0.25);">${escapeHtml(note)}</textarea>
                </div>
              `).join('')}
            </div>
            <button type="button" class="add-btn" data-photonoteadd="${photosPath}|${i}" style="width:100%; font-size:11.5px; padding:6px;">+ הוסף הערה</button>
          </div>
        </div>
      `).join('')}
    </div>
  `;
}

function renderPhotoDocumentationCard(){
  const photos = state.generalPhotos || [];
  return `
    <section class="card" data-key="general-photos">
      <div class="card-head" data-toggle="general-photos">
        <h2>📷 תיעוד תמונות</h2>
        <span class="chev">▾</span>
      </div>
      <div class="card-body">
        <p style="font-size:12px; color:var(--text-dim); margin-top:0;">
          ניתן לצלם או להעלות תמונות מהשטח, ולהוסיף לכל תמונה כמה הערות שצריך — כל הערה תמוספר אוטומטית (1.1, 1.2, 1.3...). התמונות והערותיהן יופיעו בדוח המודפס.
        </p>
        <input type="file" accept="image/*" multiple id="generalPhotoInputGallery" style="display:none;">
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
          <button type="button" class="add-panel-card" id="btnGeneralPhotoPickGallery">🖼️ הוסף תמונה</button>
        </div>
        ${buildPhotoDocumentationGrid('generalPhotos', photos, 'general-photos')}
      </div>
    </section>
`;
}

// עמוד "רישיון בודק" — העמוד האחרון בדוח (v2.2.524). בטופס 3 של כבאות תמיד; בשאר הדוחות לפי ההגדרה.
