// מחלצת את ה-CSS האמיתי שמשמש בפועל להדפסה (buildStandaloneDoc) — לא קירוב/שכפול ידני
// (Reuse מלא, "המקור היחיד לאמת" למניעת פערים כמו זה שכבר קיים בין toc-measure ל-CSS
// האמיתי: padding:3px 5px מול padding:4px 5px בפועל). @media print{...} מפורק עם
// brace-matching אמיתי (לא regex נאיבי שנשבר על סוגריים מקוננים כמו ב-@page) והכללים
// הפנימיים שלו מוחלים ללא תנאי — כי בהקשר מדידה רגיל (לא הדפסה בפועל) @media print לא
// מופעל כלל, אחרת המדידה הייתה מתעלמת מכל כללי ה-padding/font-size שבתוכו.
function extractPrintCss(){
  const doc = buildStandaloneDoc('', '', 'x', false);
  const m = doc.match(/<style>([\s\S]*?)<\/style>/);
  if(!m) return '';
  const css = m[1];
  const marker = '@media print';
  const idx = css.indexOf(marker);
  if(idx === -1) return css;
  let i = css.indexOf('{', idx);
  let depth = 1; let j = i + 1;
  while(j < css.length && depth > 0){
    if(css[j] === '{') depth++;
    else if(css[j] === '}') depth--;
    j++;
  }
  const printInner = css.slice(i + 1, j - 1);
  const before = css.slice(0, idx);
  const after = css.slice(j);
  return before + printInner + after;
}

// ============ Preflight לטבלאות לפני Page Break ============
// מיישמת בדיוק את עץ ההחלטה שהתבקש, מבוססת מדידת גובה DOM אמיתי (לא ניחוש/צפייה חזותית):
// CHECK AVAILABLE HEIGHT -> TABLE FITS? -> YES: הדפס כרגיל | NO: נסה צמצום מקומי עדין (לא
// font-size גלובלי, לא v2.426) -> FITS NOW? -> YES: הדפס מצומצם | NO: TABLE FITS FRESH
// PAGE? -> YES: page-break-before לפני הטבלה (ולפני הכותרת הצמודה אליה, מניעת יתמות) | NO:
// SPLIT (משאירים ל-thead-חוזר+tr-לא-נשבר הקיימים, שלא נגענו בהם).
const TABLE_PREFLIGHT_PAGE_HEIGHT_PX = 1010; // זהה בדיוק ל-estimatePageNumbers (Reuse)
const TABLE_PREFLIGHT_WIDTH_PX = 680;

function applyTablePreflight(blocks){
  const printCss = extractPrintCss();
  const container = document.createElement('div');
  container.style.position = 'fixed';
  container.style.top = '0';
  container.style.left = '-99999px';
  container.style.width = TABLE_PREFLIGHT_WIDTH_PX + 'px';
  container.className = 'sheet';
  container.style.padding = '0';
  container.style.margin = '0';
  container.style.direction = 'rtl';

  const HALF_WIDTH_PX = Math.floor((TABLE_PREFLIGHT_WIDTH_PX - 16) / 2); // 16px = מרווח בין 2 העמודות

  const styleTag = document.createElement('style');
  styleTag.textContent = printCss + `
    .preflight-compact table{ margin-bottom:4px !important; }
    .preflight-compact th, .preflight-compact td{ padding:2px 4px !important; line-height:1.1 !important; }
    .preflight-compact h2{ margin:8px 0 4px !important; padding-bottom:2px !important; }
    .preflight-compact h3{ margin:5px 0 2px !important; }
    .preflight-2col{ display:grid; grid-template-columns:1fr 1fr; gap:16px; align-items:start; break-inside:avoid; page-break-inside:avoid; }
    .preflight-2col > div{ min-width:0; }
    .preflight-2col table{ width:100%; }
  `;
  document.head.appendChild(styleTag);
  document.body.appendChild(container);

  // מודדת HTML נתון (מחרוזת) בקונטיינר ברוחב נתון, ללא class=sheet (כדי לא לנפח עם ה-
  // padding שלו — אותו תיקון שכבר בוצע ל-tmpMeasure הרגיל).
  function measureHtmlAtWidth(html, widthPx, compact){
    const tmp = document.createElement('div');
    tmp.style.position = 'fixed'; tmp.style.top = '0'; tmp.style.left = '-99999px';
    tmp.style.width = widthPx + 'px';
    if(compact) tmp.classList.add('preflight-compact');
    tmp.innerHTML = html;
    document.body.appendChild(tmp);
    const h = tmp.offsetHeight || 20;
    document.body.removeChild(tmp);
    return h;
  }

  const decisionLog = [];
  let usedHeight = 0; // הבלוק הראשון מתחיל בעמוד תוכן טרי (אחרי כריכה+תוכן עניינים)

  const newBlocks = [];

  // בלוקים שמודפסים בעמוד לרוחב נפרד (טבלת סיכום כבל מ"ג, מכולות אגירה, גידי AC) תמיד מתחילים
  // בעמוד חדש, והבלוק שאחריהם חוזר לעמוד לאורך חדש. בלי האיפוס הזה, תוכן ארוך בעמוד שלפניהם (למשל
  // תמונת אזור הבדיקה) גרם ל-Preflight "להעביר" את הטבלה לעמוד הבא — מחוץ לעמוד הרוחב (v2.2.495).
  const LANDSCAPE_ZONE_KEYS = ['hc-summary', 'sp-stor-table', 'sp-ac-table'];
  let prevWasLandscapeZone = false;
  blocks.forEach((block) => {
    const isLandscapeZone = LANDSCAPE_ZONE_KEYS.includes(block.sectionKey);
    if(block.pageBreak || isLandscapeZone || prevWasLandscapeZone) usedHeight = 0; // בלוק עם page-break כפוי כבר יתחיל בעמוד טרי (v2.420 וכו')
    prevWasLandscapeZone = isLandscapeZone;
    // בלוק שמודפס לרוחב לא מפוצל ע"י ה-Preflight (שמחשב לפי גובה עמוד לאורך): פיצול יצר "בלוק המשך"
    // שיצא מחוץ לאזור הרוחב והודפס בעמוד לאורך (למשל טבלת PI בדוח כבל מ"ג). הדפדפן עצמו ממשיך
    // טבלאות לעמוד רוחב נוסף כשצריך (v2.2.498).
    // + מצב קומפקטי (אותו CSS קיים של ה-Preflight) כדי שיותר שורות ייכנסו לכל עמוד רוחב.
    if(isLandscapeZone){ newBlocks.push(Object.assign({}, block, { html: `<div class="preflight-compact">${block.html}</div>` })); usedHeight = 0; return; }

    container.innerHTML = block.html;
    const topLevelNodes = Array.from(container.children);
    // *** v2.433 — בונים segments נפרדים (לא HTML מחרוזת אחת) בכל פעם שנוסף page-break
    // פנימי (MOVE_NEXT_PAGE/RELATED_TABLE_LAYOUT-fallback). כל segment הופך בסוף לבלוק
    // נפרד משלו עם pageBreak משלו — כדי ש-estimatePageNumbers (שרץ *אחרי* הפונקציה הזו)
    // ידע לשייך כל חלק לעמוד הנכון שלו בנפרד, במקום למדוד את כל התוכן (שכולל תוכן משני
    // צידי ה-break) כיחידת-גובה רציפה אחת ומנופחת — זה בדיוק מה שגרם לעמודים ריקים
    // (estimatePageNumbers חישב שהבלוק "עדיין לא נגמר" על העמוד הנוכחי לפי הגובה המנופח,
    // קפץ לעמוד הבא עבור הבלוק *כולו*, בזמן שבפועל רק חלק ממנו כבר עבר עמוד בעצמו).
    let segments = [''];
    let sawTable = false;
    let idx = 0;

    while(idx < topLevelNodes.length){
      const node = topLevelNodes[idx];
      // *** הרחבת Preflight (המשך עבודה): מזהה גם div.slope-test-card כיחידת packing
      // שלמה, לא רק <table> — Reuse מלא של אותה לוגיקת KEEP/COMPACT/MOVE_NEXT_PAGE, בלי
      // ליצור מנגנון חדש. שם המשתנה נשאר isTable מטעמי מינימום שינוי בהמשך הקוד למטה,
      // אך כעת מייצג "יחידת packing" באופן כללי יותר.
      const isSlopeCard = node.tagName === 'DIV' && node.classList.contains('slope-test-card');
      const isFinalizationGroup = node.tagName === 'DIV' && node.classList.contains('grounding-finalization-group');
      const isGroundClampCard = node.tagName === 'DIV' && node.classList.contains('ground-clamp-card');
      const isPanelGroup = node.tagName === 'DIV' && node.classList.contains('flex-panel-group');
      const isPanelUnit = node.tagName === 'DIV' && (node.classList.contains('flex-panel-unit') || isPanelGroup);
      const isTable = node.tagName === 'TABLE' || isSlopeCard || isFinalizationGroup || isGroundClampCard || isPanelUnit;
      const measureNode = node.cloneNode(true);
      const tmpMeasure = document.createElement('div');
      tmpMeasure.style.position = 'fixed'; tmpMeasure.style.top='0'; tmpMeasure.style.left='-99999px';
      tmpMeasure.style.width = TABLE_PREFLIGHT_WIDTH_PX + 'px';
      // לא class="sheet" — זה היה מוסיף את ה-padding של .sheet עצמו (כולל padding-bottom:
      // 90px מ-v2.413) לכל מדידת-צומת בודדת, מנפח כל גובה נמדד. כללי CSS ל-table/th/td
      // גלובליים (לא תלויים ב-.sheet כהורה), אז המדידה עדיין מדויקת בלי ה-padding המיותר.
      tmpMeasure.appendChild(measureNode);
      document.body.appendChild(tmpMeasure);
      const nodeHeight = tmpMeasure.offsetHeight || 20;
      // קבוצת לוח+תמונות שגבוהה מעמוד שלם — מפרקים לחלקיה (הלוח כיחידה, ואחריו התמונות)
      if(isPanelGroup && nodeHeight > TABLE_PREFLIGHT_PAGE_HEIGHT_PX){
        document.body.removeChild(tmpMeasure);
        const parts = [];
        Array.from(node.children).forEach(ch => { if(ch.classList.contains('flex-panel-photos')) parts.push(...Array.from(ch.children)); else parts.push(ch); });
        topLevelNodes.splice(idx, 1, ...parts);
        continue;
      }

      if(!isTable){
        usedHeight += nodeHeight;
        segments[segments.length-1] += node.outerHTML;
        document.body.removeChild(tmpMeasure);
        idx++;
        continue;
      }

      sawTable = true;
      const remainingPageHeight = Math.max(0, TABLE_PREFLIGHT_PAGE_HEIGHT_PX - usedHeight);
      let decision, finalHeight = nodeHeight, breakBefore = false, compactedHeight = null;
      let consumedExtra = 0; // כמה צמתים נוספים "נבלעו" (לזיווג 2-עמודות)
      let pairedHtml = null;

      // *** RELATED_TABLE_LAYOUT (v2.432) — מנוסה *יזום*, לא רק כמוצא אחרון: טבלת "מידע"
      // צרה (class=tinfo-table — בדיוק הסגנון של "פרטי שנאי בית" מ-v2.430, key/value דו-
      // טורית) כמעט תמיד "נכנסת" לבד כ-KEEP (היא קטנה), ולכן לעולם לא הייתה מגיעה לענף
      // "לא נכנסת" שבו זיווג מנוסה כמוצא אחרון. מכיוון שהמטרה היא לנצל את *רוחב* העמוד
      // (לא רק את הגובה) — מנסים זיווג תמיד כשיש tinfo-table עם טבלה נוספת מיד אחריה
      // (אולי עם כותרת H2/H3 צמודה ביניהן), ורק אם הזיווג לא רלוונטי/לא מצליח בפועל (נמדד
      // אמיתי) — חוזרים לזרימה הרגילה. מוגבל במפורש ל-tinfo-table (לא כל טבלה) כדי לא
      // לדחוס טבלאות רחבות/מרובות-עמודות זו לצד זו ולפגוע בקריאות, בדיוק כפי שהתבקש
      // ("אם אחת הטבלאות גדולה: השאר Full Width").
      const isNarrowInfoTable = isTable && node.classList.contains('tinfo-table');
      if(isNarrowInfoTable){
        let pairStartIdx = idx + 1, pairIncludesHeading = false, headingHtml = '';
        let nextIsHeading = pairStartIdx < topLevelNodes.length && /^H[23]$/.test(topLevelNodes[pairStartIdx].tagName);
        if(nextIsHeading){
          headingHtml = topLevelNodes[pairStartIdx].outerHTML;
          pairIncludesHeading = true;
          pairStartIdx++;
        }
        const candidateNode = pairStartIdx < topLevelNodes.length ? topLevelNodes[pairStartIdx] : null;
        const candidateIsTable = candidateNode && candidateNode.tagName === 'TABLE';
        if(candidateIsTable){
          const leftHtml = node.outerHTML;
          const rightHtml = headingHtml + candidateNode.outerHTML;
          const leftHalfHeight = measureHtmlAtWidth(leftHtml, HALF_WIDTH_PX, false);
          const rightHalfHeight = measureHtmlAtWidth(rightHtml, HALF_WIDTH_PX, false);
          let combinedHeight = Math.max(leftHalfHeight, rightHalfHeight);
          let usedCompactPair = false;
          if(combinedHeight > remainingPageHeight){
            const leftCompact = measureHtmlAtWidth(leftHtml, HALF_WIDTH_PX, true);
            const rightCompact = measureHtmlAtWidth(rightHtml, HALF_WIDTH_PX, true);
            const combinedCompact = Math.max(leftCompact, rightCompact);
            if(combinedCompact <= remainingPageHeight){
              combinedHeight = combinedCompact;
              usedCompactPair = true;
            }
          }
          if(combinedHeight <= remainingPageHeight){
            decision = 'RELATED_TABLE_LAYOUT';
            finalHeight = combinedHeight;
            const compactClass = usedCompactPair ? ' preflight-compact' : '';
            pairedHtml = `<div class="preflight-2col${compactClass}"><div>${leftHtml}</div><div>${rightHtml}</div></div>`;
            consumedExtra = pairIncludesHeading ? 2 : 1;
          }
        }
      }

      if(decision === 'RELATED_TABLE_LAYOUT'){
        // זיווג יזום הצליח — מדלגים לרישום ההחלטה, לא בודקים KEEP/COMPACT רגיל לטבלה הזו
      } else if(nodeHeight <= remainingPageHeight){
        decision = 'KEEP';
      } else {
        measureNode.classList.add('preflight-compact');
        compactedHeight = tmpMeasure.offsetHeight || nodeHeight;
        if(compactedHeight <= remainingPageHeight){
          decision = 'COMPACT';
          finalHeight = compactedHeight;
        } else {
          // מוצא אחרון (טבלה רגילה שאינה tinfo-table, או tinfo-table בלי זיווג יזום מוצלח):
          // נסיון זיווג נוסף לפני MOVE_NEXT_PAGE — מכסה גם את המקרה ההפוך (טבלה רגילה
          // שלא נכנסת, עם tinfo-table/טבלה קצרה מיד אחריה) שלא טופל למעלה כי isNarrowInfoTable
          // בדק רק את הטבלה הנוכחית.
          // את הגובה שלו), בדיוק כפי שהתבקש. "קשורה" = סמוכה בזרימת המסמך (הדוגמה הקונקרטית
          // שהתבקשה: פרטי שנאי + מיד אחריה בדיקת אותו שנאי). רק שתי טבלאות אמיתיות (לא
          // תוכן אחר) מוצעות לזיווג, ורק אם שתיהן בפועל נכנסות יחד ברוחב חצי-עמוד — נמדד
          // באמת (measureHtmlAtWidth), לא מוערך.
          let pairStartIdx = idx + 1, pairIncludesHeading = false, headingHtml = '';
          let nextIsHeading = pairStartIdx < topLevelNodes.length && /^H[23]$/.test(topLevelNodes[pairStartIdx].tagName);
          if(nextIsHeading){
            headingHtml = topLevelNodes[pairStartIdx].outerHTML;
            pairIncludesHeading = true;
            pairStartIdx++;
          }
          const candidateNode = pairStartIdx < topLevelNodes.length ? topLevelNodes[pairStartIdx] : null;
          const candidateIsTable = candidateNode && candidateNode.tagName === 'TABLE';

          if(candidateIsTable){
            const leftHtml = node.outerHTML;
            const rightHtml = headingHtml + candidateNode.outerHTML;
            const leftHalfHeight = measureHtmlAtWidth(leftHtml, HALF_WIDTH_PX, false);
            const rightHalfHeight = measureHtmlAtWidth(rightHtml, HALF_WIDTH_PX, false);
            let combinedHeight = Math.max(leftHalfHeight, rightHalfHeight);
            let usedCompactPair = false;
            if(combinedHeight > remainingPageHeight){
              // מנסים גם דחיסה עדינה בתוך הזיווג (לא font-size, אותו CSS כמו COMPACT רגיל)
              const leftCompact = measureHtmlAtWidth(leftHtml, HALF_WIDTH_PX, true);
              const rightCompact = measureHtmlAtWidth(rightHtml, HALF_WIDTH_PX, true);
              const combinedCompact = Math.max(leftCompact, rightCompact);
              if(combinedCompact <= remainingPageHeight){
                combinedHeight = combinedCompact;
                usedCompactPair = true;
              }
            }
            if(combinedHeight <= remainingPageHeight){
              decision = 'RELATED_TABLE_LAYOUT';
              finalHeight = combinedHeight;
              const compactClass = usedCompactPair ? ' preflight-compact' : '';
              pairedHtml = `<div class="preflight-2col${compactClass}"><div>${leftHtml}</div><div>${rightHtml}</div></div>`;
              consumedExtra = pairIncludesHeading ? 2 : 1;
            }
          }

          if(decision !== 'RELATED_TABLE_LAYOUT'){
            if(nodeHeight <= TABLE_PREFLIGHT_PAGE_HEIGHT_PX || isSlopeCard || isFinalizationGroup || isGroundClampCard || isPanelUnit){
              // slope-test-card אינו splittable (לפי דרישה מפורשת) — גם אם, במקרה קיצון,
              // הוא גדול מעמוד שלם, מעבירים אותו שלם כ-best-effort במקום לנסות SPLIT
              // (שנועד לטבלאות עם thead-repeat, לא רלוונטי כאן).
              decision = 'MOVE_NEXT_PAGE';
              breakBefore = true;
              finalHeight = nodeHeight;
              measureNode.classList.remove('preflight-compact');
            } else {
              decision = 'SPLIT';
            }
          }
        }
      }
      document.body.removeChild(tmpMeasure);

      if(breakBefore && idx > 0){
        const prevNode = topLevelNodes[idx-1];
        if(prevNode && /^H[23]$/.test(prevNode.tagName)){
          // הכותרת הצמודה זזה יחד עם הטבלה ל-segment החדש (לא נשארת יתומה ב-segment הקודם)
          const headingHtml2 = prevNode.outerHTML;
          const cutIdx = segments[segments.length-1].lastIndexOf(headingHtml2);
          if(cutIdx !== -1){
            const movedHeading = segments[segments.length-1].slice(cutIdx);
            segments[segments.length-1] = segments[segments.length-1].slice(0, cutIdx);
            segments.push(movedHeading);
          } else {
            segments.push('');
          }
        } else {
          segments.push('');
        }
      }

      const nodeHtml = decision === 'RELATED_TABLE_LAYOUT' ? pairedHtml
        : (decision === 'COMPACT') ? measureNode.outerHTML : node.outerHTML;
      segments[segments.length-1] += nodeHtml;

      if(decision === 'MOVE_NEXT_PAGE'){
        usedHeight = finalHeight;
      } else {
        usedHeight += finalHeight;
      }

      decisionLog.push({
        section: block.title || block.sectionKey,
        tableHeight: Math.round(nodeHeight),
        remainingPageHeight: Math.round(remainingPageHeight),
        compactedHeight: compactedHeight !== null ? Math.round(compactedHeight) : null,
        decision,
      });

      idx += 1 + consumedExtra;
    }

    // *** v2.433 — כל segment הופך לבלוק נפרד משלו ב-newBlocks (לא block.html יחיד עם
    // p-page-break מוטמע באמצע) — כדי ש-estimatePageNumbers שרץ מיד אחרי applyTablePreflight
    // ימדוד כל חלק כנפרד (עם pageBreak:true על כל segment חוץ מהראשון), ולא יראה גובה
    // רציף-מנופח אחד שגורם לו "לקפוץ" בטעות עמוד שלם קדימה (בדיוק מה שיצר את העמודים
    // הריקים שדווחו). segment ראשון שומר את ה-pageBreak המקורי של הבלוק (למשל v2.420 —
    // פרק תמונות); כל segment נוסף (שנוצר מ-breakBefore פנימי) מקבל pageBreak:true במפורש.
    if(segments.length > 1 || sawTable){
      segments.forEach((segHtml, segIdx) => {
        if(!segHtml) return; // segment ריק (למשל לא הייתה כותרת להזיז) — לא דוחפים בלוק ריק
        newBlocks.push({
          level: block.level, sectionKey: block.sectionKey, title: block.title,
          html: segHtml,
          pageBreak: segIdx === 0 ? !!block.pageBreak : true,
        });
      });
    } else {
      newBlocks.push(block);
    }
  });

  document.body.removeChild(container);
  document.head.removeChild(styleTag);
  blocks.length = 0;
  newBlocks.forEach(b => blocks.push(b));
  return decisionLog;
}

function estimatePageNumbers(blocks){
  // Approximate page numbers by measuring rendered block heights against an A4 print page's content area.
  // v2.2.531 — מרווח ביטחון גדול יותר: טקסט ארוך (למשל ניתוח AI) "גלש" לפעמים 1–2 שורות לעמוד נוסף בלי כותרת.
  const pageHeightPx = 975;   // ~271mm content height at 96dpi, מינוס שולי בטיחות
  const measureWidthPx = 680; // ~180mm content width at 96dpi

  const container = document.createElement('div');
  container.style.position = 'fixed';
  container.style.top = '0';
  container.style.left = '-99999px';
  container.style.width = measureWidthPx + 'px';
  container.style.fontFamily = 'Arial, Tahoma, sans-serif';
  container.style.direction = 'rtl';
  container.className = 'sheet toc-measure';
  // *** תיקון קריטי (סבב זה): הסרת 'sheet' לגמרי (ניסיון קודם) שברה כללי CSS חיוניים
  // רבים שמקוננים תחת .sheet (למשל ".sheet table{font-size:10.5px}", ".sheet th/td
  // {padding}", ".sheet h1/h2/h3{font-size}") — גרם לניפוח מסיבי (SMA: 12->20 עמודים!)
  // כי טבלאות נמדדו בלי font-size/padding נכונים בכלל. התיקון הנכון: משאירים 'sheet'
  // (כל הכללים החיוניים האלה חוזרים לפעול כרגיל), אבל מבטלים ישירות (inline style,
  // עדיפות גבוהה יותר מ-CSS class) רק את ה-padding הבעייתי של .sheet עצמו (כולל
  // padding-bottom:90px מ-v2.413) שהיה הגורם המקורי לניפוח שניסיתי לתקן מלכתחילה.
  container.style.padding = '0';
  container.style.margin = '0';

  const styleTag = document.createElement('style');
  // *** תוקן (המשך עבודה על slope-test-card): קודם הייתה כאן רשימת CSS מקורבת, ידנית
  // (.toc-measure), שלא כללה את כללי ה-grid החדשים של .slope-test-card/.slope-test-grid.
  // התוצאה: div הנתונים ו-div הגרף "נערמו" זה-מתחת-לזה במדידה (בלי display:grid), במקום
  // זה-לצד-זה כמו בהדפסה האמיתית — מכפיל בערך את הגובה הנמדד, וגרם לבדיקה3 להידחק לעמוד
  // נפרד למרות שה-Preflight (שכבר השתמש ב-CSS האמיתי) קבע KEEP. תוקן: אותו extractPrintCss()
  // בדיוק שכבר הוכח נכון ב-applyTablePreflight (v2.431, "המקור היחיד לאמת") — לא קירוב נפרד
  // שעלול לצאת מסונכרן מול CSS אמיתי עתידי, לא רק עבור slope-test-card אלא לכל class.
  styleTag.textContent = extractPrintCss();
  document.head.appendChild(styleTag);
  document.body.appendChild(container);

  let pageNum = 2; // page 1 = cover, page 2 = table of contents
  let usedHeight = Infinity; // forces the first block onto a fresh page (page 3)
  const pages = [];

  // בלוק שמכיל רק כותרת (h2/h3) בלי תוכן ממשי משלו — לרוב "שם" (למשל כותרת הממיר) שתמיד
  // מלווה מיד בבלוק התוכן הבא (הבדיקה הראשונה שלו). בלוק כזה לא אמור "להצליח להיכנס" לבד
  // בתחתית עמוד אם אין מתחתיו מקום ולו למעט שורות מהתוכן שבא אחריו — אחרת הוא נשאר יתום.
  // לא בודקים מול הגובה המלא של הבלוק הבא (שעלול להיות טבלה ארוכה שבכל מקרה תתפרס על
  // כמה עמודים) — רק מול סף מינימלי סביר (כותרת טבלה + שורה או שתיים), כדי לא לדחוף את
  // כל הכותרת לעמוד חדש כשמספיק שהיא תתחיל עם רק חלק מהתוכן שאחריה.
  const isHeadingOnlyBlock = (html) => /^\s*<h[23]>[^<]*<\/h[23]>\s*$/.test(html);
  const minFollowupPx = 70;

  blocks.forEach((block, i)=>{
    container.innerHTML = block.html;
    const h = container.offsetHeight || 24;

    if(isHeadingOnlyBlock(block.html) && blocks[i+1]){
      const fitsAlone = usedHeight + h <= pageHeightPx;
      const fitsWithMinFollowup = usedHeight + h + minFollowupPx <= pageHeightPx;
      if(fitsAlone && !fitsWithMinFollowup){
        // אין מקום אפילו למעט שורות אחרי הכותרת — פותחים עמוד חדש בשבילה,
        // אבל שומרים על הגובה האמיתי (הקטן) שלה כדי שהבלוק הבא (התוכן ששייך לה)
        // עדיין יתחיל באותו עמוד חדש ולא יידחק לעוד עמוד נוסף.
        pageNum += 1;
        usedHeight = h;
        pages.push(pageNum);
        return;
      }
    }

    // *** בלוק הסיום (אישור/מסקנות/הערות בודק/חתימה/הצהרת חשמלאי) — GROUNDING בלבד:
    // לפני שדוחפים את כל הבלוק לעמוד הבא (h לא נכנס בשטח שנותר), מנסים גרסה מכווצת
    // באמצעות אותו preflight-compact class הקיים (Reuse מלא — לא מנגנון חדש, אותו CSS
    // שכבר משמש את applyTablePreflight ל-slope-test-card ולטבלאות). אם המכווץ נכנס —
    // משתמשים בו בפועל (גם למדידה, גם ל-HTML הסופי שמודפס). אם גם המכווץ לא נכנס —
    // נופלים חזרה להתנהגות הרגילה: כל הבלוק (שלם, לא מפוצל) עובר לעמוד הבא, לפי הדרישה
    // המפורשת "אין לפצל את הצהרת החשמלאי באמצע" ו"העדף להעביר את כל קבוצת הסיום לעמוד
    // הבא" כשהדחיסה הבטוחה לא מספיקה.
    if(block.sectionKey === 'approval' && getReportType() === 'GROUNDING' && !block.pageBreak){
      const remainingNow = pageHeightPx - usedHeight;
      if(h > remainingNow){
        const compactHtml = `<div class="preflight-compact">${block.html}</div>`;
        container.innerHTML = compactHtml;
        const compactH = container.offsetHeight || h;
        if(compactH <= remainingNow){
          block.html = compactHtml; // אותו HTML בפועל יודפס — לא רק נמדד
          pages.push(pageNum);
          usedHeight += compactH;
          return;
        }
      }
    }

    if(block.pageBreak || usedHeight + h > pageHeightPx){
      pageNum += 1;
      usedHeight = 0;
    }
    pages.push(pageNum);
    usedHeight += h;
  });

  document.body.removeChild(container);
  document.head.removeChild(styleTag);
  return pages;
}

function buildTocTable(blocks, pages, totalPages){
  let counter = 0;
  const rows = blocks.map((b,i)=>{
    if(b.level===1) counter++;
    const label = b.level===1 ? `${counter}. ${escapeHtml(b.title)}` : escapeHtml(b.title);
    return `<tr class="${b.level===1?'toc-l1':'toc-l2'}">
      <td class="toc-topic">${label}</td>
      <td class="toc-page">${pages[i]}</td>
    </tr>`;
  }).join('');

  return `
    <div class="toc-banner">תוכן עניינים</div>
    <table class="toc-table">
      <thead><tr><th class="toc-topic">נושא</th><th class="toc-page">עמוד</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>`;
}

function buildReportBlocks(){
  const m = state.meta;
  const blocks = []; // { level(1|2), title, html, pageBreak, sectionKey }
  let photoCounter = 1;

  // בלוק "לכבוד/לידי" הוסר לגמרי, לכל סוגי הדוח — לפי בקשה מפורשת ("על כל סוגי הדוח
  // באפליקציה"). עמוד השער כבר מציג "לכבוד" בטבלת הפרטים, כך שהבלוק הנפרד (שתפס עמוד שלם
  // כמעט-ריק, לפני שאר תוכן הדוח) מיותר. היה מוחרג בעבר רק ל-MAIN_PANEL/TRANSFORMER_
  // INSPECTION (v2.218/2.241) — עכשיו מוסר לגמרי, לא מותנה בסוג הדוח.

  // בלוק "תיאור המתקן / העבודה" הנפרד הוסר גם הוא לגמרי, לכל סוגי הדוח — עבר לטבלת עמוד
  // השער (ראה infoRows למעלה). היה מוחרג בעבר רק לחלק מסוגי הדוח — עכשיו מוסר לגמרי.

  if(getReportType() === 'SMA'){
    const vs = state.voltageSystem;
    if(vs.voltageClass || vs.nominalVoltage){
      const vsRows = [
        ['מסדר מתח', vs.voltageClass],
        ['מתח נומינלי', vs.nominalVoltage ? formatMeasurement(vs.nominalVoltage, vs.voltageUnit) : '']
      ].filter(r=>r[1]);
      if(vsRows.length) blocks.push({level:1, sectionKey:'voltageSystem', title:'מסדר מתח', html:`<h2>מסדר מתח</h2><table class="tinfo-table">${vsRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`});
    }

    const relevantCells = vs.hvCells.filter(c=>c.cellType || c.cellName || c.manufacturer || c.serialNo);
    if(relevantCells.length){
      const cellBlocks = relevantCells.map((c,i)=>{
        const rows = [
          ['סוג תא', c.cellType], ['שם התא', c.cellName], ['מספר תא', c.cellNumber],
          ['יצרן', c.manufacturer], ['דגם', c.model], ['מספר סידורי', c.serialNo], ['שנת ייצור', c.yearOfManufacture],
          ['מתח נקוב', c.ratedVoltage?formatMeasurement(c.ratedVoltage,c.ratedVoltageUnit):''],
          ['זרם נקוב', c.ratedCurrent?formatMeasurement(c.ratedCurrent,c.ratedCurrentUnit):''],
          ['כושר ניתוק', c.breakingCapacity?formatMeasurement(c.breakingCapacity,c.breakingCapacityUnit):''],
          ['סוג בידוד', c.insulationType], ['סוג מפסק', c.breakerType], ['סוג מנתק', c.disconnectorType],
          ['סוג הארקה', c.groundingType], ['ממסר הגנה', c.protectionRelay], ['CT', c.ct], ['VT', c.vt]
        ].filter(r=>r[1]);
        // טבלה קומפקטית — שני שדות (כותרת|ערך) בכל שורה, 4 עמודות, לפי בקשה מפורשת (אותה
        // גישה כמו "בדיקה ויזואלית"). אותה פונקציה משותפת שכבר בשימוש ב-MAIN_PANEL עבור אותה
        // בדיוק טבלה — לא לוגיקה חדשה, רק עקביות. הכותרת ("תא X — שם") מוצגת כשורה ראשונה
        // בתוך הטבלה עצמה (colspan=4), לא כ-<h3> נפרד לפניה — התבנית הבטוחה היחידה שמונעת
        // אובדן שורות בפיצול עמוד (ראו הערת printCompact2ColTable).
        let html = '';
        if(rows.length) html += printCellTable(rows, `תא ${i+1}${c.cellName?' — '+c.cellName:''}`);
        else html += `<h3 style="font-size:12.5px; margin:0 0 4px;">תא ${i+1}${c.cellName?' — '+escapeHtml(c.cellName):''}</h3>`;
        if(c.description) html += `<p style="font-size:11px; margin:4px 0 0;"><b>תיאור:</b> ${escapeHtml(c.description)}</p>`;
        if(c.notes) html += `<p style="font-size:11px; margin:4px 0 0;"><b>הערות:</b> ${escapeHtml(c.notes)}</p>`;
        // break-inside:avoid — לא לפצל טבלת תא בין שני עמודים ב-PDF, לפי דרישה מפורשת.
        return `<div style="break-inside:avoid; page-break-inside:avoid;">${html}</div>`;
      });
      // רשת שתי עמודות RTL (תא 1 מימין); כל זוג תאים בלוק נפרד (v2.2.546) — מונע עמוד ריק
      for(let x = 0; x < cellBlocks.length; x += 2){
        const grid = `<div style="display:grid; grid-template-columns:repeat(2, minmax(0, 1fr)); gap:10px 14px; align-items:start; margin-bottom:10px;">${cellBlocks.slice(x, x+2).join('')}</div>`;
        blocks.push({level:1, sectionKey: x === 0 ? 'hvCells' : 'hvCells-' + x, title: x === 0 ? 'תאי מתח גבוה' : 'תאי מתח גבוה (המשך)', html: (x === 0 ? `<h2>תאי מתח גבוה</h2>` : '') + grid});
      }
    }

    const gpd = state.generalPanelDetails;
    const gpdRows = [
      ['שם הלוח', gpd.panelName], ['מס\' פרויקט', gpd.projectNumber], ['סוג הלוח', gpd.panelType],
      ['כיבוי', gpd.extinguishing], ['גילוי', gpd.detection], ['ניתוק', gpd.disconnection]
    ].filter(r=>r[1]);
    if(gpdRows.length) blocks.push({level:1, sectionKey:'generalPanelDetails', title:'פרטי לוח חשמל', html:`<h2>פרטי לוח חשמל</h2><table class="tinfo-table">${gpdRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`});

    const gv = printItemsTable(GENERAL_VISUAL, state.generalVisual, 'generalVisual');
    const gvNotesBlock = printSectionNotesBlock(state.generalVisualSectionNotes);
    if(gv || gvNotesBlock) blocks.push({level:1, sectionKey:'generalVisual', title:'בדיקה ויזואלית כללית', html:`<h2>בדיקה ויזואלית כללית</h2>${gv||''}${gvNotesBlock}`});

    // SMA, סעיף 03 — לולאה על [mainSwitchgear, ...mainSwitchgearExtra], לפי סדר התצוגה
    // במסך. כשיש רק יחידה אחת (totalCount===1, המצב הנפוץ) — אותה כותרת/sectionKey בדיוק
    // כפי שהיו תמיד, אפס שינוי בפלט PDF לדוחות קיימים ללא שכפול.
    const msUnits = [state.mainSwitchgear, ...state.mainSwitchgearExtra];
    msUnits.forEach((msUnit, msIdx) => {
      const msTable = printItemsTable(MAIN_SWITCHGEAR_CHECKLIST, msUnit.checklist, `mainSwitchgear.checklist.${msIdx}`);
      const relevantPanelRows = msUnit.panelRows.filter(r=>r.panelName || r.cellNo || r.cellName || r.switchgearSerialNo || r.protections);
      const ad = msUnit.assemblyDetails;
      const adRows = [
        ['שם המסדר', ad.name], ['יצרן', ad.manufacturer], ['דגם', ad.model], ['מספר סידורי', ad.serialNo],
        ['שנת ייצור', ad.yearOfManufacture],
        ['מתח נקוב', ad.ratedVoltage?formatMeasurement(ad.ratedVoltage,ad.ratedVoltageUnit):''],
        ['זרם נקוב', ad.ratedCurrent?formatMeasurement(ad.ratedCurrent,ad.ratedCurrentUnit):''],
        ['כושר ניתוק', ad.breakingCapacity?formatMeasurement(ad.breakingCapacity,ad.breakingCapacityUnit):''],
        ['מספר תאים', ad.numberOfCells], ['סוג בידוד', ad.insulationType], ['דרגת הגנה IP', ad.ipRating],
        ['תקן', ad.standard], ['מיקום התקנה', ad.installLocation]
      ].filter(r=>r[1]);
      if(msTable || msUnit.notes || msUnit.cabinetDetails || relevantPanelRows.length || adRows.length || ad.notes){
        let h = '';
        if(adRows.length) h += `<h3 style="font-size:13px;">פרטי מסדר מתח גבוה</h3><table class="tinfo-table">${adRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(ad.notes) h += `<p style="font-size:12px;"><b>הערות למסדר:</b> ${escapeHtml(ad.notes)}</p>`;
        if(msTable) h += `<h3 style="font-size:13px;">בדיקה ויזואלית — מסדר</h3>${msTable}`;
        if(msUnit.cabinetDetails) h += `<p style="font-size:12px;"><b>פרטי תאים וציוד:</b> ${escapeHtml(msUnit.cabinetDetails)}</p>`;
        if(msUnit.notes) h += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(msUnit.notes)}</p>`;
        if(relevantPanelRows.length){
          h += `<h3 style="font-size:13px;">פרטי לוח מתח גבוה</h3><table><thead><tr><th>שם הלוח</th><th>מס' תא</th><th>שם התא</th><th>מס' סידורי של המסדר</th><th>הגנות קיימות</th></tr></thead><tbody>${relevantPanelRows.map(r=>`<tr><td>${escapeHtml(r.panelName)}</td><td>${escapeHtml(r.cellNo)}</td><td>${escapeHtml(r.cellName)}</td><td>${escapeHtml(r.switchgearSerialNo)}</td><td>${escapeHtml(r.protections)}</td></tr>`).join('')}</tbody></table>`;
        }
        const msTitle = msUnits.length === 1 ? 'מסדר מתח גבוה ראשי' : `מסדר מתח גבוה — מסדר ${msIdx+1}`;
        blocks.push({level:1, sectionKey:'mainSwitchgear-'+msIdx, title:msTitle, html:`<h2>${msTitle}</h2>${h}`});
      }
    });

    // הערה כללית לכרטיס "תאי מתח גבוה" (voltageSystem.hvCells) — הכרטיס עצמו (רשימת התאים)
    // לא היה מודפס כלל עד כה (אין לו בלוק PDF קיים), כך שההערה הכללית מודפסת כבלוק עצמאי
    // משלה, לא בתוך טבלה שלא קיימת ממילא. לא נוגע ב-cell.notes של כל תא בנפרד.
    const hvCellsNotesBlock = printSectionNotesBlock(state.voltageSystem.hvCellsSectionNotes);
    if(hvCellsNotesBlock) blocks.push({level:1, sectionKey:'hv-cells', title:'תאי מתח גבוה', html:`<h2>תאי מתח גבוה</h2>${hvCellsNotesBlock}`});

    state.panelOrder.forEach(id=>{
      const panel = state.panels[id];
      const sectionKey = 'panel:'+id;
      const title = panel.name || ('ממיר ' + getInverterBrandLabel());
      const headingParts = [
        panel.inverterManufacturer ? "יצרן: "+escapeHtml(panel.inverterManufacturer) : '',
        panel.inverterModel ? "דגם: "+escapeHtml(panel.inverterModel) : '',
        panel.serial ? "מס' סידורי: "+escapeHtml(panel.serial) : ''
      ].filter(Boolean);
      const heading = title + (headingParts.length ? " — " + headingParts.join(', ') : '');
      blocks.push({level:1, sectionKey, title, html:`<h2>${heading}</h2>`});

      const lv = printItemsTable(MAIN_SWITCHGEAR_CHECKLIST, panel.checklist, `panels.${id}.checklist`);
      if(lv || panel.cabinetDetails){
        let lvh = lv;
        if(panel.cabinetDetails) lvh += `<p style="font-size:12px;"><b>פרטי תאים וציוד:</b> ${escapeHtml(panel.cabinetDetails)}</p>`;
        blocks.push({level:2, sectionKey, title:'בדיקה ויזואלית — לוח', html:`<h3>בדיקה ויזואלית — לוח</h3>${lvh}`});
      }

      const had = panel.hvAssemblyDetails || {};
      const hadRows = [
        ['שם המסדר', had.name], ['יצרן', had.manufacturer], ['דגם', had.model], ['מספר סידורי', had.serialNo],
        ['שנת ייצור', had.yearOfManufacture],
        ['מתח נקוב', had.ratedVoltage?formatMeasurement(had.ratedVoltage,had.ratedVoltageUnit):''],
        ['זרם נקוב', had.ratedCurrent?formatMeasurement(had.ratedCurrent,had.ratedCurrentUnit):''],
        ['כושר ניתוק', had.breakingCapacity?formatMeasurement(had.breakingCapacity,had.breakingCapacityUnit):''],
        ['מספר תאים', had.numberOfCells], ['סוג בידוד', had.insulationType], ['דרגת הגנה IP', had.ipRating],
        ['תקן', had.standard], ['מיקום התקנה', had.installLocation]
      ].filter(r=>r[1]);
      if(hadRows.length || had.notes){
        let hadHtml = '';
        if(hadRows.length) hadHtml += `<table class="tinfo-table">${hadRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(had.notes) hadHtml += `<p style="font-size:12px;"><b>הערות למסדר:</b> ${escapeHtml(had.notes)}</p>`;
        blocks.push({level:2, sectionKey, title:'פרטי מסדר מתח גבוה', html:`<h3>פרטי מסדר מתח גבוה</h3>${hadHtml}`});
      }

      const relevantHvCells = (panel.hvCellsList||[]).filter(c=>c.cellType || c.cellName || c.manufacturer || c.serialNo);
      if(relevantHvCells.length){
        const cellBlocksHtml = relevantHvCells.map((c,i)=>{
          const rows = [
            ['סוג תא', c.cellType], ['שם התא', c.cellName], ['מספר תא', c.cellNumber],
            ['יצרן', c.manufacturer], ['דגם', c.model], ['מספר סידורי', c.serialNo], ['שנת ייצור', c.yearOfManufacture],
            ['מתח נקוב', c.ratedVoltage?formatMeasurement(c.ratedVoltage,c.ratedVoltageUnit):''],
            ['זרם נקוב', c.ratedCurrent?formatMeasurement(c.ratedCurrent,c.ratedCurrentUnit):''],
            ['כושר ניתוק', c.breakingCapacity?formatMeasurement(c.breakingCapacity,c.breakingCapacityUnit):''],
            ['סוג בידוד', c.insulationType], ['סוג מפסק', c.breakerType], ['סוג מנתק', c.disconnectorType],
            ['סוג הארקה', c.groundingType], ['ממסר הגנה', c.protectionRelay], ['CT', c.ct], ['VT', c.vt]
          ].filter(r=>r[1]);
          // טבלה קומפקטית — אותה פונקציה משותפת כמו state.voltageSystem.hvCells (v2.371) ו-
          // MAIN_PANEL. זה מופע שלישי, נפרד, שפוספס בסבב הקודם (panel.hvCellsList — תאי מתח
          // גבוה פר-ממיר, לא הרשימה הגלובלית) — כנראה זה המופע שבפועל מוצג ברוב הדוחות, בהתחשב
          // שרוב הדוחות עם כמה ממירים מגדירים תאים בנפרד לכל ממיר, לא ברשימה הגלובלית האחת.
          let h = '';
          if(rows.length) h += printCompact2ColTable(rows, `תא ${i+1}${c.cellName?' — '+c.cellName:''}`);
          else h += `<p style="font-size:12px; font-weight:700; margin-bottom:4px;">תא ${i+1}${c.cellName?' — '+escapeHtml(c.cellName):''}</p>`;
          if(c.description) h += `<p style="font-size:11.5px;">${escapeHtml(c.description)}</p>`;
          if(c.notes) h += `<p style="font-size:11.5px;">${escapeHtml(c.notes)}</p>`;
          return `<div style="break-inside:avoid; page-break-inside:avoid;">${h}</div>`;
        }).join('');
        blocks.push({level:2, sectionKey, title:'תאי מתח גבוה', html:`<h3>תאי מתח גבוה</h3>${cellBlocksHtml}`});
      }

      const relevantHvRows = (panel.hvPanelRows||[]).filter(r=>r.panelName || r.cellNo || r.cellName || r.switchgearSerialNo || r.protections);
      if(relevantHvRows.length){
        const hvRowsHtml = relevantHvRows.map(r=>`<tr><td>${escapeHtml(r.panelName)}</td><td>${escapeHtml(r.cellNo)}</td><td>${escapeHtml(r.cellName)}</td><td>${escapeHtml(r.switchgearSerialNo)}</td><td>${escapeHtml(r.protections)}</td></tr>`).join('');
        blocks.push({level:2, sectionKey, title:'פרטי לוח מתח גבוה', html:`<h3>פרטי לוח מתח גבוה</h3><table><thead><tr><th>שם הלוח</th><th>מס' תא</th><th>שם התא</th><th>מס' סידורי של המסדר</th><th>הגנות קיימות</th></tr></thead><tbody>${hvRowsHtml}</tbody></table>`});
      }

      const t = panel.transformer;
      const transformerTitle = t.name ? `שנאי — ${escapeHtml(t.name)}` : 'שנאי';
      const voltageCombined = (t.voltagePrimary && t.voltageSecondary) ? `${t.voltagePrimary}/${t.voltageSecondary}`
        : (t.voltagePrimary || t.voltageSecondary || '');
      const tRows = [
        t.mfr ? `<tr><td class="tinfo-label">תוצרת</td><td>${escapeHtml(t.mfr)}</td></tr>` : '',
        t.serialNo ? `<tr><td class="tinfo-label">מס' יצרן</td><td>${escapeHtml(t.serialNo)}</td></tr>` : '',
        t.year ? `<tr><td class="tinfo-label">שנת ייצור</td><td>${escapeHtml(t.year)}</td></tr>` : '',
        t.power ? `<tr><td class="tinfo-label">הספק (kVA)</td><td>${escapeHtml(t.power)}</td></tr>` : '',
        voltageCombined ? `<tr><td class="tinfo-label">מתח נומינלי (Kv)</td><td><span dir="ltr">${escapeHtml(voltageCombined)}</span></td></tr>` : '',
        t.shortCircuitVoltage ? `<tr><td class="tinfo-label">מתח קצר (%)</td><td>${escapeHtml(t.shortCircuitVoltage)}</td></tr>` : '',
        t.connectionGroup ? `<tr><td class="tinfo-label">סדר חיבורים</td><td>${escapeHtml(t.connectionGroup)}</td></tr>` : '',
        t.type ? `<tr><td class="tinfo-label">סוג</td><td>${escapeHtml(t.type)}</td></tr>` : '',
        t.grade ? `<tr><td class="tinfo-label">דרגה</td><td>${escapeHtml(t.grade)}</td></tr>` : ''
      ].filter(Boolean).join('');
      const tCheck = printItemsTable(TRANSFORMER_CHECKLIST, t.checklist, `panels.${id}.transformer.checklist`);
      if(tRows || tCheck){
        let th = tRows ? `<table class="tinfo-table">${tRows}</table>` : '';
        th += tCheck;
        blocks.push({level:2, sectionKey, title: transformerTitle, html:`<h3>${transformerTitle}</h3>${th}`});
      }

      const cb = printItemsTable(CABLES_CHECKLIST, panel.cables, `panels.${id}.cables`);
      if(cb) blocks.push({level:2, sectionKey, title:'בדיקת כבלים', html:`<h3>בדיקת כבלים</h3>${cb}`});

      const dccb = printDccbTable(panel.dccb);
      if(dccb) blocks.push({level:2, sectionKey, title:'חיזוק ברגים — DCCB (ממיר)', html:`<h3>חיזוק ברגים — DCCB (ממיר)</h3>${dccb}`});

      const dps = printDpsTable(panel.dps);
      if(dps) blocks.push({level:2, sectionKey, title:'חיזוק ברגים — DPS', html:`<h3>חיזוק ברגים — DPS</h3>${dps}`});

      const houseHtml = printHouseTransformer(panel.houseTransformer);
      if(houseHtml) blocks.push({level:2, sectionKey, title:'שנאי בית — כבלים', html:`<h3>שנאי בית — כבלים</h3>${houseHtml}`});

      const auxHtml = printAuxFeed(panel.auxFeed);
      if(auxHtml) blocks.push({level:2, sectionKey, title:'הזנה ללוח AUX', html:`<h3>הזנה ללוח AUX</h3>${auxHtml}`});

      const storageHtml = printStorageContainers(panel.storageContainers);
      if(storageHtml) blocks.push({level:2, sectionKey, title:'הזנה למכולת אגירה', html:`<h3>הזנה למכולת אגירה</h3>${storageHtml}`});

      const clean = printItemsTable(INVERTER_CLEANING, panel.inverterCleaning, `panels.${id}.inverterCleaning`);
      if(clean) blocks.push({level:2, sectionKey, title:'ניקיון ממיר '+getInverterBrandLabel(), html:`<h3>ניקיון ממיר ${escapeHtml(getInverterBrandLabel())}</h3>${clean}`});

      const insT = printInsulationTable(panel.insulationTransformer);
      if(insT) blocks.push({level:2, sectionKey, title:'בדיקת בידוד — שנאי', html:`<h3>בדיקת בידוד — שנאי</h3>${insT}`});

      const insH = printInsulationTable(panel.insulationHouse);
      if(insH) blocks.push({level:2, sectionKey, title:'בדיקת בידוד — שנאי בית', html:`<h3>בדיקת בידוד — שנאי בית</h3>${insH}`});

      if(panel.notes) blocks.push({level:2, sectionKey, title:'הערות לממיר', html:`<h3>הערות לממיר</h3><p style="font-size:12px;">${escapeHtml(panel.notes)}</p>`});
      if(panel.photos && panel.photos.length){
        blocks.push({level:2, sectionKey, title:'תמונות', html:`<h3>תמונות</h3>${printPhotos(panel.photos, photoCounter)}`});
        photoCounter += panel.photos.length;
      }
    });

    // SMA, סעיף 05 — לולאה על [standaloneTransformer, ...standaloneTransformerExtra], לפי
    // סדר התצוגה במסך. כשיש רק יחידה אחת — אותה כותרת/sectionKey בדיוק כפי שהיו תמיד.
    const stUnits = [state.standaloneTransformer, ...state.standaloneTransformerExtra];
    stUnits.forEach((stUnit, stIdx) => {
      const stInfoRows = [
        ['שם השנאי', stUnit.name], ['תוצרת', stUnit.mfr], ['מס\' יצרן', stUnit.serialNo], ['שנת ייצור', stUnit.year],
        ['הספק (kVA)', stUnit.power], ['מתח ראשוני (Kv)', stUnit.voltagePrimary], ['מתח משני (Kv)', stUnit.voltageSecondary],
        ['מתח קצר (%)', stUnit.shortCircuitVoltage], ['סדר חיבורים', stUnit.connectionGroup], ['סוג', stUnit.type], ['דרגה', stUnit.grade]
      ].filter(r=>r[1]);
      const stChecklist = printItemsTable(TRANSFORMER_CHECKLIST, stUnit.checklist, `standaloneTransformer.checklist.${stIdx}`);
      const isDualLv = DUAL_LV_CONNECTION_GROUPS.includes(stUnit.connectionGroup);
      const stInsulation = isDualLv
        ? printInsulationTable(stUnit.dualCoilInsulation, null, DUAL_LV_INSULATION_ROWS)
        : printInsulationTable(stUnit.insulation);
      if(stInfoRows.length || stChecklist || stInsulation || stUnit.sectionNotes){
        let sth = '';
        if(stInfoRows.length) sth += `<table class="tinfo-table">${stInfoRows.map(r=>`<tr><td class="tinfo-label">${r[0]}</td><td>${escapeHtml(String(r[1]))}</td></tr>`).join('')}</table>`;
        if(stChecklist) sth += stChecklist;
        if(stInsulation) sth += `<h3>בדיקת בידוד</h3>${stInsulation}`;
        sth += printSectionNotesBlock(stUnit.sectionNotes);
        const stTitle = stUnits.length === 1 ? 'בדיקת שנאי' : `בדיקת שנאי — TR${stIdx+1}`;
        blocks.push({level:1, sectionKey:'standalone-transformer-'+stIdx, title:stTitle, html:`<h2>${stTitle}</h2>${sth}`});
      }
    });

    const se = printItemsTable(SAFETY_EQUIPMENT, state.safetyEquipment, 'safetyEquipment');
    if(se || state.safetyNotes){
      let seh = se;
      if(state.safetyNotes) seh += `<p style="font-size:12px;"><b>הערות:</b> ${escapeHtml(state.safetyNotes)}</p>`;
      blocks.push({level:1, sectionKey:'safety', title:'ציוד בטיחות למתח גבוה', html:`<h2>ציוד בטיחות למתח גבוה</h2>${seh}`});
    }

    const notesModel = buildReportNotesModel();
    if(notesModel.length){
      const notesHtml = notesModel.map(item => {
        let h = `<p style="font-size:12px; margin:6px 0 2px; font-weight:${item.subItems.length?700:400};">${item.number}. ${escapeHtml(item.text)}</p>`;
        if(item.subItems.length){
          h += item.subItems.map(sub => `<p style="font-size:12px; margin:2px 0 2px 18px;">${sub.number} ${escapeHtml(sub.text)}</p>`).join('');
        }
        return h;
      }).join('');
      blocks.push({level:1, sectionKey:'notes', title:'הערות', html:`<h2>הערות</h2>${notesHtml}`});
    }
  } else if(getReportType() === 'GROUNDING'){
    blocks.push(...buildGroundingReportBlocks(photoCounter));
  } else if(getReportType() === 'DC_CABLE'){
    blocks.push(...buildDcCableReportBlocks(photoCounter));
  } else if(getReportType() === 'EV_DC'){
    blocks.push(...buildEvDcReportBlocks(photoCounter));
  } else if(getReportType() === 'GENERAL'){
    blocks.push(...buildGeneralReportBlocks(photoCounter));
    blocks.push(...buildGeneralReportDetailsBlocks());
    blocks.push(...buildGeneralElectricalSuppliesBlocks());
    // buildGeneralInspectionExtrasBlocks() כבר מוזרקת בתוך buildGeneralReportBlocks (מיד
    // אחרי 5.2 של המתקן הראשון) — קריאה נפרדת כאן הייתה גורמת להדפסה כפולה בפועל. חריג:
    // אם אין אף מתקן, הלולאה בפנים לא רצה כלל, אז קוראים כאן במפורש כדי לא לאבד מידע קיים.
    if(!(state.generalElectricalInspectionReport.installations||[]).length){
      blocks.push(...buildGeneralInspectionExtrasBlocks());
    }
  } else if(getReportType() === 'MEDICAL'){
    blocks.push(...buildMedicalReportBlocks(photoCounter));
  } else if(getReportType() === 'LIGHTNING'){
    blocks.push(...buildLightningReportBlocks(photoCounter));
  } else if(getReportType() === 'TOUCH_VOLTAGE'){
    blocks.push(...buildTouchVoltageReportBlocks(photoCounter));
  } else if(getReportType() === 'FIRE_FORM3'){
    blocks.push(...buildFireForm3Blocks());
  } else if(getReportType() === 'PV_INSPECTION'){
    blocks.push(...buildPvInspectionBlocks());
  } else if(getReportType() === 'STRING_POLARITY'){
    { const spb = buildStringPolarityReportBlocks(); if(spb.length) spb[0].html = SP_FIT_STYLE_TAG() + spb[0].html; blocks.push(...spb); }
  } else if(getReportType() === 'TRANSFORMER_WINDING'){
    blocks.push(...buildTransformerWindingReportBlocks());
  } else if(getReportType() === 'HV_CABLE'){
    blocks.push(...buildHvCableReportBlocks());
  } else if(getReportType() === 'FLEXIBLE'){
    blocks.push(...buildFlexibleReportBlocks());
  } else if(getReportType() === 'MAIN_PANEL'){
    blocks.push(...buildMainPanelReportBlocks());
  } else if(getReportType() === 'TRANSFORMER_INSPECTION'){
    blocks.push(...buildTransformerInspectionReportBlocks());
  } else if(getReportType() === 'EVCS'){
    blocks.push(...buildEvcsReportBlocks());
  } else {
    blocks.push(...buildSoilReportBlocks(photoCounter));
  }

  // הצהרה קבועה להגנת הבודק — כל 5 הסעיפים מודפסים תמיד, ללא תלות ב-checkbox (הוסר) — לא
  // ניתנים לביטול. customDeclaration (הצהרה נוספת חופשית, אופציונלי) עדיין יכולה להתווסף
  // בסוף — תוספת אמיתית, לא חלק מהקבועה עצמה.
  const selectedDecls = DECLARATIONS.slice();
  if(state.customDeclaration && state.customDeclaration.trim()){
    selectedDecls.push(state.customDeclaration.trim());
  }
  // הערות בודק (לשעבר "הצהרה קבועה להגנת הבודק") — שינוי עיצוב בלבד לפי בקשה מפורשת: בלוק
  // טקסט ממוספר אחד במסגרת קומפקטית, רקע רגיל (לא ירוק) — לא כרטיסים נפרדים לכל סעיף. התוכן
  // עצמו (selectedDecls, כולל v2.410) לא נגע כלל, רק העטיפה החזותית.
  const isTwFinal = getReportType() === 'TRANSFORMER_WINDING';
  const twNotesFinal = isTwFinal && state.transformerWindingReport ? getTwNoteItems(state.transformerWindingReport).map(t=>String(t||'').trim()).filter(Boolean) : [];
  const declHtml = selectedDecls.length ? `
    <h2 style="margin:8px 0 4px;">${isTwFinal ? 'הצהרת בודק' : 'הערות בודק'}</h2>
    <div style="border:1px solid #999; border-radius:4px; padding:8px 12px;">
      ${selectedDecls.map((t,i)=>`<p style="margin:0 0 4px; font-size:11px; text-align:right; direction:rtl;">${i+1}. ${escapeHtml(t)}</p>`).join('')}
    </div>` : '';

  let electricianHtml = '';
  // *** GROUNDING: הצהרת החשמלאי הוסרה מכאן (סוף הדוח) — לפי בקשה מפורשת חדשה שמבטלת
  // את v2.440. היא מוצגת עכשיו רק בעמוד הראשון (buildCoverPage, mainPanelElectricianDeclHtml),
  // בדיוק כמו שאר סוגי הדוח (SMA/MAIN_PANEL/וכו') — אותו Reuse. electricianHtml נשאר ריק
  // לכל סוגי הדוח כעת, כדי למנוע הצגה כפולה.

  // הצהרת חשמלאי לתיקון ליקוי — אוטומטית, רק כאשר קיים ליקוי בפועל בדוח (לא toggle ידני), לפי
  // בקשה מפורשת. אותה תבנית בדיוק כמו הצהרת החשמלאי המבצע הרגילה, בלוק נפרד ומזוהה משלו.
  let defectRepairHtml = '';
  if(getReportType() === 'MAIN_PANEL' && hasMainPanelDefect()){
    const defectRepairRows = `<tr>
      <td>${escapeHtml(state.defectRepairElectricianName)||'____________________'}</td>
      <td>${escapeHtml(state.defectRepairElectricianLicenseType)||'____________________'}</td>
      <td>${escapeHtml(state.defectRepairElectricianLicenseNo)||'____________________'}</td>
      <td>${formatDateIL(state.defectRepairDate)||'____________________'}</td>
    </tr>`;
    const defectDeclText = (state.defectRepairDeclarationText && state.defectRepairDeclarationText.trim()) || DEFECT_REPAIR_DECLARATION;
    defectRepairHtml = `
      <div class="decl-box">
        <div class="decl-box-title">הצהרת חשמלאי לתיקון ליקוי</div>
        <p style="font-size:12px; padding:0 14px; margin:10px 0;">${escapeHtml(defectDeclText)}</p>
        <table class="electrician-table">
          <thead><tr><th>שם החשמלאי</th><th>סוג רישיון</th><th>מס' רישיון</th><th>תאריך</th></tr></thead>
          <tbody>${defectRepairRows}</tbody>
        </table>
        <div style="font-size:12px; padding:10px 14px 4px;">חתימת החשמלאי: ________________________</div>
      </div>`;
  }

  let approvalHtml = '';
  if(state.approvalStatus && (getReportType() !== 'SOIL' && getReportType() !== 'DC_CABLE' && getReportType() !== 'EV_DC' && getReportType() !== 'MEDICAL' && getReportType() !== 'HV_CABLE' && getReportType() !== 'FLEXIBLE')){
    const cls = getApprovalColorClass(state.approvalStatus, APPROVAL_OPTIONS);
    approvalHtml = `
      <div class="decl-box">
        <div class="decl-box-title">מסקנות</div>
        <div class="approval-banner ${cls}" style="margin:14px;">${escapeHtml(state.approvalStatus)}</div>
      </div>`;
    if(state.approvalStatus === APPROVAL_OPTIONS[1] || state.approvalStatus === APPROVAL_OPTIONS[2]){
      approvalHtml += `
      <div class="decl-box">
        <div class="decl-box-title">אישור תיקון הליקויים ע"י חשמלאי / מבצע / מפקח</div>
        <p style="font-size:12px; padding:0 14px; margin:10px 0;">
          הריני מתחייב לתקן את הליקויים האמורים לעיל ללא דיחוי ולא לחבר את המתקן לחשמל עד לביצוע התיקונים כאמור.<br>
          המזמין ידאג להחתמת החשמלאי.
        </p>
        <table class="electrician-table">
          <tbody>
            <tr><td>שם החשמלאי</td><td>____________________</td><td>סוג רישיון</td><td>____________________</td><td>מס' רישיון</td><td>____________________</td></tr>
          </tbody>
        </table>
        <div style="font-size:12px; padding:10px 14px 4px;">חתימה: ____________________ &nbsp;&nbsp; תאריך: ____________________ &nbsp;&nbsp; כתובת: ____________________</div>
      </div>`;
    }
  }

  blocks.push(...buildProtectionRelayBlocks()); // ממסרי הגנה (v2.2.505) — לפני האישור
  if((declHtml || state.settings.signature || approvalHtml || defectRepairHtml) && (getReportType() !== 'SOIL' && getReportType() !== 'DC_CABLE' && getReportType() !== 'EV_DC' && getReportType() !== 'MEDICAL' && getReportType() !== 'HV_CABLE' && getReportType() !== 'FLEXIBLE' && getReportType() !== 'PV_INSPECTION' && getReportType() !== 'FIRE_FORM3')){
    const finalTitle = twNotesFinal.length ? 'הערות' : 'אישור';
    const finalizationInner = `
      <h2>${finalTitle}</h2>
      ${twNotesFinal.map((t,i)=>`<p style="font-size:12.5px; margin:4px 0; padding-right:22px; text-indent:-22px; white-space:pre-line;"><b>${i+1}.</b> ${escapeHtml(t)}</p>`).join('')}
      ${approvalHtml}
      ${declHtml}
      ${state.settings.signature
        ? `<div class="cover-sig-img-wrap" style="margin-top:26px;"><img class="cover-sig-img" src="${state.settings.signature}" alt="חתימה וחותמת"></div>`
        : `<div style="margin-top:26px; font-size:12px;">חתימה וחותמת: ________________________</div>`}
      ${electricianHtml}
      ${defectRepairHtml}
    `;
    // *** GROUNDING בלבד — באג אמיתי שנמצא ב-PDF בפועל (לא רק ב-blocks.push הלוגי):
    // ה-decl-box-ים הנפרדים (מסקנות/הערות בודק/הצהרת חשמלאי) כל אחד עם break-inside:avoid
    // משלו, אבל שום דבר לא מנע מהדפדפן להכניס page-break *בין* אחד למשנהו אם המדידה
    // ב-JS (estimatePageNumbers) הייתה אופטימית מעט מדי ביחס לרינדור האמיתי. התיקון:
    // wrapper פיזי אמיתי ב-HTML (לא רק לוגי) עם break-inside:avoid על *כל הקבוצה יחד* —
    // מונע מהדפדפן לפצל בין הרכיבים הפנימיים גם אם המדידה לא מדויקת ב-100%. שאר סוגי
    // הדוח (MAIN_PANEL/EVCS/וכו') לא שונו כלל — עדיין ללא wrapper, בדיוק כפי שהיו.
    const html = getReportType() === 'GROUNDING'
      ? `<div class="grounding-finalization-group">${finalizationInner}</div>`
      : (isTwFinal ? `<div style="break-inside:avoid; page-break-inside:avoid;">${finalizationInner}</div>` : finalizationInner);
    blocks.push({level:1, sectionKey:'approval', title:finalTitle, html, pageBreak: isTwFinal ? true : undefined});
  }

  // באג קריטי שתוקן (Audit אישר במפורש): filter(p=>p.dataUrl) החריג בטעות תמונות שכבר
  // הועלו לענן — ברגע שלתמונה יש cloudPath, ה-dataUrl (base64 מלא) מנוקה בכוונה כדי לחסוך
  // מקום ב-localStorage (ר' migrateCloudPhotoDataUrls, שורה ~10214) — כך שתמונה תקינה
  // ומוצגת בפועל בעורך (resolvePhotoSrc בודק cloudPath קודם, נופל ל-dataUrl רק אם אין) הייתה
  // מוחרגת לגמרי מה-PDF. זה בדיוק הגורם ל"רק חלק מהתמונות מגיעות" שדווח — ככל שיותר תמונות
  // מסונכרנות לענן (dataUrl מתנקה מהן אחת אחת), יותר תמונות נעלמות מה-PDF בהדרגה. התיקון
  // תואם בדיוק לדפוס הנכון שכבר קיים בקוד עצמו במקומות אחרים (p.dataUrl || p.cloudPath —
  // ראו שורות 11120/26273/27375/27808) — לא נוצר מנגנון חדש, רק תוקן ליישור עם הדפוס הקיים.
  const relevantPhotos = (state.generalPhotos||[]).filter(p=>p.dataUrl || p.cloudPath);
  if(relevantPhotos.length){
    // מחלקים לקבוצות של עד 4 תמונות — כל קבוצה הופכת לבלוק נפרד עם מעבר עמוד, כדי שלא יותר מ-4 תמונות יופיעו באותו עמוד
    const PHOTOS_PER_PAGE = 4;
    const chunks = [];
    for(let i = 0; i < relevantPhotos.length; i += PHOTOS_PER_PAGE){
      chunks.push(relevantPhotos.slice(i, i + PHOTOS_PER_PAGE));
    }
    const notesHtml = (p, photoNum, fontSize) => {
      // עמיד בפני תמונות ישנות שעדיין לא עברו מיגרציה מ-caption ל-notes (אם ההדפסה קורית לפני שכרטיס התמונות נפתח בטופס באותו סשן)
      const allNotes = (p.notes && p.notes.length) ? p.notes : (p.caption ? [p.caption] : []);
      return allNotes.filter(n=>n && n.trim())
        .map((note,ni)=>`<p style="font-size:${fontSize}px; margin:${ni===0?4:3}px 0 0;"><b>${photoNum}.${ni+1}</b> ${escapeHtml(note)}</p>`).join('');
    };
    chunks.forEach((chunk, chunkIdx) => {
      const startNum = chunkIdx * PHOTOS_PER_PAGE + 1;
      let photoBlocksHtml;
      if(chunk.length === 1){
        // תמונה בודדת בקבוצה - מסגרת שלמה עם התמונה למעלה וההערות בתוך אותה מסגרת מתחת
        const p = chunk[0];
        photoBlocksHtml = `
        <div style="border:3px solid #d4a63c; border-radius:8px; overflow:hidden; margin-bottom:14px; break-inside:avoid;">
          <div style="background:#f2f2f2; padding:5px 10px; font-size:12px; font-weight:700; color:#8a6d1e;">תמונה ${startNum}${p.title ? ` — ${escapeHtml(p.title)}` : ''}</div>
          <img src="${resolvePhotoSrc(p)}" data-cloudpath="${escapeAttr(p.cloudPath||'')}" style="width:100%; max-height:550px; object-fit:contain; display:block;">
          ${notesHtml(p, startNum, 11.5) ? `<div style="background:#f8f8f8; padding:8px 10px; border-top:1px solid #e0e0e0;">${notesHtml(p, startNum, 11.5)}</div>` : ''}
        </div>`;
      } else {
        // כמה תמונות בקבוצה - רשת דו-טורית, כל תמונה עם מסגרת משלה וההערות בתוך אותה מסגרת
        photoBlocksHtml = `<div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">
          ${chunk.map((p,i)=>`
            <div style="border:2.5px solid #d4a63c; border-radius:8px; overflow:hidden; break-inside:avoid;">
              <div style="background:#f2f2f2; padding:4px 8px; font-size:11px; font-weight:700; color:#8a6d1e;">תמונה ${startNum+i}${p.title ? ` — ${escapeHtml(p.title)}` : ''}</div>
              <img src="${resolvePhotoSrc(p)}" data-cloudpath="${escapeAttr(p.cloudPath||'')}" style="width:100%; max-height:250px; object-fit:contain; display:block;">
              ${notesHtml(p, startNum+i, 11) ? `<div style="background:#f8f8f8; padding:6px 8px; border-top:1px solid #e0e0e0;">${notesHtml(p, startNum+i, 11)}</div>` : ''}
            </div>`).join('')}
        </div>`;
      }
      blocks.push({
        level:1, sectionKey: chunkIdx===0 ? 'general-photos' : `general-photos-${chunkIdx}`,
        title: chunkIdx===0 ? 'תיעוד תמונות' : `תיעוד תמונות (המשך)`,
        html: `<h2>📷 ${chunkIdx===0 ? 'תיעוד תמונות' : 'תיעוד תמונות (המשך)'}</h2>${photoBlocksHtml}`,
        // תוקן: לפי בקשה מפורשת, פרק התמונות תמיד מתחיל בעמוד חדש — גם הקבוצה הראשונה
        // (chunkIdx===0), לא רק הקבוצות שאחריה. זו הייתה בדיוק התקלה שדווחה: הקבוצה
        // הראשונה לא קיבלה pageBreak:true, כך שיכלה להתחיל בכל שטח שנשאר מהסעיף הקודם
        // (גם שטח קטן מדי לשורת תמונות שלמה), מה שיצר את הפריסה הבלתי-מקצועית. מוגן
        // אוטומטית מפני עמוד ריק כשאין תמונות בדוח — כל הבלוק הזה כבר רץ רק בתוך
        // if(relevantPhotos.length){...} שמעל, כך שאם אין תמונות בכלל, ה-forEach הזה
        // (וממילא כל push) לעולם לא מתבצע.
        pageBreak: true
      });
    });
  }

  // === שכבת הגנה מרכזית — לא נקודתית לדוח מסוים, אלא ברמת מנוע הדוחות עצמו ===
  // לפי בקשה מפורשת: "אני לא רוצה להסתמך על כך שכל אחד מ-15 סוגי הדוח בנוי כיום נכון
  // בנפרד... מנגנון משותף וגורף ברמת מנוע הדוחות". buildReportBlocks() היא הנקודה
  // המשותפת היחידה שדרכה *כל* סוגי הדוח עוברים (return blocks בסוף הפונקציה) לפני
  // Preview/Print/PDF — כל אחד מ-15 הדוחות בונה את מערך blocks באמצעות אותה בקשת
  // push(), ואז חוזר מכאן. סינון כאן, פעם אחת, חל אוטומטית על כולם — כולל דוחות עתידיים
  // שיתווספו, בלי לגעת בקוד הפרטני של אף דוח קיים.
  // סיכום AI (v2.2.543) — לפני החתימה/האישור של הדוח, או בסוף אם אין כזה
  { const sb = buildAiSummaryBlock(); if(sb){ const END_KEYS = ['approval','soil-signature','dc-signatures','flex-signature']; const at = blocks.findIndex(b => END_KEYS.includes(b.sectionKey)); if(at >= 0) blocks.splice(at, 0, sb); else blocks.push(sb); } }
  return blocks.filter(b => hasMeaningfulContent(b.html));
}

// בודקת האם ל-HTML של בלוק דוח יש תוכן משמעותי מעבר לכותרת הסעיף עצמה — משמשת כשכבת
// הגנה מרכזית וגורפת לפני Preview/Print/PDF (ראו buildReportBlocks לעיל). "משמעותי" לפי
// בקשה מפורשת: לא null/undefined/מחרוזת ריקה/רווחים בלבד/כותרות עמודות ריקות. תמונה
// (<img>) נחשבת תוכן משמעותי גם בלי טקסט. לא תלויה במבנה נתונים של סוג דוח ספציפי —
// בודקת את ה-HTML הסופי שכבר נבנה, ולכן עובדת זהה על כל 15 סוגי הדוח וגם על דוחות
// עתידיים בלי צורך בהתאמה נפרדת.
function hasMeaningfulContent(html){
  if(!html || typeof html !== 'string') return false;
  // תמונה נחשבת תוכן משמעותי כשלעצמה, גם בלי טקסט נלווה — נבדק לפני הסרת תגיות.
  if(/<img[\s>]/i.test(html)) return true;
  let stripped = html
    // מסיר את כותרת הסעיף עצמה (h2/h3 הראשונה) — היא לא "תוכן", היא רק שם הסעיף; אחרת
    // סעיף עם כותרת בלבד וכלום מתחתיה תמיד ייחשב "יש לו תוכן" בטעות.
    .replace(/^\s*<h[234][^>]*>[\s\S]*?<\/h[234]>/i, '')
    // מסיר שורות כותרות טבלה (thead) — אלה שמות עמודות קבועים ("תיאור", "תוצאה"...),
    // לא נתונים שהמשתמש הזין; אחרת טבלה עם thead אך tbody ריק תיחשב "יש לה תוכן" בטעות.
    .replace(/<thead[\s\S]*?<\/thead>/gi, '');
  // מסיר את כל שאר תגיות ה-HTML, משאיר רק טקסט גולמי לבדיקה.
  const text = stripped.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').trim();
  return text.length > 0;
}

function getReportSections(){
  const blocks = buildCombinedReportBlocks();
  const seen = new Set();
  const out = [];
  blocks.forEach(b=>{
    if(b.level===1 && !seen.has(b.sectionKey)){
      seen.add(b.sectionKey);
      out.push({key:b.sectionKey, label:b.title});
    }
  });
  return out;
}

// מריץ callback() כשה-state החי מייצג זמנית את הפרק המבוקש (-1=ראשי), ואז משחזר בדיוק את מה
// שהיה פעיל לפני הקריאה — משמש להדפסה בלבד, לא נוגע ב-activeChapterIndex/openSections שנחשבים
// חלק ממצב העריכה החי, לא רק מהתוכן. זה מה שמאפשר לבנות בלוקי PDF לכל פרק בלי לשנות בפועל
// את מסך העריכה שהמשתמש רואה.
function withChapterActive(index, callback){
  const originalIndex = state.activeChapterIndex;
  const originalSnapshot = snapshotChapterScopedState();
  const targetSnapshot = index === -1 ? (originalIndex === -1 ? originalSnapshot : state.primaryChapterBackup) : (state.reportChapters[index] && state.reportChapters[index].snapshot);
  if(targetSnapshot && index !== originalIndex) applyChapterScopedSnapshot(targetSnapshot);
  const result = callback();
  if(index !== originalIndex) applyChapterScopedSnapshot(originalSnapshot);
  return result;
}

// מרכיב בלוקי הדפסה מכל הפרקים לרצף אחד: הראשי קודם, ואז כל פרק נוסף לפי הסדר, כל אחד עם
// כותרת-מפריד ברורה ותחת מספור המשך רציף. אישור/הצהרה/חתימה (sectionKey='approval') מוצג
// פעם אחת בלבד בסוף המסמך המאוחד — לא פעם לכל פרק — לפי הגדרות הפרק הראשי, כדי שלא ייראה
// כאילו נדרשות כמה חתימות נפרדות לאותה בדיקה אחת. כשאין פרקים נוספים בכלל (המקרה הנפוץ),
// זו בדיוק buildReportBlocks() הרגילה בלי שינוי — אפס סיכון למי שלא משתמש בפיצ'ר.
function buildCombinedReportBlocks(){
  if(!state.reportChapters || state.reportChapters.length === 0){
    return buildReportBlocks();
  }
  const allBlocks = [];
  let finalApprovalBlock = null;

  const collectChapter = (index, chapterTitle, info) => {
    const chapterBlocks = withChapterActive(index, () => buildReportBlocks());
    // תיאור העבודה של הפרק (שדה פר-פרק) — מודפס מתחת לכותרת הפרק. של הדוח הראשון כבר מופיע בעמוד השער (v2.2.500)
    const chapterDesc = index === -1 ? '' : withChapterActive(index, () => String(state.meta.description || '').trim());
    if(chapterTitle){
      // כותרת גדולה לכל טופס/דוח ב-PDF (v2.2.504) — כדי להבדיל בבירור בין הבדיקות
      allBlocks.push({level:1, sectionKey:'chapter-divider-'+index, title:chapterTitle, html:
        `<h2 class="chapter-banner" style="margin:0 0 14px; padding:16px 20px; text-align:center; border:0; border-radius:10px; background:${state.settings.reportHeaderColor || '#0F2E4D'}; color:#fff; -webkit-print-color-adjust:exact; print-color-adjust:exact; line-height:1.25;">
          <span style="display:block; font-size:12.5px; font-weight:600; opacity:.9;">פרק ${info ? info.pos : ''}${info ? ' מתוך ' + info.total : ''}</span>
          <span style="display:block; font-size:24px; font-weight:800; margin-top:2px;">${escapeHtml(info ? info.label : chapterTitle)}</span>
        </h2>${chapterDesc ? `<p style="font-size:12.5px; margin:0 0 10px; padding:8px 12px; border:1px solid #d5dfea; border-radius:8px; background:#f7fafd;"><b>תיאור העבודה:</b> ${escapeHtml(chapterDesc)}</p>` : ''}`,
        pageBreak:true});
    }
    // תחילית ייחודית לפי אינדקס הפרק — בלי זה, שני פרקים מאותו סוג דוח (למשל שני MAIN_PANEL,
    // "לוח מתח נמוך" + "לוח מתח גבוה") מייצרים sectionKey זהה לכל אחד (למשל שניהם
    // 'mp-facility-0', כי כל פרק סופר מתקנים מ-0 בתוך ה-snapshot הנפרד שלו). זה שבר את סרגל
    // בחירת הסעיפים בתצוגה המקדימה (getReportSections דידפלקט אותם לערך אחד בטעות) ואת
    // סינון הסעיפים בפועל (החרגת סעיף אחד הייתה מחריגה את שניהם, כי הם חולקים אותו מפתח).
    const keyPrefix = 'ch' + index + '-';
    chapterBlocks.forEach(b => {
      if(b.sectionKey === 'approval'){ if(index === -1) finalApprovalBlock = b; return; } // רק הראשי, ורק בסוף
      // "לכבוד / א.נ," היא ברכת פתיחה גנרית (לא תלוית-תוכן כמו description) — מוצגת פעם אחת
      // בלבד, בתחילת הפרק הראשון, לא חוזרת על עצמה זהה בכל פרק נוסף.
      if(b.sectionKey === 'letter' && index !== -1) return;
      allBlocks.push({ ...b, sectionKey: keyPrefix + b.sectionKey });
    });
  };

  const primaryLabel = getTypeDisplayLabel(state.activeChapterIndex === -1 ? state.settings.formTypeName : (state.primaryChapterBackup ? state.primaryChapterBackup.formTypeName : 'הדוח הראשי'));
  const order = getChapterPrintOrder();
  order.forEach((id, pos) => {
    const idx = id === 'primary' ? -1 : state.reportChapters.findIndex(c=>c.id===id);
    if(idx === -1 && id !== 'primary') return;
    let label = id === 'primary' ? primaryLabel : state.reportChapters[idx].label;
    // קוטביות סטרינגים (v2.2.546): כותרת הפרק לפי סוג הבדיקה שנבחר (DCCB / גידי AC / מכולות אגירה), לא תמיד "לוחות DCCB"
    try{ const spT = withChapterActive(idx, () => getReportType() === 'STRING_POLARITY' ? getStringPolarityCoverTitle().replace(/^דו"ח\s*/, '') : ''); if(spT) label = spT; }catch(e){}
    collectChapter(idx, `פרק ${pos+1}: ${label}`, { pos: pos+1, total: order.length, label });
  });

  if(finalApprovalBlock) allBlocks.push(finalApprovalBlock);
  return allBlocks;
}

function buildPrintReport(excludeKeys){
  excludeKeys = excludeKeys || new Set();
  const blocks = buildCombinedReportBlocks().filter(b => !excludeKeys.has(b.sectionKey));
  // רישיון בודק — תמיד העמוד האחרון בדוח (גם בדוח משולב). בטופס 3 של כבאות — תמיד; אחרת לפי ההגדרה
  { const lic = (typeof isFireForm3Report === 'function' && isFireForm3Report()) ? null : buildInspectorLicenseBlock(false); if(lic && !excludeKeys.has(lic.sectionKey)) blocks.push(lic); }

  // Preflight לטבלאות — רץ *לפני* estimatePageNumbers, כי הוא מכניס סימוני page-break
  // (p-page-break) בתוך block.html עצמו כשטבלה לא נכנסת בעמוד הנוכחי. יומן ההחלטות (לכל
  // טבלה: tableHeight/remainingPageHeight/compactedHeight/decision) נשמר גלובלית לדיווח —
  // לפי בקשה מפורשת, "כדי שאפשר יהיה להוכיח שההחלטה לא נעשתה ידנית".
  window.lastTablePreflightLog = applyTablePreflight(blocks);

  const pages = estimatePageNumbers(blocks);
  const totalPages = pages.length ? pages[pages.length-1] : 2;

  // Group blocks by their estimated page number so each physical printed page
  // gets its own explicit page-break and a reliable "עמוד X מתוך Y" label
  // (rather than depending on browser/PDF-engine page-counter support).
  const grouped = [];
  blocks.forEach((b,i)=>{
    const pn = pages[i];
    let group = grouped.find(g=>g.pn===pn);
    if(!group){ group = {pn, html:'', sectionKeys:[]}; grouped.push(group); }
    group.html += b.html;
    group.sectionKeys.push(b.sectionKey);
  });

  const smallHeader = buildPageHeaderHtml();

  // כשמאוחדים פרקים, מדלגים על טיפול הרוחב המיוחד — הוא בנוי בהנחת מבנה בלוקים של דוח יחיד,
  // ולא תומך בתערובת סוגי דוח בתוך אותו מסמך. פשוט מדפיסים הכל לאורך, כמו כל דוח רגיל.
  const hasChapters = state.reportChapters && state.reportChapters.length > 0;
  // בלוק טבלה אחד שמודפס בעמוד לרוחב, ושאר הדוח לאורך: טבלת הסיכום בדוח כבל מתח גבוה, וטבלת גידי
  // ההזנה ממכולות אגירה בדוח קוטביות סטרינגים (v2.2.475) — אותו מנגנון בדיוק.
  const midLandscapeKey = hasChapters ? null
    : (getReportType() === 'HV_CABLE' ? 'hc-summary' : (isStringPolarityStorageMode() ? 'sp-stor-table' : (isStringPolarityAcMode() ? 'sp-ac-table' : null)));
  const isHvCable = !!midLandscapeKey;
  const hvSummaryBlockIdx = isHvCable ? blocks.findIndex(b => b.sectionKey === midLandscapeKey) : -1;

  if(isHvCable && hvSummaryBlockIdx > -1){
    // רק בלוק טבלת הסיכום (שהוא רחב — הרבה עמודות מדידה) עובר לרוחב; שאר הדוח נשאר לאורך.
    // עובדים ישירות על ה-blocks המקוריים (לא grouped) כדי להבטיח בידוד מדויק של בלוק הטבלה —
    // אבל לפני/אחרי הטבלה, מיישמים הערכת-עמודים אמיתית (כמו בכל דוח אחר) כדי שסעיפים קצרים
    // יידחסו יחד לאותו עמוד בפועל, במקום עמוד נפרד ריק-למחצה לכל סעיף.
    const beforeBlocks = blocks.slice(0, hvSummaryBlockIdx);
    const summaryBlock = blocks[hvSummaryBlockIdx];
    const afterBlocks = blocks.slice(hvSummaryBlockIdx + 1);

    const groupByEstimatedPage = (blockList) => {
      if(!blockList.length) return '';
      const pns = estimatePageNumbers(blockList);
      const zoneGroups = [];
      blockList.forEach((b,i)=>{
        const pn = pns[i];
        let g = zoneGroups.find(g=>g.pn===pn);
        if(!g){ g = {pn, html:''}; zoneGroups.push(g); }
        g.html += b.html;
      });
      return zoneGroups.map(g => `<div class="p-page-break"></div>${smallHeader}${g.html}`).join('');
    };

    const beforeContent = groupByEstimatedPage(beforeBlocks);
    const afterContent = groupByEstimatedPage(afterBlocks);

    let html = `<div class="page-portrait-zone">`;
    html += buildCoverPage(totalPages);
    // תוכן עניינים אופציונלי לכל סוגי הדוח (כולל HV Cable) — מוצג רק אם המשתמש בחר בכך.
    // חשוב: שורת ה-page-break+header שקדמה לתוכן העניינים זזה לתוך אותה הגבלה, כי beforeContent
    // כבר מתחיל ב-page-break משלו לקבוצה הראשונה — אותו תיקון שנמצא ותוקן ב-v2.149 לדוח הכללי.
    if(state.settings.includeTableOfContents){
      html += `<div class="p-page-break"></div>${smallHeader}`;
      html += buildTocTable(blocks, pages, totalPages);
    }
    html += beforeContent;
    html += `</div>`;
    html += `<div class="page-landscape-zone">${smallHeader}${summaryBlock.html}</div>`;
    if(afterContent) html += `<div class="page-portrait-zone">${afterContent}</div>`;
    return html;
  }

  const isDcCable = !hasChapters && getReportType() === 'DC_CABLE';
  const landscapeStartIdx = isDcCable ? grouped.findIndex(g => g.sectionKeys.some(k => k.indexOf('dc-') === 0 && k !== 'dc-intro')) : -1;

  if(isDcCable && landscapeStartIdx > -1){
    const portraitGroups = grouped.slice(0, landscapeStartIdx);
    const landscapeGroups = grouped.slice(landscapeStartIdx);

    const portraitContent = portraitGroups.map(g =>
      `<div class="p-page-break"></div>${smallHeader}${g.html}`
    ).join('');
    const landscapeContent = landscapeGroups.map((g,i) =>
      i === 0 ? `${smallHeader}${g.html}` : `<div class="p-page-break"></div>${smallHeader}${g.html}`
    ).join('');

    let html = `<div class="page-portrait-zone">`;
    html += buildCoverPage(totalPages);
    // תוכן עניינים אופציונלי לכל סוגי הדוח (כולל DC Cable) — מוצג רק אם המשתמש בחר בכך.
    if(state.settings.includeTableOfContents){
      html += `<div class="p-page-break"></div>${smallHeader}`;
      html += buildTocTable(blocks, pages, totalPages);
    }
    html += portraitContent;
    html += `</div>`;
    html += `<div class="page-landscape-zone">${landscapeContent}</div>`;
    return html;
  }

  const contentHtml = grouped.map(g =>
    `<div class="p-page-break"></div>${smallHeader}${g.html}`
  ).join('');

  let html = buildCoverPage(totalPages);
  // תוכן עניינים אופציונלי לכל סוגי הדוח בנתיב הזה (SMA/SOIL/GROUNDING/EV_DC/GENERAL/MEDICAL/
  // LIGHTNING/TOUCH_VOLTAGE/TRANSFORMER_WINDING) — מוצג רק אם המשתמש בחר בכך, לא לפי סוג הדוח.
  // חשוב: שורת ה-page-break+header שקדמה לתוכן העניינים בתוך אותה הגבלה, כי contentHtml כבר
  // מתחיל ב-page-break משלו לקבוצה הראשונה (אותו תיקון עמוד-ריק שנמצא ותוקן ב-v2.149).
  if(state.settings.includeTableOfContents){
    html += `<div class="p-page-break"></div>${smallHeader}`;
    html += buildTocTable(blocks, pages, totalPages);
  }
  html += contentHtml;

  return html;
}
let toastTimer=null;
function showToast(msg, durationMs){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>t.classList.remove('show'), durationMs || 2200);
}

/* ---------- Init ---------- */
document.getElementById('versionBadge').textContent = 'v' + APP_VERSION;
document.getElementById('versionBadge').addEventListener('click', ()=>{
  const latest = CHANGELOG[0];
  showToast(`גרסה ${latest.version} (${latest.date}) — לפרטים מלאים: הגדרות חברה`);
});
const appUpdateOkBtn = document.getElementById('appUpdateOk');
if(appUpdateOkBtn) appUpdateOkBtn.addEventListener('click', async ()=>{
  if(appUpdateOkBtn.getAttribute('data-mode') === 'whats-new'){
    // מצב "מה חדש" — אין מה לרענן אליו, רק שומרים שהמשתמש ראה את הגרסה הזו כדי שלא יוצג שוב
    try{ await storageAPI.set('last-seen-app-version', APP_VERSION, false); }catch(e){ /* לא קריטי */ }
    pendingWhatsNew = null;
    hideAppUpdateModal();
  } else {
    applyAppUpdate();
  }
});
const appUpdateLaterBtn = document.getElementById('appUpdateLater');
if(appUpdateLaterBtn) appUpdateLaterBtn.addEventListener('click', ()=>{ hideAppUpdateModal(); });
const calibrationWarningOkBtn = document.getElementById('calibrationWarningOk');
if(calibrationWarningOkBtn) calibrationWarningOkBtn.addEventListener('click', ()=>{
  document.getElementById('calibrationWarningModal').classList.remove('show');
});
loadState();
startAppUpdatePolling();
// item שהמשתמש ביקש: מסך "מה חדש" בעליית האפליקציה — נבדק בנפרד מהזיהוי החי (version.json),
// כי בטלפון כל פתיחה היא לרוב טעינה טרייה שכבר מגיעה עם הקוד העדכני, כך שאין "עדכון חי" לזהות
// בכלל. ממתינים רגע קצר כדי לתת לבדיקת ה-version.json (startAppUpdatePolling) הזדמנות לרוץ
// קודם ולמנוע התנגשות בין שני החלונות באותו DOM element, אם שניהם היו מזהים משהו בו-זמנית.
setTimeout(()=>{ if(!pendingAppUpdate) checkForUnseenVersionOnStartup(); }, 1500);

// Auto-save a draft snapshot periodically (interval configurable in Settings), so work
// isn't lost even without pressing "save" manually. Reuses the same slot for the same
// ongoing inspection (matched by site name + report number + address) instead of using
// up new slots. Polls every minute and compares against the configured interval, so
// changing the setting takes effect without needing to restart any timer.
let lastAutoSaveAt = Date.now();
setInterval(()=>{
  const intervalMs = (state.settings.autoSaveMinutes || 5) * 60 * 1000;
  if(Date.now() - lastAutoSaveAt < intervalMs) return;
  lastAutoSaveAt = Date.now();
  if(state.meta.siteName || state.meta.address || state.meta.reportNumber){
    saveDraft(true);
  }
}, 60 * 1000);

// כפתור פעולות מהירות צף (שמור / גלול למעלה / גלול למטה)
(function initFab(){
  const fabMainBtn = document.getElementById('fabMainBtn');
  const fabMenu = document.getElementById('fabMenu');
  const fabContainer = document.getElementById('fabContainer');
  const fabSave = document.getElementById('fabSave');
  const fabCollapseAll = document.getElementById('fabCollapseAll');
  const fabScrollUp = document.getElementById('fabScrollUp');
  const fabScrollDown = document.getElementById('fabScrollDown');
  if(!fabMainBtn) return;

  let fabOpen = false;
  function setFabOpen(open){
    fabOpen = open;
    fabMenu.style.display = open ? 'flex' : 'none';
    fabMainBtn.style.transform = open ? 'rotate(45deg)' : 'rotate(0deg)';
  }

  fabMainBtn.addEventListener('click', (e)=>{
    e.stopPropagation();
    setFabOpen(!fabOpen);
  });

  fabSave.addEventListener('click', async (e)=>{
    e.stopPropagation();
    setFabOpen(false);
    try{
      await storageAPI.set('inspection-current', JSON.stringify(sanitizeStateForLocalSave(state)), false);
      if(navigator.onLine === false){ setSavePill('ללא רשת – שומר מקומית', false, true); }
      else{ setSavePill('נשמר', true); }
      showToast('נשמר בהצלחה');
    }catch(err){
      setSavePill('שגיאת שמירה', false);
      showToast('שגיאה בשמירה');
    }
  });

  fabCollapseAll.addEventListener('click', (e)=>{
    e.stopPropagation();
    setFabOpen(false);
    openSections.clear(); alreadySeededOpenCards.clear();
    render();
    showToast('כל הסעיפים צומצמו');
  });

  fabScrollUp.addEventListener('click', (e)=>{
    e.stopPropagation();
    setFabOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  fabScrollDown.addEventListener('click', (e)=>{
    e.stopPropagation();
    setFabOpen(false);
    window.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'smooth' });
  });

  document.addEventListener('click', (e)=>{
    if(fabOpen && !fabContainer.contains(e.target)) setFabOpen(false);
  });
})();

// אתחול חד-פעמי של ה-input הנסתר המשותף לתמונות פר-פריט בדיקה (לא חלק מה-DOM שמתחדש בכל render, לכן מאותחל פעם אחת בלבד כאן ולא בתוך attachHandlers)
let pendingItemPhotoKey = null;
(function initItemPhotoInput(){
  const itemPhotoChangeHandler = async (inputEl)=>{
    const file = inputEl.files[0];
    inputEl.value = ''; // allow re-selecting the same file again later
    if(!file || !pendingItemPhotoKey) return;
    const keyForThisUpload = pendingItemPhotoKey; // מעתיקים לפני שמאפסים, כי ה-upload לענן ממשיך async אחרי שהמשתנה הגלובלי מתאפס
    try{
      const dataUrl = await compressImage(file, 1200, 0.75);
      const entry = { id: makePanelId(), dataUrl, cloudPath: '', fileName: file.name || '', mimeType: file.type || 'image/jpeg' };
      if(!state.itemPhotos[keyForThisUpload]) state.itemPhotos[keyForThisUpload] = [];
      state.itemPhotos[keyForThisUpload].push(entry);
      scheduleSave(); render();
      // העלאה לענן היא תוספת, לא תחליף — dataUrl נשאר כגיבוי/cache מקומי תמיד.
      if(supabaseClient && isCloudIdentityLocked()){ // Phase 2B
        cloudDebugLog('מעלה תמונת פריט לענן', entry.fileName);
        uploadFileToCloudStorage(state.settings.cloudReportId, dataUrl, file.name).then(result=>{
          if(result){ entry.cloudPath = result.path; scheduleSave(); render(); }
        });
      } else if(supabaseClient){
        entry.pendingUpload = true; // section 33 — ראה processPendingPhotoUploads
      }
    }catch(e){
      showToast('שגיאה בטעינת התמונה');
    }
    pendingItemPhotoKey = null;
  };
  const input = document.getElementById('itemPhotoHiddenInput');
  if(input) input.addEventListener('change', ()=> itemPhotoChangeHandler(input));
  const inputGallery = document.getElementById('itemPhotoHiddenInputGallery');
  if(inputGallery) inputGallery.addEventListener('change', ()=> itemPhotoChangeHandler(inputGallery));
})();

// ============ נגישות (Accessibility) — מודול עצמאי, לא נוגע בשום render/state של הדוח ============
// לפי דרישה מפורשת (#10): העדפות נגישות הן העדפת משתמש, לא חלק מנתוני הדוח — נשמרות דרך
// storageAPI הקיים (Reuse, כמו has-logged-in-before/last-seen-app-version) במפתח נפרד
// לגמרי 'accessibility-prefs', shared=false (per-device/per-user, לא מסונכרן לענן כחלק
// מהדוח). לא נוגע ב-scheduleSave/state.* בשום שלב.
(function(){
  const A11Y_KEY = 'accessibility-prefs';
  const TOGGLE_ACTIONS = ['contrast','underline','spacing','readable-font','reduce-motion']; // בוליאני, class = a11y-<action>
  const CLASS_MAP = { contrast:'a11y-high-contrast', underline:'a11y-underline-links', spacing:'a11y-spacing', 'readable-font':'a11y-readable-font', 'reduce-motion':'a11y-reduce-motion' };
  let prefs = { fontLevel: 0, contrast:false, underline:false, spacing:false, 'readable-font':false, 'reduce-motion':false }; // fontLevel: 0=רגיל, 1=lg, 2=xl

  function applyPrefs(){
    const html = document.documentElement;
    html.classList.toggle('a11y-font-lg', prefs.fontLevel === 1);
    html.classList.toggle('a11y-font-xl', prefs.fontLevel === 2);
    TOGGLE_ACTIONS.forEach(a => html.classList.toggle(CLASS_MAP[a], !!prefs[a]));
    // מסנכרן את מצב aria-pressed על כפתורי התפריט, כדי שקורא-מסך ידווח נכון על המצב הנוכחי
    document.querySelectorAll('#a11yMenu [data-a11y-action]').forEach(btn=>{
      const action = btn.getAttribute('data-a11y-action');
      if(action === 'font-inc') btn.setAttribute('aria-pressed', String(prefs.fontLevel === 2));
      else if(action === 'font-dec') btn.setAttribute('aria-pressed', String(prefs.fontLevel === 0));
      else if(TOGGLE_ACTIONS.includes(action)) btn.setAttribute('aria-pressed', String(!!prefs[action]));
    });
  }

  async function savePrefs(){
    try{ await storageAPI.set(A11Y_KEY, JSON.stringify(prefs), false); }catch(e){ /* לא קריטי — נגישות ממשיכה לעבוד גם אם השמירה נכשלה */ }
  }

  async function loadPrefs(){
    try{
      const stored = await storageAPI.get(A11Y_KEY, false);
      if(stored && stored.value){
        const parsed = JSON.parse(stored.value);
        prefs = Object.assign(prefs, parsed);
      }
    }catch(e){ /* אין העדפות שמורות עדיין — נשאר עם ברירת המחדל */ }
    applyPrefs();
  }

  const a11yMenu = document.getElementById('a11yMenu');
  const a11yToggleBtn = document.getElementById('a11yToggleBtn');
  let a11yMenuOpenerEl = null;

  function setA11yMenuOpen(open, opener){
    a11yMenu.classList.toggle('show', open);
    a11yToggleBtn.setAttribute('aria-expanded', String(open));
    if(open){ a11yMenuOpenerEl = opener || a11yToggleBtn; }
    else if(a11yMenuOpenerEl){ a11yMenuOpenerEl.focus(); a11yMenuOpenerEl = null; }
  }

  a11yToggleBtn.addEventListener('click', ()=> setA11yMenuOpen(!a11yMenu.classList.contains('show'), a11yToggleBtn));
  const a11yFooterLinkBtn = document.getElementById('a11yFooterLinkBtn');
  if(a11yFooterLinkBtn) a11yFooterLinkBtn.addEventListener('click', ()=> setA11yMenuOpen(!a11yMenu.classList.contains('show'), a11yFooterLinkBtn));
  document.addEventListener('click', (e)=>{
    if(a11yMenu.classList.contains('show') && !a11yMenu.contains(e.target) && e.target !== a11yToggleBtn && e.target !== a11yFooterLinkBtn){
      setA11yMenuOpen(false);
    }
  });

  document.querySelectorAll('#a11yMenu [data-a11y-action]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const action = btn.getAttribute('data-a11y-action');
      if(action === 'font-inc') prefs.fontLevel = Math.min(2, prefs.fontLevel + 1);
      else if(action === 'font-dec') prefs.fontLevel = Math.max(0, prefs.fontLevel - 1);
      else if(action === 'reset'){
        prefs = { fontLevel:0, contrast:false, underline:false, spacing:false, 'readable-font':false, 'reduce-motion':false };
      } else if(TOGGLE_ACTIONS.includes(action)){
        prefs[action] = !prefs[action];
      }
      applyPrefs();
      savePrefs();
    });
  });

  // Modals (תקנון שימוש / הצהרת נגישות) — Focus return לכפתור שפתח את ה-Modal (Audit item 5),
  // סגירה ב-Escape ובלחיצה מחוץ למודל, ומילוי פרטי קשר בפועל מ-Company Settings (לא hardcoded)
  // כשה-Modal נפתח — כדי שתמיד יהיו עדכניים גם אם שונו אחרי טעינת הדף.
  function wireModal(modalId, openBtnId, closeBtnId, onOpen){
    const modal = document.getElementById(modalId);
    const openBtn = document.getElementById(openBtnId);
    const closeBtn = document.getElementById(closeBtnId);
    let lastFocused = null;
    function open(){
      lastFocused = document.activeElement;
      modal.classList.add('show');
      if(onOpen) onOpen();
      closeBtn.focus();
    }
    function close(){
      modal.classList.remove('show');
      if(lastFocused && lastFocused.focus) lastFocused.focus();
    }
    if(openBtn) openBtn.addEventListener('click', open);
    closeBtn.addEventListener('click', close);
    modal.addEventListener('click', (e)=>{ if(e.target === modal) close(); });
    document.addEventListener('keydown', (e)=>{
      if(e.key === 'Escape' && modal.classList.contains('show')) close();
    });
  }

  wireModal('termsModal', 'btnOpenTerms', 'termsModalClose', ()=>{
    // פרטי קשר לתקנון — נלקחים מ-Company Settings הקיימים, לא hardcoded (Reuse, לא כפל תחזוקה)
    const s = state.settings;
    document.getElementById('termsContactName').textContent = s.companyName || 'שקד הנדסת חשמל בע"מ';
    document.getElementById('termsContactPhone').textContent = s.phone || s.officePhone || '';
    document.getElementById('termsContactEmail').textContent = s.email || '';
  });

  wireModal('accessibilityStatementModal', 'btnOpenAccessibilityStatement', 'accessibilityStatementModalClose', ()=>{
    const s = state.settings;
    document.getElementById('a11yContactName').textContent = s.accessibilityCoordinatorName || s.companyName || 'שקד הנדסת חשמל בע"מ';
    document.getElementById('a11yContactPhone').textContent = s.phone || s.officePhone || '';
    document.getElementById('a11yContactEmail').textContent = s.email || '';
    document.getElementById('a11yContactAddress').textContent = s.companyAddress || '';
  });

  // Escape סוגר גם את תפריט הנגישות עצמו (לא רק Modals) אם פתוח
  document.addEventListener('keydown', (e)=>{
    if(e.key === 'Escape' && a11yMenu.classList.contains('show')) setA11yMenuOpen(false);
  });

  loadPrefs();
})();
